def _bounded_directory_names(
    directory_fd: int,
    *,
    label: str,
    max_entries: int,
) -> tuple[str, ...]:
    """Enumerate an fd-backed directory without pre-ceiling allocation."""

    names: list[str] = []
    try:
        with os.scandir(directory_fd) as entries:
            for entry in entries:
                name = entry.name
                if (
                    not isinstance(name, str)
                    or name in {"", ".", ".."}
                    or "/" in name
                    or len(os.fsencode(name)) > _MUTATION_JOURNAL_MAX_NAME_BYTES
                ):
                    raise MutationJournalError(
                        f"{label} contains a malformed entry name"
                    )
                if len(names) >= max_entries:
                    raise MutationJournalError(
                        f"{label} exceeds its entry ceiling"
                    )
                names.append(name)
    except MutationJournalError:
        raise
    except OSError as exc:
        raise MutationJournalError(
            f"cannot enumerate {label}: {exc}"
        ) from exc
    return tuple(sorted(names))


def _bound_directory_has_entries(directory_fd: int, *, label: str) -> bool:
    """Probe one fd-backed directory entry without enumerating its contents."""

    try:
        with os.scandir(directory_fd) as entries:
            return next(entries, None) is not None
    except OSError as exc:
        raise MutationJournalError(f"cannot inspect {label}: {exc}") from exc


def _private_cleanup_quarantine_name(
    directory_fd: int,
    *,
    prefix: str = ".crucible-cleanup-",
) -> str:
    """Return a private, presently absent cleanup name in ``directory_fd``."""

    if (
        not prefix.startswith(".crucible-cleanup-")
        or "/" in prefix
        or "\0" in prefix
    ):
        raise MutationJournalError("invalid cleanup quarantine prefix")
    for _attempt in range(16):
        candidate = f"{prefix}{secrets.token_hex(32)}"
        try:
            os.stat(candidate, dir_fd=directory_fd, follow_symlinks=False)
        except FileNotFoundError:
            return candidate
    raise MutationJournalError(
        "cannot reserve a private bound-cleanup quarantine name"
    )


def _read_bound_regular_entry(
    directory_fd: int,
    name: str,
    *,
    label: str,
    max_bytes: int,
) -> tuple[bytes, os.stat_result]:
    """Read one stable regular entry relative to a held directory."""

    descriptor: int | None = None
    try:
        before = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        if (
            not stat.S_ISREG(before.st_mode)
            or stat.S_ISLNK(before.st_mode)
            or before.st_nlink != 1
            or before.st_size > max_bytes
        ):
            raise MutationJournalError(
                f"{label} is unsafe or exceeds its byte ceiling"
            )
        descriptor = os.open(
            name,
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_NONBLOCK", 0),
            dir_fd=directory_fd,
        )
        opened = os.fstat(descriptor)
        if (
            not stat.S_ISREG(opened.st_mode)
            or opened.st_nlink != 1
            or (opened.st_dev, opened.st_ino)
            != (before.st_dev, before.st_ino)
        ):
            raise MutationJournalError(f"{label} changed while opening")
        payload = bytearray()
        while True:
            chunk = os.read(descriptor, min(1024 * 1024, max_bytes + 1))
            if not chunk:
                break
            if len(payload) + len(chunk) > max_bytes:
                raise MutationJournalError(f"{label} exceeds its byte ceiling")
            payload.extend(chunk)
        finished = os.fstat(descriptor)
        current = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        if any(
            getattr(opened, field) != getattr(finished, field)
            or getattr(opened, field) != getattr(current, field)
            for field in _SETTLEMENT_STABLE_STAT_FIELDS
        ):
            raise MutationJournalError(f"{label} changed during read")
        return bytes(payload), opened
    except MutationJournalError:
        raise
    except (OSError, TypeError, ValueError) as exc:
        raise MutationJournalError(f"cannot read {label}: {exc}") from exc
    finally:
        if descriptor is not None:
            os.close(descriptor)


def _git_admin_file_metadata(metadata: os.stat_result) -> tuple[int, ...]:
    """Return the stable authority fields for one Git-admin file."""

    return (
        metadata.st_dev,
        metadata.st_ino,
        stat.S_IMODE(metadata.st_mode),
        metadata.st_uid,
        metadata.st_gid,
        metadata.st_nlink,
        metadata.st_size,
        metadata.st_mtime_ns,
        metadata.st_ctime_ns,
    )


def _bound_admin_tree_inventory(
    root_fd: int,
    *,
    label: str,
    opaque_roots: Iterable[str] = (),
) -> dict[str, os.stat_result]:
    """Inventory an administrative tree without following namespace aliases."""

    opaque = tuple(_dedupe_roots(opaque_roots))
    inventory: dict[str, os.stat_result] = {}
    path_bytes = 0

    def excluded(relative: str) -> bool:
        return any(
            relative == root or relative.startswith(root.rstrip("/") + "/")
            for root in opaque
        )

    def walk(directory_fd: int, prefix: str, depth: int) -> None:
        nonlocal path_bytes
        if depth > _MUTATION_JOURNAL_MAX_DISCOVERY_DEPTH:
            raise MutationJournalError(
                f"{label} exceeds its directory-depth ceiling"
            )
        initial = _bounded_directory_names(
            directory_fd,
            label=label,
            max_entries=(
                _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS
                - len(inventory)
            ),
        )
        for name in initial:
            relative = f"{prefix}/{name}" if prefix else name
            path_bytes += len(os.fsencode(relative))
            if (
                len(inventory)
                >= _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS
                or path_bytes > _MUTATION_JOURNAL_MAX_DISCOVERY_PATH_BYTES
            ):
                raise MutationJournalError(
                    f"{label} exceeds its inventory ceiling"
                )
            before = os.stat(
                name,
                dir_fd=directory_fd,
                follow_symlinks=False,
            )
            inventory[relative] = before
            if excluded(relative) or not stat.S_ISDIR(
                before.st_mode
            ) or stat.S_ISLNK(before.st_mode):
                continue
            child_fd, opened = _open_authority_directory_at(
                directory_fd,
                name,
                label=f"{label} {relative}",
            )
            try:
                if (opened.st_dev, opened.st_ino) != (
                    before.st_dev,
                    before.st_ino,
                ):
                    raise MutationJournalError(
                        f"{label} directory changed: {relative}"
                    )
                walk(child_fd, relative, depth + 1)
                current = os.stat(
                    name,
                    dir_fd=directory_fd,
                    follow_symlinks=False,
                )
                if (current.st_dev, current.st_ino) != (
                    opened.st_dev,
                    opened.st_ino,
                ):
                    raise MutationJournalError(
                        f"{label} directory changed after inventory: {relative}"
                    )
            finally:
                os.close(child_fd)
        final = _bounded_directory_names(
            directory_fd,
            label=label,
            max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
        )
        if final != initial:
            raise MutationJournalError(
                f"{label} changed during inventory"
            )

    walk(root_fd, "", 0)
    return inventory


def _digest_bound_regular_entry(
    directory_fd: int,
    name: str,
    *,
    label: str,
    max_bytes: int,
) -> str:
    """Hash one stable, singly-linked regular entry without buffering it."""

    descriptor: int | None = None
    try:
        before = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        if (
            not stat.S_ISREG(before.st_mode)
            or stat.S_ISLNK(before.st_mode)
            or before.st_nlink != 1
            or before.st_size > max_bytes
        ):
            raise MutationJournalError(
                f"{label} is unsafe or exceeds its byte ceiling"
            )
        descriptor = os.open(
            name,
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_NONBLOCK", 0),
            dir_fd=directory_fd,
        )
        opened = os.fstat(descriptor)
        if (
            not stat.S_ISREG(opened.st_mode)
            or opened.st_nlink != 1
            or (opened.st_dev, opened.st_ino)
            != (before.st_dev, before.st_ino)
        ):
            raise MutationJournalError(f"{label} changed while opening")
        digest = hashlib.sha256()
        observed = 0
        while True:
            chunk = os.read(descriptor, 1024 * 1024)
            if not chunk:
                break
            observed += len(chunk)
            if observed > max_bytes or observed > before.st_size:
                raise MutationJournalError(f"{label} exceeds its byte ceiling")
            digest.update(chunk)
        finished = os.fstat(descriptor)
        current = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        if observed != before.st_size or any(
            getattr(opened, field) != getattr(finished, field)
            or getattr(opened, field) != getattr(current, field)
            for field in _SETTLEMENT_STABLE_STAT_FIELDS
        ):
            raise MutationJournalError(f"{label} changed during hashing")
        return digest.hexdigest()
    except MutationJournalError:
        raise
    except (OSError, TypeError, ValueError) as exc:
        raise MutationJournalError(f"cannot hash {label}: {exc}") from exc
    finally:
        if descriptor is not None:
            os.close(descriptor)


def _remove_bound_regular_entry(
    directory_fd: int,
    name: str,
    *,
    label: str,
    expected_metadata: os.stat_result | None = None,
    expected_payload: bytes | None = None,
    expected_inventory_record: tuple[object, ...] | None = None,
    quarantine_prefix: str = ".crucible-cleanup-",
) -> None:
    """Quarantine and unlink only one opened, verified regular-file inode."""

    before = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
    file_fd = os.open(
        name,
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0)
        | getattr(os, "O_NONBLOCK", 0),
        dir_fd=directory_fd,
    )
    reservation_fd: int | None = None
    try:
        opened = os.fstat(file_fd)
        if (
            not stat.S_ISREG(opened.st_mode)
            or opened.st_nlink != 1
            or (opened.st_dev, opened.st_ino)
            != (before.st_dev, before.st_ino)
            or (
                expected_metadata is not None
                and (opened.st_dev, opened.st_ino)
                != (expected_metadata.st_dev, expected_metadata.st_ino)
            )
        ):
            raise MutationJournalError(f"{label} changed while opening")

        def require_expected_inventory_record(bound_name: str) -> None:
            if expected_inventory_record is None:
                return
            if (
                len(expected_inventory_record) != 7
                or expected_inventory_record[0] != "file"
                or not isinstance(expected_inventory_record[6], str)
            ):
                raise MutationJournalError(
                    f"{label} authorized inventory record is malformed"
                )
            before_digest = os.fstat(file_fd)
            expected_size = expected_inventory_record[5]
            if (
                isinstance(expected_size, bool)
                or not isinstance(expected_size, int)
                or expected_size < 0
            ):
                raise MutationJournalError(
                    f"{label} authorized inventory size is malformed"
                )
            os.lseek(file_fd, 0, os.SEEK_SET)
            digest = hashlib.sha256()
            observed = 0
            while observed <= expected_size:
                chunk = os.read(
                    file_fd,
                    min(1024 * 1024, expected_size + 1 - observed),
                )
                if not chunk:
                    break
                observed += len(chunk)
                digest.update(chunk)
            finished_digest = os.fstat(file_fd)
            named = os.stat(
                bound_name,
                dir_fd=directory_fd,
                follow_symlinks=False,
            )
            current_record = (
                "file",
                before_digest.st_dev,
                before_digest.st_ino,
                before_digest.st_mode,
                before_digest.st_nlink,
                before_digest.st_size,
                digest.hexdigest(),
            )
            if (
                observed != expected_size
                or current_record != expected_inventory_record
                or any(
                    getattr(before_digest, field)
                    != getattr(finished_digest, field)
                    or getattr(before_digest, field) != getattr(named, field)
                    for field in _SETTLEMENT_STABLE_STAT_FIELDS
                )
            ):
                raise MutationJournalError(
                    f"{label} differs from its authorized inventory"
                )

        require_expected_inventory_record(name)
        if expected_payload is not None:
            os.lseek(file_fd, 0, os.SEEK_SET)
            if opened.st_size != len(expected_payload):
                raise MutationJournalError(f"{label} payload size changed")
            payload = bytearray()
            while len(payload) <= len(expected_payload):
                chunk = os.read(
                    file_fd,
                    min(1024 * 1024, len(expected_payload) + 1 - len(payload)),
                )
                if not chunk:
                    break
                payload.extend(chunk)
            finished = os.fstat(file_fd)
            current = os.stat(
                name,
                dir_fd=directory_fd,
                follow_symlinks=False,
            )
            if (
                bytes(payload) != expected_payload
                or any(
                    getattr(opened, field) != getattr(finished, field)
                    or getattr(opened, field) != getattr(current, field)
                    for field in _SETTLEMENT_STABLE_STAT_FIELDS
                )
            ):
                raise MutationJournalError(f"{label} payload changed")
        quarantine = _private_cleanup_quarantine_name(
            directory_fd,
            prefix=quarantine_prefix,
        )
        reservation_fd = os.open(
            quarantine,
            os.O_WRONLY
            | os.O_CREAT
            | os.O_EXCL
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0),
            0o600,
            dir_fd=directory_fd,
        )
        reservation = os.fstat(reservation_fd)
        current = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        if (current.st_dev, current.st_ino) != (
            opened.st_dev,
            opened.st_ino,
        ):
            raise MutationJournalError(f"{label} changed before quarantine")
        reserved = os.stat(
            quarantine,
            dir_fd=directory_fd,
            follow_symlinks=False,
        )
        if (reserved.st_dev, reserved.st_ino) != (
            reservation.st_dev,
            reservation.st_ino,
        ):
            raise MutationJournalError(f"{label} quarantine reservation changed")
        os.rename(
            name,
            quarantine,
            src_dir_fd=directory_fd,
            dst_dir_fd=directory_fd,
        )
        if os.fstat(reservation_fd).st_nlink != 0:
            raise MutationJournalError(
                f"{label} did not replace its quarantine reservation"
            )
        quarantined = os.stat(
            quarantine,
            dir_fd=directory_fd,
            follow_symlinks=False,
        )
        if (quarantined.st_dev, quarantined.st_ino) != (
            opened.st_dev,
            opened.st_ino,
        ):
            raise MutationJournalError(f"{label} quarantined a replacement")
        require_expected_inventory_record(quarantine)
        os.unlink(quarantine, dir_fd=directory_fd)
        if os.fstat(file_fd).st_nlink != 0:
            raise MutationJournalError(f"{label} unlinked a replacement")
    finally:
        if reservation_fd is not None:
            os.close(reservation_fd)
        os.close(file_fd)


def _remove_bound_symlink_entry(
    directory_fd: int,
    name: str,
    *,
    label: str,
    expected_metadata: os.stat_result,
) -> None:
    """Quarantine and unlink one exact symlink inode without following it."""

    path_flag = getattr(os, "O_PATH", 0)
    if not path_flag:
        raise MutationJournalError(
            f"descriptor-bound symlink cleanup is unsupported: {label}"
        )
    before = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
    descriptor = os.open(
        name,
        path_flag
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0),
        dir_fd=directory_fd,
    )
    reservation_fd: int | None = None
    quarantine: str | None = None
    moved = False
    try:
        opened = os.fstat(descriptor)
        expected_identity = (
            expected_metadata.st_dev,
            expected_metadata.st_ino,
        )
        if (
            not stat.S_ISLNK(opened.st_mode)
            or opened.st_nlink != 1
            or (before.st_dev, before.st_ino) != expected_identity
            or (opened.st_dev, opened.st_ino) != expected_identity
        ):
            raise MutationJournalError(f"{label} changed while opening")
        quarantine = _private_cleanup_quarantine_name(directory_fd)
        reservation_fd = os.open(
            quarantine,
            os.O_WRONLY
            | os.O_CREAT
            | os.O_EXCL
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0),
            0o600,
            dir_fd=directory_fd,
        )
        reservation = os.fstat(reservation_fd)
        current = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        reserved = os.stat(
            quarantine,
            dir_fd=directory_fd,
            follow_symlinks=False,
        )
        if (current.st_dev, current.st_ino) != expected_identity:
            raise MutationJournalError(f"{label} changed before quarantine")
        if (reserved.st_dev, reserved.st_ino) != (
            reservation.st_dev,
            reservation.st_ino,
        ):
            raise MutationJournalError(
                f"{label} quarantine reservation changed"
            )
        os.rename(
            name,
            quarantine,
            src_dir_fd=directory_fd,
            dst_dir_fd=directory_fd,
        )
        moved = True
        if os.fstat(reservation_fd).st_nlink != 0:
            raise MutationJournalError(
                f"{label} did not replace its quarantine reservation"
            )
        quarantined = os.stat(
            quarantine,
            dir_fd=directory_fd,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISLNK(quarantined.st_mode)
            or (quarantined.st_dev, quarantined.st_ino) != expected_identity
        ):
            raise MutationJournalError(f"{label} quarantined a replacement")
        os.unlink(quarantine, dir_fd=directory_fd)
        moved = False
        if os.fstat(descriptor).st_nlink != 0:
            raise MutationJournalError(f"{label} unlinked a replacement")
    finally:
        try:
            if moved and quarantine is not None:
                cleanup_quarantined: os.stat_result | None
                try:
                    cleanup_quarantined = os.stat(
                        quarantine,
                        dir_fd=directory_fd,
                        follow_symlinks=False,
                    )
                except FileNotFoundError:
                    cleanup_quarantined = None
                try:
                    os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
                except FileNotFoundError:
                    if cleanup_quarantined is not None and (
                        cleanup_quarantined.st_dev,
                        cleanup_quarantined.st_ino,
                    ) == (
                        os.fstat(descriptor).st_dev,
                        os.fstat(descriptor).st_ino,
                    ):
                        os.rename(
                            quarantine,
                            name,
                            src_dir_fd=directory_fd,
                            dst_dir_fd=directory_fd,
                        )
            if reservation_fd is not None and os.fstat(
                reservation_fd
            ).st_nlink != 0:
                assert quarantine is not None
                reserved = os.stat(
                    quarantine,
                    dir_fd=directory_fd,
                    follow_symlinks=False,
                )
                held = os.fstat(reservation_fd)
                if (reserved.st_dev, reserved.st_ino) == (
                    held.st_dev,
                    held.st_ino,
                ):
                    os.unlink(quarantine, dir_fd=directory_fd)
        finally:
            if reservation_fd is not None:
                os.close(reservation_fd)
            os.close(descriptor)


def _remove_bound_directory_tree(
    parent_fd: int,
    name: str,
    directory_fd: int,
    expected: os.stat_result,
    *,
    pre_remove_guard: Callable[[], None] | None = None,
    authorized_inventory: tuple[tuple[object, ...], ...] | None = None,
) -> None:
    """Delete only one held tree and, when supplied, its frozen node set.

    ``authorized_inventory`` is path-independent so an interrupted cleanup
    may resume after private quarantine renames and partial deletion.  Every
    remaining node must still be an exact member; additions, replacements,
    and changed file bytes are rejected again inside the destructive walker.
    """

    if pre_remove_guard is not None:
        pre_remove_guard()
    budget = _MutationJournalArtifactBudget()
    authorized_records: set[tuple[object, ...]] | None = None
    authorized_by_identity: dict[
        tuple[str, int, int], tuple[object, ...]
    ] = {}
    if authorized_inventory is not None:
        authorized_records = set(authorized_inventory)
        if len(authorized_records) != len(authorized_inventory):
            raise MutationJournalError(
                "bound cleanup authorized inventory contains duplicates"
            )
        for record in authorized_inventory:
            kind = record[0] if record else None
            valid_directory = (
                kind == "directory"
                and len(record) == 4
                and all(
                    isinstance(value, int) and not isinstance(value, bool)
                    for value in record[1:]
                )
            )
            valid_file = (
                kind == "file"
                and len(record) == 7
                and all(
                    isinstance(value, int) and not isinstance(value, bool)
                    for value in record[1:6]
                )
                and isinstance(record[6], str)
                and re.fullmatch(r"[0-9a-f]{64}", record[6]) is not None
            )
            if not valid_directory and not valid_file:
                raise MutationJournalError(
                    "bound cleanup authorized inventory is malformed"
                )
            identity = (
                str(kind),
                int(cast(int, record[1])),
                int(cast(int, record[2])),
            )
            if identity in authorized_by_identity:
                raise MutationJournalError(
                    "bound cleanup authorized inventory repeats an inode"
                )
            authorized_by_identity[identity] = record

    def require_authorized_subtree(current_fd: int) -> None:
        if authorized_records is None:
            return
        current = set(_terminal_cleanup_journal_inventory(current_fd))
        if not current.issubset(authorized_records):
            raise MutationJournalError(
                "bound cleanup tree contains an unauthorized or changed "
                "inventory entry"
            )

    def authorized_record(
        kind: str,
        metadata: os.stat_result,
    ) -> tuple[object, ...] | None:
        if authorized_records is None:
            return None
        record = authorized_by_identity.get(
            (kind, metadata.st_dev, metadata.st_ino)
        )
        if record is None:
            raise MutationJournalError(
                "bound cleanup encountered an unauthorized inventory inode"
            )
        return record

    require_authorized_subtree(directory_fd)

    def quarantine_directory(
        current_fd: int,
        entry_name: str,
        metadata: os.stat_result,
        depth: int,
    ) -> None:
        """Move one held directory inode aside before recursively removing it."""

        child_fd = os.open(
            entry_name,
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_NOFOLLOW", 0),
            dir_fd=current_fd,
        )
        reservation_fd: int | None = None
        quarantine: str | None = None
        try:
            opened = os.fstat(child_fd)
            if (opened.st_dev, opened.st_ino) != (
                metadata.st_dev,
                metadata.st_ino,
            ):
                raise MutationJournalError(
                    "bound cleanup directory changed while opening"
                )
            expected_record = authorized_record("directory", opened)
            if expected_record is not None and expected_record != (
                "directory",
                opened.st_dev,
                opened.st_ino,
                opened.st_mode,
            ):
                raise MutationJournalError(
                    "bound cleanup directory differs from authorized inventory"
                )
            quarantine = _private_cleanup_quarantine_name(current_fd)
            os.mkdir(quarantine, mode=0o700, dir_fd=current_fd)
            reservation_fd = os.open(
                quarantine,
                os.O_RDONLY
                | getattr(os, "O_CLOEXEC", 0)
                | getattr(os, "O_DIRECTORY", 0)
                | getattr(os, "O_NOFOLLOW", 0),
                dir_fd=current_fd,
            )
            reservation = os.fstat(reservation_fd)
            current = os.stat(
                entry_name,
                dir_fd=current_fd,
                follow_symlinks=False,
            )
            if (current.st_dev, current.st_ino) != (
                opened.st_dev,
                opened.st_ino,
            ):
                raise MutationJournalError(
                    "bound cleanup directory changed before quarantine"
                )
            reserved = os.stat(
                quarantine,
                dir_fd=current_fd,
                follow_symlinks=False,
            )
            if (reserved.st_dev, reserved.st_ino) != (
                reservation.st_dev,
                reservation.st_ino,
            ):
                raise MutationJournalError(
                    "bound cleanup quarantine reservation changed"
                )
            os.rename(
                entry_name,
                quarantine,
                src_dir_fd=current_fd,
                dst_dir_fd=current_fd,
            )
            if os.fstat(reservation_fd).st_nlink != 0:
                raise MutationJournalError(
                    "bound cleanup did not replace its quarantine reservation"
                )
            quarantined = os.stat(
                quarantine,
                dir_fd=current_fd,
                follow_symlinks=False,
            )
            if (quarantined.st_dev, quarantined.st_ino) != (
                opened.st_dev,
                opened.st_ino,
            ):
                raise MutationJournalError(
                    "bound cleanup quarantined a replacement directory"
                )
            clear(child_fd, depth + 1)
            current = os.stat(
                quarantine,
                dir_fd=current_fd,
                follow_symlinks=False,
            )
            if (current.st_dev, current.st_ino) != (
                opened.st_dev,
                opened.st_ino,
            ):
                raise MutationJournalError(
                    "bound cleanup directory changed before removal"
                )
            os.rmdir(quarantine, dir_fd=current_fd)
            if os.fstat(child_fd).st_nlink != 0:
                raise MutationJournalError(
                    "bound cleanup removed a replacement directory"
                )
        finally:
            if reservation_fd is not None:
                os.close(reservation_fd)
            os.close(child_fd)

    def clear(current_fd: int, depth: int) -> None:
        if depth > _MUTATION_JOURNAL_MAX_DISCOVERY_DEPTH:
            raise MutationJournalError(
                "bound cleanup exceeds its directory depth ceiling"
            )
        names = _bounded_directory_names(
            current_fd,
            label="bound mutation journal cleanup",
            max_entries=(
                _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS - budget.paths
            ),
        )
        for entry_name in names:
            budget.charge_path()
            metadata = os.stat(
                entry_name,
                dir_fd=current_fd,
                follow_symlinks=False,
            )
            if stat.S_ISDIR(metadata.st_mode) and not stat.S_ISLNK(
                metadata.st_mode
            ):
                quarantine_directory(
                    current_fd,
                    entry_name,
                    metadata,
                    depth,
                )
                continue
            if stat.S_ISREG(metadata.st_mode):
                expected_record = authorized_record("file", metadata)
                _remove_bound_regular_entry(
                    current_fd,
                    entry_name,
                    label="bound cleanup regular entry",
                    expected_metadata=metadata,
                    expected_inventory_record=expected_record,
                )
                continue
            raise MutationJournalError(
                "bound cleanup encountered a special filesystem entry"
            )
        if _bounded_directory_names(
            current_fd,
            label="bound mutation journal cleanup",
            max_entries=1,
        ):
            raise MutationJournalError(
                "bound cleanup directory changed during removal"
            )

    held = os.fstat(directory_fd)
    if (held.st_dev, held.st_ino) != (expected.st_dev, expected.st_ino):
        raise MutationJournalError("bound cleanup directory identity changed")
    current = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    if (current.st_dev, current.st_ino) != (held.st_dev, held.st_ino):
        raise MutationJournalError(
            "bound cleanup target changed before content removal"
        )
    clear(directory_fd, 0)
    current = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    if (current.st_dev, current.st_ino) != (held.st_dev, held.st_ino):
        raise MutationJournalError(
            "bound cleanup target changed before terminal removal"
        )
    os.rmdir(name, dir_fd=parent_fd)
    if os.fstat(directory_fd).st_nlink != 0:
        raise MutationJournalError(
            "bound cleanup removed a replacement terminal directory"
        )


def _requires_full_fsck(reasons: Iterable[str]) -> bool:
    """Return whether rollback touched object-connectivity authority."""

    return bool(set(reasons).intersection(_FSCK_INTEGRITY_CLASSES))


def _register_live(transaction_id: str) -> None:
    with _LIVE_TRANSACTIONS_LOCK:
        _LIVE_TRANSACTIONS.add(transaction_id)


def _reject_git_redirect_env() -> None:
    active = sorted({
        *(key for key in _GIT_REDIRECT_ENV if os.environ.get(key)),
        *(
            key for key, value in os.environ.items()
            if key.startswith("GIT_CONFIG_") and value
        ),
    })
    if active:
        raise MutationJournalError(
            f"ambient Git redirect environment is unsupported: {active!r}"
        )


def _sanitized_git_env(**overrides: str) -> dict[str, str]:
    """Return an Assay-equivalent Git environment with no ambient controls.

    All ``GIT_*`` variables are attacker-controlled execution/configuration
    surfaces. Callers that deliberately need an isolated index/object store
    add only those exact redirects through ``overrides`` after the scrub.
    Optional locking is disabled by default so read-only provenance probes do
    not opportunistically refresh a governed live index; Git still takes every
    lock required for an intentional mutation.
    """

    env = {
        key: value
        for key, value in os.environ.items()
        if not key.startswith("GIT_")
    }
    env.update({
        "GIT_CONFIG_NOSYSTEM": "1",
        "GIT_CONFIG_GLOBAL": os.devnull,
        "GIT_ATTR_NOSYSTEM": "1",
        "GIT_TERMINAL_PROMPT": "0",
        "GIT_PAGER": "cat",
        "GIT_OPTIONAL_LOCKS": "0",
    })
    env.update(overrides)
    return env


def _git_argv(*args: str) -> list[str]:
    """Build a Git argv with hooks, monitors, and transports disabled."""

    return ["git", *_GIT_SAFE_OPTIONS, *args]


def _unregister_live(transaction_id: str) -> None:
    """Drop only process-local ownership (crash/death simulation semantics)."""

    with _LIVE_TRANSACTIONS_LOCK:
        _LIVE_TRANSACTIONS.discard(transaction_id)
        _LIVE_JOURNAL_OBJECTS.pop(transaction_id, None)
        _FAILED_LIVE_TRANSACTIONS.discard(transaction_id)


def _unregister_terminal_live(transaction_id: str) -> None:
    """Drop a proof-cleaned terminal member and refresh surviving owners."""

    with _LIVE_TRANSACTIONS_LOCK:
        journal = _LIVE_JOURNAL_OBJECTS.get(transaction_id)
        affected = (
            set(journal._manifest.get(
                "registry_transaction_family", ()
            ))
            if journal is not None else set()
        )
        affected.update(_live_journal_component_locked(transaction_id))
        _LIVE_TRANSACTIONS.discard(transaction_id)
        _LIVE_JOURNAL_OBJECTS.pop(transaction_id, None)
        _FAILED_LIVE_TRANSACTIONS.discard(transaction_id)
        affected.discard(transaction_id)
        _refresh_live_journal_families_locked(affected)


def _live_journal_component_locked(transaction_id: str) -> set[str]:
    """Return one current lineage component while the live lock is held."""

    if transaction_id not in _LIVE_JOURNAL_OBJECTS:
        return set()
    adjacency: dict[str, set[str]] = {
        candidate_id: set() for candidate_id in _LIVE_JOURNAL_OBJECTS
    }
    for candidate_id, candidate in _LIVE_JOURNAL_OBJECTS.items():
        parent = candidate.parent_transaction_id
        if parent is not None and parent in adjacency:
            adjacency[candidate_id].add(parent)
            adjacency[parent].add(candidate_id)
    component: set[str] = set()
    pending = [transaction_id]
    while pending:
        current = pending.pop()
        if current in component:
            continue
        component.add(current)
        pending.extend(adjacency[current])
    return component


def _refresh_live_journal_families_locked(transaction_ids: Iterable[str]) -> None:
    """Persist only lineage components touched by a register/unregister."""

    pending = set(transaction_ids).intersection(_LIVE_JOURNAL_OBJECTS)
    while pending:
        transaction_id = next(iter(pending))
        component = _live_journal_component_locked(transaction_id)
        pending.difference_update(component)
        family = tuple(sorted(component))
        failed = tuple(sorted(component.intersection(_FAILED_LIVE_TRANSACTIONS)))
        parents = {
            member_id: _LIVE_JOURNAL_OBJECTS[
                member_id
            ].parent_transaction_id
            for member_id in sorted(component)
        }
        for member_id in sorted(component):
            member = _LIVE_JOURNAL_OBJECTS[member_id]
            member._set_registry_transaction_family(
                family,
                failed=failed,
                parents=parents,
            )


def _mark_live_family_failed(transaction_id: str) -> None:
    """Durably prevent ancestors from disarming a failed descendant."""

    with _LIVE_TRANSACTIONS_LOCK:
        _FAILED_LIVE_TRANSACTIONS.add(transaction_id)
        _refresh_live_journal_families_locked(
            _live_journal_component_locked(transaction_id)
        )


def _register_live_journal(journal: "WorkspaceMutationJournal") -> None:
    _retain_published_setup_journal(journal)


def resolve_live_mutation_journal(
    journal_dir: str | Path,
    transaction_id: str,
) -> "WorkspaceMutationJournal":
    """Resolve serialized host identity to the exact process-live owner.

    Isolated mutation hosts may carry a path and transaction ID through their
    immutable ToolContext snapshot, but those strings are descriptive rather
    than authority.  This resolver returns only the object already registered
    by journal publication and re-proves its captured directory identities;
    it never constructs authority by loading a caller-selected manifest.
    """

    if not isinstance(transaction_id, str) or not transaction_id:
        raise MutationJournalError(
            "live mutation journal transaction identity is malformed"
        )
    rendered = Path(os.path.abspath(os.fspath(journal_dir)))
    with _LIVE_TRANSACTIONS_LOCK:
        journal = _LIVE_JOURNAL_OBJECTS.get(transaction_id)
        if (
            journal is None
            or transaction_id not in _LIVE_TRANSACTIONS
            or journal.transaction_id != transaction_id
            or Path(os.path.abspath(os.fspath(
                journal._logical_journal_dir
            ))) != rendered
            or journal._logical_journal_identity is None
            or journal._logical_journal_parent_identity is None
        ):
            raise MutationJournalError(
                "serialized mutation journal identity has no exact live owner"
            )
        try:
            directory = rendered.lstat()
            parent = rendered.parent.lstat()
        except OSError as exc:
            raise MutationJournalError(
                "cannot revalidate live mutation journal identity"
            ) from exc
        if (
            not stat.S_ISDIR(directory.st_mode)
            or stat.S_ISLNK(directory.st_mode)
            or (directory.st_dev, directory.st_ino)
            != journal._logical_journal_identity
            or not stat.S_ISDIR(parent.st_mode)
            or stat.S_ISLNK(parent.st_mode)
            or (parent.st_dev, parent.st_ino)
            != journal._logical_journal_parent_identity
        ):
            raise MutationJournalError(
                "live mutation journal path changed identity"
            )
        return journal


def _retain_published_setup_journal(
    journal: "WorkspaceMutationJournal",
) -> None:
    """Adopt an exact published journal after registration-path failure.

    Publication precedes process-local registration.  If registration raises,
    cleanup still needs the complete live/recovery family projection before it
    can prove a never-armed epoch safe.  This unpatchable internal recovery
    path retains the exact object and retries the same durable family refresh;
    it never weakens the projection check.
    """

    transaction_id = journal.transaction_id
    with _LIVE_TRANSACTIONS_LOCK:
        existing = _LIVE_JOURNAL_OBJECTS.get(transaction_id)
        if existing is not None and existing is not journal:
            raise MutationJournalError(
                "published mutation journal registration collides with a "
                f"different live owner: {transaction_id}"
            )
        journal._setup_registration_pending = True
        previous_family = set(journal._manifest.get(
            "registry_transaction_family", ()
        ))
        _LIVE_JOURNAL_OBJECTS[transaction_id] = journal
        current_family = _live_journal_component_locked(transaction_id)
        _refresh_live_journal_families_locked(
            previous_family.union(current_family)
        )
        journal._setup_registration_pending = False


def _writer_epoch_available_members_locked(
    current: "WorkspaceMutationJournal | None" = None,
) -> dict[str, "WorkspaceMutationJournal"]:
    """Merge live and recovery authority only when their IDs are disjoint."""

    recovery = cast(
        dict[str, WorkspaceMutationJournal],
        getattr(_LOCK_STATE, "writer_epoch_recovery_members", {}),
    )
    collisions = set(recovery).intersection(_LIVE_JOURNAL_OBJECTS)
    if collisions:
        raise MutationJournalError(
            "writer epoch recovery authority collides with a live owner: "
            f"{sorted(collisions)!r}"
        )
    available = {**recovery, **_LIVE_JOURNAL_OBJECTS}
    if current is not None:
        existing = available.get(current.transaction_id)
        same_durable_owner = (
            existing is not None
            and existing is not current
            and isinstance(existing, WorkspaceMutationJournal)
            and current._logical_journal_identity is not None
            and current._logical_journal_parent_identity is not None
            and existing._logical_journal_identity
            == current._logical_journal_identity
            and existing._logical_journal_parent_identity
            == current._logical_journal_parent_identity
            and existing._registry_authority_journal_dir.name
            == current._registry_authority_journal_dir.name
        )
        same_certified_owner = False
        if (
            existing is not None
            and existing is not current
            and not isinstance(existing, WorkspaceMutationJournal)
            and getattr(existing, "parent_transaction_id", object())
            == current.parent_transaction_id
        ):
            reader = getattr(existing, "read_writer_epoch_record", None)
            if callable(reader):
                try:
                    same_certified_owner = (
                        reader() == current.read_writer_epoch_record()
                    )
                except BaseException as exc:
                    raise MutationJournalError(
                        "writer epoch certified authority is unreadable"
                    ) from exc
        if (
            existing is not None
            and existing is not current
            and not same_durable_owner
            and not same_certified_owner
        ):
            raise MutationJournalError(
                "writer epoch current authority collides with another owner: "
                f"{current.transaction_id!r}"
            )
        if existing is None:
            available[current.transaction_id] = current
    return available


def live_writer_epoch_family(
    journal: "WorkspaceMutationJournal",
) -> tuple["WorkspaceMutationJournal", ...]:
    """Resolve one exact active rooted family under the live-registry lock.

    Writer-frontier callers use this instead of guessing that a landing
    journal is alone.  The operational registry projection on every member
    must agree with the actual process-owned parent graph before the canonical
    root-first tuple is returned.
    """

    with _LIVE_TRANSACTIONS_LOCK:
        transaction_id = journal.transaction_id
        if _LIVE_JOURNAL_OBJECTS.get(transaction_id) is not journal:
            raise MutationJournalError(
                "writer epoch journal is not the exact live registry owner"
            )
        component = _live_journal_component_locked(transaction_id)
        members = {
            member_id: _LIVE_JOURNAL_OBJECTS[member_id]
            for member_id in component
        }
        if not members or any(not member.active for member in members.values()):
            raise MutationJournalError(
                "writer epoch family contains an inactive member"
            )
        parents = {
            member_id: member.parent_transaction_id
            for member_id, member in members.items()
        }
        roots = tuple(
            member_id
            for member_id, parent in parents.items()
            if parent is None
        )
        if len(roots) != 1:
            raise MutationJournalError(
                "writer epoch live family requires exactly one root"
            )
        depths = {roots[0]: 0}
        unresolved = set(members).difference(depths)
        while unresolved:
            progressed = False
            for member_id in sorted(unresolved):
                parent = parents[member_id]
                if parent in depths:
                    depths[member_id] = depths[cast(str, parent)] + 1
                    unresolved.remove(member_id)
                    progressed = True
                    break
            if not progressed:
                raise MutationJournalError(
                    "writer epoch live family is disconnected or cyclic"
                )
        expected_ids = set(members)
        for member in members.values():
            projected_ids = {
                str(member_id)
                for member_id in member._manifest.get(
                    "registry_transaction_family",
                    (),
                )
            }
            projected_parents = {
                str(member_id): (
                    str(parent) if parent is not None else None
                )
                for member_id, parent in member._manifest.get(
                    "registry_family_parents",
                    {},
                ).items()
            }
            if projected_ids != expected_ids or projected_parents != parents:
                raise MutationJournalError(
                    "writer epoch live registry projection differs from its "
                    "process-owned family"
                )
        return tuple(
            members[member_id]
            for member_id in sorted(
                members,
                key=lambda item: (depths[item], item),
            )
        )


def _after_fork_child() -> None:
    """Discard process-local grants and close inherited flock descriptors."""

    global _HELD_AUTHORITY_DESCRIPTORS
    global _HELD_LOCK_DESCRIPTORS
    global _FAILED_LIVE_TRANSACTIONS
    global _IN_PROCESS_LOCKS
    global _IN_PROCESS_EXTERNAL_COMMON_LOCKS
    global _IN_PROCESS_EXTERNAL_ROOT_LOCKS
    global _IN_PROCESS_LOCKS_GUARD
    global _LIVE_JOURNAL_OBJECTS
    global _LIVE_TRANSACTIONS
    global _LIVE_TRANSACTIONS_LOCK
    global _LOCK_STATE

    # Do not issue LOCK_UN: flock state is attached to the inherited open file
    # description and an explicit unlock here would release the parent's grant.
    for descriptor in tuple(
        _HELD_LOCK_DESCRIPTORS | _HELD_AUTHORITY_DESCRIPTORS
    ):
        try:
            os.close(descriptor)
        except OSError:
            pass
    _HELD_LOCK_DESCRIPTORS = set()
    _HELD_AUTHORITY_DESCRIPTORS = set()
    _IN_PROCESS_LOCKS_GUARD = threading.Lock()
    _IN_PROCESS_LOCKS = {}
    _IN_PROCESS_EXTERNAL_COMMON_LOCKS = {}
    _IN_PROCESS_EXTERNAL_ROOT_LOCKS = {}
    _LOCK_STATE = threading.local()
    _LIVE_TRANSACTIONS_LOCK = threading.RLock()
    _LIVE_TRANSACTIONS = set()
    _LIVE_JOURNAL_OBJECTS = {}
    _FAILED_LIVE_TRANSACTIONS = set()


if hasattr(os, "register_at_fork"):
    os.register_at_fork(after_in_child=_after_fork_child)


def _is_live(transaction_id: str) -> bool:
    with _LIVE_TRANSACTIONS_LOCK:
        return transaction_id in _LIVE_TRANSACTIONS


class MutationJournalError(RuntimeError):
    """The checkout could not be snapshotted or restored safely."""


class _SpecAuthorityEntryError(MutationJournalError):
    """The Corpus Spec authority guard could not be entered safely."""


@contextmanager
def _readable_spec_authority(corpus: "Corpus"):
    """Enter Corpus authority while distinguishing entry from body errors."""

    with ExitStack() as stack:
        try:
            authority = corpus.retained_spec_authority()
            # Retain the exact Assay owner before direct entry.  This callback
            # is inert until the source publishes its lease, but closes the
            # callee-to-caller return window before our assignment can run.
            stack.callback(authority.retry_cleanup)
            spec = authority.__enter__()
        except Exception as exc:  # noqa: BLE001 - normalize guard entry only
            raise _SpecAuthorityEntryError(
                "latest Spec authority is unreadable: "
                f"{type(exc).__name__}: {exc}"
            ) from exc
        yield spec


class MutationJournalCleanupError(MutationJournalError):
    """Journal setup failed while its exact retry authority stays owned."""

    def __init__(
        self,
        *,
        owner: "WorkspaceMutationJournal",
        primary_error: BaseException,
        cleanup_error: BaseException | None = None,
    ) -> None:
        if not owner.cleanup_pending:
            raise ValueError(
                "MutationJournalCleanupError requires live cleanup authority"
            )
        self.owner = owner
        self.primary_error = primary_error
        self.cleanup_error = cleanup_error
        detail = (
            f"; cleanup={type(cleanup_error).__name__}: {cleanup_error}"
            if cleanup_error is not None
            else ""
        )
        super().__init__(
            "mutation journal setup failed after "
            f"{type(primary_error).__name__}: {primary_error}; retained="
            f"{owner.journal_dir}{detail}"
        )

    def retry_cleanup(self) -> None:
        """Retry the exact retained journal and replace this owner on failure."""

        try:
            # The error may escape the workflow's original lock scope.  The
            # retry handle therefore carries the same serialization guarantee
            # as a fresh mutation workflow.
            with self.owner._pre_root_restore_authority():
                settled = self.owner.retry_cleanup()
        except BaseException as cleanup_error:
            if self.owner.cleanup_pending:
                raise MutationJournalCleanupError(
                    owner=self.owner,
                    primary_error=self,
                    cleanup_error=cleanup_error,
                ) from self
            raise MutationJournalError(
                "mutation journal cleanup retry failed after all authority "
                f"settled: {type(cleanup_error).__name__}: {cleanup_error}"
            ) from cleanup_error
        if self.owner.cleanup_pending:
            raise MutationJournalCleanupError(
                owner=self.owner,
                primary_error=self,
                cleanup_error=MutationJournalError(
                    "mutation journal retained ownership after cleanup retry"
                ),
            ) from self
        if settled is not True:
            raise MutationJournalError(
                "mutation journal cleanup retry reported failure after all "
                "authority settled"
            ) from self


def _require_live_parent_transaction(
    transaction_id: str,
) -> "WorkspaceMutationJournal":
    """Resolve a process-owned active parent or reject the claimed lineage."""

    if not isinstance(transaction_id, str) or not transaction_id:
        raise MutationJournalError("parent mutation transaction id is invalid")
    with _LIVE_TRANSACTIONS_LOCK:
        parent = _LIVE_JOURNAL_OBJECTS.get(transaction_id)
        if (
            transaction_id not in _LIVE_TRANSACTIONS
            or parent is None
            or not parent.active
        ):
            raise MutationJournalError(
                "parent mutation transaction is not live in this process: "
                f"{transaction_id}"
            )
        return parent


def validate_live_parent_transaction(
    transaction_id: str,
    *,
    cwd: str | Path,
) -> None:
    """Validate hidden child-workflow authority before backend acquisition.

    Parent IDs are process-local capabilities, not caller assertions.  A
    nested workflow may defer lifecycle publication only to an active parent
    journal that owns the exact same target checkout.
    """

    parent = _require_live_parent_transaction(transaction_id)
    active = _active_workspace_mutation_authority(cwd)
    if active is not None:
        authority = _assert_workspace_mutation_authority(cwd)
        metadata = os.fstat(authority.root_descriptor)
        expected = parent._manifest.get("authority_lock") or {}
        if (
            expected.get("root_device") is not None
            and metadata.st_dev != int(expected["root_device"])
        ) or (
            expected.get("root_inode") is not None
            and metadata.st_ino != int(expected["root_inode"])
        ):
            raise MutationJournalError(
                "parent mutation transaction owns a different checkout inode"
            )
        return
    expected_root = Path(cwd).resolve()
    parent_root = Path(parent._manifest["cwd"]).resolve()
    if parent_root != expected_root:
        raise MutationJournalError(
            "parent mutation transaction belongs to a different checkout: "
            f"expected {expected_root}, observed {parent_root}"
        )


def validated_live_parent_writer_epoch_family(
    transaction_id: str,
    *,
    cwd: str | Path,
) -> tuple["WorkspaceMutationJournal", ...]:
    """Return the exact sole live family for a nested workflow checkout.

    A process-local parent ID authenticates ancestry, but nested recovery must
    also reject an unrelated live root in the same checkout.  The caller holds
    the workspace mutation lock, so the registry projection cannot acquire a
    new workflow-owned writer between this proof and child journal creation.
    """

    validate_live_parent_transaction(transaction_id, cwd=cwd)
    parent = _require_live_parent_transaction(transaction_id)
    family = live_writer_epoch_family(parent)
    family_ids = {member.transaction_id for member in family}
    expected_root = _lexical_workspace_path(cwd)
    with _LIVE_TRANSACTIONS_LOCK:
        unrelated = sorted(
            member_id
            for member_id, member in _LIVE_JOURNAL_OBJECTS.items()
            if (
                member.active
                and _lexical_workspace_path(member._manifest["cwd"])
                == expected_root
                and member_id not in family_ids
            )
        )
    if unrelated:
        raise MutationJournalError(
            "nested mutation authority has unrelated live checkout owners: "
            f"{unrelated!r}"
        )
    return family


