class WorkspaceMutationLockAcquisitionLease:
    """Source-published proof that one lock layer reached its yield.

    A caller can retain the accompanying context's ``retry_cleanup`` before
    invoking ``__enter__``. The callback is inert while this lease is pending.
    Every resource-bearing source in the recovery chain publishes from inside
    its held lexical scope immediately before yielding. Its parent registers
    that owner before entry, closing both the raw source and retained-wrapper
    return windows. A plain ``with`` has no owner installed at its own
    ``__enter__`` return opcode and is not an interruption-safe substitute.
    """

    def __init__(self) -> None:
        self._phase: Literal[
            "pending",
            "active",
            "settling",
            "released",
            "abandoned",
        ] = "pending"

    @property
    def entry_pending(self) -> bool:
        return self._phase == "pending"

    @property
    def cleanup_required(self) -> bool:
        """Whether the source generator is suspended with a live lock."""

        return self._phase == "active"

    @property
    def cleanup_complete(self) -> bool:
        return self._phase in {"released", "abandoned"}

    @property
    def settlement_pending(self) -> bool:
        return self._phase == "settling"

    def _publish(self) -> None:
        if self._phase != "pending":
            raise RuntimeError("workspace acquisition lease is not reusable")
        self._phase = "active"

    def _begin_settlement(self) -> None:
        if self._phase == "active":
            self._phase = "settling"

    def _mark_released(self) -> None:
        if self._phase not in {"active", "settling"}:
            raise RuntimeError("workspace acquisition lease has no live release")
        self._phase = "released"

    def _abandon(self) -> None:
        if self._phase == "pending":
            self._phase = "abandoned"


_AcquisitionT = TypeVar("_AcquisitionT")
_AcquisitionT_co = TypeVar("_AcquisitionT_co", covariant=True)
_SETTLED_ACQUISITION_INTERRUPT_ATTR = (
    "_crucible_settled_acquisition_interrupt"
)
_SETTLED_ACQUISITION_INTERRUPT_TOKEN = object()


class _RetryableAcquisitionOwner(Protocol[_AcquisitionT_co]):
    """One pre-registerable acquisition with an exact retry surface."""

    @property
    def cleanup_complete(self) -> bool: ...

    def __enter__(self) -> _AcquisitionT_co: ...

    def retry_cleanup(self) -> None: ...


class _RetainedAcquisition(
    AbstractContextManager[_AcquisitionT],
    Generic[_AcquisitionT],
):
    """One source-published context with a pre-registerable exact owner."""

    def __init__(
        self,
        context: AbstractContextManager[_AcquisitionT],
        acquisition_lease: WorkspaceMutationLockAcquisitionLease,
    ) -> None:
        self._context = context
        self.acquisition_lease = acquisition_lease
        self._exit_complete = False
        self._exit_failure: BaseException | None = None
        self._nested_cleanup_owner: (
            _RetainedAcquisitionOwnerChain | None
        ) = None

    @property
    def cleanup_complete(self) -> bool:
        return bool(
            self._exit_failure is None
            and (
                self._nested_cleanup_owner is None
                or self._nested_cleanup_owner.cleanup_complete
            )
            and (
                self._exit_complete
                or self.acquisition_lease.cleanup_complete
            )
        )

    def _exit_once(
        self,
        exc_type: type[BaseException] | None,
        exc: BaseException | None,
        traceback: TracebackType | None,
    ) -> bool:
        if self._exit_complete:
            return False
        if self._exit_failure is not None:
            raise self._exit_failure.with_traceback(
                self._exit_failure.__traceback__
            )
        if not self.acquisition_lease.cleanup_required:
            # Entry has not reached the source-owned publish point, or the
            # source already began lexical settlement itself.  In either case
            # calling a generator ``__exit__`` here would be unsafe/redundant.
            self.acquisition_lease._abandon()
            return False
        try:
            suppressed = self._context.__exit__(exc_type, exc, traceback)
        except BaseException as exit_error:  # noqa: BLE001 - exact owner
            nested_owner = _retained_acquisition_cleanup_owner(exit_error)
            if nested_owner is not None:
                self._nested_cleanup_owner = nested_owner
            if self.acquisition_lease.cleanup_complete:
                # A source can positively prove that an operation completed
                # before an asynchronous exception crossed its return.  Do not
                # retain false cleanup debt over an already-settled resource.
                self._exit_complete = True
            elif (
                self.acquisition_lease.settlement_pending
                and _is_settled_acquisition_interrupt(exit_error)
            ):
                # A nested exact owner replayed the same SIGINT only after its
                # complete LIFO chain settled.  Reaching this source boundary
                # proves all of this generator's intervening finally blocks ran.
                self._exit_complete = True
                self.acquisition_lease._mark_released()
            elif not self.acquisition_lease.cleanup_required:
                # The generator crossed its one-shot exit frontier.  Retain
                # that exact failure; retrying a consumed generator can falsely
                # report success while its cleanup debt remains unresolved.
                self._exit_failure = exit_error
            raise
        self._exit_complete = True
        if not self.acquisition_lease.cleanup_complete:
            # A generator source may have caught the exception injected by
            # ``contextlib.__exit__`` and published its own completed
            # settlement before contextlib returns ``False``.  Treat that as
            # the same successful one-shot exit; do not consume the release
            # transition twice.
            self.acquisition_lease._mark_released()
        return bool(suppressed)

    def __enter__(self) -> _AcquisitionT:
        if not self.acquisition_lease.entry_pending:
            raise RuntimeError("retained acquisition context is not reusable")
        try:
            return self._context.__enter__()
        except BaseException as entry_error:  # noqa: BLE001 - close return gap
            nested_owner = _retained_acquisition_cleanup_owner(entry_error)
            if nested_owner is not None:
                self._nested_cleanup_owner = nested_owner
            if self.acquisition_lease.cleanup_required:
                try:
                    self._exit_once(
                        type(entry_error),
                        entry_error,
                        entry_error.__traceback__,
                    )
                except BaseException as exit_error:  # noqa: BLE001
                    if exit_error is entry_error:
                        raise
                    raise exit_error from entry_error
            elif self.acquisition_lease.entry_pending:
                self.acquisition_lease._abandon()
            else:
                # The source crossed its exit frontier while entry was still
                # transferring. Preserve that one-shot failure for explicit
                # retry diagnostics rather than accepting a closed generator.
                self._exit_failure = entry_error
            raise

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc: BaseException | None,
        traceback: TracebackType | None,
    ) -> bool:
        return self._exit_once(exc_type, exc, traceback)

    def retry_cleanup(self) -> None:
        """Release one published layer, retaining a consumed exit failure."""

        nested_owner = self._nested_cleanup_owner
        if nested_owner is not None and not nested_owner.cleanup_complete:
            try:
                nested_owner.retry_cleanup()
            except BaseException:  # noqa: BLE001 - replay after exact release
                if nested_owner.cleanup_complete:
                    self._nested_cleanup_owner = None
                    if (
                        self._exit_failure is not None
                        and self.acquisition_lease.settlement_pending
                    ):
                        self._exit_failure = None
                        self._exit_complete = True
                        self.acquisition_lease._mark_released()
                raise
        if nested_owner is not None and nested_owner.cleanup_complete:
            self._nested_cleanup_owner = None
            if (
                self._exit_failure is not None
                and self.acquisition_lease.settlement_pending
            ):
                self._exit_failure = None
                self._exit_complete = True
                self.acquisition_lease._mark_released()
                return
        self._exit_once(None, None, None)


class RetainedRecoveryWorkspaceMutationLock(
    _RetainedAcquisition[_WorkspaceMutationAuthority],
):
    """Recovery lock context with a pre-registerable exact exit owner."""


class _RetainedAcquisitionCleanupError(MutationJournalError):
    """A nested acquisition cleanup failed while its exact owner remains."""

    def __init__(
        self,
        *,
        owner: "_RetainedAcquisitionOwnerChain",
        primary_error: BaseException | None,
        cleanup_error: BaseException,
    ) -> None:
        self.owner = owner
        self.primary_error = primary_error
        self.cleanup_error = cleanup_error
        # Never invoke arbitrary exception formatting while publishing the
        # exact retry owner.  Typed fields retain the complete diagnostics.
        super().__init__("retained acquisition cleanup failed")


def _retained_acquisition_cleanup_owner(
    error: BaseException,
) -> "_RetainedAcquisitionOwnerChain | None":
    """Read only our exact typed error; never invoke a hostile owner hook."""

    if type(error) is not _RetainedAcquisitionCleanupError:
        return None
    owner = vars(error).get("owner")
    return owner if isinstance(owner, _RetainedAcquisitionOwnerChain) else None


def _mark_settled_acquisition_interrupt(error: BaseException) -> None:
    """Tag exact SIGINT replay after every owner in one chain settled."""

    if type(error) is KeyboardInterrupt:
        vars(error)[_SETTLED_ACQUISITION_INTERRUPT_ATTR] = (
            _SETTLED_ACQUISITION_INTERRUPT_TOKEN
        )


def _is_settled_acquisition_interrupt(error: BaseException) -> bool:
    """Recognize only our private marker on the built-in interrupt type."""

    return bool(
        type(error) is KeyboardInterrupt
        and vars(error).get(_SETTLED_ACQUISITION_INTERRUPT_ATTR)
        is _SETTLED_ACQUISITION_INTERRUPT_TOKEN
    )


def _rlock_depth(lock: threading.RLock, *, label: str) -> tuple[int, bool]:
    """Return this thread's RLock depth and whether it is exact."""

    recursion_count = getattr(lock, "_recursion_count", None)
    if callable(recursion_count):
        depth = recursion_count()
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise MutationJournalError(f"{label} depth is malformed")
        return depth, True
    is_owned = getattr(lock, "_is_owned", None)
    if callable(is_owned):
        return (1 if is_owned() else 0), False
    raise MutationJournalError(f"{label} ownership is not observable")


class _RetainedRLockDepthOwner(AbstractContextManager[None]):
    """Retain exactly one RLock depth across post-operation interruption."""

    def __init__(
        self,
        lock: threading.RLock,
        *,
        nonblocking: bool,
        label: str,
    ) -> None:
        self._lock = lock
        self._nonblocking = nonblocking
        self._label = label
        self._entry_started = False
        self._owner_pid: int | None = None
        self._owner_thread_id: int | None = None
        self._depth_before: int | None = None
        self._depth_exact = False
        self._cleanup_pending = False
        self._cleanup_complete = False

    @property
    def cleanup_complete(self) -> bool:
        return self._cleanup_complete

    def _assert_cleanup_thread(self) -> None:
        if self._owner_pid is None or self._owner_thread_id is None:
            return
        if os.getpid() != self._owner_pid:
            raise MutationJournalError(
                f"{self._label} cleanup belongs to another process generation"
            )
        if threading.get_ident() != self._owner_thread_id:
            raise MutationJournalError(
                f"{self._label} cleanup belongs to another thread"
            )

    def _has_added_depth(self) -> bool:
        baseline = self._depth_before
        if baseline is None:
            return False
        current, exact = _rlock_depth(self._lock, label=self._label)
        if self._depth_exact:
            if not exact:
                raise MutationJournalError(
                    f"{self._label} exact depth became unobservable"
                )
            if current not in {baseline, baseline + 1}:
                raise MutationJournalError(
                    f"{self._label} depth changed outside its retained owner"
                )
            return current == baseline + 1
        if baseline:
            raise MutationJournalError(
                f"cannot prove reentrant {self._label} cleanup on this runtime"
            )
        return current > 0

    def __enter__(self) -> None:
        if self._entry_started:
            raise RuntimeError("retained RLock acquisition is not reusable")
        self._entry_started = True
        self._owner_pid = os.getpid()
        self._owner_thread_id = threading.get_ident()
        self._depth_before, self._depth_exact = _rlock_depth(
            self._lock,
            label=self._label,
        )
        if self._depth_before and not self._depth_exact:
            raise MutationJournalError(
                f"cannot prove reentrant {self._label} depth on this runtime"
            )
        # Mark cleanup first: acquire() may succeed and then be interrupted at
        # its return boundary before Python can record the boolean result.
        self._cleanup_pending = True
        try:
            acquired = self._lock.acquire(not self._nonblocking)
            if not acquired:
                raise MutationJournalError(
                    f"{self._label} is busy; refusing deadlock-prone nested "
                    "acquisition"
                )
            if not self._has_added_depth():
                raise MutationJournalError(
                    f"{self._label} acquisition did not publish one exact depth"
                )
            return None
        except BaseException as entry_error:  # noqa: BLE001 - exact depth owner
            try:
                self.retry_cleanup()
            except BaseException as cleanup_error:  # noqa: BLE001
                if self.cleanup_complete:
                    if cleanup_error is entry_error:
                        raise
                    raise entry_error.with_traceback(
                        entry_error.__traceback__
                    ) from cleanup_error
                raise
            raise

    def __exit__(
        self,
        _exc_type: type[BaseException] | None,
        _exc: BaseException | None,
        _traceback: TracebackType | None,
    ) -> Literal[False]:
        self.retry_cleanup()
        return False

    def retry_cleanup(self) -> None:
        """Release only this owner's added recursion depth, exactly once."""

        if self._cleanup_complete:
            return
        if self._owner_pid is not None and os.getpid() != self._owner_pid:
            # ``register_at_fork`` discards every inherited process grant and
            # closes its flock descriptors before child code can run.  The
            # inherited Python RLock is a private child-memory copy, not the
            # freshly registered child lock; abandoning that obsolete depth is
            # required so normal unwinding cannot disturb reacquired authority.
            self._cleanup_pending = False
            self._cleanup_complete = True
            return
        self._assert_cleanup_thread()
        if not self._cleanup_pending or not self._has_added_depth():
            self._cleanup_pending = False
            self._cleanup_complete = True
            return
        try:
            self._lock.release()
        except BaseException:  # noqa: BLE001 - prove post-release interruption
            if not self._has_added_depth():
                self._cleanup_pending = False
                self._cleanup_complete = True
            raise
        if self._has_added_depth():
            raise MutationJournalError(
                f"{self._label} release did not settle its exact depth"
            )
        self._cleanup_pending = False
        self._cleanup_complete = True


class _RetainedAcquisitionOwnerChain:
    """Strict-LIFO owner chain retained across a failing nested release."""

    def __init__(self) -> None:
        self._owners: list[_RetryableAcquisitionOwner[Any]] = []
        self._deferred_error: BaseException | None = None

    @property
    def cleanup_complete(self) -> bool:
        return not self._owners

    def __enter__(self) -> "_RetainedAcquisitionOwnerChain":
        return self

    def enter_context(
        self,
        context: _RetryableAcquisitionOwner[_AcquisitionT],
    ) -> _AcquisitionT:
        self._owners.append(context)
        return context.__enter__()

    def retry_cleanup(self) -> None:
        while self._owners:
            owner = self._owners[-1]
            try:
                owner.retry_cleanup()
            except BaseException as cleanup_error:  # noqa: BLE001 - exact replay
                if owner.cleanup_complete:
                    self._owners.pop()
                    if self._deferred_error is None:
                        # Preserve a post-success interrupt across a later
                        # outer-owner cleanup failure.  Otherwise a retry could
                        # settle the chain while silently losing the first
                        # asynchronous exception.
                        self._deferred_error = cleanup_error
                    continue
                raise
            else:
                self._owners.pop()
        deferred_error = self._deferred_error
        if deferred_error is not None:
            self._deferred_error = None
            _mark_settled_acquisition_interrupt(deferred_error)
            raise deferred_error.with_traceback(deferred_error.__traceback__)

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc: BaseException | None,
        traceback: TracebackType | None,
    ) -> Literal[False]:
        try:
            self.retry_cleanup()
        except BaseException as cleanup_error:  # noqa: BLE001 - exact owner
            if self.cleanup_complete:
                raise
            raise _RetainedAcquisitionCleanupError(
                owner=self,
                primary_error=exc,
                cleanup_error=cleanup_error,
            ) from exc
        return False


@dataclass(frozen=True)
class _GitAdminAuthorityBatch:
    """One short-lived, thread-bound proof for an admin-tree operation."""

    journal_token: object
    transaction_id: str
    owner_pid: int
    owner_thread_id: int
    authorities: tuple[
        tuple[_WorkspaceMutationAuthority, _ExternalWorkspaceCoordination], ...
    ]


_AUTHORITY_DISCOVERY_TIMEOUT_S = 5.0
_CONTROL_FILE_MAX_BYTES = 1024 * 1024


def _read_bounded_control_file(
    path: Path,
    *,
    required: bool,
    label: str,
) -> bytes | None:
    """Read one Git control file without following/blocking special files."""

    candidate = path if path.is_absolute() else path.absolute()
    try:
        metadata = candidate.lstat()
    except FileNotFoundError as exc:
        if required:
            raise MutationJournalError(
                f"required {label} is missing: {candidate}"
            ) from exc
        return None
    except OSError as exc:
        raise MutationJournalError(
            f"cannot inspect {label} {candidate}: {exc}"
        ) from exc
    if not stat.S_ISREG(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
        raise MutationJournalError(f"{label} must be a real regular file")
    if metadata.st_nlink != 1:
        raise MutationJournalError(f"{label} must not be hard-linked")
    if metadata.st_size > _CONTROL_FILE_MAX_BYTES:
        raise MutationJournalError(
            f"{label} exceeds {_CONTROL_FILE_MAX_BYTES} bytes"
        )
    flags = (
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0)
        | getattr(os, "O_NONBLOCK", 0)
    )
    try:
        descriptor = os.open(candidate, flags)
    except OSError as exc:
        raise MutationJournalError(
            f"cannot safely open {label} {candidate}: {exc}"
        ) from exc
    try:
        opened = os.fstat(descriptor)
        stable_fields = (
            "st_dev",
            "st_ino",
            "st_mode",
            "st_nlink",
            "st_size",
            "st_mtime_ns",
            "st_ctime_ns",
        )
        if (
            not stat.S_ISREG(opened.st_mode)
            or opened.st_nlink != 1
            or any(
                getattr(metadata, field) != getattr(opened, field)
                for field in stable_fields
            )
        ):
            raise MutationJournalError(f"{label} changed while opening")
        chunks: list[bytes] = []
        observed = 0
        while True:
            chunk = os.read(descriptor, 64 * 1024)
            if not chunk:
                break
            observed += len(chunk)
            if observed > _CONTROL_FILE_MAX_BYTES:
                raise MutationJournalError(
                    f"{label} grew beyond {_CONTROL_FILE_MAX_BYTES} bytes"
                )
            chunks.append(chunk)
        finished = os.fstat(descriptor)
        if any(
            getattr(opened, field) != getattr(finished, field)
            for field in stable_fields
        ):
            raise MutationJournalError(f"{label} changed during inspection")
        current = candidate.lstat()
        if any(
            getattr(opened, field) != getattr(current, field)
            for field in stable_fields
        ):
            raise MutationJournalError(f"{label} changed identity")
        return b"".join(chunks)
    except MutationJournalError:
        raise
    except (OSError, TypeError, ValueError) as exc:
        raise MutationJournalError(f"cannot read {label}: {exc}") from exc
    finally:
        os.close(descriptor)


def _thread_workspace_authorities() -> tuple[_WorkspaceMutationAuthority, ...]:
    """Return a snapshot of the authorities this thread holds in this process.

    An owner that was dropped unexited stays registered until a garbage
    collection finalizes its lock generators, and that release removes its
    keys from this registry.  A collection can begin at any call a caller
    makes, so no caller iterates the registry itself: one C call copies its
    values, and a collection cannot begin inside that call.
    """

    return tuple(
        authority
        for authority in tuple(
            getattr(_LOCK_STATE, "authorities", {}).values()
        )
        if authority.owner_pid == os.getpid()
    )


def _lexical_absolute_control_path(base: Path, rendered: str) -> Path:
    if not rendered or "\0" in rendered or "\n" in rendered or "\r" in rendered:
        raise MutationJournalError("Git control path is malformed")
    candidate = Path(rendered)
    if not candidate.is_absolute():
        candidate = base / candidate
    candidate = Path(os.path.abspath(os.fspath(candidate)))
    if not candidate.is_absolute():  # pragma: no cover - abspath contract
        raise MutationJournalError("Git control path is not absolute")
    # Descriptor-bound Git intentionally renders --git-path results beneath
    # GIT_DIR=/proc/self/fd/N.  Persisting that process-local spelling would
    # leave a dead fd in the journal.  Convert only a descriptor this thread
    # already holds back to its authenticated logical root; arbitrary /proc or
    # symlink spellings receive no such authority.
    descriptor_binding = _held_authority_descriptor_path(candidate)
    if descriptor_binding is not None:
        descriptor, _alias, relative = descriptor_binding
        logical_roots: set[Path] = set()
        for authority in _thread_workspace_authorities():
            for logical_root, held_descriptor in (
                (authority.root, authority.root_descriptor),
                (authority.common_dir, authority.common_descriptor),
                (authority.git_common_dir, authority.git_common_descriptor),
                (authority.git_dir, authority.git_dir_descriptor),
            ):
                if held_descriptor == descriptor:
                    logical_roots.add(logical_root)
        if len(logical_roots) != 1:
            raise MutationJournalError(
                "held Git control path has ambiguous logical authority: "
                f"{candidate}"
            )
        candidate = next(iter(logical_roots)) / relative
    return candidate


def _preflight_local_config_authority(cwd: Path) -> None:
    """Reject local include directives before any Git authority command."""

    dotgit = cwd / ".git"
    try:
        metadata = dotgit.lstat()
    except OSError as exc:
        raise MutationJournalError(
            f"cannot inspect checkout Git control path {dotgit}: {exc}"
        ) from exc
    configs: list[tuple[str, Path, bool]] = []
    if stat.S_ISDIR(metadata.st_mode) and not stat.S_ISLNK(metadata.st_mode):
        configs.extend((
            ("repository config", dotgit / "config", True),
            ("worktree config", dotgit / "config.worktree", False),
        ))
    elif stat.S_ISREG(metadata.st_mode) and not stat.S_ISLNK(metadata.st_mode):
        control = _read_bounded_control_file(
            dotgit,
            required=True,
            label="checkout .git control file",
        )
        assert control is not None
        lines = control.splitlines()
        if len(lines) != 1 or not lines[0].lower().startswith(b"gitdir: "):
            raise MutationJournalError("checkout .git control file is malformed")
        gitdir = _lexical_absolute_control_path(
            cwd,
            os.fsdecode(lines[0][8:]),
        )
        commondir_payload = _read_bounded_control_file(
            gitdir / "commondir",
            required=False,
            label="Git commondir control file",
        )
        common_dir = gitdir
        if commondir_payload is not None:
            commondir_lines = commondir_payload.splitlines()
            if len(commondir_lines) != 1 or not commondir_lines[0]:
                raise MutationJournalError("Git commondir file is malformed")
            common_dir = _lexical_absolute_control_path(
                gitdir,
                os.fsdecode(commondir_lines[0]),
            )
        configs.extend((
            ("repository config", common_dir / "config", True),
            ("worktree config", gitdir / "config.worktree", False),
        ))
    else:
        raise MutationJournalError(
            "checkout .git control path must be a real file or directory"
        )

    for label, path, required in configs:
        payload = _read_bounded_control_file(
            path,
            required=required,
            label=label,
        )
        if payload is None:
            continue
        if any(
            line.lstrip().lower().startswith(b"[include")
            for line in payload.splitlines()
        ):
            raise MutationJournalError(
                "Git config include/includeIf directives are unsupported "
                "during workspace authority discovery"
            )


def _open_authority_directory(path: Path, *, label: str) -> tuple[int, os.stat_result]:
    try:
        metadata = path.lstat()
    except OSError as exc:
        raise MutationJournalError(f"cannot inspect {label} {path}: {exc}") from exc
    if not stat.S_ISDIR(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
        raise MutationJournalError(f"{label} must be a real directory: {path}")
    flags = (
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    descriptor: int | None = None
    try:
        descriptor = os.open(path, flags)
        opened = os.fstat(descriptor)
    except OSError as exc:
        if descriptor is not None:
            os.close(descriptor)
        raise MutationJournalError(
            f"cannot bind {label} {path}: {exc}"
        ) from exc
    assert descriptor is not None
    if (
        not stat.S_ISDIR(opened.st_mode)
        or opened.st_dev != metadata.st_dev
        or opened.st_ino != metadata.st_ino
    ):
        os.close(descriptor)
        raise MutationJournalError(f"{label} changed while opening: {path}")
    return descriptor, opened


def _assert_authority_directory_binding(
    path: Path,
    descriptor: int,
    expected: os.stat_result,
    *,
    label: str,
) -> None:
    try:
        current = path.lstat()
        held = os.fstat(descriptor)
    except OSError as exc:
        raise MutationJournalError(
            f"cannot revalidate {label} {path}: {exc}"
        ) from exc
    if (
        not stat.S_ISDIR(current.st_mode)
        or stat.S_ISLNK(current.st_mode)
        or not stat.S_ISDIR(held.st_mode)
        or current.st_dev != expected.st_dev
        or current.st_ino != expected.st_ino
        or held.st_dev != expected.st_dev
        or held.st_ino != expected.st_ino
    ):
        raise MutationJournalError(f"{label} changed identity: {path}")


def _open_authority_directory_at(
    parent_fd: int,
    name: str,
    *,
    label: str,
) -> tuple[int, os.stat_result]:
    """Open one real directory relative to an already-held parent."""

    flags = (
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    descriptor: int | None = None
    try:
        before = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        descriptor = os.open(name, flags, dir_fd=parent_fd)
        opened = os.fstat(descriptor)
        after = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except OSError as exc:
        if descriptor is not None:
            os.close(descriptor)
        raise MutationJournalError(
            f"cannot bind {label} relative to held checkout: {exc}"
        ) from exc
    assert descriptor is not None
    if (
        not stat.S_ISDIR(opened.st_mode)
        or stat.S_ISLNK(before.st_mode)
        or (before.st_dev, before.st_ino) != (opened.st_dev, opened.st_ino)
        or (after.st_dev, after.st_ino) != (opened.st_dev, opened.st_ino)
    ):
        os.close(descriptor)
        raise MutationJournalError(f"{label} changed while opening")
    return descriptor, opened


def _open_authority_path_directory_at(
    parent_fd: int,
    name: str,
    *,
    label: str,
) -> tuple[int, os.stat_result]:
    """Bind one real directory without requiring read/search permission."""

    if not hasattr(os, "O_PATH"):
        raise MutationJournalError(
            f"platform cannot bind inaccessible {label}"
        )
    flags = (
        os.O_PATH
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    descriptor: int | None = None
    try:
        before = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        descriptor = os.open(name, flags, dir_fd=parent_fd)
        opened = os.fstat(descriptor)
        after = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except OSError as exc:
        if descriptor is not None:
            os.close(descriptor)
        raise MutationJournalError(
            f"cannot bind {label} relative to held checkout: {exc}"
        ) from exc
    assert descriptor is not None
    if (
        not stat.S_ISDIR(opened.st_mode)
        or stat.S_ISLNK(before.st_mode)
        or (before.st_dev, before.st_ino) != (opened.st_dev, opened.st_ino)
        or (after.st_dev, after.st_ino) != (opened.st_dev, opened.st_ino)
    ):
        os.close(descriptor)
        raise MutationJournalError(f"{label} changed while opening")
    return descriptor, opened


def _parse_git_control_path(payload: bytes, *, label: str) -> str:
    value = payload.rstrip(b"\r\n")
    if not value or b"\0" in value or b"\n" in value or b"\r" in value:
        raise MutationJournalError(f"malformed {label}")
    return os.fsdecode(value)


def _discover_bound_git_authority(
    root: Path,
    root_fd: int,
) -> tuple[
    Path,
    int,
    os.stat_result,
    Path,
    int,
    os.stat_result,
]:
    """Resolve ``.git`` and ``commondir`` from the held root, without Git."""

    root_alias = Path(_authority_descriptor_cwd(root_fd))
    git_entry = root_alias / ".git"
    try:
        entry_metadata = git_entry.lstat()
    except OSError as exc:
        raise MutationJournalError(
            f"cannot inspect held checkout .git entry: {exc}"
        ) from exc

    git_dir_fd: int | None = None
    git_common_fd: int | None = None
    try:
        if stat.S_ISDIR(entry_metadata.st_mode) and not stat.S_ISLNK(
            entry_metadata.st_mode
        ):
            git_dir = root / ".git"
            git_dir_fd, git_dir_metadata = _open_authority_directory_at(
                root_fd,
                ".git",
                label="workspace Git dir",
            )
        elif stat.S_ISREG(entry_metadata.st_mode) and not stat.S_ISLNK(
            entry_metadata.st_mode
        ):
            payload = _read_bounded_control_file(
                git_entry,
                required=True,
                label="checkout .git indirection",
            )
            assert payload is not None
            prefix = b"gitdir: "
            if not payload.startswith(prefix):
                raise MutationJournalError("malformed checkout .git indirection")
            rendered = _parse_git_control_path(
                payload[len(prefix):],
                label="checkout .git indirection",
            )
            candidate = Path(rendered)
            if not candidate.is_absolute():
                candidate = root_alias / candidate
            git_dir = candidate.resolve(strict=True)
            git_dir_fd, git_dir_metadata = _open_authority_directory(
                git_dir,
                label="workspace Git dir",
            )
        else:
            raise MutationJournalError(
                "held checkout .git entry must be a real directory or file"
            )

        common_control = (
            Path(_authority_descriptor_cwd(git_dir_fd)) / "commondir"
        )
        common_payload = _read_bounded_control_file(
            common_control,
            required=False,
            label="Git commondir control",
        )
        if common_payload is None:
            git_common_dir = git_dir
        else:
            rendered_common = _parse_git_control_path(
                common_payload,
                label="Git commondir control",
            )
            common_candidate = Path(rendered_common)
            if not common_candidate.is_absolute():
                common_candidate = (
                    Path(_authority_descriptor_cwd(git_dir_fd))
                    / common_candidate
                )
            git_common_dir = common_candidate.resolve(strict=True)
        git_common_fd, git_common_metadata = _open_authority_directory(
            git_common_dir,
            label="workspace Git common dir",
        )
        return (
            git_dir,
            git_dir_fd,
            git_dir_metadata,
            git_common_dir,
            git_common_fd,
            git_common_metadata,
        )
    except BaseException:
        if git_common_fd is not None:
            os.close(git_common_fd)
        if git_dir_fd is not None:
            os.close(git_dir_fd)
        raise


def _assert_bound_git_discovery(
    authority: _WorkspaceMutationAuthority,
) -> None:
    """Independently rediscover the held root's current Git admin chain."""

    (
        _git_dir_path,
        git_dir_fd,
        git_dir_metadata,
        _git_common_path,
        git_common_fd,
        git_common_metadata,
    ) = _discover_bound_git_authority(
        authority.root,
        authority.root_descriptor,
    )
    try:
        if (
            (git_dir_metadata.st_dev, git_dir_metadata.st_ino)
            != (
                authority.git_dir_metadata.st_dev,
                authority.git_dir_metadata.st_ino,
            )
            or (git_common_metadata.st_dev, git_common_metadata.st_ino)
            != (
                authority.git_common_metadata.st_dev,
                authority.git_common_metadata.st_ino,
            )
        ):
            raise MutationJournalError(
                "workspace Git admin authority changed after acquisition"
            )
    finally:
        os.close(git_common_fd)
        os.close(git_dir_fd)


def _authority_descriptor_cwd(descriptor: int) -> str:
    try:
        expected = os.fstat(descriptor)
    except OSError as exc:
        raise MutationJournalError(
            f"cannot inspect held workspace authority descriptor: {exc}"
        ) from exc
    for prefix in ("/proc/self/fd", "/dev/fd"):
        candidate = f"{prefix}/{descriptor}"
        try:
            observed = os.stat(candidate)
        except OSError:
            continue
        if observed.st_dev == expected.st_dev and observed.st_ino == expected.st_ino:
            return candidate
    raise MutationJournalError(
        "platform cannot bind Git authority discovery to a held directory"
    )


def _held_authority_descriptor_path(
    path: Path,
) -> tuple[int, Path, Path] | None:
    """Return the held authority fd, its alias, and a safe relative suffix.

    ``/proc/self/fd/N`` and ``/dev/fd/N`` are kernel-provided symlink
    spellings for an already-open directory.  Treating either spelling like
    an ordinary filesystem symlink defeats the point of descriptor-bound
    recovery; following it through an ordinary pathname operation, however,
    would make an arbitrary fd alias an authority grant.  Recognize only
    descriptors that this process currently holds for workspace authority and
    reject lexical parent traversal in the suffix.

    Only the descriptor that the path itself names is inspected, and only
    while an authority registered in this thread holds it.  The descriptors
    of another owner of the thread are never touched: a garbage collection
    may release a dropped owner during this call, and that release must
    neither fail this caller nor let a closed or reused number through.
    """

    parts = path.parts
    if parts[:4] == ("/", "proc", "self", "fd") and len(parts) > 4:
        name = parts[4]
    elif parts[:3] == ("/", "dev", "fd") and len(parts) > 3:
        name = parts[3]
    else:
        return None
    for authority in _thread_workspace_authorities():
        for descriptor in (
            authority.root_descriptor,
            authority.common_descriptor,
            authority.git_common_descriptor,
            authority.git_dir_descriptor,
        ):
            # The number is never parsed from the path: the path's text must
            # equal the canonical decimal of a number this thread holds.
            if (
                str(descriptor) != name
                or descriptor not in _HELD_AUTHORITY_DESCRIPTORS
            ):
                continue
            alias = Path(_authority_descriptor_cwd(descriptor))
            try:
                relative = path.relative_to(alias)
            except ValueError:
                return None
            if any(part == ".." for part in relative.parts):
                raise MutationJournalError(
                    f"held authority descriptor path escapes its root: {path}"
                )
            # Last step before the number is handed out: this thread still
            # registers the same authority and the number is still held.  A
            # release removes the registration, then discards the number,
            # then closes it.  The registry is read by one subscript and no
            # call follows it before the return, so neither a collection nor
            # another thread can release the owner, or reuse its number, in
            # between.
            try:
                registered = getattr(_LOCK_STATE, "authorities", {})[
                    authority.root
                ]
            except KeyError:
                registered = None
            if (
                registered is not authority
                or descriptor not in _HELD_AUTHORITY_DESCRIPTORS
            ):
                raise MutationJournalError(
                    "held workspace authority descriptor was released "
                    f"during inspection: {path}"
                )
            return descriptor, alias, relative
    return None


def _descriptor_bound_lstat(path: Path) -> os.stat_result:
    """Return directory metadata for an exact held-fd alias, else lstat."""

    binding = _held_authority_descriptor_path(path)
    if binding is not None and binding[2] == Path("."):
        return os.fstat(binding[0])
    return path.lstat()


def _recovery_settlement(
    corpus: "Corpus",
    journal: "WorkspaceMutationJournal",
    *,
    disposition: str,
) -> RecoverySettlement:
    """Describe only evidence that resolves to one exact attached record."""

    expected = journal._manifest.get("expected_implementation")
    lineage = journal._manifest.get("lineage")
    implementation_ref = _expected_implementation_ref(
        corpus,
        expected if isinstance(expected, dict) else None,
        lineage if isinstance(lineage, dict) else None,
        strict_ambiguity=disposition == "preserved",
    )
    expected_lifecycle = journal._manifest.get("expected_lifecycle")
    lifecycle_ref = _expected_lifecycle_ref(
        corpus,
        expected_lifecycle if isinstance(expected_lifecycle, dict) else None,
        lineage if isinstance(lineage, dict) else None,
        strict_ambiguity=disposition == "preserved",
    )
    baseline_spec_version: int | None = None
    baseline_spec_hash: str | None = None
    if isinstance(lineage, dict):
        version = lineage.get("spec_version")
        if isinstance(version, int) and not isinstance(version, bool):
            baseline_spec_version = version
        rendered_hash = lineage.get("spec_hash")
        if isinstance(rendered_hash, str):
            baseline_spec_hash = rendered_hash
    return RecoverySettlement(
        transaction_id=journal.transaction_id,
        slice_id=journal.slice_id,
        disposition=disposition,
        implementation_ref=implementation_ref,
        lifecycle_ref=lifecycle_ref,
        protected_scope=(
            tuple(str(path) for path in journal._manifest.get("scope", ()))
            if disposition == "preserved"
            else ()
        ),
        baseline_spec_version=baseline_spec_version,
        baseline_spec_hash=baseline_spec_hash,
    )


def _open_workspace_lock_entry(
    common_fd: int,
) -> tuple[int, os.stat_result]:
    flags = (
        os.O_RDWR
        | os.O_CREAT
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0)
        | getattr(os, "O_NONBLOCK", 0)
    )
    try:
        descriptor = os.open(
            "crucible-workspace.lock",
            flags,
            0o600,
            dir_fd=common_fd,
        )
    except OSError as exc:
        raise MutationJournalError(
            f"cannot safely open workspace authority lock: {exc}"
        ) from exc
    try:
        metadata = os.fstat(descriptor)
        current = os.stat(
            "crucible-workspace.lock",
            dir_fd=common_fd,
            follow_symlinks=False,
        )
    except OSError as exc:
        os.close(descriptor)
        raise MutationJournalError(
            f"cannot bind workspace authority lock: {exc}"
        ) from exc
    if (
        not stat.S_ISREG(metadata.st_mode)
        or metadata.st_nlink != 1
        or not stat.S_ISREG(current.st_mode)
        or current.st_nlink != 1
        or current.st_dev != metadata.st_dev
        or current.st_ino != metadata.st_ino
    ):
        os.close(descriptor)
        raise MutationJournalError(
            "workspace authority lock must be one real single-link file"
        )
    return descriptor, metadata


def _assert_workspace_lock_entry(
    common_fd: int,
    descriptor: int,
    expected: os.stat_result,
) -> None:
    try:
        held = os.fstat(descriptor)
        current = os.stat(
            "crucible-workspace.lock",
            dir_fd=common_fd,
            follow_symlinks=False,
        )
    except OSError as exc:
        raise MutationJournalError(
            f"cannot revalidate workspace authority lock: {exc}"
        ) from exc
    if (
        not stat.S_ISREG(held.st_mode)
        or held.st_nlink != 1
        or not stat.S_ISREG(current.st_mode)
        or current.st_nlink != 1
        or held.st_dev != expected.st_dev
        or held.st_ino != expected.st_ino
        or current.st_dev != expected.st_dev
        or current.st_ino != expected.st_ino
    ):
        raise MutationJournalError(
            "workspace authority lock changed identity"
        )


def _lexical_workspace_path(cwd: str | Path) -> Path:
    """Return an absolute spelling without following a replaceable alias."""

    return Path(os.path.abspath(os.fspath(cwd)))


def _external_lock_order_key(key: tuple[int, int]) -> tuple[int, int]:
    """Return the path-independent total order for external lock identities."""

    return key


def _validated_external_identity(
    device: object,
    inode: object,
    *,
    label: str,
) -> tuple[int, int]:
    if (
        isinstance(device, bool)
        or not isinstance(device, int)
        or device < 0
        or isinstance(inode, bool)
        or not isinstance(inode, int)
        or inode <= 0
    ):
        raise MutationJournalError(f"{label} identity is malformed")
    return device, inode


@contextmanager
def _bound_pre_root_workspace(
    cwd: str | Path,
    *,
    expected_root_key: tuple[int, int] | None = None,
    acquisition_lease: WorkspaceMutationLockAcquisitionLease | None = None,
) -> Iterator[_PreRootWorkspaceBinding]:
    """Pin one checkout through its parent without traversing its contents."""

    if not hasattr(os, "O_PATH"):
        raise MutationJournalError(
            "platform cannot bind external workspace root authority"
        )
    creator_pid = os.getpid()
    try:
        root = Path(cwd).resolve(strict=True)
    except (OSError, RuntimeError) as exc:
        raise MutationJournalError(
            f"cannot resolve external workspace root authority: {exc}"
        ) from exc
    if root == root.parent or root.name in {"", ".", ".."}:
        raise MutationJournalError(
            "filesystem root cannot be a workspace mutation checkout"
        )
    parent_fd, parent_metadata = _open_authority_directory(
        root.parent,
        label="external workspace root parent",
    )
    root_fd: int | None = None
    try:
        before = os.stat(
            root.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if not stat.S_ISDIR(before.st_mode) or stat.S_ISLNK(before.st_mode):
            raise MutationJournalError(
                f"external workspace root must be a real directory: {root}"
            )
        root_fd = os.open(
            root.name,
            os.O_PATH
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_NOFOLLOW", 0),
            dir_fd=parent_fd,
        )
        opened = os.fstat(root_fd)
        if (
            not stat.S_ISDIR(opened.st_mode)
            or (opened.st_dev, opened.st_ino) != (before.st_dev, before.st_ino)
        ):
            raise MutationJournalError(
                "external workspace root changed while opening"
            )
        if expected_root_key is not None and (
            opened.st_dev,
            opened.st_ino,
        ) != expected_root_key:
            raise MutationJournalError(
                "external workspace root differs from captured authority"
            )
        binding = _PreRootWorkspaceBinding(
            root=root,
            parent=root.parent,
            basename=root.name,
            parent_descriptor=parent_fd,
            parent_metadata=parent_metadata,
            root_descriptor=root_fd,
            root_metadata=opened,
        )
        _HELD_AUTHORITY_DESCRIPTORS.update((parent_fd, root_fd))
        _assert_pre_root_workspace_binding(binding)
        if acquisition_lease is not None:
            acquisition_lease._publish()
        try:
            yield binding
        finally:
            if acquisition_lease is not None:
                acquisition_lease._begin_settlement()
        if os.getpid() == creator_pid:
            _assert_pre_root_workspace_binding(binding)
    except MutationJournalError:
        raise
    except OSError as exc:
        raise MutationJournalError(
            f"cannot bind external workspace root authority: {exc}"
        ) from exc
    finally:
        if os.getpid() == creator_pid:
            if root_fd is not None:
                _HELD_AUTHORITY_DESCRIPTORS.discard(root_fd)
                os.close(root_fd)
            _HELD_AUTHORITY_DESCRIPTORS.discard(parent_fd)
            os.close(parent_fd)


def _assert_pre_root_workspace_binding(
    binding: _PreRootWorkspaceBinding,
) -> None:
    """Reprove the held parent, basename, and root inode as one authority."""

    _assert_authority_directory_binding(
        binding.parent,
        binding.parent_descriptor,
        binding.parent_metadata,
        label="external workspace root parent",
    )
    try:
        held = os.fstat(binding.root_descriptor)
        current = os.stat(
            binding.basename,
            dir_fd=binding.parent_descriptor,
            follow_symlinks=False,
        )
    except OSError as exc:
        raise MutationJournalError(
            f"cannot revalidate external workspace root: {exc}"
        ) from exc
    expected = (
        binding.root_metadata.st_dev,
        binding.root_metadata.st_ino,
    )
    if (
        not stat.S_ISDIR(held.st_mode)
        or not stat.S_ISDIR(current.st_mode)
        or stat.S_ISLNK(current.st_mode)
        or (held.st_dev, held.st_ino) != expected
        or (current.st_dev, current.st_ino) != expected
    ):
        raise MutationJournalError(
            "external workspace root changed identity"
        )


def _external_lock_filename(kind: str, key: tuple[int, int]) -> str:
    if kind not in {"common", "root"}:
        raise MutationJournalError("external workspace lock kind is invalid")
    device, inode = _validated_external_identity(
        key[0],
        key[1],
        label=f"external {kind} lock",
    )
    return f"{kind}-{device:016x}-{inode:016x}.lock"


def _assert_external_lock_parent_mode(
    metadata: os.stat_result,
    *,
    label: str,
    sticky_allowed: bool,
) -> None:
    mode = stat.S_IMODE(metadata.st_mode)
    writable = mode & (stat.S_IWGRP | stat.S_IWOTH)
    if (
        not stat.S_ISDIR(metadata.st_mode)
        or metadata.st_uid != 0
        or (writable and not (sticky_allowed and mode & stat.S_ISVTX))
    ):
        raise MutationJournalError(
            f"{label} is not a trusted root-owned directory"
        )


def _open_external_lock_namespace() -> tuple[
    int,
    os.stat_result,
    int,
    os.stat_result,
    str,
    int,
    os.stat_result,
]:
    """Open the fixed /tmp/private-UID lock namespace without following links."""

    if _EXTERNAL_LOCK_PARENT != Path("/tmp"):
        raise MutationJournalError(
            "external workspace lock parent differs from fixed /tmp authority"
        )
    root_fd, root_metadata = _open_authority_directory(
        Path("/"),
        label="external lock namespace root",
    )
    parent_fd: int | None = None
    directory_fd: int | None = None
    try:
        _assert_external_lock_parent_mode(
            root_metadata,
            label="external lock namespace root",
            sticky_allowed=False,
        )
        parent_fd, parent_metadata = _open_authority_directory_at(
            root_fd,
            "tmp",
            label="external lock namespace parent",
        )
        _assert_external_lock_parent_mode(
            parent_metadata,
            label="external lock namespace parent",
            sticky_allowed=True,
        )
        uid = os.geteuid()
        directory_name = f"{_EXTERNAL_LOCK_DIRECTORY_PREFIX}{uid}"
        try:
            os.mkdir(directory_name, 0o700, dir_fd=parent_fd)
            try:
                os.fsync(parent_fd)
            except OSError as exc:
                if exc.errno not in {errno.EINVAL, errno.ENOTSUP, errno.EROFS}:
                    raise
        except FileExistsError:
            pass
        directory_fd, directory_metadata = _open_authority_directory_at(
            parent_fd,
            directory_name,
            label="private external workspace lock directory",
        )
        if (
            directory_metadata.st_uid != uid
            or stat.S_IMODE(directory_metadata.st_mode) != 0o700
        ):
            raise MutationJournalError(
                "private external workspace lock directory has unsafe ownership "
                "or mode"
            )
        _HELD_AUTHORITY_DESCRIPTORS.update(
            (root_fd, parent_fd, directory_fd)
        )
        return (
            root_fd,
            root_metadata,
            parent_fd,
            parent_metadata,
            directory_name,
            directory_fd,
            directory_metadata,
        )
    except BaseException:
        if directory_fd is not None:
            os.close(directory_fd)
        if parent_fd is not None:
            os.close(parent_fd)
        os.close(root_fd)
        raise


def _close_external_lock_namespace(
    authority: _ExternalFileLockAuthority,
) -> None:
    for descriptor in (
        authority.directory_descriptor,
        authority.parent_descriptor,
        authority.namespace_root_descriptor,
    ):
        _HELD_AUTHORITY_DESCRIPTORS.discard(descriptor)
        os.close(descriptor)


def _assert_external_file_lock(
    authority: _ExternalFileLockAuthority,
) -> None:
    """Reprove every fixed namespace component and the named lock inode."""

    if authority.owner_pid != os.getpid():
        raise MutationJournalError(
            "external workspace lock belongs to another process generation"
        )
    _assert_authority_directory_binding(
        Path("/"),
        authority.namespace_root_descriptor,
        authority.namespace_root_metadata,
        label="external lock namespace root",
    )
    try:
        parent_current = os.stat(
            "tmp",
            dir_fd=authority.namespace_root_descriptor,
            follow_symlinks=False,
        )
        directory_current = os.stat(
            authority.directory_name,
            dir_fd=authority.parent_descriptor,
            follow_symlinks=False,
        )
        lock_current = os.stat(
            authority.filename,
            dir_fd=authority.directory_descriptor,
            follow_symlinks=False,
        )
        lock_held = os.fstat(authority.lock_descriptor)
    except OSError as exc:
        raise MutationJournalError(
            f"cannot revalidate external workspace lock: {exc}"
        ) from exc
    if (
        not stat.S_ISDIR(parent_current.st_mode)
        or stat.S_ISLNK(parent_current.st_mode)
        or (parent_current.st_dev, parent_current.st_ino)
        != (
            authority.parent_metadata.st_dev,
            authority.parent_metadata.st_ino,
        )
        or not stat.S_ISDIR(directory_current.st_mode)
        or stat.S_ISLNK(directory_current.st_mode)
        or (directory_current.st_dev, directory_current.st_ino)
        != (
            authority.directory_metadata.st_dev,
            authority.directory_metadata.st_ino,
        )
        or directory_current.st_uid != os.geteuid()
        or stat.S_IMODE(directory_current.st_mode) != 0o700
        or not stat.S_ISREG(lock_held.st_mode)
        or lock_held.st_nlink != 1
        or lock_held.st_uid != os.geteuid()
        or stat.S_IMODE(lock_held.st_mode) != 0o600
        or not stat.S_ISREG(lock_current.st_mode)
        or lock_current.st_nlink != 1
        or (lock_current.st_dev, lock_current.st_ino)
        != (authority.lock_metadata.st_dev, authority.lock_metadata.st_ino)
        or (lock_held.st_dev, lock_held.st_ino)
        != (authority.lock_metadata.st_dev, authority.lock_metadata.st_ino)
    ):
        raise MutationJournalError(
            "external workspace lock namespace or inode changed"
        )


@contextmanager
def _in_process_lock_admission(
    lock: threading.RLock,
    *,
    nonblocking: bool,
    label: str,
    acquisition_lease: WorkspaceMutationLockAcquisitionLease | None = None,
) -> Iterator[None]:
    """Acquire a process lock without waiting across an independent lock."""

    release = _RetainedAcquisitionOwnerChain()
    try:
        with release:
            release.enter_context(
                _RetainedRLockDepthOwner(
                    lock,
                    nonblocking=nonblocking,
                    label=label,
                )
            )
            if acquisition_lease is not None:
                acquisition_lease._publish()
            try:
                yield
            finally:
                if acquisition_lease is not None:
                    acquisition_lease._begin_settlement()
    except BaseException:  # noqa: BLE001 - prove post-release interruption
        if (
            acquisition_lease is not None
            and acquisition_lease.settlement_pending
            and release.cleanup_complete
        ):
            acquisition_lease._mark_released()
        raise


@contextmanager
def _external_file_lock(
    *,
    kind: str,
    key: tuple[int, int],
    common_key: tuple[int, int] | None = None,
    acquisition_lease: WorkspaceMutationLockAcquisitionLease | None = None,
) -> Iterator[_ExternalFileLockAuthority]:
    """Acquire one crash-released external lock with process reentrancy."""

    key = _validated_external_identity(
        key[0], key[1], label=f"external {kind} lock"
    )
    creator_pid = os.getpid()
    if kind == "common":
        process_locks = _IN_PROCESS_EXTERNAL_COMMON_LOCKS
        state_name = "external_common_held"
    elif kind == "root":
        process_locks = _IN_PROCESS_EXTERNAL_ROOT_LOCKS
        state_name = "external_root_held"
        if common_key is None:
            raise MutationJournalError(
                "external root lock lacks common-lock ordering authority"
            )
    else:
        raise MutationJournalError("external workspace lock kind is invalid")

    with _IN_PROCESS_LOCKS_GUARD:
        process_lock = process_locks.setdefault(key, threading.RLock())
    # A garbage collection that releases a dropped owner of this thread pops
    # that owner's entries from the per-thread lock tables, so every loop
    # over such a table reads a snapshot.
    held_before = getattr(_LOCK_STATE, state_name, {})
    nested_independent_common = kind == "common" and any(
        held_key != key
        and depth
        and held_authority.owner_pid == os.getpid()
        for held_key, (depth, held_authority, _bound_common) in tuple(
            held_before.items()
        )
    )
    with _RetainedAcquisitionOwnerChain() as admission_release:
        admission_release.enter_context(
            _retained_in_process_lock_admission(
                process_lock,
                nonblocking=nested_independent_common,
                label="external workspace common lock",
            )
        )
        held = getattr(_LOCK_STATE, state_name, {})
        existing = held.get(key)
        if existing is not None:
            depth, existing_authority, held_common_key = existing
            if existing_authority.owner_pid != os.getpid():
                held.pop(key, None)
            else:
                if kind == "root" and held_common_key != common_key:
                    raise MutationJournalError(
                        "external workspace root is bound to another common "
                        "lock identity"
                    )
                _assert_external_file_lock(existing_authority)
                held[key] = (depth + 1, existing_authority, held_common_key)
                setattr(_LOCK_STATE, state_name, held)
                try:
                    if acquisition_lease is not None:
                        acquisition_lease._publish()
                    try:
                        yield existing_authority
                    finally:
                        if acquisition_lease is not None:
                            acquisition_lease._begin_settlement()
                finally:
                    if os.getpid() == creator_pid:
                        held[key] = (
                            depth,
                            existing_authority,
                            held_common_key,
                        )
                return

        if kind == "common":
            held_keys = [
                held_key
                for held_key, (depth, held_authority, _bound_common) in tuple(
                    held.items()
                )
                if depth and held_authority.owner_pid == os.getpid()
            ]
            nested_independent_common = bool(held_keys)
        else:
            common_held = getattr(_LOCK_STATE, "external_common_held", {})
            common_entry = common_held.get(common_key)
            if (
                common_entry is None
                or not common_entry[0]
                or common_entry[1].owner_pid != os.getpid()
            ):
                raise MutationJournalError(
                    "external workspace root lock requires its common lock"
                )

        (
            namespace_root_fd,
            namespace_root_metadata,
            parent_fd,
            parent_metadata,
            directory_name,
            directory_fd,
            directory_metadata,
        ) = _open_external_lock_namespace()
        filename = _external_lock_filename(kind, key)
        descriptor: int | None = None
        locked = False
        authority: _ExternalFileLockAuthority | None = None
        try:
            try:
                descriptor = os.open(
                    filename,
                    os.O_RDWR
                    | os.O_CREAT
                    | getattr(os, "O_CLOEXEC", 0)
                    | getattr(os, "O_NOFOLLOW", 0)
                    | getattr(os, "O_NONBLOCK", 0),
                    0o600,
                    dir_fd=directory_fd,
                )
            except OSError as exc:
                raise MutationJournalError(
                    f"cannot open external workspace lock: {exc}"
                ) from exc
            metadata = os.fstat(descriptor)
            current = os.stat(
                filename,
                dir_fd=directory_fd,
                follow_symlinks=False,
            )
            if (
                not stat.S_ISREG(metadata.st_mode)
                or metadata.st_nlink != 1
                or metadata.st_uid != os.geteuid()
                or stat.S_IMODE(metadata.st_mode) != 0o600
                or not stat.S_ISREG(current.st_mode)
                or current.st_nlink != 1
                or (current.st_dev, current.st_ino)
                != (metadata.st_dev, metadata.st_ino)
            ):
                raise MutationJournalError(
                    "external workspace lock must be one private real file"
                )
            authority = _ExternalFileLockAuthority(
                kind=kind,
                key=key,
                namespace_root_descriptor=namespace_root_fd,
                namespace_root_metadata=namespace_root_metadata,
                parent_descriptor=parent_fd,
                parent_metadata=parent_metadata,
                directory_name=directory_name,
                directory_descriptor=directory_fd,
                directory_metadata=directory_metadata,
                filename=filename,
                lock_descriptor=descriptor,
                lock_metadata=metadata,
                owner_pid=os.getpid(),
            )
            _HELD_LOCK_DESCRIPTORS.add(descriptor)
            _assert_external_file_lock(authority)
            try:
                _external_flock(
                    descriptor,
                    _EXTERNAL_LOCK_EX
                    | (
                        _EXTERNAL_LOCK_NB
                        if nested_independent_common
                        else 0
                    ),
                )
            except OSError as exc:
                if nested_independent_common and exc.errno in {
                    errno.EACCES,
                    errno.EAGAIN,
                }:
                    raise MutationJournalError(
                        "external workspace common lock is busy; refusing "
                        "deadlock-prone nested acquisition"
                    ) from exc
                raise
            locked = True
            _assert_external_file_lock(authority)
            held[key] = (1, authority, common_key)
            setattr(_LOCK_STATE, state_name, held)
            try:
                if acquisition_lease is not None:
                    acquisition_lease._publish()
                try:
                    yield authority
                finally:
                    if acquisition_lease is not None:
                        acquisition_lease._begin_settlement()
            finally:
                held.pop(key, None)
                if os.getpid() == creator_pid:
                    _assert_external_file_lock(authority)
        finally:
            if os.getpid() == creator_pid:
                if locked and descriptor is not None:
                    _external_flock(descriptor, _EXTERNAL_LOCK_UN)
                if descriptor is not None:
                    _HELD_LOCK_DESCRIPTORS.discard(descriptor)
                    os.close(descriptor)
                if authority is not None:
                    _close_external_lock_namespace(authority)
                else:
                    for owned in (
                        directory_fd,
                        parent_fd,
                        namespace_root_fd,
                    ):
                        _HELD_AUTHORITY_DESCRIPTORS.discard(owned)
                        os.close(owned)


def _retained_bound_pre_root_workspace(
    cwd: str | Path,
    *,
    expected_root_key: tuple[int, int] | None = None,
) -> _RetainedAcquisition[_PreRootWorkspaceBinding]:
    """Return an exact owner for one descriptor-bound workspace root."""

    lease = WorkspaceMutationLockAcquisitionLease()
    return _RetainedAcquisition(
        _bound_pre_root_workspace(
            cwd,
            expected_root_key=expected_root_key,
            acquisition_lease=lease,
        ),
        lease,
    )


def _retained_in_process_lock_admission(
    lock: threading.RLock,
    *,
    nonblocking: bool,
    label: str,
) -> _RetainedAcquisition[None]:
    """Return an owner published from inside one acquired process lock."""

    lease = WorkspaceMutationLockAcquisitionLease()
    return _RetainedAcquisition(
        _in_process_lock_admission(
            lock,
            nonblocking=nonblocking,
            label=label,
            acquisition_lease=lease,
        ),
        lease,
    )


def _retained_external_file_lock(
    *,
    kind: str,
    key: tuple[int, int],
    common_key: tuple[int, int] | None = None,
) -> _RetainedAcquisition[_ExternalFileLockAuthority]:
    """Return an exact owner for one process-plus-kernel external lock."""

    lease = WorkspaceMutationLockAcquisitionLease()
    return _RetainedAcquisition(
        _external_file_lock(
            kind=kind,
            key=key,
            common_key=common_key,
            acquisition_lease=lease,
        ),
        lease,
    )


def _discover_external_common_binding(
    binding: _PreRootWorkspaceBinding,
) -> tuple[Path, tuple[int, int]]:
    common = _workspace_authority_common_dir(
        binding.root,
        root_fd=binding.root_descriptor,
    )
    descriptor, metadata = _open_authority_directory(
        common,
        label="external workspace common authority",
    )
    try:
        _assert_pre_root_workspace_binding(binding)
        _assert_authority_directory_binding(
            common,
            descriptor,
            metadata,
            label="external workspace common authority",
        )
        return common, (metadata.st_dev, metadata.st_ino)
    finally:
        os.close(descriptor)


@contextmanager
def _external_workspace_coordination(
    cwd: str | Path,
    *,
    captured_authority: Mapping[str, object] | None = None,
    acquisition_lease: WorkspaceMutationLockAcquisitionLease | None = None,
) -> Iterator[_ExternalWorkspaceCoordination]:
    """Hold common then exact-root locks outside the checkout for all writes."""

    creator_pid = os.getpid()
    expected_root_key: tuple[int, int] | None = None
    if captured_authority is None:
        captured_common: tuple[Path, tuple[int, int]] | None = None
    else:
        expected_root_key = _validated_external_identity(
            captured_authority.get("root_device"),
            captured_authority.get("root_inode"),
            label="captured external workspace root",
        )
        common_dir_value = captured_authority.get("common_dir")
        if not isinstance(common_dir_value, str):
            raise MutationJournalError(
                "captured external workspace common path is malformed"
            )
        common_dir = _lexical_workspace_path(common_dir_value)
        if Path(common_dir_value) != common_dir:
            raise MutationJournalError(
                "captured external workspace common path is noncanonical"
            )
        captured_common = (
            common_dir,
            _validated_external_identity(
                captured_authority.get("common_device"),
                captured_authority.get("common_inode"),
                label="captured external workspace common",
            ),
        )

    with _RetainedAcquisitionOwnerChain() as authority_release:
        binding = authority_release.enter_context(
            _retained_bound_pre_root_workspace(
                cwd,
                expected_root_key=expected_root_key,
            )
        )
        common_dir, common_key = (
            _discover_external_common_binding(binding)
            if captured_common is None
            else captured_common
        )
        root_key = (
            binding.root_metadata.st_dev,
            binding.root_metadata.st_ino,
        )
        common_lock = authority_release.enter_context(
            _retained_external_file_lock(
                kind="common",
                key=common_key,
            )
        )
        _assert_pre_root_workspace_binding(binding)
        root_lock = authority_release.enter_context(
            _retained_external_file_lock(
                kind="root",
                key=root_key,
                common_key=common_key,
            )
        )
        _assert_pre_root_workspace_binding(binding)
        authority = _ExternalWorkspaceCoordination(
            binding=binding,
            common_dir=common_dir,
            common_key=common_key,
            common_lock=common_lock,
            root_key=root_key,
            root_lock=root_lock,
            owner_pid=os.getpid(),
        )
        authorities = getattr(
            _LOCK_STATE,
            "external_workspace_authorities",
            [],
        )
        authorities.append(authority)
        _LOCK_STATE.external_workspace_authorities = authorities
        try:
            if captured_authority is None:
                observed = _discover_external_common_binding(binding)
                if observed != (common_dir, common_key):
                    raise MutationJournalError(
                        "workspace common authority changed during "
                        "external coordination"
                    )
            _assert_external_workspace_coordination(authority)
            if acquisition_lease is not None:
                acquisition_lease._publish()
            try:
                yield authority
            finally:
                if acquisition_lease is not None:
                    acquisition_lease._begin_settlement()
            if os.getpid() == creator_pid:
                _assert_external_workspace_coordination(authority)
        finally:
            if os.getpid() == creator_pid:
                for index in range(len(authorities) - 1, -1, -1):
                    try:
                        candidate = authorities[index]
                    except IndexError:
                        # A dropped owner of this thread was released by a
                        # garbage collection after the length was read and
                        # removed its own entry.  Entries only move to lower
                        # indexes, so this downward walk still reaches the
                        # entry of this owner.
                        continue
                    if candidate is authority:
                        authorities.pop(index)
                        break


def _retained_external_workspace_coordination(
    cwd: str | Path,
    *,
    captured_authority: Mapping[str, object] | None = None,
) -> _RetainedAcquisition[_ExternalWorkspaceCoordination]:
    """Return a source-published owner for complete external coordination."""

    lease = WorkspaceMutationLockAcquisitionLease()
    return _RetainedAcquisition(
        _external_workspace_coordination(
            cwd,
            captured_authority=captured_authority,
            acquisition_lease=lease,
        ),
        lease,
    )


def _assert_external_workspace_coordination(
    authority: _ExternalWorkspaceCoordination,
) -> None:
    if authority.owner_pid != os.getpid():
        raise MutationJournalError(
            "external workspace coordination belongs to another process"
        )
    _assert_pre_root_workspace_binding(authority.binding)
    _assert_external_file_lock(authority.common_lock)
    _assert_external_file_lock(authority.root_lock)
    common_held = getattr(_LOCK_STATE, "external_common_held", {}).get(
        authority.common_key
    )
    root_held = getattr(_LOCK_STATE, "external_root_held", {}).get(
        authority.root_key
    )
    if (
        common_held is None
        or not common_held[0]
        or common_held[1] is not authority.common_lock
        or root_held is None
        or not root_held[0]
        or root_held[1] is not authority.root_lock
        or root_held[2] != authority.common_key
    ):
        raise MutationJournalError(
            "external workspace coordination is not held by this thread"
        )


def _active_external_workspace_coordination(
    cwd: str | Path,
) -> _ExternalWorkspaceCoordination | None:
    lexical = _lexical_workspace_path(cwd)
    # A reversed walk of the list itself ends early when a released owner's
    # entry leaves it, before the entry of a live owner is reached.
    for authority in reversed(tuple(getattr(
        _LOCK_STATE,
        "external_workspace_authorities",
        (),
    ))):
        if authority.owner_pid != os.getpid():
            continue
        if lexical == authority.binding.root:
            return authority
        try:
            current = os.stat(lexical, follow_symlinks=True)
        except OSError:
            continue
        if (current.st_dev, current.st_ino) == authority.root_key:
            return authority
    return None


def _active_workspace_mutation_authority(
    cwd: str | Path,
) -> _WorkspaceMutationAuthority | None:
    """Find this thread's grant before resolving a potentially swapped path."""

    authorities = getattr(_LOCK_STATE, "authorities", {})
    lexical = _lexical_workspace_path(cwd)
    authority = authorities.get(lexical)
    if authority is None:
        try:
            resolved = Path(cwd).resolve(strict=True)
        except (OSError, RuntimeError):
            return None
        authority = authorities.get(resolved)
    if authority is None or authority.owner_pid != os.getpid():
        return None
    return authority


def _assert_workspace_mutation_authority(
    cwd: str | Path,
) -> _WorkspaceMutationAuthority:
    """Prove the caller still targets its exact held checkout and lock."""

    authority = _active_workspace_mutation_authority(cwd)
    if authority is None:
        raise MutationJournalError(
            "workspace mutation authority is not held by this thread"
        )
    external = _active_external_workspace_coordination(cwd)
    if external is None:
        raise MutationJournalError(
            "workspace mutation authority lost external coordination"
        )
    _assert_external_workspace_coordination(external)
    if (
        authority.external_common_key != external.common_key
        or authority.external_root_key != external.root_key
    ):
        raise MutationJournalError(
            "workspace mutation authority conflicts with external coordination"
        )
    _assert_authority_directory_binding(
        authority.root,
        authority.root_descriptor,
        authority.root_metadata,
        label="workspace authority root",
    )
    _assert_authority_directory_binding(
        authority.common_dir,
        authority.common_descriptor,
        authority.common_metadata,
        label="workspace authority common dir",
    )
    _assert_authority_directory_binding(
        authority.git_common_dir,
        authority.git_common_descriptor,
        authority.git_common_metadata,
        label="workspace Git common dir",
    )
    _assert_authority_directory_binding(
        authority.git_dir,
        authority.git_dir_descriptor,
        authority.git_dir_metadata,
        label="workspace Git dir",
    )
    _assert_workspace_lock_entry(
        authority.common_descriptor,
        authority.lock_descriptor,
        authority.lock_metadata,
    )
    _assert_bound_git_discovery(authority)
    rediscovered = _workspace_authority_common_dir(
        authority.root,
        root_fd=authority.root_descriptor,
    )
    if rediscovered != authority.common_dir:
        raise MutationJournalError(
            "workspace mutation authority changed after lock acquisition"
        )
    _assert_authority_directory_binding(
        authority.root,
        authority.root_descriptor,
        authority.root_metadata,
        label="workspace authority root",
    )
    _assert_authority_directory_binding(
        authority.common_dir,
        authority.common_descriptor,
        authority.common_metadata,
        label="workspace authority common dir",
    )
    _assert_authority_directory_binding(
        authority.git_common_dir,
        authority.git_common_descriptor,
        authority.git_common_metadata,
        label="workspace Git common dir",
    )
    _assert_authority_directory_binding(
        authority.git_dir,
        authority.git_dir_descriptor,
        authority.git_dir_metadata,
        label="workspace Git dir",
    )
    _assert_workspace_lock_entry(
        authority.common_descriptor,
        authority.lock_descriptor,
        authority.lock_metadata,
    )
    _assert_bound_git_discovery(authority)
    return authority


def _workspace_lock_order_key(
    lock_key: tuple[Path, int, int],
) -> tuple[int, int]:
    """Return the identity-only order shared by all workspace lock layers."""

    return _validated_external_identity(
        lock_key[1],
        lock_key[2],
        label="workspace lock",
    )


def _assert_reentrant_workspace_mutation_authority(
    authority: _WorkspaceMutationAuthority,
    external: _ExternalWorkspaceCoordination,
) -> None:
    """Reprove already-held descriptors without traversing a chmod-000 root."""

    _assert_external_workspace_coordination(external)
    if (
        authority.owner_pid != os.getpid()
        or authority.external_common_key != external.common_key
        or authority.external_root_key != external.root_key
    ):
        raise MutationJournalError(
            "reentrant workspace authority conflicts with external coordination"
        )
    for metadata, descriptor, label in (
        (authority.root_metadata, authority.root_descriptor, "root"),
        (authority.common_metadata, authority.common_descriptor, "common"),
        (
            authority.git_common_metadata,
            authority.git_common_descriptor,
            "Git common",
        ),
        (authority.git_dir_metadata, authority.git_dir_descriptor, "Git dir"),
    ):
        try:
            observed = os.fstat(descriptor)
        except OSError as exc:
            raise MutationJournalError(
                f"cannot revalidate held {label} authority: {exc}"
            ) from exc
        if (
            not stat.S_ISDIR(observed.st_mode)
            or (observed.st_dev, observed.st_ino)
            != (metadata.st_dev, metadata.st_ino)
        ):
            raise MutationJournalError(
                f"held {label} authority changed identity"
            )
    try:
        observed_lock = os.fstat(authority.lock_descriptor)
    except OSError as exc:
        raise MutationJournalError(
            f"cannot revalidate held workspace lock: {exc}"
        ) from exc
    if (
        not stat.S_ISREG(observed_lock.st_mode)
        or observed_lock.st_nlink != 1
        or (observed_lock.st_dev, observed_lock.st_ino)
        != (authority.lock_metadata.st_dev, authority.lock_metadata.st_ino)
    ):
        raise MutationJournalError("held workspace lock changed identity")


@contextmanager
def _canonical_workspace_mutation_lock(
    cwd: str | Path,
    *,
    acquisition_lease: WorkspaceMutationLockAcquisitionLease | None = None,
) -> Iterator[_WorkspaceMutationAuthority]:
    """Serialize Crucible mutation workflows targeting one Git worktree.

    The kernel releases ``flock`` automatically on every process-death mode,
    including SIGKILL.  The next process acquires the lock before running the
    journal reaper, so recovery cannot race a still-live Crucible writer.
    Human/editor writes do not honor this advisory lock and remain outside the
    transaction guarantee.
    """

    import fcntl

    creator_pid = os.getpid()
    _reject_git_redirect_env()
    external = _active_external_workspace_coordination(cwd)
    if external is None:
        raise MutationJournalError(
            "canonical workspace lock requires external coordination"
        )
    _assert_external_workspace_coordination(external)
    lexical_root = _lexical_workspace_path(cwd)
    active = _active_workspace_mutation_authority(cwd)
    if active is not None:
        _assert_reentrant_workspace_mutation_authority(active, external)
        with _IN_PROCESS_LOCKS_GUARD:
            process_lock = _IN_PROCESS_LOCKS.get(active.lock_key)
        if process_lock is None:
            raise MutationJournalError(
                "workspace mutation authority lost its process lock"
            )
        with _RetainedAcquisitionOwnerChain() as process_release:
            process_release.enter_context(
                _retained_in_process_lock_admission(
                    process_lock,
                    nonblocking=False,
                    label="workspace mutation lock",
                )
            )
            held = getattr(_LOCK_STATE, "held", {})
            depth, descriptor, owner_pid = held.get(
                active.lock_key,
                (0, None, None),
            )
            if (
                not depth
                or owner_pid != os.getpid()
                or descriptor != active.lock_descriptor
            ):
                raise MutationJournalError(
                    "workspace mutation authority is inconsistent"
                )
            held[active.lock_key] = (depth + 1, descriptor, owner_pid)
            _LOCK_STATE.held = held
            try:
                if acquisition_lease is not None:
                    acquisition_lease._publish()
                yield active
            finally:
                if acquisition_lease is not None:
                    acquisition_lease._begin_settlement()
                if os.getpid() == creator_pid:
                    held[active.lock_key] = (depth, descriptor, owner_pid)
        return

    root = Path(cwd).resolve(strict=True)
    root_fd, root_metadata = _open_authority_directory(
        root,
        label="workspace authority root",
    )
    _HELD_AUTHORITY_DESCRIPTORS.add(root_fd)
    try:
        common_dir = _workspace_authority_common_dir(root, root_fd=root_fd)
        _assert_authority_directory_binding(
            root,
            root_fd,
            root_metadata,
            label="workspace authority root",
        )
        common_fd, common_metadata = _open_authority_directory(
            common_dir,
            label="workspace authority common dir",
        )
        _HELD_AUTHORITY_DESCRIPTORS.add(common_fd)
        git_common_fd: int | None = None
        git_dir_fd: int | None = None
        try:
            bound_root = Path(_authority_descriptor_cwd(root_fd))
            (
                git_dir,
                git_dir_fd,
                git_dir_metadata,
                git_common_dir,
                git_common_fd,
                git_common_metadata,
            ) = _discover_bound_git_authority(root, root_fd)
            assert git_dir_fd is not None
            assert git_common_fd is not None
            _HELD_AUTHORITY_DESCRIPTORS.add(git_dir_fd)
            _HELD_AUTHORITY_DESCRIPTORS.add(git_common_fd)
            _assert_authority_directory_binding(
                common_dir,
                common_fd,
                common_metadata,
                label="workspace authority common dir",
            )
            lock_key = (
                common_metadata.st_dev,
                common_metadata.st_ino,
            )
            held_before_acquire = getattr(_LOCK_STATE, "held", {})
            held_independent_keys = [
                key
                for key, (depth, _descriptor, owner_pid) in tuple(
                    held_before_acquire.items()
                )
                if depth and owner_pid == os.getpid() and key != lock_key
            ]
            nested_independent_lock = bool(held_independent_keys)
            with _IN_PROCESS_LOCKS_GUARD:
                process_lock = _IN_PROCESS_LOCKS.setdefault(
                    lock_key,
                    threading.RLock(),
                )
            with _RetainedAcquisitionOwnerChain() as process_release:
                process_release.enter_context(
                    _retained_in_process_lock_admission(
                        process_lock,
                        nonblocking=nested_independent_lock,
                        label="workspace mutation lock",
                    )
                )
                held = getattr(_LOCK_STATE, "held", {})
                depth, descriptor, owner_pid = held.get(
                    lock_key,
                    (0, None, None),
                )
                if depth and owner_pid == os.getpid():
                    assert descriptor is not None
                    _assert_authority_directory_binding(
                        root,
                        root_fd,
                        root_metadata,
                        label="workspace authority root",
                    )
                    _assert_authority_directory_binding(
                        common_dir,
                        common_fd,
                        common_metadata,
                        label="workspace authority common dir",
                    )
                    _assert_workspace_lock_entry(
                        common_fd,
                        descriptor,
                        os.fstat(descriptor),
                    )
                    authority = _WorkspaceMutationAuthority(
                        root=root,
                        root_descriptor=root_fd,
                        root_metadata=root_metadata,
                        common_dir=common_dir,
                        common_descriptor=common_fd,
                        common_metadata=common_metadata,
                        git_common_dir=git_common_dir,
                        git_common_descriptor=git_common_fd,
                        git_common_metadata=git_common_metadata,
                        git_dir=git_dir,
                        git_dir_descriptor=git_dir_fd,
                        git_dir_metadata=git_dir_metadata,
                        lock_descriptor=descriptor,
                        lock_metadata=os.fstat(descriptor),
                        lock_key=lock_key,
                        external_common_key=external.common_key,
                        external_root_key=external.root_key,
                        owner_pid=owner_pid,
                    )
                    authorities = getattr(_LOCK_STATE, "authorities", {})
                    if any(
                        key in authorities
                        and authorities[key] is not authority
                        for key in (lexical_root, root, bound_root)
                    ):
                        raise MutationJournalError(
                            "workspace path already has different mutation "
                            "authority"
                        )
                    authorities[lexical_root] = authority
                    authorities[root] = authority
                    authorities[bound_root] = authority
                    _LOCK_STATE.authorities = authorities
                    held[lock_key] = (depth + 1, descriptor, owner_pid)
                    _LOCK_STATE.held = held
                    try:
                        _assert_workspace_mutation_authority(root)
                        if acquisition_lease is not None:
                            acquisition_lease._publish()
                        yield authority
                    finally:
                        if acquisition_lease is not None:
                            acquisition_lease._begin_settlement()
                        if os.getpid() == creator_pid:
                            held[lock_key] = (depth, descriptor, owner_pid)
                            for key, candidate in tuple(authorities.items()):
                                if candidate is authority:
                                    authorities.pop(key, None)
                    return
                if depth:
                    # A fork inherits thread-local Python state but not a
                    # logical re-entrant grant. Acquire the kernel lock anew.
                    if descriptor is not None:
                        try:
                            os.close(descriptor)
                        except OSError:
                            pass
                        _HELD_LOCK_DESCRIPTORS.discard(descriptor)
                    held.pop(lock_key, None)

                descriptor, lock_metadata = _open_workspace_lock_entry(
                    common_fd,
                )
                _HELD_LOCK_DESCRIPTORS.add(descriptor)
                locked = False
                try:
                    try:
                        fcntl.flock(
                            descriptor,
                            fcntl.LOCK_EX
                            | (
                                fcntl.LOCK_NB
                                if nested_independent_lock
                                else 0
                            ),
                        )
                    except OSError as exc:
                        if nested_independent_lock and exc.errno in {
                            errno.EACCES,
                            errno.EAGAIN,
                        }:
                            raise MutationJournalError(
                                "workspace mutation lock is busy; refusing "
                                "deadlock-prone nested acquisition"
                            ) from exc
                        raise
                    locked = True
                    _assert_workspace_lock_entry(
                        common_fd,
                        descriptor,
                        lock_metadata,
                    )
                    _assert_authority_directory_binding(
                        root,
                        root_fd,
                        root_metadata,
                        label="workspace authority root",
                    )
                    _assert_authority_directory_binding(
                        common_dir,
                        common_fd,
                        common_metadata,
                        label="workspace authority common dir",
                    )
                    rediscovered = _workspace_authority_common_dir(
                        root,
                        root_fd=root_fd,
                    )
                    if rediscovered != common_dir:
                        raise MutationJournalError(
                            "workspace lock authority changed during acquisition"
                        )
                    _assert_authority_directory_binding(
                        root,
                        root_fd,
                        root_metadata,
                        label="workspace authority root",
                    )
                    _assert_authority_directory_binding(
                        common_dir,
                        common_fd,
                        common_metadata,
                        label="workspace authority common dir",
                    )
                    _assert_workspace_lock_entry(
                        common_fd,
                        descriptor,
                        lock_metadata,
                    )
                    held[lock_key] = (1, descriptor, os.getpid())
                    _LOCK_STATE.held = held
                    authority = _WorkspaceMutationAuthority(
                        root=root,
                        root_descriptor=root_fd,
                        root_metadata=root_metadata,
                        common_dir=common_dir,
                        common_descriptor=common_fd,
                        common_metadata=common_metadata,
                        git_common_dir=git_common_dir,
                        git_common_descriptor=git_common_fd,
                        git_common_metadata=git_common_metadata,
                        git_dir=git_dir,
                        git_dir_descriptor=git_dir_fd,
                        git_dir_metadata=git_dir_metadata,
                        lock_descriptor=descriptor,
                        lock_metadata=lock_metadata,
                        lock_key=lock_key,
                        external_common_key=external.common_key,
                        external_root_key=external.root_key,
                        owner_pid=os.getpid(),
                    )
                    authorities = getattr(_LOCK_STATE, "authorities", {})
                    if any(
                        key in authorities
                        for key in (lexical_root, root, bound_root)
                    ):
                        raise MutationJournalError(
                            "workspace path already has mutation authority"
                        )
                    authorities[lexical_root] = authority
                    authorities[root] = authority
                    authorities[bound_root] = authority
                    _LOCK_STATE.authorities = authorities
                    try:
                        _assert_workspace_mutation_authority(root)
                        if acquisition_lease is not None:
                            acquisition_lease._publish()
                        yield authority
                    finally:
                        if acquisition_lease is not None:
                            acquisition_lease._begin_settlement()
                        if os.getpid() == creator_pid:
                            held.pop(lock_key, None)
                            for key, candidate in tuple(authorities.items()):
                                if candidate is authority:
                                    authorities.pop(key, None)
                finally:
                    if os.getpid() == creator_pid:
                        if locked:
                            fcntl.flock(descriptor, fcntl.LOCK_UN)
                        _HELD_LOCK_DESCRIPTORS.discard(descriptor)
                        os.close(descriptor)
        finally:
            if os.getpid() == creator_pid:
                if git_dir_fd is not None:
                    _HELD_AUTHORITY_DESCRIPTORS.discard(git_dir_fd)
                    os.close(git_dir_fd)
                if git_common_fd is not None:
                    _HELD_AUTHORITY_DESCRIPTORS.discard(git_common_fd)
                    os.close(git_common_fd)
                _HELD_AUTHORITY_DESCRIPTORS.discard(common_fd)
                os.close(common_fd)
    finally:
        if os.getpid() == creator_pid:
            _HELD_AUTHORITY_DESCRIPTORS.discard(root_fd)
            os.close(root_fd)


def _retained_canonical_workspace_mutation_lock(
    cwd: str | Path,
) -> RetainedRecoveryWorkspaceMutationLock:
    """Return an exact owner published at the canonical authority yield."""

    lease = WorkspaceMutationLockAcquisitionLease()
    return RetainedRecoveryWorkspaceMutationLock(
        _canonical_workspace_mutation_lock(
            cwd,
            acquisition_lease=lease,
        ),
        lease,
    )


@contextmanager
def workspace_mutation_lock(
    cwd: str | Path,
    *,
    acquisition_lease: WorkspaceMutationLockAcquisitionLease | None = None,
) -> Iterator[_WorkspaceMutationAuthority]:
    """Hold external common/root coordination and the canonical Git lock."""

    active_external = _active_external_workspace_coordination(cwd)
    if active_external is not None:
        _assert_external_workspace_coordination(active_external)
        with _RetainedAcquisitionOwnerChain() as authority_release:
            authority = authority_release.enter_context(
                _retained_canonical_workspace_mutation_lock(cwd)
            )
            if acquisition_lease is not None:
                acquisition_lease._publish()
            try:
                yield authority
            finally:
                if acquisition_lease is not None:
                    acquisition_lease._begin_settlement()
        return
    with _RetainedAcquisitionOwnerChain() as authority_release:
        external = authority_release.enter_context(
            _retained_external_workspace_coordination(cwd)
        )
        authority = authority_release.enter_context(
            _retained_canonical_workspace_mutation_lock(
                external.binding.root
            )
        )
        if (
            (authority.common_metadata.st_dev,
             authority.common_metadata.st_ino)
            != external.common_key
            or (authority.root_metadata.st_dev, authority.root_metadata.st_ino)
            != external.root_key
        ):
            raise MutationJournalError(
                "canonical workspace authority differs from external "
                "coordination"
            )
        if acquisition_lease is not None:
            acquisition_lease._publish()
        try:
            yield authority
        finally:
            if acquisition_lease is not None:
                acquisition_lease._begin_settlement()


def _retained_workspace_mutation_lock(
    cwd: str | Path,
) -> RetainedRecoveryWorkspaceMutationLock:
    """Return an owner published only after the complete lock chain is live."""

    lease = WorkspaceMutationLockAcquisitionLease()
    return RetainedRecoveryWorkspaceMutationLock(
        workspace_mutation_lock(cwd, acquisition_lease=lease),
        lease,
    )


def retained_nested_workspace_mutation_lock(
    cwd: str | Path,
) -> RetainedRecoveryWorkspaceMutationLock:
    """Retain a reentrant canonical lock under live outer coordination.

    Nested Tier/Handoff children already run beneath the parent's external
    checkout coordination.  Bypass the plain aggregate generator so the
    acquisition lease is published at the canonical source's actual yield;
    this closes the callee-to-caller interruption window without pretending
    the helper is safe for an independently coordinated root acquisition.
    """

    external = _active_external_workspace_coordination(cwd)
    if external is None:
        raise MutationJournalError(
            "retained nested workspace lock requires live external "
            "coordination"
        )
    _assert_external_workspace_coordination(external)
    return _retained_canonical_workspace_mutation_lock(cwd)


def _recovery_admission_inventory(
    corpus: "Corpus",
    workspace: Path,
) -> tuple[
    tuple[WorkspaceMutationJournal, ...],
    tuple[_TerminalCleanupReceipt, ...],
    dict[str, WorkspaceMutationJournal],
    tuple[object, ...],
    WorkspaceMutationJournal | None,
]:
    """Capture the complete Corpus authority used for pre-root admission."""

    with _RetainedAcquisitionOwnerChain() as binding_release:
        requested_binding = binding_release.enter_context(
            _retained_bound_pre_root_workspace(workspace)
        )
        requested_root_key = (
            requested_binding.root_metadata.st_dev,
            requested_binding.root_metadata.st_ino,
        )
    receipts: list[_TerminalCleanupReceipt] = []
    all_journals = discover_mutation_journals(
        corpus,
        _terminal_receipts=receipts,
    )
    if any(
        not isinstance(receipt, _TerminalCleanupReceipt)
        for receipt in receipts
    ):
        raise MutationJournalError(
            "writer epoch recovery admission receipt inventory is malformed"
        )
    receipt_journals = {
        receipt.transaction_id: _journal_from_terminal_cleanup_receipt(receipt)
        for receipt in receipts
    }
    all_members = (*all_journals, *receipt_journals.values())

    def captured_root_key(
        journal: WorkspaceMutationJournal,
    ) -> tuple[int, int] | None:
        expected = journal._manifest.get("authority_lock")
        if not isinstance(expected, Mapping):
            return None
        try:
            return _validated_external_identity(
                expected.get("root_device"),
                expected.get("root_inode"),
                label="recovery inventory root",
            )
        except MutationJournalError:
            return None

    related_ids = {
        journal.transaction_id
        for journal in all_members
        if captured_root_key(journal) == requested_root_key
    }
    changed = True
    while changed:
        changed = False
        for journal in all_members:
            family = {
                str(transaction_id)
                for transaction_id in journal._manifest.get(
                    "registry_transaction_family",
                    (),
                )
            }
            if related_ids.intersection(family) and not family.issubset(
                related_ids
            ):
                related_ids.update(family)
                changed = True
    journals = tuple(
        journal
        for journal in all_journals
        if journal.transaction_id in related_ids
    )
    receipts = [
        receipt
        for receipt in receipts
        if receipt.transaction_id in related_ids
    ]
    members: dict[str, WorkspaceMutationJournal] = {}
    for journal in journals:
        if journal.transaction_id in members:
            raise MutationJournalError(
                "pre-root recovery inventory contains duplicate transactions"
            )
        members[journal.transaction_id] = journal
    for receipt in receipts:
        journal = receipt_journals[receipt.transaction_id]
        if journal.transaction_id in members:
            raise MutationJournalError(
                "pre-root recovery inventory duplicates a receipt transaction"
            )
        members[journal.transaction_id] = journal

    def binding_record(
        journal: WorkspaceMutationJournal,
    ) -> tuple[object, ...]:
        binding = journal._discovery_binding
        return (
            journal.transaction_id,
            str(journal.journal_dir),
            hashlib.sha256(json.dumps(
                journal._manifest,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")).hexdigest(),
            None if binding is None else (
                str(binding.spec_dir),
                binding.spec_device,
                binding.spec_inode,
                tuple(
                    (item.name, item.device, item.inode)
                    for item in binding.components
                ),
                binding.manifest_metadata,
                binding.artifact_inventory,
            ),
        )

    fingerprint: tuple[object, ...] = (
        tuple(binding_record(journal) for journal in journals),
        tuple(
            (
                receipt.transaction_id,
                str(receipt.parent_path),
                receipt.parent_device,
                receipt.parent_inode,
                receipt.receipt_name,
                hashlib.sha256(receipt.receipt_payload).hexdigest(),
                receipt.journal_device,
                receipt.journal_inode,
                receipt.target_name,
            )
            for receipt in receipts
        ),
    )

    root_members = tuple(
        member
        for member in members.values()
        if captured_root_key(member) == requested_root_key
    )
    representative = root_members[0] if root_members else None
    if representative is not None:
        signatures: set[tuple[object, ...]] = set()
        for member in root_members:
            expected = member._manifest.get("authority_lock")
            directory_modes = member._manifest.get("directory_modes")
            if not isinstance(expected, Mapping) or not isinstance(
                directory_modes,
                Mapping,
            ):
                raise MutationJournalError(
                    "pre-root recovery member lacks captured authority"
                )
            signatures.add((
                expected.get("root_device"),
                expected.get("root_inode"),
                expected.get("root_mode"),
                expected.get("common_dir"),
                expected.get("common_device"),
                expected.get("common_inode"),
                directory_modes.get("."),
            ))
        if len(signatures) != 1:
            raise MutationJournalError(
                "pre-root recovery members disagree on workspace authority"
            )
    return (
        journals,
        tuple(receipts),
        members,
        fingerprint,
        representative,
    )


@contextmanager
def _recovery_workspace_mutation_lock(
    corpus: "Corpus",
    cwd: str | Path,
    acquisition_lease: WorkspaceMutationLockAcquisitionLease,
) -> Iterator[_WorkspaceMutationAuthority]:
    """Admit startup recovery before touching an inaccessible checkout root."""

    workspace = _lexical_workspace_path(cwd)
    (
        _initial_journals,
        _initial_receipts,
        _initial_members,
        initial_fingerprint,
        initial_representative,
    ) = _recovery_admission_inventory(corpus, workspace)
    if initial_representative is None:
        with _RetainedAcquisitionOwnerChain() as workspace_release:
            authority = workspace_release.enter_context(
                _retained_workspace_mutation_lock(workspace)
            )
            try:
                acquisition_lease._publish()
                yield authority
            finally:
                acquisition_lease._begin_settlement()
        return

    expected = initial_representative._manifest.get("authority_lock")
    assert isinstance(expected, Mapping)
    with _RetainedAcquisitionOwnerChain() as external_release:
        external_release.enter_context(
            _retained_external_workspace_coordination(
                workspace,
                captured_authority=expected,
            )
        )
        (
            _locked_journals,
            _locked_receipts,
            locked_members,
            locked_fingerprint,
            representative,
        ) = _recovery_admission_inventory(corpus, workspace)
        if (
            locked_fingerprint != initial_fingerprint
            or representative is None
        ):
            raise MutationJournalError(
                "mutation journal inventory changed before pre-root admission"
            )
        previous_members = getattr(
            _LOCK_STATE,
            "writer_epoch_recovery_members",
            None,
        )
        _LOCK_STATE.writer_epoch_recovery_members = locked_members
        try:
            for member in locked_members.values():
                member._require_writer_epoch_quiescence(
                    frontier="pre-root startup recovery admission"
                )
        finally:
            if previous_members is None:
                try:
                    del _LOCK_STATE.writer_epoch_recovery_members
                except AttributeError:
                    pass
            else:
                _LOCK_STATE.writer_epoch_recovery_members = previous_members
        prepared: _PreparedWorkspaceRootAccess | None = None
        admitted = False
        try:
            prepared = representative._prepare_workspace_root_access()
            representative._assert_external_common_authority()
            with _RetainedAcquisitionOwnerChain() as workspace_release:
                authority = workspace_release.enter_context(
                    _retained_workspace_mutation_lock(workspace)
                )
                admitted = True
                try:
                    acquisition_lease._publish()
                    yield authority
                finally:
                    acquisition_lease._begin_settlement()
        finally:
            if not admitted:
                representative._revert_workspace_root_access(prepared)
            else:
                representative._settle_prepared_workspace_root_access(
                    prepared
                )


def recovery_workspace_mutation_lock(
    corpus: "Corpus",
    cwd: str | Path,
) -> RetainedRecoveryWorkspaceMutationLock:
    """Return a recovery lock with source-published retained acquisition.

    Mutation workflows must retain ``result.retry_cleanup`` before invoking
    ``result.__enter__``; ordinary ``with`` syntax alone cannot cover its own
    post-entry return bytecode against asynchronous main-thread interruption.
    """

    acquisition_lease = WorkspaceMutationLockAcquisitionLease()
    context = _recovery_workspace_mutation_lock(
        corpus,
        cwd,
        acquisition_lease,
    )
    return RetainedRecoveryWorkspaceMutationLock(
        context,
        acquisition_lease,
    )


def _bound_git_subprocess_authority(
    cwd: Path,
    **overrides: str,
) -> tuple[dict[str, str], tuple[int, ...]]:
    """Bind Git to the held worktree/admin/common directory descriptors."""

    authority = _active_workspace_mutation_authority(cwd)
    if authority is None:
        return _sanitized_git_env(**overrides), ()
    descriptors = tuple(dict.fromkeys((
        authority.root_descriptor,
        authority.git_dir_descriptor,
        authority.git_common_descriptor,
    )))
    return (
        _sanitized_git_env(
            GIT_WORK_TREE=_authority_descriptor_cwd(
                authority.root_descriptor
            ),
            GIT_DIR=_authority_descriptor_cwd(
                authority.git_dir_descriptor
            ),
            GIT_COMMON_DIR=_authority_descriptor_cwd(
                authority.git_common_descriptor
            ),
            **overrides,
        ),
        descriptors,
    )


def _run_bound_git_process(
    cwd: Path,
    argv: Iterable[str],
    *,
    input_bytes: bytes | None = None,
    timeout_s: float | None = None,
    **overrides: str,
) -> subprocess.CompletedProcess[bytes]:
    """Run a Git process against the exact held worktree/admin authority."""

    env, authority_fds = _bound_git_subprocess_authority(cwd, **overrides)
    try:
        return subprocess.run(
            tuple(argv),
            cwd=cwd,
            env=env,
            input=input_bytes,
            capture_output=True,
            check=False,
            timeout=timeout_s,
            pass_fds=authority_fds,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise MutationJournalError(
            f"Git subprocess could not run in {cwd}: {exc}"
        ) from exc


def _run_bound_git_bounded_stdout(
    cwd: Path,
    argv: Iterable[str],
    *,
    max_stdout_bytes: int,
    label: str,
    timeout_s: float = 300.0,
    **overrides: str,
) -> bytes:
    """Stream Git output and terminate before it can exceed its byte proof."""

    if (
        not isinstance(max_stdout_bytes, int)
        or isinstance(max_stdout_bytes, bool)
        or not 0 <= max_stdout_bytes
        <= _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_BYTES
    ):
        raise MutationJournalError(f"invalid Git byte ceiling for {label}")
    if not isinstance(timeout_s, (int, float)) or not 0 < timeout_s <= 3600:
        raise MutationJournalError(f"invalid Git timeout for {label}")
    env, authority_fds = _bound_git_subprocess_authority(cwd, **overrides)
    process: subprocess.Popen[bytes] | None = None
    selector = selectors.DefaultSelector()
    stdout = bytearray()
    stderr = bytearray()
    stderr_truncated = False
    try:
        process = subprocess.Popen(
            tuple(argv),
            cwd=cwd,
            env=env,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            pass_fds=authority_fds,
        )
        assert process.stdout is not None
        assert process.stderr is not None
        selector.register(process.stdout, selectors.EVENT_READ, "stdout")
        selector.register(process.stderr, selectors.EVENT_READ, "stderr")
        deadline = time.monotonic() + float(timeout_s)
        while selector.get_map():
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                process.kill()
                raise MutationJournalError(
                    f"{label} exceeded its {timeout_s:g}s timeout"
                )
            ready = selector.select(remaining)
            if not ready:
                process.kill()
                raise MutationJournalError(
                    f"{label} exceeded its {timeout_s:g}s timeout"
                )
            for key, _events in ready:
                chunk = os.read(key.fd, 1024 * 1024)
                if not chunk:
                    selector.unregister(key.fileobj)
                    continue
                if key.data == "stdout":
                    if len(stdout) + len(chunk) > max_stdout_bytes:
                        process.kill()
                        raise MutationJournalError(
                            f"{label} exceeds its Git output byte ceiling"
                        )
                    stdout.extend(chunk)
                elif len(stderr) < _CONTROL_FILE_MAX_BYTES:
                    remaining = _CONTROL_FILE_MAX_BYTES - len(stderr)
                    stderr.extend(chunk[:remaining])
                    stderr_truncated = stderr_truncated or len(chunk) > remaining
                else:
                    stderr_truncated = True
        returncode = process.wait()
        if returncode != 0:
            detail = stderr.decode("utf-8", errors="replace").strip()
            if stderr_truncated:
                detail += " [stderr truncated]"
            raise MutationJournalError(
                f"{label} failed with exit {returncode}: {detail}"
            )
        return bytes(stdout)
    except MutationJournalError:
        raise
    except (OSError, subprocess.SubprocessError) as exc:
        raise MutationJournalError(f"cannot run {label}: {exc}") from exc
    finally:
        selector.close()
        if process is not None:
            if process.poll() is None:
                process.kill()
            process.wait()
            if process.stdout is not None:
                process.stdout.close()
            if process.stderr is not None:
                process.stderr.close()


def _git(
    cwd: Path,
    *args: str,
    check: bool = True,
    timeout_s: float | None = None,
    pass_fds: tuple[int, ...] = (),
) -> bytes:
    if pass_fds:
        env = _sanitized_git_env(GIT_OPTIONAL_LOCKS="0")
        authority_fds: tuple[int, ...] = ()
    else:
        env, authority_fds = _bound_git_subprocess_authority(
            cwd,
            GIT_OPTIONAL_LOCKS="0",
        )
    inherited_fds = tuple(dict.fromkeys((*pass_fds, *authority_fds)))
    try:
        result = subprocess.run(
            _git_argv(*args),
            cwd=cwd,
            env=env,
            capture_output=True,
            check=False,
            timeout=timeout_s,
            pass_fds=inherited_fds,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise MutationJournalError(
            f"git {' '.join(args)} could not run in {cwd}: {exc}"
        ) from exc
    if check and result.returncode != 0:
        stderr = result.stderr.decode("utf-8", errors="replace").strip()
        raise MutationJournalError(
            f"git {' '.join(args)} failed in {cwd}: {stderr}"
        )
    return result.stdout


def _git_fsck(
    cwd: Path,
    *args: str,
    check: bool = True,
) -> subprocess.CompletedProcess[bytes]:
    """Run fsck against authoritative objects, not the commit-graph cache.

    History-sanitized shallow checkouts can retain a commit-graph written
    before unreachable ancestors were pruned.  The graph is an acceleration
    cache and its exact physical image is guarded by the journal separately;
    object verification must honor the shallow boundary instead of failing on
    intentionally absent commits named only by that unchanged cache.
    """

    result = _run_bound_git_process(
        cwd,
        _git_argv("-c", "core.commitGraph=false", "fsck", *args),
        GIT_OPTIONAL_LOCKS="0",
    )
    if check and result.returncode != 0:
        diagnostic = b"\n".join((result.stdout, result.stderr)).decode(
            "utf-8", errors="replace"
        ).strip()
        raise MutationJournalError(
            f"git fsck {' '.join(args)} failed in {cwd}: {diagnostic[-1000:]}"
        )
    return result


def _git_config(cwd: Path, key: str, *, boolean: bool = False) -> str | None:
    args = ["git", "config"]
    if boolean:
        args.append("--bool")
    args.extend(("--get", key))
    result = _run_bound_git_process(
        cwd,
        args,
    )
    if result.returncode == 1:
        return None
    if result.returncode != 0:
        raise MutationJournalError(
            f"cannot inspect Git config {key}: "
            + result.stderr.decode("utf-8", errors="replace").strip()
        )
    return result.stdout.decode("utf-8", errors="surrogateescape").rstrip("\r\n")


def _repository_config_names(cwd: Path) -> tuple[str, ...]:
    """Return local/worktree config names without loading includes."""

    result = _run_bound_git_process(
        cwd,
        _git_argv(
            "config",
            "--no-includes",
            "--name-only",
            "--get-regexp",
            ".*",
        ),
    )
    if result.returncode not in {0, 1}:
        raise MutationJournalError(
            "cannot inspect repository Git config names: "
            + result.stderr.decode("utf-8", errors="replace").strip()
        )
    return tuple(
        line.decode("utf-8", errors="surrogateescape")
        for line in result.stdout.splitlines()
        if line
    )


def _reject_git_config_includes(cwd: Path) -> None:
    includes = tuple(
        name
        for name in _repository_config_names(cwd)
        if name.lower().startswith(("include.", "includeif."))
    )
    if includes:
        raise MutationJournalError(
            "external Git config includes are unsupported by exact rollback: "
            f"{includes[0]!r}"
        )


def _reject_repository_filter_config(cwd: Path) -> None:
    configured_filters = tuple(
        name
        for name in _repository_config_names(cwd)
        if re.fullmatch(
            r"filter\..*\.(clean|smudge|process|required)",
            name.lower(),
        )
    )
    if configured_filters:
        raise MutationJournalError(
            "configured Git filter drivers are unsupported by exact mutation "
            f"rollback: {configured_filters[0][:500]}"
        )


def _reject_transforming_checkout(
    cwd: Path,
    *,
    probe_paths: Iterable[str] = (),
) -> tuple[tuple[str, ...], tuple[str, ...]]:
    """Reject unsafe transforms and return transformed/filter path sets.

    Git's built-in text/EOL/ident transforms do not execute external
    code, but a checkout is not necessarily a byte-exact inverse of the
    current worktree image.  Callers bind those paths either to their raw Git
    blob or to a physical journal snapshot before mutation begins.  An active
    but unconfigured ``filter`` attribute is handled as another opaque
    transforming path: journal-owned Git commands suppress global/system
    configuration, repository-local filter drivers are rejected below, and
    the physical checkout image is snapshotted when it differs from the index
    blob.  This supports materialized binary stores without executing their
    external filters.
    """

    if os.name != "nt" and _git_config(cwd, "core.filemode", boolean=True) == "false":
        raise MutationJournalError(
            "core.filemode=false is unsupported by exact mutation rollback"
        )
    autocrlf = _git_config(cwd, "core.autocrlf", boolean=True)
    if autocrlf not in {None, "false"}:
        raise MutationJournalError(
            f"core.autocrlf={autocrlf!r} is unsupported by exact rollback"
        )
    if _git_config(cwd, "core.eol") not in {None, "native"}:
        raise MutationJournalError(
            "non-native core.eol is unsupported by exact mutation rollback"
        )
    if _git_config(cwd, "core.attributesFile") is not None:
        raise MutationJournalError(
            "core.attributesFile is unsupported by exact mutation rollback"
        )
    if _git_config(cwd, "core.trustctime", boolean=True) == "false":
        raise MutationJournalError(
            "core.trustctime=false can hide tracked writes from exact rollback"
        )
    check_stat = _git_config(cwd, "core.checkStat")
    if check_stat is not None and check_stat.lower() == "minimal":
        raise MutationJournalError(
            "core.checkStat=minimal can hide tracked writes from exact rollback"
        )
    if _git_config(cwd, "core.ignoreStat", boolean=True) == "true":
        raise MutationJournalError(
            "core.ignoreStat=true can hide tracked writes from exact rollback"
        )
    if _git_config(cwd, "core.ignoreCase", boolean=True) == "true":
        raise MutationJournalError(
            "core.ignoreCase=true can hide case-distinct worktree writes"
        )
    if _git_config(cwd, "core.precomposeUnicode", boolean=True) == "true":
        raise MutationJournalError(
            "core.precomposeUnicode=true is unsupported by exact rollback"
        )
    fsmonitor = _git_config(cwd, "core.fsmonitor")
    if fsmonitor is not None and fsmonitor.lower() not in {"", "false"}:
        raise MutationJournalError(
            "configured Git fsmonitor is unsupported by exact rollback"
        )

    # Ask Git for the *effective* attributes of every tracked path.  Reading
    # tracked ``.gitattributes`` files is not equivalent: an untracked
    # attribute file is active in the working tree, as are info/system
    # attributes and per-directory precedence rules.  The NUL protocol keeps
    # arbitrary POSIX path bytes unambiguous and ``check-attr`` never invokes
    # a configured content filter.
    tracked_paths = tuple(
        path for path in _git(cwd, "ls-files", "-z").split(b"\0") if path
    )
    checked_paths = tuple(dict.fromkeys((
        *tracked_paths,
        *(os.fsencode(path) for path in probe_paths),
    )))
    if not checked_paths:
        return (), ()
    result = _run_bound_git_process(
        cwd,
        _git_argv("check-attr", "-z", "--all", "--stdin"),
        input_bytes=b"\0".join(checked_paths) + b"\0",
    )
    if result.returncode != 0:
        raise MutationJournalError(
            "cannot inspect effective Git attributes: "
            + result.stderr.decode("utf-8", errors="replace").strip()
        )
    fields = result.stdout.split(b"\0")
    if fields and fields[-1] == b"":
        fields.pop()
    if len(fields) % 3:
        raise MutationJournalError("malformed git check-attr output")
    built_in_transforming = {
        b"crlf",
        b"eol",
        b"ident",
        b"text",
    }
    unsupported_transforming = {b"filter", b"working-tree-encoding"}
    transforming_paths: set[str] = set()
    external_filter_paths: set[str] = set()
    for offset in range(0, len(fields), 3):
        encoded_path, attribute, value = fields[offset:offset + 3]
        normalized_attribute = attribute.lower()
        if normalized_attribute not in (
            built_in_transforming | unsupported_transforming
        ):
            continue
        # ``-text``/``!text`` and equivalent negative forms explicitly turn
        # a transform off.  All other effective values can change the byte
        # image produced by checkout/reset and are outside exact rollback's
        # supported repository shapes.
        if value.lower() in {b"unset", b"unspecified"}:
            continue
        if normalized_attribute == b"filter":
            # With repository-local drivers rejected above and ambient
            # drivers suppressed in _sanitized_git_env(), this attribute is
            # inert for every journal-owned Git command.  Still bind the
            # physical image because the operator checkout may have been
            # materialized by a driver before this transaction began.
            relative = os.fsdecode(encoded_path)
            transforming_paths.add(relative)
            external_filter_paths.add(relative)
            continue
        if normalized_attribute in unsupported_transforming:
            raise MutationJournalError(
                "external or encoding transforming Git attributes are "
                "unsupported by "
                f"exact mutation rollback: {os.fsdecode(encoded_path)!r} has "
                f"{os.fsdecode(attribute)}={os.fsdecode(value)!r}"
            )
        transforming_paths.add(os.fsdecode(encoded_path))
    return (
        tuple(sorted(transforming_paths)),
        tuple(sorted(external_filter_paths)),
    )


def _git_status_paths(cwd: Path) -> set[str]:
    """Return every Git-visible changed path, including rename endpoints."""

    result = _run_bound_git_process(
        cwd,
        [
            "git", *_GIT_SAFE_OPTIONS,
            "status", "--porcelain=v1", "-z", "--untracked-files=all",
        ],
        GIT_OPTIONAL_LOCKS="0",
    )
    if result.returncode != 0:
        raise MutationJournalError(
            "cannot inspect Git status: "
            + result.stderr.decode("utf-8", errors="replace").strip()
        )
    raw = result.stdout
    records = raw.split(b"\0")
    paths: set[str] = set()
    index = 0
    while index < len(records):
        record = records[index]
        index += 1
        if not record:
            continue
        if len(record) < 4:
            raise MutationJournalError("malformed git status record")
        status_code = record[:2]
        paths.add(os.fsdecode(record[3:]))
        if b"R" in status_code or b"C" in status_code:
            if index >= len(records) or not records[index]:
                raise MutationJournalError("malformed git rename record")
            paths.add(os.fsdecode(records[index]))
            index += 1
    return paths


def _gitlink_paths(cwd: Path) -> tuple[str, ...]:
    paths: set[str] = set()
    index_raw = _git(cwd, "ls-files", "--stage", "-z")
    for record in index_raw.split(b"\0"):
        if not record:
            continue
        metadata, separator, encoded_path = record.partition(b"\t")
        if not separator:
            raise MutationJournalError("malformed Git index stage record")
        if metadata.split(b" ", 1)[0] == b"160000":
            paths.add(os.fsdecode(encoded_path))
    head_raw = _git(cwd, "ls-tree", "-r", "-z", "HEAD")
    for record in head_raw.split(b"\0"):
        if not record:
            continue
        metadata, separator, encoded_path = record.partition(b"\t")
        if not separator:
            raise MutationJournalError("malformed Git HEAD tree record")
        if metadata.split(b" ", 1)[0] == b"160000":
            paths.add(os.fsdecode(encoded_path))
    return tuple(sorted(paths))


def _walk_complete_real_tree(
    root: Path,
    *,
    tree_label: str,
) -> Iterator[tuple[Path, list[str], list[str]]]:
    """Walk retained real directories completely or fail the capture.

    ``Path.rglob`` and ``os.walk`` without ``onerror`` silently omit a real
    directory when ``scandir`` returns ``EACCES``.  A mutation baseline may
    never interpret that omission as an empty tree.  Track every real
    directory the caller retains for descent, bind its identity when listed,
    and require a corresponding visit.  Callers may prune opaque or separately
    guarded roots by removing their names from the yielded ``dirs`` list.
    """

    try:
        root_metadata = _descriptor_bound_lstat(root)
    except OSError as exc:
        raise MutationJournalError(
            f"cannot inspect {tree_label} root for complete traversal: {root}: {exc}"
        ) from exc
    if not stat.S_ISDIR(root_metadata.st_mode) or stat.S_ISLNK(
        root_metadata.st_mode
    ):
        raise MutationJournalError(
            f"{tree_label} root must be a real directory: {root}"
        )

    pending = {root: (root_metadata.st_dev, root_metadata.st_ino)}

    def walk_error(error: OSError) -> NoReturn:
        raise MutationJournalError(
            f"cannot completely traverse {tree_label}: "
            f"{error.filename or root}: {error}"
        ) from error

    for current, dirs, files in os.walk(
        root,
        topdown=True,
        onerror=walk_error,
        followlinks=False,
    ):
        current_path = Path(current)
        try:
            metadata = _descriptor_bound_lstat(current_path)
        except OSError as exc:
            walk_error(exc)
        expected_identity = pending.pop(current_path, None)
        if (
            expected_identity is None
            or not stat.S_ISDIR(metadata.st_mode)
            or stat.S_ISLNK(metadata.st_mode)
            or (metadata.st_dev, metadata.st_ino) != expected_identity
        ):
            raise MutationJournalError(
                f"{tree_label} directory changed identity during complete "
                f"traversal: {current_path}"
            )

        yield current_path, dirs, files

        for name in dirs:
            child = current_path / name
            try:
                child_metadata = child.lstat()
            except OSError as exc:
                walk_error(exc)
            if stat.S_ISDIR(child_metadata.st_mode) and not stat.S_ISLNK(
                child_metadata.st_mode
            ):
                pending[child] = (
                    child_metadata.st_dev,
                    child_metadata.st_ino,
                )

    if pending:
        raise MutationJournalError(
            f"cannot completely traverse {tree_label}: "
            f"unvisited={sorted(str(path) for path in pending)[:10]!r}"
        )


def _nested_vcs_markers(cwd: Path, scope: Iterable[str]) -> tuple[str, ...]:
    markers: set[str] = set()
    for relative in scope:
        target = cwd / relative
        ancestor = target if target.is_dir() else target.parent
        while ancestor != cwd and cwd in ancestor.parents:
            for name in _VCS_METADATA_COMPONENTS:
                candidate = ancestor / name
                if candidate.exists() or candidate.is_symlink():
                    markers.add(candidate.relative_to(cwd).as_posix())
            ancestor = ancestor.parent
        if not target.is_dir() or target.is_symlink():
            continue
        for current_path, dirs, files in _walk_complete_real_tree(
            target,
            tree_label="nested VCS marker search",
        ):
            names = set(dirs) | set(files)
            for name in names.intersection(_VCS_METADATA_COMPONENTS):
                markers.add(
                    (current_path / name).relative_to(cwd).as_posix()
                )
            dirs[:] = [
                name
                for name in dirs
                if name not in _VCS_METADATA_COMPONENTS
                and not (current_path / name).is_symlink()
            ]
    return tuple(sorted(markers))


def _all_nested_vcs_markers(
    cwd: Path,
    *,
    excluded_roots: Iterable[str] = (),
) -> tuple[str, ...]:
    """Inventory nested VCS administration anywhere in the worktree.

    Outer Git status cannot see mutations inside an embedded repository.  A
    transaction therefore cannot offer exact rollback while any nested VCS
    authority exists, even when it is outside the declared write scope.  The
    checkout's own root ``.git`` and Crucible-owned run metadata are the only
    exclusions.
    """

    excluded = tuple(_dedupe_roots(excluded_roots))

    def is_excluded(relative: str) -> bool:
        return any(
            relative == root or relative.startswith(root + "/")
            for root in excluded
        )

    markers: set[str] = set()
    for current_path, dirs, files in _walk_complete_real_tree(
        cwd,
        tree_label="worktree nested VCS marker search",
    ):
        current_relative = (
            ""
            if current_path == cwd
            else current_path.relative_to(cwd).as_posix()
        )
        retained_dirs: list[str] = []
        for name in dirs:
            relative = f"{current_relative}/{name}".lstrip("/")
            if (not current_relative and name == ".git") or is_excluded(relative):
                continue
            candidate = current_path / name
            if name in _VCS_METADATA_COMPONENTS:
                markers.add(relative)
                continue
            if not candidate.is_symlink():
                retained_dirs.append(name)
        dirs[:] = retained_dirs
        for name in files:
            relative = f"{current_relative}/{name}".lstrip("/")
            if (not current_relative and name == ".git") or is_excluded(relative):
                continue
            if name in _VCS_METADATA_COMPONENTS:
                markers.add(relative)
    return tuple(sorted(markers))


def _assert_directory_restore_control(
    path: Path,
    metadata: os.stat_result,
) -> None:
    """Enforce Crucible's ordinary-POSIX directory ownership contract.

    Exact rollback supports the normal local-filesystem rule that root or the
    directory owner can restore mode and user/ACL metadata.  Deliberately do
    not probe with ``chmod``: even a same-mode probe can alter inode metadata.
    Capability-only ownership and root-squashed/policy filesystems are outside
    this fail-closed contract.
    """

    if os.name == "nt" or not hasattr(os, "geteuid"):
        return
    effective_uid = os.geteuid()
    if effective_uid == 0 or metadata.st_uid == effective_uid:
        return
    raise MutationJournalError(
        "mutation journal cannot control modeled baseline directory under "
        "the ordinary-POSIX ownership contract: "
        f"path={str(path)!r} uid={metadata.st_uid} gid={metadata.st_gid} "
        f"mode={stat.S_IMODE(metadata.st_mode):#06o} "
        f"journal_euid={effective_uid}"
    )


def _make_real_directory_tree_owner_accessible(
    root: Path,
    *,
    tree_label: str,
    root_descriptor: int | None = None,
    excluded_roots: Iterable[str] = (),
    recursive: bool = True,
    final_root_mode: int | None = None,
    expected_root_identity: tuple[int, int] | None = None,
) -> None:
    """Grant owner access to every current real directory below ``root``.

    Rollback must remove transaction-created directories as well as restore
    baseline directories.  A model can create an owner-controlled directory
    and then chmod it to ``000``; baseline-only mode preparation cannot enter
    or remove that addition.  Keep every traversal descriptor-relative, never
    open symlinks, and verify each child inode after the no-follow chmod before
    descending.  The owning restore pass either reapplies baseline modes or
    removes the transaction-created directories.
    """

    if os.name == "nt":
        # Windows permissions do not create the POSIX owner-access failure
        # this preparation repairs.  Keep the established Windows behavior.
        return

    excluded = tuple(_dedupe_roots(excluded_roots))

    def excluded_path(relative: str) -> bool:
        return any(
            relative == excluded_root
            or relative.startswith(excluded_root.rstrip("/") + "/")
            for excluded_root in excluded
        )

    required_flags = ("O_PATH", "O_DIRECTORY", "O_NOFOLLOW")
    missing_flags = [name for name in required_flags if not hasattr(os, name)]
    if (
        missing_flags
        or os.listdir not in os.supports_fd
        or os.stat not in os.supports_dir_fd
    ):
        raise MutationJournalError(
            f"platform cannot safely prepare inaccessible {tree_label} "
            "directories without following aliases: "
            f"missing_flags={missing_flags!r}"
        )

    readable_open_flags = (
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | os.O_DIRECTORY
        | os.O_NOFOLLOW
    )
    path_open_flags = (
        os.O_PATH
        | getattr(os, "O_CLOEXEC", 0)
        | os.O_DIRECTORY
        | os.O_NOFOLLOW
    )

    def open_real_child_directory(
        parent_fd: int,
        name: str,
        path: Path,
        *,
        expected_identity: tuple[int, int] | None = None,
    ) -> int | None:
        try:
            before = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        except OSError as exc:
            raise MutationJournalError(
                f"{tree_label} directory changed during access preparation: {path}"
            ) from exc
        if not stat.S_ISDIR(before.st_mode) or stat.S_ISLNK(before.st_mode):
            return None
        path_fd: int | None = None
        child_fd: int | None = None
        try:
            try:
                path_fd = os.open(
                    name,
                    path_open_flags,
                    dir_fd=parent_fd,
                )
                opened_path = os.fstat(path_fd)
                current = os.stat(
                    name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
            except OSError as exc:
                raise MutationJournalError(
                    f"{tree_label} directory became inaccessible or aliased "
                    f"during access preparation: {path}: {exc}"
                ) from exc
            if (
                not stat.S_ISDIR(opened_path.st_mode)
                or (opened_path.st_dev, opened_path.st_ino)
                != (before.st_dev, before.st_ino)
                or (current.st_dev, current.st_ino)
                != (opened_path.st_dev, opened_path.st_ino)
                or (
                    expected_identity is not None
                    and (opened_path.st_dev, opened_path.st_ino)
                    != expected_identity
                )
            ):
                raise MutationJournalError(
                    f"{tree_label} directory changed identity during access "
                    f"preparation: {path}"
                )
            requested = stat.S_IMODE(opened_path.st_mode) | 0o700
            if stat.S_IMODE(opened_path.st_mode) != requested:
                try:
                    os.chmod(_authority_descriptor_cwd(path_fd), requested)
                except (NotImplementedError, OSError, ValueError) as exc:
                    raise MutationJournalError(
                        f"cannot safely grant owner access to real {tree_label} "
                        f"directory {path}: {exc}"
                    ) from exc
            prepared = os.fstat(path_fd)
            current = os.stat(
                name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
            if (
                not stat.S_ISDIR(prepared.st_mode)
                or (prepared.st_dev, prepared.st_ino)
                != (opened_path.st_dev, opened_path.st_ino)
                or stat.S_IMODE(prepared.st_mode) != requested
                or (current.st_dev, current.st_ino)
                != (opened_path.st_dev, opened_path.st_ino)
            ):
                raise MutationJournalError(
                    f"{tree_label} directory changed while granting owner "
                    f"access: {path}"
                )
            try:
                child_fd = os.open(
                    _authority_descriptor_cwd(path_fd),
                    readable_open_flags & ~os.O_NOFOLLOW,
                )
            except OSError as exc:
                raise MutationJournalError(
                    f"{tree_label} directory remained inaccessible during "
                    f"access preparation: {path}: {exc}"
                ) from exc
            opened = os.fstat(child_fd)
            current = os.stat(
                name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
            if (
                not stat.S_ISDIR(opened.st_mode)
                or (opened.st_dev, opened.st_ino)
                != (opened_path.st_dev, opened_path.st_ino)
                or (current.st_dev, current.st_ino)
                != (opened_path.st_dev, opened_path.st_ino)
            ):
                raise MutationJournalError(
                    f"{tree_label} directory changed while reopening after "
                    f"access preparation: {path}"
                )
            result = child_fd
            child_fd = None
            return result
        finally:
            if child_fd is not None:
                os.close(child_fd)
            if path_fd is not None:
                os.close(path_fd)

    binding = _held_authority_descriptor_path(root)
    if root_descriptor is not None:
        try:
            root_fd = os.dup(root_descriptor)
        except OSError as exc:
            raise MutationJournalError(
                f"cannot duplicate held authority for {tree_label}: {exc}"
            ) from exc
        try:
            authority_metadata = os.fstat(root_fd)
            if not stat.S_ISDIR(authority_metadata.st_mode) or (
                expected_root_identity is not None
                and (authority_metadata.st_dev, authority_metadata.st_ino)
                != expected_root_identity
            ):
                raise MutationJournalError(
                    f"held authority for {tree_label} is not a directory"
                )
            requested = stat.S_IMODE(authority_metadata.st_mode) | 0o700
            if stat.S_IMODE(authority_metadata.st_mode) != requested:
                os.fchmod(root_fd, requested)
                current_metadata = os.fstat(root_fd)
                if (
                    not stat.S_ISDIR(current_metadata.st_mode)
                    or current_metadata.st_dev != authority_metadata.st_dev
                    or current_metadata.st_ino != authority_metadata.st_ino
                ):
                    raise MutationJournalError(
                        f"held authority for {tree_label} changed identity"
                    )
        except BaseException:
            os.close(root_fd)
            raise
    elif binding is None:
        parent = root.parent
        try:
            parent_fd = os.open(parent, readable_open_flags)
        except OSError as exc:
            raise MutationJournalError(
                f"cannot open {tree_label} parent without following aliases: "
                f"{parent}: {exc}"
            ) from exc
        try:
            opened_root_fd = open_real_child_directory(
                parent_fd,
                root.name,
                root,
                expected_identity=expected_root_identity,
            )
            if opened_root_fd is None:
                raise MutationJournalError(
                    f"{tree_label} root must remain a real directory: {root}"
                )
            root_fd = opened_root_fd
        finally:
            os.close(parent_fd)
    else:
        authority_fd, alias, relative = binding
        try:
            root_fd = os.dup(authority_fd)
        except OSError as exc:
            raise MutationJournalError(
                f"cannot duplicate held authority for {tree_label}: {exc}"
            ) from exc
        current = alias
        try:
            authority_metadata = os.fstat(root_fd)
            if not stat.S_ISDIR(authority_metadata.st_mode) or (
                not relative.parts
                and expected_root_identity is not None
                and (authority_metadata.st_dev, authority_metadata.st_ino)
                != expected_root_identity
            ):
                raise MutationJournalError(
                    f"held authority for {tree_label} is not a directory"
                )
            requested = stat.S_IMODE(authority_metadata.st_mode) | 0o700
            if stat.S_IMODE(authority_metadata.st_mode) != requested:
                os.fchmod(root_fd, requested)
                current_metadata = os.fstat(root_fd)
                if (
                    not stat.S_ISDIR(current_metadata.st_mode)
                    or current_metadata.st_dev != authority_metadata.st_dev
                    or current_metadata.st_ino != authority_metadata.st_ino
                ):
                    raise MutationJournalError(
                        f"held authority for {tree_label} changed identity"
                    )
            for index, name in enumerate(relative.parts):
                child_path = current / name
                child_fd = open_real_child_directory(
                    root_fd,
                    name,
                    child_path,
                    expected_identity=(
                        expected_root_identity
                        if index == len(relative.parts) - 1
                        else None
                    ),
                )
                if child_fd is None:
                    raise MutationJournalError(
                        f"{tree_label} root must remain a real directory: "
                        f"{child_path}"
                    )
                os.close(root_fd)
                root_fd = child_fd
                current = child_path
        except BaseException:
            os.close(root_fd)
            raise

    root_metadata = os.fstat(root_fd)
    if not recursive:
        try:
            if final_root_mode is not None:
                os.fchmod(root_fd, final_root_mode)
                finished = os.fstat(root_fd)
                if (
                    (finished.st_dev, finished.st_ino)
                    != (root_metadata.st_dev, root_metadata.st_ino)
                    or stat.S_IMODE(finished.st_mode) != final_root_mode
                ):
                    raise MutationJournalError(
                        f"held {tree_label} root changed during mode restoration"
                    )
        finally:
            os.close(root_fd)
        return
    pending: list[tuple[tuple[str, ...], tuple[int, int]]] = [
        ((), (root_metadata.st_dev, root_metadata.st_ino)),
    ]
    try:
        while pending:
            relative_parts, expected_identity = pending.pop()
            directory_fd = os.dup(root_fd)
            current = root
            try:
                for name in relative_parts:
                    child_path = current / name
                    child_fd = open_real_child_directory(
                        directory_fd,
                        name,
                        child_path,
                    )
                    if child_fd is None:
                        raise MutationJournalError(
                            f"{tree_label} directory became aliased during "
                            f"access preparation: {child_path}"
                        )
                    os.close(directory_fd)
                    directory_fd = child_fd
                    current = child_path
                current_metadata = os.fstat(directory_fd)
                if (
                    current_metadata.st_dev,
                    current_metadata.st_ino,
                ) != expected_identity:
                    raise MutationJournalError(
                        f"{tree_label} directory changed identity before "
                        f"descent: {current}"
                    )
                names = os.listdir(directory_fd)
                for name in names:
                    child_path = current / name
                    child_relative = PurePosixPath(
                        *relative_parts,
                        name,
                    ).as_posix()
                    if excluded_path(child_relative):
                        continue
                    child_fd = open_real_child_directory(
                        directory_fd,
                        name,
                        child_path,
                    )
                    if child_fd is not None:
                        try:
                            child_metadata = os.fstat(child_fd)
                        finally:
                            os.close(child_fd)
                        pending.append((
                            (*relative_parts, name),
                            (child_metadata.st_dev, child_metadata.st_ino),
                        ))
            except BaseException:
                os.close(directory_fd)
                raise
            os.close(directory_fd)
        if final_root_mode is not None:
            os.fchmod(root_fd, final_root_mode)
            finished = os.fstat(root_fd)
            if (
                (finished.st_dev, finished.st_ino)
                != (root_metadata.st_dev, root_metadata.st_ino)
                or stat.S_IMODE(finished.st_mode) != final_root_mode
            ):
                raise MutationJournalError(
                    f"held {tree_label} root changed during mode restoration"
                )
    finally:
        os.close(root_fd)


def _directory_mode_inventory(
    cwd: Path,
    *,
    excluded_roots: Iterable[str] = (),
    require_restore_control: bool = False,
) -> dict[str, int]:
    excluded = tuple(_dedupe_roots(excluded_roots))

    def is_excluded(relative: str) -> bool:
        return any(
            relative == root or relative.startswith(root + "/")
            for root in excluded
        )

    inventory: dict[str, int] = {}
    for current_path, dirs, _files in _walk_complete_real_tree(
        cwd,
        tree_label="worktree directory topology",
    ):
        relative = (
            "." if current_path == cwd else current_path.relative_to(cwd).as_posix()
        )
        metadata = _descriptor_bound_lstat(current_path)
        if require_restore_control:
            _assert_directory_restore_control(current_path, metadata)
        inventory[relative] = stat.S_IMODE(metadata.st_mode)
        retained: list[str] = []
        for name in dirs:
            child = current_path / name
            child_relative = (
                name if relative == "." else f"{relative}/{name}"
            )
            if (
                (relative == "." and name == ".git")
                or is_excluded(child_relative)
                or child.is_symlink()
            ):
                continue
            metadata = child.lstat()
            if not stat.S_ISDIR(metadata.st_mode):
                raise MutationJournalError(
                    f"worktree directory changed type during inventory: {child}"
                )
            if require_restore_control:
                _assert_directory_restore_control(child, metadata)
            inventory[child_relative] = stat.S_IMODE(metadata.st_mode)
            retained.append(name)
        dirs[:] = retained
    return inventory


def _relevant_nested_vcs_markers(
    cwd: Path,
    *,
    excluded_roots: Iterable[str] = (),
    ignored_roots: Iterable[str] | None = None,
) -> tuple[str, ...]:
    """Return nested markers that are part of outer Git's authority.

    Git-ignored build trees are intentionally outside the transaction's exact
    rollback boundary.  Query each marker's containing directory without
    ``--no-index`` so a tracked directory cannot be hidden by a broad ignore
    pattern.
    """

    baseline_ignored = (
        tuple(ignored_roots)
        if ignored_roots is not None
        else _ignored_directory_roots(cwd)
    )
    return _all_nested_vcs_markers(
        cwd,
        excluded_roots=(*excluded_roots, *baseline_ignored),
    )


def _ignored_directory_roots(cwd: Path) -> tuple[str, ...]:
    """Return collapsed ignored directory roots without traversing them."""

    raw = _git(
        cwd,
        "ls-files",
        "-z",
        "--others",
        "--ignored",
        "--exclude-standard",
        "--directory",
    )
    roots = (
        os.fsdecode(encoded).rstrip("/")
        for encoded in raw.split(b"\0")
        if encoded.endswith(b"/")
    )
    return _dedupe_roots(roots)


def _ignored_directory_roots_outside_authority(
    cwd: Path,
    *,
    protected_paths: Iterable[str],
) -> tuple[str, ...]:
    """Return only ignored roots disjoint from captured path authority.

    Ignored build trees outside the declared surface remain opaque.  An
    ignored root that contains, equals, or is contained by a snapshotted path
    cannot be excluded from directory authority: restoring a captured entry
    below it requires a durable binding for every real parent directory.
    """

    protected = tuple(
        path for path in _dedupe_roots(protected_paths) if path != "."
    )
    return tuple(
        ignored
        for ignored in _ignored_directory_roots(cwd)
        if not any(
            ignored == path
            or ignored.startswith(path.rstrip("/") + "/")
            or path.startswith(ignored.rstrip("/") + "/")
            for path in protected
        )
    )


def _ignore_policy_paths(cwd: Path) -> tuple[str, ...]:
    if _git_config(cwd, "core.excludesFile") is not None:
        raise MutationJournalError(
            "core.excludesFile is unsupported by exact mutation rollback"
        )
    raw = _git(
        cwd,
        "ls-files",
        "-z",
        "--cached",
        "--others",
        "--exclude-standard",
        "--",
        ".gitignore",
        ":(glob)**/.gitignore",
    )
    return tuple(os.fsdecode(encoded) for encoded in raw.split(b"\0") if encoded)


def _capture_ignore_policy(journal_dir: Path, cwd: Path) -> list[dict]:
    snapshot_root = journal_dir / "ignore_policy"
    records: list[dict] = []
    tracked = {
        os.fsdecode(encoded)
        for encoded in _git(
            cwd,
            "ls-files",
            "-z",
            "--cached",
            "--",
            ".gitignore",
            ":(glob)**/.gitignore",
        ).split(b"\0")
        if encoded
    }
    for index, relative in enumerate(_ignore_policy_paths(cwd)):
        path = cwd / relative
        try:
            metadata = _descriptor_bound_lstat(path)
        except FileNotFoundError as exc:
            if relative not in tracked:
                raise MutationJournalError(
                    "untracked Git ignore policy disappeared during capture: "
                    f"{relative}"
                ) from exc
            records.append({
                "path": relative,
                "exists": False,
            })
            continue
        if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
            raise MutationJournalError(
                f"Git ignore policy must be a non-linked regular file: {relative}"
            )
        snapshot = f"{index:06d}"
        payload = path.read_bytes()
        write_atomic_bytes(snapshot_root / snapshot, payload)
        records.append({
            "path": relative,
            "exists": True,
            "mode": stat.S_IMODE(metadata.st_mode),
            "snapshot": snapshot,
            "xattrs": _xattr_inventory(path),
            **_capture_snapshot_blob_record(journal_dir, payload),
        })
    return records


def _attribute_policy_paths(cwd: Path) -> tuple[str, ...]:
    # Do not apply ignore rules here. An untracked .gitattributes below an
    # ignored directory can still govern tracked descendants, and a mutated
    # .gitignore must not hide a newly-created policy file during rollback.
    raw = _git(
        cwd,
        "ls-files",
        "-z",
        "--cached",
        "--others",
        "--",
        ".gitattributes",
        ":(glob)**/.gitattributes",
    )
    return tuple(os.fsdecode(encoded) for encoded in raw.split(b"\0") if encoded)


def _capture_attribute_policy(
    journal_dir: Path,
    cwd: Path,
    paths: Iterable[str],
) -> list[dict[str, object]]:
    snapshot_root = journal_dir / "attribute_policy"
    tracked = {
        os.fsdecode(encoded)
        for encoded in _git(
            cwd,
            "ls-files",
            "-z",
            "--cached",
            "--",
            ".gitattributes",
            ":(glob)**/.gitattributes",
        ).split(b"\0")
        if encoded
    }
    records: list[dict[str, object]] = []
    for index, relative in enumerate(paths):
        path = cwd / relative
        try:
            metadata = path.lstat()
        except FileNotFoundError as exc:
            if relative not in tracked:
                raise MutationJournalError(
                    "untracked Git attribute policy disappeared during capture: "
                    f"{relative}"
                ) from exc
            records.append({"path": relative, "exists": False})
            continue
        if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
            raise MutationJournalError(
                "Git attribute policy must be a non-linked regular file: "
                f"{relative}"
            )
        snapshot = f"{index:06d}"
        payload = path.read_bytes()
        write_atomic_bytes(snapshot_root / snapshot, payload)
        records.append({
            "path": relative,
            "exists": True,
            "mode": stat.S_IMODE(metadata.st_mode),
            "snapshot": snapshot,
            "xattrs": _xattr_inventory(path),
            **_capture_snapshot_blob_record(journal_dir, payload),
        })
    return records


def _tracked_worktree_inventory(
    cwd: Path,
    *,
    gitlinks: Iterable[str] = (),
    extra_paths: Iterable[str] = (),
) -> dict[str, dict[str, object]]:
    """Capture a metadata-only guard for a clean nested worktree.

    Nested dependency checkouts may contain gigabytes of tracked data and
    transforming attributes, so copying or hashing their worktree is not a
    viable per-invocation operation.  Status plus inode metadata catches
    ordinary writes cheaply; if it changes, the parent transaction retains
    its journal rather than attempting a potentially lossy checkout.
    """

    tracked_paths = {
        os.fsdecode(encoded)
        for encoded in _git(cwd, "ls-files", "-z").split(b"\0")
        if encoded
    }
    tracked_paths.update(extra_paths)
    paths = set(tracked_paths)
    paths.add(".")
    for relative in tracked_paths:
        parent = PurePosixPath(relative).parent
        while str(parent) not in {"", "."}:
            paths.add(parent.as_posix())
            parent = parent.parent
    return _tracked_worktree_inventory_for_paths(
        cwd,
        paths=paths,
        gitlinks=gitlinks,
    )


def _tracked_path_metadata(
    cwd: Path,
    *,
    gitlinks: Iterable[str] = (),
) -> dict[str, dict[str, object]]:
    """Capture Git-invisible metadata for every tracked non-gitlink path."""

    nested_roots = tuple(_dedupe_roots(gitlinks))
    inventory: dict[str, dict[str, object]] = {}
    for encoded in _git(cwd, "ls-files", "-z").split(b"\0"):
        if not encoded:
            continue
        relative = os.fsdecode(encoded)
        if any(
            relative == root or relative.startswith(root + "/")
            for root in nested_roots
        ):
            continue
        record = _tracked_path_metadata_for_path(cwd, relative)
        kind = record["kind"]
        if kind not in {"file", "symlink", "missing"}:
            raise MutationJournalError(
                f"tracked path has unsupported worktree type: {relative}"
            )
        if kind != "missing" and record["nlink"] != 1:
            raise MutationJournalError(
                f"tracked path must not be hard-linked: {relative}"
            )
        inventory[relative] = record
    return inventory


def _tracked_path_metadata_for_path(
    cwd: Path,
    relative: str,
) -> dict[str, object]:
    path = cwd / relative
    try:
        metadata = path.lstat()
    except FileNotFoundError:
        return {"kind": "missing"}
    kind = (
        "file" if stat.S_ISREG(metadata.st_mode)
        else "symlink" if stat.S_ISLNK(metadata.st_mode)
        else "other"
    )
    record: dict[str, object] = {
        "kind": kind,
        "mode": stat.S_IMODE(metadata.st_mode),
        "nlink": metadata.st_nlink,
        "xattrs": _xattr_inventory(path),
        "device": metadata.st_dev,
        "inode": metadata.st_ino,
        "size": metadata.st_size,
        "mtime_ns": metadata.st_mtime_ns,
        "ctime_ns": metadata.st_ctime_ns,
    }
    if kind == "symlink":
        record["target"] = os.readlink(path)
    return record


def _xattr_inventory(path: Path) -> dict[str, str]:
    """Capture bounded no-follow xattrs, including POSIX ACL xattrs."""

    if not hasattr(os, "listxattr"):
        return {}
    binding = _held_authority_descriptor_path(path)
    descriptor = (
        binding[0]
        if binding is not None and binding[2] == Path(".")
        else None
    )
    target: int | Path = descriptor if descriptor is not None else path
    nofollow = {} if descriptor is not None else {"follow_symlinks": False}
    try:
        names = sorted(os.listxattr(target, **nofollow))
    except OSError as exc:
        if exc.errno in {errno.ENOTSUP, errno.EOPNOTSUPP}:
            return {}
        raise MutationJournalError(f"cannot inspect xattrs for {path}: {exc}") from exc
    if len(names) > 256:
        raise MutationJournalError(f"too many xattrs for exact rollback: {path}")
    inventory: dict[str, str] = {}
    total_bytes = 0
    for name in names:
        try:
            value = os.getxattr(target, name, **nofollow)
        except OSError as exc:
            raise MutationJournalError(
                f"cannot read xattr {name!r} for {path}: {exc}"
            ) from exc
        total_bytes += len(value)
        if total_bytes > 4 * 1024 * 1024:
            raise MutationJournalError(f"xattrs too large for exact rollback: {path}")
        inventory[name] = value.hex()
    return inventory


def _restore_xattrs(path: Path, expected: dict[str, str]) -> None:
    if not hasattr(os, "listxattr"):
        if expected:
            raise MutationJournalError(
                f"platform cannot restore baseline xattrs for {path}"
            )
        return
    binding = _held_authority_descriptor_path(path)
    descriptor = (
        binding[0]
        if binding is not None and binding[2] == Path(".")
        else None
    )
    target: int | Path = descriptor if descriptor is not None else path
    nofollow = {} if descriptor is not None else {"follow_symlinks": False}
    current = _xattr_inventory(path)
    for name in set(current).difference(expected):
        os.removexattr(target, name, **nofollow)
    for name, encoded in expected.items():
        value = bytes.fromhex(encoded)
        if current.get(name) != encoded:
            os.setxattr(target, name, value, **nofollow)


def _tracked_worktree_inventory_for_paths(
    cwd: Path,
    *,
    paths: Iterable[str],
    gitlinks: Iterable[str] = (),
) -> dict[str, dict[str, object]]:
    nested_roots = set(gitlinks)
    inventory: dict[str, dict[str, object]] = {}
    for relative in paths:
        if relative in nested_roots:
            continue
        path = cwd / relative
        try:
            metadata = _descriptor_bound_lstat(path)
        except FileNotFoundError:
            inventory[relative] = {"kind": "missing"}
            continue
        kind = (
            "symlink" if stat.S_ISLNK(metadata.st_mode)
            else "file" if stat.S_ISREG(metadata.st_mode)
            else "directory" if stat.S_ISDIR(metadata.st_mode)
            else "other"
        )
        record: dict[str, object] = {
            "kind": kind,
            "mode": stat.S_IMODE(metadata.st_mode),
        }
        record["xattrs"] = _xattr_inventory(path)
        if kind != "directory":
            record.update({
                "size": metadata.st_size,
                "mtime_ns": metadata.st_mtime_ns,
                "ctime_ns": metadata.st_ctime_ns,
                "nlink": metadata.st_nlink,
            })
        if stat.S_ISLNK(metadata.st_mode):
            record["target"] = os.readlink(path)
        inventory[relative] = record
    return inventory


def _structural_worktree_inventory(
    inventory: dict[str, dict[str, object]],
) -> dict[str, dict[str, object]]:
    structural: dict[str, dict[str, object]] = {}
    for relative, record in inventory.items():
        retained = dict(record)
        for key in ("size", "mtime_ns", "ctime_ns"):
            retained.pop(key, None)
        structural[relative] = retained
    return structural


def _nested_clean_status(
    cwd: Path,
    *,
    excluded_roots: Iterable[str] = (),
) -> bytes:
    result = _run_bound_git_process(
        cwd,
        [
            "git", *_GIT_SAFE_OPTIONS,
            "status", "--porcelain=v1", "-z", "--untracked-files=all",
            "--ignore-submodules=none",
        ],
        GIT_OPTIONAL_LOCKS="0",
    )
    if result.returncode != 0:
        raise MutationJournalError(
            "cannot inspect nested Git status: "
            + result.stderr.decode("utf-8", errors="replace").strip()
        )
    excluded = tuple(_dedupe_roots(excluded_roots))
    if not excluded:
        return result.stdout
    records = result.stdout.split(b"\0")
    retained: list[bytes] = []
    index = 0
    while index < len(records):
        record = records[index]
        index += 1
        if not record:
            continue
        if len(record) < 4:
            raise MutationJournalError("malformed nested Git status record")
        status_code = record[:2]
        related = [record]
        paths = [os.fsdecode(record[3:])]
        if b"R" in status_code or b"C" in status_code:
            if index >= len(records) or not records[index]:
                raise MutationJournalError("malformed nested Git rename record")
            related.append(records[index])
            paths.append(os.fsdecode(records[index]))
            index += 1
        if any(
            path == root or path.startswith(root + "/")
            for path in paths
            for root in excluded
        ):
            continue
        retained.extend(related)
    return b"\0".join(retained) + (b"\0" if retained else b"")


def _registered_worktrees(cwd: Path) -> tuple[str, ...]:
    raw = _git(cwd, "worktree", "list", "--porcelain", "-z")
    return tuple(
        os.fsdecode(field[len(b"worktree "):])
        for field in raw.split(b"\0")
        if field.startswith(b"worktree ")
    )


def _registered_worktree_admin_roots(cwd: Path) -> dict[Path, str]:
    """Map linked checkout paths, including missing ones, to admin roots."""

    root = _git_common_dir(cwd) / "worktrees"
    if not root.is_dir():
        return {}
    mapping: dict[Path, str] = {}
    for admin in root.iterdir():
        if not admin.is_dir() or admin.is_symlink():
            continue
        gitdir_file = admin / "gitdir"
        try:
            rendered = gitdir_file.read_text(
                encoding="utf-8", errors="surrogateescape"
            ).strip()
        except OSError:
            continue
        if not rendered:
            continue
        git_entry = Path(rendered)
        checkout = git_entry.parent.resolve()
        mapping[checkout] = admin.name
    return mapping


def _module_admin_roots(cwd: Path) -> tuple[str, ...]:
    root = _git_common_dir(cwd) / "modules"
    if not root.is_dir():
        return ()
    roots: list[str] = []
    for current_path, dirs, files in _walk_complete_real_tree(
        root,
        tree_label="Git module administration discovery",
    ):
        if {"HEAD", "config"}.issubset(files) and "objects" in dirs:
            roots.append(current_path.relative_to(root).as_posix())
            dirs[:] = []
            continue
        dirs[:] = [
            name for name in dirs
            if not (current_path / name).is_symlink()
        ]
    return tuple(sorted(roots))


def _module_namespace_topology(
    cwd: Path,
    *,
    guarded_roots: Iterable[str],
    require_restore_control: bool = False,
) -> dict[str, dict[str, int | str]]:
    root = _git_common_dir(cwd) / "modules"
    try:
        root_metadata = root.lstat()
    except FileNotFoundError:
        return {".": {"kind": "missing"}}
    if (
        not stat.S_ISDIR(root_metadata.st_mode)
        or stat.S_ISLNK(root_metadata.st_mode)
    ):
        return {".": {"kind": "aliased"}}
    if require_restore_control:
        _assert_directory_restore_control(root, root_metadata)
    guarded = set(guarded_roots)
    topology: dict[str, dict[str, int | str]] = {
        ".": {
            "kind": "directory",
            "mode": stat.S_IMODE(root_metadata.st_mode),
            "device": root_metadata.st_dev,
            "inode": root_metadata.st_ino,
        }
    }
    for current_path, dirs, files in _walk_complete_real_tree(
        root,
        tree_label="Git module namespace",
    ):
        relative = (
            "" if current_path == root else current_path.relative_to(root).as_posix()
        )
        if relative in guarded:
            dirs[:] = []
            continue
        if relative and {"HEAD", "config"}.issubset(files) and "objects" in dirs:
            repository_metadata = current_path.lstat()
            topology[relative] = {
                "kind": "repository",
                "device": repository_metadata.st_dev,
                "inode": repository_metadata.st_ino,
            }
            dirs[:] = []
            continue
        retained: list[str] = []
        for name in dirs:
            child = current_path / name
            child_relative = f"{relative}/{name}".lstrip("/")
            if child_relative in guarded:
                continue
            metadata = child.lstat()
            if stat.S_ISLNK(metadata.st_mode):
                topology[child_relative] = {
                    "kind": "symlink",
                    "target": os.readlink(child),
                    "device": metadata.st_dev,
                    "inode": metadata.st_ino,
                    "nlink": metadata.st_nlink,
                }
                continue
            if not stat.S_ISDIR(metadata.st_mode):
                topology[child_relative] = {
                    "kind": "other",
                    "device": metadata.st_dev,
                    "inode": metadata.st_ino,
                }
                continue
            if require_restore_control:
                _assert_directory_restore_control(child, metadata)
            topology[child_relative] = {
                "kind": "directory",
                "mode": stat.S_IMODE(metadata.st_mode),
                "device": metadata.st_dev,
                "inode": metadata.st_ino,
            }
            retained.append(name)
        dirs[:] = retained
        for name in files:
            child = current_path / name
            child_relative = f"{relative}/{name}".lstrip("/")
            metadata = child.lstat()
            topology[child_relative] = {
                "kind": "file" if stat.S_ISREG(metadata.st_mode) else "other",
                "mode": stat.S_IMODE(metadata.st_mode),
                "device": metadata.st_dev,
                "inode": metadata.st_ino,
                "nlink": metadata.st_nlink,
                "size": metadata.st_size,
                "mtime_ns": metadata.st_mtime_ns,
                "ctime_ns": metadata.st_ctime_ns,
            }
    return topology


def _capture_cached_module_controls(
    journal_dir: Path,
    modules_root: Path,
    module_roots: Iterable[str],
) -> list[dict[str, object]]:
    """Snapshot deinitialized module controls while excluding payload caches."""

    captured: list[dict[str, object]] = []
    for module_index, relative_root in enumerate(sorted(module_roots)):
        root = modules_root / relative_root
        root_metadata = root.lstat()
        if not stat.S_ISDIR(root_metadata.st_mode) or stat.S_ISLNK(
            root_metadata.st_mode
        ):
            raise MutationJournalError(f"cached module control is aliased: {root}")
        _assert_directory_restore_control(root, root_metadata)
        entries: dict[str, dict[str, object]] = {}
        payload_roots: dict[str, dict[str, object]] = {}
        entry_count = 0
        total_bytes = 0
        for current_path, dirs, files in _walk_complete_real_tree(
            root,
            tree_label="cached Git module controls",
        ):
            current_relative = (
                "" if current_path == root
                else current_path.relative_to(root).as_posix()
            )
            retained: list[str] = []
            for name in sorted(dirs):
                child = current_path / name
                relative = f"{current_relative}/{name}".lstrip("/")
                metadata = child.lstat()
                if stat.S_ISLNK(metadata.st_mode) or not stat.S_ISDIR(metadata.st_mode):
                    raise MutationJournalError(
                        f"cached module control is aliased: {child}"
                    )
                _assert_directory_restore_control(child, metadata)
                if not current_relative and name in _CACHED_MODULE_PAYLOAD_DIRECTORIES:
                    payload_roots[name] = {
                        "kind": "directory",
                        "mode": stat.S_IMODE(metadata.st_mode),
                        "device": metadata.st_dev,
                        "inode": metadata.st_ino,
                        "xattrs": _xattr_inventory(child),
                    }
                    continue
                entries[relative] = {
                    "kind": "directory",
                    "mode": stat.S_IMODE(metadata.st_mode),
                    "device": metadata.st_dev,
                    "inode": metadata.st_ino,
                    "xattrs": _xattr_inventory(child),
                }
                entry_count += 1
                retained.append(name)
            dirs[:] = retained
            for name in sorted(files):
                child = current_path / name
                relative = f"{current_relative}/{name}".lstrip("/")
                metadata = child.lstat()
                if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
                    raise MutationJournalError(
                        f"cached module control must be a regular file: {child}"
                    )
                entry_count += 1
                total_bytes += metadata.st_size
                if entry_count > 100_000 or total_bytes > 64 * 1024 * 1024:
                    raise MutationJournalError(
                        f"cached module controls are unexpectedly large: {root}"
                    )
                snapshot = f"{module_index:04d}/{len(entries):08d}"
                payload = child.read_bytes()
                write_atomic_bytes(
                    journal_dir / "cached_module_controls" / snapshot,
                    payload,
                )
                entries[relative] = {
                    "kind": "file",
                    "mode": stat.S_IMODE(metadata.st_mode),
                    "snapshot": snapshot,
                    "xattrs": _xattr_inventory(child),
                    **_capture_snapshot_blob_record(journal_dir, payload),
                }
        captured.append({
            "root": str(root),
            "relative_root": relative_root,
            "entries": entries,
            "payload_roots": payload_roots,
        })
    return captured


def _cached_module_control_metadata(
    root: Path,
) -> tuple[dict[str, dict[str, object]], dict[str, dict[str, object]]]:
    entries: dict[str, dict[str, object]] = {}
    payload_roots: dict[str, dict[str, object]] = {}
    for current_path, dirs, files in _walk_complete_real_tree(
        root,
        tree_label="cached Git module control verification",
    ):
        current_relative = (
            "" if current_path == root
            else current_path.relative_to(root).as_posix()
        )
        retained: list[str] = []
        for name in sorted(dirs):
            child = current_path / name
            relative = f"{current_relative}/{name}".lstrip("/")
            metadata = child.lstat()
            kind = (
                "directory"
                if stat.S_ISDIR(metadata.st_mode) and not stat.S_ISLNK(metadata.st_mode)
                else "other"
            )
            record: dict[str, object] = {
                "kind": kind,
                "mode": stat.S_IMODE(metadata.st_mode),
                "xattrs": _xattr_inventory(child),
            }
            if not current_relative and name in _CACHED_MODULE_PAYLOAD_DIRECTORIES:
                record.update({
                    "device": metadata.st_dev,
                    "inode": metadata.st_ino,
                })
                payload_roots[name] = record
                continue
            entries[relative] = record
            if kind == "directory":
                retained.append(name)
        dirs[:] = retained
        for name in sorted(files):
            child = current_path / name
            relative = f"{current_relative}/{name}".lstrip("/")
            metadata = child.lstat()
            entries[relative] = {
                "kind": "file" if stat.S_ISREG(metadata.st_mode) else "other",
                "mode": stat.S_IMODE(metadata.st_mode),
                "nlink": metadata.st_nlink,
                "xattrs": _xattr_inventory(child),
            }
    return entries, payload_roots


def _worktree_namespace_topology(
    cwd: Path,
    *,
    guarded_admin_roots: Iterable[str] = (),
    require_restore_control: bool = False,
) -> dict[str, dict[str, int | str]]:
    common = _git_common_dir(cwd)
    root = common / "worktrees"
    git_dir = _git_dir(cwd)
    guarded: set[str] = set(guarded_admin_roots)
    try:
        relative_git_dir = git_dir.relative_to(root)
    except ValueError:
        pass
    else:
        if relative_git_dir.parts:
            guarded.add(relative_git_dir.parts[0])
    try:
        root_metadata = root.lstat()
    except FileNotFoundError:
        return {".": {"kind": "missing"}}
    if (
        not stat.S_ISDIR(root_metadata.st_mode)
        or stat.S_ISLNK(root_metadata.st_mode)
    ):
        return {".": {"kind": "aliased"}}
    if require_restore_control:
        _assert_directory_restore_control(root, root_metadata)
    topology: dict[str, dict[str, int | str]] = {
        ".": {
            "kind": "directory",
            "mode": stat.S_IMODE(root_metadata.st_mode),
            "device": root_metadata.st_dev,
            "inode": root_metadata.st_ino,
        }
    }
    for current_path, dirs, files in _walk_complete_real_tree(
        root,
        tree_label="Git worktree administration namespace",
    ):
        relative = (
            "" if current_path == root else current_path.relative_to(root).as_posix()
        )
        if relative in guarded:
            dirs[:] = []
            continue
        retained: list[str] = []
        for name in dirs:
            child = current_path / name
            child_relative = f"{relative}/{name}".lstrip("/")
            if child_relative in guarded:
                continue
            metadata = child.lstat()
            topology[child_relative] = {
                "kind": "directory" if stat.S_ISDIR(metadata.st_mode) else "other",
                "mode": stat.S_IMODE(metadata.st_mode),
                "device": metadata.st_dev,
                "inode": metadata.st_ino,
            }
            if stat.S_ISDIR(metadata.st_mode) and not stat.S_ISLNK(metadata.st_mode):
                if require_restore_control:
                    _assert_directory_restore_control(child, metadata)
                retained.append(name)
        dirs[:] = retained
        for name in files:
            child = current_path / name
            child_relative = f"{relative}/{name}".lstrip("/")
            metadata = child.lstat()
            topology[child_relative] = {
                "kind": "file" if stat.S_ISREG(metadata.st_mode) else "other",
                "mode": stat.S_IMODE(metadata.st_mode),
                "device": metadata.st_dev,
                "inode": metadata.st_ino,
                "nlink": metadata.st_nlink,
                "size": metadata.st_size,
                "mtime_ns": metadata.st_mtime_ns,
                "ctime_ns": metadata.st_ctime_ns,
            }
            if len(topology) > 10_000:
                raise MutationJournalError("Git worktree namespace is too large")
    return topology


def _capture_git_entry(journal_dir: Path, cwd: Path) -> dict[str, object]:
    path = cwd / ".git"
    metadata = path.lstat()
    if stat.S_ISLNK(metadata.st_mode):
        raise MutationJournalError(f"Git administration must not be symlinked: {path}")
    if stat.S_ISDIR(metadata.st_mode):
        return {
            "kind": "directory",
            "mode": stat.S_IMODE(metadata.st_mode),
            "device": metadata.st_dev,
            "inode": metadata.st_ino,
            "resolved": str(path.resolve()),
            "xattrs": _xattr_inventory(path),
        }
    if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
        raise MutationJournalError(
            f"Git indirection file must be a non-linked regular file: {path}"
        )
    payload = path.read_bytes()
    write_atomic_bytes(journal_dir / "git_entry", payload)
    return {
        "kind": "file",
        "mode": stat.S_IMODE(metadata.st_mode),
        "resolved": str(path.resolve()),
        "xattrs": _xattr_inventory(path),
        **_capture_snapshot_blob_record(journal_dir, payload),
    }


def _head(cwd: Path) -> str:
    return _git(cwd, "rev-parse", "HEAD").decode().strip()


def _index_path(cwd: Path) -> Path:
    rendered = os.fsdecode(_git(cwd, "rev-parse", "--git-path", "index")).strip()
    return _lexical_absolute_control_path(cwd, rendered)


def _symbolic_head(cwd: Path) -> str | None:
    result = _git(cwd, "symbolic-ref", "-q", "HEAD", check=False).decode().strip()
    return result or None


def _refs_snapshot(cwd: Path) -> dict[str, str]:
    raw = _git(
        cwd,
        "for-each-ref",
        "--format=%(refname)%00%(objectname)",
    )
    refs: dict[str, str] = {}
    for record in raw.splitlines():
        try:
            encoded_ref, encoded_oid = record.split(b"\0", 1)
        except ValueError as exc:
            raise MutationJournalError("malformed Git ref inventory") from exc
        refs[os.fsdecode(encoded_ref)] = encoded_oid.decode("ascii")
    return refs


def _objects_path(cwd: Path) -> Path:
    rendered = os.fsdecode(
        _git(
            cwd,
            "rev-parse",
            "--path-format=absolute",
            "--git-path",
            "objects",
        )
    ).strip()
    path = _lexical_absolute_control_path(cwd, rendered)
    try:
        metadata = path.lstat()
    except FileNotFoundError as exc:
        raise MutationJournalError(
            f"Git object directory is missing: {path}"
        ) from exc
    if not stat.S_ISDIR(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
        raise MutationJournalError(
            f"Git object root must be a real directory, got {path}"
        )
    return path


def _refs_path(cwd: Path) -> Path:
    rendered = os.fsdecode(
        _git(cwd, "rev-parse", "--git-path", "refs")
    ).strip()
    path = _lexical_absolute_control_path(cwd, rendered)
    try:
        metadata = path.lstat()
    except FileNotFoundError as exc:
        raise MutationJournalError(f"Git refs directory is missing: {path}") from exc
    if not stat.S_ISDIR(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
        raise MutationJournalError(
            f"Git refs root must be a real directory, got {path}"
        )
    return path


def _git_common_dir(
    cwd: Path,
    *,
    timeout_s: float | None = None,
) -> Path:
    rendered = os.fsdecode(
        _git(
            cwd,
            "rev-parse",
            "--path-format=absolute",
            "--git-common-dir",
            timeout_s=timeout_s,
        )
    )
    if rendered.endswith("\r\n"):
        rendered = rendered[:-2]
    elif rendered.endswith("\n"):
        rendered = rendered[:-1]
    path = Path(rendered)
    if not path.is_absolute():
        path = cwd / path
    return path.resolve()


def _git_dir(cwd: Path) -> Path:
    rendered = os.fsdecode(_git(
        cwd,
        "rev-parse",
        "--path-format=absolute",
        "--absolute-git-dir",
    ))
    if rendered.endswith("\r\n"):
        rendered = rendered[:-2]
    elif rendered.endswith("\n"):
        rendered = rendered[:-1]
    return Path(rendered).resolve()


def _git_worktree_root(cwd: Path) -> Path:
    rendered = os.fsdecode(_git(
        cwd,
        "rev-parse",
        "--path-format=absolute",
        "--show-toplevel",
    )).strip()
    return Path(rendered).resolve()


def _workspace_authority_common_dir(
    cwd: Path,
    *,
    root_fd: int | None = None,
) -> Path:
    """Return the topmost superproject common dir for locking/registry."""

    current = cwd.resolve()
    visited: set[Path] = set()
    if root_fd is None:
        current_fd, current_metadata = _open_authority_directory(
            current,
            label="workspace authority root",
        )
    else:
        try:
            current_fd = os.dup(root_fd)
            current_metadata = os.fstat(current_fd)
        except OSError as exc:
            raise MutationJournalError(
                f"cannot duplicate workspace authority root: {exc}"
            ) from exc
    try:
        while current not in visited:
            visited.add(current)
            _assert_authority_directory_binding(
                current,
                current_fd,
                current_metadata,
                label="workspace authority root",
            )
            _preflight_local_config_authority(current)
            _assert_authority_directory_binding(
                current,
                current_fd,
                current_metadata,
                label="workspace authority root",
            )
            rendered = os.fsdecode(_git(
                Path(_authority_descriptor_cwd(current_fd)),
                "rev-parse",
                "--path-format=absolute",
                "--show-superproject-working-tree",
                check=False,
                timeout_s=_AUTHORITY_DISCOVERY_TIMEOUT_S,
                pass_fds=(current_fd,),
            ))
            _assert_authority_directory_binding(
                current,
                current_fd,
                current_metadata,
                label="workspace authority root",
            )
            if rendered.endswith("\r\n"):
                rendered = rendered[:-2]
            elif rendered.endswith("\n"):
                rendered = rendered[:-1]
            if not rendered:
                break
            parent = Path(rendered).resolve()
            if parent == current:
                raise MutationJournalError("Git superproject cycle detected")
            parent_fd, parent_metadata = _open_authority_directory(
                parent,
                label="superproject authority root",
            )
            os.close(current_fd)
            current = parent
            current_fd = parent_fd
            current_metadata = parent_metadata

        _assert_authority_directory_binding(
            current,
            current_fd,
            current_metadata,
            label="workspace authority root",
        )
        rendered_common = os.fsdecode(_git(
            Path(_authority_descriptor_cwd(current_fd)),
            "rev-parse",
            "--path-format=absolute",
            "--git-common-dir",
            timeout_s=_AUTHORITY_DISCOVERY_TIMEOUT_S,
            pass_fds=(current_fd,),
        ))
        _assert_authority_directory_binding(
            current,
            current_fd,
            current_metadata,
            label="workspace authority root",
        )
        common = Path(rendered_common.rstrip("\r\n"))
        if not common.is_absolute():
            common = current / common
        return common.resolve()
    finally:
        os.close(current_fd)


def _superproject_worktree(cwd: Path) -> Path | None:
    rendered = os.fsdecode(_git(
        cwd,
        "rev-parse",
        "--path-format=absolute",
        "--show-superproject-working-tree",
        check=False,
    )).strip()
    return Path(rendered).resolve() if rendered else None


def _capture_authority_lock(cwd: Path) -> dict[str, object]:
    """Capture the topmost lock inode that grants this transaction authority."""

    active = _active_workspace_mutation_authority(cwd)
    if active is not None:
        authority = _assert_workspace_mutation_authority(cwd)
        metadata = os.fstat(authority.lock_descriptor)
        common_metadata = os.fstat(authority.common_descriptor)
        root_metadata = os.fstat(authority.root_descriptor)
        return {
            "path": str(
                authority.common_dir / "crucible-workspace.lock"
            ),
            "mode": stat.S_IMODE(metadata.st_mode),
            "device": metadata.st_dev,
            "inode": metadata.st_ino,
            "nlink": metadata.st_nlink,
            "xattrs": _xattr_inventory(
                authority.common_dir / "crucible-workspace.lock"
            ),
            "common_dir": str(authority.common_dir),
            "common_mode": stat.S_IMODE(common_metadata.st_mode),
            "common_device": common_metadata.st_dev,
            "common_inode": common_metadata.st_ino,
            "root_mode": stat.S_IMODE(root_metadata.st_mode),
            "root_device": root_metadata.st_dev,
            "root_inode": root_metadata.st_ino,
        }

    common_dir = _workspace_authority_common_dir(cwd)
    root_metadata = cwd.lstat()
    common_metadata = common_dir.lstat()
    if (
        not stat.S_ISDIR(common_metadata.st_mode)
        or stat.S_ISLNK(common_metadata.st_mode)
    ):
        raise MutationJournalError(
            f"workspace authority common dir must be real: {common_dir}"
        )
    _assert_directory_restore_control(common_dir, common_metadata)
    path = common_dir / "crucible-workspace.lock"
    descriptor = os.open(
        path,
        os.O_RDWR | os.O_CREAT | getattr(os, "O_CLOEXEC", 0),
        0o600,
    )
    os.close(descriptor)
    metadata = path.lstat()
    if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
        raise MutationJournalError(
            f"workspace authority lock must be singly linked: {path}"
        )
    return {
        "path": str(path),
        "mode": stat.S_IMODE(metadata.st_mode),
        "device": metadata.st_dev,
        "inode": metadata.st_ino,
        "nlink": metadata.st_nlink,
        "xattrs": _xattr_inventory(path),
        "common_dir": str(common_dir),
        "common_mode": stat.S_IMODE(common_metadata.st_mode),
        "common_device": common_metadata.st_dev,
        "common_inode": common_metadata.st_ino,
        "root_mode": stat.S_IMODE(root_metadata.st_mode),
        "root_device": root_metadata.st_dev,
        "root_inode": root_metadata.st_ino,
    }


def _registry_directory(cwd: Path) -> Path:
    path = _workspace_authority_common_dir(cwd) / _REGISTRY_DIRECTORY
    try:
        metadata = path.lstat()
    except FileNotFoundError:
        path.mkdir(mode=0o700)
        metadata = path.lstat()
    if not stat.S_ISDIR(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
        raise MutationJournalError(
            f"mutation-journal registry must be a real directory: {path}"
        )
    return path


def _registry_marker_path(cwd: Path, transaction_id: str) -> Path:
    active = _active_workspace_mutation_authority(cwd)
    common_dir = (
        active.common_dir
        if active is not None
        else _workspace_authority_common_dir(cwd)
    )
    return (
        common_dir
        / _REGISTRY_DIRECTORY
        / f"{transaction_id}.json"
    )


def _assert_bound_workspace_registry_identity(
    cwd: Path,
    registry_fd: int,
    expected: os.stat_result,
    *,
    label: str,
) -> None:
    """Reprove one pinned registry against its authority-relative name."""

    authority = _assert_workspace_mutation_authority(cwd)
    try:
        held = os.fstat(registry_fd)
        current = os.stat(
            _REGISTRY_DIRECTORY,
            dir_fd=authority.common_descriptor,
            follow_symlinks=False,
        )
    except OSError as exc:
        raise MutationJournalError(
            f"cannot revalidate {label}: {exc}"
        ) from exc
    expected_identity = (expected.st_dev, expected.st_ino)
    expected_mode = stat.S_IMODE(expected.st_mode)
    if (
        not stat.S_ISDIR(held.st_mode)
        or not stat.S_ISDIR(current.st_mode)
        or stat.S_ISLNK(current.st_mode)
        or (held.st_dev, held.st_ino) != expected_identity
        or (current.st_dev, current.st_ino) != expected_identity
        or stat.S_IMODE(held.st_mode) != expected_mode
        or stat.S_IMODE(current.st_mode) != expected_mode
    ):
        raise MutationJournalError(f"{label} changed identity or mode")


@contextmanager
def _bound_workspace_registry_directory(
    cwd: Path,
) -> Iterator[tuple[Path, int]]:
    """Hold the exact registry below the active common-dir authority.

    Registry inspection and mutation must never reopen the child through its
    lexical path.  An editor or fault injector can replace that path with a
    symlink after the workspace lock is acquired; the advisory lock only
    serializes cooperating Crucible writers.  Open the child relative to the
    already-held common-directory descriptor and reprove that same inode is
    still installed before releasing it.
    """

    if _active_workspace_mutation_authority(cwd) is None:
        with workspace_mutation_lock(cwd):
            with _bound_workspace_registry_directory(cwd) as binding:
                yield binding
        return
    authority = _assert_workspace_mutation_authority(cwd)
    common_fd = authority.common_descriptor
    registry_path = authority.common_dir / _REGISTRY_DIRECTORY
    try:
        expected_registry = os.stat(
            _REGISTRY_DIRECTORY,
            dir_fd=common_fd,
            follow_symlinks=False,
        )
    except FileNotFoundError:
        private_fd: int | None = None
        try:
            private_name, private_fd, expected_registry = (
                _create_private_bound_workspace_directory(
                    common_fd,
                    label="mutation-journal registry",
                )
            )
            os.fchmod(private_fd, 0o700)
            _fsync_bound_directory(private_fd)
            _assert_workspace_mutation_authority(cwd)
            _publish_private_bound_workspace_directory(
                common_fd,
                private_name,
                _REGISTRY_DIRECTORY,
                private_fd,
                expected_registry,
                label="mutation-journal registry",
            )
            _fsync_bound_directory(common_fd)
        finally:
            if private_fd is not None:
                os.close(private_fd)
    registry_fd, opened = _open_authority_directory_at(
        common_fd,
        _REGISTRY_DIRECTORY,
        label="mutation-journal registry",
    )
    if (opened.st_dev, opened.st_ino) != (
        expected_registry.st_dev,
        expected_registry.st_ino,
    ):
        os.close(registry_fd)
        raise MutationJournalError(
            "mutation-journal registry changed before binding"
        )
    try:
        yield registry_path, registry_fd
    finally:
        try:
            held = os.fstat(registry_fd)
            current = os.stat(
                _REGISTRY_DIRECTORY,
                dir_fd=common_fd,
                follow_symlinks=False,
            )
            if (
                not stat.S_ISDIR(held.st_mode)
                or not stat.S_ISDIR(current.st_mode)
                or stat.S_ISLNK(current.st_mode)
                or (held.st_dev, held.st_ino)
                != (opened.st_dev, opened.st_ino)
                or stat.S_IMODE(held.st_mode)
                != stat.S_IMODE(opened.st_mode)
                or (current.st_dev, current.st_ino)
                != (opened.st_dev, opened.st_ino)
                or stat.S_IMODE(current.st_mode)
                != stat.S_IMODE(opened.st_mode)
            ):
                raise MutationJournalError(
                    "mutation-journal registry changed while held"
                )
            _assert_workspace_mutation_authority(cwd)
        except MutationJournalError:
            raise
        except (OSError, TypeError, ValueError) as exc:
            raise MutationJournalError(
                f"cannot revalidate mutation-journal registry: {exc}"
            ) from exc
        finally:
            os.close(registry_fd)


def _bound_registry_entry_names_at(registry_fd: int) -> tuple[str, ...]:
    """Return one stable, bounded registry-name snapshot from a held inode."""

    initial = _bounded_directory_names(
        registry_fd,
        label="mutation-journal registry",
        max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
    )
    final = _bounded_directory_names(
        registry_fd,
        label="mutation-journal registry",
        max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
    )
    if initial != final:
        raise MutationJournalError(
            "mutation-journal registry changed during inventory"
        )
    return initial


def _bound_registry_entry_names(cwd: Path) -> tuple[str, ...]:
    """Return one stable, bounded registry-name snapshot."""

    with _bound_workspace_registry_directory(cwd) as (
        _registry_path,
        registry_fd,
    ):
        return _bound_registry_entry_names_at(registry_fd)


def _write_bound_registry_marker_at(
    registry_fd: int,
    transaction_id: str,
    payload: bytes,
    *,
    expected_baseline_entries: Iterable[str],
) -> None:
    """Publish one marker through the held registry inode and verify it."""

    marker_name = f"{transaction_id}.json"
    expected_baseline = tuple(sorted(set(expected_baseline_entries)))
    if marker_name in expected_baseline:
        raise MutationJournalError(
            "mutation registry marker already exists in its baseline"
        )
    before_names = _bounded_directory_names(
        registry_fd,
        label="mutation-journal registry publication",
        max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
    )
    if before_names != expected_baseline:
        raise MutationJournalError(
            "mutation-journal registry changed before marker publication"
        )
    _publish_bound_regular_noreplace(
        registry_fd,
        marker_name,
        payload,
        label=f"mutation registry marker {transaction_id}",
    )
    observed, _metadata = _read_bound_regular_entry(
        registry_fd,
        marker_name,
        label=f"mutation registry marker {transaction_id}",
        max_bytes=max(len(payload), 1),
    )
    if observed != payload:
        raise MutationJournalError(
            "mutation registry marker changed after publication"
        )


def _write_bound_registry_marker(
    cwd: Path,
    transaction_id: str,
    payload: bytes,
    *,
    expected_baseline_entries: Iterable[str],
) -> None:
    """Publish one marker through a freshly held registry inode."""

    with _bound_workspace_registry_directory(cwd) as (
        _registry_path,
        registry_fd,
    ):
        _write_bound_registry_marker_at(
            registry_fd,
            transaction_id,
            payload,
            expected_baseline_entries=expected_baseline_entries,
        )


def _assert_registry_clear(
    cwd: Path,
    *,
    allowed_transaction_ids: Iterable[str] = (),
    _registry_binding: tuple[Path, int] | None = None,
) -> None:
    """Fail before snapshotting over another corpus's orphaned mutation."""

    allowed = frozenset(allowed_transaction_ids)
    blockers: list[str] = []
    with ExitStack() as stack:
        if _registry_binding is None:
            registry, registry_fd = stack.enter_context(
                _bound_workspace_registry_directory(cwd)
            )
        else:
            registry, registry_fd = _registry_binding
        initial_names = _bounded_directory_names(
            registry_fd,
            label="mutation-journal registry",
            max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
        )
        removed_names: set[str] = set()
        for name in initial_names:
            marker = registry / name
            try:
                metadata = os.stat(
                    name,
                    dir_fd=registry_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                blockers.append(f"registry entry disappeared: {marker}")
                continue
            cleanup_residue = re.fullmatch(
                r"\.crucible-cleanup-[0-9a-f]{64}",
                name,
            ) is not None
            if name.startswith(".tmp_") or cleanup_residue:
                if stat.S_ISREG(metadata.st_mode) and metadata.st_nlink == 1:
                    # Atomic-write residue predates marker publication and
                    # therefore cannot own source mutation.  Quarantine the
                    # exact opened inode before unlinking it; a process-death
                    # residue has the finite generic cleanup spelling above
                    # and is handled identically on the next preflight.
                    try:
                        _remove_bound_regular_entry(
                            registry_fd,
                            name,
                            label="mutation registry temporary",
                            expected_metadata=metadata,
                        )
                    except MutationJournalError:
                        raise
                    except (OSError, TypeError, ValueError) as exc:
                        raise MutationJournalError(
                            "cannot remove exact mutation registry temporary: "
                            f"{exc}"
                        ) from exc
                    removed_names.add(name)
                    continue
                blockers.append(f"invalid registry temporary {marker}")
                continue
            try:
                payload, _opened = _read_bound_regular_entry(
                    registry_fd,
                    name,
                    label=f"mutation registry entry {name!r}",
                    max_bytes=_CONTROL_FILE_MAX_BYTES,
                )
                record = json.loads(payload)
                if not isinstance(record, dict):
                    raise TypeError("registry record is not an object")
                transaction_id = str(record["transaction_id"])
                if name != f"{transaction_id}.json":
                    raise ValueError("registry filename does not match record")
            except (
                KeyError,
                TypeError,
                ValueError,
                json.JSONDecodeError,
                MutationJournalError,
            ):
                blockers.append(f"invalid registry record {marker}")
                continue
            if _is_live(transaction_id):
                continue
            if transaction_id in allowed:
                continue
            blockers.append(
                f"transaction {transaction_id} from "
                f"{record.get('spec_dir', '<unknown corpus>')} "
                f"(journal {record.get('journal_dir', '<unknown>')})"
            )
        final_names = _bounded_directory_names(
            registry_fd,
            label="mutation-journal registry",
            max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
        )
        if set(final_names) != set(initial_names).difference(removed_names):
            raise MutationJournalError(
                "mutation-journal registry changed during preflight"
            )
    if blockers:
        raise MutationJournalError(
            "orphaned workspace mutation from another run/corpus must be "
            "recovered before a new baseline is captured: "
            + "; ".join(blockers)
        )


def _originating_spec_dir(journal_root: Path) -> Path:
    resolved_root = journal_root.resolve()
    for parent in (resolved_root, *resolved_root.parents):
        if parent.name == "runs":
            return parent.parent.resolve()
    return resolved_root.parent.resolve()


def _originating_spec_dir_lexical(journal_root: Path) -> Path:
    """Derive the Corpus root without resolving a replaceable journal path."""

    lexical_root = _lexical_workspace_path(journal_root)
    for parent in (lexical_root, *lexical_root.parents):
        if parent.name == "runs":
            return parent.parent
    return lexical_root.parent


def _git_control_path(cwd: Path, name: str) -> Path:
    rendered = os.fsdecode(_git(cwd, "rev-parse", "--git-path", name))
    if rendered.endswith("\r\n"):
        rendered = rendered[:-2]
    elif rendered.endswith("\n"):
        rendered = rendered[:-1]
    return _lexical_absolute_control_path(cwd, rendered)


def _capture_control_files(
    journal_dir: Path,
    cwd: Path,
    symbolic_head: str | None,
) -> list[dict[str, object]]:
    # Snapshot both durable controls and their lock-file namespaces. A model
    # that strands (for example) ``index.lock`` otherwise prevents every later
    # Git write even though HEAD, refs, and the index itself still compare
    # equal to the transaction baseline.
    names = [
        "HEAD",
        "HEAD.lock",
        "ORIG_HEAD",
        "ORIG_HEAD.lock",
        "FETCH_HEAD",
        "FETCH_HEAD.lock",
        "COMMIT_EDITMSG",
        "COMMIT_EDITMSG.lock",
        "MERGE_HEAD",
        "MERGE_HEAD.lock",
        "MERGE_MSG",
        "MERGE_MSG.lock",
        "MERGE_RR",
        "MERGE_RR.lock",
        "SQUASH_MSG",
        "SQUASH_MSG.lock",
        "CHERRY_PICK_HEAD",
        "CHERRY_PICK_HEAD.lock",
        "REVERT_HEAD",
        "REVERT_HEAD.lock",
        "REBASE_HEAD",
        "REBASE_HEAD.lock",
        "BISECT_HEAD",
        "BISECT_HEAD.lock",
        "BISECT_START",
        "BISECT_START.lock",
        "BISECT_LOG",
        "BISECT_LOG.lock",
        "BISECT_NAMES",
        "BISECT_NAMES.lock",
        "BISECT_RUN",
        "BISECT_RUN.lock",
        "AUTO_MERGE",
        "AUTO_MERGE.lock",
        "shallow",
        "shallow.lock",
        "config",
        "config.lock",
        "config.worktree",
        "config.worktree.lock",
        "info/grafts",
        "info/grafts.lock",
        "info/exclude",
        "info/exclude.lock",
        "info/attributes",
        "info/attributes.lock",
        "info/sparse-checkout",
        "info/sparse-checkout.lock",
        "logs/HEAD",
        "logs/HEAD.lock",
        "index.lock",
        "packed-refs",
        "packed-refs.lock",
    ]
    if symbolic_head is not None:
        names.extend((symbolic_head, f"{symbolic_head}.lock"))
    records: list[dict[str, object]] = []
    seen: set[Path] = set()
    control_dir = journal_dir / "git_controls"
    for name in names:
        path = _git_control_path(cwd, name)
        if path in seen:
            continue
        seen.add(path)
        try:
            metadata = path.lstat()
        except FileNotFoundError:
            records.append({
                "name": name,
                "path": str(path),
                "exists": False,
            })
            continue
        if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
            raise MutationJournalError(
                f"Git control file must be a singly-linked regular file: {path}"
            )
        snapshot = str(len(records))
        payload = path.read_bytes()
        write_atomic_bytes(control_dir / snapshot, payload)
        records.append({
            "name": name,
            "path": str(path),
            "exists": True,
            "mode": stat.S_IMODE(metadata.st_mode),
            "snapshot": snapshot,
            "xattrs": _xattr_inventory(path),
            **_capture_snapshot_blob_record(journal_dir, payload),
        })
    return records


def _capture_refs_tree(
    journal_dir: Path,
    refs_root: Path,
    *,
    snapshot_name: str = "git_refs",
    require_restore_control: bool = False,
) -> dict[str, dict[str, object]]:
    """Snapshot the physical loose-ref namespace without following aliases."""

    if require_restore_control:
        root_metadata = refs_root.lstat()
        if not stat.S_ISDIR(root_metadata.st_mode) or stat.S_ISLNK(
            root_metadata.st_mode
        ):
            raise MutationJournalError(
                f"Git administrative tree must be a real directory: {refs_root}"
            )
        _assert_directory_restore_control(refs_root, root_metadata)
    records: dict[str, dict[str, object]] = {}
    snapshot_dir = journal_dir / snapshot_name
    candidates: list[Path] = []
    for current_path, dirs, files in _walk_complete_real_tree(
        refs_root,
        tree_label="Git administrative tree",
    ):
        candidates.extend(current_path / name for name in (*dirs, *files))
    for candidate in sorted(
        candidates,
        key=lambda path: (
            len(path.relative_to(refs_root).parts),
            path.relative_to(refs_root).as_posix(),
        ),
    ):
        relative = candidate.relative_to(refs_root).as_posix()
        metadata = candidate.lstat()
        if stat.S_ISDIR(metadata.st_mode) and not stat.S_ISLNK(metadata.st_mode):
            if require_restore_control:
                _assert_directory_restore_control(candidate, metadata)
            records[relative] = {
                "kind": "directory",
                "mode": stat.S_IMODE(metadata.st_mode),
                "device": metadata.st_dev,
                "inode": metadata.st_ino,
                "xattrs": _xattr_inventory(candidate),
            }
            continue
        if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
            raise MutationJournalError(
                "Git loose-ref entries must be singly-linked regular files "
                f"or real directories: {candidate}"
            )
        snapshot = str(len(records))
        payload = candidate.read_bytes()
        write_atomic_bytes(snapshot_dir / snapshot, payload)
        records[relative] = {
            "kind": "file",
            "mode": stat.S_IMODE(metadata.st_mode),
            "snapshot": snapshot,
            "xattrs": _xattr_inventory(candidate),
            **_capture_snapshot_blob_record(journal_dir, payload),
        }
    return records


def _refs_tree_matches(
    journal_dir: Path,
    refs_root: Path,
    expected: dict[str, dict[str, object]],
    *,
    snapshot_name: str = "git_refs",
) -> bool:
    try:
        current = _capture_refs_tree(
            journal_dir / "refs_probe",
            refs_root,
            snapshot_name=snapshot_name,
        )
    finally:
        shutil.rmtree(journal_dir / "refs_probe", ignore_errors=True)
    if set(current) != set(expected):
        return False
    for relative, record in expected.items():
        observed = current[relative]
        if (
            observed.get("kind") != record.get("kind")
            or observed.get("mode") != record.get("mode")
            or observed.get("xattrs", {}) != record.get("xattrs", {})
        ):
            return False
        if record.get("kind") == "file":
            expected_payload = (
                journal_dir / snapshot_name / str(record["snapshot"])
            ).read_bytes()
            if (refs_root / relative).read_bytes() != expected_payload:
                return False
    return True


def _capture_git_admin_topology(
    journal_dir: Path,
    cwd: Path,
) -> list[dict[str, object]]:
    roots = tuple(dict.fromkeys((_git_common_dir(cwd), _git_dir(cwd))))
    captured: list[dict[str, object]] = []
    for root_index, root in enumerate(roots):
        root_metadata = root.lstat()
        if not stat.S_ISDIR(root_metadata.st_mode) or stat.S_ISLNK(
            root_metadata.st_mode
        ):
            raise MutationJournalError(
                f"Git admin root must be a real directory: {root}"
            )
        _assert_directory_restore_control(root, root_metadata)
        entries: dict[str, dict[str, object]] = {}
        for path in sorted(root.iterdir(), key=lambda candidate: candidate.name):
            metadata = path.lstat()
            name = path.name
            if stat.S_ISREG(metadata.st_mode):
                if metadata.st_nlink != 1:
                    raise MutationJournalError(
                        f"Git admin file must not be hard-linked: {path}"
                    )
                if name == "crucible-workspace.lock":
                    entries[name] = {
                        "kind": "authority_lock",
                        "mode": stat.S_IMODE(metadata.st_mode),
                        "device": metadata.st_dev,
                        "inode": metadata.st_ino,
                        "nlink": metadata.st_nlink,
                        "xattrs": _xattr_inventory(path),
                    }
                    continue
                if name == "index":
                    entries[name] = {
                        "kind": "owned_file",
                        "mode": stat.S_IMODE(metadata.st_mode),
                        "device": metadata.st_dev,
                        "uid": metadata.st_uid,
                        "gid": metadata.st_gid,
                        "xattrs": _xattr_inventory(path),
                    }
                    continue
                snapshot = f"root_{root_index}_file_{len(entries)}"
                payload = path.read_bytes()
                write_atomic_bytes(
                    journal_dir / "git_admin_topology" / snapshot,
                    payload,
                )
                entries[name] = {
                    "kind": "file",
                    "mode": stat.S_IMODE(metadata.st_mode),
                    "snapshot": snapshot,
                    "xattrs": _xattr_inventory(path),
                    **_capture_snapshot_blob_record(journal_dir, payload),
                }
                continue
            if not stat.S_ISDIR(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
                raise MutationJournalError(
                    f"unsupported Git admin top-level entry: {path}"
                )
            _assert_directory_restore_control(path, metadata)
            if name in _MODE_ONLY_GIT_ADMIN_DIRECTORIES:
                entries[name] = {
                    "kind": "owned_directory",
                    "mode": stat.S_IMODE(metadata.st_mode),
                    "device": metadata.st_dev,
                    "inode": metadata.st_ino,
                    "xattrs": _xattr_inventory(path),
                }
                continue
            entry_count = 0
            total_bytes = 0
            for current_path, dirs, files in _walk_complete_real_tree(
                path,
                tree_label="custom Git administrative tree",
            ):
                for child_name in (*dirs, *files):
                    child = current_path / child_name
                    child_metadata = child.lstat()
                    if stat.S_ISLNK(child_metadata.st_mode):
                        raise MutationJournalError(
                            f"custom Git admin tree contains symlink: {child}"
                        )
                    entry_count += 1
                    if stat.S_ISREG(child_metadata.st_mode):
                        total_bytes += child_metadata.st_size
                    if entry_count > 10_000 or total_bytes > 16 * 1024 * 1024:
                        raise MutationJournalError(
                            f"unsupported large custom Git admin tree: {path}"
                        )
            snapshot_name = f"git_admin_unknown_{root_index}_{len(entries)}"
            tree = _capture_refs_tree(
                journal_dir,
                path,
                snapshot_name=snapshot_name,
                require_restore_control=True,
            )
            entries[name] = {
                "kind": "guarded_directory",
                "mode": stat.S_IMODE(metadata.st_mode),
                "device": metadata.st_dev,
                "inode": metadata.st_ino,
                "snapshot_name": snapshot_name,
                "entries": tree,
                "xattrs": _xattr_inventory(path),
            }
        captured.append({
            "root": str(root),
            "mode": stat.S_IMODE(root_metadata.st_mode),
            "device": root_metadata.st_dev,
            "inode": root_metadata.st_ino,
            "xattrs": _xattr_inventory(root),
            "entries": entries,
        })
    return captured


def _capture_auxiliary_git_trees(
    journal_dir: Path,
    cwd: Path,
) -> tuple[list[dict[str, object]], dict[str, object] | None]:
    """Capture executable/operation Git-admin directories exactly."""

    records: list[dict[str, object]] = []
    disabled_git_hooks: dict[str, object] | None = None
    for index, name in enumerate((
        "hooks",
        "sequencer",
        "rebase-apply",
        "rebase-merge",
        "rr-cache",
    )):
        path = _auxiliary_git_tree_path(cwd, name)
        disabled_hooks = (
            _disabled_git_hooks_device(path)
            if name == "hooks" else None
        )
        if disabled_hooks is not None:
            # ``core.hooksPath=/dev/null`` is a common, explicit way to
            # disable hook execution.  The device is outside this
            # transaction's mutation authority, so bind its null-device
            # identity separately but never put it in the restorable tree
            # list.  Older v2 recovery code safely ignores this optional
            # manifest field instead of trying to unlink the device.
            disabled_git_hooks = {
                "path": str(path),
                "rdev": disabled_hooks.st_rdev,
            }
            continue
        if name == "hooks" and (
            path == journal_dir.resolve()
            or path in journal_dir.resolve().parents
            or journal_dir.resolve() in path.parents
        ):
            raise MutationJournalError(
                f"configured Git hooks path overlaps mutation journal: {path}"
            )
        try:
            metadata = path.lstat()
        except FileNotFoundError:
            records.append({
                "name": name,
                "path": str(path),
                "exists": False,
                "snapshot_name": f"git_aux_{index}",
                "entries": {},
            })
            continue
        if not stat.S_ISDIR(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
            raise MutationJournalError(
                f"Git administrative tree must be a real directory: {path}"
            )
        snapshot_name = f"git_aux_{index}"
        records.append({
            "name": name,
            "path": str(path),
            "exists": True,
            "mode": stat.S_IMODE(metadata.st_mode),
            "device": metadata.st_dev,
            "inode": metadata.st_ino,
            "xattrs": _xattr_inventory(path),
            "snapshot_name": snapshot_name,
            "entries": _capture_refs_tree(
                journal_dir,
                path,
                snapshot_name=snapshot_name,
                require_restore_control=True,
            ),
        })
    return records, disabled_git_hooks


def _disabled_git_hooks_device(path: Path) -> os.stat_result | None:
    """Return metadata only for the canonical platform null device.

    No other external file, device, or symlink is accepted as a disabled
    hooks sentinel.  In particular, retaining the final path component while
    resolving its parent prevents a lookalike symlink from gaining this
    exception.
    """

    null_path = Path(os.devnull)
    if not null_path.is_absolute():
        return None
    canonical_null = null_path.parent.resolve() / null_path.name
    if path != canonical_null:
        return None
    try:
        metadata = path.lstat()
    except FileNotFoundError:
        return None
    if not stat.S_ISCHR(metadata.st_mode):
        return None
    return metadata


def _auxiliary_git_tree_path(cwd: Path, name: str) -> Path:
    if name == "hooks":
        # Query without Crucible's temporary hooksPath=/dev/null override so a
        # repository-owned custom hooks directory (for example ``.githooks``)
        # is protected too. External/global hook trees are rejected: this
        # transaction has no authority to snapshot or restore them.  The
        # canonical null character device is the sole exception because it
        # disables hooks and is bound as a non-restorable sentinel.
        result = _run_bound_git_process(
            cwd,
            [
                "git", *_GIT_STABILITY_OPTIONS,
                "rev-parse", "--git-path", "hooks",
            ],
        )
        if result.returncode != 0:
            raise MutationJournalError(
                "cannot resolve configured Git hooks path: "
                + result.stderr.decode("utf-8", errors="replace").strip()
            )
        rendered = os.fsdecode(result.stdout)
        if rendered.endswith("\r\n"):
            rendered = rendered[:-2]
        elif rendered.endswith("\n"):
            rendered = rendered[:-1]
        path = _lexical_absolute_control_path(cwd, rendered)
        if _disabled_git_hooks_device(path) is not None:
            return path
        # During recovery ``cwd`` is deliberately a /proc/self/fd alias for
        # the already-held checkout inode.  Keep that lexical authority in
        # addition to the public resolved spelling; resolving it away and
        # then comparing a relative ``hooks`` result incorrectly classifies
        # the descriptor-bound path as external.
        workspace_alias = _lexical_workspace_path(cwd)
        workspace = cwd.resolve()
        common = _git_common_dir(cwd)
        descriptor_binding = _held_authority_descriptor_path(path)
        if not (
            descriptor_binding is not None
            or workspace_alias in path.parents
            or workspace in path.parents
            or common in path.parents
        ):
            raise MutationJournalError(
                f"configured Git hooks path escapes workspace/admin roots: {path}"
            )
        protected = (
            _objects_path(cwd),
            _refs_path(cwd),
            common / "logs",
            common / _REGISTRY_DIRECTORY,
            _index_path(cwd),
        )
        if any(
            path == root or path in root.parents or root in path.parents
            for root in protected
        ):
            raise MutationJournalError(
                f"configured Git hooks path overlaps protected Git state: {path}"
            )
        return path
    return _git_control_path(cwd, name)


def _object_inventory(
    cwd: Path,
    *,
    require_restore_control: bool = False,
) -> tuple[Path, dict[str, dict[str, object]]]:
    root = _objects_path(cwd)
    root_metadata: os.stat_result | None = None
    if require_restore_control:
        root_metadata = root.lstat()
        if not stat.S_ISDIR(root_metadata.st_mode) or stat.S_ISLNK(
            root_metadata.st_mode
        ):
            raise MutationJournalError(
                f"Git object root must be a real directory: {root}"
            )
        _assert_directory_restore_control(root, root_metadata)
    inventory: dict[str, dict[str, object]] = {}

    def capture(candidate: Path, metadata: os.stat_result) -> None:
        relative = candidate.relative_to(root).as_posix()
        if stat.S_ISDIR(metadata.st_mode) and not stat.S_ISLNK(metadata.st_mode):
            if require_restore_control:
                _assert_directory_restore_control(candidate, metadata)
            inventory[relative] = {
                "kind": "directory",
                "mode": stat.S_IMODE(metadata.st_mode),
                "device": metadata.st_dev,
                "inode": metadata.st_ino,
                "xattrs": _xattr_inventory(candidate),
            }
            return
        kind = (
            "file" if stat.S_ISREG(metadata.st_mode)
            else "symlink" if stat.S_ISLNK(metadata.st_mode)
            else "other"
        )
        inventory[relative] = {
            "kind": kind,
            "mode": stat.S_IMODE(metadata.st_mode),
            "device": metadata.st_dev,
            "inode": metadata.st_ino,
            "nlink": metadata.st_nlink,
            "size": metadata.st_size,
            "mtime_ns": metadata.st_mtime_ns,
            "ctime_ns": metadata.st_ctime_ns,
            "xattrs": _xattr_inventory(candidate),
        }

    for current_path, dirs, files in _walk_complete_real_tree(
        root,
        tree_label=(
            "Git object baseline inventory"
            if require_restore_control
            else "Git object inventory"
        ),
    ):
        retained: list[str] = []
        for name in dirs:
            candidate = current_path / name
            metadata = candidate.lstat()
            capture(candidate, metadata)
            if stat.S_ISDIR(metadata.st_mode) and not stat.S_ISLNK(
                metadata.st_mode
            ):
                retained.append(name)
        dirs[:] = retained

        for name in files:
            candidate = current_path / name
            capture(candidate, candidate.lstat())
    return root, inventory


def _timestamp_only_object_changes(
    expected: dict[str, dict[str, object]],
    current: dict[str, dict[str, object]],
    *,
    allow_additions: bool = False,
) -> set[str] | None:
    """Return timestamp-only drift on canonical Git object payloads."""

    expected_paths = set(expected)
    current_paths = set(current)
    if (
        not expected_paths.issubset(current_paths)
        or (not allow_additions and current_paths != expected_paths)
    ):
        return None
    changes = {
        path
        for path in expected
        if current[path] != expected[path]
    }
    if not changes:
        return set()
    ignored = {"ctime_ns", "mtime_ns"}
    for path in changes:
        loose = re.fullmatch(
            r"[0-9a-f]{2}/(?:[0-9a-f]{38}|[0-9a-f]{62})",
            path,
        )
        match = re.fullmatch(
            r"pack/pack-([0-9a-f]{40}|[0-9a-f]{64})\.pack",
            path,
        )
        if (
            expected[path].get("kind") != "file"
            or current[path].get("kind") != "file"
            or (loose is None and match is None)
        ):
            return None
        expected_authority = {
            key: value
            for key, value in expected[path].items()
            if key not in ignored
        }
        current_authority = {
            key: value
            for key, value in current[path].items()
            if key not in ignored
        }
        if current_authority != expected_authority:
            return None
        if loose is not None:
            if (
                expected[path].get("nlink") != 1
                or current[path].get("nlink") != 1
            ):
                return None
            continue
        assert match is not None
        index_path = f"pack/pack-{match.group(1)}.idx"
        expected_index = expected.get(index_path)
        current_index = current.get(index_path)
        if (
            expected_index is None
            or current_index is None
            or expected_index != current_index
            or expected_index.get("kind") != "file"
            or expected_index.get("nlink") != 1
            or current_index.get("kind") != "file"
            or current_index.get("nlink") != 1
        ):
            return None
    return changes


def _index_semantic_views(cwd: Path, index: Path) -> tuple[bytes, bytes, bytes]:
    """Capture staged entries plus assume-unchanged/skip-worktree flags."""
    def _view(*args: str) -> bytes:
        result = _run_bound_git_process(
            cwd,
            ["git", *_GIT_SAFE_OPTIONS, "ls-files", *args],
            GIT_INDEX_FILE=str(index),
        )
        if result.returncode != 0:
            raise MutationJournalError(
                "cannot inspect Git index semantics: "
                + result.stderr.decode("utf-8", errors="replace").strip()
            )
        return result.stdout

    return (
        _view("--stage", "-z"),
        _view("-v", "-z"),
        _view("-f", "-z"),
    )


def _hidden_index_paths(verbose_view: bytes) -> tuple[str, ...]:
    hidden: list[str] = []
    for record in verbose_view.split(b"\0"):
        if len(record) < 3:
            continue
        tag = record[:1]
        if tag == b"S" or (b"a" <= tag <= b"z"):
            hidden.append(os.fsdecode(record[2:]))
    return tuple(hidden)


def _normalize_relative(cwd: Path, rendered: str) -> str:
    """Canonically validate an already-worktree-relative machine path."""

    normalized = rendered.replace("\\", "/") if os.name == "nt" else rendered
    candidate = PurePosixPath(normalized)
    if candidate.is_absolute() or ".." in candidate.parts:
        raise MutationJournalError(
            f"mutation scope escapes checkout: {rendered!r}"
        )
    text = candidate.as_posix()
    if (
        text in {"", "."}
        or any(
            part.casefold() in _VCS_METADATA_COMPONENTS
            for part in candidate.parts
        )
    ):
        raise MutationJournalError(
            f"mutation scope may not target Git metadata: {rendered!r}"
        )
    target = cwd / text
    try:
        # Resolve parent components to reject ``dir -> /outside`` traversal,
        # but do not resolve the final component: a tracked symlink is itself
        # a legitimate path to snapshot/replace even when its target is
        # outside the checkout.
        logical_root = cwd.resolve(strict=True)
        target.parent.resolve(strict=False).relative_to(logical_root)
    except ValueError as exc:
        raise MutationJournalError(
            f"mutation scope escapes checkout: {rendered!r}"
        ) from exc
    return text


def _normalize_directive_scope(cwd: Path, rendered: str) -> str:
    """Apply the planner's optional redundant-cwd prefix exactly once."""

    normalized = rendered.replace("\\", "/") if os.name == "nt" else rendered
    candidate = PurePosixPath(normalized)
    parts = candidate.parts
    if parts and parts[0] == cwd.name and len(parts) > 1:
        unstripped = cwd.joinpath(*parts)
        if not unstripped.exists() and not unstripped.parent.is_dir():
            candidate = PurePosixPath(*parts[1:])
    return _normalize_relative(cwd, candidate.as_posix())


def normalize_scope_path(cwd: str | Path, rendered: str) -> str:
    """Public workflow-level path normalization shared with tier fan-out."""

    return _normalize_directive_scope(Path(cwd).resolve(), rendered)


def _normalize_scope_authority(
    cwd: Path,
    rendered_scope: Iterable[str],
) -> tuple[tuple[str, ...], set[str]]:
    """Return canonical scope roots and the subset authorized recursively.

    A trailing separator is authored authority for a directory even when the
    directory does not exist yet.  ``PurePosixPath`` necessarily removes that
    separator while canonicalizing the path, so retain the intent alongside
    the normalized root rather than trying to infer it from the live tree.
    Existing real directories remain recursive for compatibility with older
    directives that did not include a trailing separator.
    """

    normalized: list[str] = []
    recursive: set[str] = set()
    for rendered in rendered_scope:
        normalized_root = _normalize_directive_scope(cwd, rendered)
        if normalized_root not in normalized:
            normalized.append(normalized_root)
        separator_normalized = (
            rendered.replace("\\", "/") if os.name == "nt" else rendered
        )
        target = cwd / normalized_root
        authored_recursive = separator_normalized.endswith("/")
        if authored_recursive:
            try:
                metadata = target.lstat()
            except FileNotFoundError:
                metadata = None
            if metadata is not None and (
                not stat.S_ISDIR(metadata.st_mode)
                or stat.S_ISLNK(metadata.st_mode)
            ):
                raise MutationJournalError(
                    "recursive mutation scope must be absent or a real "
                    f"directory: {rendered!r}"
                )
        if authored_recursive or (
            target.is_dir() and not target.is_symlink()
        ):
            recursive.add(normalized_root)
    return tuple(normalized), recursive


def normalize_workspace_path(cwd: str | Path, rendered: str) -> str:
    """Validate a Git/manifest path without planner-prefix reinterpretation."""

    return _normalize_relative(Path(cwd).resolve(), rendered)


def _blob_path(journal_dir: Path, digest: str) -> Path:
    return journal_dir / "blobs" / digest


def _capture_snapshot_blob_record(
    journal_dir: Path,
    payload: bytes,
) -> dict[str, int | str]:
    """Persist one content-addressed snapshot and return its exact binding.

    Git-administration snapshots historically lived only at descriptive
    journal paths (``git_refs/3``, ``git_controls/7``, and so on).  Those
    names are useful for an operator, but they are not restore authority: a
    replaced file, symlink, FIFO, or stale partial write at such a name could
    otherwise become bytes written back into the repository.  Every
    restorable payload is therefore also bound to the journal's no-follow
    ``blobs/<sha256>`` namespace and the manifest records both digest and
    length.
    """

    digest = hashlib.sha256(payload).hexdigest()
    blob = _blob_path(journal_dir, digest)
    try:
        metadata = blob.lstat()
    except FileNotFoundError:
        write_atomic_bytes(blob, payload)
    else:
        if (
            not stat.S_ISREG(metadata.st_mode)
            or stat.S_ISLNK(metadata.st_mode)
            or metadata.st_nlink != 1
            or metadata.st_size != len(payload)
            or blob.read_bytes() != payload
        ):
            raise MutationJournalError(
                f"mutation snapshot blob conflicts with its digest: {blob}"
            )
    return {"sha256": digest, "size": len(payload)}


def _stage_zero_blob_oids(
    cwd: Path,
    paths: Iterable[str],
) -> dict[str, str]:
    selected = set(paths)
    result: dict[str, str] = {}
    for record in _git(cwd, "ls-files", "--stage", "-z").split(b"\0"):
        if not record:
            continue
        metadata, separator, encoded_path = record.partition(b"\t")
        fields = metadata.split()
        relative = os.fsdecode(encoded_path)
        if (
            not separator
            or len(fields) != 3
            or relative not in selected
            or fields[0] not in {b"100644", b"100755"}
            or fields[2] != b"0"
        ):
            continue
        result[relative] = fields[1].decode("ascii")
    return result


def _available_blob_oids(
    cwd: Path,
    expected_sizes: dict[str, int],
) -> set[str]:
    """Return object IDs locally readable as blobs of the expected size."""

    if not expected_sizes:
        return set()
    requested = sorted(expected_sizes)
    result = _run_bound_git_process(
        cwd,
        [
            "git",
            *_GIT_SAFE_OPTIONS,
            "cat-file",
            "--batch-check=%(objectname) %(objecttype) %(objectsize)",
        ],
        input_bytes=("\n".join(requested) + "\n").encode("ascii"),
        GIT_NO_LAZY_FETCH="1",
        GIT_NO_REPLACE_OBJECTS="1",
    )
    if result.returncode != 0:
        raise MutationJournalError(
            "cannot inspect transforming-path Git blobs: "
            + result.stderr.decode("utf-8", errors="replace").strip()
        )
    lines = result.stdout.splitlines()
    if len(lines) != len(requested):
        raise MutationJournalError(
            "malformed transforming-path git cat-file output"
        )
    available: set[str] = set()
    for requested_oid, line in zip(requested, lines, strict=True):
        fields = line.split()
        if len(fields) != 3:
            continue
        observed_oid, kind, encoded_size = fields
        try:
            size = int(encoded_size)
        except ValueError:
            continue
        if (
            observed_oid.decode("ascii", errors="ignore") == requested_oid
            and kind == b"blob"
            and size == expected_sizes[requested_oid]
        ):
            available.add(requested_oid)
    return available


def _raw_object_restore_bindings(
    cwd: Path,
    transforming_paths: Iterable[str],
    *,
    already_snapshotted: Iterable[str],
) -> tuple[dict[str, dict[str, object]], set[str]]:
    """Bind canonical worktree bytes to blobs; identify physical snapshots.

    A Git-clean text path can still have a physical CRLF/encoding image that
    differs from its index blob.  Such paths must be copied into the journal.
    When the byte image hashes to the stage-0 blob, retaining the object ID and
    an independent SHA-256 digest is sufficient and avoids duplicating every
    text file in repositories with wildcard ``text=auto`` rules.
    """

    transform_set = set(transforming_paths)
    excluded = set(already_snapshotted)
    candidates = transform_set.difference(excluded)
    index_oids = _stage_zero_blob_oids(cwd, candidates)
    object_format = _git(cwd, "rev-parse", "--show-object-format").strip().decode(
        "ascii", errors="strict",
    )
    if object_format not in {"sha1", "sha256"}:
        raise MutationJournalError(
            f"unsupported Git object format for exact rollback: {object_format!r}"
        )

    provisional: dict[str, dict[str, object]] = {}
    snapshot_paths = transform_set.difference(candidates)
    for relative in sorted(candidates):
        target = cwd / relative
        oid = index_oids.get(relative)
        try:
            metadata = target.lstat()
        except FileNotFoundError:
            snapshot_paths.add(relative)
            continue
        if (
            oid is None
            or not stat.S_ISREG(metadata.st_mode)
            or metadata.st_nlink != 1
        ):
            snapshot_paths.add(relative)
            continue
        data = target.read_bytes()
        digest = hashlib.new(object_format)
        digest.update(f"blob {len(data)}\0".encode("ascii"))
        digest.update(data)
        if digest.hexdigest() != oid:
            snapshot_paths.add(relative)
            continue
        provisional[relative] = {
            "oid": oid,
            "sha256": hashlib.sha256(data).hexdigest(),
            "size": len(data),
            "mode": stat.S_IMODE(metadata.st_mode),
            "nlink": metadata.st_nlink,
            "xattrs": _xattr_inventory(target),
        }

    oid_sizes = {
        str(record["oid"]): int(cast(int | str, record["size"]))
        for record in provisional.values()
    }
    available = _available_blob_oids(cwd, oid_sizes)
    bindings: dict[str, dict[str, object]] = {}
    for relative, record in provisional.items():
        if record["oid"] not in available:
            snapshot_paths.add(relative)
            continue
        try:
            # Bind the actual object payload, not only its Git OID/type/size.
            # This independent SHA-256 proof makes replacement refs, object
            # corruption, and legacy-hash collisions fall back to a physical
            # journal snapshot before mutation starts.
            _read_bound_blob(cwd, relative, record)
        except MutationJournalError:
            snapshot_paths.add(relative)
            continue
        bindings[relative] = record
    return bindings, snapshot_paths


def _capture_one(journal_dir: Path, cwd: Path, relative: str) -> dict:
    target = cwd / relative
    try:
        metadata = target.lstat()
    except FileNotFoundError:
        return {"kind": "missing"}

    mode = stat.S_IMODE(metadata.st_mode)
    if stat.S_ISLNK(metadata.st_mode):
        if metadata.st_nlink != 1:
            raise MutationJournalError(
                f"mutation snapshot symlink must not be hard-linked: {relative}"
            )
        return {
            "kind": "symlink",
            "mode": mode,
            "target": os.readlink(target),
            "nlink": metadata.st_nlink,
            "xattrs": _xattr_inventory(target),
        }
    if stat.S_ISDIR(metadata.st_mode):
        return {
            "kind": "directory",
            "mode": mode,
            "xattrs": _xattr_inventory(target),
        }
    if not stat.S_ISREG(metadata.st_mode):
        raise MutationJournalError(
            f"unsupported special file in mutation snapshot: {relative}"
        )
    if metadata.st_nlink != 1:
        raise MutationJournalError(
            f"mutation snapshot file must not be hard-linked: {relative}"
        )

    data = target.read_bytes()
    digest = hashlib.sha256(data).hexdigest()
    blob = _blob_path(journal_dir, digest)
    if not blob.exists():
        write_atomic_bytes(blob, data)
    return {
        "kind": "file",
        "mode": mode,
        "sha256": digest,
        "size": len(data),
        "nlink": metadata.st_nlink,
        "xattrs": _xattr_inventory(target),
    }


_SETTLEMENT_STABLE_STAT_FIELDS = (
    "st_dev",
    "st_ino",
    "st_mode",
    "st_nlink",
    "st_size",
    "st_mtime_ns",
    "st_ctime_ns",
)


@dataclass
class _SettlementCaptureBudget:
    """Finite resource accounting for one exact lifecycle postimage."""

    paths: int = 0
    path_bytes: int = 0
    hashed_bytes: int = 0
    xattr_bytes: int = 0

    def add_path(self, relative: str) -> None:
        self.paths += 1
        self.path_bytes += len(os.fsencode(relative))
        if self.paths > _LIFECYCLE_SETTLEMENT_MAX_PATHS:
            raise MutationJournalError(
                "lifecycle settlement exceeds its path-count ceiling"
            )
        if self.path_bytes > _LIFECYCLE_SETTLEMENT_MAX_PATH_BYTES:
            raise MutationJournalError(
                "lifecycle settlement exceeds its path-bytes ceiling"
            )

    def add_hashed_bytes(self, count: int) -> None:
        self.hashed_bytes += count
        if self.hashed_bytes > _LIFECYCLE_SETTLEMENT_MAX_HASHED_BYTES:
            raise MutationJournalError(
                "lifecycle settlement exceeds its hashed-bytes ceiling"
            )

    def add_xattr_bytes(self, count: int) -> None:
        self.xattr_bytes += count
        if self.xattr_bytes > _LIFECYCLE_SETTLEMENT_MAX_XATTR_BYTES:
            raise MutationJournalError(
                "lifecycle settlement exceeds its xattr-bytes ceiling"
            )

    def as_record(self) -> dict[str, int]:
        return {
            "paths": self.paths,
            "path_bytes": self.path_bytes,
            "hashed_bytes": self.hashed_bytes,
            "xattr_bytes": self.xattr_bytes,
        }


def _settlement_relative_path(
    rendered: str,
    *,
    allow_terminal_vcs_metadata: bool = False,
) -> str:
    """Validate a machine path lexically without following live aliases."""

    normalized = rendered.replace("\\", "/") if os.name == "nt" else rendered
    candidate = PurePosixPath(normalized)
    if (
        candidate.is_absolute()
        or not candidate.parts
        or len(candidate.parts) > _LIFECYCLE_SETTLEMENT_MAX_DEPTH
        or any(part in {"", ".", ".."} for part in candidate.parts)
        or any(
            part.casefold() in _VCS_METADATA_COMPONENTS
            for part in (
                candidate.parts[:-1]
                if allow_terminal_vcs_metadata
                else candidate.parts
            )
        )
    ):
        raise MutationJournalError(
            f"invalid lifecycle settlement workspace path: {rendered!r}"
        )
    return candidate.as_posix()


@dataclass(frozen=True)
class _PendingDeleteQuarantine:
    """One exact, durable hosted-delete recovery mapping."""

    token: str
    target_relative: str
    quarantine_relative: str
    parent_chain: tuple[tuple[int, ...], ...]
    state: Literal["reserved", "bound"]
    quarantine_device: int | None
    quarantine_inode: int | None
    quarantine_mode: int | None
    quarantine_mount_id: int | None
    child_pid: int | None
    child_start_ticks: int | None
    boot_id: str

    def to_record(self) -> dict[str, object]:
        return {
            "token": self.token,
            "target_relative": self.target_relative,
            "quarantine_relative": self.quarantine_relative,
            "parent_chain": [list(identity) for identity in self.parent_chain],
            "state": self.state,
            "quarantine_device": self.quarantine_device,
            "quarantine_inode": self.quarantine_inode,
            "quarantine_mode": self.quarantine_mode,
            "quarantine_mount_id": self.quarantine_mount_id,
            "child_pid": self.child_pid,
            "child_start_ticks": self.child_start_ticks,
            "boot_id": self.boot_id,
        }


def _pending_delete_quarantine_relative(
    target_relative: str,
    token: str,
) -> str:
    """Derive the only private sibling name accepted by recovery."""

    target = PurePosixPath(_settlement_relative_path(target_relative))
    if not _PENDING_DELETE_TOKEN_RE.fullmatch(token):
        raise MutationJournalError("pending delete token is malformed")
    quarantine_name = (
        f".{target.name}.crucible-delete-{token}"
        f"{_PENDING_DELETE_QUARANTINE_SUFFIX}"
    )
    # Linux NAME_MAX is normally 255.  Use the portable lower bound here;
    # publication may apply a stricter filesystem-specific ceiling.
    if len(os.fsencode(quarantine_name)) > 255:
        raise MutationJournalError(
            "pending delete quarantine name exceeds its component ceiling"
        )
    parent = target.parent
    return (
        quarantine_name
        if parent == PurePosixPath(".")
        else (parent / quarantine_name).as_posix()
    )


def _parse_pending_delete_quarantine(
    raw: object,
    *,
    manifest: Mapping[str, object],
) -> _PendingDeleteQuarantine:
    """Parse one closed receipt whose target is an explicit scope root."""

    required = frozenset({
        "token",
        "target_relative",
        "quarantine_relative",
        "parent_chain",
        "state",
        "quarantine_device",
        "quarantine_inode",
        "quarantine_mode",
        "quarantine_mount_id",
        "child_pid",
        "child_start_ticks",
        "boot_id",
    })
    if not isinstance(raw, dict) or frozenset(raw) != required:
        raise MutationJournalError(
            "pending delete quarantine receipt has a malformed shape"
        )
    token = raw.get("token")
    target_rendered = raw.get("target_relative")
    quarantine_rendered = raw.get("quarantine_relative")
    state = raw.get("state")
    if (
        not isinstance(token, str)
        or not _PENDING_DELETE_TOKEN_RE.fullmatch(token)
        or not isinstance(target_rendered, str)
        or not isinstance(quarantine_rendered, str)
        or state not in {"reserved", "bound"}
    ):
        raise MutationJournalError(
            "pending delete quarantine receipt has malformed identity fields"
        )
    target_relative = _settlement_relative_path(target_rendered)
    quarantine_relative = _settlement_relative_path(quarantine_rendered)
    if target_relative != target_rendered:
        raise MutationJournalError(
            "pending delete target is not canonically relative"
        )
    expected_quarantine = _pending_delete_quarantine_relative(
        target_relative,
        token,
    )
    if quarantine_relative != quarantine_rendered or (
        quarantine_relative != expected_quarantine
    ):
        raise MutationJournalError(
            "pending delete quarantine does not match its target and token"
        )
    raw_scope = manifest.get("scope")
    if not isinstance(raw_scope, list) or any(
        not isinstance(path, str) for path in raw_scope
    ):
        raise MutationJournalError(
            "pending delete journal scope is malformed"
        )
    scope = tuple(_settlement_relative_path(path) for path in raw_scope)
    if tuple(raw_scope) != scope or target_relative not in scope:
        raise MutationJournalError(
            "pending delete target is not an explicit journal scope root"
        )

    raw_parent_chain = raw.get("parent_chain")
    expected_chain_length = len(PurePosixPath(target_relative).parts)
    if (
        not isinstance(raw_parent_chain, list)
        or len(raw_parent_chain) != expected_chain_length
    ):
        raise MutationJournalError(
            "pending delete parent chain has a malformed length"
        )
    parent_chain: list[tuple[int, ...]] = []
    for raw_identity in raw_parent_chain:
        if (
            not isinstance(raw_identity, list)
            or len(raw_identity) != 6
            or any(
                isinstance(value, bool) or not isinstance(value, int)
                for value in raw_identity
            )
        ):
            raise MutationJournalError(
                "pending delete parent chain has malformed identity fields"
            )
        device, inode, file_type, uid, gid, mount_id = raw_identity
        if (
            device < 0
            or inode <= 0
            or file_type != stat.S_IFDIR
            or uid < 0
            or gid < 0
            or mount_id <= 0
        ):
            raise MutationJournalError(
                "pending delete parent chain has unsafe identity fields"
            )
        parent_chain.append(tuple(raw_identity))

    bound_names = (
        "quarantine_device",
        "quarantine_inode",
        "quarantine_mode",
        "quarantine_mount_id",
        "child_pid",
        "child_start_ticks",
    )
    values = tuple(raw.get(name) for name in bound_names)
    boot_id = raw.get("boot_id")
    if (
        not isinstance(boot_id, str)
        or re.fullmatch(
            r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-"
            r"[0-9a-f]{4}-[0-9a-f]{12}",
            boot_id,
        )
        is None
    ):
        raise MutationJournalError(
            "pending delete receipt has a malformed boot identity"
        )
    if state == "reserved":
        if any(value is not None for value in values):
            raise MutationJournalError(
                "reserved pending delete receipt carries bound authority"
            )
    else:
        if any(
            isinstance(value, bool)
            or not isinstance(value, int)
            or value <= 0
            for value in values
        ):
            raise MutationJournalError(
                "bound pending delete receipt has malformed authority"
            )
        mode = cast(int, raw["quarantine_mode"])
        if not stat.S_ISDIR(mode) or stat.S_IMODE(mode) != 0o700:
            raise MutationJournalError(
                "bound pending delete quarantine is not a private directory"
            )

    receipt = _PendingDeleteQuarantine(
        token=token,
        target_relative=target_relative,
        quarantine_relative=quarantine_relative,
        parent_chain=tuple(parent_chain),
        state=cast(Literal["reserved", "bound"], state),
        quarantine_device=cast(int | None, raw["quarantine_device"]),
        quarantine_inode=cast(int | None, raw["quarantine_inode"]),
        quarantine_mode=cast(int | None, raw["quarantine_mode"]),
        quarantine_mount_id=cast(int | None, raw["quarantine_mount_id"]),
        child_pid=cast(int | None, raw["child_pid"]),
        child_start_ticks=cast(int | None, raw["child_start_ticks"]),
        boot_id=boot_id,
    )
    if receipt.to_record() != raw:
        raise MutationJournalError(
            "pending delete quarantine receipt is not canonical"
        )
    return receipt


def _pending_delete_quarantines(
    manifest: Mapping[str, object],
) -> tuple[_PendingDeleteQuarantine, ...]:
    """Return the bounded canonical pending-delete inventory."""

    raw = manifest.get(_PENDING_DELETE_QUARANTINES_KEY, [])
    if not isinstance(raw, list) or len(raw) > (
        _PENDING_DELETE_QUARANTINES_MAX
    ):
        raise MutationJournalError(
            "pending delete quarantine inventory is malformed or unbounded"
        )
    receipts = tuple(
        _parse_pending_delete_quarantine(item, manifest=manifest)
        for item in raw
    )
    if len({receipt.token for receipt in receipts}) != len(receipts):
        raise MutationJournalError(
            "pending delete quarantine inventory contains duplicate tokens"
        )
    return receipts


def _read_bounded_proc_entry(path: str, *, label: str) -> bytes:
    """Read one small kernel-owned procfs control without following aliases."""

    descriptor: int | None = None
    try:
        descriptor = os.open(
            path,
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_NONBLOCK", 0),
        )
        payload = bytearray()
        while True:
            chunk = os.read(descriptor, min(
                4096,
                _PENDING_DELETE_MAX_PROC_BYTES + 1 - len(payload),
            ))
            if not chunk:
                break
            payload.extend(chunk)
            if len(payload) > _PENDING_DELETE_MAX_PROC_BYTES:
                raise MutationJournalError(f"{label} exceeds its byte ceiling")
        return bytes(payload)
    except MutationJournalError:
        raise
    except OSError as exc:
        raise MutationJournalError(f"cannot read {label}: {exc}") from exc
    finally:
        if descriptor is not None:
            os.close(descriptor)


def _pending_delete_boot_id() -> str:
    try:
        rendered = _read_bounded_proc_entry(
            "/proc/sys/kernel/random/boot_id",
            label="kernel boot identity",
        ).decode("ascii").strip()
    except UnicodeError as exc:
        raise MutationJournalError("kernel boot identity is malformed") from exc
    if re.fullmatch(
        r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-"
        r"[0-9a-f]{4}-[0-9a-f]{12}",
        rendered,
    ) is None:
        raise MutationJournalError("kernel boot identity is malformed")
    return rendered


def _pending_delete_process_identity(pid: int) -> tuple[str, int] | None:
    """Return Linux process state/start ticks, or ``None`` after its exit."""

    try:
        payload = _read_bounded_proc_entry(
            f"/proc/{pid}/stat",
            label="pending delete child process identity",
        )
    except MutationJournalError as exc:
        if isinstance(exc.__cause__, FileNotFoundError):
            return None
        raise
    try:
        rendered = payload.decode("ascii")
        closing = rendered.rfind(") ")
        if closing < 0:
            raise ValueError
        fields = rendered[closing + 2:].split()
        state = fields[0]
        start_ticks = int(fields[19])
    except (IndexError, UnicodeError, ValueError) as exc:
        raise MutationJournalError(
            "pending delete child process identity is malformed"
        ) from exc
    if len(state) != 1 or start_ticks <= 0:
        raise MutationJournalError(
            "pending delete child process identity is malformed"
        )
    return state, start_ticks


def _pending_delete_mount_id(descriptor: int) -> int:
    """Return Linux mount identity for a held descriptor."""

    payload = _read_bounded_proc_entry(
        f"/proc/self/fdinfo/{descriptor}",
        label="pending delete mount identity",
    )
    mount_ids: list[int] = []
    for line in payload.splitlines():
        key, separator, value = line.partition(b":")
        if separator and key == b"mnt_id":
            try:
                mount_ids.append(int(value.strip()))
            except ValueError as exc:
                raise MutationJournalError(
                    "pending delete mount identity is malformed"
                ) from exc
    if len(mount_ids) != 1 or mount_ids[0] <= 0:
        raise MutationJournalError(
            "pending delete mount identity cannot be proved"
        )
    return mount_ids[0]


def _pending_delete_directory_identity(descriptor: int) -> tuple[int, ...]:
    """Return one rename-stable directory identity plus its mount ID."""

    opened = os.fstat(descriptor)
    if not stat.S_ISDIR(opened.st_mode):
        raise MutationJournalError(
            "pending delete parent-chain authority is not a directory"
        )
    return (
        opened.st_dev,
        opened.st_ino,
        stat.S_IFMT(opened.st_mode),
        opened.st_uid,
        opened.st_gid,
        _pending_delete_mount_id(descriptor),
    )


def _pending_delete_chain_matches(
    expected: tuple[tuple[int, ...], ...],
    observed: tuple[tuple[int, ...], ...],
    *,
    same_boot: bool,
) -> bool:
    """Compare persistent fields always and mount capabilities per boot."""

    return len(expected) == len(observed) and all(
        expected_identity[:5] == observed_identity[:5]
        and (
            not same_boot
            or expected_identity[5] == observed_identity[5]
        )
        for expected_identity, observed_identity in zip(
            expected,
            observed,
            strict=True,
        )
    )


def _close_pending_delete_owned_descriptor(
    owned: list[int],
    descriptor: int,
    *,
    label: str,
) -> None:
    """Detach one numeric fd before its sole close attempt."""

    try:
        owned.remove(descriptor)
    except ValueError as exc:
        raise MutationJournalError(
            f"{label} descriptor has no local close authority"
        ) from exc
    try:
        os.close(descriptor)
    except BaseException as exc:
        raise MutationJournalError(
            f"{label} descriptor close is indeterminate"
        ) from exc


def _settle_pending_delete_owned_descriptors(
    owned: list[int],
    *,
    label: str,
) -> None:
    """Close each still-owned fd once without retrying a numeric value."""

    failures: list[BaseException] = []
    while owned:
        descriptor = owned.pop()
        try:
            os.close(descriptor)
        except BaseException as exc:
            failures.append(exc)
    if failures:
        error = MutationJournalError(
            f"{label} descriptor settlement is indeterminate"
        )
        for failure in failures[1:]:
            error.add_note(
                "additional descriptor close failure: "
                f"{type(failure).__name__}: {failure}"
            )
        raise error from failures[0]


@contextmanager
def _open_pending_delete_parent(
    cwd: Path,
    receipt: _PendingDeleteQuarantine,
    *,
    root_descriptor: int | None = None,
    verify_receipt_chain: bool = True,
) -> Iterator[
    tuple[int, int, str, str, tuple[tuple[int, ...], ...]]
]:
    """Hold the receipt parent through a no-follow, same-mount root walk."""

    authority = (
        _assert_workspace_mutation_authority(cwd)
        if root_descriptor is None
        else None
    )
    root_fd = (
        authority.root_descriptor
        if authority is not None
        else cast(int, root_descriptor)
    )
    root_opened = os.fstat(root_fd)
    if not stat.S_ISDIR(root_opened.st_mode):
        raise MutationJournalError(
            "pending delete root descriptor is not a directory"
        )
    root_mount_id = _pending_delete_mount_id(root_fd)
    same_boot = receipt.boot_id == _pending_delete_boot_id()
    target = PurePosixPath(receipt.target_relative)
    quarantine = PurePosixPath(receipt.quarantine_relative)
    if target.parent != quarantine.parent:
        raise MutationJournalError(
            "pending delete quarantine is not adjacent to its target"
        )
    components = target.parts[:-1]
    flags = (
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    owned: list[int] = []
    descriptor = -1
    chain: list[tuple[int, ...]] = []
    yielded = False
    body_failed = False
    try:
        try:
            descriptor = os.dup(root_fd)
        except OSError as exc:
            raise MutationJournalError(
                "cannot duplicate pending delete root descriptor"
            ) from exc
        owned.append(descriptor)
        chain.append(_pending_delete_directory_identity(descriptor))
        if chain[0][5] != root_mount_id:
            raise MutationJournalError(
                "pending delete root mount identity changed while opening"
            )
        for component in components:
            child: int | None = None
            try:
                before = os.stat(
                    component,
                    dir_fd=descriptor,
                    follow_symlinks=False,
                )
                child = os.open(component, flags, dir_fd=descriptor)
                owned.append(child)
                opened = os.fstat(child)
                after = os.stat(
                    component,
                    dir_fd=descriptor,
                    follow_symlinks=False,
                )
            except OSError as exc:
                raise MutationJournalError(
                    "cannot safely traverse pending delete parent for "
                    f"{receipt.target_relative!r}: {exc}"
                ) from exc
            if (
                not stat.S_ISDIR(before.st_mode)
                or stat.S_ISLNK(before.st_mode)
                or not stat.S_ISDIR(opened.st_mode)
                or (before.st_dev, before.st_ino)
                != (opened.st_dev, opened.st_ino)
                or (after.st_dev, after.st_ino)
                != (opened.st_dev, opened.st_ino)
                or _pending_delete_mount_id(child) != root_mount_id
            ):
                raise MutationJournalError(
                    "pending delete parent changed identity, became an "
                    "alias, or crossed a mount boundary"
                )
            _close_pending_delete_owned_descriptor(
                owned,
                descriptor,
                label="pending delete traversed parent",
            )
            descriptor = child
            chain.append(_pending_delete_directory_identity(descriptor))
        observed_chain = tuple(chain)
        if verify_receipt_chain and not _pending_delete_chain_matches(
            receipt.parent_chain,
            observed_chain,
            same_boot=same_boot,
        ):
            raise MutationJournalError(
                "pending delete named parent chain differs from its receipt"
            )
        yielded = True
        try:
            yield (
                descriptor,
                root_mount_id,
                target.name,
                quarantine.name,
                observed_chain,
            )
        except BaseException:
            body_failed = True
            raise
    finally:
        reproof_failure: BaseException | None = None
        if yielded:
            reproof_owned: list[int] = []
            try:
                current = os.dup(root_fd)
                reproof_owned.append(current)
                reproof_chain = [
                    _pending_delete_directory_identity(current)
                ]
                for component in components:
                    child = os.open(component, flags, dir_fd=current)
                    reproof_owned.append(child)
                    _close_pending_delete_owned_descriptor(
                        reproof_owned,
                        current,
                        label="pending delete reproof parent",
                    )
                    current = child
                    if _pending_delete_mount_id(current) != root_mount_id:
                        raise MutationJournalError(
                            "pending delete parent crossed a mount boundary"
                        )
                    reproof_chain.append(
                        _pending_delete_directory_identity(current)
                    )
                if tuple(reproof_chain) != tuple(chain) or (
                    _pending_delete_directory_identity(current)
                    != _pending_delete_directory_identity(descriptor)
                ):
                    raise MutationJournalError(
                        "pending delete parent changed while held"
                    )
                if authority is None:
                    current_root = os.fstat(root_fd)
                    if (current_root.st_dev, current_root.st_ino) != (
                        root_opened.st_dev,
                        root_opened.st_ino,
                    ):
                        raise MutationJournalError(
                            "pending delete root descriptor changed while held"
                        )
                else:
                    _assert_workspace_mutation_authority(cwd)
            except BaseException as exc:
                reproof_failure = exc
            try:
                _settle_pending_delete_owned_descriptors(
                    reproof_owned,
                    label="pending delete parent reproof",
                )
            except BaseException as exc:
                reproof_failure = reproof_failure or exc
        cleanup_failure: BaseException | None = None
        try:
            _settle_pending_delete_owned_descriptors(
                owned,
                label="pending delete parent",
            )
        except BaseException as exc:
            cleanup_failure = exc
        if cleanup_failure is not None:
            if reproof_failure is not None:
                cleanup_failure.add_note(
                    "parent reproof also failed after "
                    f"{type(reproof_failure).__name__}: {reproof_failure}"
                )
            raise cleanup_failure
        if reproof_failure is not None:
            if not body_failed:
                raise reproof_failure
            logger.error(
                "pending delete parent also lost binding during failure: "
                "%s: %s",
                type(reproof_failure).__name__,
                reproof_failure,
            )


@contextmanager
def _open_pending_delete_quarantine(
    parent_fd: int,
    quarantine_name: str,
    *,
    expected_mount_id: int,
    allow_removed: bool = False,
) -> Iterator[tuple[int, os.stat_result] | None]:
    """Open one exact private qdir, yielding ``None`` when it is absent."""

    flags = (
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    descriptor: int | None = None
    try:
        try:
            before = os.stat(
                quarantine_name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            yield None
            return
        descriptor = os.open(quarantine_name, flags, dir_fd=parent_fd)
        opened = os.fstat(descriptor)
        after = os.stat(
            quarantine_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISDIR(before.st_mode)
            or stat.S_ISLNK(before.st_mode)
            or not stat.S_ISDIR(opened.st_mode)
            or (before.st_dev, before.st_ino)
            != (opened.st_dev, opened.st_ino)
            or (after.st_dev, after.st_ino)
            != (opened.st_dev, opened.st_ino)
            or stat.S_IMODE(opened.st_mode) != 0o700
            or opened.st_uid != os.geteuid()
            or _pending_delete_mount_id(descriptor) != expected_mount_id
        ):
            raise MutationJournalError(
                "pending delete quarantine binding is unsafe"
            )
        yield descriptor, opened
        try:
            current = os.stat(
                quarantine_name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            if not allow_removed:
                raise
            held = os.fstat(descriptor)
            if (held.st_dev, held.st_ino) != (
                opened.st_dev,
                opened.st_ino,
            ):
                raise MutationJournalError(
                    "removed pending delete quarantine changed while held"
                ) from None
            return
        held = os.fstat(descriptor)
        if (current.st_dev, current.st_ino) != (
            opened.st_dev,
            opened.st_ino,
        ) or (held.st_dev, held.st_ino) != (
            opened.st_dev,
            opened.st_ino,
        ):
            raise MutationJournalError(
                "pending delete quarantine changed while held"
            )
    except MutationJournalError:
        raise
    except OSError as exc:
        raise MutationJournalError(
            f"cannot bind pending delete quarantine: {exc}"
        ) from exc
    finally:
        if descriptor is not None:
            os.close(descriptor)


def _assert_pending_delete_quarantine_absent(
    cwd: Path,
    receipt: _PendingDeleteQuarantine,
    *,
    root_descriptor: int | None = None,
    parent_descriptor: int | None = None,
) -> None:
    """Prove the exact receipt qdir is absent from the held workspace."""

    if parent_descriptor is not None:
        if root_descriptor is None:
            raise MutationJournalError(
                "retained pending delete parent lacks root authority"
            )
        root_mount_id = _pending_delete_mount_id(root_descriptor)
        _authenticate_pending_delete_parent_descriptor(
            receipt,
            parent_descriptor,
            expected_mount_id=root_mount_id,
        )
        quarantine_name = PurePosixPath(receipt.quarantine_relative).name
        with _open_pending_delete_quarantine(
            parent_descriptor,
            quarantine_name,
            expected_mount_id=root_mount_id,
        ) as bound:
            if bound is not None:
                raise MutationJournalError(
                    "pending delete quarantine remains in the workspace"
                )
        return

    with _open_pending_delete_parent(
        cwd,
        receipt,
        root_descriptor=root_descriptor,
    ) as (
        parent_fd,
        root_mount_id,
        _target_name,
        quarantine_name,
        _parent_chain,
    ):
        with _open_pending_delete_quarantine(
            parent_fd,
            quarantine_name,
            expected_mount_id=root_mount_id,
        ) as bound:
            if bound is not None:
                raise MutationJournalError(
                    "pending delete quarantine remains in the workspace"
                )


def _assert_bound_pending_delete_quarantine(
    cwd: Path,
    receipt: _PendingDeleteQuarantine,
    *,
    require_empty: bool,
    root_descriptor: int | None = None,
    parent_descriptor: int | None = None,
) -> tuple[str, ...]:
    """Prove exact qdir identity and return its bounded entry inventory."""

    if receipt.state != "bound":
        raise MutationJournalError(
            "pending delete receipt has no bound quarantine authority"
        )
    @contextmanager
    def open_parent() -> Iterator[tuple[int, int, str]]:
        if parent_descriptor is not None:
            if root_descriptor is None:
                raise MutationJournalError(
                    "retained pending delete parent lacks root authority"
                )
            root_mount_id = _pending_delete_mount_id(root_descriptor)
            _authenticate_pending_delete_parent_descriptor(
                receipt,
                parent_descriptor,
                expected_mount_id=root_mount_id,
            )
            yield (
                parent_descriptor,
                root_mount_id,
                PurePosixPath(receipt.quarantine_relative).name,
            )
            return
        with _open_pending_delete_parent(
            cwd,
            receipt,
            root_descriptor=root_descriptor,
        ) as (
            parent_fd,
            root_mount_id,
            _target_name,
            quarantine_name,
            _parent_chain,
        ):
            yield parent_fd, root_mount_id, quarantine_name

    with open_parent() as (
        parent_fd,
        root_mount_id,
        quarantine_name,
    ):
        with _open_pending_delete_quarantine(
            parent_fd,
            quarantine_name,
            expected_mount_id=root_mount_id,
        ) as bound:
            if bound is None:
                raise MutationJournalError(
                    "bound pending delete quarantine is missing"
                )
            quarantine_fd, opened = bound
            if (
                opened.st_dev != receipt.quarantine_device
                or opened.st_ino != receipt.quarantine_inode
                or opened.st_mode != receipt.quarantine_mode
                or root_mount_id != receipt.quarantine_mount_id
            ):
                raise MutationJournalError(
                    "pending delete quarantine differs from its receipt"
                )
            entries = _bounded_directory_names(
                quarantine_fd,
                label="pending delete quarantine",
                max_entries=2,
            )
            if require_empty and entries:
                raise MutationJournalError(
                    "pending delete quarantine was not empty before child ACK"
                )
            if entries not in {(), (_PENDING_DELETE_PAYLOAD,)}:
                raise MutationJournalError(
                    "pending delete quarantine contains foreign entries"
                )
            return entries


def _authenticate_pending_delete_root_descriptor(
    manifest: Mapping[str, object],
    descriptor: int | None,
) -> None:
    """Bind a host-thread fd to the journal's captured checkout identity."""

    if descriptor is None:
        return
    if isinstance(descriptor, bool) or not isinstance(descriptor, int) or (
        descriptor < 0
    ):
        raise MutationJournalError(
            "pending delete root descriptor is malformed"
        )
    expected = manifest.get("authority_lock")
    if not isinstance(expected, dict):
        raise MutationJournalError(
            "pending delete journal lacks captured workspace authority"
        )
    device = expected.get("root_device")
    inode = expected.get("root_inode")
    if any(
        isinstance(value, bool)
        or not isinstance(value, int)
        or value < 0
        for value in (device, inode)
    ):
        raise MutationJournalError(
            "pending delete journal root authority is malformed"
        )
    try:
        opened = os.fstat(descriptor)
    except OSError as exc:
        raise MutationJournalError(
            "pending delete root descriptor is not live"
        ) from exc
    if (
        not stat.S_ISDIR(opened.st_mode)
        or (opened.st_dev, opened.st_ino) != (device, inode)
    ):
        raise MutationJournalError(
            "pending delete root descriptor differs from journal authority"
        )
    _pending_delete_mount_id(descriptor)


def _authenticate_pending_delete_parent_descriptor(
    receipt: _PendingDeleteQuarantine,
    descriptor: int,
    *,
    expected_mount_id: int,
) -> None:
    """Bind a retained terminal-parent fd to the durable chain identity."""

    if isinstance(descriptor, bool) or not isinstance(descriptor, int) or (
        descriptor < 0
    ):
        raise MutationJournalError(
            "pending delete parent descriptor is malformed"
        )
    try:
        observed = _pending_delete_directory_identity(descriptor)
    except (OSError, MutationJournalError) as exc:
        raise MutationJournalError(
            "pending delete parent descriptor is not live"
        ) from exc
    if observed[5] != expected_mount_id or not _pending_delete_chain_matches(
        (receipt.parent_chain[-1],),
        (observed,),
        same_boot=receipt.boot_id == _pending_delete_boot_id(),
    ):
        raise MutationJournalError(
            "pending delete parent descriptor differs from its receipt"
        )


@contextmanager
def _open_settlement_parent_if_present(
    root_fd: int,
    relative: str,
    *,
    allow_terminal_vcs_metadata: bool = False,
) -> Iterator[
    tuple[int, str, tuple[tuple[int, int], ...], int | None]
]:
    """Open every parent component from the held root without aliases."""

    components = PurePosixPath(_settlement_relative_path(
        relative,
        allow_terminal_vcs_metadata=allow_terminal_vcs_metadata,
    )).parts
    flags = (
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    try:
        descriptor = os.dup(root_fd)
    except OSError as exc:
        raise MutationJournalError(
            f"cannot duplicate settlement root descriptor: {exc}"
        ) from exc
    chain = [(os.fstat(descriptor).st_dev, os.fstat(descriptor).st_ino)]
    try:
        for index, component in enumerate(components[:-1]):
            child: int | None = None
            try:
                before = os.stat(
                    component,
                    dir_fd=descriptor,
                    follow_symlinks=False,
                )
                child = os.open(component, flags, dir_fd=descriptor)
                opened = os.fstat(child)
                after = os.stat(
                    component,
                    dir_fd=descriptor,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                if child is not None:
                    os.close(child)
                yield descriptor, components[-1], tuple(chain), index
                return
            except (OSError, TypeError, ValueError) as exc:
                if child is not None:
                    os.close(child)
                raise MutationJournalError(
                    "cannot safely traverse lifecycle settlement parent "
                    f"for {relative!r}: {exc}"
                ) from exc
            if (
                not stat.S_ISDIR(before.st_mode)
                or stat.S_ISLNK(before.st_mode)
                or not stat.S_ISDIR(opened.st_mode)
                or (before.st_dev, before.st_ino)
                != (opened.st_dev, opened.st_ino)
                or (after.st_dev, after.st_ino)
                != (opened.st_dev, opened.st_ino)
            ):
                os.close(child)
                raise MutationJournalError(
                    "lifecycle settlement parent changed identity or became "
                    f"an alias: {relative!r}"
                )
            os.close(descriptor)
            descriptor = child
            chain.append((opened.st_dev, opened.st_ino))
        yield descriptor, components[-1], tuple(chain), None
    finally:
        os.close(descriptor)


def _assert_settlement_parent_binding(
    root_fd: int,
    relative: str,
    parent_fd: int,
    held_chain: tuple[tuple[int, int], ...],
    *,
    allow_terminal_vcs_metadata: bool = False,
) -> None:
    held = os.fstat(parent_fd)
    with _open_settlement_parent_if_present(
        root_fd,
        relative,
        allow_terminal_vcs_metadata=allow_terminal_vcs_metadata,
    ) as rebound:
        rebound_fd, _name, current_chain, missing_index = rebound
        if missing_index is not None:
            raise MutationJournalError(
                f"lifecycle settlement parent disappeared: {relative!r}"
            )
        current = os.fstat(rebound_fd)
    if (
        (held.st_dev, held.st_ino) != (current.st_dev, current.st_ino)
        or held_chain != current_chain
    ):
        raise MutationJournalError(
            f"lifecycle settlement parent changed identity: {relative!r}"
        )


def _settlement_xattr_inventory(
    *,
    descriptor: int | None,
    parent_fd: int,
    name: str,
    relative: str,
    budget: _SettlementCaptureBudget,
) -> dict[str, str]:
    """Capture bounded xattrs through a held entry or parent descriptor."""

    if not hasattr(os, "listxattr"):
        return {}
    if descriptor is None:
        target: int | Path = Path(_authority_descriptor_cwd(parent_fd)) / name
        nofollow = {"follow_symlinks": False}
    else:
        target = descriptor
        nofollow = {}
    try:
        names = sorted(os.listxattr(target, **nofollow))
    except OSError as exc:
        if exc.errno in {errno.ENOTSUP, errno.EOPNOTSUPP}:
            return {}
        raise MutationJournalError(
            f"cannot inspect settlement xattrs for {relative!r}: {exc}"
        ) from exc
    if len(names) > 256:
        raise MutationJournalError(
            f"too many settlement xattrs for {relative!r}"
        )
    inventory: dict[str, str] = {}
    node_bytes = 0
    for xattr_name in names:
        try:
            value = os.getxattr(target, xattr_name, **nofollow)
        except OSError as exc:
            raise MutationJournalError(
                "cannot read settlement xattr "
                f"{xattr_name!r} for {relative!r}: {exc}"
            ) from exc
        node_bytes += len(os.fsencode(xattr_name)) + len(value)
        if node_bytes > 4 * 1024 * 1024:
            raise MutationJournalError(
                f"settlement xattrs too large for {relative!r}"
            )
        inventory[xattr_name] = value.hex()
    budget.add_xattr_bytes(node_bytes)
    return inventory


def _settlement_stat_record(metadata: os.stat_result) -> dict[str, object]:
    return {
        "mode": stat.S_IMODE(metadata.st_mode),
        "nlink": metadata.st_nlink,
        "device": metadata.st_dev,
        "inode": metadata.st_ino,
        "uid": metadata.st_uid,
        "gid": metadata.st_gid,
        "mtime_ns": metadata.st_mtime_ns,
        "ctime_ns": metadata.st_ctime_ns,
    }


def _current_postimage_state(
    root_fd: int,
    relative: str,
    budget: _SettlementCaptureBudget,
) -> dict[str, object]:
    """Capture one exact node through the held root without following aliases."""

    relative = _settlement_relative_path(relative)
    with _open_settlement_parent_if_present(root_fd, relative) as binding:
        parent_fd, name, parent_chain, missing_index = binding
        if missing_index is not None:
            # Rewalk once: absence behind a missing parent is authority only
            # while the same held-root traversal remains absent.
            with _open_settlement_parent_if_present(root_fd, relative) as retry:
                (
                    _retry_fd,
                    _retry_name,
                    retry_chain,
                    retry_missing_index,
                ) = retry
                if (
                    retry_missing_index != missing_index
                    or retry_chain != parent_chain
                ):
                    raise MutationJournalError(
                        f"settlement parent appeared during capture: {relative!r}"
                    )
            return {
                "kind": "missing",
                "parent_chain": [list(identity) for identity in parent_chain],
                "missing_parent_index": missing_index,
            }
        try:
            before = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            _assert_settlement_parent_binding(
                root_fd,
                relative,
                parent_fd,
                parent_chain,
            )
            try:
                os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                return {
                    "kind": "missing",
                    "parent_chain": [list(identity) for identity in parent_chain],
                    "missing_parent_index": None,
                }
            raise MutationJournalError(
                f"settlement path appeared during capture: {relative!r}"
            ) from None
        except (OSError, TypeError, ValueError) as exc:
            raise MutationJournalError(
                f"cannot inspect settlement path {relative!r}: {exc}"
            ) from exc

        opened_fd: int | None = None
        try:
            state = _settlement_stat_record(before)
            state["parent_chain"] = [
                list(identity) for identity in parent_chain
            ]
            if stat.S_ISLNK(before.st_mode):
                if before.st_nlink != 1:
                    raise MutationJournalError(
                        f"settlement symlink is hard-linked: {relative!r}"
                    )
                state.update({
                    "kind": "symlink",
                    "target": os.readlink(name, dir_fd=parent_fd),
                    "xattrs": _settlement_xattr_inventory(
                        descriptor=None,
                        parent_fd=parent_fd,
                        name=name,
                        relative=relative,
                        budget=budget,
                    ),
                })
            elif stat.S_ISREG(before.st_mode):
                if before.st_nlink != 1:
                    raise MutationJournalError(
                        f"settlement file is hard-linked: {relative!r}"
                    )
                opened_fd = os.open(
                    name,
                    os.O_RDONLY
                    | getattr(os, "O_CLOEXEC", 0)
                    | getattr(os, "O_NOFOLLOW", 0)
                    | getattr(os, "O_NONBLOCK", 0),
                    dir_fd=parent_fd,
                )
                opened = os.fstat(opened_fd)
                if (
                    not stat.S_ISREG(opened.st_mode)
                    or (opened.st_dev, opened.st_ino)
                    != (before.st_dev, before.st_ino)
                ):
                    raise MutationJournalError(
                        f"settlement file changed while opening: {relative!r}"
                    )
                digest = hashlib.sha256()
                observed = 0
                while True:
                    chunk = os.read(opened_fd, 1024 * 1024)
                    if not chunk:
                        break
                    observed += len(chunk)
                    budget.add_hashed_bytes(len(chunk))
                    digest.update(chunk)
                state.update({
                    "kind": "file",
                    "sha256": digest.hexdigest(),
                    "size": observed,
                    "xattrs": _settlement_xattr_inventory(
                        descriptor=opened_fd,
                        parent_fd=parent_fd,
                        name=name,
                        relative=relative,
                        budget=budget,
                    ),
                })
                finished = os.fstat(opened_fd)
                if any(
                    getattr(opened, field) != getattr(finished, field)
                    for field in _SETTLEMENT_STABLE_STAT_FIELDS
                ):
                    raise MutationJournalError(
                        f"settlement file changed during read: {relative!r}"
                    )
            elif stat.S_ISDIR(before.st_mode):
                opened_fd = os.open(
                    name,
                    os.O_RDONLY
                    | getattr(os, "O_CLOEXEC", 0)
                    | getattr(os, "O_DIRECTORY", 0)
                    | getattr(os, "O_NOFOLLOW", 0),
                    dir_fd=parent_fd,
                )
                opened = os.fstat(opened_fd)
                if (
                    not stat.S_ISDIR(opened.st_mode)
                    or (opened.st_dev, opened.st_ino)
                    != (before.st_dev, before.st_ino)
                ):
                    raise MutationJournalError(
                        f"settlement directory changed while opening: {relative!r}"
                    )
                state.update({
                    "kind": "directory",
                    "xattrs": _settlement_xattr_inventory(
                        descriptor=opened_fd,
                        parent_fd=parent_fd,
                        name=name,
                        relative=relative,
                        budget=budget,
                    ),
                })
            else:
                raise MutationJournalError(
                    f"unsupported special settlement path: {relative!r}"
                )
            after = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            if any(
                getattr(before, field) != getattr(after, field)
                for field in _SETTLEMENT_STABLE_STAT_FIELDS
            ):
                raise MutationJournalError(
                    f"settlement postimage changed during capture: {relative!r}"
                )
            _assert_settlement_parent_binding(
                root_fd,
                relative,
                parent_fd,
                parent_chain,
            )
            return state
        except MutationJournalError:
            raise
        except (OSError, TypeError, ValueError) as exc:
            raise MutationJournalError(
                f"cannot capture settlement postimage {relative!r}: {exc}"
            ) from exc
        finally:
            if opened_fd is not None:
                os.close(opened_fd)


def _validated_active_parent_postimage_record(
    record: _ActiveParentPostimageRecord,
) -> _ActiveParentPostimageRecord:
    """Validate the exact field matrix of one in-process handoff record."""

    if type(record) is not _ActiveParentPostimageRecord:
        raise MutationJournalError(
            "active parent postimage handoff record has an invalid type"
        )
    if _settlement_relative_path(record.path) != record.path:
        raise MutationJournalError(
            f"active parent postimage path is malformed: {record.path!r}"
        )
    parts = PurePosixPath(record.path).parts
    if (
        not record.parent_chain
        or any(
            type(identity) is not tuple
            or len(identity) != 2
            or any(
                isinstance(value, bool)
                or not isinstance(value, int)
                or value < 0
                for value in identity
            )
            for identity in record.parent_chain
        )
    ):
        raise MutationJournalError(
            f"active parent postimage parent chain is malformed: {record.path!r}"
        )
    if record.missing_parent_index is None:
        if len(record.parent_chain) != len(parts):
            raise MutationJournalError(
                "active parent postimage parent chain has the wrong depth: "
                f"{record.path!r}"
            )
    elif (
        isinstance(record.missing_parent_index, bool)
        or not isinstance(record.missing_parent_index, int)
        or record.missing_parent_index < 0
        or record.missing_parent_index >= len(parts) - 1
        or len(record.parent_chain) != record.missing_parent_index + 1
    ):
        raise MutationJournalError(
            "active parent postimage missing-parent proof is malformed: "
            f"{record.path!r}"
        )
    if record.kind not in {"missing", "symlink", "file"}:
        raise MutationJournalError(
            f"active parent postimage kind is malformed: {record.path!r}"
        )
    if (
        type(record.xattrs) is not tuple
        or tuple(sorted(record.xattrs)) != record.xattrs
        or any(
            type(item) is not tuple
            or len(item) != 2
            or not isinstance(item[0], str)
            or not isinstance(item[1], str)
            for item in record.xattrs
        )
        or len({name for name, _value in record.xattrs}) != len(record.xattrs)
        or _validated_restore_xattrs(
            dict(record.xattrs),
            label=record.path,
        )
        != dict(record.xattrs)
    ):
        raise MutationJournalError(
            f"active parent postimage xattrs are malformed: {record.path!r}"
        )
    if record.kind == "missing":
        if any(
            value is not None
            for value in (
                record.device,
                record.inode,
                record.mode,
                record.sha256,
                record.size,
                record.target,
            )
        ) or record.xattrs:
            raise MutationJournalError(
                "active parent missing-postimage fields are malformed: "
                f"{record.path!r}"
            )
        return record
    if any(
        isinstance(value, bool) or not isinstance(value, int) or value < 0
        for value in (record.device, record.inode)
    ) or (
        isinstance(record.mode, bool)
        or not isinstance(record.mode, int)
        or not 0 <= record.mode <= 0o7777
    ):
        raise MutationJournalError(
            f"active parent postimage identity is malformed: {record.path!r}"
        )
    if record.missing_parent_index is not None:
        raise MutationJournalError(
            "an existing active parent postimage has a missing parent: "
            f"{record.path!r}"
        )
    if record.kind == "file":
        if (
            not isinstance(record.sha256, str)
            or re.fullmatch(r"[0-9a-f]{64}", record.sha256) is None
            or isinstance(record.size, bool)
            or not isinstance(record.size, int)
            or record.size < 0
            or record.target is not None
        ):
            raise MutationJournalError(
                f"active parent file postimage is malformed: {record.path!r}"
            )
        return record
    if (
        not isinstance(record.target, str)
        or record.sha256 is not None
        or record.size is not None
    ):
        raise MutationJournalError(
            f"active parent symlink postimage is malformed: {record.path!r}"
        )
    return record


def _active_parent_postimage_record_from_state(
    relative: str,
    state: Mapping[str, object],
) -> _ActiveParentPostimageRecord:
    """Project one descriptor-stable node state into an immutable proof."""

    raw_chain = state.get("parent_chain")
    if not isinstance(raw_chain, list):
        raise MutationJournalError(
            f"active parent postimage lacks parent authority: {relative!r}"
        )
    try:
        parent_chain = tuple(
            (int(identity[0]), int(identity[1]))
            for identity in raw_chain
            if isinstance(identity, list) and len(identity) == 2
        )
    except (TypeError, ValueError) as exc:
        raise MutationJournalError(
            f"active parent postimage parent authority is malformed: {relative!r}"
        ) from exc
    if len(parent_chain) != len(raw_chain):
        raise MutationJournalError(
            f"active parent postimage parent authority is malformed: {relative!r}"
        )
    kind = state.get("kind")
    missing_parent_index = state.get("missing_parent_index")
    if kind == "missing":
        record = _ActiveParentPostimageRecord(
            path=relative,
            kind="missing",
            parent_chain=parent_chain,
            missing_parent_index=cast(int | None, missing_parent_index),
            device=None,
            inode=None,
            mode=None,
        )
    elif kind in {"file", "symlink"}:
        raw_xattrs = state.get("xattrs")
        if not isinstance(raw_xattrs, dict):
            raise MutationJournalError(
                f"active parent postimage xattrs are malformed: {relative!r}"
            )
        record = _ActiveParentPostimageRecord(
            path=relative,
            kind=cast(Literal["file", "symlink"], kind),
            parent_chain=parent_chain,
            missing_parent_index=None,
            device=cast(int, state.get("device")),
            inode=cast(int, state.get("inode")),
            mode=cast(int, state.get("mode")),
            xattrs=tuple(sorted(
                (str(name), str(value))
                for name, value in raw_xattrs.items()
            )),
            sha256=(
                cast(str, state.get("sha256"))
                if kind == "file"
                else None
            ),
            size=(cast(int, state.get("size")) if kind == "file" else None),
            target=(
                cast(str, state.get("target"))
                if kind == "symlink"
                else None
            ),
        )
    else:
        raise MutationJournalError(
            f"active parent postimage has an unsupported kind: {relative!r}"
        )
    return _validated_active_parent_postimage_record(record)


def _active_parent_postimage_identity(
    record: _ActiveParentPostimageRecord,
) -> tuple[int, int] | None:
    record = _validated_active_parent_postimage_record(record)
    if record.kind == "missing":
        return None
    return cast(int, record.device), cast(int, record.inode)


def _active_parent_postimage_observation(
    state: Mapping[str, object],
) -> dict[str, object]:
    """Project an exact state into tracked-metadata comparison fields."""

    if state.get("kind") == "missing":
        return {"kind": "missing"}
    keys = (
        "kind",
        "mode",
        "nlink",
        "xattrs",
        "device",
        "inode",
        "size",
        "mtime_ns",
        "ctime_ns",
        "target",
    )
    observation = {key: state[key] for key in keys if key in state}
    if state.get("kind") == "symlink" and "size" not in observation:
        target = state.get("target")
        if not isinstance(target, str):
            raise MutationJournalError(
                "active parent symlink observation lacks a target"
            )
        observation["size"] = len(os.fsencode(target))
    return observation


def _assert_reviewable_active_parent_transition(
    relative: str,
    baseline: Mapping[str, object] | None,
    record: _ActiveParentPostimageRecord,
) -> None:
    """Reject Git-invisible metadata that no tier candidate can review."""

    record = _validated_active_parent_postimage_record(record)
    baseline_kind = baseline.get("kind") if baseline is not None else None
    if baseline is not None and baseline_kind not in {"missing", "file", "symlink"}:
        raise MutationJournalError(
            f"active parent baseline kind is malformed: {relative!r}"
        )
    if record.kind == "missing":
        if baseline_kind not in {"missing", "file", "symlink"}:
            raise MutationJournalError(
                "active parent absence is not a reviewed tracked deletion: "
                f"{relative!r}"
            )
        return

    record_xattrs = dict(record.xattrs)
    if baseline_kind == record.kind:
        assert baseline is not None
        baseline_xattrs = _validated_restore_xattrs(
            baseline.get("xattrs", {}),
            label=relative,
        )
        if record_xattrs != baseline_xattrs:
            raise MutationJournalError(
                f"active parent postimage has unreviewed xattr drift: {relative!r}"
            )
        baseline_mode = baseline.get("mode")
        if (
            isinstance(baseline_mode, bool)
            or not isinstance(baseline_mode, int)
            or not 0 <= baseline_mode <= 0o7777
        ):
            raise MutationJournalError(
                f"active parent baseline mode is malformed: {relative!r}"
            )
        assert record.mode is not None
        if record.kind == "file":
            record_executable = record.mode & 0o111
            baseline_executable = baseline_mode & 0o111
            if (
                (record.mode & ~0o111) != (baseline_mode & ~0o111)
                or (
                    record_executable != baseline_executable
                    and {record_executable, baseline_executable} != {0, 0o111}
                )
            ):
                raise MutationJournalError(
                    "active parent postimage has unreviewed permission drift: "
                    f"{relative!r}"
                )
        elif record.mode != baseline_mode:
            raise MutationJournalError(
                f"active parent symlink mode changed: {relative!r}"
            )
        return

    if record_xattrs:
        raise MutationJournalError(
            "active parent new/type-transition postimage has unreviewed xattrs: "
            f"{relative!r}"
        )
    if record.kind == "file" and record.mode not in {0o644, 0o755}:
        raise MutationJournalError(
            "active parent new/type-transition file has an unreviewed mode: "
            f"{relative!r}"
        )
    if record.kind == "symlink" and record.mode != 0o777:
        raise MutationJournalError(
            "active parent new/type-transition symlink has an unreviewed mode: "
            f"{relative!r}"
        )


def _reprove_active_parent_postimage(
    root_fd: int,
    record: _ActiveParentPostimageRecord,
    budget: _SettlementCaptureBudget,
) -> dict[str, object]:
    """Descriptor-stably reprove one exact accepted node or absence."""

    record = _validated_active_parent_postimage_record(record)
    state = _current_postimage_state(root_fd, record.path, budget)
    observed = _active_parent_postimage_record_from_state(record.path, state)
    if observed != record:
        raise MutationJournalError(
            "active parent postimage differs from its accepted proof: "
            f"{record.path!r}"
        )
    return dict(state)


def _descriptor_recursive_postimage_paths(
    root_fd: int,
    relative: str,
) -> tuple[str, ...]:
    """Enumerate one recursive scope through stable directory descriptors."""

    relative = _settlement_relative_path(relative)
    discovered: set[str] = {relative}

    def add_path(path: str) -> None:
        discovered.add(_settlement_relative_path(path))
        if len(discovered) > _LIFECYCLE_SETTLEMENT_MAX_PATHS:
            raise MutationJournalError(
                "lifecycle settlement recursive scope exceeds its path ceiling"
            )

    def walk(directory_fd: int, directory_path: str, depth: int) -> None:
        if depth > _LIFECYCLE_SETTLEMENT_MAX_DEPTH:
            raise MutationJournalError(
                "lifecycle settlement recursive scope exceeds its depth ceiling"
            )
        opened = os.fstat(directory_fd)
        if not stat.S_ISDIR(opened.st_mode):
            raise MutationJournalError(
                f"settlement recursive root is not a directory: {directory_path!r}"
            )
        remaining = _LIFECYCLE_SETTLEMENT_MAX_PATHS - len(discovered)
        initial_names = _bounded_directory_names(
            directory_fd,
            label=(
                "lifecycle settlement directory "
                f"{directory_path!r}"
            ),
            max_entries=remaining,
        )
        for name in initial_names:
            if not isinstance(name, str) or name in {"", ".", ".."} or "/" in name:
                raise MutationJournalError(
                    f"invalid settlement directory entry below {directory_path!r}"
                )
            child_path = f"{directory_path}/{name}"
            add_path(child_path)
            try:
                before = os.stat(
                    name,
                    dir_fd=directory_fd,
                    follow_symlinks=False,
                )
            except OSError as exc:
                raise MutationJournalError(
                    f"settlement entry changed during enumeration: {child_path!r}"
                ) from exc
            if not stat.S_ISDIR(before.st_mode) or stat.S_ISLNK(before.st_mode):
                continue
            child_fd: int | None = None
            try:
                child_fd = os.open(
                    name,
                    os.O_RDONLY
                    | getattr(os, "O_CLOEXEC", 0)
                    | getattr(os, "O_DIRECTORY", 0)
                    | getattr(os, "O_NOFOLLOW", 0),
                    dir_fd=directory_fd,
                )
                child_opened = os.fstat(child_fd)
                if (
                    not stat.S_ISDIR(child_opened.st_mode)
                    or (child_opened.st_dev, child_opened.st_ino)
                    != (before.st_dev, before.st_ino)
                ):
                    raise MutationJournalError(
                        f"settlement directory changed while opening: {child_path!r}"
                    )
                walk(child_fd, child_path, depth + 1)
                after = os.stat(
                    name,
                    dir_fd=directory_fd,
                    follow_symlinks=False,
                )
                if any(
                    getattr(before, field) != getattr(after, field)
                    for field in _SETTLEMENT_STABLE_STAT_FIELDS
                ):
                    raise MutationJournalError(
                        "settlement directory changed during enumeration: "
                        f"{child_path!r}"
                    )
            finally:
                if child_fd is not None:
                    os.close(child_fd)
        final_names = _bounded_directory_names(
            directory_fd,
            label=(
                "lifecycle settlement directory "
                f"{directory_path!r}"
            ),
            max_entries=remaining,
        )
        try:
            finished = os.fstat(directory_fd)
        except OSError as exc:
            raise MutationJournalError(
                f"cannot revalidate settlement directory {directory_path!r}: {exc}"
            ) from exc
        if initial_names != final_names or any(
            getattr(opened, field) != getattr(finished, field)
            for field in _SETTLEMENT_STABLE_STAT_FIELDS
        ):
            raise MutationJournalError(
                f"settlement directory changed during enumeration: {directory_path!r}"
            )
        with _open_settlement_parent_if_present(
            root_fd,
            directory_path,
        ) as rebound:
            parent_fd, name, _parent_chain, missing_index = rebound
            if missing_index is not None:
                raise MutationJournalError(
                    f"settlement directory disappeared: {directory_path!r}"
                )
            rebound_metadata = os.stat(
                name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        if (opened.st_dev, opened.st_ino) != (
            rebound_metadata.st_dev,
            rebound_metadata.st_ino,
        ):
            raise MutationJournalError(
                f"settlement directory changed root-relative identity: {directory_path!r}"
            )

    with _open_settlement_parent_if_present(root_fd, relative) as binding:
        parent_fd, name, _parent_chain, missing_index = binding
        if missing_index is not None:
            return (relative,)
        try:
            metadata = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            return (relative,)
        if not stat.S_ISDIR(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
            return (relative,)
        directory_fd = os.open(
            name,
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_NOFOLLOW", 0),
            dir_fd=parent_fd,
        )
        try:
            opened = os.fstat(directory_fd)
            if (metadata.st_dev, metadata.st_ino) != (
                opened.st_dev,
                opened.st_ino,
            ):
                raise MutationJournalError(
                    f"settlement recursive root changed: {relative!r}"
                )
            walk(directory_fd, relative, len(PurePosixPath(relative).parts))
        finally:
            os.close(directory_fd)
    return tuple(sorted(discovered))


def _read_bound_blob(
    cwd: Path,
    relative: str,
    binding: dict[str, object],
) -> bytes:
    oid = str(binding["oid"])
    result = _run_bound_git_process(
        cwd,
        ["git", *_GIT_SAFE_OPTIONS, "cat-file", "blob", oid],
        GIT_NO_LAZY_FETCH="1",
        GIT_NO_REPLACE_OBJECTS="1",
    )
    if result.returncode != 0:
        raise MutationJournalError(
            f"cannot read raw baseline Git blob for {relative}: "
            + result.stderr.decode("utf-8", errors="replace").strip()
        )
    payload = result.stdout
    if (
        len(payload) != int(cast(int | str, binding["size"]))
        or hashlib.sha256(payload).hexdigest() != binding["sha256"]
    ):
        raise MutationJournalError(
            f"raw baseline Git blob changed for {relative}"
        )
    return payload


def _matches_raw_object_binding(
    journal: "WorkspaceMutationJournal",
    relative: str,
    binding: dict[str, object],
) -> bool:
    with _bound_workspace_restore_root(journal) as root_fd:
        observed = _current_postimage_state(
            root_fd,
            relative,
            _SettlementCaptureBudget(),
        )
    if observed.get("kind") != "file":
        return False
    if (
        observed.get("nlink") != int(cast(
            int | str, binding.get("nlink", 1)
        ))
        or observed.get("size") != int(cast(int | str, binding["size"]))
        or observed.get("mode") != int(cast(
            int | str, binding["mode"]
        ))
        or observed.get("xattrs") != binding.get("xattrs", {})
    ):
        return False
    cwd = journal._bound_workspace_cwd()
    payload = _read_bound_blob(cwd, relative, binding)
    return observed.get("sha256") == hashlib.sha256(payload).hexdigest()


def _matches_snapshot(
    journal: "WorkspaceMutationJournal",
    relative: str,
    expected: Mapping[str, Any],
) -> bool:
    with _bound_workspace_restore_root(journal) as root_fd:
        observed = _current_postimage_state(
            root_fd,
            relative,
            _SettlementCaptureBudget(),
        )
    if observed.get("kind") == "missing":
        return expected["kind"] == "missing"

    kind = expected["kind"]
    if kind == "opaque_directory":
        return True
    if kind == "directory":
        return (
            observed.get("kind") == "directory"
            and observed.get("mode") == int(expected["mode"])
            and observed.get("xattrs") == expected.get("xattrs", {})
        )
    if kind == "symlink":
        return (
            observed.get("kind") == "symlink"
            and observed.get("nlink") == int(expected.get("nlink", 1))
            and observed.get("target") == expected["target"]
            and observed.get("xattrs") == expected.get("xattrs", {})
        )
    if kind != "file" or observed.get("kind") != "file":
        return False
    if (
        observed.get("mode") != int(expected["mode"])
        or observed.get("size") != int(expected["size"])
        or observed.get("nlink") != int(expected.get("nlink", 1))
        or observed.get("xattrs") != expected.get("xattrs", {})
    ):
        return False
    # Also verify the journal blob while it is hot; a corrupt baseline must
    # fail closed before a model attempt can be accepted.
    baseline = journal._read_snapshot_blob_record(
        expected,
        label=f"mutation snapshot {relative}",
    )
    if hashlib.sha256(baseline).hexdigest() != expected["sha256"]:
        raise MutationJournalError(
            f"corrupt mutation snapshot blob for {relative}"
        )
    return observed.get("sha256") == expected["sha256"]


def _walk_snapshot_paths(
    cwd: Path,
    roots: Iterable[str],
    *,
    recursive_roots: Iterable[str],
) -> set[str]:
    paths: set[str] = set()
    recursive = set(recursive_roots)
    for relative in roots:
        paths.add(relative)
        target = cwd / relative
        if (
            relative not in recursive
            or not target.is_dir()
            or target.is_symlink()
        ):
            continue
        for current, dirs, files in _walk_complete_real_tree(
            target,
            tree_label="recursive mutation snapshot",
        ):
            rel_root = current.relative_to(cwd).as_posix()
            paths.add(rel_root)
            traversable: list[str] = []
            for name in dirs:
                child = current / name
                paths.add(child.relative_to(cwd).as_posix())
                if not child.is_symlink():
                    traversable.append(name)
            # Do not traverse symlinked directories.
            dirs[:] = traversable
            for name in files:
                paths.add((current / name).relative_to(cwd).as_posix())
    return paths


def _remove_path(path: Path) -> None:
    try:
        metadata = path.lstat()
    except FileNotFoundError:
        return
    if stat.S_ISDIR(metadata.st_mode) and not stat.S_ISLNK(metadata.st_mode):
        shutil.rmtree(path)
    else:
        path.unlink()


@contextmanager
def _bound_workspace_restore_root(
    journal: "WorkspaceMutationJournal",
) -> Iterator[int]:
    """Hold the exact checkout inode for one descriptor-relative restore.

    ``_bound_workspace_cwd`` deliberately returns a ``/proc/self/fd`` alias
    while the workspace lock is held.  Appending a slash-containing path to
    that alias is not sufficient confinement: the kernel can still follow a
    transaction-time symlink in an intermediate component.  Restore helpers
    therefore start from this duplicated root descriptor and walk every
    parent with ``O_NOFOLLOW``.
    """

    logical_root = Path(journal._manifest["cwd"])
    authority = _active_workspace_mutation_authority(logical_root)
    if authority is None:
        descriptor, opened = _open_authority_directory(
            logical_root,
            label="mutation restore workspace root",
        )
    else:
        authority = _assert_workspace_mutation_authority(logical_root)
        try:
            descriptor = os.dup(authority.root_descriptor)
            opened = os.fstat(descriptor)
        except OSError as exc:
            raise MutationJournalError(
                f"cannot duplicate mutation restore workspace root: {exc}"
            ) from exc

    expected = journal._manifest.get("authority_lock") or {}
    body_failed = False
    try:
        if (
            not stat.S_ISDIR(opened.st_mode)
            or (
                expected.get("root_device") is not None
                and opened.st_dev != int(expected["root_device"])
            )
            or (
                expected.get("root_inode") is not None
                and opened.st_ino != int(expected["root_inode"])
            )
        ):
            raise MutationJournalError(
                "mutation restore root differs from journal authority"
            )
        yield descriptor
    except BaseException:
        body_failed = True
        raise
    finally:
        try:
            if authority is None:
                _assert_authority_directory_binding(
                    logical_root,
                    descriptor,
                    opened,
                    label="mutation restore workspace root",
                )
            else:
                _assert_workspace_mutation_authority(logical_root)
        except BaseException:
            if not body_failed:
                raise
            logger.exception(
                "mutation restore root also lost binding during failure"
            )
        finally:
            os.close(descriptor)


def _fsync_bound_directory(descriptor: int) -> None:
    """Best-effort directory durability, matching ``write_atomic_bytes``."""

    try:
        os.fsync(descriptor)
    except OSError:
        # Some supported filesystems do not permit fsync on directory handles.
        pass


def _restore_bound_descriptor_xattrs(
    descriptor: int,
    expected: Mapping[str, str],
    *,
    label: str,
) -> None:
    """Restore exact xattrs through an already-open file/directory inode."""

    if not hasattr(os, "listxattr"):
        if expected:
            raise MutationJournalError(
                f"platform cannot restore baseline xattrs for {label}"
            )
        return
    try:
        names = sorted(os.listxattr(descriptor))
    except OSError as exc:
        if exc.errno in {errno.ENOTSUP, errno.EOPNOTSUPP} and not expected:
            return
        raise MutationJournalError(
            f"cannot inspect xattrs for {label}: {exc}"
        ) from exc
    if len(names) > 256:
        raise MutationJournalError(
            f"too many xattrs for exact rollback: {label}"
        )
    for name in set(names).difference(expected):
        try:
            os.removexattr(descriptor, name)
        except OSError as exc:
            raise MutationJournalError(
                f"cannot remove xattr {name!r} for {label}: {exc}"
            ) from exc
    total_bytes = 0
    for name, encoded in expected.items():
        try:
            value = bytes.fromhex(encoded)
        except (TypeError, ValueError) as exc:
            raise MutationJournalError(
                f"invalid baseline xattr {name!r} for {label}"
            ) from exc
        total_bytes += len(value)
        if total_bytes > 4 * 1024 * 1024:
            raise MutationJournalError(
                f"xattrs too large for exact rollback: {label}"
            )
        try:
            os.setxattr(descriptor, name, value)
        except OSError as exc:
            raise MutationJournalError(
                f"cannot restore xattr {name!r} for {label}: {exc}"
            ) from exc


def _validated_restore_xattrs(
    value: object,
    *,
    label: str,
) -> dict[str, str]:
    """Validate bounded restore xattrs before any namespace mutation."""

    if not isinstance(value, dict) or len(value) > 256:
        raise MutationJournalError(
            f"workspace snapshot xattrs are malformed: {label!r}"
        )
    validated: dict[str, str] = {}
    total_bytes = 0
    for name, encoded in value.items():
        if (
            not isinstance(name, str)
            or not name
            or "\0" in name
            or not isinstance(encoded, str)
        ):
            raise MutationJournalError(
                f"workspace snapshot xattrs are malformed: {label!r}"
            )
        try:
            decoded = bytes.fromhex(encoded)
        except ValueError as exc:
            raise MutationJournalError(
                f"workspace snapshot xattrs are malformed: {label!r}"
            ) from exc
        total_bytes += len(decoded)
        if total_bytes > 4 * 1024 * 1024:
            raise MutationJournalError(
                f"workspace snapshot xattrs are too large: {label!r}"
            )
        validated[name] = encoded
    return validated


def _read_bound_snapshot_blob(
    journal: "WorkspaceMutationJournal",
    digest: object,
    recorded_size: object,
    budget: "_MutationJournalArtifactBudget",
    *,
    label: str,
) -> bytes:
    """Read one exact journal blob through held journal/blob directories."""

    if (
        not isinstance(digest, str)
        or re.fullmatch(r"[0-9a-f]{64}", digest) is None
        or not isinstance(recorded_size, int)
        or isinstance(recorded_size, bool)
        or not 0 <= recorded_size <= _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_BYTES
    ):
        raise MutationJournalError(
            f"workspace snapshot blob binding is malformed: {label!r}"
        )
    budget.charge_path()
    budget.charge_bytes(recorded_size)

    journal_fd: int | None = None
    blobs_fd: int | None = None
    logical_journal = journal.journal_dir
    discovery_binding = journal._discovery_binding
    direct_binding = discovery_binding is None
    failed = True
    try:
        if direct_binding:
            journal_fd, journal_metadata = _open_authority_directory(
                logical_journal,
                label="mutation snapshot journal",
            )
        else:
            journal_fd = os.open(
                logical_journal,
                os.O_RDONLY
                | getattr(os, "O_CLOEXEC", 0)
                | getattr(os, "O_DIRECTORY", 0),
            )
            journal_metadata = os.fstat(journal_fd)
            assert discovery_binding is not None
            component = discovery_binding.components[-1]
            if (journal_metadata.st_dev, journal_metadata.st_ino) != (
                component.device,
                component.inode,
            ):
                raise MutationJournalError(
                    "mutation snapshot journal conflicts with discovery binding"
                )
        blobs_fd, blobs_metadata = _open_authority_directory_at(
            journal_fd,
            "blobs",
            label="mutation snapshot blob directory",
        )
        payload, _opened = _read_bound_regular_entry(
            blobs_fd,
            digest,
            label=f"mutation snapshot blob for {label}",
            max_bytes=recorded_size,
        )
        current_blobs = os.stat(
            "blobs",
            dir_fd=journal_fd,
            follow_symlinks=False,
        )
        held_blobs = os.fstat(blobs_fd)
        if (
            len(payload) != recorded_size
            or hashlib.sha256(payload).hexdigest() != digest
            or (current_blobs.st_dev, current_blobs.st_ino)
            != (blobs_metadata.st_dev, blobs_metadata.st_ino)
            or (held_blobs.st_dev, held_blobs.st_ino)
            != (blobs_metadata.st_dev, blobs_metadata.st_ino)
        ):
            raise MutationJournalError(
                f"corrupt mutation snapshot blob for {label}"
            )
        failed = False
        return payload
    except MutationJournalError:
        raise
    except (OSError, TypeError, ValueError) as exc:
        raise MutationJournalError(
            f"cannot read mutation snapshot blob for {label}: {exc}"
        ) from exc
    finally:
        try:
            if direct_binding and journal_fd is not None:
                try:
                    _assert_authority_directory_binding(
                        logical_journal,
                        journal_fd,
                        journal_metadata,
                        label="mutation snapshot journal",
                    )
                except BaseException:
                    if not failed:
                        raise
                    logger.exception(
                        "mutation snapshot journal also lost binding during failure"
                    )
        finally:
            if blobs_fd is not None:
                os.close(blobs_fd)
            if journal_fd is not None:
                os.close(journal_fd)


def _workspace_restore_parent_prefixes(relative: str) -> tuple[str, ...]:
    parts = PurePosixPath(_settlement_relative_path(relative)).parts[:-1]
    return tuple(PurePosixPath(*parts[:index]).as_posix() for index in range(1, len(parts) + 1))


def _ensure_bound_workspace_restore_parents(
    journal: "WorkspaceMutationJournal",
    root_fd: int,
    relative: str,
    *,
    expected_parent_bindings: Mapping[str, tuple[int, int] | None] | None = None,
) -> tuple[tuple[str, int, int], ...]:
    """Recreate only manifest-proven baseline parents without path aliases."""

    prefixes = _workspace_restore_parent_prefixes(relative)
    expected_modes = journal._manifest.get("directory_modes")
    expected_xattrs = journal._manifest.get("directory_xattrs", {})
    if not isinstance(expected_modes, dict) or not isinstance(expected_xattrs, dict):
        raise MutationJournalError("workspace directory baseline is malformed")
    expected_identities = journal._effective_workspace_directory_identities(
        expected_modes,
    )
    parent_metadata: dict[str, tuple[int, dict[str, str]]] = {}
    for prefix in prefixes:
        mode = expected_modes.get(prefix)
        if (
            not isinstance(mode, int)
            or isinstance(mode, bool)
            or not 0 <= mode <= 0o7777
        ):
            raise MutationJournalError(
                f"workspace restore parent lacks baseline authority: {prefix!r}"
            )
        parent_metadata[prefix] = (
            mode,
            _validated_restore_xattrs(
                expected_xattrs.get(prefix, {}),
                label=prefix,
            ),
        )

    descriptor = os.dup(root_fd)
    chain = [(os.fstat(descriptor).st_dev, os.fstat(descriptor).st_ino)]
    bindings: list[tuple[str, int, int]] = []
    try:
        for prefix, component in zip(
            prefixes,
            PurePosixPath(relative).parts[:-1],
            strict=True,
        ):
            if (
                expected_parent_bindings is not None
                and prefix in expected_parent_bindings
            ):
                had_previous_binding = True
                previously_bound = expected_parent_bindings[prefix]
            else:
                had_previous_binding = False
                previously_bound = None
            try:
                before = os.stat(
                    component,
                    dir_fd=descriptor,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                if had_previous_binding and previously_bound is not None:
                    raise MutationJournalError(
                        "workspace restore parent disappeared between roots: "
                        f"{prefix!r}"
                    ) from None
                _assert_settlement_parent_binding(
                    root_fd,
                    prefix,
                    descriptor,
                    tuple(chain),
                )
                private_name, child, opened = (
                    _create_private_bound_workspace_directory(
                        descriptor,
                        label=f"workspace restore parent {prefix!r}",
                    )
                )
                try:
                    mode, xattrs = parent_metadata[prefix]
                    _restore_bound_descriptor_xattrs(
                        child,
                        xattrs,
                        label=prefix,
                    )
                    os.fchmod(child, mode | 0o700)
                    _fsync_bound_directory(child)
                    _assert_settlement_parent_binding(
                        root_fd,
                        prefix,
                        descriptor,
                        tuple(chain),
                    )
                    _publish_private_bound_workspace_directory(
                        descriptor,
                        private_name,
                        component,
                        child,
                        opened,
                        label=f"workspace restore parent {prefix!r}",
                    )
                    _fsync_bound_directory(descriptor)
                except BaseException:
                    os.close(child)
                    raise
            else:
                if had_previous_binding and previously_bound is None:
                    raise MutationJournalError(
                        "workspace restore parent appeared between roots: "
                        f"{prefix!r}"
                    )
                if not stat.S_ISDIR(before.st_mode) or stat.S_ISLNK(
                    before.st_mode
                ):
                    raise MutationJournalError(
                        f"workspace restore parent is aliased: {prefix!r}"
                    )
                child, opened = _open_authority_directory_at(
                    descriptor,
                    component,
                    label=f"workspace restore parent {prefix!r}",
                )
                if (opened.st_dev, opened.st_ino) != (
                    before.st_dev,
                    before.st_ino,
                ):
                    os.close(child)
                    raise MutationJournalError(
                        f"workspace restore parent changed: {prefix!r}"
                    )
                if previously_bound is not None and previously_bound != (
                    opened.st_dev,
                    opened.st_ino,
                ):
                    os.close(child)
                    raise MutationJournalError(
                        "workspace restore parent changed between roots: "
                        f"{prefix!r}"
                    )
                captured_identity = expected_identities[prefix]
                if (
                    (opened.st_dev, opened.st_ino) != captured_identity
                    and previously_bound
                    != (opened.st_dev, opened.st_ino)
                ):
                    os.close(child)
                    raise MutationJournalError(
                        "workspace restore parent differs from its captured "
                        f"identity: {prefix!r}"
                    )
            os.close(descriptor)
            descriptor = child
            chain.append((opened.st_dev, opened.st_ino))
            bindings.append((prefix, opened.st_dev, opened.st_ino))
    finally:
        os.close(descriptor)
    return tuple(bindings)


def _restore_bound_workspace_parent_metadata(
    journal: "WorkspaceMutationJournal",
    root_fd: int,
    bindings: Iterable[tuple[str, int, int]],
) -> None:
    """Restore parent directory metadata deepest-first through held fds."""

    expected_modes = cast(dict[str, object], journal._manifest["directory_modes"])
    expected_xattrs = cast(
        dict[str, object],
        journal._manifest.get("directory_xattrs", {}),
    )
    for prefix, expected_device, expected_inode in reversed(tuple(bindings)):
        with _open_settlement_parent_if_present(root_fd, prefix) as binding:
            parent_fd, name, parent_chain, missing_index = binding
            if missing_index is not None:
                raise MutationJournalError(
                    f"workspace restore parent disappeared: {prefix!r}"
                )
            _assert_settlement_parent_binding(
                root_fd,
                prefix,
                parent_fd,
                parent_chain,
            )
            directory_fd, opened = _open_authority_directory_at(
                parent_fd,
                name,
                label=f"workspace restore parent {prefix!r}",
            )
            try:
                if (opened.st_dev, opened.st_ino) != (
                    expected_device,
                    expected_inode,
                ):
                    raise MutationJournalError(
                        f"workspace restore parent changed: {prefix!r}"
                    )
                mode = cast(int, expected_modes[prefix])
                xattrs = _validated_restore_xattrs(
                    expected_xattrs.get(prefix, {}),
                    label=prefix,
                )
                _restore_bound_descriptor_xattrs(
                    directory_fd,
                    xattrs,
                    label=prefix,
                )
                os.fchmod(directory_fd, mode)
                _fsync_bound_directory(directory_fd)
                current = os.stat(
                    name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
                if (current.st_dev, current.st_ino) != (
                    opened.st_dev,
                    opened.st_ino,
                ):
                    raise MutationJournalError(
                        f"workspace restore parent changed: {prefix!r}"
                    )
            finally:
                os.close(directory_fd)


def _merge_workspace_restore_parent_bindings(
    accumulated: dict[str, tuple[int, int] | None],
    observed: Iterable[tuple[str, int | None, int | None]],
) -> None:
    """Merge parent identities/absence tokens across sequential roots."""

    for path, device, inode in observed:
        if (device is None) != (inode is None):
            raise MutationJournalError(
                f"workspace restore parent observation is malformed: {path!r}"
            )
        identity = None if device is None else (device, cast(int, inode))
        if path not in accumulated:
            accumulated[path] = identity
            continue
        previous = accumulated[path]
        if previous is None and identity is not None:
            # A materialized later root may legitimately reconstruct a parent
            # that an earlier absence root proved absent.  Ensure authorizes
            # that transition only while the missing token remains true.
            accumulated[path] = identity
            continue
        if previous != identity:
            raise MutationJournalError(
                f"workspace restore parent changed between roots: {path!r}"
            )


def _assert_expected_workspace_restore_parent_bindings(
    relative: str,
    parent_chain: tuple[tuple[int, int], ...],
    missing_index: int | None,
    expected: Mapping[str, tuple[int, int] | None] | None,
) -> None:
    """Enforce cross-root parent authority before any target mutation."""

    if not expected:
        return
    for index, prefix in enumerate(_workspace_restore_parent_prefixes(relative)):
        if prefix not in expected:
            continue
        expected_identity = expected[prefix]
        chain_index = index + 1
        if expected_identity is None:
            if chain_index < len(parent_chain):
                raise MutationJournalError(
                    "workspace restore parent appeared between roots: "
                    f"{prefix!r}"
                )
            continue
        if missing_index is not None and index >= missing_index:
            raise MutationJournalError(
                "workspace restore parent disappeared between roots: "
                f"{prefix!r}"
            )
        if (
            chain_index >= len(parent_chain)
            or parent_chain[chain_index] != expected_identity
        ):
            raise MutationJournalError(
                "workspace restore parent changed between roots: "
                f"{prefix!r}"
            )


def _observed_workspace_restore_parent_bindings(
    relative: str,
    parent_chain: tuple[tuple[int, int], ...],
) -> tuple[tuple[str, int | None, int | None], ...]:
    """Bind every existing parent observed by one held-root target walk."""

    prefixes = _workspace_restore_parent_prefixes(relative)
    return tuple(
        (
            (prefix, *parent_chain[index + 1])
            if index + 1 < len(parent_chain)
            else (prefix, None, None)
        )
        for index, prefix in enumerate(prefixes)
    )


@dataclass(frozen=True)
class _BoundWorkspaceDirectoryRecord:
    relative: str
    device: int
    inode: int
    mode: int
    xattrs: dict[str, str]


def _validated_workspace_directory_baseline(
    expected_modes: object,
    expected_xattrs: object,
) -> tuple[dict[str, int], dict[str, dict[str, str]]]:
    """Validate the complete directory authority before namespace mutation."""

    if (
        not isinstance(expected_modes, dict)
        or not isinstance(expected_xattrs, dict)
        or len(expected_modes) > _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS
        or len(expected_xattrs) > _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS
        or "." not in expected_modes
    ):
        raise MutationJournalError("workspace directory baseline is malformed")
    modes: dict[str, int] = {}
    xattrs: dict[str, dict[str, str]] = {}
    path_bytes = 0
    for relative, mode in expected_modes.items():
        if not isinstance(relative, str) or (
            relative != "." and _settlement_relative_path(relative) != relative
        ):
            raise MutationJournalError(
                f"workspace directory baseline path is malformed: {relative!r}"
            )
        if (
            relative != "."
            and len(PurePosixPath(relative).parts)
            > _MUTATION_JOURNAL_MAX_DISCOVERY_DEPTH
        ):
            raise MutationJournalError(
                f"workspace directory baseline is too deep: {relative!r}"
            )
        if (
            not isinstance(mode, int)
            or isinstance(mode, bool)
            or not 0 <= mode <= 0o7777
        ):
            raise MutationJournalError(
                f"workspace directory baseline mode is malformed: {relative!r}"
            )
        path_bytes += len(os.fsencode(relative))
        if path_bytes > _MUTATION_JOURNAL_MAX_DISCOVERY_PATH_BYTES:
            raise MutationJournalError(
                "workspace directory baseline exceeds its path-byte ceiling"
            )
        modes[relative] = mode
        xattrs[relative] = _validated_restore_xattrs(
            expected_xattrs.get(relative, {}),
            label=relative,
        )
    unexpected_xattrs = set(expected_xattrs).difference(modes)
    if unexpected_xattrs or any(
        not isinstance(path, str) for path in expected_xattrs
    ):
        raise MutationJournalError(
            "workspace directory xattr baseline has unknown paths"
        )
    for relative in modes:
        if relative == ".":
            continue
        parent = PurePosixPath(relative).parent.as_posix()
        if parent == ".":
            parent = "."
        if parent not in modes:
            raise MutationJournalError(
                "workspace directory baseline lacks parent authority: "
                f"{relative!r}"
            )
    return modes, xattrs


def _validated_workspace_directory_identities(
    value: object,
    paths: Iterable[str],
) -> dict[str, tuple[int, int]]:
    """Validate capture-time inode authority for every baseline directory."""

    expected_paths = set(paths)
    if not isinstance(value, dict) or set(value) != expected_paths:
        raise MutationJournalError(
            "workspace directory identity baseline is malformed"
        )
    identities: dict[str, tuple[int, int]] = {}
    for relative, record in value.items():
        if (
            not isinstance(relative, str)
            or not isinstance(record, dict)
            or set(record) != {"device", "inode"}
        ):
            raise MutationJournalError(
                "workspace directory identity baseline is malformed"
            )
        device = record.get("device")
        inode = record.get("inode")
        if any(
            isinstance(component, bool)
            or not isinstance(component, int)
            or component < 0
            for component in (device, inode)
        ):
            raise MutationJournalError(
                "workspace directory identity baseline is malformed"
            )
        identities[relative] = (cast(int, device), cast(int, inode))
    return identities


def _bound_workspace_directory_inventory(
    root_fd: int,
    *,
    excluded_roots: Iterable[str],
    require_restore_control: bool = False,
    logical_root: Path | None = None,
) -> dict[str, _BoundWorkspaceDirectoryRecord]:
    """Inventory real directories beneath one held workspace root."""

    excluded = tuple(_dedupe_roots(excluded_roots))

    def is_excluded(relative: str) -> bool:
        return any(
            relative == root or relative.startswith(root.rstrip("/") + "/")
            for root in excluded
        )

    root = os.fstat(root_fd)
    if not stat.S_ISDIR(root.st_mode):
        raise MutationJournalError("bound workspace root is not a directory")
    if require_restore_control:
        if logical_root is None:
            raise MutationJournalError(
                "bounded directory ownership validation lacks a logical root"
            )
        _assert_directory_restore_control(logical_root, root)
    inventory = {
        ".": _BoundWorkspaceDirectoryRecord(
            relative=".",
            device=root.st_dev,
            inode=root.st_ino,
            mode=stat.S_IMODE(root.st_mode),
            xattrs=_bound_descriptor_xattr_inventory(root_fd, label="."),
        )
    }
    paths = 1
    path_bytes = 1

    def walk(directory_fd: int, prefix: str, depth: int) -> None:
        nonlocal paths, path_bytes
        if depth > _MUTATION_JOURNAL_MAX_DISCOVERY_DEPTH:
            raise MutationJournalError(
                "workspace directory inventory exceeds its depth ceiling"
            )
        remaining = _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS - paths
        initial_names = _bounded_directory_names(
            directory_fd,
            label="bound workspace directory inventory",
            max_entries=remaining,
        )
        for name in initial_names:
            paths += 1
            if paths > _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS:
                raise MutationJournalError(
                    "workspace directory inventory exceeds its path ceiling"
                )
            relative = f"{prefix}/{name}" if prefix else name
            path_bytes += len(os.fsencode(relative))
            if path_bytes > _MUTATION_JOURNAL_MAX_DISCOVERY_PATH_BYTES:
                raise MutationJournalError(
                    "workspace directory inventory exceeds its path-byte ceiling"
                )
            if (not prefix and name == ".git") or is_excluded(relative):
                continue
            before = os.stat(
                name,
                dir_fd=directory_fd,
                follow_symlinks=False,
            )
            if not stat.S_ISDIR(before.st_mode) or stat.S_ISLNK(before.st_mode):
                continue
            child_fd, opened = _open_authority_directory_at(
                directory_fd,
                name,
                label=f"workspace directory {relative!r}",
            )
            try:
                record = _BoundWorkspaceDirectoryRecord(
                    relative=relative,
                    device=opened.st_dev,
                    inode=opened.st_ino,
                    mode=stat.S_IMODE(opened.st_mode),
                    xattrs=_bound_descriptor_xattr_inventory(
                        child_fd,
                        label=relative,
                    ),
                )
                if require_restore_control:
                    assert logical_root is not None
                    _assert_directory_restore_control(
                        logical_root / relative,
                        opened,
                    )
                inventory[relative] = record
                walk(child_fd, relative, depth + 1)
                held = os.fstat(child_fd)
                current = os.stat(
                    name,
                    dir_fd=directory_fd,
                    follow_symlinks=False,
                )
                if (
                    (held.st_dev, held.st_ino) != (record.device, record.inode)
                    or (current.st_dev, current.st_ino)
                    != (record.device, record.inode)
                ):
                    raise MutationJournalError(
                        f"workspace directory changed during inventory: {relative!r}"
                    )
            finally:
                os.close(child_fd)
        if _bounded_directory_names(
            directory_fd,
            label="bound workspace directory inventory",
            max_entries=max(
                _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS - paths,
                len(initial_names),
            ),
        ) != initial_names:
            raise MutationJournalError(
                "workspace directory topology changed during inventory"
            )

    walk(root_fd, "", 0)
    return inventory


def _workspace_directory_parent_chain(
    relative: str,
    authority: Mapping[str, _BoundWorkspaceDirectoryRecord],
) -> tuple[tuple[int, int], ...]:
    root = authority.get(".")
    if root is None:
        raise MutationJournalError("workspace root directory authority is absent")
    chain = [(root.device, root.inode)]
    for prefix in _workspace_restore_parent_prefixes(relative):
        record = authority.get(prefix)
        if record is None:
            raise MutationJournalError(
                f"workspace directory parent authority is absent: {prefix!r}"
            )
        chain.append((record.device, record.inode))
    return tuple(chain)


def _assert_bound_workspace_absence_token(
    root_fd: int,
    relative: str,
    authority: Mapping[str, _BoundWorkspaceDirectoryRecord],
) -> None:
    """Prove that a cross-root absence token names no node of any kind."""

    with _open_settlement_parent_if_present(root_fd, relative) as binding:
        parent_fd, name, parent_chain, missing_index = binding
        prefixes = _workspace_restore_parent_prefixes(relative)
        for index, identity in enumerate(parent_chain):
            authority_path = "." if index == 0 else prefixes[index - 1]
            record = authority.get(authority_path)
            if record is None or identity != (record.device, record.inode):
                raise MutationJournalError(
                    "workspace absence-token parent changed: "
                    f"{relative!r}"
                )
        if missing_index is not None:
            with _open_settlement_parent_if_present(root_fd, relative) as retry:
                (
                    _retry_fd,
                    _retry_name,
                    retry_chain,
                    retry_missing_index,
                ) = retry
                if (
                    retry_chain != parent_chain
                    or retry_missing_index != missing_index
                ):
                    raise MutationJournalError(
                        "workspace absence-token parent appeared: "
                        f"{relative!r}"
                    )
            return
        expected_chain = _workspace_directory_parent_chain(relative, authority)
        if parent_chain != expected_chain:
            raise MutationJournalError(
                f"workspace absence-token parent changed: {relative!r}"
            )
        _assert_settlement_parent_binding(
            root_fd,
            relative,
            parent_fd,
            parent_chain,
        )
        try:
            os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            _assert_settlement_parent_binding(
                root_fd,
                relative,
                parent_fd,
                parent_chain,
            )
            try:
                os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                return
        raise MutationJournalError(
            f"workspace absence token is no longer absent: {relative!r}"
        )


def _remove_bound_empty_workspace_directory(
    root_fd: int,
    relative: str,
    expected: _BoundWorkspaceDirectoryRecord,
    authority: Mapping[str, _BoundWorkspaceDirectoryRecord],
) -> None:
    """Remove one exact, still-empty addition without recursive deletion."""

    expected_chain = _workspace_directory_parent_chain(relative, authority)
    with _open_settlement_parent_if_present(root_fd, relative) as binding:
        parent_fd, name, parent_chain, missing_index = binding
        if missing_index is not None or parent_chain != expected_chain:
            raise MutationJournalError(
                f"workspace directory parent changed before removal: {relative!r}"
            )
        _assert_settlement_parent_binding(
            root_fd,
            relative,
            parent_fd,
            parent_chain,
        )
        directory_fd, opened = _open_authority_directory_at(
            parent_fd,
            name,
            label=f"workspace directory addition {relative!r}",
        )
        reservation_fd: int | None = None
        reservation_path_fd: int | None = None
        reservation_path_opened: os.stat_result | None = None
        reservation_created: os.stat_result | None = None
        quarantine: str | None = None
        try:
            if (opened.st_dev, opened.st_ino) != (
                expected.device,
                expected.inode,
            ):
                raise MutationJournalError(
                    f"workspace directory changed before removal: {relative!r}"
                )
            quarantine = _private_cleanup_quarantine_name(
                parent_fd,
                prefix=".crucible-cleanup-directory-",
            )
            os.mkdir(quarantine, mode=0o700, dir_fd=parent_fd)
            reservation_created = os.stat(
                quarantine,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
            if (
                not stat.S_ISDIR(reservation_created.st_mode)
                or stat.S_ISLNK(reservation_created.st_mode)
            ):
                raise MutationJournalError(
                    "workspace directory cleanup reservation changed after creation"
                )
            (
                reservation_path_fd,
                reservation_path_opened,
            ) = _open_authority_path_directory_at(
                parent_fd,
                quarantine,
                label="workspace directory cleanup reservation",
            )
            reservation_fd, readable_reservation = _open_authority_directory_at(
                parent_fd,
                quarantine,
                label="workspace directory cleanup reservation",
            )
            if (
                readable_reservation.st_dev,
                readable_reservation.st_ino,
            ) != (
                reservation_path_opened.st_dev,
                reservation_path_opened.st_ino,
            ):
                raise MutationJournalError(
                    "workspace directory cleanup reservation changed while binding"
                )
            _assert_settlement_parent_binding(
                root_fd,
                relative,
                parent_fd,
                parent_chain,
            )
            current = os.stat(
                name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
            if (current.st_dev, current.st_ino) != (
                expected.device,
                expected.inode,
            ):
                raise MutationJournalError(
                    f"workspace directory changed before removal: {relative!r}"
                )
            os.rename(
                name,
                quarantine,
                src_dir_fd=parent_fd,
                dst_dir_fd=parent_fd,
            )
            if os.fstat(reservation_fd).st_nlink != 0:
                raise MutationJournalError(
                    f"workspace directory quarantine failed: {relative!r}"
                )
            quarantined = os.stat(
                quarantine,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
            if (quarantined.st_dev, quarantined.st_ino) != (
                expected.device,
                expected.inode,
            ):
                _rename_bound_noreplace(
                    parent_fd,
                    quarantine,
                    name,
                    label=f"workspace directory quarantine rollback {relative!r}",
                )
                raise MutationJournalError(
                    f"workspace directory changed during quarantine: {relative!r}"
                )
            try:
                has_entries = _bound_directory_has_entries(
                    directory_fd,
                    label=f"workspace directory addition {relative!r}",
                )
            except BaseException as inspection_error:
                try:
                    _rename_bound_noreplace(
                        parent_fd,
                        quarantine,
                        name,
                        label=(
                            "workspace directory inspection rollback "
                            f"{relative!r}"
                        ),
                    )
                except BaseException as rollback_error:
                    raise MutationJournalError(
                        "cannot inspect quarantined workspace directory "
                        f"{relative!r}: {inspection_error}; rollback failed: "
                        f"{rollback_error}"
                    ) from inspection_error
                raise
            if has_entries:
                _rename_bound_noreplace(
                    parent_fd,
                    quarantine,
                    name,
                    label=f"workspace directory nonempty rollback {relative!r}",
                )
                raise MutationJournalError(
                    f"workspace directory addition is not empty: {relative!r}"
                )
            try:
                os.rmdir(quarantine, dir_fd=parent_fd)
            except OSError as exc:
                try:
                    _rename_bound_noreplace(
                        parent_fd,
                        quarantine,
                        name,
                        label=(
                            "workspace directory failed-removal rollback "
                            f"{relative!r}"
                        ),
                    )
                except BaseException as rollback_error:
                    raise MutationJournalError(
                        f"cannot remove empty workspace directory {relative!r}: "
                        f"{exc}; rollback failed: {rollback_error}"
                    ) from exc
                raise MutationJournalError(
                    f"cannot remove empty workspace directory {relative!r}: {exc}"
                ) from exc
            if os.fstat(directory_fd).st_nlink != 0:
                raise MutationJournalError(
                    f"workspace directory removal lost identity: {relative!r}"
                )
            _assert_settlement_parent_binding(
                root_fd,
                relative,
                parent_fd,
                parent_chain,
            )
            try:
                os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                pass
            else:
                raise MutationJournalError(
                    f"workspace directory remained after removal: {relative!r}"
                )
            _fsync_bound_directory(parent_fd)
        finally:
            try:
                if reservation_fd is not None:
                    reservation = os.fstat(reservation_fd)
                    if reservation.st_nlink != 0:
                        if quarantine is None:
                            raise MutationJournalError(
                                "workspace directory cleanup reservation lost its name"
                            )
                        current_reservation = os.stat(
                            quarantine,
                            dir_fd=parent_fd,
                            follow_symlinks=False,
                        )
                        if (
                            current_reservation.st_dev,
                            current_reservation.st_ino,
                        ) != (reservation.st_dev, reservation.st_ino):
                            raise MutationJournalError(
                                "workspace directory cleanup reservation changed"
                            )
                        if _bounded_directory_names(
                            reservation_fd,
                            label="workspace directory cleanup reservation",
                            max_entries=1,
                        ):
                            raise MutationJournalError(
                                "workspace directory cleanup reservation is not empty"
                            )
                        os.rmdir(quarantine, dir_fd=parent_fd)
                        if os.fstat(reservation_fd).st_nlink != 0:
                            raise MutationJournalError(
                                "workspace directory cleanup reservation was not removed"
                            )
                        _fsync_bound_directory(parent_fd)
                elif reservation_path_fd is not None:
                    assert reservation_path_opened is not None
                    assert quarantine is not None
                    _discard_private_bound_workspace_path_directory(
                        parent_fd,
                        quarantine,
                        reservation_path_fd,
                        reservation_path_opened,
                        label="workspace directory cleanup reservation",
                    )
                elif reservation_created is not None:
                    assert quarantine is not None
                    _bind_and_discard_created_private_workspace_directory(
                        parent_fd,
                        quarantine,
                        reservation_created,
                        label="workspace directory cleanup reservation",
                    )
            finally:
                if reservation_fd is not None:
                    os.close(reservation_fd)
                if reservation_path_fd is not None:
                    os.close(reservation_path_fd)
                os.close(directory_fd)


def _create_bound_workspace_baseline_directory(
    root_fd: int,
    relative: str,
    mode: int,
    xattrs: Mapping[str, str],
    authority: Mapping[str, _BoundWorkspaceDirectoryRecord],
) -> _BoundWorkspaceDirectoryRecord:
    """Publish one missing baseline directory with atomic no-replace."""

    expected_chain = _workspace_directory_parent_chain(relative, authority)
    with _open_settlement_parent_if_present(root_fd, relative) as binding:
        parent_fd, name, parent_chain, missing_index = binding
        if missing_index is not None or parent_chain != expected_chain:
            raise MutationJournalError(
                f"workspace directory parent changed before creation: {relative!r}"
            )
        _assert_settlement_parent_binding(
            root_fd,
            relative,
            parent_fd,
            parent_chain,
        )
        try:
            os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise MutationJournalError(
                f"workspace directory appeared before creation: {relative!r}"
            )
        private_name, directory_fd, opened = (
            _create_private_bound_workspace_directory(
                parent_fd,
                label=f"workspace baseline directory {relative!r}",
            )
        )
        try:
            _restore_bound_descriptor_xattrs(
                directory_fd,
                xattrs,
                label=relative,
            )
            os.fchmod(directory_fd, mode | 0o700)
            _fsync_bound_directory(directory_fd)
            _assert_settlement_parent_binding(
                root_fd,
                relative,
                parent_fd,
                parent_chain,
            )
            _publish_private_bound_workspace_directory(
                parent_fd,
                private_name,
                name,
                directory_fd,
                opened,
                label=f"workspace baseline directory {relative!r}",
            )
            _fsync_bound_directory(parent_fd)
            return _BoundWorkspaceDirectoryRecord(
                relative=relative,
                device=opened.st_dev,
                inode=opened.st_ino,
                mode=mode | 0o700,
                xattrs=dict(xattrs),
            )
        except BaseException as creation_error:
            try:
                current_private = os.stat(
                    private_name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                pass
            else:
                if (current_private.st_dev, current_private.st_ino) != (
                    opened.st_dev,
                    opened.st_ino,
                ):
                    raise MutationJournalError(
                        f"{creation_error}; private baseline directory changed "
                        f"for {relative!r}"
                    ) from creation_error
                try:
                    _discard_private_bound_workspace_directory(
                        parent_fd,
                        private_name,
                        directory_fd,
                        opened,
                        label=f"workspace baseline directory {relative!r}",
                    )
                except BaseException as cleanup_error:
                    raise MutationJournalError(
                        f"{creation_error}; private baseline directory cleanup "
                        f"failed for {relative!r}: {cleanup_error}"
                    ) from creation_error
            raise
        finally:
            os.close(directory_fd)


def _restore_bound_workspace_directory_metadata(
    root_fd: int,
    relative: str,
    expected: _BoundWorkspaceDirectoryRecord,
    mode: int,
    xattrs: Mapping[str, str],
    authority: Mapping[str, _BoundWorkspaceDirectoryRecord],
) -> None:
    """Restore one exact directory inode after all descendant operations."""

    if relative == ".":
        held = os.fstat(root_fd)
        if (held.st_dev, held.st_ino) != (expected.device, expected.inode):
            raise MutationJournalError("workspace root changed before metadata restore")
        _restore_bound_descriptor_xattrs(root_fd, xattrs, label=relative)
        os.fchmod(root_fd, mode)
        _fsync_bound_directory(root_fd)
        return
    expected_chain = _workspace_directory_parent_chain(relative, authority)
    with _open_settlement_parent_if_present(root_fd, relative) as binding:
        parent_fd, name, parent_chain, missing_index = binding
        if missing_index is not None or parent_chain != expected_chain:
            raise MutationJournalError(
                f"workspace directory parent changed before metadata restore: "
                f"{relative!r}"
            )
        _assert_settlement_parent_binding(
            root_fd,
            relative,
            parent_fd,
            parent_chain,
        )
        directory_fd, opened = _open_authority_directory_at(
            parent_fd,
            name,
            label=f"workspace directory metadata {relative!r}",
        )
        try:
            if (opened.st_dev, opened.st_ino) != (
                expected.device,
                expected.inode,
            ):
                raise MutationJournalError(
                    f"workspace directory changed before metadata restore: "
                    f"{relative!r}"
                )
            _restore_bound_descriptor_xattrs(directory_fd, xattrs, label=relative)
            os.fchmod(directory_fd, mode)
            _fsync_bound_directory(directory_fd)
            current = os.stat(
                name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
            held = os.fstat(directory_fd)
            if (
                (current.st_dev, current.st_ino)
                != (expected.device, expected.inode)
                or (held.st_dev, held.st_ino)
                != (expected.device, expected.inode)
            ):
                raise MutationJournalError(
                    f"workspace directory changed during metadata restore: "
                    f"{relative!r}"
                )
            _assert_settlement_parent_binding(
                root_fd,
                relative,
                parent_fd,
                parent_chain,
            )
        finally:
            os.close(directory_fd)


def _bound_descriptor_xattr_inventory(
    descriptor: int,
    *,
    label: str,
) -> dict[str, str]:
    """Read one bounded exact xattr image through a held descriptor."""

    if not hasattr(os, "listxattr"):
        return {}
    try:
        names = sorted(os.listxattr(descriptor))
    except OSError as exc:
        if exc.errno in {errno.ENOTSUP, errno.EOPNOTSUPP}:
            return {}
        raise MutationJournalError(
            f"cannot inspect xattrs for {label}: {exc}"
        ) from exc
    if len(names) > 256:
        raise MutationJournalError(
            f"too many xattrs for exact rollback: {label}"
        )
    inventory: dict[str, str] = {}
    total_bytes = 0
    for name in names:
        try:
            value = os.getxattr(descriptor, name)
        except OSError as exc:
            raise MutationJournalError(
                f"cannot read xattr {name!r} for {label}: {exc}"
            ) from exc
        total_bytes += len(os.fsencode(name)) + len(value)
        if total_bytes > 4 * 1024 * 1024:
            raise MutationJournalError(
                f"xattrs too large for exact rollback: {label}"
            )
        inventory[name] = value.hex()
    return inventory


def _reprove_bound_workspace_directory_authority(
    root_fd: int,
    authority: Mapping[str, _BoundWorkspaceDirectoryRecord],
    expected_modes: Mapping[str, int],
    expected_xattrs: Mapping[str, Mapping[str, str]],
    *,
    excluded_roots: Iterable[str],
) -> dict[str, _BoundWorkspaceDirectoryRecord]:
    """Freshly prove final directory topology, identity, mode, and xattrs."""

    observed = _bound_workspace_directory_inventory(
        root_fd,
        excluded_roots=excluded_roots,
    )
    if set(observed) != set(authority) or set(observed) != set(expected_modes):
        raise MutationJournalError(
            "workspace directory topology changed after metadata restoration"
        )
    for relative in sorted(
        observed,
        key=lambda path: (path.count("/"), path),
    ):
        expected = authority[relative]
        current = observed[relative]
        if (
            (current.device, current.inode)
            != (expected.device, expected.inode)
            or current.mode != expected_modes[relative]
        ):
            raise MutationJournalError(
                "workspace directory authority changed after restoration: "
                f"{relative!r}"
            )

        def assert_descriptor(
            descriptor: int,
            *,
            expected: _BoundWorkspaceDirectoryRecord = expected,
            relative: str = relative,
        ) -> None:
            held = os.fstat(descriptor)
            if (
                (held.st_dev, held.st_ino)
                != (expected.device, expected.inode)
                or stat.S_IMODE(held.st_mode) != expected_modes[relative]
                or _bound_descriptor_xattr_inventory(
                    descriptor,
                    label=relative,
                )
                != expected_xattrs[relative]
            ):
                raise MutationJournalError(
                    "workspace directory metadata changed during final proof: "
                    f"{relative!r}"
                )

        if relative == ".":
            assert_descriptor(root_fd)
            continue
        else:
            expected_chain = _workspace_directory_parent_chain(
                relative,
                observed,
            )
        with _open_settlement_parent_if_present(
            root_fd,
            relative,
        ) as binding:
            parent_fd, name, parent_chain, missing_index = binding
            if missing_index is not None or parent_chain != expected_chain:
                raise MutationJournalError(
                    "workspace directory parent changed during final proof: "
                    f"{relative!r}"
                )
            descriptor, opened = _open_authority_directory_at(
                parent_fd,
                name,
                label=f"final workspace directory {relative!r}",
            )
            try:
                if (opened.st_dev, opened.st_ino) != (
                    expected.device,
                    expected.inode,
                ):
                    raise MutationJournalError(
                        "workspace directory changed during final proof: "
                        f"{relative!r}"
                    )
                assert_descriptor(descriptor)
                _assert_settlement_parent_binding(
                    root_fd,
                    relative,
                    parent_fd,
                    parent_chain,
                )
            finally:
                os.close(descriptor)
    return observed


def _remove_bound_workspace_entry(
    root_fd: int,
    relative: str,
    parent_fd: int,
    name: str,
    parent_chain: tuple[tuple[int, int], ...],
    *,
    allow_terminal_vcs_metadata: bool = False,
    expected_top_metadata: tuple[int, ...] | None = None,
) -> None:
    """Remove one workspace node/tree without following any path alias.

    The caller intentionally passes its held parent so tests and recovery code
    can exercise the exact race boundary.  Every destructive step first proves
    that the held chain and the top entry still occupy the root-relative path.
    Binding loss raises before that step and leaves the journal armed.
    """

    relative = _settlement_relative_path(
        relative,
        allow_terminal_vcs_metadata=allow_terminal_vcs_metadata,
    )
    budget = _MutationJournalArtifactBudget()

    def assert_parent() -> None:
        _assert_settlement_parent_binding(
            root_fd,
            relative,
            parent_fd,
            parent_chain,
            allow_terminal_vcs_metadata=allow_terminal_vcs_metadata,
        )

    try:
        top_metadata = os.stat(
            name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
    except FileNotFoundError:
        assert_parent()
        try:
            os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            assert_parent()
            return
        raise MutationJournalError(
            f"workspace restore path appeared during absence proof: {relative!r}"
        ) from None
    except (OSError, TypeError, ValueError) as exc:
        raise MutationJournalError(
            f"cannot inspect workspace restore path {relative!r}: {exc}"
        ) from exc

    top_identity = (top_metadata.st_dev, top_metadata.st_ino)
    if (
        expected_top_metadata is not None
        and _git_admin_file_metadata(top_metadata) != expected_top_metadata
    ):
        raise MutationJournalError(
            f"workspace restore path changed before removal: {relative!r}"
        )

    def assert_top() -> None:
        assert_parent()
        try:
            current = os.stat(
                name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except (OSError, TypeError, ValueError) as exc:
            raise MutationJournalError(
                f"workspace restore path changed before removal: {relative!r}"
            ) from exc
        if (
            (current.st_dev, current.st_ino) != top_identity
            or (
                expected_top_metadata is not None
                and _git_admin_file_metadata(current)
                != expected_top_metadata
            )
        ):
            raise MutationJournalError(
                f"workspace restore path changed before removal: {relative!r}"
            )

    def remove_at(
        current_parent_fd: int,
        entry_name: str,
        entry_label: str,
        depth: int,
        revalidate: Callable[[], None],
    ) -> None:
        if depth > _MUTATION_JOURNAL_MAX_DISCOVERY_DEPTH:
            raise MutationJournalError(
                "workspace restore removal exceeds its depth ceiling"
            )
        revalidate()
        before = os.stat(
            entry_name,
            dir_fd=current_parent_fd,
            follow_symlinks=False,
        )
        if stat.S_ISDIR(before.st_mode) and not stat.S_ISLNK(before.st_mode):
            child_fd = os.open(
                entry_name,
                os.O_RDONLY
                | getattr(os, "O_CLOEXEC", 0)
                | getattr(os, "O_DIRECTORY", 0)
                | getattr(os, "O_NOFOLLOW", 0),
                dir_fd=current_parent_fd,
            )
            try:
                opened = os.fstat(child_fd)
                if (
                    not stat.S_ISDIR(opened.st_mode)
                    or (opened.st_dev, opened.st_ino)
                    != (before.st_dev, before.st_ino)
                ):
                    raise MutationJournalError(
                        f"workspace restore directory changed: {entry_label!r}"
                    )

                def assert_child() -> None:
                    revalidate()
                    current = os.stat(
                        entry_name,
                        dir_fd=current_parent_fd,
                        follow_symlinks=False,
                    )
                    if (
                        not stat.S_ISDIR(current.st_mode)
                        or stat.S_ISLNK(current.st_mode)
                        or (current.st_dev, current.st_ino)
                        != (opened.st_dev, opened.st_ino)
                    ):
                        raise MutationJournalError(
                            "workspace restore directory changed before "
                            f"removal: {entry_label!r}"
                        )

                remaining = (
                    _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS
                    - budget.paths
                )
                for child_name in _bounded_directory_names(
                    child_fd,
                    label="workspace restore removal",
                    max_entries=max(remaining, 0),
                ):
                    budget.charge_path()
                    child_label = f"{entry_label}/{child_name}"
                    remove_at(
                        child_fd,
                        child_name,
                        child_label,
                        depth + 1,
                        assert_child,
                    )
                if _bounded_directory_names(
                    child_fd,
                    label="workspace restore removal",
                    max_entries=1,
                ):
                    raise MutationJournalError(
                        "workspace restore directory changed during removal: "
                        f"{entry_label!r}"
                    )
                assert_child()
                os.rmdir(entry_name, dir_fd=current_parent_fd)
                _fsync_bound_directory(current_parent_fd)
            finally:
                os.close(child_fd)
            return

        # unlink(2) never follows the final component.  Re-read the exact entry
        # after the root/top binding check so a replacement directory fails
        # closed instead of redirecting a recursive delete.
        revalidate()
        current = os.stat(
            entry_name,
            dir_fd=current_parent_fd,
            follow_symlinks=False,
        )
        if (
            stat.S_ISDIR(current.st_mode)
            or (current.st_dev, current.st_ino) != (before.st_dev, before.st_ino)
        ):
            raise MutationJournalError(
                f"workspace restore entry changed before unlink: {entry_label!r}"
            )
        os.unlink(entry_name, dir_fd=current_parent_fd)
        _fsync_bound_directory(current_parent_fd)

    remove_at(parent_fd, name, relative, 0, assert_top)
    assert_parent()
    try:
        os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except FileNotFoundError:
        assert_parent()
        return
    raise MutationJournalError(
        f"workspace restore path remained after removal: {relative!r}"
    )


def _write_all_bound(descriptor: int, payload: bytes) -> None:
    view = memoryview(payload)
    written = 0
    while written < len(view):
        count = os.write(descriptor, view[written:])
        if count <= 0:
            raise MutationJournalError(
                "descriptor-relative workspace restore made no write progress"
            )
        written += count


def _link_bound_unnamed_noreplace(
    temporary_fd: int,
    parent_fd: int,
    final_name: str,
    *,
    label: str,
) -> None:
    """Atomically link one anonymous file without replacing a final entry."""

    if final_name in {"", ".", ".."} or "/" in final_name:
        raise MutationJournalError(
            f"atomic file publication has unsafe target for {label}"
        )
    try:
        linkat = ctypes.CDLL(None, use_errno=True).linkat
    except (AttributeError, OSError) as exc:
        raise MutationJournalError(
            f"atomic file publication is unavailable for {label}"
        ) from exc
    linkat.argtypes = (
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_int,
    )
    linkat.restype = ctypes.c_int
    # AT_EMPTY_PATH is the direct kernel binding. Some constrained containers
    # lack CAP_DAC_READ_SEARCH for that form; the verified /proc fd alias with
    # AT_SYMLINK_FOLLOW is the documented unprivileged O_TMPFILE fallback.
    result = linkat(
        temporary_fd,
        b"",
        parent_fd,
        os.fsencode(final_name),
        0x1000,  # AT_EMPTY_PATH
    )
    error = ctypes.get_errno() if result != 0 else 0
    if result != 0 and error in {errno.ENOENT, errno.EPERM}:
        source = _authority_descriptor_cwd(temporary_fd)
        result = linkat(
            -100,  # AT_FDCWD
            os.fsencode(source),
            parent_fd,
            os.fsencode(final_name),
            0x400,  # AT_SYMLINK_FOLLOW
        )
        error = ctypes.get_errno() if result != 0 else 0
    if result == 0:
        return
    if error in {errno.EEXIST, errno.ENOTEMPTY}:
        raise MutationJournalError(
            f"atomic file publication target appeared for {label}"
        )
    if error in {
        errno.ENOSYS,
        errno.EINVAL,
        errno.EOPNOTSUPP,
        errno.ENOENT,
        errno.EPERM,
    }:
        raise MutationJournalError(
            f"atomic file publication is unsupported for {label}"
        )
    raise MutationJournalError(
        f"cannot atomically publish file for {label}: {os.strerror(error)}"
    )


def _publish_bound_regular_noreplace(
    parent_fd: int,
    final_name: str,
    payload: bytes,
    *,
    label: str,
) -> os.stat_result:
    """Durably publish complete bytes under one absent held-parent name.

    The file remains anonymous until its bytes and inode are durable. A process
    death before the no-replace link therefore leaves no partial namespace
    authority, while a colliding final entry is never overwritten.
    """

    temporary_flag = getattr(os, "O_TMPFILE", 0)
    if temporary_flag == 0:
        raise MutationJournalError(
            f"anonymous atomic file publication is unavailable for {label}"
        )
    temporary_fd: int | None = None
    try:
        try:
            temporary_fd = os.open(
                ".",
                os.O_RDWR
                | temporary_flag
                | getattr(os, "O_CLOEXEC", 0)
                | getattr(os, "O_NOFOLLOW", 0),
                0o600,
                dir_fd=parent_fd,
            )
        except OSError as exc:
            raise MutationJournalError(
                f"cannot create anonymous publication file for {label}: {exc}"
            ) from exc
        opened = os.fstat(temporary_fd)
        if not stat.S_ISREG(opened.st_mode) or opened.st_nlink != 0:
            raise MutationJournalError(
                f"anonymous publication inode is unsafe for {label}"
            )
        _write_all_bound(temporary_fd, payload)
        os.fsync(temporary_fd)
        prepared = os.fstat(temporary_fd)
        if (
            not stat.S_ISREG(prepared.st_mode)
            or prepared.st_nlink != 0
            or prepared.st_size != len(payload)
            or (prepared.st_dev, prepared.st_ino)
            != (opened.st_dev, opened.st_ino)
        ):
            raise MutationJournalError(
                f"anonymous publication inode changed for {label}"
            )
        _link_bound_unnamed_noreplace(
            temporary_fd,
            parent_fd,
            final_name,
            label=label,
        )
        published = os.stat(
            final_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        linked = os.fstat(temporary_fd)
        if (
            not stat.S_ISREG(published.st_mode)
            or published.st_nlink != 1
            or linked.st_nlink != 1
            or published.st_size != len(payload)
            or (published.st_dev, published.st_ino)
            != (linked.st_dev, linked.st_ino)
        ):
            raise MutationJournalError(
                f"published file binding changed for {label}"
            )
        os.lseek(temporary_fd, 0, os.SEEK_SET)
        observed = bytearray()
        while len(observed) <= len(payload):
            chunk = os.read(
                temporary_fd,
                min(1024 * 1024, len(payload) + 1 - len(observed)),
            )
            if not chunk:
                break
            observed.extend(chunk)
        finished = os.fstat(temporary_fd)
        current = os.stat(
            final_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if bytes(observed) != payload or any(
            getattr(linked, field) != getattr(finished, field)
            or getattr(linked, field) != getattr(current, field)
            for field in _SETTLEMENT_STABLE_STAT_FIELDS
        ):
            raise MutationJournalError(
                f"published file bytes changed for {label}"
            )
        _fsync_bound_directory(parent_fd)
        return current
    finally:
        if temporary_fd is not None:
            os.close(temporary_fd)


def _claim_bound_workspace_file(
    parent_fd: int,
    name: str,
) -> int:
    """Atomically claim one absent final file name without replacement."""

    return os.open(
        name,
        os.O_WRONLY
        | os.O_CREAT
        | os.O_EXCL
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0),
        0o600,
        dir_fd=parent_fd,
    )


def _rename_bound_noreplace(
    directory_fd: int,
    source_name: str,
    destination_name: str,
    *,
    label: str,
) -> None:
    """Atomically publish a private entry without replacing a live target."""

    if any(
        not isinstance(name, str)
        or name in {"", ".", ".."}
        or "/" in name
        or "\0" in name
        for name in (source_name, destination_name)
    ):
        raise MutationJournalError(
            f"atomic no-replace publication has an invalid name for {label}"
        )
    try:
        renameat2 = ctypes.CDLL(None, use_errno=True).renameat2
    except (AttributeError, OSError) as exc:
        raise MutationJournalError(
            f"atomic no-replace publication is unavailable for {label}"
        ) from exc
    renameat2.argtypes = (
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_uint,
    )
    renameat2.restype = ctypes.c_int
    result = renameat2(
        directory_fd,
        os.fsencode(source_name),
        directory_fd,
        os.fsencode(destination_name),
        1,  # RENAME_NOREPLACE
    )
    if result == 0:
        return
    error = ctypes.get_errno()
    if error in {errno.ENOSYS, errno.EINVAL, errno.EOPNOTSUPP}:
        raise MutationJournalError(
            f"atomic no-replace publication is unsupported for {label}"
        )
    if error in {errno.EEXIST, errno.ENOTEMPTY}:
        raise MutationJournalError(
            f"workspace restore target appeared before publication: {label}"
        )
    raise MutationJournalError(
        f"cannot publish workspace restore directory for {label}: "
        f"{os.strerror(error)}"
    )


def _discard_private_bound_workspace_directory(
    parent_fd: int,
    name: str,
    descriptor: int,
    expected: os.stat_result,
    *,
    label: str,
) -> None:
    """Remove one exact empty private directory without touching unknown bytes."""

    parent = os.fstat(parent_fd)
    record = _BoundWorkspaceDirectoryRecord(
        relative=name,
        device=expected.st_dev,
        inode=expected.st_ino,
        mode=stat.S_IMODE(expected.st_mode),
        xattrs={},
    )
    held = os.fstat(descriptor)
    if (held.st_dev, held.st_ino) != (record.device, record.inode):
        raise MutationJournalError(
            f"private workspace directory changed before discard for {label}"
        )
    _remove_bound_empty_workspace_directory(
        parent_fd,
        name,
        record,
        {
            ".": _BoundWorkspaceDirectoryRecord(
                relative=".",
                device=parent.st_dev,
                inode=parent.st_ino,
                mode=stat.S_IMODE(parent.st_mode),
                xattrs={},
            ),
            name: record,
        },
    )


def _discard_private_bound_workspace_path_directory(
    parent_fd: int,
    name: str,
    descriptor: int,
    expected: os.stat_result,
    *,
    label: str,
) -> None:
    """Remove one exact empty private directory held only through ``O_PATH``."""

    held = os.fstat(descriptor)
    try:
        current = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except OSError as exc:
        raise MutationJournalError(
            f"cannot inspect private workspace directory for {label}: {exc}"
        ) from exc
    if (
        not stat.S_ISDIR(held.st_mode)
        or stat.S_ISLNK(current.st_mode)
        or (held.st_dev, held.st_ino) != (expected.st_dev, expected.st_ino)
        or (current.st_dev, current.st_ino)
        != (expected.st_dev, expected.st_ino)
    ):
        raise MutationJournalError(
            f"private workspace directory changed before discard for {label}"
        )
    try:
        # rmdir is deliberately the only deletion primitive here: injected or
        # unknown content makes it fail closed instead of recursively deleting
        # bytes that were never workflow-owned.
        os.rmdir(name, dir_fd=parent_fd)
    except OSError as exc:
        raise MutationJournalError(
            f"cannot discard exact empty private directory for {label}: {exc}"
        ) from exc
    if os.fstat(descriptor).st_nlink != 0:
        raise MutationJournalError(
            f"private workspace directory changed during discard for {label}"
        )
    _fsync_bound_directory(parent_fd)


def _bind_and_discard_created_private_workspace_directory(
    parent_fd: int,
    name: str,
    created: os.stat_result,
    *,
    label: str,
) -> None:
    """Recover a just-created private directory after its first bind failed."""

    descriptor, opened = _open_authority_path_directory_at(
        parent_fd,
        name,
        label=label,
    )
    try:
        if (opened.st_dev, opened.st_ino) != (
            created.st_dev,
            created.st_ino,
        ):
            raise MutationJournalError(
                f"created private workspace directory changed for {label}"
            )
        _discard_private_bound_workspace_path_directory(
            parent_fd,
            name,
            descriptor,
            opened,
            label=label,
        )
    finally:
        os.close(descriptor)


def _create_private_bound_workspace_directory(
    parent_fd: int,
    *,
    label: str,
) -> tuple[str, int, os.stat_result]:
    """Create and bind an unguessable staging directory in a held parent."""

    for _attempt in range(16):
        private_name = f".crucible-restore-dir-{secrets.token_hex(32)}"
        watch_fd: int | None = None
        path_descriptor: int | None = None
        path_opened: os.stat_result | None = None
        created_metadata: os.stat_result | None = None
        descriptor: int | None = None
        opened: os.stat_result | None = None
        try:
            try:
                libc = ctypes.CDLL(None, use_errno=True)
                inotify_init1 = libc.inotify_init1
                inotify_add_watch = libc.inotify_add_watch
            except (AttributeError, OSError) as exc:
                raise MutationJournalError(
                    f"bound directory creation watch is unavailable for {label}"
                ) from exc
            inotify_init1.argtypes = (ctypes.c_int,)
            inotify_init1.restype = ctypes.c_int
            inotify_add_watch.argtypes = (
                ctypes.c_int,
                ctypes.c_char_p,
                ctypes.c_uint32,
            )
            inotify_add_watch.restype = ctypes.c_int
            watch_fd = inotify_init1(
                getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NONBLOCK", 0)
            )
            if watch_fd < 0:
                error = ctypes.get_errno()
                raise MutationJournalError(
                    f"cannot initialize bound creation watch for {label}: "
                    f"{os.strerror(error)}"
                )
            watch_mask = 0x00000100 | 0x00000200 | 0x00000040 | 0x00000080
            watch_mask |= 0x00000400 | 0x00000800
            watch_descriptor = inotify_add_watch(
                watch_fd,
                os.fsencode(_authority_descriptor_cwd(parent_fd)),
                watch_mask,
            )
            if watch_descriptor < 0:
                error = ctypes.get_errno()
                raise MutationJournalError(
                    f"cannot bind creation watch for {label}: {os.strerror(error)}"
                )
            try:
                os.mkdir(private_name, mode=0o700, dir_fd=parent_fd)
            except FileExistsError:
                continue
            created_metadata = os.stat(
                private_name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
            if not stat.S_ISDIR(created_metadata.st_mode) or stat.S_ISLNK(
                created_metadata.st_mode
            ):
                raise MutationJournalError(
                    f"private workspace restore directory changed after "
                    f"creation for {label}"
                )
            path_descriptor, path_opened = _open_authority_path_directory_at(
                parent_fd,
                private_name,
                label=f"private {label}",
            )
            descriptor, opened = _open_authority_directory_at(
                parent_fd,
                private_name,
                label=f"private {label}",
            )
            if (opened.st_dev, opened.st_ino) != (
                path_opened.st_dev,
                path_opened.st_ino,
            ):
                raise MutationJournalError(
                    f"private workspace restore directory changed while "
                    f"binding for {label}"
                )

            encoded_events = bytearray()
            while True:
                try:
                    chunk = os.read(watch_fd, 64 * 1024)
                except BlockingIOError:
                    break
                if not chunk:
                    break
                encoded_events.extend(chunk)
                if len(encoded_events) > _CONTROL_FILE_MAX_BYTES:
                    raise MutationJournalError(
                        f"bound creation watch overflowed for {label}"
                    )
            offset = 0
            created_events = 0
            unsafe = False
            while offset < len(encoded_events):
                if len(encoded_events) - offset < 16:
                    raise MutationJournalError(
                        f"bound creation watch is malformed for {label}"
                    )
                _watch, mask, _cookie, name_length = struct.unpack_from(
                    "iIII",
                    encoded_events,
                    offset,
                )
                offset += 16
                if name_length > len(encoded_events) - offset:
                    raise MutationJournalError(
                        f"bound creation watch is malformed for {label}"
                    )
                encoded_name = bytes(
                    encoded_events[offset : offset + name_length]
                ).split(b"\0", 1)[0]
                offset += name_length
                if mask & (0x00004000 | 0x00008000):
                    unsafe = True
                if encoded_name != os.fsencode(private_name):
                    continue
                if mask & 0x00000100 and mask & 0x40000000:
                    created_events += 1
                if mask & (0x00000200 | 0x00000040 | 0x00000080):
                    unsafe = True
            if created_events != 1 or unsafe:
                raise MutationJournalError(
                    f"private workspace restore directory changed during "
                    f"creation for {label}"
                )
            os.close(path_descriptor)
            path_descriptor = None
            return private_name, descriptor, opened
        except BaseException as creation_error:
            if descriptor is not None:
                try:
                    assert opened is not None
                    _discard_private_bound_workspace_directory(
                        parent_fd,
                        private_name,
                        descriptor,
                        opened,
                        label=label,
                    )
                except BaseException as cleanup_error:
                    raise MutationJournalError(
                        f"{creation_error}; private directory cleanup failed "
                        f"for {label}: {cleanup_error}"
                    ) from creation_error
                finally:
                    os.close(descriptor)
            elif path_descriptor is not None:
                try:
                    assert path_opened is not None
                    _discard_private_bound_workspace_path_directory(
                        parent_fd,
                        private_name,
                        path_descriptor,
                        path_opened,
                        label=label,
                    )
                except BaseException as cleanup_error:
                    raise MutationJournalError(
                        f"{creation_error}; private directory cleanup failed "
                        f"for {label}: {cleanup_error}"
                    ) from creation_error
            elif created_metadata is not None:
                try:
                    _bind_and_discard_created_private_workspace_directory(
                        parent_fd,
                        private_name,
                        created_metadata,
                        label=label,
                    )
                except BaseException as cleanup_error:
                    raise MutationJournalError(
                        f"{creation_error}; private directory cleanup failed "
                        f"for {label}: {cleanup_error}"
                    ) from creation_error
            raise
        finally:
            if path_descriptor is not None:
                os.close(path_descriptor)
            if watch_fd is not None:
                os.close(watch_fd)
    raise MutationJournalError(
        f"cannot reserve private workspace restore directory for {label}"
    )


def _open_bound_directory_content_watch(
    descriptor: int,
    *,
    label: str,
) -> int:
    """Watch one held staging inode for child-name mutations."""

    try:
        libc = ctypes.CDLL(None, use_errno=True)
        inotify_init1 = libc.inotify_init1
        inotify_add_watch = libc.inotify_add_watch
    except (AttributeError, OSError) as exc:
        raise MutationJournalError(
            f"bound directory content watch is unavailable for {label}"
        ) from exc
    inotify_init1.argtypes = (ctypes.c_int,)
    inotify_init1.restype = ctypes.c_int
    inotify_add_watch.argtypes = (
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_uint32,
    )
    inotify_add_watch.restype = ctypes.c_int
    watch_fd = inotify_init1(
        getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NONBLOCK", 0)
    )
    if watch_fd < 0:
        error = ctypes.get_errno()
        raise MutationJournalError(
            f"cannot initialize bound content watch for {label}: "
            f"{os.strerror(error)}"
        )
    # Child create/delete and move-to/from events cover files, hardlinks, and
    # directories.  Queue overflow/unmount/ignored are reported regardless of
    # the requested mask and are treated as lost integrity below.
    watch_mask = (
        0x00000100
        | 0x00000200
        | 0x00000040
        | 0x00000080
        | 0x00000400
        | 0x00000800
    )
    watch_descriptor = inotify_add_watch(
        watch_fd,
        os.fsencode(_authority_descriptor_cwd(descriptor)),
        watch_mask,
    )
    if watch_descriptor < 0:
        error = ctypes.get_errno()
        os.close(watch_fd)
        raise MutationJournalError(
            f"cannot bind directory content watch for {label}: "
            f"{os.strerror(error)}"
        )
    return watch_fd


def _bound_directory_content_watch_changed(
    watch_fd: int,
    *,
    label: str,
    expected_self_moves: int = 0,
) -> bool:
    """Drain a staging watch and report any child mutation or lost event."""

    encoded_events = bytearray()
    while True:
        try:
            chunk = os.read(watch_fd, 64 * 1024)
        except BlockingIOError:
            break
        if not chunk:
            break
        encoded_events.extend(chunk)
        if len(encoded_events) > _CONTROL_FILE_MAX_BYTES:
            raise MutationJournalError(
                f"bound directory content watch overflowed for {label}"
            )
    offset = 0
    changed = False
    self_moves = 0
    while offset < len(encoded_events):
        if len(encoded_events) - offset < 16:
            raise MutationJournalError(
                f"bound directory content watch is malformed for {label}"
            )
        _watch, mask, _cookie, name_length = struct.unpack_from(
            "iIII",
            encoded_events,
            offset,
        )
        offset += 16
        if name_length > len(encoded_events) - offset:
            raise MutationJournalError(
                f"bound directory content watch is malformed for {label}"
            )
        encoded_name = bytes(
            encoded_events[offset : offset + name_length]
        ).split(b"\0", 1)[0]
        offset += name_length
        if mask & (0x00000400 | 0x00002000 | 0x00004000 | 0x00008000):
            changed = True
        if mask & 0x00000800:
            self_moves += 1
        if encoded_name:
            changed = True
    return changed or self_moves != expected_self_moves


def _retract_bound_directory_publication(
    parent_fd: int,
    final_name: str,
    private_name: str,
    published: os.stat_result,
    *,
    label: str,
) -> None:
    """Move one unsafe successful publication back without deleting bytes."""

    _rename_bound_noreplace(
        parent_fd,
        final_name,
        private_name,
        label=f"unsafe publication rollback for {label}",
    )
    returned = os.stat(
        private_name,
        dir_fd=parent_fd,
        follow_symlinks=False,
    )
    if (returned.st_dev, returned.st_ino) != (
        published.st_dev,
        published.st_ino,
    ):
        raise MutationJournalError(
            f"returned workspace restore staging changed for {label}"
        )
    _fsync_bound_directory(parent_fd)


def _publish_private_bound_workspace_directory(
    parent_fd: int,
    private_name: str,
    final_name: str,
    descriptor: int,
    expected: os.stat_result,
    *,
    label: str,
) -> None:
    """Publish the held private directory and prove its final name binding."""

    watch_fd = _open_bound_directory_content_watch(
        descriptor,
        label=label,
    )
    try:
        held = os.fstat(descriptor)
        private = os.stat(
            private_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if (
            (held.st_dev, held.st_ino) != (expected.st_dev, expected.st_ino)
            or (private.st_dev, private.st_ino)
            != (expected.st_dev, expected.st_ino)
        ):
            raise MutationJournalError(
                f"private workspace restore directory changed for {label}"
            )
        if _bounded_directory_names(
            descriptor,
            label=f"private workspace restore directory for {label}",
            max_entries=1,
        ) or _bound_directory_content_watch_changed(
            watch_fd,
            label=label,
        ):
            raise MutationJournalError(
                f"private workspace restore directory is not empty for {label}"
            )
        try:
            _rename_bound_noreplace(
                parent_fd,
                private_name,
                final_name,
                label=label,
            )
        except BaseException as publication_error:
            try:
                current = os.stat(
                    private_name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
                if (current.st_dev, current.st_ino) != (
                    expected.st_dev,
                    expected.st_ino,
                ):
                    raise MutationJournalError(
                        f"private workspace restore directory changed for {label}"
                    )
                # Staging is created empty.  Never recurse here: a same-UID
                # adversary can inject an external hardlink or moved directory
                # after the emptiness proof but before a publication collision.
                # rmdir either removes the still-empty inode or fails closed while
                # retaining every unknown byte for operator recovery.
                os.rmdir(private_name, dir_fd=parent_fd)
                _fsync_bound_directory(parent_fd)
            except BaseException as cleanup_error:
                raise MutationJournalError(
                    f"{publication_error}; private staging cleanup failed for "
                    f"{label}: {cleanup_error}"
                ) from publication_error
            raise
        published = os.stat(
            final_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        held = os.fstat(descriptor)
        if (
            (published.st_dev, published.st_ino)
            != (expected.st_dev, expected.st_ino)
            or (held.st_dev, held.st_ino)
            != (expected.st_dev, expected.st_ino)
        ):
            integrity_error = MutationJournalError(
                f"published workspace restore directory changed for {label}"
            )
            try:
                _retract_bound_directory_publication(
                    parent_fd,
                    final_name,
                    private_name,
                    published,
                    label=label,
                )
            except BaseException as rollback_error:
                raise MutationJournalError(
                    f"{integrity_error}; unsafe publication rollback failed "
                    f"for {label}: {rollback_error}"
                ) from integrity_error
            raise integrity_error
        if _bound_directory_content_watch_changed(
            watch_fd,
            label=label,
            expected_self_moves=1,
        ):
            integrity_error = MutationJournalError(
                f"private workspace restore directory changed during "
                f"publication for {label}"
            )
            try:
                current = os.stat(
                    final_name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
                if (current.st_dev, current.st_ino) != (
                    expected.st_dev,
                    expected.st_ino,
                ):
                    raise MutationJournalError(
                        f"published workspace restore directory changed for {label}"
                    )
                _retract_bound_directory_publication(
                    parent_fd,
                    final_name,
                    private_name,
                    published,
                    label=label,
                )
            except BaseException as rollback_error:
                raise MutationJournalError(
                    f"{integrity_error}; unsafe publication rollback failed "
                    f"for {label}: {rollback_error}"
                ) from integrity_error
            raise integrity_error
    finally:
        os.close(watch_fd)


def _install_bound_workspace_entry(
    root_fd: int,
    relative: str,
    *,
    expected_parent_chain: tuple[tuple[int, int], ...],
    kind: str,
    mode: int,
    xattrs: Mapping[str, str],
    payload: bytes | None = None,
    target: str | None = None,
    allow_terminal_vcs_metadata: bool = False,
) -> tuple[int, int]:
    """Install one absent baseline entry through its held no-follow parent."""

    relative = _settlement_relative_path(
        relative,
        allow_terminal_vcs_metadata=allow_terminal_vcs_metadata,
    )
    with _open_settlement_parent_if_present(
        root_fd,
        relative,
        allow_terminal_vcs_metadata=allow_terminal_vcs_metadata,
    ) as binding:
        parent_fd, name, parent_chain, missing_index = binding
        if missing_index is not None:
            raise MutationJournalError(
                f"workspace restore parent is absent: {relative!r}"
            )
        if parent_chain != expected_parent_chain:
            raise MutationJournalError(
                f"workspace restore parent conflicts with captured authority: "
                f"{relative!r}"
            )
        _assert_settlement_parent_binding(
            root_fd,
            relative,
            parent_fd,
            parent_chain,
            allow_terminal_vcs_metadata=allow_terminal_vcs_metadata,
        )
        try:
            os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise MutationJournalError(
                f"workspace restore path appeared before install: {relative!r}"
            )

        if not isinstance(mode, int) or isinstance(mode, bool) or not 0 <= mode <= 0o7777:
            raise MutationJournalError(
                f"workspace restore mode is invalid: {relative!r}"
            )
        if not isinstance(xattrs, Mapping) or any(
            not isinstance(key, str) or not isinstance(value, str)
            for key, value in xattrs.items()
        ):
            raise MutationJournalError(
                f"workspace restore xattrs are invalid: {relative!r}"
            )
        if kind == "symlink" and xattrs:
            raise MutationJournalError(
                "descriptor-bound symlink xattr restoration is unsupported; "
                f"journal retained for {relative!r}"
            )

        installed_identity: tuple[int, int] | None = None
        if kind == "file":
            if payload is None:
                raise MutationJournalError(
                    f"workspace restore file payload is absent: {relative!r}"
                )
            descriptor: int | None = None
            try:
                descriptor = _claim_bound_workspace_file(
                    parent_fd,
                    name,
                )
                opened = os.fstat(descriptor)
                if not stat.S_ISREG(opened.st_mode) or opened.st_nlink != 1:
                    raise MutationJournalError(
                        f"workspace restore temporary is unsafe: {relative!r}"
                    )
                _write_all_bound(descriptor, payload)
                _restore_bound_descriptor_xattrs(
                    descriptor,
                    xattrs,
                    label=relative,
                )
                os.fchmod(descriptor, mode)
                os.fsync(descriptor)
                _assert_settlement_parent_binding(
                    root_fd,
                    relative,
                    parent_fd,
                    parent_chain,
                    allow_terminal_vcs_metadata=allow_terminal_vcs_metadata,
                )
                installed_identity = (opened.st_dev, opened.st_ino)
                current = os.stat(
                    name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
                if (
                    not stat.S_ISREG(current.st_mode)
                    or current.st_nlink != 1
                    or (current.st_dev, current.st_ino) != installed_identity
                ):
                    raise MutationJournalError(
                        f"workspace restore file changed on install: {relative!r}"
                    )
                _fsync_bound_directory(parent_fd)
            finally:
                if descriptor is not None:
                    os.close(descriptor)
        elif kind == "directory":
            private_name, directory_fd, opened = (
                _create_private_bound_workspace_directory(
                    parent_fd,
                    label=f"workspace restore directory {relative!r}",
                )
            )
            try:
                _restore_bound_descriptor_xattrs(
                    directory_fd,
                    xattrs,
                    label=relative,
                )
                os.fchmod(directory_fd, mode)
                _fsync_bound_directory(directory_fd)
                _assert_settlement_parent_binding(
                    root_fd,
                    relative,
                    parent_fd,
                    parent_chain,
                    allow_terminal_vcs_metadata=allow_terminal_vcs_metadata,
                )
                _publish_private_bound_workspace_directory(
                    parent_fd,
                    private_name,
                    name,
                    directory_fd,
                    opened,
                    label=f"workspace restore directory {relative!r}",
                )
                installed_identity = (opened.st_dev, opened.st_ino)
                _fsync_bound_directory(parent_fd)
            finally:
                os.close(directory_fd)
        elif kind == "symlink":
            if not isinstance(target, str) or "\0" in target:
                raise MutationJournalError(
                    f"workspace restore symlink target is invalid: {relative!r}"
                )
            os.symlink(target, name, dir_fd=parent_fd)
            created = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            if not stat.S_ISLNK(created.st_mode) or created.st_nlink != 1:
                raise MutationJournalError(
                    f"workspace restore symlink is unsafe: {relative!r}"
                )
            installed_identity = (created.st_dev, created.st_ino)
            if os.readlink(name, dir_fd=parent_fd) != target:
                raise MutationJournalError(
                    f"workspace restore symlink changed: {relative!r}"
                )
            _fsync_bound_directory(parent_fd)
        else:
            raise MutationJournalError(
                f"unsupported workspace restore kind {kind!r}: {relative!r}"
            )

        _assert_settlement_parent_binding(
            root_fd,
            relative,
            parent_fd,
            parent_chain,
            allow_terminal_vcs_metadata=allow_terminal_vcs_metadata,
        )
        installed = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        if installed_identity is None or (
            installed.st_dev,
            installed.st_ino,
        ) != installed_identity:
            raise MutationJournalError(
                f"workspace restore entry changed after install: {relative!r}"
            )
        return installed_identity


def _materialize_git_tree_restore_entry(
    cwd: Path,
    head: str,
    relative: str,
    budget: "_MutationJournalArtifactBudget",
) -> dict[str, object] | None:
    """Authenticate one exact tracked baseline before deleting live bytes."""

    relative = _settlement_relative_path(relative)
    if re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", head) is None:
        raise MutationJournalError("mutation restore baseline commit is malformed")

    def safe_git(max_bytes: int, *arguments: str) -> bytes:
        return _run_bound_git_bounded_stdout(
            cwd,
            ["git", *_GIT_SAFE_OPTIONS, "--literal-pathspecs", *arguments],
            max_stdout_bytes=max_bytes,
            label=f"baseline Git entry {relative!r}",
            GIT_NO_LAZY_FETCH="1",
            GIT_NO_REPLACE_OBJECTS="1",
        )

    tree_ceiling = len(os.fsencode(relative)) + 256
    raw = safe_git(tree_ceiling, "ls-tree", "-z", head, "--", relative)
    exact: list[tuple[bytes, bytes, str]] = []
    for record in raw.split(b"\0"):
        if not record:
            continue
        metadata, separator, encoded_path = record.partition(b"\t")
        fields = metadata.split()
        if not separator or len(fields) != 3:
            raise MutationJournalError(
                f"malformed baseline tree entry for {relative!r}"
            )
        if os.fsdecode(encoded_path) != relative:
            continue
        encoded_mode, encoded_type, encoded_oid = fields
        exact.append(
            (
                encoded_mode,
                encoded_type,
                encoded_oid.decode("ascii", errors="strict"),
            )
        )
    if not exact:
        return None
    if len(exact) != 1:
        raise MutationJournalError(
            f"ambiguous baseline tree entry for {relative!r}"
        )
    mode, object_type, oid_text = exact[0]
    if mode == b"160000" or object_type == b"commit":
        raise MutationJournalError(
            "cannot exactly restore an initialized nested submodule from the "
            f"superproject gitlink: {relative}; journal retained"
        )
    if mode not in {b"100644", b"100755", b"120000"} or object_type != b"blob":
        raise MutationJournalError(
            f"unsupported baseline tree entry for {relative!r}"
        )
    if (
        len(oid_text) not in {40, 64}
        or any(character not in "0123456789abcdef" for character in oid_text)
    ):
        raise MutationJournalError(
            f"malformed baseline object id for {relative!r}"
        )
    encoded_size = safe_git(128, "cat-file", "-s", oid_text).strip()
    if re.fullmatch(rb"[0-9]+", encoded_size) is None:
        raise MutationJournalError(
            f"baseline Git blob size is malformed for {relative!r}"
        )
    blob_size = int(encoded_size)
    if (
        blob_size > _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_BYTES
        or blob_size
        > _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_BYTES - budget.bytes
    ):
        raise MutationJournalError(
            f"baseline Git blob exceeds restore byte ceiling: {relative!r}"
        )
    budget.charge_path()
    budget.charge_bytes(blob_size)
    payload = safe_git(blob_size, "cat-file", "blob", oid_text)
    if len(payload) != blob_size:
        raise MutationJournalError(
            f"baseline Git blob size changed for {relative!r}"
        )
    digest = (
        hashlib.sha1(usedforsecurity=False)
        if len(oid_text) == 40
        else hashlib.sha256()
    )
    digest.update(f"blob {len(payload)}\0".encode("ascii"))
    digest.update(payload)
    if digest.hexdigest() != oid_text:
        raise MutationJournalError(
            f"baseline Git blob changed for {relative!r}"
        )
    if mode == b"120000":
        if b"\0" in payload:
            raise MutationJournalError(
                f"baseline symlink contains NUL for {relative!r}"
            )
        return {
            "kind": "symlink",
            "mode": 0o777,
            "target": os.fsdecode(payload),
            "xattrs": {},
        }
    return {
        "kind": "file",
        "mode": 0o755 if mode == b"100755" else 0o644,
        "payload": payload,
        "xattrs": {},
    }


def _materialize_raw_object_restore_entry(
    cwd: Path,
    relative: str,
    binding: Mapping[str, object],
    budget: "_MutationJournalArtifactBudget",
) -> dict[str, object]:
    """Read an exact transform-free blob with strict object/size bindings."""

    oid = binding.get("oid")
    expected_sha256 = binding.get("sha256")
    recorded_size = binding.get("size")
    if (
        not isinstance(oid, str)
        or re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", oid) is None
        or not isinstance(expected_sha256, str)
        or re.fullmatch(r"[0-9a-f]{64}", expected_sha256) is None
        or not isinstance(recorded_size, int)
        or isinstance(recorded_size, bool)
        or not 0 <= recorded_size <= _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_BYTES
        or recorded_size
        > _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_BYTES - budget.bytes
    ):
        raise MutationJournalError(
            f"raw workspace restore authority is malformed: {relative!r}"
        )

    def safe_git(max_bytes: int, *arguments: str) -> bytes:
        return _run_bound_git_bounded_stdout(
            cwd,
            ["git", *_GIT_SAFE_OPTIONS, "--literal-pathspecs", *arguments],
            max_stdout_bytes=max_bytes,
            label=f"raw baseline Git blob for {relative!r}",
            GIT_NO_LAZY_FETCH="1",
            GIT_NO_REPLACE_OBJECTS="1",
        )

    encoded_size = safe_git(128, "cat-file", "-s", oid).strip()
    if (
        re.fullmatch(rb"[0-9]+", encoded_size) is None
        or int(encoded_size) != recorded_size
    ):
        raise MutationJournalError(
            f"raw baseline Git blob size changed for {relative}"
        )
    budget.charge_path()
    budget.charge_bytes(recorded_size)
    payload = safe_git(recorded_size, "cat-file", "blob", oid)
    if (
        len(payload) != recorded_size
        or hashlib.sha256(payload).hexdigest() != expected_sha256
    ):
        raise MutationJournalError(
            f"raw baseline Git blob changed for {relative}"
        )
    object_digest = (
        hashlib.sha1(usedforsecurity=False)
        if len(oid) == 40
        else hashlib.sha256()
    )
    object_digest.update(f"blob {len(payload)}\0".encode("ascii"))
    object_digest.update(payload)
    if object_digest.hexdigest() != oid:
        raise MutationJournalError(
            f"raw baseline Git object id changed for {relative}"
        )
    return {
        "kind": "file",
        "mode": binding.get("mode"),
        "xattrs": binding.get("xattrs", {}),
        "payload": payload,
    }


def _dedupe_roots(paths: Iterable[str]) -> tuple[str, ...]:
    roots: list[str] = []
    for path in sorted(set(paths), key=lambda item: (item.count("/"), item)):
        if any(path == root or path.startswith(root + "/") for root in roots):
            continue
        roots.append(path)
    return tuple(roots)


def _generation_zero_writer_epoch_family(
    manifest: Mapping[str, object],
) -> tuple[tuple[str, str | None], ...]:
    """Parse the monotonic generation-zero family projection exactly."""

    raw_ids = manifest.get("writer_epoch_family")
    raw_parents = manifest.get("writer_epoch_family_parents")
    if (
        not isinstance(raw_ids, list)
        or not raw_ids
        or not isinstance(raw_parents, dict)
        or any(not isinstance(transaction_id, str) for transaction_id in raw_ids)
        or len(raw_ids) != len(set(raw_ids))
        or any(
            not isinstance(transaction_id, str)
            or (parent is not None and not isinstance(parent, str))
            for transaction_id, parent in raw_parents.items()
        )
    ):
        raise MutationJournalError(
            "generation-zero writer epoch family projection is malformed"
        )
    ids = set(raw_ids)
    parents = {
        str(transaction_id): (
            str(parent) if parent is not None else None
        )
        for transaction_id, parent in raw_parents.items()
    }
    if set(parents) != ids:
        raise MutationJournalError(
            "generation-zero writer epoch family projection is incomplete"
        )
    roots = tuple(
        transaction_id
        for transaction_id, parent in parents.items()
        if parent is None
    )
    if len(roots) != 1:
        raise MutationJournalError(
            "generation-zero writer epoch family requires exactly one root"
        )
    depths = {roots[0]: 0}
    unresolved = ids.difference(depths)
    while unresolved:
        progressed = False
        for transaction_id in sorted(unresolved):
            parent = parents[transaction_id]
            if parent in depths:
                depths[transaction_id] = depths[cast(str, parent)] + 1
                unresolved.remove(transaction_id)
                progressed = True
                break
        if not progressed:
            raise MutationJournalError(
                "generation-zero writer epoch family is disconnected or cyclic"
            )
    return tuple(
        (transaction_id, parents[transaction_id])
        for transaction_id in sorted(
            ids,
            key=lambda item: (depths[item], item),
        )
    )


def _writer_epoch_terminal_proof_records(
    manifest: Mapping[str, object],
) -> tuple[object, ...]:
    """Return a cloned, structurally bounded proof inventory."""

    records = manifest.get("writer_epoch_terminal_proofs", {})
    if not isinstance(records, dict) or any(
        not isinstance(transaction_id, str)
        or not isinstance(record, dict)
        for transaction_id, record in records.items()
    ):
        raise MutationJournalError(
            "writer epoch terminal proof inventory is malformed"
        )
    canonical: list[dict[str, object]] = []
    embedded_ids: set[str] = set()
    for transaction_id in sorted(records):
        record = records[transaction_id]
        try:
            proof = _writer_epoch_module.parse_writer_epoch_terminal_proof(
                record
            )
        except (TypeError, ValueError) as exc:
            raise MutationJournalError(
                "writer epoch terminal proof inventory is malformed: "
                f"{exc}"
            ) from exc
        if (
            proof.transaction_id != transaction_id
            or proof.transaction_id in embedded_ids
            or proof.to_record() != record
        ):
            raise MutationJournalError(
                "writer epoch terminal proof key/embedded identity differs"
            )
        embedded_ids.add(proof.transaction_id)
        canonical.append(proof.to_record())
    return tuple(canonical)


class WorkspaceMutationJournal:
    """One durable mutation transaction for one slice/invocation."""

    def __init__(self, journal_dir: Path, manifest: dict) -> None:
        self.journal_dir = journal_dir
        self._logical_journal_dir = journal_dir
        transaction_id = str(manifest.get("transaction_id", ""))
        # The storage adapter must not learn its identity from a freshly
        # replaced manifest.  Keep the constructor-validated transaction ID
        # as immutable compare-and-write authority.
        self._transaction_id = transaction_id
        self._registry_authority_journal_dir = (
            journal_dir.parent / transaction_id
            if transaction_id
            and journal_dir.name.startswith(".crucible-cleanup-")
            else journal_dir
        )
        try:
            journal_metadata = journal_dir.lstat()
            parent_metadata = journal_dir.parent.lstat()
        except OSError:
            self._logical_journal_identity: tuple[int, int] | None = None
            self._logical_journal_parent_identity: tuple[int, int] | None = None
        else:
            self._logical_journal_identity = (
                journal_metadata.st_dev,
                journal_metadata.st_ino,
            )
            self._logical_journal_parent_identity = (
                parent_metadata.st_dev,
                parent_metadata.st_ino,
            )
        self._manifest = manifest
        self._manifest_lock = threading.RLock()
        # Admin-tree validation may inspect thousands of entries.  Its
        # full Git-discovery proof is batchable, but the capability must stay
        # bound to this exact journal object rather than becoming reusable
        # process-global authority.
        self._git_admin_authority_token = object()
        self._terminal_cleanup_epoch_proof: (
            _writer_epoch_module.WriterEpochTerminalProof | None
        ) = None
        # Durable publication happens before process-local family
        # registration.  A setup exception in that narrow window leaves this
        # exact object as the retry authority until registration is rebuilt.
        self._setup_registration_pending = False
        self._discovery_binding: _MutationJournalPathBinding | None = None
        self._restored_workspace_entry_authority: dict[
            str, tuple[int, int] | None
        ] = {}
        self._restored_tracked_metadata_observations: dict[
            str, dict[str, object]
        ] = {}
        self._selectively_restored_attribute_policy: set[str] = set()
        self._active_parent_postimage_handoffs: dict[
            object, _ActiveParentPostimageHandoff
        ] = {}
        self._consumed_active_parent_postimage_handoffs: dict[
            object, _ActiveParentPostimageHandoff
        ] = {}
        # Writer-epoch proofs deliberately reload the durable manifest before
        # every mutation frontier.  Rollback must therefore not rely on an
        # in-memory-only clearing of pre-capture attribute findings: the next
        # proof would resurrect the durable latch and make an otherwise exact
        # restore reject its own final validation.  Keep the rollback-only
        # validation state outside the reloadable manifest, while separately
        # retaining any *new* attribute drift observed during restoration.
        self._restore_validation_in_progress = False
        self._restore_new_attribute_changes: set[str] = set()
        self._restore_new_attribute_admin_changed = False
        # Baseline Git-admin directories normally retain their captured inode.
        # If a failed writer deleted one, descriptor-relative restoration may
        # recreate it exactly; remember that transient inode so every later
        # administrative phase proves the same replacement instead of
        # accepting an arbitrary matching-mode directory.
        self._restored_git_admin_directory_authority: dict[
            str, tuple[int, int]
        ] = {}

    def _validated_restored_workspace_directory_authority(
        self,
        paths: Iterable[str],
    ) -> dict[str, tuple[int, int]]:
        """Validate durable replacement inodes installed by selective restore."""

        expected_paths = set(paths)
        raw = self._manifest.get(
            _RESTORED_WORKSPACE_DIRECTORY_AUTHORITY_KEY,
            {},
        )
        if not isinstance(raw, dict):
            raise MutationJournalError(
                "restored workspace directory authority is malformed"
            )
        authority: dict[str, tuple[int, int]] = {}
        for relative, record in raw.items():
            if (
                not isinstance(relative, str)
                or relative == "."
                or relative not in expected_paths
                or not isinstance(record, dict)
                or set(record) != {"device", "inode"}
            ):
                raise MutationJournalError(
                    "restored workspace directory authority is malformed"
                )
            device = record.get("device")
            inode = record.get("inode")
            if any(
                isinstance(component, bool)
                or not isinstance(component, int)
                or component < 0
                for component in (device, inode)
            ):
                raise MutationJournalError(
                    "restored workspace directory authority is malformed"
                )
            authority[relative] = (
                cast(int, device),
                cast(int, inode),
            )
        return authority

    def _effective_workspace_directory_identities(
        self,
        paths: Iterable[str],
    ) -> dict[str, tuple[int, int]]:
        """Return capture identities plus proven selective-restore replacements."""

        expected_paths = tuple(paths)
        identities = _validated_workspace_directory_identities(
            self._manifest.get("directory_identities"),
            expected_paths,
        )
        identities.update(
            self._validated_restored_workspace_directory_authority(
                expected_paths,
            )
        )
        owners: dict[tuple[int, int], str] = {}
        for relative, identity in identities.items():
            previous = owners.setdefault(identity, relative)
            if previous != relative:
                raise MutationJournalError(
                    "restored workspace directory authority is malformed: "
                    f"{relative!r} aliases {previous!r}"
                )
        return identities

    def _record_restored_workspace_directory_authority(
        self,
        authority: Mapping[str, _BoundWorkspaceDirectoryRecord],
    ) -> bool:
        """Persist exact directory inodes privately installed during restore."""

        expected_modes = self._manifest.get("directory_modes")
        if not isinstance(expected_modes, dict):
            raise MutationJournalError(
                "workspace directory baseline is malformed"
            )
        captured = _validated_workspace_directory_identities(
            self._manifest.get("directory_identities"),
            expected_modes,
        )
        if set(authority) != set(expected_modes):
            raise MutationJournalError(
                "restored workspace directory authority is incomplete"
            )
        replacements: dict[str, dict[str, int]] = {}
        for relative, record in authority.items():
            identity = (record.device, record.inode)
            if relative == ".":
                if identity != captured[relative]:
                    raise MutationJournalError(
                        "workspace root cannot be rebound during selective restore"
                    )
                continue
            if identity != captured[relative]:
                replacements[relative] = {
                    "device": record.device,
                    "inode": record.inode,
                }
        if self._manifest.get(
            _RESTORED_WORKSPACE_DIRECTORY_AUTHORITY_KEY,
            {},
        ) == replacements:
            return False
        self._manifest[
            _RESTORED_WORKSPACE_DIRECTORY_AUTHORITY_KEY
        ] = replacements
        return True

    def _validated_restored_tracked_entry_authority(
        self,
    ) -> dict[str, tuple[int, int]]:
        """Validate durable file/symlink inodes installed by selective restore."""

        expected = self._manifest.get("tracked_path_metadata", {})
        raw = self._manifest.get(_RESTORED_TRACKED_ENTRY_AUTHORITY_KEY, {})
        if not isinstance(expected, dict) or not isinstance(raw, dict):
            raise MutationJournalError(
                "restored tracked entry authority is malformed"
            )
        replacements: dict[str, tuple[int, int]] = {}
        for relative, record in raw.items():
            baseline = expected.get(relative)
            if (
                not isinstance(relative, str)
                or _settlement_relative_path(relative) != relative
                or not isinstance(baseline, Mapping)
                or baseline.get("kind") not in {"file", "symlink"}
                or not isinstance(record, dict)
                or set(record) != {"device", "inode"}
            ):
                raise MutationJournalError(
                    "restored tracked entry authority is malformed"
                )
            device = record.get("device")
            inode = record.get("inode")
            if any(
                isinstance(component, bool)
                or not isinstance(component, int)
                or component < 0
                for component in (device, inode)
            ):
                raise MutationJournalError(
                    "restored tracked entry authority is malformed"
                )
            replacements[relative] = (
                cast(int, device),
                cast(int, inode),
            )

        for relative, baseline in expected.items():
            if not isinstance(relative, str) or not isinstance(
                baseline,
                Mapping,
            ):
                raise MutationJournalError(
                    "tracked metadata baseline is malformed"
                )
            if baseline.get("kind") not in {"file", "symlink"}:
                continue
            device = baseline.get("device")
            inode = baseline.get("inode")
            if any(
                isinstance(component, bool)
                or not isinstance(component, int)
                or component < 0
                for component in (device, inode)
            ):
                raise MutationJournalError(
                    f"tracked path lacks captured identity: {relative}"
                )
        directory_identities = set(
            self._effective_workspace_directory_identities(
                self._manifest.get("directory_modes", {})
            ).values()
        )
        owners: dict[tuple[int, int], str] = {}
        # Only replacement identities are asserted to be live by this durable
        # overlay.  A restored directory may legitimately reuse an inode from
        # a deleted capture-time file before that file is recreated, so stale
        # baseline identities must not participate in this alias check.
        for relative, identity in replacements.items():
            if identity in directory_identities:
                raise MutationJournalError(
                    "restored tracked entry authority is malformed: "
                    f"{relative!r} aliases a directory"
                )
            previous = owners.setdefault(identity, relative)
            if previous != relative:
                raise MutationJournalError(
                    "restored tracked entry authority is malformed: "
                    f"{relative!r} aliases {previous!r}"
                )
        return replacements

    def _record_restored_tracked_entry_authority(
        self,
        authority: Mapping[str, tuple[int, int] | None],
    ) -> bool:
        """Persist exact tracked-entry replacements proved after restoration."""

        expected = self._manifest.get("tracked_path_metadata", {})
        if not isinstance(expected, dict):
            raise MutationJournalError("tracked metadata baseline is malformed")
        replacements: dict[str, dict[str, int]] = {}
        for relative, baseline in expected.items():
            if not isinstance(relative, str) or not isinstance(
                baseline,
                Mapping,
            ):
                raise MutationJournalError(
                    "tracked metadata baseline is malformed"
                )
            kind = baseline.get("kind")
            if kind not in {"file", "symlink"}:
                continue
            observed = authority.get(relative)
            device = baseline.get("device")
            inode = baseline.get("inode")
            if (
                observed is None
                or any(
                    isinstance(component, bool)
                    or not isinstance(component, int)
                    or component < 0
                    for component in (device, inode)
                )
            ):
                raise MutationJournalError(
                    f"tracked path lacks restored authority: {relative}"
                )
            if observed != (device, inode):
                replacements[relative] = {
                    "device": observed[0],
                    "inode": observed[1],
                }
        previous = self._manifest.get(
            _RESTORED_TRACKED_ENTRY_AUTHORITY_KEY,
            {},
        )
        if previous == replacements:
            return False
        self._manifest[_RESTORED_TRACKED_ENTRY_AUTHORITY_KEY] = replacements
        try:
            # Validate cross-entry and directory uniqueness before publication.
            self._validated_restored_tracked_entry_authority()
        except BaseException:
            self._manifest[_RESTORED_TRACKED_ENTRY_AUTHORITY_KEY] = previous
            raise
        return True

    def _bound_workspace_cwd(self) -> Path:
        """Address the held checkout inode, never a replaceable pathname."""

        rendered = Path(self._manifest["cwd"])
        authority = _active_workspace_mutation_authority(rendered)
        if authority is None:
            return rendered
        metadata = os.fstat(authority.root_descriptor)
        expected = self._manifest.get("authority_lock") or {}
        if (
            expected.get("root_device") is not None
            and metadata.st_dev != int(expected["root_device"])
        ) or (
            expected.get("root_inode") is not None
            and metadata.st_ino != int(expected["root_inode"])
        ):
            raise MutationJournalError(
                "held workspace root does not match journal authority"
            )
        return Path(_authority_descriptor_cwd(authority.root_descriptor))

    def _metadata_relative_roots(self, cwd: Path) -> tuple[str, ...]:
        """Return workflow-owned paths independently of root path spelling."""

        recorded = self._manifest.get("metadata_relatives")
        if recorded is not None:
            return tuple(str(path) for path in recorded)
        # Legacy manifests predate the normalized relative projection. Rebind
        # their absolute spellings through the held root descriptor before
        # comparing them with descriptor-addressed ``cwd``.
        relatives: list[str] = []
        for rendered in self._manifest.get("metadata_roots", ()):
            try:
                relatives.append(
                    self._bound_manifest_path(rendered)
                    .relative_to(cwd)
                    .as_posix()
                )
            except ValueError:
                continue
        return tuple(relatives)

    def _bound_manifest_path(self, rendered: str | Path) -> Path:
        """Rebase a captured path onto its deepest held authority root.

        Linked worktrees make the per-worktree Git directory a descendant of
        the common Git directory.  First-match selection is therefore an
        authority bug: a path owned by the narrower per-worktree descriptor
        can accidentally be addressed through the broader common root.  Pick
        the longest lexical root, and reject an equal-depth mapping unless all
        candidates name the same captured root and held inode.
        """

        path = Path(rendered)
        authority = _active_workspace_mutation_authority(
            Path(self._manifest["cwd"])
        )
        if authority is None:
            return path
        bindings = (
            (
                Path(str(self._manifest.get(
                    "git_admin_dir",
                    authority.git_dir,
                ))),
                Path(_authority_descriptor_cwd(
                    authority.git_dir_descriptor
                )),
                authority.git_dir_descriptor,
            ),
            (
                Path(str(self._manifest.get(
                    "git_common_dir",
                    authority.git_common_dir,
                ))),
                Path(_authority_descriptor_cwd(
                    authority.git_common_descriptor
                )),
                authority.git_common_descriptor,
            ),
            (
                Path(str((self._manifest.get("authority_lock") or {}).get(
                    "common_dir",
                    authority.common_dir,
                ))),
                Path(_authority_descriptor_cwd(authority.common_descriptor)),
                authority.common_descriptor,
            ),
            (
                Path(self._manifest["cwd"]),
                Path(_authority_descriptor_cwd(authority.root_descriptor)),
                authority.root_descriptor,
            ),
        )
        candidates: list[tuple[int, Path, Path, int, Path]] = []
        for captured_root, held_root, descriptor in bindings:
            try:
                relative = path.relative_to(captured_root)
            except ValueError:
                continue
            if any(part == ".." for part in relative.parts):
                raise MutationJournalError(
                    "captured journal path escapes its bound authority root"
                )
            candidates.append((
                len(captured_root.parts),
                captured_root,
                held_root,
                descriptor,
                relative,
            ))
        if not candidates:
            return path
        depth = max(candidate[0] for candidate in candidates)
        deepest = [candidate for candidate in candidates if candidate[0] == depth]
        captured_roots = {candidate[1] for candidate in deepest}
        held_identities = {
            (
                os.fstat(candidate[3]).st_dev,
                os.fstat(candidate[3]).st_ino,
            )
            for candidate in deepest
        }
        if len(captured_roots) != 1 or len(held_identities) != 1:
            raise MutationJournalError(
                "captured journal path has ambiguous held-root authority: "
                f"{path}"
            )
        _depth, _captured, held_root, _descriptor, relative = deepest[0]
        return held_root / relative

    def _read_snapshot_blob_record(
        self,
        record: object,
        *,
        label: str,
        budget: "_MutationJournalArtifactBudget | None" = None,
    ) -> bytes:
        """Read a manifest-bound payload; descriptive snapshots never win."""

        if not isinstance(record, Mapping):
            raise MutationJournalError(
                f"Git-admin snapshot binding is malformed: {label}"
            )
        return _read_bound_snapshot_blob(
            self,
            record.get("sha256"),
            record.get("size"),
            budget or _MutationJournalArtifactBudget(),
            label=label,
        )

    def _git_admin_directory_records(self) -> dict[str, dict[str, object]]:
        """Return capture-time inode authority for every admin directory.

        The map intentionally includes exact/guarded trees and the roots of
        opaque stores, but never treats opaque payload contents as restorable.
        Conflicting projections are a malformed manifest, not a reason to
        choose whichever record was visited first.
        """

        records: dict[str, dict[str, object]] = {}

        def add(path: Path, record: Mapping[str, object]) -> None:
            device = record.get("device")
            inode = record.get("inode")
            if any(
                isinstance(value, bool)
                or not isinstance(value, int)
                or value < 0
                for value in (device, inode)
            ):
                return
            key = os.fspath(_lexical_workspace_path(path))
            normalized = dict(record)
            previous = records.get(key)
            if previous is not None and (
                previous.get("device"), previous.get("inode")
            ) != (device, inode):
                raise MutationJournalError(
                    f"Git-admin directory authority is ambiguous: {key}"
                )
            records[key] = normalized

        for root_record in self._manifest.get("git_admin_topology", ()):
            root = Path(str(root_record["root"]))
            add(root, root_record)
            for name, entry in root_record.get("entries", {}).items():
                if entry.get("kind") not in {
                    "owned_directory", "guarded_directory"
                }:
                    continue
                entry_root = root / str(name)
                add(entry_root, entry)
                if entry.get("kind") == "guarded_directory":
                    for relative, child in entry.get("entries", {}).items():
                        if child.get("kind") == "directory":
                            add(entry_root / str(relative), child)

        refs_path = self._manifest.get("refs_path")
        if refs_path is not None:
            refs_root_record = {
                "device": self._manifest.get("refs_root_device"),
                "inode": self._manifest.get("refs_root_inode"),
                "mode": self._manifest.get("refs_root_mode"),
                "xattrs": self._manifest.get("refs_root_xattrs", {}),
            }
            refs_root = Path(str(refs_path))
            add(refs_root, refs_root_record)
            for relative, entry in (
                self._manifest.get("refs_tree") or {}
            ).items():
                if entry.get("kind") == "directory":
                    add(refs_root / str(relative), entry)

        log_refs_path = self._manifest.get("log_refs_path")
        if log_refs_path is not None and self._manifest.get("log_refs_exists"):
            log_root_record = {
                "device": self._manifest.get("log_refs_root_device"),
                "inode": self._manifest.get("log_refs_root_inode"),
                "mode": self._manifest.get("log_refs_root_mode"),
                "xattrs": self._manifest.get("log_refs_root_xattrs", {}),
            }
            log_root = Path(str(log_refs_path))
            add(log_root, log_root_record)
            for relative, entry in (
                self._manifest.get("log_refs_tree") or {}
            ).items():
                if entry.get("kind") == "directory":
                    add(log_root / str(relative), entry)

        for root_record in self._manifest.get("auxiliary_git_trees", ()):
            if not root_record.get("exists"):
                continue
            root = Path(str(root_record["path"]))
            add(root, root_record)
            for relative, entry in root_record.get("entries", {}).items():
                if entry.get("kind") == "directory":
                    add(root / str(relative), entry)

        for root_record in self._manifest.get(
            "absent_worktree_admin_controls", ()
        ):
            root = Path(str(root_record["root"]))
            add(root, root_record)
            for relative, entry in root_record.get("entries", {}).items():
                if entry.get("kind") == "directory":
                    add(root / str(relative), entry)

        cached_metadata = self._manifest.get("cached_module_metadata", {})
        for root_record in self._manifest.get("cached_module_controls", ()):
            root = Path(str(root_record["root"]))
            root_baseline = cached_metadata.get(
                str(root_record.get("relative_root")), {}
            )
            add(root, root_baseline)
            for relative, entry in root_record.get("entries", {}).items():
                if entry.get("kind") == "directory":
                    add(root / str(relative), entry)
            for name, entry in root_record.get("payload_roots", {}).items():
                add(root / str(name), entry)

        objects_path = self._manifest.get("objects_path")
        if objects_path:
            objects_root = Path(str(objects_path))
            add(objects_root, {
                "device": self._manifest.get("objects_root_device"),
                "inode": self._manifest.get("objects_root_inode"),
                "mode": self._manifest.get("objects_root_mode"),
                "xattrs": self._manifest.get("objects_root_xattrs", {}),
            })
            for relative, entry in (
                self._manifest.get("object_inventory") or {}
            ).items():
                if entry.get("kind") == "directory":
                    add(objects_root / str(relative), entry)

        common = Path(str(self._manifest.get(
            "git_common_dir",
            Path(str(self._manifest.get("objects_path", ""))).parent,
        )))
        for field, name in (
            ("module_namespace_topology", "modules"),
            ("worktree_namespace_topology", "worktrees"),
        ):
            topology = self._manifest.get(field)
            if not isinstance(topology, Mapping):
                continue
            root = common / name
            for relative, entry in topology.items():
                if entry.get("kind") not in {"directory", "repository"}:
                    continue
                add(root if relative == "." else root / str(relative), entry)
        return records

    def _git_admin_workspace_authorities(
        self,
    ) -> tuple[_WorkspaceMutationAuthority, ...]:
        """Return held authorities that may bind this journal's admin paths."""

        recorded_cwd = Path(self._manifest["cwd"])
        exact = _active_workspace_mutation_authority(recorded_cwd)
        captured_common = _lexical_workspace_path(Path(str(
            self._manifest.get("git_common_dir", "")
        )))
        candidates: list[_WorkspaceMutationAuthority] = []
        if exact is not None:
            candidates.append(exact)
        for authority in _thread_workspace_authorities():
            if (
                authority is exact
                or _lexical_workspace_path(authority.git_common_dir)
                != captured_common
            ):
                continue
            candidates.append(authority)
        return tuple({id(candidate): candidate for candidate in candidates}.values())

    @contextmanager
    def _git_admin_authority_batch(
        self,
    ) -> Iterator[_GitAdminAuthorityBatch]:
        """Authenticate Git discovery once around one complete admin tree.

        Descriptor-relative entry inspection still reproves the selected
        directory, lock, process, thread, and journal token for every entry.
        Full Git discovery is repeated at the successful end of the batch so
        a clean result cannot survive a concurrent ``.git``/``commondir``
        retarget.  This changes subprocess growth from O(entries) to
        O(distinct held authorities per tree).
        """

        authenticated: list[
            tuple[_WorkspaceMutationAuthority, _ExternalWorkspaceCoordination]
        ] = []
        for authority in self._git_admin_workspace_authorities():
            proved = _assert_workspace_mutation_authority(authority.root)
            if proved is not authority:
                raise MutationJournalError(
                    "Git-admin batch resolved different workspace authority"
                )
            external = _active_external_workspace_coordination(authority.root)
            if external is None:
                raise MutationJournalError(
                    "Git-admin batch lost external workspace coordination"
                )
            authenticated.append((authority, external))
        batch = _GitAdminAuthorityBatch(
            journal_token=self._git_admin_authority_token,
            transaction_id=self._transaction_id,
            owner_pid=os.getpid(),
            owner_thread_id=threading.get_ident(),
            authorities=tuple(authenticated),
        )
        stack = getattr(_LOCK_STATE, "git_admin_authority_batches", None)
        if stack is None:
            stack = []
            _LOCK_STATE.git_admin_authority_batches = stack
        stack.append(batch)
        try:
            yield batch
            for authority, _external in batch.authorities:
                proved = _assert_workspace_mutation_authority(authority.root)
                if proved is not authority:
                    raise MutationJournalError(
                        "Git-admin batch ended under different workspace authority"
                    )
        finally:
            if not stack or stack[-1] is not batch:
                raise MutationJournalError(
                    "Git-admin authority batch stack changed during proof"
                )
            stack.pop()
            if not stack:
                del _LOCK_STATE.git_admin_authority_batches

    def _assert_git_admin_authority_batch(
        self,
        batch: _GitAdminAuthorityBatch,
        authority: _WorkspaceMutationAuthority | None = None,
    ) -> None:
        """Reprove one per-entry use of a short-lived admin-tree capability."""

        stack = getattr(_LOCK_STATE, "git_admin_authority_batches", ())
        if (
            batch.journal_token is not self._git_admin_authority_token
            or batch.transaction_id != self._transaction_id
            or batch.owner_pid != os.getpid()
            or batch.owner_thread_id != threading.get_ident()
            or not stack
            or stack[-1] is not batch
        ):
            raise MutationJournalError(
                "Git-admin authority batch is stale or belongs to another "
                "journal, process, or thread"
            )
        if authority is None:
            return
        for candidate, sealed_external in batch.authorities:
            if candidate is not authority:
                continue
            if (
                _active_external_workspace_coordination(authority.root)
                is not sealed_external
            ):
                raise MutationJournalError(
                    "Git-admin authority batch changed external coordination"
                )
            _assert_reentrant_workspace_mutation_authority(
                authority,
                cast(_ExternalWorkspaceCoordination, sealed_external),
            )
            return
        raise MutationJournalError(
            "Git-admin entry selected authority outside its authenticated batch"
        )

    @contextmanager
    def _bound_git_admin_path(
        self,
        rendered: str | Path,
        *,
        authority_batch: _GitAdminAuthorityBatch | None = None,
    ) -> Iterator[tuple[int, str, Path]]:
        """Yield a held authority root and lexical suffix for one admin path."""

        path = _lexical_workspace_path(Path(rendered))
        recorded_cwd = Path(self._manifest["cwd"])
        exact = _active_workspace_mutation_authority(recorded_cwd)
        if authority_batch is not None:
            self._assert_git_admin_authority_batch(authority_batch)
        captured_records: dict[Path, Mapping[str, object]] = {}
        for root_record in self._manifest.get("git_admin_topology", ()):
            if isinstance(root_record, Mapping) and root_record.get("root"):
                captured_records[_lexical_workspace_path(Path(str(
                    root_record["root"]
                )))] = root_record
        authority_record = self._manifest.get("authority_lock") or {}
        captured_root = _lexical_workspace_path(recorded_cwd)
        captured_records.setdefault(captured_root, {
            "device": authority_record.get("root_device"),
            "inode": authority_record.get("root_inode"),
        })
        rendered_lock_root = authority_record.get("common_dir")
        if rendered_lock_root is not None:
            captured_records.setdefault(
                _lexical_workspace_path(Path(str(rendered_lock_root))),
                {
                    "device": authority_record.get("common_device"),
                    "inode": authority_record.get("common_inode"),
                },
            )

        held = {
            id(candidate): candidate
            for candidate in self._git_admin_workspace_authorities()
        }
        bindings: list[
            tuple[Path, int, _WorkspaceMutationAuthority | None]
        ] = []
        owned_descriptors: list[int] = []

        def append_captured_binding(
            root: Path,
            descriptor: int,
            authority: _WorkspaceMutationAuthority | None,
        ) -> None:
            """Admit a descriptor only when its sealed root inode matches."""

            normalized = _lexical_workspace_path(root)
            record = captured_records.get(normalized)
            if record is None:
                return
            device = record.get("device")
            inode = record.get("inode")
            if (
                isinstance(device, bool)
                or not isinstance(device, int)
                or isinstance(inode, bool)
                or not isinstance(inode, int)
            ):
                return
            opened = os.fstat(descriptor)
            if (opened.st_dev, opened.st_ino) != (device, inode):
                return
            bindings.append((normalized, descriptor, authority))

        if exact is not None:
            append_captured_binding(
                Path(str(self._manifest.get("git_admin_dir", exact.git_dir))),
                exact.git_dir_descriptor,
                exact,
            )
            append_captured_binding(
                Path(str(self._manifest.get(
                    "git_common_dir", exact.git_common_dir
                ))),
                exact.git_common_descriptor,
                exact,
            )
            append_captured_binding(
                Path(str((self._manifest.get("authority_lock") or {}).get(
                    "common_dir", exact.common_dir
                ))),
                exact.common_descriptor,
                exact,
            )
            append_captured_binding(
                recorded_cwd,
                exact.root_descriptor,
                exact,
            )

        # Writer lanes share one Git common directory with the parent checkout
        # while retaining distinct worktree roots and per-worktree Git dirs.
        # Their cleanup therefore runs under the parent's already-held
        # repository authority.  Reuse only that exact common-dir inode; the
        # lane Git dir is then reached as a descriptor-relative descendant.
        captured_common = _lexical_workspace_path(Path(str(
            self._manifest.get("git_common_dir", "")
        )))
        for held_authority in held.values():
            if exact is held_authority:
                continue
            if _lexical_workspace_path(held_authority.git_common_dir) != (
                captured_common
            ):
                continue
            append_captured_binding(
                captured_common,
                held_authority.git_common_descriptor,
                held_authority,
            )

        # Direct journal callers and restart recovery may not already own a
        # thread-local workspace lock grant.  Bind the capture-time inodes
        # themselves in that case.  A renamed/symlinked replacement cannot
        # acquire authority merely by occupying the old pathname: the opened
        # directory must match the device/inode sealed in the manifest.
        already_bound = {
            root for root, _descriptor, _authority in bindings
        }
        for root, record in captured_records.items():
            if root in already_bound:
                continue
            device = record.get("device")
            inode = record.get("inode")
            if (
                isinstance(device, bool)
                or not isinstance(device, int)
                or isinstance(inode, bool)
                or not isinstance(inode, int)
            ):
                continue
            try:
                descriptor, opened = _open_authority_directory(
                    root,
                    label=f"captured Git-admin authority {root}",
                )
            except MutationJournalError:
                continue
            if (opened.st_dev, opened.st_ino) != (device, inode):
                os.close(descriptor)
                continue
            owned_descriptors.append(descriptor)
            bindings.append((root, descriptor, None))

        candidates: list[
            tuple[int, Path, int, Path, _WorkspaceMutationAuthority | None]
        ] = []
        for root, descriptor, binding_authority in bindings:
            root = _lexical_workspace_path(root)
            aliases = (root, Path(_authority_descriptor_cwd(descriptor)))
            for alias in aliases:
                try:
                    relative = path.relative_to(alias)
                except ValueError:
                    continue
                if any(part == ".." for part in relative.parts):
                    raise MutationJournalError(
                        f"Git-admin path escapes held authority: {path}"
                    )
                # The procfs spelling is accepted only when it names this
                # exact already-authenticated held descriptor.  An arbitrary
                # `/proc/self/fd/N` from a manifest cannot enter `aliases`.
                candidates.append((
                    len(alias.parts),
                    root,
                    descriptor,
                    relative,
                    binding_authority,
                ))
        if not candidates:
            for descriptor in owned_descriptors:
                os.close(descriptor)
            raise MutationJournalError(
                f"Git-admin path is outside held authority: {path}"
            )
        depth = max(candidate[0] for candidate in candidates)
        deepest = [candidate for candidate in candidates if candidate[0] == depth]
        if len({candidate[1] for candidate in deepest}) != 1 or len({
            (os.fstat(candidate[2]).st_dev, os.fstat(candidate[2]).st_ino)
            for candidate in deepest
        }) != 1:
            for owned in owned_descriptors:
                os.close(owned)
            raise MutationJournalError(
                f"Git-admin path has ambiguous held authority: {path}"
            )
        (
            _depth,
            logical_root,
            descriptor,
            relative,
            selected_authority,
        ) = deepest[0]
        if selected_authority is not None:
            if authority_batch is None:
                _assert_workspace_mutation_authority(selected_authority.root)
            else:
                self._assert_git_admin_authority_batch(
                    authority_batch,
                    selected_authority,
                )
        if relative == Path("."):
            relative_text = "."
        else:
            relative_text = relative.as_posix()
            # This namespace is Git administration authority, so a lexical
            # ``.git`` component is expected.  Workspace settlement paths
            # forbid VCS components and cannot be reused here; containment
            # under the held root plus the explicit ``..`` rejection above
            # is the relevant confinement rule.
            if relative.is_absolute() or relative_text in {"", ".", ".."}:
                raise MutationJournalError(
                    f"Git-admin path is noncanonical: {path}"
                )
        duplicate = os.dup(descriptor)
        try:
            yield duplicate, relative_text, logical_root
        finally:
            os.close(duplicate)
            for owned in owned_descriptors:
                os.close(owned)

    def _has_held_git_admin_authority(self) -> bool:
        """Return whether this thread can bind this journal's admin root."""

        recorded_cwd = Path(self._manifest["cwd"])
        if _active_workspace_mutation_authority(recorded_cwd) is not None:
            return True
        rendered_common = self._manifest.get("git_common_dir")
        if rendered_common is None:
            return False
        captured_common = _lexical_workspace_path(Path(str(rendered_common)))
        expected_identity: tuple[int, int] | None = None
        for root_record in self._manifest.get("git_admin_topology", ()):
            if not isinstance(root_record, Mapping):
                continue
            rendered_root = root_record.get("root")
            if rendered_root is None or _lexical_workspace_path(Path(str(
                rendered_root
            ))) != captured_common:
                continue
            device = root_record.get("device")
            inode = root_record.get("inode")
            if (
                isinstance(device, bool)
                or not isinstance(device, int)
                or isinstance(inode, bool)
                or not isinstance(inode, int)
            ):
                return False
            expected_identity = (device, inode)
            break
        if expected_identity is None:
            authority_record = self._manifest.get("authority_lock") or {}
            if _lexical_workspace_path(Path(str(
                authority_record.get("common_dir", captured_common)
            ))) == captured_common:
                device = authority_record.get("common_device")
                inode = authority_record.get("common_inode")
                if (
                    not isinstance(device, bool)
                    and isinstance(device, int)
                    and not isinstance(inode, bool)
                    and isinstance(inode, int)
                ):
                    expected_identity = (device, inode)
        if expected_identity is None:
            return False
        return any(
            _lexical_workspace_path(candidate.git_common_dir)
            == captured_common
            and (
                os.fstat(candidate.git_common_descriptor).st_dev,
                os.fstat(candidate.git_common_descriptor).st_ino,
            ) == expected_identity
            for candidate in _thread_workspace_authorities()
        )

    def _ensure_git_admin_parent_chain(
        self,
        root_fd: int,
        logical_root: Path,
        relative: str,
    ) -> tuple[tuple[int, int], ...]:
        """Materialize missing baseline parents and reject substitutions."""

        components = PurePosixPath(_settlement_relative_path(relative)).parts
        directory_records = self._git_admin_directory_records()
        for length in range(1, len(components)):
            prefix = PurePosixPath(*components[:length]).as_posix()
            logical = _lexical_workspace_path(logical_root / prefix)
            key = os.fspath(logical)
            expected = directory_records.get(key)
            if expected is None:
                raise MutationJournalError(
                    f"Git-admin parent lacks captured authority: {logical}"
                )
            with _open_settlement_parent_if_present(root_fd, prefix) as binding:
                parent_fd, name, parent_chain, missing_index = binding
                if missing_index is not None:
                    raise MutationJournalError(
                        f"Git-admin ancestor disappeared: {logical}"
                    )
                try:
                    before = os.stat(
                        name,
                        dir_fd=parent_fd,
                        follow_symlinks=False,
                    )
                except FileNotFoundError:
                    mode = expected.get("mode")
                    if not isinstance(mode, int) or isinstance(mode, bool):
                        raise MutationJournalError(
                            f"Git-admin directory mode is malformed: {logical}"
                        ) from None
                    identity = _install_bound_workspace_entry(
                        root_fd,
                        prefix,
                        expected_parent_chain=parent_chain,
                        kind="directory",
                        mode=mode,
                        xattrs=_validated_restore_xattrs(
                            expected.get("xattrs", {}),
                            label=os.fspath(logical),
                        ),
                    )
                    self._restored_git_admin_directory_authority[key] = identity
                    continue
                if not stat.S_ISDIR(before.st_mode) or stat.S_ISLNK(before.st_mode):
                    raise MutationJournalError(
                        f"Git-admin parent is aliased: {logical}"
                    )
                expected_identity = self._restored_git_admin_directory_authority.get(
                    key,
                    (cast(int, expected["device"]), cast(int, expected["inode"])),
                )
                if (before.st_dev, before.st_ino) != expected_identity:
                    raise MutationJournalError(
                        f"Git-admin parent changed identity: {logical}"
                    )
                directory_fd, opened = _open_authority_directory_at(
                    parent_fd,
                    name,
                    label=f"Git-admin parent {logical}",
                )
                try:
                    if (opened.st_dev, opened.st_ino) != expected_identity:
                        raise MutationJournalError(
                            f"Git-admin parent changed while opening: {logical}"
                        )
                finally:
                    os.close(directory_fd)
                _assert_settlement_parent_binding(
                    root_fd,
                    prefix,
                    parent_fd,
                    parent_chain,
                )
        with _open_settlement_parent_if_present(root_fd, relative) as binding:
            _parent_fd, _name, parent_chain, missing_index = binding
            if missing_index is not None:
                raise MutationJournalError(
                    f"Git-admin target parent is absent: {relative}"
                )
            return parent_chain

    def _restore_bound_git_admin_file(
        self,
        rendered: str | Path,
        *,
        exists: bool,
        record: Mapping[str, object],
        payload: bytes | None,
        label: str,
        expected_current: tuple[
            bytes,
            tuple[int, ...],
            Mapping[str, str],
        ] | None = None,
    ) -> bool:
        """Restore one admin file through held parents with no replacement.

        ``expected_current`` optionally binds a previously authenticated file
        through the destructive transition.  It is used by index-cache
        normalization so a replacement between semantic proof and restoration
        is rejected instead of being mistaken for the proved bookkeeping file.
        """

        if exists:
            mode = record.get("mode")
            if not isinstance(mode, int) or isinstance(mode, bool) or not (
                0 <= mode <= 0o7777
            ):
                raise MutationJournalError(
                    f"Git-admin file mode is malformed: {label}"
                )
            if payload is None:
                raise MutationJournalError(
                    f"Git-admin file payload is absent: {label}"
                )
            xattrs = _validated_restore_xattrs(
                record.get("xattrs", {}),
                label=label,
            )
        else:
            mode = 0
            xattrs = {}
            if payload is not None:
                raise MutationJournalError(
                    f"absent Git-admin file has a payload: {label}"
                )

        changed = False
        with self._bound_git_admin_path(rendered) as (
            root_fd,
            relative,
            logical_root,
        ):
            if relative == ".":
                raise MutationJournalError(
                    f"Git-admin file aliases an authority root: {label}"
                )
            if not exists:
                with _open_settlement_parent_if_present(
                    root_fd,
                    relative,
                ) as absence:
                    (
                        _absence_parent_fd,
                        _absence_name,
                        absence_chain,
                        absence_missing_index,
                    ) = absence
                    if absence_missing_index is not None:
                        # An absent baseline control whose parent also never
                        # existed needs no reconstruction. Reprove the exact
                        # missing-parent frontier so a racing appearance does
                        # not get mistaken for stable absence.
                        with _open_settlement_parent_if_present(
                            root_fd,
                            relative,
                        ) as retry:
                            (
                                _retry_parent_fd,
                                _retry_name,
                                retry_chain,
                                retry_missing_index,
                            ) = retry
                            if (
                                retry_chain != absence_chain
                                or retry_missing_index
                                != absence_missing_index
                            ):
                                raise MutationJournalError(
                                    f"Git-admin absence changed: {label}"
                                )
                        return False
            parent_chain = self._ensure_git_admin_parent_chain(
                root_fd,
                logical_root,
                relative,
            )
            with _open_settlement_parent_if_present(
                root_fd,
                relative,
                allow_terminal_vcs_metadata=True,
            ) as binding:
                parent_fd, name, observed_chain, missing_index = binding
                if missing_index is not None or observed_chain != parent_chain:
                    raise MutationJournalError(
                        f"Git-admin file parent changed: {label}"
                    )
                _assert_settlement_parent_binding(
                    root_fd,
                    relative,
                    parent_fd,
                    parent_chain,
                )
                try:
                    metadata = os.stat(
                        name,
                        dir_fd=parent_fd,
                        follow_symlinks=False,
                    )
                except FileNotFoundError:
                    metadata = None

                if expected_current is not None:
                    expected_payload, expected_metadata, expected_xattrs = (
                        expected_current
                    )
                    if (
                        metadata is None
                        or _git_admin_file_metadata(metadata)
                        != expected_metadata
                    ):
                        raise MutationJournalError(
                            f"Git-admin file changed before normalization: {label}"
                        )
                    observed_payload, opened = _read_bound_regular_entry(
                        parent_fd,
                        name,
                        label=f"{label} pre-normalization binding",
                        max_bytes=len(expected_payload),
                    )
                    observed_xattrs = _xattr_inventory(
                        Path(_authority_descriptor_cwd(parent_fd)) / name
                    )
                    rebound = os.stat(
                        name,
                        dir_fd=parent_fd,
                        follow_symlinks=False,
                    )
                    if (
                        observed_payload != expected_payload
                        or observed_xattrs != dict(expected_xattrs)
                        or _git_admin_file_metadata(opened)
                        != expected_metadata
                        or _git_admin_file_metadata(rebound)
                        != expected_metadata
                    ):
                        raise MutationJournalError(
                            f"Git-admin file changed before normalization: {label}"
                        )

                if not exists:
                    if metadata is None:
                        return False
                    if stat.S_ISDIR(metadata.st_mode) and not stat.S_ISLNK(
                        metadata.st_mode
                    ):
                        raise MutationJournalError(
                            "refusing to recursively remove an unauthenticated "
                            f"Git-admin directory replacement: {label}"
                        )
                    _remove_bound_workspace_entry(
                        root_fd,
                        relative,
                        parent_fd,
                        name,
                        parent_chain,
                    )
                    return True

                matches = False
                if (
                    metadata is not None
                    and stat.S_ISREG(metadata.st_mode)
                    and not stat.S_ISLNK(metadata.st_mode)
                    and metadata.st_nlink == 1
                    and metadata.st_size == len(cast(bytes, payload))
                    and stat.S_IMODE(metadata.st_mode) == mode
                ):
                    current_payload, opened = _read_bound_regular_entry(
                        parent_fd,
                        name,
                        label=label,
                        max_bytes=len(cast(bytes, payload)),
                    )
                    current_xattrs = _xattr_inventory(
                        Path(_authority_descriptor_cwd(parent_fd)) / name
                    )
                    current = os.stat(
                        name,
                        dir_fd=parent_fd,
                        follow_symlinks=False,
                    )
                    matches = (
                        current_payload == payload
                        and current_xattrs == xattrs
                        and (current.st_dev, current.st_ino)
                        == (opened.st_dev, opened.st_ino)
                    )
                if matches:
                    _assert_settlement_parent_binding(
                        root_fd,
                        relative,
                        parent_fd,
                        parent_chain,
                        allow_terminal_vcs_metadata=True,
                    )
                    return False
                if metadata is not None:
                    if stat.S_ISDIR(metadata.st_mode) and not stat.S_ISLNK(
                        metadata.st_mode
                    ):
                        raise MutationJournalError(
                            "refusing to recursively replace an unauthenticated "
                            f"Git-admin directory: {label}"
                        )
                    _remove_bound_workspace_entry(
                        root_fd,
                        relative,
                        parent_fd,
                        name,
                        parent_chain,
                        expected_top_metadata=(
                            expected_current[1]
                            if expected_current is not None
                            else None
                        ),
                    )
                changed = True

            # Reopen after removal.  Publication uses O_EXCL/no-replace and
            # proves the same parent chain immediately before the claim.
            installed = _install_bound_workspace_entry(
                root_fd,
                relative,
                expected_parent_chain=parent_chain,
                kind="file",
                mode=mode,
                xattrs=xattrs,
                payload=payload,
            )
            with _open_settlement_parent_if_present(
                root_fd,
                relative,
                allow_terminal_vcs_metadata=True,
            ) as binding:
                parent_fd, name, final_chain, missing_index = binding
                if missing_index is not None or final_chain != parent_chain:
                    raise MutationJournalError(
                        f"Git-admin file parent changed after install: {label}"
                    )
                current = os.stat(
                    name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
                if (current.st_dev, current.st_ino) != installed:
                    raise MutationJournalError(
                        f"Git-admin file changed after install: {label}"
                    )
                _assert_settlement_parent_binding(
                    root_fd,
                    relative,
                    parent_fd,
                    parent_chain,
                )
        return changed

    @contextmanager
    def _open_bound_git_admin_directory(
        self,
        rendered: str | Path,
        *,
        record: Mapping[str, object],
        label: str,
        authority_batch: _GitAdminAuthorityBatch | None = None,
    ) -> Iterator[int]:
        """Open one captured admin directory through its held parent chain."""

        device = record.get("device")
        inode = record.get("inode")
        if (
            isinstance(device, bool)
            or not isinstance(device, int)
            or isinstance(inode, bool)
            or not isinstance(inode, int)
        ):
            raise MutationJournalError(
                f"Git-admin directory lacks inode authority: {label}"
            )
        logical = _lexical_workspace_path(Path(rendered))
        expected = self._restored_git_admin_directory_authority.get(
            os.fspath(logical),
            (device, inode),
        )
        with self._bound_git_admin_path(
            logical,
            authority_batch=authority_batch,
        ) as (
            authority_fd,
            relative,
            _logical_root,
        ):
            if relative == ".":
                descriptor = os.dup(authority_fd)
                opened = os.fstat(descriptor)
                if (
                    not stat.S_ISDIR(opened.st_mode)
                    or (opened.st_dev, opened.st_ino) != expected
                ):
                    os.close(descriptor)
                    raise MutationJournalError(
                        f"Git-admin directory changed identity: {label}"
                    )
                try:
                    yield descriptor
                finally:
                    os.close(descriptor)
                return
            with _open_settlement_parent_if_present(
                authority_fd,
                relative,
            ) as binding:
                parent_fd, name, parent_chain, missing_index = binding
                if missing_index is not None:
                    raise MutationJournalError(
                        f"Git-admin directory disappeared: {label}"
                    )
                descriptor, opened = _open_authority_directory_at(
                    parent_fd,
                    name,
                    label=label,
                )
                if (opened.st_dev, opened.st_ino) != expected:
                    os.close(descriptor)
                    raise MutationJournalError(
                        f"Git-admin directory changed identity: {label}"
                    )
                try:
                    _assert_settlement_parent_binding(
                        authority_fd,
                        relative,
                        parent_fd,
                        parent_chain,
                    )
                    yield descriptor
                    current = os.stat(
                        name,
                        dir_fd=parent_fd,
                        follow_symlinks=False,
                    )
                    if (current.st_dev, current.st_ino) != expected:
                        raise MutationJournalError(
                            f"Git-admin directory changed while held: {label}"
                        )
                    _assert_settlement_parent_binding(
                        authority_fd,
                        relative,
                        parent_fd,
                        parent_chain,
                    )
                finally:
                    os.close(descriptor)

    def _inspect_bound_git_admin_entry(
        self,
        rendered: str | Path,
        *,
        label: str,
        authority_batch: _GitAdminAuthorityBatch | None = None,
    ) -> tuple[os.stat_result, dict[str, str]]:
        """Inspect a stable admin entry without following a namespace alias."""

        logical = _lexical_workspace_path(Path(rendered))
        with self._bound_git_admin_path(
            logical,
            authority_batch=authority_batch,
        ) as (
            root_fd,
            relative,
            _logical_root,
        ):
            if relative == ".":
                metadata = os.fstat(root_fd)
                return metadata, _bound_descriptor_xattr_inventory(
                    root_fd,
                    label=label,
                )
            with _open_settlement_parent_if_present(
                root_fd,
                relative,
                allow_terminal_vcs_metadata=True,
            ) as binding:
                parent_fd, name, parent_chain, missing_index = binding
                if missing_index is not None:
                    raise MutationJournalError(
                        f"Git-admin entry disappeared: {label}"
                    )
                before = os.stat(
                    name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
                flags = (
                    os.O_RDONLY
                    | getattr(os, "O_CLOEXEC", 0)
                    | getattr(os, "O_NOFOLLOW", 0)
                    | getattr(os, "O_NONBLOCK", 0)
                )
                if stat.S_ISDIR(before.st_mode) and not stat.S_ISLNK(
                    before.st_mode
                ):
                    flags |= getattr(os, "O_DIRECTORY", 0)
                descriptor = os.open(name, flags, dir_fd=parent_fd)
                try:
                    opened = os.fstat(descriptor)
                    if (opened.st_dev, opened.st_ino) != (
                        before.st_dev,
                        before.st_ino,
                    ):
                        raise MutationJournalError(
                            f"Git-admin entry changed while opening: {label}"
                        )
                    xattrs = _bound_descriptor_xattr_inventory(
                        descriptor,
                        label=label,
                    )
                    current = os.stat(
                        name,
                        dir_fd=parent_fd,
                        follow_symlinks=False,
                    )
                    if (current.st_dev, current.st_ino) != (
                        opened.st_dev,
                        opened.st_ino,
                    ):
                        raise MutationJournalError(
                            f"Git-admin entry changed during inspection: {label}"
                        )
                    _assert_settlement_parent_binding(
                        root_fd,
                        relative,
                        parent_fd,
                        parent_chain,
                        allow_terminal_vcs_metadata=True,
                    )
                    return opened, xattrs
                finally:
                    os.close(descriptor)

    def _assert_bound_git_admin_entry_absent(
        self,
        rendered: str | Path,
        *,
        label: str,
    ) -> None:
        """Prove one missing admin entry through a stable held parent chain."""

        logical = _lexical_workspace_path(Path(rendered))
        with self._bound_git_admin_path(logical) as (
            root_fd,
            relative,
            _logical_root,
        ):
            if relative == ".":
                raise MutationJournalError(
                    f"absent Git-admin entry aliases authority root: {label}"
                )
            with _open_settlement_parent_if_present(
                root_fd,
                relative,
                allow_terminal_vcs_metadata=True,
            ) as first:
                parent_fd, name, parent_chain, missing_index = first
                if missing_index is None:
                    try:
                        os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
                    except FileNotFoundError:
                        _assert_settlement_parent_binding(
                            root_fd,
                            relative,
                            parent_fd,
                            parent_chain,
                            allow_terminal_vcs_metadata=True,
                        )
                    else:
                        raise MutationJournalError(
                            f"Git-admin entry unexpectedly exists: {label}"
                        )
            with _open_settlement_parent_if_present(
                root_fd,
                relative,
                allow_terminal_vcs_metadata=True,
            ) as second:
                (
                    retry_parent_fd,
                    retry_name,
                    retry_chain,
                    retry_missing_index,
                ) = second
                if (
                    retry_chain != parent_chain
                    or retry_missing_index != missing_index
                ):
                    raise MutationJournalError(
                        f"Git-admin absence changed during proof: {label}"
                    )
                if retry_missing_index is None:
                    try:
                        os.stat(
                            retry_name,
                            dir_fd=retry_parent_fd,
                            follow_symlinks=False,
                        )
                    except FileNotFoundError:
                        _assert_settlement_parent_binding(
                            root_fd,
                            relative,
                            retry_parent_fd,
                            retry_chain,
                            allow_terminal_vcs_metadata=True,
                        )
                    else:
                        raise MutationJournalError(
                            f"Git-admin entry appeared during proof: {label}"
                        )

    def _read_bound_git_admin_file(
        self,
        rendered: str | Path,
        *,
        label: str,
        max_bytes: int,
        authority_batch: _GitAdminAuthorityBatch | None = None,
    ) -> tuple[bytes, os.stat_result, dict[str, str]]:
        """Read one stable Git-admin file through a held parent descriptor."""

        logical = _lexical_workspace_path(Path(rendered))
        with self._bound_git_admin_path(
            logical,
            authority_batch=authority_batch,
        ) as (
            root_fd,
            relative,
            _logical_root,
        ):
            if relative == ".":
                raise MutationJournalError(
                    f"Git-admin file aliases an authority root: {label}"
                )
            with _open_settlement_parent_if_present(
                root_fd,
                relative,
                allow_terminal_vcs_metadata=True,
            ) as binding:
                parent_fd, name, parent_chain, missing_index = binding
                if missing_index is not None:
                    raise MutationJournalError(
                        f"Git-admin file parent disappeared: {label}"
                    )
                payload, opened = _read_bound_regular_entry(
                    parent_fd,
                    name,
                    label=label,
                    max_bytes=max_bytes,
                )
                xattrs = _xattr_inventory(
                    Path(_authority_descriptor_cwd(parent_fd)) / name
                )
                current = os.stat(
                    name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
                if (current.st_dev, current.st_ino) != (
                    opened.st_dev,
                    opened.st_ino,
                ):
                    raise MutationJournalError(
                        f"Git-admin file changed after read: {label}"
                    )
                _assert_settlement_parent_binding(
                    root_fd,
                    relative,
                    parent_fd,
                    parent_chain,
                    allow_terminal_vcs_metadata=True,
                )
                return payload, opened, xattrs

    def _restore_bound_git_admin_entry_metadata(
        self,
        rendered: str | Path,
        *,
        record: Mapping[str, object],
        label: str,
        require_identity: bool,
    ) -> bool:
        """Restore metadata on one already-proved opaque admin entry."""

        mode = record.get("mode")
        if (
            isinstance(mode, bool)
            or not isinstance(mode, int)
            or not 0 <= mode <= 0o7777
        ):
            raise MutationJournalError(
                f"Git-admin metadata mode is malformed: {label}"
            )
        expected_xattrs = _validated_restore_xattrs(
            record.get("xattrs", {}),
            label=label,
        )
        before, _xattrs = self._inspect_bound_git_admin_entry(
            rendered,
            label=label,
        )
        if require_identity:
            expected = (
                record.get("device"),
                record.get("inode"),
            )
            if expected != (before.st_dev, before.st_ino):
                raise MutationJournalError(
                    f"Git-admin opaque entry changed identity: {label}"
                )
        if stat.S_ISREG(before.st_mode):
            if before.st_nlink != 1:
                raise MutationJournalError(
                    f"Git-admin opaque file is hard-linked: {label}"
                )
        elif not stat.S_ISDIR(before.st_mode) or stat.S_ISLNK(before.st_mode):
            raise MutationJournalError(
                f"Git-admin opaque entry has unsupported type: {label}"
            )

        logical = _lexical_workspace_path(Path(rendered))
        changed = False
        with self._bound_git_admin_path(logical) as (
            root_fd,
            relative,
            _logical_root,
        ):
            if relative == ".":
                descriptor = os.dup(root_fd)
                parent_binding = None
            else:
                parent_binding = _open_settlement_parent_if_present(
                    root_fd,
                    relative,
                )
                parent_fd, name, parent_chain, missing_index = (
                    parent_binding.__enter__()
                )
                if missing_index is not None:
                    parent_binding.__exit__(None, None, None)
                    raise MutationJournalError(
                        f"Git-admin opaque entry disappeared: {label}"
                    )
                flags = (
                    os.O_RDONLY
                    | getattr(os, "O_CLOEXEC", 0)
                    | getattr(os, "O_NOFOLLOW", 0)
                    | getattr(os, "O_NONBLOCK", 0)
                )
                if stat.S_ISDIR(before.st_mode):
                    flags |= getattr(os, "O_DIRECTORY", 0)
                descriptor = os.open(name, flags, dir_fd=parent_fd)
            try:
                opened = os.fstat(descriptor)
                if (opened.st_dev, opened.st_ino) != (
                    before.st_dev,
                    before.st_ino,
                ):
                    raise MutationJournalError(
                        f"Git-admin opaque entry changed before metadata restore: {label}"
                    )
                if _bound_descriptor_xattr_inventory(
                    descriptor,
                    label=label,
                ) != expected_xattrs:
                    _restore_bound_descriptor_xattrs(
                        descriptor,
                        expected_xattrs,
                        label=label,
                    )
                    changed = True
                if stat.S_IMODE(opened.st_mode) != mode:
                    os.fchmod(descriptor, mode)
                    changed = True
                sealed = os.fstat(descriptor)
                if (sealed.st_dev, sealed.st_ino) != (
                    opened.st_dev,
                    opened.st_ino,
                ):
                    raise MutationJournalError(
                        f"Git-admin opaque entry changed during metadata restore: {label}"
                    )
                if relative != ".":
                    current = os.stat(
                        name,
                        dir_fd=parent_fd,
                        follow_symlinks=False,
                    )
                    if (current.st_dev, current.st_ino) != (
                        opened.st_dev,
                        opened.st_ino,
                    ):
                        raise MutationJournalError(
                            f"Git-admin opaque entry changed after metadata restore: {label}"
                        )
                    _assert_settlement_parent_binding(
                        root_fd,
                        relative,
                        parent_fd,
                        parent_chain,
                    )
            finally:
                os.close(descriptor)
                if parent_binding is not None:
                    parent_binding.__exit__(None, None, None)
        return changed

    def _restore_bound_git_admin_tree(
        self,
        rendered: str | Path,
        *,
        exists: bool,
        record: Mapping[str, object],
        entries: Mapping[str, Mapping[str, object]],
        label: str,
        opaque_roots: Iterable[str] = (),
        preloaded_payloads: Mapping[str, bytes] | None = None,
    ) -> bool:
        """Reconcile one exact admin tree while preserving captured inodes."""

        opaque = tuple(_dedupe_roots(opaque_roots))
        mode = record.get("mode")
        if exists and (
            not isinstance(mode, int)
            or isinstance(mode, bool)
            or not 0 <= mode <= 0o7777
        ):
            raise MutationJournalError(
                f"Git-admin tree mode is malformed: {label}"
            )
        root_xattrs = _validated_restore_xattrs(
            record.get("xattrs", {}),
            label=label,
        ) if exists else {}

        # Validate the complete manifest and authenticate every payload before
        # the first namespace or metadata mutation.
        normalized_entries: dict[str, dict[str, object]] = {}
        payloads: dict[str, bytes] = {}
        budget = _MutationJournalArtifactBudget()
        for rendered_relative, untyped_entry in entries.items():
            if not isinstance(rendered_relative, str) or not isinstance(
                untyped_entry,
                Mapping,
            ):
                raise MutationJournalError(
                    f"Git-admin tree manifest is malformed: {label}"
                )
            relative = _settlement_relative_path(rendered_relative)
            if relative != rendered_relative:
                raise MutationJournalError(
                    f"Git-admin tree path is noncanonical: {rendered_relative!r}"
                )
            entry = dict(untyped_entry)
            kind = entry.get("kind")
            entry_mode = entry.get("mode")
            if kind not in {"directory", "file"} or (
                not isinstance(entry_mode, int)
                or isinstance(entry_mode, bool)
                or not 0 <= entry_mode <= 0o7777
            ):
                raise MutationJournalError(
                    f"Git-admin tree entry is malformed: {label}/{relative}"
                )
            _validated_restore_xattrs(
                entry.get("xattrs", {}),
                label=f"{label}/{relative}",
            )
            if kind == "directory" and any(
                isinstance(entry.get(field), bool)
                or not isinstance(entry.get(field), int)
                or cast(int, entry.get(field)) < 0
                for field in ("device", "inode")
            ):
                raise MutationJournalError(
                    f"Git-admin directory lacks inode authority: {label}/{relative}"
                )
            if kind == "file":
                if preloaded_payloads is None:
                    payloads[relative] = self._read_snapshot_blob_record(
                        entry,
                        label=f"{label}/{relative}",
                        budget=budget,
                    )
                else:
                    try:
                        payloads[relative] = preloaded_payloads[relative]
                    except KeyError:
                        raise MutationJournalError(
                            "preloaded Git-admin payload is absent: "
                            f"{label}/{relative}"
                        ) from None
            normalized_entries[relative] = entry
        for relative in normalized_entries:
            parent = PurePosixPath(relative).parent.as_posix()
            while parent not in {"", "."}:
                parent_entry = normalized_entries.get(parent)
                if parent_entry is None or parent_entry.get("kind") != "directory":
                    raise MutationJournalError(
                        f"Git-admin tree lacks parent authority: {label}/{relative}"
                    )
                parent = PurePosixPath(parent).parent.as_posix()

        logical_target = _lexical_workspace_path(Path(rendered))
        changed = False
        with self._bound_git_admin_path(logical_target) as (
            authority_fd,
            target_relative,
            logical_root,
        ):
            target_fd: int | None = None
            root_identity: tuple[int, int]
            if target_relative == ".":
                if not exists:
                    raise MutationJournalError(
                        f"cannot remove held Git-admin authority root: {label}"
                    )
                target_fd = os.dup(authority_fd)
                opened_root = os.fstat(target_fd)
                expected_identity = (
                    record.get("device"),
                    record.get("inode"),
                )
                if expected_identity != (
                    opened_root.st_dev,
                    opened_root.st_ino,
                ):
                    raise MutationJournalError(
                        f"Git-admin authority root changed: {label}"
                    )
                root_identity = (opened_root.st_dev, opened_root.st_ino)
            else:
                if not exists:
                    with _open_settlement_parent_if_present(
                        authority_fd,
                        target_relative,
                    ) as absence:
                        (
                            _absence_parent_fd,
                            _absence_name,
                            absence_chain,
                            absence_missing_index,
                        ) = absence
                        if absence_missing_index is not None:
                            # An absent baseline tree whose parent also never
                            # existed needs no reconstruction. Reprove the
                            # exact missing-parent frontier so a racing
                            # appearance cannot be mistaken for stable
                            # absence.
                            with _open_settlement_parent_if_present(
                                authority_fd,
                                target_relative,
                            ) as retry:
                                (
                                    _retry_parent_fd,
                                    _retry_name,
                                    retry_chain,
                                    retry_missing_index,
                                ) = retry
                                if (
                                    retry_chain != absence_chain
                                    or retry_missing_index
                                    != absence_missing_index
                                ):
                                    raise MutationJournalError(
                                        f"Git-admin tree absence changed: {label}"
                                    )
                            return False
                parent_chain = self._ensure_git_admin_parent_chain(
                    authority_fd,
                    logical_root,
                    target_relative,
                )
                with _open_settlement_parent_if_present(
                    authority_fd,
                    target_relative,
                ) as binding:
                    parent_fd, name, observed_chain, missing_index = binding
                    if missing_index is not None or observed_chain != parent_chain:
                        raise MutationJournalError(
                            f"Git-admin tree parent changed: {label}"
                        )
                    try:
                        current_root = os.stat(
                            name,
                            dir_fd=parent_fd,
                            follow_symlinks=False,
                        )
                    except FileNotFoundError:
                        current_root = None
                    if not exists:
                        if current_root is None:
                            return False
                        if stat.S_ISDIR(
                            current_root.st_mode
                        ) and not stat.S_ISLNK(current_root.st_mode):
                            raise MutationJournalError(
                                "refusing to recursively remove an "
                                "unauthenticated Git-admin tree: "
                                f"{label}"
                            )
                        _remove_bound_workspace_entry(
                            authority_fd,
                            target_relative,
                            parent_fd,
                            name,
                            parent_chain,
                        )
                        return True
                    expected_identity = self._restored_git_admin_directory_authority.get(
                        os.fspath(logical_target),
                        (
                            cast(int, record.get("device")),
                            cast(int, record.get("inode")),
                        ),
                    )
                    if current_root is not None and stat.S_ISDIR(
                        current_root.st_mode
                    ) and not stat.S_ISLNK(current_root.st_mode):
                        if (current_root.st_dev, current_root.st_ino) != (
                            expected_identity
                        ):
                            raise MutationJournalError(
                                f"Git-admin tree changed identity: {label}"
                            )
                    else:
                        if current_root is not None:
                            _remove_bound_workspace_entry(
                                authority_fd,
                                target_relative,
                                parent_fd,
                                name,
                                parent_chain,
                            )
                        installed = _install_bound_workspace_entry(
                            authority_fd,
                            target_relative,
                            expected_parent_chain=parent_chain,
                            kind="directory",
                            mode=cast(int, mode),
                            xattrs=root_xattrs,
                        )
                        self._restored_git_admin_directory_authority[
                            os.fspath(logical_target)
                        ] = installed
                        expected_identity = installed
                        changed = True
                    target_fd, opened = _open_authority_directory_at(
                        parent_fd,
                        name,
                        label=label,
                    )
                    if (opened.st_dev, opened.st_ino) != expected_identity:
                        os.close(target_fd)
                        target_fd = None
                        raise MutationJournalError(
                            f"Git-admin tree changed while opening: {label}"
                        )
                    root_identity = expected_identity
                    _assert_settlement_parent_binding(
                        authority_fd,
                        target_relative,
                        parent_fd,
                        parent_chain,
                    )

            assert target_fd is not None
            try:
                inventory = _bound_admin_tree_inventory(
                    target_fd,
                    label=label,
                    opaque_roots=opaque,
                )
                # A real same-mode directory is the dangerous substitution:
                # unlike a file/symlink transition, recursively editing it can
                # mutate an externally parked tree. Reject it before removing
                # any addition or replacing any file.
                for relative, entry in normalized_entries.items():
                    if entry["kind"] != "directory":
                        continue
                    current = inventory.get(relative)
                    if current is None or not stat.S_ISDIR(
                        current.st_mode
                    ) or stat.S_ISLNK(current.st_mode):
                        continue
                    logical = os.fspath(logical_target / relative)
                    expected_identity = self._restored_git_admin_directory_authority.get(
                        logical,
                        (cast(int, entry["device"]), cast(int, entry["inode"])),
                    )
                    if (current.st_dev, current.st_ino) != expected_identity:
                        raise MutationJournalError(
                            f"Git-admin directory changed identity: {label}/{relative}"
                        )

                expected_names = set(normalized_entries)
                for relative in set(inventory).difference(expected_names):
                    if any(
                        relative == root
                        or relative.startswith(root.rstrip("/") + "/")
                        for root in opaque
                    ):
                        continue
                    observed = inventory[relative]
                    if stat.S_ISDIR(observed.st_mode) and not stat.S_ISLNK(
                        observed.st_mode
                    ):
                        raise MutationJournalError(
                            "refusing to recursively remove an "
                            "unauthenticated Git-admin directory addition: "
                            f"{label}/{relative}"
                        )
                for relative in sorted(
                    set(inventory).difference(expected_names),
                    key=lambda value: (value.count("/"), value),
                    reverse=True,
                ):
                    if any(
                        relative == root
                        or relative.startswith(root.rstrip("/") + "/")
                        for root in opaque
                    ):
                        continue
                    with _open_settlement_parent_if_present(
                        target_fd,
                        relative,
                    ) as binding:
                        parent_fd, name, parent_chain, missing_index = binding
                        if missing_index is not None:
                            raise MutationJournalError(
                                f"Git-admin addition parent disappeared: {label}/{relative}"
                            )
                        _remove_bound_workspace_entry(
                            target_fd,
                            relative,
                            parent_fd,
                            name,
                            parent_chain,
                        )
                        changed = True

                for relative, entry in sorted(
                    normalized_entries.items(),
                    key=lambda item: (item[0].count("/"), item[0]),
                ):
                    if entry["kind"] != "directory":
                        continue
                    with _open_settlement_parent_if_present(
                        target_fd,
                        relative,
                    ) as binding:
                        parent_fd, name, parent_chain, missing_index = binding
                        if missing_index is not None:
                            raise MutationJournalError(
                                f"Git-admin directory parent disappeared: {label}/{relative}"
                            )
                        try:
                            current = os.stat(
                                name,
                                dir_fd=parent_fd,
                                follow_symlinks=False,
                            )
                        except FileNotFoundError:
                            current = None
                        if current is not None and (
                            not stat.S_ISDIR(current.st_mode)
                            or stat.S_ISLNK(current.st_mode)
                        ):
                            _remove_bound_workspace_entry(
                                target_fd,
                                relative,
                                parent_fd,
                                name,
                                parent_chain,
                            )
                            current = None
                        if current is None:
                            installed = _install_bound_workspace_entry(
                                target_fd,
                                relative,
                                expected_parent_chain=parent_chain,
                                kind="directory",
                                mode=cast(int, entry["mode"]),
                                xattrs=_validated_restore_xattrs(
                                    entry.get("xattrs", {}),
                                    label=f"{label}/{relative}",
                                ),
                            )
                            self._restored_git_admin_directory_authority[
                                os.fspath(logical_target / relative)
                            ] = installed
                            changed = True

                for relative, entry in sorted(normalized_entries.items()):
                    if entry["kind"] != "file":
                        continue
                    if self._restore_bound_git_admin_file(
                        logical_target / relative,
                        exists=True,
                        record=entry,
                        payload=payloads[relative],
                        label=f"{label}/{relative}",
                    ):
                        changed = True

                # Metadata is restored deepest-first so a restrictive parent
                # never blocks access to a child still being finalized.
                for relative, entry in sorted(
                    (
                        item for item in normalized_entries.items()
                        if item[1]["kind"] == "directory"
                    ),
                    key=lambda item: (item[0].count("/"), item[0]),
                    reverse=True,
                ):
                    with _open_settlement_parent_if_present(
                        target_fd,
                        relative,
                    ) as binding:
                        parent_fd, name, parent_chain, missing_index = binding
                        if missing_index is not None:
                            raise MutationJournalError(
                                f"Git-admin directory disappeared: {label}/{relative}"
                            )
                        child_fd, opened = _open_authority_directory_at(
                            parent_fd,
                            name,
                            label=f"{label}/{relative}",
                        )
                        try:
                            expected_identity = self._restored_git_admin_directory_authority.get(
                                os.fspath(logical_target / relative),
                                (
                                    cast(int, entry["device"]),
                                    cast(int, entry["inode"]),
                                ),
                            )
                            if (opened.st_dev, opened.st_ino) != expected_identity:
                                raise MutationJournalError(
                                    f"Git-admin directory changed: {label}/{relative}"
                                )
                            expected_xattrs = _validated_restore_xattrs(
                                entry.get("xattrs", {}),
                                label=f"{label}/{relative}",
                            )
                            if _bound_descriptor_xattr_inventory(
                                child_fd,
                                label=f"{label}/{relative}",
                            ) != expected_xattrs:
                                _restore_bound_descriptor_xattrs(
                                    child_fd,
                                    expected_xattrs,
                                    label=f"{label}/{relative}",
                                )
                                changed = True
                            requested_mode = int(cast(int, entry["mode"]))
                            if stat.S_IMODE(opened.st_mode) != requested_mode:
                                os.fchmod(child_fd, requested_mode)
                                changed = True
                            _fsync_bound_directory(child_fd)
                            _assert_settlement_parent_binding(
                                target_fd,
                                relative,
                                parent_fd,
                                parent_chain,
                            )
                        finally:
                            os.close(child_fd)

                if _bound_descriptor_xattr_inventory(
                    target_fd,
                    label=label,
                ) != root_xattrs:
                    _restore_bound_descriptor_xattrs(
                        target_fd,
                        root_xattrs,
                        label=label,
                    )
                    changed = True
                current_root = os.fstat(target_fd)
                requested_root_mode = int(cast(int, mode))
                if stat.S_IMODE(current_root.st_mode) != requested_root_mode:
                    os.fchmod(target_fd, requested_root_mode)
                    changed = True
                sealed = os.fstat(target_fd)
                if (sealed.st_dev, sealed.st_ino) != root_identity:
                    raise MutationJournalError(
                        f"Git-admin tree changed during restoration: {label}"
                    )

                final_inventory = _bound_admin_tree_inventory(
                    target_fd,
                    label=f"{label} final proof",
                    opaque_roots=opaque,
                )
                if set(final_inventory) != set(normalized_entries):
                    raise MutationJournalError(
                        f"Git-admin tree differs after restoration: {label}"
                    )
                for relative, entry in normalized_entries.items():
                    observed = final_inventory[relative]
                    if entry["kind"] == "directory":
                        expected_identity = self._restored_git_admin_directory_authority.get(
                            os.fspath(logical_target / relative),
                            (
                                cast(int, entry["device"]),
                                cast(int, entry["inode"]),
                            ),
                        )
                        if (
                            not stat.S_ISDIR(observed.st_mode)
                            or stat.S_ISLNK(observed.st_mode)
                            or (observed.st_dev, observed.st_ino)
                            != expected_identity
                        ):
                            raise MutationJournalError(
                                f"Git-admin directory lost authority: {label}/{relative}"
                            )
                    elif not stat.S_ISREG(observed.st_mode) or observed.st_nlink != 1:
                        raise MutationJournalError(
                            f"Git-admin file lost authority: {label}/{relative}"
                        )
            finally:
                os.close(target_fd)
        return changed

    def _bound_git_admin_tree_matches(
        self,
        rendered: str | Path,
        *,
        record: Mapping[str, object],
        entries: Mapping[str, Mapping[str, object]],
        label: str,
        opaque_roots: Iterable[str] = (),
    ) -> bool:
        """Prove an exact admin tree from held inodes and bound blobs."""

        payloads: dict[str, bytes] = {}
        budget = _MutationJournalArtifactBudget()
        for rendered_relative, entry in entries.items():
            if (
                not isinstance(rendered_relative, str)
                or _settlement_relative_path(rendered_relative)
                != rendered_relative
                or not isinstance(entry, Mapping)
            ):
                raise MutationJournalError(
                    f"Git-admin assertion manifest is malformed: {label}"
                )
            if entry.get("kind") == "file":
                payloads[rendered_relative] = self._read_snapshot_blob_record(
                    entry,
                    label=f"{label}/{rendered_relative}",
                    budget=budget,
                )
        with self._git_admin_authority_batch() as authority_batch:
            with self._open_bound_git_admin_directory(
                rendered,
                record=record,
                label=label,
                authority_batch=authority_batch,
            ) as root_fd:
                inventory = _bound_admin_tree_inventory(
                    root_fd,
                    label=label,
                    opaque_roots=opaque_roots,
                )
                if set(inventory) != set(entries):
                    return False
                for relative, entry in entries.items():
                    observed = inventory[relative]
                    kind = entry.get("kind")
                    if (
                        stat.S_IMODE(observed.st_mode) != entry.get("mode")
                        or kind == "directory"
                        and (
                            not stat.S_ISDIR(observed.st_mode)
                            or stat.S_ISLNK(observed.st_mode)
                            or (observed.st_dev, observed.st_ino)
                            != (entry.get("device"), entry.get("inode"))
                        )
                        or kind == "file"
                        and (
                            not stat.S_ISREG(observed.st_mode)
                            or observed.st_nlink != 1
                        )
                    ):
                        return False
                    logical = Path(rendered) / relative
                    inspected, xattrs = self._inspect_bound_git_admin_entry(
                        logical,
                        label=f"{label}/{relative}",
                        authority_batch=authority_batch,
                    )
                    if (
                        (inspected.st_dev, inspected.st_ino)
                        != (observed.st_dev, observed.st_ino)
                        or xattrs != entry.get("xattrs", {})
                    ):
                        return False
                    if kind == "file":
                        payload, opened, _file_xattrs = (
                            self._read_bound_git_admin_file(
                                logical,
                                label=f"{label}/{relative}",
                                max_bytes=max(len(payloads[relative]), 1),
                                authority_batch=authority_batch,
                            )
                        )
                        if (
                            payload != payloads[relative]
                            or (opened.st_dev, opened.st_ino)
                            != (observed.st_dev, observed.st_ino)
                        ):
                            return False
                return True

    def _assert_bound_git_authority(self) -> None:
        """Bind the held checkout's Git admin before any recovery write."""

        logical = Path(self._manifest["cwd"])
        authority = _active_workspace_mutation_authority(logical)
        if authority is None:
            return
        cwd = self._bound_workspace_cwd()
        try:
            worktree = _git_worktree_root(cwd)
            common = _git_common_dir(cwd)
            git_dir = _git_dir(cwd)
            worktree_metadata = worktree.lstat()
            held_root = os.fstat(authority.root_descriptor)
        except (OSError, MutationJournalError) as exc:
            raise MutationJournalError(
                f"held checkout lost its Git administration: {exc}"
            ) from exc
        captured_common = self._manifest.get("git_common_dir")
        if captured_common is None:
            objects_path = self._manifest.get("objects_path")
            captured_common = (
                str(Path(str(objects_path)).parent)
                if objects_path
                else str(common)
            )
        expected_common = self._bound_manifest_path(str(captured_common))
        expected_git_dir = self._bound_manifest_path(str(
            self._manifest.get("git_admin_dir", git_dir)
        ))
        if (
            not stat.S_ISDIR(worktree_metadata.st_mode)
            or stat.S_ISLNK(worktree_metadata.st_mode)
            or worktree_metadata.st_dev != held_root.st_dev
            or worktree_metadata.st_ino != held_root.st_ino
            or not self._bound_paths_same(common, expected_common)
            or not self._bound_paths_same(git_dir, expected_git_dir)
        ):
            raise MutationJournalError(
                "held checkout Git administration no longer binds its "
                "workspace authority"
            )

    def _prepare_workspace_root_access(
        self,
    ) -> _PreparedWorkspaceRootAccess | None:
        """Grant minimal owner lock-admission access through a bound root fd.

        A crashed provider can chmod the checkout root to ``000``.  The Git
        common-dir and lock checks necessarily traverse below that root, so
        bind the captured root inode first and add only owner read/search
        permission before those checks.  The ordinary lock opener requires
        both bits but never owner write.  ``O_PATH`` deliberately avoids requiring
        read/search permission while ``/proc/self/fd`` keeps the chmod tied to
        the opened inode rather than the replaceable checkout pathname.

        The caller must prove writer-epoch quiescence before entering this
        pre-lock repair.  This helper independently validates every manifest
        value used as mutation authority so a corrupt journal cannot turn the
        access-recovery exception into an unchecked chmod.
        """

        expected = self._manifest.get("authority_lock")
        if expected is None:
            return None
        if not isinstance(expected, Mapping):
            raise MutationJournalError(
                "workspace root access authority is malformed"
            )
        root_device = expected.get("root_device")
        root_inode = expected.get("root_inode")
        root_mode = expected.get("root_mode")
        if any(
            isinstance(value, bool)
            or not isinstance(value, int)
            or value < 0
            for value in (root_device, root_inode)
        ) or (
            not isinstance(root_mode, int)
            or isinstance(root_mode, bool)
            or not 0 <= root_mode <= 0o7777
        ):
            raise MutationJournalError(
                "workspace root access authority is malformed"
            )
        directory_modes = self._manifest.get("directory_modes")
        baseline_mode = (
            directory_modes.get(".")
            if isinstance(directory_modes, Mapping)
            else None
        )
        if (
            not isinstance(baseline_mode, int)
            or isinstance(baseline_mode, bool)
            or not 0 <= baseline_mode <= 0o7777
            or baseline_mode != root_mode
        ):
            raise MutationJournalError(
                "workspace root baseline mode authority is malformed"
            )
        logical = Path(self._manifest["cwd"])
        external = _active_external_workspace_coordination(logical)
        if external is None:
            raise MutationJournalError(
                "workspace root access preparation requires external "
                "coordination"
            )
        _assert_external_workspace_coordination(external)
        common_key = _validated_external_identity(
            expected.get("common_device"),
            expected.get("common_inode"),
            label="workspace root access common authority",
        )
        if (
            external.root_key != (root_device, root_inode)
            or external.common_key != common_key
        ):
            raise MutationJournalError(
                "workspace root access authority conflicts with external "
                "coordination"
            )
        descriptor = os.dup(external.binding.root_descriptor)
        try:
            metadata = os.fstat(descriptor)
            if (
                not stat.S_ISDIR(metadata.st_mode)
                or metadata.st_dev != root_device
                or metadata.st_ino != root_inode
            ):
                raise MutationJournalError(
                    "checkout root changed identity before access preparation"
                )
            requested = stat.S_IMODE(metadata.st_mode) | stat.S_IRUSR | stat.S_IXUSR
            if stat.S_IMODE(metadata.st_mode) != requested:
                os.chmod(_authority_descriptor_cwd(descriptor), requested)
            finished = os.fstat(descriptor)
            if (
                not stat.S_ISDIR(finished.st_mode)
                or finished.st_dev != metadata.st_dev
                or finished.st_ino != metadata.st_ino
                or stat.S_IMODE(finished.st_mode) != requested
            ):
                raise MutationJournalError(
                    "checkout root changed during access preparation"
                )
            return _PreparedWorkspaceRootAccess(
                previous_mode=stat.S_IMODE(metadata.st_mode),
                prepared_mode=requested,
            )
        finally:
            os.close(descriptor)

    def _revert_workspace_root_access(
        self,
        prepared: _PreparedWorkspaceRootAccess | None,
    ) -> None:
        """Undo a pre-lock repair if canonical admission did not complete."""

        if prepared is None or prepared.previous_mode == prepared.prepared_mode:
            return
        logical = Path(self._manifest["cwd"])
        external = _active_external_workspace_coordination(logical)
        if external is None:
            raise MutationJournalError(
                "cannot revert workspace root access without external "
                "coordination"
            )
        _assert_external_workspace_coordination(external)
        descriptor = os.dup(external.binding.root_descriptor)
        try:
            observed = os.fstat(descriptor)
            mode = stat.S_IMODE(observed.st_mode)
            if mode != prepared.prepared_mode:
                raise MutationJournalError(
                    "checkout root mode changed after access preparation"
                )
            os.chmod(
                _authority_descriptor_cwd(descriptor),
                prepared.previous_mode,
            )
            finished = os.fstat(descriptor)
            if (
                (finished.st_dev, finished.st_ino) != external.root_key
                or stat.S_IMODE(finished.st_mode) != prepared.previous_mode
            ):
                raise MutationJournalError(
                    "checkout root changed while reverting access preparation"
                )
        finally:
            os.close(descriptor)

    def _settle_prepared_workspace_root_access(
        self,
        prepared: _PreparedWorkspaceRootAccess | None,
    ) -> None:
        """Close a temporary family-lock repair after its body settles."""

        if prepared is None or prepared.previous_mode == prepared.prepared_mode:
            return
        logical = Path(self._manifest["cwd"])
        external = _active_external_workspace_coordination(logical)
        if external is None:
            raise MutationJournalError(
                "cannot settle workspace root access without coordination"
            )
        _assert_external_workspace_coordination(external)
        current = os.fstat(external.binding.root_descriptor)
        current_mode = stat.S_IMODE(current.st_mode)
        raw_modes = self._manifest.get("directory_modes")
        baseline_mode = (
            raw_modes.get(".") if isinstance(raw_modes, Mapping) else None
        )
        if current_mode in {prepared.previous_mode, baseline_mode}:
            return
        if current_mode != prepared.prepared_mode:
            raise MutationJournalError(
                "checkout root mode changed during coordinated family work"
            )
        self._revert_workspace_root_access(prepared)

    def _assert_external_common_authority(self) -> None:
        """Rebind Git after root repair and compare it to captured authority."""

        logical = Path(self._manifest["cwd"])
        external = _active_external_workspace_coordination(logical)
        expected = self._manifest.get("authority_lock")
        if external is None or not isinstance(expected, Mapping):
            raise MutationJournalError(
                "workspace common reproof lacks external authority"
            )
        observed = _discover_external_common_binding(external.binding)
        expected_common = (
            _lexical_workspace_path(str(expected.get("common_dir"))),
            _validated_external_identity(
                expected.get("common_device"),
                expected.get("common_inode"),
                label="captured workspace common",
            ),
        )
        if observed != expected_common or observed != (
            external.common_dir,
            external.common_key,
        ):
            raise MutationJournalError(
                "workspace common authority differs after root access repair"
            )

    @contextmanager
    def _pre_root_restore_authority(self) -> Iterator[None]:
        """Coordinate, repair, and canonically admit one direct restore."""

        expected = self._manifest.get("authority_lock")
        if not isinstance(expected, Mapping):
            raise MutationJournalError(
                "pre-root recovery lacks captured workspace authority"
            )
        logical = Path(self._manifest["cwd"])
        with _external_workspace_coordination(
            logical,
            captured_authority=expected,
        ):
            self._require_writer_epoch_quiescence(
                frontier="pre-lock workspace root access preparation"
            )
            prepared = self._prepare_workspace_root_access()
            admitted = False
            try:
                self._assert_external_common_authority()
                with workspace_mutation_lock(logical):
                    admitted = True
                    yield
            finally:
                if not admitted:
                    self._revert_workspace_root_access(prepared)
                else:
                    self._settle_prepared_workspace_root_access(prepared)

    @contextmanager
    def _nested_restore_authority(self) -> Iterator[None]:
        """Hold one child's exact root authority across family preflight."""

        logical = Path(self._manifest["cwd"])
        if _active_external_workspace_coordination(logical) is None:
            with self._pre_root_restore_authority():
                yield
            return
        if _active_workspace_mutation_authority(logical) is None:
            with workspace_mutation_lock(logical):
                yield
            return
        yield

    def _bound_paths_same(self, left: str | Path, right: str | Path) -> bool:
        """Compare captured/current paths by their descriptor-rebased inode."""

        try:
            left_metadata = self._bound_path_metadata(left)
            right_metadata = self._bound_path_metadata(right)
        except OSError:
            return False
        return (
            left_metadata.st_dev == right_metadata.st_dev
            and left_metadata.st_ino == right_metadata.st_ino
        )

    def _bound_path_metadata(self, rendered: str | Path) -> os.stat_result:
        """lstat a rebound path, treating held fd aliases as directories."""

        path = self._bound_manifest_path(rendered)
        authority = _active_workspace_mutation_authority(
            Path(self._manifest["cwd"])
        )
        if authority is not None:
            descriptor_paths = {
                Path(_authority_descriptor_cwd(authority.root_descriptor)):
                    authority.root_descriptor,
                Path(_authority_descriptor_cwd(authority.common_descriptor)):
                    authority.common_descriptor,
                Path(_authority_descriptor_cwd(
                    authority.git_common_descriptor
                )): authority.git_common_descriptor,
                Path(_authority_descriptor_cwd(
                    authority.git_dir_descriptor
                )): authority.git_dir_descriptor,
            }
            descriptor = descriptor_paths.get(path)
            if descriptor is not None:
                return os.fstat(descriptor)
        return path.lstat()

    def _bound_paths_equivalent(
        self,
        left: str | Path,
        right: str | Path,
    ) -> bool:
        """Compare an existing node or one absent final entry safely."""

        left_path = self._bound_manifest_path(left)
        right_path = self._bound_manifest_path(right)
        if left_path == right_path:
            return True
        if self._bound_paths_same(left_path, right_path):
            return True
        return (
            left_path.name == right_path.name
            and self._bound_paths_same(left_path.parent, right_path.parent)
        )

    @classmethod
    def begin(
        cls,
        *,
        cwd: str | Path,
        journal_root: Path,
        slice_id: str,
        scope: Iterable[str],
        sequence: int,
        spec: "Spec | None" = None,
        parent_transaction_id: str | None = None,
        _nested_gitlink_guard: bool = False,
        _external_worktree_guard: bool = False,
        _registered_peer_roots: Iterable[str] = (),
        _suppress_peer_guards: bool = False,
        _opaque_gitlink_roots: Iterable[str] = (),
        _suppress_superproject_guard: bool = False,
    ) -> "WorkspaceMutationJournal":
        """Begin a journal and remove unregistered partial artifacts on error."""

        root = Path(journal_root)
        before = set(root.iterdir()) if root.is_dir() else set()
        try:
            return cls._begin_unchecked(
                cwd=cwd,
                journal_root=root,
                slice_id=slice_id,
                scope=scope,
                sequence=sequence,
                spec=spec,
                parent_transaction_id=parent_transaction_id,
                _nested_gitlink_guard=_nested_gitlink_guard,
                _external_worktree_guard=_external_worktree_guard,
                _registered_peer_roots=_registered_peer_roots,
                _suppress_peer_guards=_suppress_peer_guards,
                _opaque_gitlink_roots=_opaque_gitlink_roots,
                _suppress_superproject_guard=_suppress_superproject_guard,
            )
        except BaseException as error:
            retained_owner_dir = (
                error.owner.journal_dir
                if isinstance(error, MutationJournalCleanupError)
                else None
            )
            try:
                candidates = (
                    set(root.iterdir()).difference(before)
                    if root.is_dir()
                    else set()
                )
            except OSError:
                # Sweeping is best-effort. In particular, never replace a typed
                # cleanup owner merely because its journal root became
                # temporarily unreadable while handling the primary failure.
                candidates = set()
            for candidate in candidates:
                if retained_owner_dir is not None:
                    try:
                        retained_owner_dir.relative_to(candidate)
                    except ValueError:
                        pass
                    else:
                        # The typed error is the caller's exact retry
                        # authority. Never let best-effort partial-artifact
                        # sweeping destroy it or an ancestor containing it.
                        continue
                manifest_path = candidate / _MANIFEST
                marker_exists = False
                try:
                    manifest = json.loads(manifest_path.read_text())
                    marker_exists = Path(manifest["registry_marker"]).is_file()
                except (OSError, KeyError, TypeError, json.JSONDecodeError):
                    pass
                if not marker_exists:
                    shutil.rmtree(candidate, ignore_errors=True)
            raise

    @classmethod
    def _begin_unchecked(
        cls,
        *,
        cwd: str | Path,
        journal_root: Path,
        slice_id: str,
        scope: Iterable[str],
        sequence: int,
        spec: "Spec | None" = None,
        parent_transaction_id: str | None = None,
        _nested_gitlink_guard: bool = False,
        _external_worktree_guard: bool = False,
        _registered_peer_roots: Iterable[str] = (),
        _suppress_peer_guards: bool = False,
        _opaque_gitlink_roots: Iterable[str] = (),
        _suppress_superproject_guard: bool = False,
        _registry_binding: tuple[Path, int, os.stat_result] | None = None,
    ) -> "WorkspaceMutationJournal":
        _reject_git_redirect_env()
        if _active_workspace_mutation_authority(cwd) is not None:
            _assert_workspace_mutation_authority(cwd)
        root = Path(cwd).resolve()
        if not (root / ".git").exists():
            raise MutationJournalError(f"not a Git checkout: {root}")
        if _git_worktree_root(root) != root:
            raise MutationJournalError(
                f"journal cwd is not the exact Git worktree root: {root}"
            )
        if parent_transaction_id is not None:
            # A caller cannot create a child lineage by asserting an opaque
            # string. Internal gitlink/peer guards may target related
            # worktrees, so exact-cwd validation remains the responsibility
            # of nested workflow entry points; every child still requires a
            # process-owned active parent here.
            _require_live_parent_transaction(parent_transaction_id)
        _reject_git_config_includes(root)
        _reject_repository_filter_config(root)
        core_worktree_config = _git_config(root, "core.worktree")
        normalized_scope, recursive_scope = _normalize_scope_authority(
            root,
            scope,
        )
        transforming_paths, external_filter_paths = (
            ((), ())
            if _nested_gitlink_guard
            else _reject_transforming_checkout(
                root,
                probe_paths=normalized_scope,
            )
        )
        if _registry_binding is None:
            # Keep the exact registry inode open across every creation phase.
            # A lexical replacement between preflight, capture, manifest
            # publication, and marker publication must never become authority.
            created_journal: WorkspaceMutationJournal | None = None
            try:
                with _bound_workspace_registry_directory(root) as (
                    registry_path,
                    registry_fd,
                ):
                    registry_metadata = os.fstat(registry_fd)
                    # Canonical normalization removes trailing separators.
                    # Re-render the recursive subset so the held-registry
                    # revalidation cannot narrow authored directory authority
                    # for a root that is still absent.
                    created_journal = cls._begin_unchecked(
                        cwd=root,
                        journal_root=journal_root,
                        slice_id=slice_id,
                        scope=tuple(
                            f"{path}/" if path in recursive_scope else path
                            for path in normalized_scope
                        ),
                        sequence=sequence,
                        spec=spec,
                        parent_transaction_id=parent_transaction_id,
                        _nested_gitlink_guard=_nested_gitlink_guard,
                        _external_worktree_guard=_external_worktree_guard,
                        _registered_peer_roots=_registered_peer_roots,
                        _suppress_peer_guards=_suppress_peer_guards,
                        _opaque_gitlink_roots=_opaque_gitlink_roots,
                        _suppress_superproject_guard=(
                            _suppress_superproject_guard
                        ),
                        _registry_binding=(
                            registry_path,
                            registry_fd,
                            registry_metadata,
                        ),
                    )
                return created_journal
            except BaseException as error:
                if (
                    created_journal is not None
                    and not isinstance(error, MutationJournalCleanupError)
                ):
                    raise MutationJournalCleanupError(
                        owner=created_journal,
                        primary_error=error,
                    ) from error
                raise
        registry_path, registry_fd, registry_metadata = _registry_binding
        held_registry_metadata = os.fstat(registry_fd)
        if (
            not stat.S_ISDIR(held_registry_metadata.st_mode)
            or (
                held_registry_metadata.st_dev,
                held_registry_metadata.st_ino,
            )
            != (registry_metadata.st_dev, registry_metadata.st_ino)
        ):
            raise MutationJournalError(
                "mutation-journal registry changed during transaction creation"
            )
        authority_lock = _capture_authority_lock(root)
        _assert_registry_clear(
            root,
            _registry_binding=(registry_path, registry_fd),
        )
        registry_baseline_entries = _bound_registry_entry_names_at(
            registry_fd
        )
        _assert_bound_workspace_registry_identity(
            root,
            registry_fd,
            registry_metadata,
            label="mutation-journal registry after preflight",
        )
        registered_worktrees = _registered_worktrees(root)
        main_worktree = (
            Path(registered_worktrees[0]).resolve()
            if registered_worktrees else root
        )
        allowed_worktrees = {root}
        if _nested_gitlink_guard or (root / ".git").is_file():
            # Absorbed submodules without extensions.worktreeConfig may report
            # their administrative gitdir as the sole porcelain worktree.
            allowed_worktrees.add(_git_common_dir(root))
        if _git_dir(root) != _git_common_dir(root):
            allowed_worktrees.add(main_worktree)
        allowed_worktrees.update(
            Path(rendered).resolve() for rendered in _registered_peer_roots
        )
        sibling_worktrees = tuple(
            rendered
            for rendered in registered_worktrees
            if Path(rendered).resolve() not in allowed_worktrees
        )
        linked_main_peer = (
            (str(main_worktree),)
            if (
                _git_dir(root) != _git_common_dir(root)
                and main_worktree != root
            ) else ()
        )
        peer_candidates = (
            ()
            if _suppress_peer_guards
            else tuple(dict.fromkeys((*sibling_worktrees, *linked_main_peer)))
        )
        available_peer_worktrees: list[str] = []
        absent_peer_worktrees: list[str] = []
        for rendered in peer_candidates:
            peer_path = Path(rendered).resolve()
            if peer_path.is_dir() and (peer_path / ".git").exists():
                available_peer_worktrees.append(str(peer_path))
            elif not peer_path.exists():
                absent_peer_worktrees.append(str(peer_path))
            else:
                raise MutationJournalError(
                    "registered sibling Git worktree path is occupied by an "
                    f"untrusted non-checkout: {peer_path}"
                )
        peer_worktrees = tuple(available_peer_worktrees)
        worktrees_admin_root = _git_common_dir(root) / "worktrees"
        guarded_worktree_admin_roots: set[str] = set()
        absent_worktree_admin_roots: dict[str, str] = {}
        absent_peer_set = {
            Path(path).resolve() for path in absent_peer_worktrees
        }
        admin_roots_by_checkout = _registered_worktree_admin_roots(root)
        for rendered_peer in (
            *_registered_peer_roots,
            *peer_worktrees,
            *absent_peer_worktrees,
        ):
            resolved_peer = Path(rendered_peer).resolve()
            admin_name = admin_roots_by_checkout.get(resolved_peer)
            if admin_name is not None:
                guarded_worktree_admin_roots.add(admin_name)
                if resolved_peer in absent_peer_set:
                    absent_worktree_admin_roots[admin_name] = str(
                        worktrees_admin_root / admin_name
                    )
                continue
            if not resolved_peer.is_dir() or not (resolved_peer / ".git").exists():
                continue
            peer_git_dir = _git_dir(resolved_peer)
            try:
                relative_peer_git_dir = peer_git_dir.relative_to(
                    worktrees_admin_root
                )
            except ValueError:
                continue
            if relative_peer_git_dir.parts:
                guarded_worktree_admin_roots.add(
                    relative_peer_git_dir.parts[0]
                )
        worktree_namespace_topology = _worktree_namespace_topology(
            root,
            guarded_admin_roots=guarded_worktree_admin_roots,
            require_restore_control=True,
        )
        unsupported_worktree_namespace = {
            path: metadata
            for path, metadata in worktree_namespace_topology.items()
            if (
                path != "."
                or metadata.get("kind") not in {"directory", "missing"}
            )
        }
        if unsupported_worktree_namespace:
            raise MutationJournalError(
                "partial or unregistered Git worktree administration is "
                f"unsupported: {sorted(unsupported_worktree_namespace)[:10]!r}"
            )

        safe_slice = "".join(
            char if char.isalnum() or char in "-_" else "_"
            for char in slice_id
        )[:80] or "slice"
        transaction_id = secrets.token_hex(16)
        journal_dir = journal_root / (
            f"{sequence:04d}_{safe_slice}_{secrets.token_hex(6)}"
        )
        journal_dir.mkdir(parents=True, mode=0o700)

        absent_worktree_admin_controls: list[dict[str, object]] = []
        for admin_index, (name, rendered) in enumerate(sorted(
            absent_worktree_admin_roots.items()
        )):
            admin_root = Path(rendered)
            metadata = admin_root.lstat()
            if (
                not stat.S_ISDIR(metadata.st_mode)
                or stat.S_ISLNK(metadata.st_mode)
            ):
                raise MutationJournalError(
                    f"missing-worktree admin root is aliased: {admin_root}"
                )
            _assert_directory_restore_control(admin_root, metadata)
            snapshot_name = f"absent_worktree_admin_{admin_index}"
            absent_worktree_admin_controls.append({
                "name": name,
                "root": str(admin_root),
                "mode": stat.S_IMODE(metadata.st_mode),
                "device": metadata.st_dev,
                "inode": metadata.st_ino,
                "xattrs": _xattr_inventory(admin_root),
                "snapshot_name": snapshot_name,
                "entries": _capture_refs_tree(
                    journal_dir,
                    admin_root,
                    snapshot_name=snapshot_name,
                    require_restore_control=True,
                ),
            })

        # Capture the raw index before any status/discovery operation. Even a
        # read-only ``git status`` may refresh stat-cache bytes unless optional
        # locks are disabled, and the transaction baseline must precede every
        # Crucible observation.
        index = _index_path(root)
        try:
            index_metadata = index.lstat()
        except FileNotFoundError:
            index_metadata = None
        if index_metadata is not None:
            if not stat.S_ISREG(index_metadata.st_mode):
                raise MutationJournalError(
                    f"Git index must be a regular file, got {index}"
                )
            if index_metadata.st_nlink != 1:
                raise MutationJournalError(
                    f"Git index must not be hard-linked, got {index}"
                )
        index_exists = index_metadata is not None
        index_xattrs = (
            _xattr_inventory(index) if index_metadata is not None else {}
        )
        index_blob: dict[str, int | str] | None = None
        index_semantic_blobs: dict[str, dict[str, int | str]] = {}
        if index_exists:
            index_payload = index.read_bytes()
            write_atomic_bytes(journal_dir / "index", index_payload)
            index_blob = _capture_snapshot_blob_record(
                journal_dir,
                index_payload,
            )
            semantic_views = _index_semantic_views(root, index)
            hidden_index_paths = _hidden_index_paths(semantic_views[1])
            if hidden_index_paths and not _nested_gitlink_guard:
                raise MutationJournalError(
                    "Git index assume-unchanged/skip-worktree flags are "
                    "unsupported because they hide out-of-scope writes: "
                    f"{list(hidden_index_paths)!r}"
                )
            for name, payload in zip(
                ("index_stage", "index_flags_v", "index_flags_f"),
                semantic_views,
                strict=True,
            ):
                write_atomic_bytes(journal_dir / name, payload)
                index_semantic_blobs[name] = _capture_snapshot_blob_record(
                    journal_dir,
                    payload,
                )

        gitlinks = _gitlink_paths(root)
        gitlink_set = set(gitlinks)
        transforming_paths = tuple(
            path for path in transforming_paths if path not in gitlink_set
        )
        external_filter_paths = tuple(
            path for path in external_filter_paths if path not in gitlink_set
        )
        filtered_scope = sorted(
            filtered
            for filtered in external_filter_paths
            if any(
                filtered == authorized
                or filtered.startswith(authorized.rstrip("/") + "/")
                or authorized.startswith(filtered.rstrip("/") + "/")
                for authorized in normalized_scope
            )
        )
        if filtered_scope:
            raise MutationJournalError(
                "declared mutation scope includes externally filtered paths; "
                "exact capture cannot author their canonical stored image "
                f"without executing a driver: {filtered_scope!r}"
            )
        opaque_gitlink_roots = tuple(dict.fromkeys(
            _normalize_relative(root, path)
            for path in _opaque_gitlink_roots
        ))
        invalid_opaque_roots = sorted(
            path for path in opaque_gitlink_roots if path not in gitlinks
        )
        if invalid_opaque_roots:
            raise MutationJournalError(
                "opaque ancestor-guard roots are not Git links: "
                f"{invalid_opaque_roots!r}"
            )
        nested_scope = sorted({
            path
            for path in normalized_scope
            for gitlink in gitlinks
            if (
                path == gitlink
                or path.startswith(gitlink + "/")
                or gitlink.startswith(path.rstrip("/") + "/")
            )
        })
        if nested_scope:
            raise MutationJournalError(
                "declared mutation scope enters a Git submodule; nested "
                f"repositories require a separate transaction: {nested_scope!r}"
            )
        resolved_journal_root = journal_root.resolve()
        metadata_parent = resolved_journal_root.parent
        # A caller may place ``journal_root`` directly under the checkout.
        # Excluding its parent in that shape would mean excluding the entire
        # repository (rendered as ``.``), while failing to exclude it causes
        # rollback to delete its own index snapshot. Bound the exclusion to
        # the journal directory itself in this edge shape.
        metadata_roots = {
            resolved_journal_root
            if metadata_parent == root
            else metadata_parent
        }
        for parent in journal_root.resolve().parents:
            if parent.name == "runs":
                metadata_roots.add(parent.parent.resolve())
                break
        metadata_relatives: tuple[str, ...] = tuple(sorted(
            candidate.relative_to(root).as_posix()
            for candidate in metadata_roots
            if root in candidate.parents
        ))

        initialized_gitlinks = tuple(
            gitlink
            for gitlink in gitlinks
            if (root / gitlink / ".git").exists()
        )
        tracked_path_metadata = _tracked_path_metadata(
            root,
            gitlinks=gitlinks,
        )
        module_admin_roots = _module_admin_roots(root)
        modules_root = _git_common_dir(root) / "modules"
        initialized_module_admin_roots: set[str] = set()
        external_initialized_gitlinks: list[str] = []
        for gitlink in initialized_gitlinks:
            nested_common = _git_common_dir(root / gitlink)
            try:
                initialized_module_admin_roots.add(
                    nested_common.relative_to(modules_root).as_posix()
                )
            except ValueError:
                # Gitlinks may be populated from a separately cloned checkout
                # rather than absorbed beneath this superproject's modules
                # directory. Their dedicated child journal owns that external
                # admin root; the parent module namespace has nothing to map.
                external_initialized_gitlinks.append(gitlink)
        unsupported_module_roots = tuple(
            module
            for module in module_admin_roots
            if module not in initialized_module_admin_roots
        )
        cached_module_admin_roots = unsupported_module_roots
        cached_module_metadata: dict[str, dict[str, object]] = {}
        for module in cached_module_admin_roots:
            module_path = modules_root / module
            metadata = module_path.lstat()
            if (
                not stat.S_ISDIR(metadata.st_mode)
                or stat.S_ISLNK(metadata.st_mode)
            ):
                raise MutationJournalError(
                    f"cached Git module admin is aliased: {module_path}"
                )
            cached_module_metadata[module] = {
                "mode": stat.S_IMODE(metadata.st_mode),
                "device": metadata.st_dev,
                "inode": metadata.st_ino,
                "xattrs": _xattr_inventory(module_path),
            }
        cached_module_controls = _capture_cached_module_controls(
            journal_dir,
            modules_root,
            cached_module_admin_roots,
        )
        module_namespace_topology = _module_namespace_topology(
            root,
            guarded_roots=(
                *initialized_module_admin_roots,
                *cached_module_admin_roots,
            ),
            require_restore_control=True,
        )
        expected_connective_dirs = {
            parent.as_posix()
            for module in (
                *initialized_module_admin_roots,
                *cached_module_admin_roots,
            )
            for parent in PurePosixPath(module).parents
            if str(parent) not in {"", "."}
        }
        unsupported_module_topology = {
            path: metadata
            for path, metadata in module_namespace_topology.items()
            if (
                (
                    path == "."
                    and metadata.get("kind") not in {"directory", "missing"}
                )
                or (
                    path != "."
                    and (
                        path not in expected_connective_dirs
                        or metadata.get("kind") != "directory"
                    )
                )
            )
        }
        if unsupported_module_topology:
            raise MutationJournalError(
                "partial or unowned Git module namespace is unsupported by "
                "exact mutation rollback: "
                f"{sorted(unsupported_module_topology)[:10]!r}"
            )
        for gitlink in initialized_gitlinks:
            if gitlink in opaque_gitlink_roots:
                continue
            nested_root = root / gitlink
            if nested_root.is_symlink() or not nested_root.is_dir():
                raise MutationJournalError(
                    f"initialized Git submodule is aliased or not a directory: {gitlink}"
                )
            _reject_git_config_includes(nested_root)
            _reject_repository_filter_config(nested_root)
            dirty = _nested_clean_status(nested_root)
            if dirty and not _external_worktree_guard:
                raise MutationJournalError(
                    "initialized Git submodules must be clean before exact "
                    f"mutation rollback begins: {gitlink!r}"
                )

        def _workflow_owned(path: str) -> bool:
            return any(
                path == metadata or path.startswith(metadata + "/")
                for metadata in metadata_relatives
            )

        attribute_policy_paths = _attribute_policy_paths(root)
        baseline_dirty = tuple(sorted(
            path for path in _git_status_paths(root)
            if not _workflow_owned(path)
            and not any(
                path == opaque or path.startswith(opaque + "/")
                for opaque in opaque_gitlink_roots
            )
            and not (
                _external_worktree_guard
                and any(
                    path == gitlink or path.startswith(gitlink + "/")
                    for gitlink in initialized_gitlinks
                )
            )
        ))
        snapshot_roots = (
            set(baseline_dirty)
            | set(normalized_scope)
            | set(attribute_policy_paths)
            # Ambient clean/smudge drivers are deliberately unavailable to
            # journal-owned Git commands.  Always retain their materialized
            # worktree bytes physically: a canonical object binding proves
            # the index image, not the image an external driver produced.
            | set(external_filter_paths)
        )
        ignored_nested_vcs_roots = (
            _ignored_directory_roots_outside_authority(
                root,
                protected_paths=snapshot_roots,
            )
        )
        nested_admin_markers = _relevant_nested_vcs_markers(
            root,
            excluded_roots=(*metadata_relatives, *initialized_gitlinks),
            ignored_roots=ignored_nested_vcs_roots,
        )
        if nested_admin_markers:
            raise MutationJournalError(
                "worktree contains nested VCS administration unsupported by "
                f"exact mutation rollback: {nested_admin_markers!r}"
            )
        directory_excluded_roots = (
            *metadata_relatives,
            *initialized_gitlinks,
            *ignored_nested_vcs_roots,
        )
        active_authority = _active_workspace_mutation_authority(root)
        if active_authority is None:
            directory_root_fd, _directory_root_metadata = (
                _open_authority_directory(
                    root,
                    label="workspace directory baseline root",
                )
            )
        else:
            directory_root_fd = os.dup(active_authority.root_descriptor)
        try:
            bounded_directory_inventory = _bound_workspace_directory_inventory(
                directory_root_fd,
                excluded_roots=directory_excluded_roots,
                require_restore_control=True,
                logical_root=root,
            )
        finally:
            os.close(directory_root_fd)
        directory_modes = {
            relative: record.mode
            for relative, record in bounded_directory_inventory.items()
        }
        directory_xattrs = {
            relative: dict(record.xattrs)
            for relative, record in bounded_directory_inventory.items()
        }
        directory_identities = {
            relative: {
                "device": record.device,
                "inode": record.inode,
            }
            for relative, record in bounded_directory_inventory.items()
        }
        snapshot_paths = _walk_snapshot_paths(
            root,
            snapshot_roots,
            # A Git status entry naming a dirty submodule is a directory; do
            # not recursively copy that repository.  Explicit directory
            # scopes are recursive because their whole subtree is authorized
            # to mutate and must round-trip exactly.
            recursive_roots=recursive_scope,
        )
        raw_object_restore, transforming_snapshot_paths = (
            _raw_object_restore_bindings(
                root,
                transforming_paths,
                already_snapshotted=snapshot_paths,
            )
        )
        snapshot_paths.update(transforming_snapshot_paths)
        entries = {}
        for path in sorted(snapshot_paths):
            item = _capture_one(journal_dir, root, path)
            if (
                item["kind"] == "directory"
                and not any(
                    path == scope_root or path.startswith(scope_root + "/")
                    for scope_root in recursive_scope
                )
            ):
                raise MutationJournalError(
                    "pre-dirty nested repositories/submodules are unsupported; "
                    f"cannot snapshot opaque directory exactly: {path}"
                )
            entries[path] = item

        git_entry = _capture_git_entry(journal_dir, root)
        git_admin_dir = _git_dir(root)
        git_common_dir = _git_common_dir(root)
        git_admin_metadata = git_admin_dir.lstat()
        if (
            not stat.S_ISDIR(git_admin_metadata.st_mode)
            or stat.S_ISLNK(git_admin_metadata.st_mode)
        ):
            raise MutationJournalError(
                f"Git administrative root must be a real directory: {git_admin_dir}"
            )
        _assert_directory_restore_control(git_admin_dir, git_admin_metadata)
        ignore_policy = _capture_ignore_policy(journal_dir, root)
        attribute_policy = _capture_attribute_policy(
            journal_dir,
            root,
            attribute_policy_paths,
        )
        guard_status = (
            _nested_clean_status(
                root,
                excluded_roots=opaque_gitlink_roots,
            )
            if _nested_gitlink_guard else None
        )
        tracked_worktree_inventory = (
            _tracked_worktree_inventory(
                root,
                gitlinks=gitlinks,
                extra_paths=(
                    _git_status_paths(root)
                    if _nested_gitlink_guard else ()
                ),
            )
            if _nested_gitlink_guard else None
        )
        if tracked_worktree_inventory is not None and opaque_gitlink_roots:
            tracked_worktree_inventory = _structural_worktree_inventory(
                tracked_worktree_inventory
            )

        objects_root, object_inventory = _object_inventory(
            root,
            require_restore_control=True,
        )
        objects_root_metadata = objects_root.lstat()
        objects_root_mode = stat.S_IMODE(objects_root_metadata.st_mode)
        objects_root_xattrs = _xattr_inventory(objects_root)
        shared_object_store_allowed = (
            _nested_gitlink_guard or _superproject_worktree(root) is not None
        )
        unsupported_objects = sorted(
            path
            for path, metadata in object_inventory.items()
            if (
                metadata.get("kind") not in {"file", "directory"}
                or (
                    metadata.get("kind") == "file"
                    and metadata.get("nlink") != 1
                    and not shared_object_store_allowed
                )
            )
        )
        if unsupported_objects:
            raise MutationJournalError(
                "Git object inventory contains aliased or non-regular entries; "
                "shared/reference object stores are unsupported: "
                f"{unsupported_objects[:10]!r}"
            )
        if os.environ.get("GIT_ALTERNATE_OBJECT_DIRECTORIES"):
            raise MutationJournalError(
                "alternate Git object directories are unsupported"
            )
        alternates_file = objects_root / "info" / "alternates"
        if alternates_file.exists() and alternates_file.read_bytes().strip():
            raise MutationJournalError(
                "Git objects/info/alternates is unsupported"
            )
        shared_index = _git(
            root,
            "rev-parse",
            "--shared-index-path",
            check=False,
        ).decode().strip()
        if shared_index:
            raise MutationJournalError(
                f"split Git index is unsupported: {shared_index}"
            )
        refs_root = _refs_path(root)
        refs_tree = _capture_refs_tree(
            journal_dir,
            refs_root,
            require_restore_control=True,
        )
        refs_root_metadata = refs_root.lstat()
        refs_root_mode = stat.S_IMODE(refs_root_metadata.st_mode)
        refs_root_xattrs = _xattr_inventory(refs_root)
        log_refs_root = _git_control_path(root, "logs/refs")
        try:
            log_refs_metadata = log_refs_root.lstat()
        except FileNotFoundError:
            log_refs_metadata = None
        if log_refs_metadata is not None and (
            not stat.S_ISDIR(log_refs_metadata.st_mode)
            or stat.S_ISLNK(log_refs_metadata.st_mode)
        ):
            raise MutationJournalError(
                f"Git ref-log root must be a real directory: {log_refs_root}"
            )
        log_refs_tree = (
            _capture_refs_tree(
                journal_dir,
                log_refs_root,
                snapshot_name="git_ref_logs",
                require_restore_control=True,
            )
            if log_refs_metadata is not None
            else None
        )
        symbolic_head = _symbolic_head(root)
        control_files = _capture_control_files(
            journal_dir,
            root,
            symbolic_head,
        )
        auxiliary_git_trees, disabled_git_hooks = _capture_auxiliary_git_trees(
            journal_dir,
            root,
        )
        git_admin_topology = _capture_git_admin_topology(journal_dir, root)

        lineage = None
        if spec is not None:
            from assay.corpus.store import Corpus  # noqa: PLC0415

            lineage_corpus = Corpus(_originating_spec_dir(journal_root))
            try:
                persisted_spec, persisted_digest = (
                    lineage_corpus.get_spec_with_digest(int(spec.version))
                )
            except FileNotFoundError:
                # Standalone live parent transactions may deliberately keep
                # journals outside a Corpus run tree.  They can still own and
                # restore bytes in-process, but absent persisted raw authority
                # they receive no crash-time acceptance lineage and therefore
                # can never disarm a prepared keep after restart.
                pass
            else:
                if persisted_spec != spec:
                    raise MutationJournalError(
                        "journal Spec differs from its persisted manifest "
                        "authority"
                    )

                lineage = {
                    "spec_version": int(spec.version),
                    "spec_hash": str(persisted_digest),
                    "root": (
                        str(spec.root)
                        if spec.root is not None
                        else None
                    ),
                    "implementation_refs": [
                        str(ref)
                        for ref in getattr(spec, "implementation_refs", ())
                    ],
                    "lifecycle_event_refs": [
                        str(ref)
                        for ref in getattr(spec, "lifecycle_event_refs", ())
                    ],
                }

        registry_marker = registry_path / f"{transaction_id}.json"
        manifest = {
            "schema": _SCHEMA,
            "transaction_id": transaction_id,
            "parent_transaction_id": parent_transaction_id,
            "created_ns": time.time_ns(),
            "sequence": sequence,
            "cwd": str(root),
            "worktree_root": str(root),
            "core_worktree_config": core_worktree_config,
            "head": _head(root),
            "head_symbolic_ref": symbolic_head,
            "refs": _refs_snapshot(root),
            "refs_path": str(refs_root),
            "refs_resolved_path": str(refs_root.resolve()),
            "refs_root_mode": refs_root_mode,
            "refs_root_device": refs_root_metadata.st_dev,
            "refs_root_inode": refs_root_metadata.st_ino,
            "refs_root_xattrs": refs_root_xattrs,
            "refs_tree": refs_tree,
            "log_refs_path": str(log_refs_root),
            "log_refs_exists": log_refs_metadata is not None,
            "log_refs_root_mode": (
                stat.S_IMODE(log_refs_metadata.st_mode)
                if log_refs_metadata is not None else None
            ),
            "log_refs_root_device": (
                log_refs_metadata.st_dev
                if log_refs_metadata is not None else None
            ),
            "log_refs_root_inode": (
                log_refs_metadata.st_ino
                if log_refs_metadata is not None else None
            ),
            "log_refs_root_xattrs": (
                _xattr_inventory(log_refs_root)
                if log_refs_metadata is not None else {}
            ),
            "log_refs_tree": log_refs_tree,
            "control_files": control_files,
            "auxiliary_git_trees": auxiliary_git_trees,
            "disabled_git_hooks": disabled_git_hooks,
            "git_admin_topology": git_admin_topology,
            "authority_lock": authority_lock,
            "registered_worktrees": list(registered_worktrees),
            "absent_registered_worktrees": list(absent_peer_worktrees),
            "absent_worktree_admin_controls": absent_worktree_admin_controls,
            "worktree_namespace_topology": worktree_namespace_topology,
            "guarded_worktree_admin_roots": sorted(
                guarded_worktree_admin_roots
            ),
            "module_admin_roots": list(module_admin_roots),
            "initialized_module_admin_roots": sorted(
                initialized_module_admin_roots
            ),
            "external_initialized_gitlinks": external_initialized_gitlinks,
            "cached_module_admin_roots": list(cached_module_admin_roots),
            "cached_module_metadata": cached_module_metadata,
            "cached_module_controls": cached_module_controls,
            "module_namespace_topology": module_namespace_topology,
            "git_entry": git_entry,
            "git_admin_dir": str(git_admin_dir),
            "git_common_dir": str(git_common_dir),
            "git_admin_dir_mode": stat.S_IMODE(git_admin_metadata.st_mode),
            "ignore_policy": ignore_policy,
            "attribute_policy": attribute_policy,
            "pre_capture_attribute_changes": [],
            "pre_capture_attribute_admin_changed": False,
            _DEFERRED_RECURSIVE_ATTRIBUTE_POLICY_KEY: {},
            _RESTORED_WORKSPACE_DIRECTORY_AUTHORITY_KEY: {},
            _RESTORED_TRACKED_ENTRY_AUTHORITY_KEY: {},
            "slice_id": slice_id,
            "state": "invoking",
            WRITER_EPOCH_MANIFEST_KEY: initial_writer_epoch_record(),
            # Unlike the operational registry projection, this family claim
            # is monotonic until the first epoch arm.  A child disappearing or
            # being acknowledged cannot shrink the authority used to decide
            # whether generation zero is safe.
            "writer_epoch_family": [transaction_id],
            "writer_epoch_family_parents": {
                transaction_id: parent_transaction_id,
            },
            "writer_epoch_terminal_proofs": {},
            # A hosted delete first publishes a durable, exact mapping from
            # its declared source root to a private sibling quarantine.  The
            # mapping survives loss of the complete parent process and is
            # normalized before ordinary writer-epoch recovery is attempted.
            _PENDING_DELETE_QUARANTINES_KEY: [],
            "scope": list(normalized_scope),
            "recursive_scope": sorted(recursive_scope),
            "scope_escapes": [],
            "baseline_dirty": list(baseline_dirty),
            "transforming_paths": list(transforming_paths),
            "external_filter_paths": list(external_filter_paths),
            "raw_object_restore": raw_object_restore,
            "entries": entries,
            "index_path": str(index),
            "index_exists": index_exists,
            "index_mode": (
                stat.S_IMODE(index_metadata.st_mode) if index_metadata else None
            ),
            "index_device": (
                index_metadata.st_dev if index_metadata else None
            ),
            "index_uid": index_metadata.st_uid if index_metadata else None,
            "index_gid": index_metadata.st_gid if index_metadata else None,
            "index_xattrs": index_xattrs,
            "index_blob": index_blob,
            "index_semantic_blobs": index_semantic_blobs,
            "index_semantic_views": bool(index_exists),
            "objects_path": str(objects_root),
            "objects_resolved_path": str(objects_root.resolve()),
            "objects_root_mode": objects_root_mode,
            "objects_root_device": objects_root_metadata.st_dev,
            "objects_root_inode": objects_root_metadata.st_ino,
            "objects_root_xattrs": objects_root_xattrs,
            "object_inventory": object_inventory,
            "metadata_roots": [str(path) for path in sorted(metadata_roots)],
            "metadata_relatives": list(metadata_relatives),
            "gitlinks": list(gitlinks),
            "initialized_gitlinks": list(initialized_gitlinks),
            "opaque_gitlink_roots": list(opaque_gitlink_roots),
            "ignored_nested_vcs_roots": list(ignored_nested_vcs_roots),
            "directory_modes": directory_modes,
            "directory_xattrs": directory_xattrs,
            "directory_identities": directory_identities,
            "nested_gitlink_guard": _nested_gitlink_guard,
            "external_worktree_guard": _external_worktree_guard,
            "guard_status": guard_status.hex() if guard_status is not None else None,
            "tracked_worktree_inventory": tracked_worktree_inventory,
            "tracked_path_metadata": tracked_path_metadata,
            "expected_implementation": None,
            "expected_lifecycle": None,
            "lineage": lineage,
            "registry_marker": str(registry_marker),
            "registry_directory": str(registry_path),
            "registry_directory_mode": stat.S_IMODE(
                registry_metadata.st_mode
            ),
            "registry_directory_device": registry_metadata.st_dev,
            "registry_directory_inode": registry_metadata.st_ino,
            "registry_baseline_entries": list(registry_baseline_entries),
        }
        write_atomic_json(journal_dir / _MANIFEST, manifest)
        registry_payload = {
            "schema": _SCHEMA,
            "transaction_id": transaction_id,
            "cwd": str(root),
            "spec_dir": str(_originating_spec_dir(journal_root)),
            "journal_dir": str(journal_dir.resolve()),
        }
        registry_bytes = json.dumps(
            registry_payload,
            indent=2,
            default=str,
        ).encode("utf-8")
        write_atomic_bytes(journal_dir / "registry_marker", registry_bytes)
        _assert_bound_workspace_registry_identity(
            root,
            registry_fd,
            registry_metadata,
            label="mutation-journal registry before marker publication",
        )
        _write_bound_registry_marker_at(
            registry_fd,
            transaction_id,
            registry_bytes,
            expected_baseline_entries=registry_baseline_entries,
        )
        _register_live(transaction_id)
        journal = cls(journal_dir, manifest)
        registration_complete = False
        try:
            _register_live_journal(journal)
            registration_complete = True
            for nested_sequence, gitlink in enumerate(
                (
                    path for path in initialized_gitlinks
                    if path not in opaque_gitlink_roots
                ),
                start=1,
            ):
                cls.begin(
                    cwd=root / gitlink,
                    journal_root=journal_dir / "nested_mutations",
                    slice_id=f"{slice_id}::gitlink::{gitlink}",
                    scope=(),
                    sequence=nested_sequence,
                    spec=None,
                    parent_transaction_id=transaction_id,
                    _nested_gitlink_guard=True,
                    _external_worktree_guard=_external_worktree_guard,
                    _suppress_superproject_guard=True,
                )
            all_peer_roots = tuple(dict.fromkeys((
                str(root),
                *(str(Path(path).resolve()) for path in peer_worktrees),
                *(str(Path(path).resolve()) for path in absent_peer_worktrees),
                *(str(Path(path).resolve()) for path in _registered_peer_roots),
            )))
            for peer_offset, rendered_peer in enumerate(
                peer_worktrees,
                start=1,
            ):
                cls.begin(
                    cwd=Path(rendered_peer).resolve(),
                    journal_root=journal_dir / "nested_mutations",
                    slice_id=(
                        f"{slice_id}::linked-peer-worktree::{peer_offset}"
                    ),
                    scope=(),
                    sequence=len(initialized_gitlinks) + peer_offset,
                    spec=None,
                    parent_transaction_id=transaction_id,
                    _nested_gitlink_guard=True,
                    _external_worktree_guard=True,
                    _registered_peer_roots=tuple(
                        path
                        for path in all_peer_roots
                        if Path(path).resolve() != Path(rendered_peer).resolve()
                    ),
                    _suppress_peer_guards=True,
                )
            superproject = (
                None if _suppress_superproject_guard
                else _superproject_worktree(root)
            )
            if superproject is not None:
                try:
                    opaque_child = root.relative_to(superproject).as_posix()
                except ValueError as exc:
                    raise MutationJournalError(
                        "submodule worktree escapes reported superproject"
                    ) from exc
                cls.begin(
                    cwd=superproject,
                    journal_root=journal_dir / "nested_mutations",
                    slice_id=f"{slice_id}::ancestor-superproject",
                    scope=(),
                    sequence=(
                        len(initialized_gitlinks) + len(peer_worktrees) + 1
                    ),
                    spec=None,
                    parent_transaction_id=transaction_id,
                    _nested_gitlink_guard=True,
                    _external_worktree_guard=True,
                    _opaque_gitlink_roots=(opaque_child,),
                )
        except BaseException as primary_error:
            if not registration_complete:
                journal._setup_registration_pending = True
                try:
                    _retain_published_setup_journal(journal)
                except BaseException as registration_error:
                    raise MutationJournalCleanupError(
                        owner=journal,
                        primary_error=primary_error,
                        cleanup_error=registration_error,
                    ) from primary_error
            try:
                journal.retry_cleanup()
            except BaseException as cleanup_error:
                if journal.cleanup_pending:
                    raise MutationJournalCleanupError(
                        owner=journal,
                        primary_error=primary_error,
                        cleanup_error=cleanup_error,
                    ) from primary_error
                raise primary_error from cleanup_error
            if journal.cleanup_pending:
                raise MutationJournalCleanupError(
                    owner=journal,
                    primary_error=primary_error,
                ) from primary_error
            raise
        return journal

    @classmethod
    def load(cls, journal_dir: Path) -> "WorkspaceMutationJournal":
        manifest = json.loads((journal_dir / _MANIFEST).read_text())
        if manifest.get("schema") != _SCHEMA:
            raise MutationJournalError(
                f"unsupported mutation journal schema at {journal_dir}"
            )
        return cls(journal_dir, manifest)

    def _nested_journals(self) -> tuple["WorkspaceMutationJournal", ...]:
        root = self.journal_dir / "nested_mutations"
        try:
            root_metadata = root.lstat()
        except FileNotFoundError:
            return ()
        if not stat.S_ISDIR(root_metadata.st_mode) or stat.S_ISLNK(
            root_metadata.st_mode
        ):
            raise MutationJournalError(
                f"nested mutation journal root is aliased: {root}"
            )
        root_fd, opened_root = _open_authority_directory(
            root,
            label="nested mutation journal root",
        )
        journals: list[WorkspaceMutationJournal] = []
        try:
            names = _bounded_directory_names(
                root_fd,
                label="nested mutation journal family",
                max_entries=_MUTATION_JOURNAL_MAX_NESTED_MEMBERS,
            )
            for name in names:
                if name in {"", ".", ".."} or "/" in name:
                    raise MutationJournalError(
                        "nested mutation journal member name is malformed"
                    )
                child_fd: int | None = None
                manifest_fd: int | None = None
                try:
                    child_before = os.stat(
                        name,
                        dir_fd=root_fd,
                        follow_symlinks=False,
                    )
                    child_fd = os.open(
                        name,
                        os.O_RDONLY
                        | getattr(os, "O_CLOEXEC", 0)
                        | getattr(os, "O_DIRECTORY", 0)
                        | getattr(os, "O_NOFOLLOW", 0),
                        dir_fd=root_fd,
                    )
                    child_opened = os.fstat(child_fd)
                    if (
                        not stat.S_ISDIR(child_before.st_mode)
                        or stat.S_ISLNK(child_before.st_mode)
                        or (child_before.st_dev, child_before.st_ino)
                        != (child_opened.st_dev, child_opened.st_ino)
                    ):
                        raise MutationJournalError(
                            "nested mutation journal member changed identity"
                        )
                    manifest_before = os.stat(
                        _MANIFEST,
                        dir_fd=child_fd,
                        follow_symlinks=False,
                    )
                    if (
                        not stat.S_ISREG(manifest_before.st_mode)
                        or stat.S_ISLNK(manifest_before.st_mode)
                        or manifest_before.st_nlink != 1
                        or manifest_before.st_size
                        > _MUTATION_JOURNAL_MAX_MANIFEST_BYTES
                    ):
                        raise MutationJournalError(
                            "nested mutation journal manifest is unsafe"
                        )
                    manifest_fd = os.open(
                        _MANIFEST,
                        os.O_RDONLY
                        | getattr(os, "O_CLOEXEC", 0)
                        | getattr(os, "O_NOFOLLOW", 0)
                        | getattr(os, "O_NONBLOCK", 0),
                        dir_fd=child_fd,
                    )
                    manifest_opened = os.fstat(manifest_fd)
                    if (
                        not stat.S_ISREG(manifest_opened.st_mode)
                        or (manifest_before.st_dev, manifest_before.st_ino)
                        != (manifest_opened.st_dev, manifest_opened.st_ino)
                    ):
                        raise MutationJournalError(
                            "nested mutation journal manifest changed while "
                            "opening"
                        )
                    chunks: list[bytes] = []
                    observed = 0
                    while True:
                        chunk = os.read(manifest_fd, 1024 * 1024)
                        if not chunk:
                            break
                        observed += len(chunk)
                        if observed > _MUTATION_JOURNAL_MAX_MANIFEST_BYTES:
                            raise MutationJournalError(
                                "nested mutation journal manifest exceeds its "
                                "size ceiling"
                            )
                        chunks.append(chunk)
                    manifest_finished = os.fstat(manifest_fd)
                    manifest_after = os.stat(
                        _MANIFEST,
                        dir_fd=child_fd,
                        follow_symlinks=False,
                    )
                    child_after = os.stat(
                        name,
                        dir_fd=root_fd,
                        follow_symlinks=False,
                    )
                    if any(
                        getattr(manifest_opened, field)
                        != getattr(manifest_finished, field)
                        for field in _SETTLEMENT_STABLE_STAT_FIELDS
                    ) or any(
                        getattr(manifest_opened, field)
                        != getattr(manifest_after, field)
                        for field in _SETTLEMENT_STABLE_STAT_FIELDS
                    ) or (
                        child_before.st_dev,
                        child_before.st_ino,
                    ) != (child_after.st_dev, child_after.st_ino):
                        raise MutationJournalError(
                            "nested mutation journal changed during load"
                        )
                    manifest = json.loads(b"".join(chunks).decode("utf-8"))
                    if not isinstance(manifest, dict) or manifest.get(
                        "schema"
                    ) != _SCHEMA:
                        raise MutationJournalError(
                            "nested mutation journal schema is unsupported"
                        )
                    journals.append(type(self)(root / name, manifest))
                except MutationJournalError:
                    raise
                except (OSError, ValueError, json.JSONDecodeError) as exc:
                    raise MutationJournalError(
                        f"nested mutation journal is unreadable: {root / name}: "
                        f"{exc}"
                    ) from exc
                finally:
                    if manifest_fd is not None:
                        os.close(manifest_fd)
                    if child_fd is not None:
                        os.close(child_fd)
            final_names = _bounded_directory_names(
                root_fd,
                label="nested mutation journal family",
                max_entries=_MUTATION_JOURNAL_MAX_NESTED_MEMBERS,
            )
            finished_root = os.fstat(root_fd)
            if names != final_names or (
                opened_root.st_dev,
                opened_root.st_ino,
            ) != (finished_root.st_dev, finished_root.st_ino):
                raise MutationJournalError(
                    "nested mutation journal family changed during discovery"
                )
            _assert_authority_directory_binding(
                root,
                root_fd,
                opened_root,
                label="nested mutation journal root",
            )
        finally:
            os.close(root_fd)
        return tuple(sorted(
            journals,
            key=lambda item: (item.created_ns, item.transaction_id),
        ))

    def _allowed_registry_entries(self) -> set[str]:
        allowed = set(self._manifest.get("registry_baseline_entries", ()))
        allowed.add(f"{self.transaction_id}.json")
        allowed.update(
            f"{transaction_id}.json"
            for transaction_id in self._manifest.get(
                "registry_transaction_family", ()
            )
        )

        def add_nested(journal: "WorkspaceMutationJournal") -> None:
            allowed.add(f"{journal.transaction_id}.json")
            for child in journal._nested_journals():
                add_nested(child)

        for nested in self._nested_journals():
            add_nested(nested)
        return allowed

    def _required_registry_entries(self) -> set[str]:
        return {
            *self._manifest.get("registry_baseline_entries", ()),
            f"{self.transaction_id}.json",
        }

    def _assert_registry_topology_unchanged(self) -> None:
        marker = self._registry_marker()
        if marker is None:
            return
        with self._bound_registry_directory() as registry_fd:
            names = _bounded_directory_names(
                registry_fd,
                label="mutation-journal registry topology",
                max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
            )
            observed = set(names)
            if (
                not self._required_registry_entries().issubset(observed)
                or not observed.issubset(self._allowed_registry_entries())
            ):
                raise MutationJournalError(
                    f"slice {self.slice_id} changed mutation registry topology"
                )
            for name in names:
                _read_bound_regular_entry(
                    registry_fd,
                    name,
                    label=f"mutation registry entry {name!r}",
                    max_bytes=_CONTROL_FILE_MAX_BYTES,
                )
            if names != _bounded_directory_names(
                registry_fd,
                label="mutation-journal registry topology",
                max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
            ):
                raise MutationJournalError(
                    "mutation registry changed during topology inspection"
                )

    def _restore_registry_topology(self) -> None:
        marker = self._registry_marker()
        if marker is None:
            return
        allowed = self._allowed_registry_entries()
        with self._bound_registry_directory() as registry_fd:
            initial_names = _bounded_directory_names(
                registry_fd,
                label="mutation-journal registry restore",
                max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
            )
            removed_names: set[str] = set()
            for name in initial_names:
                if name in allowed:
                    continue
                try:
                    metadata = os.stat(
                        name,
                        dir_fd=registry_fd,
                        follow_symlinks=False,
                    )
                except FileNotFoundError as exc:
                    raise MutationJournalError(
                        "mutation registry changed during topology restore"
                    ) from exc
                if stat.S_ISDIR(metadata.st_mode) and not stat.S_ISLNK(
                    metadata.st_mode
                ):
                    directory_fd, opened = _open_authority_directory_at(
                        registry_fd,
                        name,
                        label=f"mutation registry addition {name!r}",
                    )
                    try:
                        _remove_bound_directory_tree(
                            registry_fd,
                            name,
                            directory_fd,
                            opened,
                        )
                    finally:
                        os.close(directory_fd)
                    removed_names.add(name)
                    continue
                if (
                    not stat.S_ISREG(metadata.st_mode)
                    or stat.S_ISLNK(metadata.st_mode)
                    or metadata.st_nlink != 1
                ):
                    raise MutationJournalError(
                        "mutation registry topology contains an unsafe "
                        f"addition: {name!r}"
                    )
                _remove_bound_regular_entry(
                    registry_fd,
                    name,
                    label=f"mutation registry addition {name!r}",
                    expected_metadata=metadata,
                )
                removed_names.add(name)
            final_names = _bounded_directory_names(
                registry_fd,
                label="mutation-journal registry restore",
                max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
            )
            if set(final_names) != set(initial_names).difference(removed_names):
                raise MutationJournalError(
                    "mutation registry changed during topology restore"
                )

    def _assert_nested_journals_exact(self) -> None:
        for journal in self._nested_journals():
            journal.assert_exact_baseline()

    def _assert_git_entry_unchanged(self) -> None:
        self._assert_authority_lock_unchanged()
        cwd = self._bound_workspace_cwd()
        expected_worktree = self._bound_manifest_path(
            str(self._manifest.get("worktree_root", self._manifest["cwd"]))
        )
        if (
            not self._bound_paths_same(_git_worktree_root(cwd), expected_worktree)
            or _git_config(cwd, "core.worktree")
            != self._manifest.get("core_worktree_config")
        ):
            raise MutationJournalError(
                f"slice {self.slice_id} changed Git worktree binding"
            )
        expected = self._manifest.get("git_entry")
        if expected is None:
            return
        expected_admin = self._manifest.get("git_admin_dir")
        if expected_admin is not None:
            admin = _git_dir(cwd)
            metadata = admin.lstat()
            if (
                not self._bound_paths_same(admin, expected_admin)
                or not stat.S_ISDIR(metadata.st_mode)
                or stat.S_ISLNK(metadata.st_mode)
                or stat.S_IMODE(metadata.st_mode)
                != int(self._manifest["git_admin_dir_mode"])
            ):
                raise MutationJournalError(
                    f"slice {self.slice_id} moved or changed Git admin root"
                )
        # ``cwd`` may intentionally be a held ``/proc/self/fd/<n>`` alias.
        # Namespace binding starts from the capture-time lexical checkout and
        # reaches the same inode through the held root descriptor.
        path = Path(self._manifest["cwd"]) / ".git"
        try:
            metadata, xattrs = self._inspect_bound_git_admin_entry(
                path,
                label="workspace Git administration entry",
            )
        except MutationJournalError as exc:
            raise MutationJournalError(
                f"slice {self.slice_id} removed or aliased Git "
                "administration entry"
            ) from exc
        kind = expected["kind"]
        if kind == "directory":
            if (
                not stat.S_ISDIR(metadata.st_mode)
                or stat.S_ISLNK(metadata.st_mode)
                or (metadata.st_dev, metadata.st_ino)
                != (int(expected["device"]), int(expected["inode"]))
                or stat.S_IMODE(metadata.st_mode) != int(expected["mode"])
                or xattrs != expected.get("xattrs", {})
            ):
                raise MutationJournalError(
                    f"slice {self.slice_id} moved or aliased Git administration"
                )
            return
        expected_payload = self._read_snapshot_blob_record(
            expected,
            label="Git indirection assertion",
        )
        payload, opened, opened_xattrs = self._read_bound_git_admin_file(
            path,
            label="workspace Git indirection entry",
            max_bytes=max(len(expected_payload), 1),
        )
        if (
            not stat.S_ISREG(metadata.st_mode)
            or metadata.st_nlink != 1
            or stat.S_IMODE(metadata.st_mode) != int(expected["mode"])
            or (opened.st_dev, opened.st_ino)
            != (metadata.st_dev, metadata.st_ino)
            or opened_xattrs != expected.get("xattrs", {})
            or payload != expected_payload
        ):
            raise MutationJournalError(
                f"slice {self.slice_id} changed Git indirection file"
            )

    def _assert_authority_lock_unchanged(self) -> None:
        expected = self._manifest.get("authority_lock")
        if expected is None:
            return
        authority = _active_workspace_mutation_authority(
            Path(self._manifest["cwd"])
        )
        if authority is not None:
            common_metadata = os.fstat(authority.common_descriptor)
            metadata = os.fstat(authority.lock_descriptor)
            root_metadata = os.fstat(authority.root_descriptor)
            if (
                not stat.S_ISDIR(root_metadata.st_mode)
                or (
                    expected.get("root_device") is not None
                    and root_metadata.st_dev != int(expected["root_device"])
                )
                or (
                    expected.get("root_inode") is not None
                    and root_metadata.st_ino != int(expected["root_inode"])
                )
                or not stat.S_ISDIR(common_metadata.st_mode)
                or common_metadata.st_dev != int(expected["common_device"])
                or common_metadata.st_ino != int(expected["common_inode"])
                or stat.S_IMODE(common_metadata.st_mode)
                != int(expected["common_mode"])
                or not stat.S_ISREG(metadata.st_mode)
                or metadata.st_dev != int(expected["device"])
                or metadata.st_ino != int(expected["inode"])
                or metadata.st_nlink != int(expected["nlink"])
                or stat.S_IMODE(metadata.st_mode) != int(expected["mode"])
                or _bound_descriptor_xattr_inventory(
                    authority.lock_descriptor,
                    label="workspace authority lock",
                )
                != expected.get("xattrs", {})
            ):
                raise MutationJournalError(
                    "held workspace authority differs from journal authority"
                )
            return
        common_dir = Path(str(expected["common_dir"]))
        path = Path(str(expected["path"]))
        common_record = {
            "device": expected.get("common_device"),
            "inode": expected.get("common_inode"),
        }
        try:
            with self._open_bound_git_admin_directory(
                common_dir,
                record=common_record,
                label="workspace authority common directory",
            ) as common_fd:
                common_metadata = os.fstat(common_fd)
                metadata, xattrs = self._inspect_bound_git_admin_entry(
                    path,
                    label="workspace authority lock",
                )
                if (
                    not stat.S_ISDIR(common_metadata.st_mode)
                    or stat.S_IMODE(common_metadata.st_mode)
                    != int(expected["common_mode"])
                    or not stat.S_ISREG(metadata.st_mode)
                    or metadata.st_dev != int(expected["device"])
                    or metadata.st_ino != int(expected["inode"])
                    or metadata.st_nlink != int(expected["nlink"])
                    or stat.S_IMODE(metadata.st_mode)
                    != int(expected["mode"])
                    or xattrs != expected.get("xattrs", {})
                ):
                    raise MutationJournalError(
                        "workspace authority lock inode or common dir changed; "
                        "refusing unsafe repair"
                    )
        except MutationJournalError:
            raise
        except OSError as exc:
            raise MutationJournalError(
                "workspace authority lock or common dir disappeared"
            ) from exc

    def _assert_tracked_path_metadata_unchanged(self) -> None:
        expected = self._manifest.get("tracked_path_metadata")
        if expected is None:
            return
        cwd = self._bound_workspace_cwd()
        status_paths = _git_status_paths(cwd)
        scope = tuple(self._manifest.get("scope", ()))
        recursive_scope = set(self._manifest.get("recursive_scope", ()))

        def git_visible(relative: str) -> bool:
            return any(
                relative == changed or relative.startswith(changed + "/")
                for changed in status_paths
            )

        def authorized(relative: str) -> bool:
            return any(
                relative == root
                or (
                    root in recursive_scope
                    and relative.startswith(root.rstrip("/") + "/")
                )
                for root in scope
            )

        changes: list[str] = []
        for relative, baseline in expected.items():
            current = _tracked_path_metadata_for_path(cwd, relative)
            restored_observation = (
                self._restored_tracked_metadata_observations.get(relative)
            )
            if restored_observation is not None:
                if current != restored_observation:
                    changes.append(relative)
                continue
            if self.state == "rolled_back":
                # A completed rollback may have installed a fresh inode.  A
                # containing family journal can subsequently reinstall that
                # same baseline before it asks this terminal child to prove
                # its exact state.  The parent carries the live inode grant;
                # this child must still enforce every Git-invisible property,
                # but cannot require its superseded volatile inode/timestamp
                # observation after reload.
                stable_fields = {
                    "kind",
                    "mode",
                    "nlink",
                    "xattrs",
                    "size",
                    "target",
                }
                if {
                    key: value
                    for key, value in current.items()
                    if key in stable_fields
                } == {
                    key: value
                    for key, value in baseline.items()
                    if key in stable_fields
                }:
                    continue
            if current == baseline:
                continue
            if current.get("kind") != "missing" and current.get("nlink") != 1:
                changes.append(relative)
                continue
            # A scoped cleanup can intentionally turn a baseline-dirty path
            # back into its HEAD image. Such a path disappears from current
            # ``git status`` even though the transaction explicitly owns it.
            # Scope authorizes Git-visible content/type/executable-bit
            # changes; link-count, xattr, and non-executable mode checks below
            # remain fail-closed.
            if git_visible(relative) or authorized(relative):
                baseline_kind = baseline.get("kind")
                current_kind = current.get("kind")
                if baseline_kind != current_kind:
                    # File/symlink/deletion transitions are represented by
                    # Git and remain within the declared write surface.
                    continue
                if baseline.get("xattrs", {}) != current.get("xattrs", {}):
                    changes.append(relative)
                    continue
                if baseline_kind == "file":
                    baseline_mode = int(baseline["mode"])
                    current_mode = int(cast(int | str, current["mode"]))
                    if (baseline_mode & ~0o111) == (current_mode & ~0o111):
                        continue
                elif baseline_kind == "symlink":
                    # Symlink targets are Git-visible; their lstat mode is not
                    # portably mutable on supported POSIX checkouts.
                    if baseline.get("mode") == current.get("mode"):
                        continue
            changes.append(relative)
        if changes:
            raise MutationJournalError(
                f"slice {self.slice_id} changed tracked path type, link count, "
                f"or Git-invisible mode: {sorted(changes)[:10]!r}"
            )

    def _assert_cached_module_controls_unchanged(self) -> None:
        cached_metadata = self._manifest.get("cached_module_metadata", {})
        for record in self._manifest.get("cached_module_controls", ()):
            root = self._bound_manifest_path(str(record["root"]))
            relative_root = str(record["relative_root"])
            root_record = cached_metadata.get(relative_root)
            if not isinstance(root_record, Mapping):
                raise MutationJournalError(
                    "cached module root authority is malformed"
                )
            entries = {
                **record.get("entries", {}),
                **record.get("payload_roots", {}),
            }
            if not self._bound_git_admin_tree_matches(
                root,
                record=root_record,
                entries=entries,
                label=f"cached module controls {relative_root}",
                opaque_roots=record.get("payload_roots", {}).keys(),
            ):
                raise MutationJournalError(
                    f"slice {self.slice_id} changed cached module controls {root}"
                )

    def _assert_absent_worktree_admin_controls_unchanged(self) -> None:
        for record in self._manifest.get(
            "absent_worktree_admin_controls", ()
        ):
            root = self._bound_manifest_path(str(record["root"]))
            if (
                not self._bound_git_admin_tree_matches(
                    root,
                    record=record,
                    entries=record["entries"],
                    label=f"missing-worktree admin {record.get('name')}",
                )
            ):
                raise MutationJournalError(
                    f"slice {self.slice_id} changed missing-worktree admin {root}"
                )

    def _restore_absent_worktree_admin_controls(self) -> None:
        for record in self._manifest.get(
            "absent_worktree_admin_controls", ()
        ):
            self._restore_bound_git_admin_tree(
                str(record["root"]),
                exists=True,
                record=record,
                entries=record.get("entries", {}),
                label=f"missing-worktree admin {record.get('name')}",
            )

    def _restore_cached_module_controls(self) -> None:
        cached_metadata = self._manifest.get("cached_module_metadata", {})
        for record in self._manifest.get("cached_module_controls", ()):
            relative_root = str(record["relative_root"])
            expected_root = cached_metadata[relative_root]
            expected_payloads = record.get("payload_roots", {})
            if not isinstance(expected_payloads, Mapping):
                raise MutationJournalError(
                    "cached module payload-root manifest is malformed"
                )
            entries = dict(record.get("entries", {}))
            # Cached module roots and opaque payload roots carry bytes that
            # Crucible deliberately did not snapshot.  Prove every such inode
            # before any control-file mutation; absence or substitution is a
            # retained-journal failure, never permission to recreate it empty.
            with self._open_bound_git_admin_directory(
                str(record["root"]),
                record=expected_root,
                label=f"cached module root {relative_root}",
            ):
                pass
            for name, payload_record in expected_payloads.items():
                if name in entries or not isinstance(payload_record, Mapping):
                    raise MutationJournalError(
                        "cached module control/payload authority overlaps"
                    )
                metadata, xattrs = self._inspect_bound_git_admin_entry(
                    Path(str(record["root"])) / str(name),
                    label=f"cached module payload {relative_root}/{name}",
                )
                if (
                    not stat.S_ISDIR(metadata.st_mode)
                    or stat.S_ISLNK(metadata.st_mode)
                    or (metadata.st_dev, metadata.st_ino)
                    != (
                        payload_record.get("device"),
                        payload_record.get("inode"),
                    )
                    or stat.S_IMODE(metadata.st_mode)
                    != payload_record.get("mode")
                    or xattrs != payload_record.get("xattrs", {})
                ):
                    raise MutationJournalError(
                        "cached module opaque payload authority changed: "
                        f"{relative_root}/{name}"
                    )
                entries[str(name)] = dict(payload_record)
            self._restore_bound_git_admin_tree(
                str(record["root"]),
                exists=True,
                record=expected_root,
                entries=entries,
                label=f"cached module controls {relative_root}",
                opaque_roots=tuple(str(name) for name in expected_payloads),
            )

    def _validated_active_parent_handoff_paths(
        self,
        rendered_paths: tuple[str, ...],
    ) -> frozenset[str]:
        """Authenticate an explicit, disjoint immediate-parent path grant."""

        if not rendered_paths:
            return frozenset()
        if self.parent_transaction_id is None:
            raise MutationJournalError(
                "retained parent paths require an immediate live parent"
            )
        if any(not isinstance(path, str) for path in rendered_paths):
            raise MutationJournalError(
                "retained parent paths contain a non-string path"
            )
        if len(set(rendered_paths)) != len(rendered_paths):
            raise MutationJournalError(
                "retained parent paths contain duplicate authority"
            )
        normalized: list[str] = []
        for rendered in rendered_paths:
            if _settlement_relative_path(rendered) != rendered:
                raise MutationJournalError(
                    f"retained parent path is malformed: {rendered!r}"
                )
            normalized.append(rendered)

        logical_cwd = Path(self._manifest["cwd"])
        family = validated_live_parent_writer_epoch_family(
            self.parent_transaction_id,
            cwd=logical_cwd,
        )
        family_by_id = {member.transaction_id: member for member in family}
        parent = _require_live_parent_transaction(self.parent_transaction_id)
        if (
            family_by_id.get(self.transaction_id) is not self
            or family_by_id.get(parent.transaction_id) is not parent
            or self.parent_transaction_id != parent.transaction_id
        ):
            raise MutationJournalError(
                "retained parent path lineage is not the exact live family"
            )
        family_ids = set(family_by_id)
        with _LIVE_TRANSACTIONS_LOCK:
            if any(
                _LIVE_JOURNAL_OBJECTS.get(transaction_id) is not member
                or transaction_id not in _LIVE_TRANSACTIONS
                or not member.active
                for transaction_id, member in family_by_id.items()
            ):
                raise MutationJournalError(
                    "retained parent path family changed during validation"
                )
            failed = family_ids.intersection(_FAILED_LIVE_TRANSACTIONS)
            for member in family:
                raw_failed = member._manifest.get("failed_family_members", ())
                if not isinstance(raw_failed, list) or any(
                    not isinstance(transaction_id, str) for transaction_id in raw_failed
                ):
                    raise MutationJournalError(
                        "retained parent failed-family projection is malformed"
                    )
                failed.update(family_ids.intersection(raw_failed))
        if failed:
            raise MutationJournalError(
                "retained parent path family contains failed authority: "
                f"{sorted(failed)!r}"
            )

        def scope_projection(
            journal: "WorkspaceMutationJournal",
        ) -> tuple[tuple[str, ...], frozenset[str]]:
            raw_scope = journal._manifest.get("scope")
            raw_recursive = journal._manifest.get("recursive_scope", ())
            if (
                not isinstance(raw_scope, list)
                or not isinstance(raw_recursive, list)
                or any(not isinstance(path, str) for path in raw_scope)
                or any(not isinstance(path, str) for path in raw_recursive)
            ):
                raise MutationJournalError(
                    "retained parent path scope projection is malformed"
                )
            scope = tuple(_settlement_relative_path(path) for path in raw_scope)
            recursive = frozenset(
                _settlement_relative_path(path) for path in raw_recursive
            )
            if len(set(scope)) != len(scope) or not recursive.issubset(scope):
                raise MutationJournalError(
                    "retained parent path scope projection is ambiguous"
                )
            return scope, recursive

        child_scope, _child_recursive = scope_projection(self)
        parent_scope, parent_recursive = scope_projection(parent)
        for relative in normalized:
            if any(
                relative == root
                or relative.startswith(root.rstrip("/") + "/")
                or root.startswith(relative.rstrip("/") + "/")
                for root in child_scope
            ):
                raise MutationJournalError(
                    f"retained parent path overlaps child restore authority: {relative}"
                )
            if not any(
                relative == root
                or (
                    root in parent_recursive
                    and relative.startswith(root.rstrip("/") + "/")
                )
                for root in parent_scope
            ):
                raise MutationJournalError(
                    "retained parent path is outside immediate-parent scope: "
                    f"{relative}"
                )
        return frozenset(normalized)

    def capture_active_parent_postimage_handoff(
        self,
        paths: Iterable[str],
    ) -> _ActiveParentPostimageHandoff | None:
        """Issue a one-shot proof for exact accepted parent-owned postimages."""

        if not self.active:
            raise MutationJournalError(
                "cannot issue a parent postimage handoff from an inactive child"
            )
        rendered_paths = tuple(paths)
        logical_cwd = Path(self._manifest["cwd"])
        if not self._has_held_git_admin_authority():
            with workspace_mutation_lock(logical_cwd):
                return self.capture_active_parent_postimage_handoff(rendered_paths)
        self._require_writer_epoch_quiescence(
            frontier="active parent postimage handoff capture"
        )
        authorized = self._validated_active_parent_handoff_paths(rendered_paths)
        tracked = self._manifest.get("tracked_path_metadata")
        if not isinstance(tracked, dict):
            raise MutationJournalError(
                "active parent handoff lacks tracked metadata authority"
            )
        entries = self._manifest.get("entries")
        if not isinstance(entries, dict):
            raise MutationJournalError(
                "active parent handoff lacks snapshot baseline authority"
            )
        parent = _require_live_parent_transaction(
            cast(str, self.parent_transaction_id)
        )
        parent_entries = parent._manifest.get("entries")
        if not isinstance(parent_entries, dict):
            raise MutationJournalError(
                "active parent handoff lacks immediate-parent baseline authority"
            )
        directory_modes, _directory_xattrs = (
            _validated_workspace_directory_baseline(
                self._manifest.get("directory_modes"),
                self._manifest.get("directory_xattrs"),
            )
        )
        directory_identities = self._effective_workspace_directory_identities(
            directory_modes,
        )

        def baseline_for(relative: str) -> Mapping[str, object] | None:
            baseline = tracked.get(relative)
            if baseline is None:
                baseline = entries.get(relative)
            if baseline is None:
                baseline = parent_entries.get(relative)
            if baseline is not None and not isinstance(baseline, Mapping):
                raise MutationJournalError(
                    "active parent handoff baseline is malformed: "
                    f"{relative}"
                )
            return baseline

        records: dict[str, _ActiveParentPostimageRecord] = {}
        baselines: dict[str, Mapping[str, object] | None] = {}
        budget = _SettlementCaptureBudget()
        with _bound_workspace_restore_root(self) as root_fd:
            root = os.fstat(root_fd)
            for relative in sorted(authorized):
                current = _current_postimage_state(
                    root_fd,
                    relative,
                    budget,
                )
                record = _active_parent_postimage_record_from_state(
                    relative,
                    current,
                )
                prefixes = _workspace_restore_parent_prefixes(relative)
                try:
                    captured_parent_chain = (
                        directory_identities["."],
                        *(directory_identities[prefix] for prefix in prefixes),
                    )
                except KeyError as exc:
                    raise MutationJournalError(
                        "active parent candidate uses a directory that did not "
                        "exist when the child journal began: "
                        f"{relative!r}"
                    ) from exc
                if (
                    record.missing_parent_index is not None
                    or record.parent_chain != captured_parent_chain
                ):
                    raise MutationJournalError(
                        "active parent candidate directory topology changed "
                        "after the child journal began: "
                        f"{relative!r}"
                    )
                records[relative] = record
                baselines[relative] = baseline_for(relative)

            for relative, record in records.items():
                baseline = baselines[relative]
                baseline_kind = (
                    baseline.get("kind") if baseline is not None else None
                )
                if record.kind != "missing" and baseline_kind in {None, "missing"}:
                    rename_sources: list[tuple[str, Mapping[str, object]]] = []
                    record_identity = _active_parent_postimage_identity(record)
                    for source, source_baseline in tracked.items():
                        if not isinstance(source, str) or not isinstance(
                            source_baseline,
                            Mapping,
                        ):
                            raise MutationJournalError(
                                "active parent tracked baseline is malformed"
                            )
                        if source_baseline.get("kind") not in {"file", "symlink"}:
                            continue
                        source_identity = (
                            source_baseline.get("device"),
                            source_baseline.get("inode"),
                        )
                        if source_identity == record_identity:
                            rename_sources.append((source, source_baseline))
                    if rename_sources:
                        if len(rename_sources) != 1:
                            raise MutationJournalError(
                                "active parent rename source authority is "
                                f"ambiguous: {relative!r}"
                            )
                        source, source_baseline = rename_sources[0]
                        source_record = records.get(source)
                        if source_record is None or source_record.kind != "missing":
                            raise MutationJournalError(
                                "active parent rename requires explicit source "
                                f"and destination grants: {source!r} -> "
                                f"{relative!r}"
                            )
                        baseline = source_baseline
                _assert_reviewable_active_parent_transition(
                    relative,
                    baseline,
                    record,
                )
            if (
                self._validated_active_parent_handoff_paths(rendered_paths)
                != authorized
            ):
                raise MutationJournalError(
                    "active parent handoff authority changed during capture"
                )
            if not records:
                return None
            capability = object()
            handoff = _ActiveParentPostimageHandoff(
                child_transaction_id=self.transaction_id,
                parent_transaction_id=cast(str, self.parent_transaction_id),
                root_device=root.st_dev,
                root_inode=root.st_ino,
                records=tuple(records[path] for path in sorted(records)),
                capability=capability,
            )
            self._active_parent_postimage_handoffs[capability] = handoff
            return handoff

    def _consume_active_parent_postimage_handoff(
        self,
        handoff: _ActiveParentPostimageHandoff,
    ) -> dict[str, _ActiveParentPostimageRecord]:
        """Consume and authenticate one exact in-process handoff proof."""

        if type(handoff) is not _ActiveParentPostimageHandoff:
            raise MutationJournalError(
                "active parent postimage handoff has an invalid type"
            )
        try:
            issued = self._active_parent_postimage_handoffs.pop(handoff.capability)
        except (KeyError, TypeError) as exc:
            raise MutationJournalError(
                "active parent postimage handoff is absent, foreign, or reused"
            ) from exc
        if issued is not handoff:
            raise MutationJournalError(
                "active parent postimage handoff is not the issued capability"
            )
        if (
            handoff.child_transaction_id != self.transaction_id
            or handoff.parent_transaction_id != self.parent_transaction_id
            or not handoff.records
        ):
            raise MutationJournalError(
                "active parent postimage handoff lineage is malformed"
            )
        paths = tuple(record.path for record in handoff.records)
        if len(set(paths)) != len(paths):
            raise MutationJournalError(
                "active parent postimage handoff contains duplicate paths"
            )
        authorized = self._validated_active_parent_handoff_paths(paths)
        records: dict[str, _ActiveParentPostimageRecord] = {}
        for record in handoff.records:
            try:
                _validated_active_parent_postimage_record(record)
            except MutationJournalError as exc:
                raise MutationJournalError(
                    "active parent postimage handoff record is malformed: "
                    f"{record.path!r}"
                ) from exc
            if record.path not in authorized:
                raise MutationJournalError(
                    "active parent postimage handoff path is unauthorized: "
                    f"{record.path!r}"
                )
            records[record.path] = record
        with _bound_workspace_restore_root(self) as root_fd:
            root = os.fstat(root_fd)
        if (root.st_dev, root.st_ino) != (
            handoff.root_device,
            handoff.root_inode,
        ):
            raise MutationJournalError(
                "active parent postimage handoff owns a different checkout"
            )
        self._consumed_active_parent_postimage_handoffs[
            handoff.capability
        ] = handoff
        return records

    def reprove_consumed_active_parent_postimage_handoff(
        self,
        handoff: _ActiveParentPostimageHandoff,
    ) -> None:
        """Reassert a consumed proof after child cleanup and before a paid gate."""

        if self.active:
            raise MutationJournalError(
                "active parent postimage handoff was not terminally consumed"
            )
        if type(handoff) is not _ActiveParentPostimageHandoff:
            raise MutationJournalError(
                "active parent postimage handoff has an invalid type"
            )
        try:
            consumed = self._consumed_active_parent_postimage_handoffs[
                handoff.capability
            ]
        except (KeyError, TypeError) as exc:
            raise MutationJournalError(
                "active parent postimage handoff is absent, foreign, or "
                "unconsumed"
            ) from exc
        if consumed is not handoff:
            raise MutationJournalError(
                "active parent postimage handoff is not the consumed capability"
            )
        if (
            handoff.child_transaction_id != self.transaction_id
            or handoff.parent_transaction_id != self.parent_transaction_id
            or not handoff.records
        ):
            raise MutationJournalError(
                "consumed active parent postimage lineage is malformed"
            )

        logical_cwd = Path(self._manifest["cwd"])
        if not self._has_held_git_admin_authority():
            with workspace_mutation_lock(logical_cwd):
                self.reprove_consumed_active_parent_postimage_handoff(handoff)
                return
        parent = _require_live_parent_transaction(
            handoff.parent_transaction_id
        )
        if (
            not parent.active
            or parent.transaction_id != self.parent_transaction_id
            or Path(parent._manifest["cwd"]) != logical_cwd
        ):
            raise MutationJournalError(
                "consumed active parent postimage lost its immediate parent"
            )
        family = validated_live_parent_writer_epoch_family(
            parent.transaction_id,
            cwd=logical_cwd,
        )
        family_by_id = {member.transaction_id: member for member in family}
        if family_by_id.get(parent.transaction_id) is not parent:
            raise MutationJournalError(
                "consumed active parent postimage family changed after cleanup"
            )
        with _LIVE_TRANSACTIONS_LOCK:
            family_ids = set(family_by_id)
            failed = family_ids.intersection(_FAILED_LIVE_TRANSACTIONS)
            failed.update(
                {self.transaction_id}.intersection(_FAILED_LIVE_TRANSACTIONS)
            )
            for member in family:
                raw_failed = member._manifest.get("failed_family_members", ())
                if not isinstance(raw_failed, list) or any(
                    not isinstance(transaction_id, str)
                    for transaction_id in raw_failed
                ):
                    raise MutationJournalError(
                        "consumed active parent failed-family projection is "
                        "malformed"
                    )
                failed.update(raw_failed)
            if any(
                _LIVE_JOURNAL_OBJECTS.get(transaction_id) is not member
                or transaction_id not in _LIVE_TRANSACTIONS
                or not member.active
                for transaction_id, member in family_by_id.items()
            ):
                raise MutationJournalError(
                    "consumed active parent family is no longer the live "
                    "authority"
                )
        if failed:
            raise MutationJournalError(
                "consumed active parent postimage family contains failed "
                f"authority: {sorted(failed)!r}"
            )

        budget = _SettlementCaptureBudget()
        with _bound_workspace_restore_root(self) as root_fd:
            root = os.fstat(root_fd)
            if (root.st_dev, root.st_ino) != (
                handoff.root_device,
                handoff.root_inode,
            ):
                raise MutationJournalError(
                    "consumed active parent postimage owns a different checkout"
                )
            for record in handoff.records:
                _reprove_active_parent_postimage(root_fd, record, budget)

    def _tracked_regular_baseline_sha256(
        self,
        cwd: Path,
        relative: str,
    ) -> str:
        """Return the authenticated capture-time bytes for one tracked file."""

        entry = self._manifest.get("entries", {}).get(relative)
        if entry is not None:
            if not isinstance(entry, Mapping) or entry.get("kind") != "file":
                raise MutationJournalError(
                    "retained parent path lacks a regular captured preimage: "
                    f"{relative}"
                )
            payload = self._read_snapshot_blob_record(
                entry,
                label=f"tracked parent-handoff preimage {relative}",
            )
            return hashlib.sha256(payload).hexdigest()

        raw_binding = self._manifest.get("raw_object_restore", {}).get(relative)
        if raw_binding is not None:
            if not isinstance(raw_binding, dict):
                raise MutationJournalError(
                    f"retained parent raw preimage is malformed: {relative}"
                )
            return hashlib.sha256(
                _read_bound_blob(cwd, relative, raw_binding)
            ).hexdigest()

        tree_entry = _materialize_git_tree_restore_entry(
            cwd,
            str(self._manifest["head"]),
            relative,
            _MutationJournalArtifactBudget(),
        )
        if (
            not isinstance(tree_entry, dict)
            or tree_entry.get("kind") != "file"
            or not isinstance(tree_entry.get("payload"), bytes)
        ):
            raise MutationJournalError(
                f"retained parent path lacks an exact file preimage: {relative}"
            )
        return hashlib.sha256(cast(bytes, tree_entry["payload"])).hexdigest()

    def _restore_tracked_path_metadata(
        self,
        cwd: Path,
        directory_authority: Mapping[str, _BoundWorkspaceDirectoryRecord],
        *,
        active_parent_postimages: (
            Mapping[str, _ActiveParentPostimageRecord] | None
        ) = None,
        allow_exact_baseline_rebind: bool = False,
        restored_roots: frozenset[str] = frozenset(),
    ) -> tuple[
        dict[str, tuple[int, int] | None],
        frozenset[str],
    ]:
        expected = self._manifest.get("tracked_path_metadata")
        if expected is None:
            expected = {}
        if not isinstance(expected, dict):
            raise MutationJournalError("tracked metadata baseline is malformed")
        postimages = dict(active_parent_postimages or {})
        paths: dict[str, Mapping[str, object] | None] = dict(expected)
        for relative in postimages:
            paths.setdefault(relative, None)
        # A prior selective restore may have installed exact baseline files or
        # symlinks with replacement inodes.  Their authority must survive a
        # process restart just as restored directory authority does; otherwise
        # a later scoped restore would either trust a pathname or reject our
        # own previously published baseline inode.  Validate the durable map
        # before touching the workspace and then let process-local authority
        # (including a just-published inode) take precedence.
        durable_entry_authority = (
            self._validated_restored_tracked_entry_authority()
        )
        for relative, identity in durable_entry_authority.items():
            self._restored_workspace_entry_authority.setdefault(
                relative,
                identity,
            )
        entry_authority: dict[str, tuple[int, int] | None] = dict(
            durable_entry_authority
        )
        entry_authority.update(self._restored_workspace_entry_authority)
        verified_postimages: set[str] = set()
        postimage_budget = _SettlementCaptureBudget()
        with _bound_workspace_restore_root(self) as root_fd:
            for relative, baseline in paths.items():
                if (
                    not isinstance(relative, str)
                    or _settlement_relative_path(relative) != relative
                    or (baseline is not None and not isinstance(baseline, Mapping))
                ):
                    raise MutationJournalError(
                        "tracked metadata baseline is malformed"
                    )
                parent_postimage = postimages.get(relative)
                parent_postimage_eligible = parent_postimage is not None and not any(
                    relative == root or relative.startswith(root.rstrip("/") + "/")
                    for root in restored_roots
                )
                if parent_postimage is not None and not parent_postimage_eligible:
                    raise MutationJournalError(
                        "active parent postimage overlaps restored authority: "
                        f"{relative}"
                    )
                if parent_postimage_eligible:
                    assert parent_postimage is not None
                    expected_chain = _workspace_directory_parent_chain(
                        relative,
                        directory_authority,
                    )
                    state = _reprove_active_parent_postimage(
                        root_fd,
                        parent_postimage,
                        postimage_budget,
                    )
                    observed_chain = tuple(
                        (int(identity[0]), int(identity[1]))
                        for identity in cast(list[list[int]], state["parent_chain"])
                    )
                    if observed_chain != expected_chain:
                        raise MutationJournalError(
                            "active parent postimage parent authority changed: "
                            f"{relative}"
                        )
                    active_identity = _active_parent_postimage_identity(
                        parent_postimage
                    )
                    self._restored_workspace_entry_authority[relative] = (
                        active_identity
                    )
                    entry_authority[relative] = active_identity
                    self._restored_tracked_metadata_observations[relative] = (
                        _active_parent_postimage_observation(state)
                    )
                    verified_postimages.add(relative)
                    continue
                if baseline is None:
                    raise MutationJournalError(
                        "active parent postimage proof vanished for an untracked "
                        f"path: {relative}"
                    )
                kind = baseline.get("kind")
                if relative in entry_authority:
                    expected_identity = entry_authority[relative]
                elif kind == "missing":
                    expected_identity = None
                else:
                    device = baseline.get("device")
                    inode = baseline.get("inode")
                    if any(
                        isinstance(component, bool)
                        or not isinstance(component, int)
                        or component < 0
                        for component in (device, inode)
                    ):
                        raise MutationJournalError(
                            f"tracked path lacks captured identity: {relative}"
                        )
                    expected_identity = (
                        cast(int, device),
                        cast(int, inode),
                    )
                if kind == "missing" and expected_identity is None:
                    # A tracked entry can already be absent beneath an absent
                    # parent when a later transaction starts (for example,
                    # after an earlier tier deleted a tracked subtree).  Its
                    # captured absence is still exact authority.  Validate the
                    # reachable parent prefix and the leaf absence together;
                    # requiring a complete parent chain here would reject the
                    # very missing-parent state that was captured.
                    _assert_bound_workspace_absence_token(
                        root_fd,
                        relative,
                        directory_authority,
                    )
                    entry_authority[relative] = None
                    self._restored_tracked_metadata_observations[relative] = {
                        "kind": "missing"
                    }
                    continue
                expected_chain = _workspace_directory_parent_chain(
                    relative,
                    directory_authority,
                )
                with _open_settlement_parent_if_present(
                    root_fd,
                    relative,
                ) as binding:
                    parent_fd, name, parent_chain, missing_index = binding
                    if missing_index is not None:
                        if kind == "missing" and expected_identity is None:
                            entry_authority[relative] = None
                            self._restored_tracked_metadata_observations[
                                relative
                            ] = {"kind": "missing"}
                            continue
                        raise MutationJournalError(
                            f"tracked path parent was not restored: {relative}"
                        )
                    if parent_chain != expected_chain:
                        raise MutationJournalError(
                            f"tracked path parent authority changed: {relative}"
                        )
                    _assert_settlement_parent_binding(
                        root_fd,
                        relative,
                        parent_fd,
                        parent_chain,
                    )
                    try:
                        metadata = os.stat(
                            name,
                            dir_fd=parent_fd,
                            follow_symlinks=False,
                        )
                    except FileNotFoundError:
                        if kind == "missing" and expected_identity is None:
                            entry_authority[relative] = None
                            self._restored_tracked_metadata_observations[
                                relative
                            ] = {"kind": "missing"}
                            continue
                        raise MutationJournalError(
                            f"tracked path was not restored: {relative}"
                        ) from None
                    if kind == "missing" or expected_identity is None:
                        raise MutationJournalError(
                            f"tracked path unexpectedly exists: {relative}"
                        )
                    observed_identity = (metadata.st_dev, metadata.st_ino)
                    carried_authority: str | None = None
                    if metadata.st_nlink != 1:
                        raise MutationJournalError(
                            f"tracked path authority changed: {relative}"
                        )
                    if observed_identity != expected_identity:
                        if allow_exact_baseline_rebind:
                            carried_authority = "exact_baseline_rebind"
                        else:
                            raise MutationJournalError(
                                f"tracked path authority changed: {relative}"
                            )
                        if kind != "file" or not stat.S_ISREG(metadata.st_mode):
                            raise MutationJournalError(
                                "carried tracked path is not a regular file: "
                                f"{relative}"
                            )
                        expected_identity = observed_identity
                    if kind == "symlink":
                        if (
                            not stat.S_ISLNK(metadata.st_mode)
                            or os.readlink(name, dir_fd=parent_fd)
                            != baseline.get("target")
                            or _validated_restore_xattrs(
                                baseline.get("xattrs", {}),
                                label=relative,
                            )
                        ):
                            raise MutationJournalError(
                                f"tracked symlink metadata is unsupported or "
                                f"changed: {relative}"
                            )
                        entry_authority[relative] = expected_identity
                        self._restored_tracked_metadata_observations[relative] = {
                            "kind": "symlink",
                            "mode": stat.S_IMODE(metadata.st_mode),
                            "nlink": metadata.st_nlink,
                            "xattrs": {},
                            "device": metadata.st_dev,
                            "inode": metadata.st_ino,
                            "size": metadata.st_size,
                            "mtime_ns": metadata.st_mtime_ns,
                            "ctime_ns": metadata.st_ctime_ns,
                            "target": baseline.get("target"),
                        }
                        continue
                    if kind != "file" or not stat.S_ISREG(metadata.st_mode):
                        raise MutationJournalError(
                            f"tracked path type was not restored: {relative}"
                        )
                    baseline_xattrs = _validated_restore_xattrs(
                        baseline.get("xattrs", {}),
                        label=relative,
                    )
                    baseline_mode = baseline.get("mode")
                    if (
                        not isinstance(baseline_mode, int)
                        or isinstance(baseline_mode, bool)
                        or not 0 <= baseline_mode <= 0o7777
                    ):
                        raise MutationJournalError(
                            f"tracked path mode is malformed: {relative}"
                        )
                    path_fd = os.open(
                        name,
                        os.O_PATH
                        | getattr(os, "O_CLOEXEC", 0)
                        | getattr(os, "O_NOFOLLOW", 0),
                        dir_fd=parent_fd,
                    )
                    file_fd: int | None = None
                    try:
                        opened_path = os.fstat(path_fd)
                        current = os.stat(
                            name,
                            dir_fd=parent_fd,
                            follow_symlinks=False,
                        )
                        if (
                            not stat.S_ISREG(opened_path.st_mode)
                            or opened_path.st_nlink != 1
                            or (opened_path.st_dev, opened_path.st_ino)
                            != expected_identity
                            or (current.st_dev, current.st_ino)
                            != expected_identity
                        ):
                            raise MutationJournalError(
                                f"tracked path changed while binding: {relative}"
                            )
                        if carried_authority is not None:
                            if stat.S_IMODE(opened_path.st_mode) != baseline_mode:
                                raise MutationJournalError(
                                    f"carried tracked path mode changed: {relative}"
                                )
                            file_fd = os.open(
                                _authority_descriptor_cwd(path_fd),
                                os.O_RDONLY
                                | getattr(os, "O_CLOEXEC", 0)
                                | getattr(os, "O_NONBLOCK", 0),
                            )
                            opened = os.fstat(file_fd)
                            if (
                                not stat.S_ISREG(opened.st_mode)
                                or opened.st_nlink != 1
                                or (opened.st_dev, opened.st_ino) != expected_identity
                                or _bound_descriptor_xattr_inventory(
                                    file_fd,
                                    label=relative,
                                )
                                != baseline_xattrs
                            ):
                                raise MutationJournalError(
                                    f"carried tracked path metadata changed: {relative}"
                                )
                            if opened.st_size > _LIFECYCLE_SETTLEMENT_MAX_HASHED_BYTES:
                                raise MutationJournalError(
                                    "carried tracked path exceeds its byte "
                                    f"ceiling: {relative}"
                                )
                            digest = hashlib.sha256()
                            observed_size = 0
                            while True:
                                chunk = os.read(file_fd, 1024 * 1024)
                                if not chunk:
                                    break
                                observed_size += len(chunk)
                                if observed_size > opened.st_size:
                                    raise MutationJournalError(
                                        "carried tracked path grew during "
                                        f"hashing: {relative}"
                                    )
                                digest.update(chunk)
                            finished = os.fstat(file_fd)
                            current = os.stat(
                                name,
                                dir_fd=parent_fd,
                                follow_symlinks=False,
                            )
                            if observed_size != opened.st_size or any(
                                getattr(opened, field) != getattr(finished, field)
                                or getattr(opened, field) != getattr(current, field)
                                for field in _SETTLEMENT_STABLE_STAT_FIELDS
                            ):
                                raise MutationJournalError(
                                    "carried tracked path changed during "
                                    f"hashing: {relative}"
                                )
                            observed_digest = digest.hexdigest()
                            baseline_digest = self._tracked_regular_baseline_sha256(
                                cwd,
                                relative,
                            )
                            if observed_digest != baseline_digest:
                                raise MutationJournalError(
                                    "rebound tracked path differs from its "
                                    f"exact baseline: {relative}"
                                )
                            self._restored_workspace_entry_authority[relative] = (
                                expected_identity
                            )
                            entry_authority[relative] = expected_identity
                            self._restored_tracked_metadata_observations[relative] = {
                                "kind": "file",
                                "mode": stat.S_IMODE(finished.st_mode),
                                "nlink": finished.st_nlink,
                                "xattrs": dict(baseline_xattrs),
                                "device": finished.st_dev,
                                "inode": finished.st_ino,
                                "size": finished.st_size,
                                "mtime_ns": finished.st_mtime_ns,
                                "ctime_ns": finished.st_ctime_ns,
                            }
                            _assert_settlement_parent_binding(
                                root_fd,
                                relative,
                                parent_fd,
                                parent_chain,
                            )
                            continue
                        working_mode = stat.S_IMODE(opened_path.st_mode) | 0o600
                        if stat.S_IMODE(opened_path.st_mode) != working_mode:
                            os.chmod(
                                _authority_descriptor_cwd(path_fd),
                                working_mode,
                            )
                        file_fd = os.open(
                            _authority_descriptor_cwd(path_fd),
                            os.O_RDONLY
                            | getattr(os, "O_CLOEXEC", 0)
                            | getattr(os, "O_NONBLOCK", 0),
                        )
                        opened = os.fstat(file_fd)
                        if (
                            not stat.S_ISREG(opened.st_mode)
                            or opened.st_nlink != 1
                            or (opened.st_dev, opened.st_ino)
                            != expected_identity
                        ):
                            raise MutationJournalError(
                                f"tracked path changed while reopening: {relative}"
                            )
                        # A guard-only sibling may still be observing this
                        # inode's ctime.  Re-applying identical metadata is a
                        # real mutation on Linux (even fchmod to the same mode
                        # advances ctime), so perform only the repairs that
                        # differ from the authenticated baseline.
                        if _bound_descriptor_xattr_inventory(
                            file_fd,
                            label=relative,
                        ) != baseline_xattrs:
                            _restore_bound_descriptor_xattrs(
                                file_fd,
                                baseline_xattrs,
                                label=relative,
                            )
                        if stat.S_IMODE(os.fstat(file_fd).st_mode) != baseline_mode:
                            os.fchmod(file_fd, baseline_mode)
                        finished = os.fstat(file_fd)
                        current = os.stat(
                            name,
                            dir_fd=parent_fd,
                            follow_symlinks=False,
                        )
                        if (
                            (finished.st_dev, finished.st_ino)
                            != expected_identity
                            or (current.st_dev, current.st_ino)
                            != expected_identity
                            or stat.S_IMODE(finished.st_mode) != baseline_mode
                            or _bound_descriptor_xattr_inventory(
                                file_fd,
                                label=relative,
                            )
                            != baseline_xattrs
                        ):
                            raise MutationJournalError(
                                f"tracked path changed during metadata restore: "
                                f"{relative}"
                            )
                        self._restored_tracked_metadata_observations[relative] = {
                            "kind": "file",
                            "mode": stat.S_IMODE(finished.st_mode),
                            "nlink": finished.st_nlink,
                            "xattrs": dict(baseline_xattrs),
                            "device": finished.st_dev,
                            "inode": finished.st_ino,
                            "size": finished.st_size,
                            "mtime_ns": finished.st_mtime_ns,
                            "ctime_ns": finished.st_ctime_ns,
                        }
                    finally:
                        if file_fd is not None:
                            os.close(file_fd)
                        os.close(path_fd)
                    _assert_settlement_parent_binding(
                        root_fd,
                        relative,
                        parent_fd,
                        parent_chain,
                    )
                    entry_authority[relative] = expected_identity
        return entry_authority, frozenset(verified_postimages)

    def _tracked_metadata_drift_paths(self, cwd: Path) -> set[str]:
        expected = self._manifest.get("tracked_path_metadata", {})
        return {
            relative
            for relative, baseline in expected.items()
            if _tracked_path_metadata_for_path(cwd, relative)
            != self._restored_tracked_metadata_observations.get(
                relative,
                baseline,
            )
        }

    def _reprove_restored_tracked_path_authority(
        self,
        cwd: Path,
        directory_authority: Mapping[
            str, _BoundWorkspaceDirectoryRecord
        ],
        entry_authority: Mapping[str, tuple[int, int] | None],
        *,
        active_parent_postimages: (
            Mapping[str, _ActiveParentPostimageRecord] | None
        ) = None,
    ) -> frozenset[str]:
        """Rebind every tracked entry to the carried post-restore authority."""

        observed, verified_postimages = self._restore_tracked_path_metadata(
            cwd,
            directory_authority,
            active_parent_postimages=active_parent_postimages,
        )
        expected_paths = set(
            (self._manifest.get("tracked_path_metadata") or {}).keys()
        )
        expected_paths.update(active_parent_postimages or {})
        for relative in expected_paths:
            if (
                relative not in entry_authority
                or observed.get(relative) != entry_authority[relative]
            ):
                raise MutationJournalError(
                    "tracked workspace authority changed before terminal "
                    f"handoff: {relative!r}"
                )
        return verified_postimages

    def _reprove_restored_workspace_entry_authority(
        self,
        directory_authority: Mapping[
            str, _BoundWorkspaceDirectoryRecord
        ],
    ) -> None:
        """Reprove every installed/removed snapshot entry under held parents."""

        with _bound_workspace_restore_root(self) as root_fd:
            for relative, expected_identity in sorted(
                self._restored_workspace_entry_authority.items()
            ):
                if expected_identity is None:
                    _assert_bound_workspace_absence_token(
                        root_fd,
                        relative,
                        directory_authority,
                    )
                    continue
                expected_chain = _workspace_directory_parent_chain(
                    relative,
                    directory_authority,
                )
                with _open_settlement_parent_if_present(
                    root_fd,
                    relative,
                ) as binding:
                    parent_fd, name, parent_chain, missing_index = binding
                    if missing_index is not None:
                        raise MutationJournalError(
                            "restored workspace entry parent disappeared: "
                            f"{relative!r}"
                        )
                    if parent_chain != expected_chain:
                        raise MutationJournalError(
                            "restored workspace entry parent changed: "
                            f"{relative!r}"
                        )
                    try:
                        current = os.stat(
                            name,
                            dir_fd=parent_fd,
                            follow_symlinks=False,
                        )
                    except FileNotFoundError:
                        raise MutationJournalError(
                            f"restored workspace entry disappeared: {relative!r}"
                        ) from None
                    if (current.st_dev, current.st_ino) != expected_identity:
                        raise MutationJournalError(
                            "restored workspace entry authority changed: "
                            f"{relative!r}"
                        )
                    _assert_settlement_parent_binding(
                        root_fd,
                        relative,
                        parent_fd,
                        parent_chain,
                    )

    def _restore_git_entry(self, cwd: Path) -> None:
        expected = self._manifest.get("git_entry")
        if expected is None:
            return
        if not isinstance(expected, Mapping):
            raise MutationJournalError("Git entry manifest is malformed")
        if expected["kind"] == "directory":
            with _bound_workspace_restore_root(self) as root_fd:
                with _open_settlement_parent_if_present(
                    root_fd,
                    ".git",
                    allow_terminal_vcs_metadata=True,
                ) as binding:
                    parent_fd, name, parent_chain, missing_index = binding
                    if missing_index is not None:
                        raise MutationJournalError(
                            "Git administration disappeared"
                        )
                    descriptor, opened = _open_authority_directory_at(
                        parent_fd,
                        name,
                        label="workspace Git administration",
                    )
                    try:
                        if (
                            opened.st_dev != int(expected["device"])
                            or opened.st_ino != int(expected["inode"])
                        ):
                            raise MutationJournalError(
                                "Git administration moved or aliased"
                            )
                        requested_mode = int(expected["mode"])
                        expected_xattrs = _validated_restore_xattrs(
                            expected.get("xattrs", {}),
                            label="workspace Git administration",
                        )
                        if _bound_descriptor_xattr_inventory(
                            descriptor,
                            label="workspace Git administration",
                        ) != expected_xattrs:
                            _restore_bound_descriptor_xattrs(
                                descriptor,
                                expected_xattrs,
                                label="workspace Git administration",
                            )
                        if stat.S_IMODE(opened.st_mode) != requested_mode:
                            os.fchmod(descriptor, requested_mode)
                        _assert_settlement_parent_binding(
                            root_fd,
                            ".git",
                            parent_fd,
                            parent_chain,
                            allow_terminal_vcs_metadata=True,
                        )
                    finally:
                        os.close(descriptor)
            return
        if expected.get("kind") != "file":
            raise MutationJournalError("Git entry kind is unsupported")
        payload = self._read_snapshot_blob_record(
            expected,
            label="Git indirection file",
        )
        with _bound_workspace_restore_root(self) as root_fd:
            with _open_settlement_parent_if_present(
                root_fd,
                ".git",
                allow_terminal_vcs_metadata=True,
            ) as binding:
                parent_fd, name, parent_chain, missing_index = binding
                if missing_index is not None:
                    raise MutationJournalError(
                        "Git indirection parent disappeared"
                    )
                current = os.stat(
                    name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
                if stat.S_ISDIR(current.st_mode) and not stat.S_ISLNK(
                    current.st_mode
                ):
                    raise MutationJournalError(
                        "refusing to recursively replace an unauthenticated "
                        "Git indirection directory"
                    )
                _remove_bound_workspace_entry(
                    root_fd,
                    ".git",
                    parent_fd,
                    name,
                    parent_chain,
                    allow_terminal_vcs_metadata=True,
                )
            _install_bound_workspace_entry(
                root_fd,
                ".git",
                expected_parent_chain=((
                    os.fstat(root_fd).st_dev,
                    os.fstat(root_fd).st_ino,
                ),),
                kind="file",
                mode=int(expected["mode"]),
                xattrs=_validated_restore_xattrs(
                    expected.get("xattrs", {}),
                    label="workspace Git indirection entry",
                ),
                payload=payload,
                allow_terminal_vcs_metadata=True,
            )
        admin = _git_dir(cwd)
        if not self._bound_paths_same(
            admin,
            self._manifest.get("git_admin_dir", str(admin)),
        ):
            raise MutationJournalError("Git admin root moved during rollback")

    def _ignore_policy_unchanged(self) -> bool:
        cwd = self._bound_workspace_cwd()
        expected_records = self._manifest.get("ignore_policy")
        if expected_records is None:
            return True
        current_paths = set(_ignore_policy_paths(cwd))
        expected_paths = {record["path"] for record in expected_records}
        if current_paths != expected_paths:
            return False
        payloads: dict[str, bytes] = {}
        budget = _MutationJournalArtifactBudget()
        for record in expected_records:
            if bool(record.get("exists", True)):
                relative = str(record["path"])
                payloads[relative] = self._read_snapshot_blob_record(
                    record,
                    label=f"Git ignore policy {relative}",
                    budget=budget,
                )
        with _bound_workspace_restore_root(self) as root_fd:
            for record in expected_records:
                relative = _normalize_relative(cwd, str(record["path"]))
                with _open_settlement_parent_if_present(
                    root_fd,
                    relative,
                ) as binding:
                    parent_fd, name, parent_chain, missing_index = binding
                    if missing_index is not None:
                        if record.get("exists", True):
                            return False
                        continue
                    if not record.get("exists", True):
                        return False
                    expected = payloads[relative]
                    try:
                        payload, metadata = _read_bound_regular_entry(
                            parent_fd,
                            name,
                            label=f"Git ignore policy {relative}",
                            max_bytes=max(len(expected), 1),
                        )
                    except MutationJournalError:
                        return False
                    if (
                        stat.S_IMODE(metadata.st_mode) != int(record["mode"])
                        or _xattr_inventory(
                            Path(_authority_descriptor_cwd(parent_fd)) / name
                        )
                        != record.get("xattrs", {})
                        or payload != expected
                    ):
                        return False
                    try:
                        _assert_settlement_parent_binding(
                            root_fd,
                            relative,
                            parent_fd,
                            parent_chain,
                        )
                    except MutationJournalError:
                        return False
        return True

    def _effective_ignored_directory_roots(
        self,
        cwd: Path,
        *,
        protected_paths: Iterable[str],
    ) -> tuple[str, ...]:
        """Retain baseline-opaque roots and admit safe current additions.

        ``ignored_nested_vcs_roots`` is captured before the writer starts and
        is excluded from the baseline directory inventory. Recomputing only
        from the post-write tree against that inventory's guarded ancestors
        would make every nested baseline build/cache root authoritative and
        then misclassify its recursive growth as topology drift.

        Fresh ignored roots are trustworthy only while the captured ignore
        policy remains exact. Baseline roots remain opaque either way: they
        were deliberately outside transaction authority at capture time.
        """

        baseline = tuple(
            self._manifest.get("ignored_nested_vcs_roots", ())
        )
        if not self._ignore_policy_unchanged():
            return baseline
        return tuple(dict.fromkeys((
            *baseline,
            *_ignored_directory_roots_outside_authority(
                cwd,
                protected_paths=protected_paths,
            ),
        )))

    def _deleted_recursive_scope_roots(self) -> frozenset[str]:
        """Return captured recursive directories proven wholly absent."""

        scope = {
            _settlement_relative_path(str(path))
            for path in self._manifest.get("scope", ())
        }
        recursive_scope = {
            _settlement_relative_path(str(path))
            for path in self._manifest.get("recursive_scope", ())
        }
        entries = self._manifest.get("entries")
        expected_modes = self._manifest.get("directory_modes")
        if not isinstance(entries, dict) or not isinstance(expected_modes, dict):
            raise MutationJournalError(
                "mutation journal workspace baseline is malformed"
            )
        captured_identities = self._effective_workspace_directory_identities(
            expected_modes,
        )
        deleted: set[str] = set()
        with _bound_workspace_restore_root(self) as root_fd:
            for recursive_root in sorted(recursive_scope):
                baseline = entries.get(recursive_root)
                if recursive_root not in scope or not (
                    isinstance(baseline, Mapping)
                    and baseline.get("kind") == "directory"
                ):
                    continue
                with _open_settlement_parent_if_present(
                    root_fd,
                    recursive_root,
                ) as binding:
                    parent_fd, name, parent_chain, missing_index = binding
                    if missing_index is not None:
                        # An ancestor above the authority root disappeared.
                        continue
                    prefixes = _workspace_restore_parent_prefixes(
                        recursive_root
                    )
                    for index, observed in enumerate(parent_chain):
                        authority_path = (
                            "." if index == 0 else prefixes[index - 1]
                        )
                        if captured_identities.get(authority_path) != observed:
                            raise MutationJournalError(
                                "recursive deletion parent changed before "
                                f"absence proof: {recursive_root}"
                            )
                    try:
                        os.stat(
                            name,
                            dir_fd=parent_fd,
                            follow_symlinks=False,
                        )
                    except FileNotFoundError:
                        _assert_settlement_parent_binding(
                            root_fd,
                            recursive_root,
                            parent_fd,
                            parent_chain,
                        )
                        try:
                            os.stat(
                                name,
                                dir_fd=parent_fd,
                                follow_symlinks=False,
                            )
                        except FileNotFoundError:
                            deleted.add(recursive_root)
                            continue
                        raise MutationJournalError(
                            "recursive deletion root appeared during absence "
                            f"proof: {recursive_root}"
                        ) from None
        return frozenset(deleted)

    def _recursive_scope_root_for_missing_attribute_parent(
        self,
        root_fd: int,
        relative: str,
        parent_chain: tuple[tuple[int, int], ...],
        missing_index: int,
        *,
        allow_missing_below_root: bool,
    ) -> str | None:
        """Classify a policy-parent absence owned by one recursive root."""

        scope = {
            _settlement_relative_path(str(path))
            for path in self._manifest.get("scope", ())
        }
        recursive_scope = {
            _settlement_relative_path(str(path))
            for path in self._manifest.get("recursive_scope", ())
        }
        entries = self._manifest.get("entries")
        if not isinstance(entries, dict):
            raise MutationJournalError(
                "mutation journal workspace entries are malformed"
            )
        relative_parts = PurePosixPath(relative).parts
        candidates: list[tuple[int, str]] = []
        for recursive_root in recursive_scope:
            root_parts = PurePosixPath(recursive_root).parts
            if (
                recursive_root not in scope
                or len(root_parts) >= len(relative_parts)
                or relative_parts[:len(root_parts)] != root_parts
            ):
                continue
            baseline = entries.get(recursive_root)
            if not isinstance(baseline, Mapping) or (
                baseline.get("kind") != "directory"
            ):
                continue
            root_index = len(root_parts) - 1
            if missing_index == root_index or (
                allow_missing_below_root and missing_index > root_index
            ):
                candidates.append((len(root_parts), recursive_root))
        if not candidates:
            return None

        expected_modes = self._manifest.get("directory_modes")
        if not isinstance(expected_modes, dict):
            raise MutationJournalError(
                "workspace directory baseline is malformed"
            )
        captured_identities = self._effective_workspace_directory_identities(
            expected_modes,
        )
        prefixes = _workspace_restore_parent_prefixes(relative)
        for index, observed in enumerate(parent_chain):
            authority_path = "." if index == 0 else prefixes[index - 1]
            if captured_identities.get(authority_path) != observed:
                raise MutationJournalError(
                    "Git attribute policy parent changed before recursive "
                    f"deletion proof: {relative}"
                )

        with _open_settlement_parent_if_present(
            root_fd,
            relative,
        ) as retry:
            (
                _retry_fd,
                _retry_name,
                retry_chain,
                retry_missing_index,
            ) = retry
            if (
                retry_chain != parent_chain
                or retry_missing_index != missing_index
            ):
                raise MutationJournalError(
                    "Git attribute policy parent changed during recursive "
                    f"deletion proof: {relative}"
                )
        return max(candidates)[1]

    def _deferred_recursive_attribute_policy_roots(
        self,
        cwd: Path,
        paths: Iterable[str],
    ) -> dict[str, str]:
        """Reprove policy paths covered by a whole-root tombstone."""

        deferred: dict[str, str] = {}
        with _bound_workspace_restore_root(self) as root_fd:
            for rendered in paths:
                relative = _normalize_relative(cwd, rendered)
                with _open_settlement_parent_if_present(
                    root_fd,
                    relative,
                ) as binding:
                    (
                        _parent_fd,
                        _name,
                        parent_chain,
                        missing_index,
                    ) = binding
                    if missing_index is None:
                        continue
                    recursive_root = (
                        self._recursive_scope_root_for_missing_attribute_parent(
                            root_fd,
                            relative,
                            parent_chain,
                            missing_index,
                            allow_missing_below_root=False,
                        )
                    )
                    if recursive_root is not None:
                        deferred[relative] = recursive_root
        return deferred

    def _validated_deferred_recursive_attribute_policy_roots(
        self,
    ) -> dict[str, str]:
        """Validate durable whole-root deletion proofs before reuse."""

        raw = self._manifest.get(
            _DEFERRED_RECURSIVE_ATTRIBUTE_POLICY_KEY,
            {},
        )
        if not isinstance(raw, dict):
            raise MutationJournalError(
                "deferred recursive Git attribute policy proof is malformed"
            )
        scope = {
            _settlement_relative_path(str(path))
            for path in self._manifest.get("scope", ())
        }
        recursive_scope = {
            _settlement_relative_path(str(path))
            for path in self._manifest.get("recursive_scope", ())
        }
        entries = self._manifest.get("entries")
        attribute_policy = self._manifest.get("attribute_policy")
        if not isinstance(entries, dict) or not isinstance(attribute_policy, list):
            raise MutationJournalError(
                "mutation journal attribute proof baseline is malformed"
            )
        attribute_paths: set[str] = set()
        for record in attribute_policy:
            path = record.get("path") if isinstance(record, Mapping) else None
            if not isinstance(path, str):
                raise MutationJournalError(
                    "mutation journal Git attribute policy baseline is malformed"
                )
            normalized_path = _settlement_relative_path(path)
            if normalized_path != path or normalized_path in attribute_paths:
                raise MutationJournalError(
                    "mutation journal Git attribute policy baseline is malformed"
                )
            attribute_paths.add(normalized_path)

        validated: dict[str, str] = {}
        for rendered_path, rendered_root in raw.items():
            if not isinstance(rendered_path, str) or not isinstance(
                rendered_root,
                str,
            ):
                raise MutationJournalError(
                    "deferred recursive Git attribute policy proof is malformed"
                )
            path = _settlement_relative_path(rendered_path)
            recursive_root = _settlement_relative_path(rendered_root)
            baseline = entries.get(recursive_root)
            if (
                path != rendered_path
                or recursive_root != rendered_root
                or path not in attribute_paths
                or recursive_root not in scope
                or recursive_root not in recursive_scope
                or not path.startswith(recursive_root.rstrip("/") + "/")
                or not isinstance(baseline, Mapping)
                or baseline.get("kind") != "directory"
            ):
                raise MutationJournalError(
                    "deferred recursive Git attribute policy proof is invalid"
                )
            validated[path] = recursive_root
        return validated

    def _restored_attribute_policy_paths(
        self,
        cwd: Path,
        paths: Iterable[str],
        restored_roots: Iterable[str],
    ) -> frozenset[str]:
        """Reprove historical policy findings restored to their exact image."""

        entries = self._manifest.get("entries")
        expected_records = self._manifest.get("attribute_policy")
        raw_bindings = self._manifest.get("raw_object_restore", {})
        if (
            not isinstance(entries, dict)
            or not isinstance(expected_records, list)
            or not isinstance(raw_bindings, dict)
        ):
            raise MutationJournalError(
                "mutation journal attribute proof baseline is malformed"
            )
        policy_paths: set[str] = set()
        for record in expected_records:
            path = record.get("path") if isinstance(record, Mapping) else None
            if not isinstance(path, str):
                raise MutationJournalError(
                    "mutation journal Git attribute policy baseline is malformed"
                )
            normalized_path = _settlement_relative_path(path)
            if normalized_path != path or normalized_path in policy_paths:
                raise MutationJournalError(
                    "mutation journal Git attribute policy baseline is malformed"
                )
            policy_paths.add(normalized_path)
        deferred_roots = (
            self._validated_deferred_recursive_attribute_policy_roots()
        )
        roots = tuple(
            _normalize_relative(cwd, rendered)
            for rendered in restored_roots
        )
        restored: set[str] = set()
        for rendered in paths:
            relative = _normalize_relative(cwd, rendered)
            if (
                relative not in policy_paths
                or relative not in deferred_roots
                or not any(
                relative == root or relative.startswith(root.rstrip("/") + "/")
                for root in roots
                )
            ):
                continue
            baseline = entries.get(relative)
            if not isinstance(baseline, Mapping):
                raise MutationJournalError(
                    "Git attribute policy path lacks an exact workspace snapshot: "
                    f"{relative}"
                )
            if not _matches_snapshot(self, relative, baseline):
                continue
            raw_binding = raw_bindings.get(relative)
            if raw_binding is not None and not _matches_raw_object_binding(
                self,
                relative,
                raw_binding,
            ):
                continue
            restored.add(relative)
        return frozenset(restored)

    def _restore_recursive_roots_for_attribute_policy(
        self,
        cwd: Path,
    ) -> tuple[
        tuple[str, ...],
        dict[str, tuple[int, int] | None],
    ]:
        """Restore roots needed before rollback can perform Git reads."""

        expected_records = self._manifest.get("attribute_policy")
        if expected_records is None:
            return (), {}
        roots: set[str] = set()
        changed_paths: set[str] = set()
        with _bound_workspace_restore_root(self) as root_fd:
            for raw_record in expected_records:
                if not isinstance(raw_record, Mapping):
                    raise MutationJournalError(
                        "Git attribute policy baseline is malformed"
                    )
                if not bool(raw_record.get("exists", True)):
                    continue
                relative = _normalize_relative(
                    cwd,
                    str(raw_record["path"]),
                )
                with _open_settlement_parent_if_present(
                    root_fd,
                    relative,
                ) as binding:
                    (
                        _parent_fd,
                        _name,
                        parent_chain,
                        missing_index,
                    ) = binding
                    if missing_index is None:
                        continue
                    recursive_root = (
                        self._recursive_scope_root_for_missing_attribute_parent(
                            root_fd,
                            relative,
                            parent_chain,
                            missing_index,
                            allow_missing_below_root=True,
                        )
                    )
                    if recursive_root is None:
                        continue
                    roots.add(recursive_root)
                    changed_paths.add(relative)

        restored_parent_bindings: dict[
            str, tuple[int, int] | None
        ] = {}
        for recursive_root in _dedupe_roots(roots):
            _merge_workspace_restore_parent_bindings(
                restored_parent_bindings,
                self._restore_snapshot_root(
                    cwd,
                    recursive_root,
                    expected_parent_bindings=restored_parent_bindings,
                ),
            )
        return tuple(sorted(changed_paths)), restored_parent_bindings

    def _restore_attribute_policy(
        self,
        cwd: Path,
        *,
        defer_deleted_recursive_roots: bool = False,
    ) -> tuple[str, ...]:
        """Restore worktree attribute controls before attribute-aware Git.

        Returns changed policy paths. The caller uses that signal to force a
        full rollback even though early restoration makes Git status clean.
        """

        expected_records = self._manifest.get("attribute_policy")
        if expected_records is None:
            return ()
        current_paths = {
            _normalize_relative(cwd, path)
            for path in _attribute_policy_paths(cwd)
        }
        expected_paths = {
            str(record["path"]) for record in expected_records
        }
        changed_paths = current_paths.symmetric_difference(expected_paths)
        payloads: dict[str, bytes] = {}
        normalized_records: list[tuple[str, Mapping[str, object]]] = []
        budget = _MutationJournalArtifactBudget()
        for raw_record in expected_records:
            if not isinstance(raw_record, Mapping):
                raise MutationJournalError(
                    "Git attribute policy baseline is malformed"
                )
            relative = _normalize_relative(cwd, str(raw_record["path"]))
            normalized_records.append((relative, raw_record))
            if bool(raw_record.get("exists", True)):
                payloads[relative] = self._read_snapshot_blob_record(
                    raw_record,
                    label=f"Git attribute policy {relative}",
                    budget=budget,
                )

        def remove_bound(
            root_fd: int,
            relative: str,
        ) -> bool:
            with _open_settlement_parent_if_present(
                root_fd,
                relative,
            ) as binding:
                parent_fd, name, parent_chain, missing_index = binding
                if missing_index is not None:
                    return False
                try:
                    metadata = os.stat(
                        name,
                        dir_fd=parent_fd,
                        follow_symlinks=False,
                    )
                except FileNotFoundError:
                    _assert_settlement_parent_binding(
                        root_fd,
                        relative,
                        parent_fd,
                        parent_chain,
                    )
                    try:
                        os.stat(
                            name,
                            dir_fd=parent_fd,
                            follow_symlinks=False,
                        )
                    except FileNotFoundError:
                        _assert_settlement_parent_binding(
                            root_fd,
                            relative,
                            parent_fd,
                            parent_chain,
                        )
                        return False
                    raise MutationJournalError(
                        "Git attribute policy appeared during absence proof: "
                        f"{relative}"
                    ) from None
                if stat.S_ISDIR(metadata.st_mode) and not stat.S_ISLNK(
                    metadata.st_mode
                ):
                    raise MutationJournalError(
                        "refusing to recursively replace Git attribute policy: "
                        f"{relative}"
                    )
                _remove_bound_workspace_entry(
                    root_fd,
                    relative,
                    parent_fd,
                    name,
                    parent_chain,
                )
                return True

        with _bound_workspace_restore_root(self) as root_fd:
            for relative in sorted(current_paths.difference(expected_paths)):
                remove_bound(root_fd, relative)

            for relative, record in normalized_records:
                exists = bool(record.get("exists", True))
                if not exists:
                    if remove_bound(root_fd, relative):
                        changed_paths.add(relative)
                    continue
                payload = payloads[relative]
                mode = record.get("mode")
                if (
                    isinstance(mode, bool)
                    or not isinstance(mode, int)
                    or not 0 <= mode <= 0o7777
                ):
                    raise MutationJournalError(
                        f"Git attribute policy mode is malformed: {relative}"
                    )
                xattrs = _validated_restore_xattrs(
                    record.get("xattrs", {}),
                    label=f"Git attribute policy {relative}",
                )
                with _open_settlement_parent_if_present(
                    root_fd,
                    relative,
                ) as binding:
                    parent_fd, name, parent_chain, missing_index = binding
                    metadata: os.stat_result | None
                    if missing_index is not None:
                        metadata = None
                        if defer_deleted_recursive_roots and (
                            self._recursive_scope_root_for_missing_attribute_parent(
                                root_fd,
                                relative,
                                parent_chain,
                                missing_index,
                                allow_missing_below_root=False,
                            )
                            is not None
                        ):
                            changed_paths.add(relative)
                            continue
                    else:
                        metadata = os.stat(
                            name,
                            dir_fd=parent_fd,
                            follow_symlinks=False,
                        )
                    matches = False
                    if (
                        metadata is not None
                        and stat.S_ISREG(metadata.st_mode)
                        and metadata.st_nlink == 1
                        and stat.S_IMODE(metadata.st_mode) == mode
                        and metadata.st_size == len(payload)
                    ):
                        observed, opened = _read_bound_regular_entry(
                            parent_fd,
                            name,
                            label=f"Git attribute policy {relative}",
                            max_bytes=max(len(payload), 1),
                        )
                        matches = (
                            observed == payload
                            and _xattr_inventory(
                                Path(_authority_descriptor_cwd(parent_fd))
                                / name
                            )
                            == xattrs
                            and (opened.st_dev, opened.st_ino)
                            == (metadata.st_dev, metadata.st_ino)
                        )
                    if matches:
                        _assert_settlement_parent_binding(
                            root_fd,
                            relative,
                            parent_fd,
                            parent_chain,
                        )
                        continue
                changed_paths.add(relative)
                remove_bound(root_fd, relative)
                with _open_settlement_parent_if_present(
                    root_fd,
                    relative,
                ) as absence:
                    _parent_fd, _name, parent_chain, missing_index = absence
                    if missing_index is not None:
                        raise MutationJournalError(
                            "Git attribute policy parent disappeared: "
                            f"{relative}"
                        )
                _install_bound_workspace_entry(
                    root_fd,
                    relative,
                    expected_parent_chain=parent_chain,
                    kind="file",
                    mode=mode,
                    xattrs=xattrs,
                    payload=payload,
                )
        return tuple(sorted(changed_paths))

    def _assert_nested_worktree_unchanged(self) -> None:
        expected = self._manifest.get("tracked_worktree_inventory")
        if expected is None:
            return
        self._assert_nested_worktree_metadata_unchanged()
        cwd = self._bound_workspace_cwd()
        expected_status_hex = self._manifest.get("guard_status")
        expected_status = (
            bytes.fromhex(str(expected_status_hex))
            if expected_status_hex is not None else b""
        )
        if _nested_clean_status(
            cwd,
            excluded_roots=self._manifest.get("opaque_gitlink_roots", ()),
        ) != expected_status:
            raise MutationJournalError(
                f"nested Git worktree status changed during slice {self.slice_id}"
            )
    def _assert_nested_worktree_metadata_unchanged(self) -> None:
        expected = self._manifest.get("tracked_worktree_inventory")
        if expected is None:
            return
        cwd = self._bound_workspace_cwd()
        current = _tracked_worktree_inventory_for_paths(
            cwd,
            paths=expected,
            gitlinks=self._manifest.get("gitlinks", ()),
        )
        if self._manifest.get("opaque_gitlink_roots"):
            current = _structural_worktree_inventory(current)
        expected_preflight = json.loads(json.dumps(expected))
        current_preflight = json.loads(json.dumps(current))
        for inventory in (expected_preflight, current_preflight):
            root_record = inventory.get(".")
            if isinstance(root_record, dict):
                # The exact directory snapshot owns the checkout-root mode.
                # Pre-root admission may have added owner read/search before
                # this metadata-only guard runs; all other root metadata and
                # every tracked descendant remain fail-closed here.
                root_record.pop("mode", None)
        if current_preflight != expected_preflight:
            raise MutationJournalError(
                f"nested Git worktree metadata changed during slice {self.slice_id}"
            )

    def _preflight_nested_restore(self) -> None:
        if self._manifest.get("external_worktree_guard"):
            self._assert_nested_worktree_unchanged()
        else:
            self._assert_nested_worktree_metadata_unchanged()
        nested_journals = self._nested_journals()
        with ExitStack() as nested_authorities:
            for nested in nested_journals:
                nested_authorities.enter_context(
                    nested._nested_restore_authority()
                )
            for nested in nested_journals:
                nested._preflight_nested_restore()

    def assert_exact_baseline(self) -> None:
        """Assert that a guard-only nested checkout remains at its baseline."""

        self._require_writer_epoch_quiescence(frontier="exact baseline proof")
        self.assert_head_unchanged()
        self.assert_repository_metadata_unchanged()
        self.assert_index_unchanged()
        self._assert_nested_worktree_unchanged()

    @property
    def created_ns(self) -> int:
        return int(self._manifest["created_ns"])

    @property
    def slice_id(self) -> str:
        return str(self._manifest["slice_id"])

    @property
    def transaction_id(self) -> str:
        return self._transaction_id

    @property
    def state(self) -> str:
        return str(self._manifest["state"])

    @property
    def active(self) -> bool:
        return self.state not in {"committed", "rolled_back"}

    @property
    def cleanup_pending(self) -> bool:
        """Whether this object still owns mutation or registry cleanup.

        A rollback/commit writes its terminal state before unlinking the
        common-directory registry marker.  If that unlink fails, the workspace
        bytes are settled but topology changes must remain blocked and the
        in-memory journal is still the only exact retry authority.
        """

        if self.active:
            return True
        parent_fd: int | None = None
        try:
            parent_fd, parent_opened = _open_authority_directory(
                self._logical_journal_dir.parent,
                label="terminal cleanup pending parent",
            )
            if (
                self._logical_journal_parent_identity is not None
                and (parent_opened.st_dev, parent_opened.st_ino)
                != self._logical_journal_parent_identity
            ):
                return True
            receipt = _terminal_cleanup_receipt_at(
                parent_fd,
                self._logical_journal_dir.parent,
                self.transaction_id,
            )
            if receipt is not None:
                journal_pending = receipt.target_name is not None
            else:
                try:
                    self._logical_journal_dir.lstat()
                except FileNotFoundError:
                    journal_pending = False
                except OSError:
                    journal_pending = True
                else:
                    journal_pending = True
        except (
            KeyError,
            OSError,
            RuntimeError,
            TypeError,
            ValueError,
            MutationJournalError,
        ):
            return True
        finally:
            if parent_fd is not None:
                os.close(parent_fd)
        try:
            marker = self._registry_marker()
        except (
            KeyError,
            OSError,
            RuntimeError,
            TypeError,
            ValueError,
            MutationJournalError,
        ):
            return True
        if marker is None:
            return journal_pending
        try:
            marker.lstat()
        except FileNotFoundError:
            return journal_pending
        except OSError:
            return True
        return True

    def retry_cleanup(self) -> bool:
        """Retry rollback or terminal registry-marker cleanup."""

        if self._setup_registration_pending:
            try:
                _retain_published_setup_journal(self)
            except BaseException:
                logger.exception(
                    "mutation journal %s: setup registration authority "
                    "cannot be rebuilt",
                    self.journal_dir,
                )
                return False
        if not self.cleanup_pending:
            if not self.active:
                _unregister_terminal_live(self.transaction_id)
            return True
        if not self.active:
            parent_fd: int | None = None
            try:
                parent_fd, parent_opened = _open_authority_directory(
                    self._logical_journal_dir.parent,
                    label="terminal cleanup retry parent",
                )
                if (
                    self._logical_journal_parent_identity is not None
                    and (parent_opened.st_dev, parent_opened.st_ino)
                    != self._logical_journal_parent_identity
                ):
                    raise MutationJournalError(
                        "terminal cleanup retry parent changed identity"
                    )
                receipt = _terminal_cleanup_receipt_at(
                    parent_fd,
                    self._logical_journal_dir.parent,
                    self.transaction_id,
                )
                if receipt is not None:
                    if (
                        self._logical_journal_identity is None
                        or (
                            receipt.journal_device,
                            receipt.journal_inode,
                        )
                        != self._logical_journal_identity
                        or receipt.manifest != self._manifest
                    ):
                        raise MutationJournalError(
                            "terminal cleanup retry receipt conflicts with "
                            "the retained journal authority"
                        )
                    self._bind_terminal_cleanup_epoch_proof(
                        receipt.writer_epoch_terminal_proof
                    )
            except MutationJournalError:
                logger.exception(
                    "mutation journal %s: terminal receipt cannot authorize "
                    "cleanup retry",
                    self.journal_dir,
                )
                return False
            finally:
                if parent_fd is not None:
                    os.close(parent_fd)
        try:
            self._require_writer_epoch_quiescence(
                frontier="terminal cleanup retry"
            )
        except MutationJournalError:
            logger.exception(
                "mutation journal %s: writer epoch blocks cleanup",
                self.journal_dir,
            )
            return False
        if self.active:
            return self.restore()
        try:
            _cleanup_terminal_mutation_journal(self)
        except BaseException:
            logger.exception(
                "mutation journal %s: terminal cleanup failed; owner retained",
                self.journal_dir,
            )
            return False
        return not self.cleanup_pending

    @property
    def parent_transaction_id(self) -> str | None:
        parent = self._manifest.get("parent_transaction_id")
        return str(parent) if parent is not None else None

    @contextmanager
    def _bound_writer_epoch_journal_directory(
        self,
    ) -> Iterator[tuple[Path, int]]:
        """Hold this journal's exact directory for epoch persistence."""

        if self._discovery_binding is not None:
            with _bound_mutation_journal_directory(
                self,
                verify_manifest_payload=False,
            ) as (artifact_dir, bound_journal_fd, _parent_fd, _entry_name):
                yield artifact_dir, bound_journal_fd
            return

        logical = self._logical_journal_dir
        parent_fd, parent_opened = _open_authority_directory(
            logical.parent,
            label="writer epoch journal parent",
        )
        journal_fd: int | None = None
        try:
            if (
                self._logical_journal_parent_identity is None
                or (parent_opened.st_dev, parent_opened.st_ino)
                != self._logical_journal_parent_identity
            ):
                raise MutationJournalError(
                    "writer epoch journal parent changed identity"
                )
            journal_fd, opened = _open_authority_directory_at(
                parent_fd,
                logical.name,
                label="writer epoch journal",
            )
            if (
                self._logical_journal_identity is None
                or (opened.st_dev, opened.st_ino)
                != self._logical_journal_identity
            ):
                raise MutationJournalError(
                    "writer epoch journal changed identity"
                )
            yield Path(_authority_descriptor_cwd(journal_fd)), journal_fd
            current = os.stat(
                logical.name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
            if (current.st_dev, current.st_ino) != (
                opened.st_dev,
                opened.st_ino,
            ):
                raise MutationJournalError(
                    "writer epoch journal changed while held"
                )
            _assert_authority_directory_binding(
                logical.parent,
                parent_fd,
                parent_opened,
                label="writer epoch journal parent",
            )
        finally:
            if journal_fd is not None:
                os.close(journal_fd)
            os.close(parent_fd)

    def read_writer_epoch_record(self) -> object:
        """Freshly read this journal's durable epoch record."""

        with self._manifest_lock:
            if self._terminal_cleanup_epoch_proof is not None:
                return json.loads(json.dumps(
                    self._terminal_cleanup_epoch_proof.epoch_record,
                    sort_keys=True,
                    separators=(",", ":"),
                ))
            with self._bound_writer_epoch_journal_directory() as (
                artifact_dir,
                journal_fd,
            ):
                observed = _load_mutation_journal_manifest_at(
                    journal_fd,
                    artifact_dir,
                )
                if observed.get("transaction_id") != self._transaction_id:
                    raise MutationJournalError(
                        "writer epoch manifest transaction identity changed"
                    )
                self._manifest = observed
                return json.loads(json.dumps(
                    observed.get(WRITER_EPOCH_MANIFEST_KEY),
                    sort_keys=True,
                    separators=(",", ":"),
                ))

    def read_writer_epoch_terminal_proofs(self) -> tuple[object, ...]:
        """Freshly read root-retained children-first terminal proofs."""

        if self._terminal_cleanup_epoch_proof is None:
            self.read_writer_epoch_record()
        return _writer_epoch_terminal_proof_records(self._manifest)

    def _bind_writer_epoch_recovery_proof(
        self,
        proof: "_writer_epoch_module.WriterEpochTerminalProof",
    ) -> None:
        """Use one parsed recovery certificate as immutable epoch storage."""

        expected = _writer_epoch_manifest_proof(
            self._manifest,
            terminal_state=proof.terminal_state,
        )
        if proof.to_record() != expected.to_record():
            raise MutationJournalError(
                "terminal cleanup writer epoch proof differs from manifest"
            )
        self._terminal_cleanup_epoch_proof = proof

    def _bind_terminal_cleanup_epoch_proof(
        self,
        proof: "_writer_epoch_module.WriterEpochTerminalProof",
    ) -> None:
        """Bind the recovery proof carried by a terminal cleanup receipt."""

        self._bind_writer_epoch_recovery_proof(proof)

    def validate_writer_epoch_prearm_family(
        self,
        expected_epoch: object,
        replacement_family: tuple[tuple[str, str | None], ...],
    ) -> None:
        """Freshly authenticate root generation-zero family authority."""

        with self._manifest_lock:
            with self._bound_writer_epoch_journal_directory() as (
                artifact_dir,
                journal_fd,
            ):
                observed = _load_mutation_journal_manifest_at(
                    journal_fd,
                    artifact_dir,
                )
                if observed.get("transaction_id") != self._transaction_id:
                    raise MutationJournalError(
                        "writer epoch manifest transaction identity changed"
                    )
                if observed.get(WRITER_EPOCH_MANIFEST_KEY) != expected_epoch:
                    raise MutationJournalError(
                        "writer epoch changed during pre-arm family validation"
                    )
                previous_family = _generation_zero_writer_epoch_family(
                    observed
                )
                if previous_family[0] != (self.transaction_id, None):
                    raise MutationJournalError(
                        "writer epoch pre-arm validator is not the family root"
                    )
                _writer_epoch_module._validate_generation_zero_family_transition(
                    epoch_record=expected_epoch,
                    previous_family=previous_family,
                    replacement_family=replacement_family,
                    terminal_proofs=_writer_epoch_terminal_proof_records(
                        observed
                    ),
                )

    def compare_and_write_writer_epoch_record(
        self,
        expected: object,
        replacement: dict[str, object],
    ) -> object:
        """Durably CAS, fsync, and reread one writer-epoch transition."""

        if not isinstance(replacement, dict):
            raise TypeError("writer epoch replacement must be a dict")
        replacement_copy = cast(dict[str, object], json.loads(json.dumps(
            replacement,
            sort_keys=True,
            separators=(",", ":"),
        )))
        with self._manifest_lock:
            with self._bound_writer_epoch_journal_directory() as (
                artifact_dir,
                journal_fd,
            ):
                # ``_manifest_lock`` serializes threads only.  The directory
                # flock closes the read/check/replace window across forked or
                # independently started workers that share this exact journal
                # inode.  A contender must reread after acquiring it, so two
                # CAS operations from one expected record cannot both publish.
                import fcntl  # noqa: PLC0415

                fcntl.flock(journal_fd, fcntl.LOCK_EX)
                try:
                    manifest_payload, manifest_metadata = (
                        _read_bound_regular_entry(
                            journal_fd,
                            _MANIFEST,
                            label="writer epoch manifest",
                            max_bytes=_MUTATION_JOURNAL_MAX_MANIFEST_BYTES,
                        )
                    )
                    try:
                        current_manifest = json.loads(manifest_payload)
                    except (UnicodeError, ValueError, TypeError) as exc:
                        raise MutationJournalError(
                            "writer epoch manifest is malformed"
                        ) from exc
                    if (
                        not isinstance(current_manifest, dict)
                        or current_manifest.get("schema") != _SCHEMA
                    ):
                        raise MutationJournalError(
                            "writer epoch manifest schema changed"
                        )
                    if current_manifest.get("transaction_id") != (
                        self.transaction_id
                    ):
                        raise MutationJournalError(
                            "writer epoch manifest transaction identity changed"
                        )
                    current_state = current_manifest.get("state")
                    if current_state not in {
                        "invoking",
                        "scoped",
                        "prepared_keep",
                        "prepared_rollback",
                    }:
                        raise MutationJournalError(
                            "writer epoch manifest is terminal or inactive"
                        )
                    current = current_manifest.get(WRITER_EPOCH_MANIFEST_KEY)
                    if current != expected:
                        raise MutationJournalError(
                            "writer epoch compare-and-write observed foreign state"
                        )
                    try:
                        parsed_current = _writer_epoch_module._parse_epoch_record(
                            current
                        )
                        parsed_replacement = (
                            _writer_epoch_module._parse_epoch_record(
                                replacement_copy
                            )
                        )
                    except (TypeError, ValueError) as exc:
                        raise MutationJournalError(
                            f"writer epoch CAS authority is UNKNOWN: {exc}"
                        ) from exc
                    if (
                        parsed_current.state == "never_armed"
                        and parsed_replacement.state == "armed"
                    ):
                        previous_family = _generation_zero_writer_epoch_family(
                            current_manifest
                        )
                        if previous_family[0] == (self.transaction_id, None):
                            _writer_epoch_module._validate_generation_zero_family_transition(
                                epoch_record=current,
                                previous_family=previous_family,
                                replacement_family=tuple(
                                    (
                                        member.transaction_id,
                                        member.parent_transaction_id,
                                    )
                                    for member in parsed_replacement.family
                                ),
                                terminal_proofs=(
                                    _writer_epoch_terminal_proof_records(
                                        current_manifest
                                    )
                                ),
                            )
                    current_manifest[
                        WRITER_EPOCH_MANIFEST_KEY
                    ] = replacement_copy
                    observed = _compare_replace_bound_manifest_at(
                        journal_fd,
                        artifact_dir,
                        expected_payload=manifest_payload,
                        expected_metadata=manifest_metadata,
                        replacement=current_manifest,
                    )
                    if self._discovery_binding is not None:
                        self._discovery_binding = replace(
                            self._discovery_binding,
                            manifest_metadata=(
                                _journal_manifest_metadata(journal_fd)
                            ),
                        )
                    self._manifest = observed
                    durable = observed.get(WRITER_EPOCH_MANIFEST_KEY)
                    if durable != replacement_copy:
                        raise MutationJournalError(
                            "writer epoch durable record differs after CAS"
                        )
                    return json.loads(json.dumps(
                        durable,
                        sort_keys=True,
                        separators=(",", ":"),
                    ))
                finally:
                    fcntl.flock(journal_fd, fcntl.LOCK_UN)

    def _compare_and_write_pending_delete_quarantines(
        self,
        transition: Callable[
            [dict[str, object], tuple[_PendingDeleteQuarantine, ...]],
            tuple[_PendingDeleteQuarantine, ...],
        ],
    ) -> tuple[_PendingDeleteQuarantine, ...]:
        """Durably CAS one pending-delete inventory transition."""

        with self._manifest_lock:
            with self._bound_writer_epoch_journal_directory() as (
                artifact_dir,
                journal_fd,
            ):
                import fcntl  # noqa: PLC0415

                fcntl.flock(journal_fd, fcntl.LOCK_EX)
                try:
                    manifest_payload, manifest_metadata = (
                        _read_bound_regular_entry(
                            journal_fd,
                            _MANIFEST,
                            label="pending delete mutation journal manifest",
                            max_bytes=_MUTATION_JOURNAL_MAX_MANIFEST_BYTES,
                        )
                    )
                    try:
                        current_manifest = json.loads(manifest_payload)
                    except (UnicodeError, ValueError, TypeError) as exc:
                        raise MutationJournalError(
                            "pending delete mutation journal manifest is "
                            "malformed"
                        ) from exc
                    if (
                        not isinstance(current_manifest, dict)
                        or current_manifest.get("schema") != _SCHEMA
                        or current_manifest.get("transaction_id")
                        != self.transaction_id
                    ):
                        raise MutationJournalError(
                            "pending delete mutation journal identity changed"
                        )
                    if current_manifest.get("state") not in {
                        "invoking",
                        "scoped",
                        "prepared_keep",
                        "prepared_rollback",
                    }:
                        raise MutationJournalError(
                            "pending delete mutation journal is inactive"
                        )
                    current = _pending_delete_quarantines(current_manifest)
                    replacement_inventory = transition(
                        cast(dict[str, object], current_manifest),
                        current,
                    )
                    if len(replacement_inventory) > (
                        _PENDING_DELETE_QUARANTINES_MAX
                    ):
                        raise MutationJournalError(
                            "pending delete transition exceeds its receipt "
                            "ceiling"
                        )
                    replacement_records = [
                        receipt.to_record()
                        for receipt in replacement_inventory
                    ]
                    current_manifest[
                        _PENDING_DELETE_QUARANTINES_KEY
                    ] = replacement_records
                    # Parse the complete replacement before publishing it;
                    # this catches non-canonical transition code as well as
                    # scope changes raced into the durable manifest.
                    if _pending_delete_quarantines(current_manifest) != (
                        replacement_inventory
                    ):
                        raise MutationJournalError(
                            "pending delete transition is not canonical"
                        )
                    if replacement_inventory == current:
                        # Exact no-op transitions are used to recover the
                        # narrow interruption window after an arm was made
                        # durable but before its caller registered the
                        # receipt for settlement.  Do not rewrite the
                        # manifest (and therefore do not manufacture a new
                        # CAS generation) for that retry.
                        self._manifest = current_manifest
                        return current
                    observed = _compare_replace_bound_manifest_at(
                        journal_fd,
                        artifact_dir,
                        expected_payload=manifest_payload,
                        expected_metadata=manifest_metadata,
                        replacement=current_manifest,
                    )
                    if self._discovery_binding is not None:
                        self._discovery_binding = replace(
                            self._discovery_binding,
                            manifest_metadata=(
                                _journal_manifest_metadata(journal_fd)
                            ),
                        )
                    self._manifest = observed
                    durable = _pending_delete_quarantines(observed)
                    if durable != replacement_inventory:
                        raise MutationJournalError(
                            "pending delete receipt differs after durable CAS"
                        )
                    return durable
                finally:
                    fcntl.flock(journal_fd, fcntl.LOCK_UN)

    def arm_pending_delete_quarantine(
        self,
        *,
        token: str,
        target_relative: str,
        parent_chain: object | None = None,
        boot_id: object | None = None,
        workspace_root_descriptor: int | None = None,
    ) -> dict[str, object]:
        """Reserve one exact delete mapping before any quarantine mutation."""

        def transition(
            manifest: dict[str, object],
            current: tuple[_PendingDeleteQuarantine, ...],
        ) -> tuple[_PendingDeleteQuarantine, ...]:
            canonical_target = _settlement_relative_path(target_relative)
            if canonical_target != target_relative:
                raise MutationJournalError(
                    "pending delete target is not canonically relative"
                )
            _authenticate_pending_delete_root_descriptor(
                manifest,
                workspace_root_descriptor,
            )
            current_boot_id = _pending_delete_boot_id()
            captured_boot_id = (
                current_boot_id if boot_id is None else boot_id
            )
            if captured_boot_id != current_boot_id:
                raise MutationJournalError(
                    "pending delete arm boot identity is not current"
                )
            provisional = _PendingDeleteQuarantine(
                token=token,
                target_relative=canonical_target,
                quarantine_relative=_pending_delete_quarantine_relative(
                    canonical_target,
                    token,
                ),
                parent_chain=(),
                state="reserved",
                quarantine_device=None,
                quarantine_inode=None,
                quarantine_mode=None,
                quarantine_mount_id=None,
                child_pid=None,
                child_start_ticks=None,
                boot_id=current_boot_id,
            )
            if parent_chain is None:
                with _open_pending_delete_parent(
                    Path(str(manifest["cwd"])),
                    provisional,
                    root_descriptor=workspace_root_descriptor,
                    verify_receipt_chain=False,
                ) as (*_unused, observed_parent_chain):
                    captured_parent_chain: object = [
                        list(identity) for identity in observed_parent_chain
                    ]
            else:
                try:
                    captured_parent_chain = json.loads(json.dumps(
                        parent_chain,
                        sort_keys=True,
                        separators=(",", ":"),
                    ))
                except (TypeError, ValueError) as exc:
                    raise MutationJournalError(
                        "pending delete parent chain is not serializable"
                    ) from exc
            receipt_record = {
                **provisional.to_record(),
                "parent_chain": captured_parent_chain,
                "boot_id": captured_boot_id,
            }
            # Parsing authenticates the exact journal scope root as part of
            # the same locked durable transition.
            receipt = _parse_pending_delete_quarantine(
                receipt_record,
                manifest=manifest,
            )
            if current:
                if current == (receipt,):
                    return current
                raise MutationJournalError(
                    "a pending delete quarantine is already armed"
                )
            _assert_pending_delete_quarantine_absent(
                Path(str(manifest["cwd"])),
                receipt,
                root_descriptor=workspace_root_descriptor,
            )
            return (receipt,)

        durable = self._compare_and_write_pending_delete_quarantines(
            transition
        )
        return durable[0].to_record()

    def bind_pending_delete_quarantine(
        self,
        expected: Mapping[str, object],
        *,
        quarantine_device: int,
        quarantine_inode: int,
        quarantine_mode: int,
        quarantine_mount_id: int,
        child_pid: int,
        child_start_ticks: int,
        boot_id: str,
        workspace_root_descriptor: int | None = None,
        parent_descriptor: int | None = None,
    ) -> dict[str, object]:
        """Bind the precreated empty qdir before acknowledging the child."""

        expected_copy = cast(dict[str, object], json.loads(json.dumps(
            expected,
            sort_keys=True,
            separators=(",", ":"),
        )))

        def transition(
            manifest: dict[str, object],
            current: tuple[_PendingDeleteQuarantine, ...],
        ) -> tuple[_PendingDeleteQuarantine, ...]:
            parsed_expected = _parse_pending_delete_quarantine(
                expected_copy,
                manifest=manifest,
            )
            if parsed_expected.state != "reserved":
                raise MutationJournalError(
                    "pending delete bind expected a reserved receipt"
                )
            _authenticate_pending_delete_root_descriptor(
                manifest,
                workspace_root_descriptor,
            )
            if boot_id != parsed_expected.boot_id:
                raise MutationJournalError(
                    "pending delete bind changed its armed boot identity"
                )
            bound = replace(
                parsed_expected,
                state="bound",
                quarantine_device=quarantine_device,
                quarantine_inode=quarantine_inode,
                quarantine_mode=quarantine_mode,
                quarantine_mount_id=quarantine_mount_id,
                child_pid=child_pid,
                child_start_ticks=child_start_ticks,
            )
            bound = _parse_pending_delete_quarantine(
                bound.to_record(),
                manifest=manifest,
            )
            if current not in {(parsed_expected,), (bound,)}:
                raise MutationJournalError(
                    "pending delete bind observed foreign receipt state"
                )
            _assert_bound_pending_delete_quarantine(
                Path(str(manifest["cwd"])),
                bound,
                require_empty=True,
                root_descriptor=workspace_root_descriptor,
                parent_descriptor=parent_descriptor,
            )
            if current == (bound,):
                # The first CAS may have become durable immediately before
                # its caller was interrupted.  Re-prove the complete bound
                # authority above, then make that exact retry a true no-op.
                return current
            # Child liveness authorizes only the reserved-to-bound mutation.
            # An exact already-bound retry is a read/reconciliation operation
            # and remains valid after that child exits.
            if boot_id != _pending_delete_boot_id():
                raise MutationJournalError(
                    "pending delete child belongs to another boot"
                )
            child = _pending_delete_process_identity(child_pid)
            if child is None or child[0] in {"X", "Z"} or child[1] != (
                child_start_ticks
            ):
                raise MutationJournalError(
                    "pending delete child identity is not live and exact"
                )
            return (bound,)

        durable = self._compare_and_write_pending_delete_quarantines(
            transition
        )
        return durable[0].to_record()

    def clear_pending_delete_quarantine(
        self,
        expected: Mapping[str, object],
        *,
        workspace_root_descriptor: int | None = None,
        parent_descriptor: int | None = None,
    ) -> None:
        """Clear one exact receipt only after its qdir is proved absent."""

        expected_copy = cast(dict[str, object], json.loads(json.dumps(
            expected,
            sort_keys=True,
            separators=(",", ":"),
        )))

        def transition(
            manifest: dict[str, object],
            current: tuple[_PendingDeleteQuarantine, ...],
        ) -> tuple[_PendingDeleteQuarantine, ...]:
            parsed_expected = _parse_pending_delete_quarantine(
                expected_copy,
                manifest=manifest,
            )
            if current not in {(), (parsed_expected,)}:
                raise MutationJournalError(
                    "pending delete clear observed foreign receipt state"
                )
            _authenticate_pending_delete_root_descriptor(
                manifest,
                workspace_root_descriptor,
            )
            _assert_pending_delete_quarantine_absent(
                Path(str(manifest["cwd"])),
                parsed_expected,
                root_descriptor=workspace_root_descriptor,
                parent_descriptor=parent_descriptor,
            )
            # Empty inventory is the exact postcondition of this operation.
            # Accept it only after re-authenticating the root and proving the
            # deterministic qdir absent, so a post-CAS interruption can be
            # retried without another manifest generation.
            return ()

        self._compare_and_write_pending_delete_quarantines(transition)

    def _require_writer_epoch_quiescence(self, *, frontier: str) -> None:
        """Fail before a source/Git frontier unless writer authority settled.

        Root quiescence is a durable family certificate: the epoch state
        machine writes descendants first, rechecks that every member remains
        active before each CAS, writes the root last, and then proves identical
        records.  Cleanup may therefore remove children sequentially while the
        still-present root authenticates their exact receipt.  A child never
        treats a missing root as safe.
        """

        try:
            raw = self.read_writer_epoch_record()
            parsed = _writer_epoch_module._parse_epoch_record(raw)
        except BaseException as exc:
            raise MutationJournalError(
                f"writer epoch is UNKNOWN before {frontier}: "
                f"{type(exc).__name__}: {exc}"
            ) from exc

        if parsed.state == "armed":
            raise MutationJournalError(
                f"writer epoch remains armed before {frontier}"
            )

        def authenticated_terminal_ids(
            root: WriterEpochStorage,
            *,
            expected_family: tuple[tuple[str, str | None], ...],
            expected_digest: str | None,
        ) -> set[str]:
            """Return exact root-certified terminal members for this epoch."""

            try:
                root_raw = root.read_writer_epoch_record()
                if root_raw != raw:
                    raise MutationJournalError(
                        f"writer epoch root certificate differs before {frontier}"
                    )
                root_parsed = _writer_epoch_module._parse_epoch_record(root_raw)
                if root_parsed.state == "quiesced":
                    root_family = tuple(
                        (
                            member.transaction_id,
                            member.parent_transaction_id,
                        )
                        for member in root_parsed.family
                    )
                elif root_parsed.state == "never_armed":
                    root_manifest = getattr(root, "_manifest", None)
                    if not isinstance(root_manifest, Mapping):
                        raise MutationJournalError(
                            "generation-zero writer epoch root lacks a durable "
                            f"family projection before {frontier}"
                        )
                    root_family = _generation_zero_writer_epoch_family(
                        root_manifest
                    )
                else:
                    raise MutationJournalError(
                        f"writer epoch root is not quiescent before {frontier}"
                    )
                if root_family != expected_family:
                    raise MutationJournalError(
                        f"writer epoch root family differs before {frontier}"
                    )
                proof_reader = getattr(
                    root,
                    "read_writer_epoch_terminal_proofs",
                    None,
                )
                if not callable(proof_reader):
                    raise MutationJournalError(
                        "writer epoch root lacks terminal-proof authority "
                        f"before {frontier}"
                    )
                proof_records = proof_reader()
                proofs = tuple(
                    _writer_epoch_module.parse_writer_epoch_terminal_proof(
                        record
                    )
                    for record in proof_records
                )
            except MutationJournalError:
                raise
            except BaseException as exc:
                raise MutationJournalError(
                    "writer epoch terminal proofs are UNKNOWN before "
                    f"{frontier}: {exc}"
                ) from exc
            family_parents = dict(expected_family)
            return {
                proof.transaction_id
                for proof in proofs
                if (
                    proof.epoch_record == raw
                    and proof.transaction_id in family_parents
                    and proof.parent_transaction_id
                    == family_parents[proof.transaction_id]
                    and proof.family == expected_family
                    and (
                        expected_digest is None
                        or proof.family_digest == expected_digest
                    )
                )
            }

        if parsed.state == "never_armed":
            family_ids = tuple(sorted({
                str(transaction_id)
                for transaction_id in self._manifest.get(
                    "writer_epoch_family",
                    (self.transaction_id,),
                )
            } | {self.transaction_id}))
            family_parents = {
                str(transaction_id): (
                    str(parent) if parent is not None else None
                )
                for transaction_id, parent in self._manifest.get(
                    "writer_epoch_family_parents",
                    {},
                ).items()
            }
            if set(family_parents) != set(family_ids):
                raise MutationJournalError(
                    f"writer epoch family topology is incomplete before {frontier}"
                )
            registry_ids = {
                str(transaction_id)
                for transaction_id in self._manifest.get(
                    "registry_transaction_family",
                    (),
                )
            }
            registry_parents = {
                str(transaction_id): (
                    str(parent) if parent is not None else None
                )
                for transaction_id, parent in self._manifest.get(
                    "registry_family_parents",
                    {},
                ).items()
            }
            if (
                not registry_ids
                or not registry_ids.issubset(family_ids)
                or registry_parents != {
                    transaction_id: family_parents[transaction_id]
                    for transaction_id in registry_ids
                }
            ):
                raise MutationJournalError(
                    f"writer epoch family projection differs before {frontier}"
                )
            with _LIVE_TRANSACTIONS_LOCK:
                available = _writer_epoch_available_members_locked(self)
            roots = tuple(
                transaction_id
                for transaction_id, parent in family_parents.items()
                if parent is None
            )
            if len(roots) != 1 or roots[0] not in available:
                raise MutationJournalError(
                    f"writer epoch root is missing before {frontier}"
                )
            root_id = roots[0]
            prearm_root = available[root_id]
            expected_family = self._writer_epoch_family_pairs(parsed)
            initially_present = {
                transaction_id
                for transaction_id in family_ids
                if transaction_id in available
                and (
                    available[transaction_id].active
                    or transaction_id == root_id
                )
            }
            if initially_present == set(family_ids):
                certified_terminal_ids: set[str] = set()
            else:
                certified_terminal_ids = authenticated_terminal_ids(
                    prearm_root,
                    expected_family=expected_family,
                    expected_digest=None,
                )
            if registry_ids.union(certified_terminal_ids) != set(family_ids):
                raise MutationJournalError(
                    f"writer epoch family projection differs before {frontier}"
                )
            with _LIVE_TRANSACTIONS_LOCK:
                # ``registry_ids`` is the durable family projection, not
                # proof that every member is still physically present.  A
                # children-first terminal cleanup can durably certify and
                # remove one child before the root acknowledges that member
                # in its manifest.  Treat only retained exact owners as
                # present; the missing-member path below then requires the
                # child's authenticated root-retained terminal proof.
                present_ids = {
                    transaction_id
                    for transaction_id in family_ids
                    if transaction_id in available
                    and (
                        available[transaction_id].active
                        or transaction_id == root_id
                        or transaction_id not in certified_terminal_ids
                    )
                }
                members = tuple(
                    available[transaction_id]
                    for transaction_id in sorted(present_ids)
                    if transaction_id in available
                )
            if len(members) != len(present_ids):
                raise MutationJournalError(
                    f"writer epoch family is incomplete before {frontier}"
                )
            if any(
                member.parent_transaction_id
                != family_parents[member.transaction_id]
                for member in members
            ):
                raise MutationJournalError(
                    f"writer epoch family topology differs before {frontier}"
                )
            try:
                require_writer_epoch_quiescence(
                    cast(tuple[WriterEpochStorage, ...], members),
                    allow_never_armed=True,
                )
            except WriterEpochBlockedError as exc:
                raise MutationJournalError(
                    f"writer epoch family blocks {frontier}: {exc}"
                ) from exc
            missing = set(family_ids).difference(present_ids)
            if missing:
                for transaction_id in missing:
                    if transaction_id not in certified_terminal_ids:
                        raise MutationJournalError(
                            "never-armed writer epoch family lacks an "
                            "authenticated terminal proof for "
                            f"{transaction_id!r} before {frontier}"
                        )
            return
        if parsed.state != "quiesced":
            raise MutationJournalError(
                f"writer epoch has unsupported state before {frontier}: "
                f"{parsed.state}"
            )

        family = parsed.family
        by_id = {
            member.transaction_id: member.parent_transaction_id
            for member in family
        }
        if (
            len(by_id) != len(family)
            or self.transaction_id not in by_id
        ):
            raise MutationJournalError(
                f"writer epoch family is malformed before {frontier}"
            )
        roots = tuple(
            transaction_id
            for transaction_id, parent in by_id.items()
            if parent is None
        )
        if len(roots) != 1:
            raise MutationJournalError(
                f"writer epoch family lacks one root before {frontier}"
            )
        root_id = roots[0]
        for transaction_id, parent in by_id.items():
            if transaction_id != root_id and parent not in by_id:
                raise MutationJournalError(
                    f"writer epoch family is disconnected before {frontier}"
                )
            visited: set[str] = set()
            cursor: str | None = transaction_id
            while cursor is not None:
                if cursor in visited:
                    raise MutationJournalError(
                        f"writer epoch family is cyclic before {frontier}"
                    )
                visited.add(cursor)
                cursor = by_id.get(cursor)
            if root_id not in visited:
                raise MutationJournalError(
                    f"writer epoch family has a foreign root before {frontier}"
                )

        with _LIVE_TRANSACTIONS_LOCK:
            available = _writer_epoch_available_members_locked(self)
        root = available.get(root_id)
        if root is None:
            raise MutationJournalError(
                f"writer epoch root is missing before {frontier}"
            )
        expected_family = tuple(
            (member.transaction_id, member.parent_transaction_id)
            for member in family
        )
        initially_live = {
            transaction_id
            for transaction_id in by_id
            if transaction_id in available
            and (
                available[transaction_id].active
                or transaction_id == root_id
            )
        }
        if initially_live == set(by_id):
            certified_terminal_ids = set()
        else:
            certified_terminal_ids = authenticated_terminal_ids(
                root,
                expected_family=expected_family,
                expected_digest=parsed.family_digest,
            )
        with _LIVE_TRANSACTIONS_LOCK:
            live_members = {
                transaction_id: available[transaction_id]
                for transaction_id in by_id
                if transaction_id in available
                and (
                    available[transaction_id].active
                    or transaction_id == root_id
                    or transaction_id not in certified_terminal_ids
                )
            }
        if len(live_members) == len(by_id):
            ordered = tuple(
                live_members[member.transaction_id] for member in family
            )
            try:
                require_writer_epoch_quiescence(
                    cast(tuple[WriterEpochStorage, ...], ordered),
                    allow_never_armed=False,
                )
            except WriterEpochBlockedError as exc:
                raise MutationJournalError(
                    f"writer epoch family blocks {frontier}: {exc}"
                ) from exc
            return

        try:
            if root.read_writer_epoch_record() != raw:
                raise MutationJournalError(
                    f"writer epoch root certificate differs before {frontier}"
                )
            for member in live_members.values():
                if member.read_writer_epoch_record() != raw:
                    raise MutationJournalError(
                        f"writer epoch member differs before {frontier}"
                    )
            proof_records = root.read_writer_epoch_terminal_proofs()
            tuple(
                _writer_epoch_module.parse_writer_epoch_terminal_proof(record)
                for record in proof_records
            )
        except MutationJournalError:
            raise
        except BaseException as exc:
            raise MutationJournalError(
                f"writer epoch terminal proofs are UNKNOWN before {frontier}: "
                f"{exc}"
            ) from exc
        missing = set(by_id).difference(live_members)
        for transaction_id in missing:
            if transaction_id not in certified_terminal_ids:
                raise MutationJournalError(
                    "writer epoch family lacks an authenticated terminal "
                    f"proof for {transaction_id!r} before {frontier}"
                )

    def _writer_epoch_family_pairs(
        self,
        parsed: object,
    ) -> tuple[tuple[str, str | None], ...]:
        """Return one canonical family from settled or generation-zero state."""

        epoch = cast("_writer_epoch_module._ParsedEpochRecord", parsed)
        if epoch.state == "quiesced":
            return tuple(
                (member.transaction_id, member.parent_transaction_id)
                for member in epoch.family
            )
        if epoch.state != "never_armed":
            raise MutationJournalError(
                "writer epoch terminal proof requires settled state"
            )
        return _generation_zero_writer_epoch_family(self._manifest)

    def _store_writer_epoch_terminal_proof(
        self,
        proof: object,
    ) -> None:
        """Persist one child proof in the still-retained family root."""

        try:
            parsed_proof = (
                _writer_epoch_module.parse_writer_epoch_terminal_proof(proof)
            )
        except (TypeError, ValueError) as exc:
            raise MutationJournalError(
                f"writer epoch terminal proof is malformed: {exc}"
            ) from exc
        with self._manifest_lock:
            root_epoch = self.read_writer_epoch_record()
            if parsed_proof.epoch_record != root_epoch:
                raise MutationJournalError(
                    "writer epoch terminal proof differs from root authority"
                )
            inventory = self._manifest.get(
                "writer_epoch_terminal_proofs",
                {},
            )
            if not isinstance(inventory, dict):
                raise MutationJournalError(
                    "writer epoch terminal proof inventory is malformed"
                )
            rendered = parsed_proof.to_record()
            existing = inventory.get(parsed_proof.transaction_id)
            if existing is not None and existing != rendered:
                raise MutationJournalError(
                    "writer epoch terminal proof conflicts with retained proof"
                )
            if existing is None:
                retained = dict(inventory)
                retained[parsed_proof.transaction_id] = rendered
                self._manifest["writer_epoch_terminal_proofs"] = retained
                self._write()
            observed = {
                cast(dict[str, object], item)["transaction_id"]: item
                for item in self.read_writer_epoch_terminal_proofs()
            }
            if observed.get(parsed_proof.transaction_id) != rendered:
                raise MutationJournalError(
                    "writer epoch terminal proof changed after persistence"
                )

    def _persist_writer_epoch_terminal_proof(self) -> None:
        """Authenticate this terminal child in its root before deletion."""

        if self.active:
            raise MutationJournalError(
                "cannot prove a non-terminal writer epoch member"
            )
        if self.state not in {"committed", "rolled_back"}:
            raise MutationJournalError(
                "writer epoch member has an unsupported terminal state"
            )
        raw = self.read_writer_epoch_record()
        try:
            parsed = _writer_epoch_module._parse_epoch_record(raw)
            family = self._writer_epoch_family_pairs(parsed)
        except (TypeError, ValueError) as exc:
            raise MutationJournalError(
                f"writer epoch is UNKNOWN before terminal proof: {exc}"
            ) from exc
        roots = tuple(
            transaction_id
            for transaction_id, parent in family
            if parent is None
        )
        if len(roots) != 1:
            raise MutationJournalError(
                "writer epoch terminal proof family lacks one root"
            )
        root_id = roots[0]
        if self.transaction_id == root_id:
            with _LIVE_TRANSACTIONS_LOCK:
                available = _writer_epoch_available_members_locked(self)
            pending_descendants = tuple(
                transaction_id
                for transaction_id, _parent in family
                if transaction_id != root_id
                and transaction_id in available
                and available[transaction_id].active
            )
            if pending_descendants:
                raise MutationJournalError(
                    "writer epoch root cleanup requires descendants first: "
                    f"{sorted(pending_descendants)!r}"
                )
            try:
                proofs = {
                    proof.transaction_id: proof
                    for proof in (
                        _writer_epoch_module.parse_writer_epoch_terminal_proof(
                            record
                        )
                        for record in self.read_writer_epoch_terminal_proofs()
                    )
                    if proof.epoch_record == raw
                }
            except (TypeError, ValueError) as exc:
                raise MutationJournalError(
                    f"writer epoch root terminal proofs are UNKNOWN: {exc}"
                ) from exc
            for transaction_id, parent in family:
                if transaction_id == root_id:
                    continue
                proof = proofs.get(transaction_id)
                if (
                    proof is None
                    or proof.parent_transaction_id != parent
                    or proof.family != family
                ):
                    raise MutationJournalError(
                        "writer epoch root cleanup lacks an exact descendant "
                        f"terminal proof: {transaction_id!r}"
                    )
            return
        with _LIVE_TRANSACTIONS_LOCK:
            available = _writer_epoch_available_members_locked(self)
            root = available.get(root_id)
        if root is None:
            raise MutationJournalError(
                "writer epoch root is missing before child terminal proof"
            )
        root_raw = root.read_writer_epoch_record()
        if root_raw != raw:
            raise MutationJournalError(
                "writer epoch root differs before child terminal proof"
            )
        try:
            proof = _writer_epoch_module.build_writer_epoch_terminal_proof(
                transaction_id=self.transaction_id,
                parent_transaction_id=self.parent_transaction_id,
                terminal_state=cast(
                    "_writer_epoch_module.WriterTerminalState",
                    self.state,
                ),
                epoch_record=raw,
                family=family,
                terminal_manifest=self._manifest,
            )
        except (
            TypeError,
            ValueError,
            _writer_epoch_module.WriterEpochBlockedError,
        ) as exc:
            raise MutationJournalError(
                f"cannot build writer epoch terminal proof: {exc}"
            ) from exc
        root._store_writer_epoch_terminal_proof(proof.to_record())

    def reparent(self, parent_transaction_id: str | None) -> None:
        """Durably rebase an active journal after its baseline is accepted."""

        if not self.active:
            raise MutationJournalError(
                f"cannot reparent inactive slice {self.slice_id}"
            )
        if parent_transaction_id == self.transaction_id:
            raise MutationJournalError("mutation journal cannot parent itself")
        self._require_writer_epoch_quiescence(frontier="journal reparent")
        try:
            epoch = _writer_epoch_module._parse_epoch_record(
                self.read_writer_epoch_record()
            )
        except BaseException as exc:
            raise MutationJournalError(
                f"writer epoch is UNKNOWN before journal reparent: {exc}"
            ) from exc
        if epoch.state != "never_armed" or epoch.generation != 0:
            raise MutationJournalError(
                "journal reparent requires a never-armed generation-zero "
                "writer epoch"
            )
        self._manifest["parent_transaction_id"] = parent_transaction_id
        self._write()
        _register_live_journal(self)

    def _write(self) -> None:
        with self._manifest_lock:
            if self._discovery_binding is None:
                write_atomic_json(self.journal_dir / _MANIFEST, self._manifest)
                return
            with _bound_mutation_journal_directory(
                self,
                verify_manifest_payload=False,
            ) as (
                artifact_dir,
                journal_fd,
                _parent_fd,
                _entry_name,
            ):
                write_atomic_json(artifact_dir / _MANIFEST, self._manifest)
                self._discovery_binding = replace(
                    self._discovery_binding,
                    manifest_metadata=_journal_manifest_metadata(journal_fd),
                )

    def _set_registry_transaction_family(
        self,
        family: Iterable[str],
        *,
        failed: Iterable[str] = (),
        parents: dict[str, str | None] | None = None,
    ) -> None:
        """Atomically merge a process-local lineage refresh into the manifest."""

        with self._manifest_lock:
            rendered_family = tuple(sorted({
                str(transaction_id) for transaction_id in family
            } | {self.transaction_id}))
            self._manifest["registry_transaction_family"] = list(
                rendered_family
            )
            self._manifest["failed_family_members"] = list(failed)
            if parents is not None:
                self._manifest["registry_family_parents"] = parents
            try:
                epoch = _writer_epoch_module._parse_epoch_record(
                    self._manifest.get(WRITER_EPOCH_MANIFEST_KEY)
                )
            except (TypeError, ValueError):
                # UNKNOWN remains fail-closed at every frontier; never repair
                # its family projection opportunistically.
                epoch = None
            if epoch is not None and epoch.state == "never_armed":
                durable_family = {
                    str(transaction_id)
                    for transaction_id in self._manifest.get(
                        "writer_epoch_family",
                        (),
                    )
                }
                durable_family.update(rendered_family)
                self._manifest["writer_epoch_family"] = sorted(
                    durable_family
                )
                durable_parents = {
                    str(transaction_id): (
                        str(parent) if parent is not None else None
                    )
                    for transaction_id, parent in self._manifest.get(
                        "writer_epoch_family_parents",
                        {},
                    ).items()
                }
                if parents is not None:
                    for transaction_id, parent in parents.items():
                        transaction_id = str(transaction_id)
                        rendered_parent = (
                            str(parent) if parent is not None else None
                        )
                        previous = durable_parents.get(transaction_id)
                        if (
                            transaction_id in durable_parents
                            and previous != rendered_parent
                            and transaction_id != self.transaction_id
                        ):
                            raise MutationJournalError(
                                "never-armed writer family parent changed "
                                f"for {transaction_id!r}"
                            )
                        durable_parents[transaction_id] = rendered_parent
                self._manifest[
                    "writer_epoch_family_parents"
                ] = durable_parents
            self._write()

    def _assert_no_failed_descendant(
        self,
        *,
        allow: Iterable[str] = (),
    ) -> None:
        allowed = {str(transaction_id) for transaction_id in allow}
        failed_family = {
            str(transaction_id)
            for transaction_id in self._manifest.get(
                "failed_family_members", ()
            )
        }
        parents = {
            str(transaction_id): (
                str(parent) if parent is not None else None
            )
            for transaction_id, parent in self._manifest.get(
                "registry_family_parents", {}
            ).items()
        }

        def is_descendant(transaction_id: str) -> bool:
            visited: set[str] = set()
            current: str | None = transaction_id
            while current is not None and current not in visited:
                if current == self.transaction_id:
                    return transaction_id != self.transaction_id
                visited.add(current)
                current = parents.get(current)
            return False

        failed = {
            transaction_id for transaction_id in failed_family
            if transaction_id not in allowed and is_descendant(transaction_id)
        }
        if failed:
            raise MutationJournalError(
                "mutation family contains an unresolved failed descendant: "
                f"{sorted(failed)!r}"
            )

    def _record_restore_failure(self) -> None:
        already_local = self.transaction_id in {
            str(transaction_id)
            for transaction_id in self._manifest.get(
                "failed_family_members", ()
            )
        }
        if not already_local:
            with self._manifest_lock:
                failed = {
                    str(transaction_id)
                    for transaction_id in self._manifest.get(
                        "failed_family_members", ()
                    )
                }
                failed.add(self.transaction_id)
                self._manifest["failed_family_members"] = sorted(failed)
                try:
                    self._write()
                except BaseException:
                    logger.exception(
                        "mutation journal %s: could not persist local failure state",
                        self.journal_dir,
                    )
        # Family propagation is a separate durable step.  Even when the local
        # latch already exists, retry it: the previous attempt may have died or
        # raised after the local write and before updating an ancestor.
        try:
            _mark_live_family_failed(self.transaction_id)
        except BaseException:
            logger.exception(
                "mutation journal %s: could not persist failed-family state",
                self.journal_dir,
            )

    def _nested_transaction_ids(self) -> set[str]:
        transaction_ids: set[str] = set()

        def collect(journal: "WorkspaceMutationJournal") -> None:
            transaction_ids.add(journal.transaction_id)
            for nested in journal._nested_journals():
                collect(nested)

        for nested in self._nested_journals():
            collect(nested)
        return transaction_ids

    def _nested_journals_for_restore(
        self,
    ) -> tuple["WorkspaceMutationJournal", ...]:
        """Resolve physical children to the exact startup-bound owners.

        A discovered parent is addressed through its held directory chain.
        Its children were also part of that same bounded startup inventory and
        carry their own discovery bindings.  Reloading them as ordinary path-
        based objects would both discard those bindings and leave the installed
        recovery objects stale after a child manifest transition.
        """

        nested = self._nested_journals()
        if self._discovery_binding is None or not nested:
            return nested
        with _LIVE_TRANSACTIONS_LOCK:
            available = _writer_epoch_available_members_locked(self)
            resolved: list[WorkspaceMutationJournal] = []
            for physical in nested:
                installed = available.get(physical.transaction_id)
                if not isinstance(installed, WorkspaceMutationJournal):
                    raise MutationJournalError(
                        "startup-bound nested mutation journal is absent from "
                        "the exact recovery inventory"
                    )
                # Reuse the collision validator that authenticates durable
                # journal and parent-directory identities before accepting a
                # separately constructed object for the same transaction.
                _writer_epoch_available_members_locked(physical)
                if (
                    physical.parent_transaction_id != self.transaction_id
                    or installed.parent_transaction_id != self.transaction_id
                ):
                    raise MutationJournalError(
                        "startup-bound nested mutation journal has foreign "
                        "parent authority"
                    )
                resolved.append(installed)
        return tuple(sorted(
            resolved,
            key=lambda item: (item.created_ns, item.transaction_id),
        ))

    def _nested_journals_children_first(
        self,
    ) -> tuple["WorkspaceMutationJournal", ...]:
        """Return the retained physical descendants in cleanup order."""

        ordered: list[WorkspaceMutationJournal] = []

        def collect(journal: "WorkspaceMutationJournal") -> None:
            for nested in journal._nested_journals_for_restore():
                collect(nested)
            ordered.append(journal)

        for nested in self._nested_journals_for_restore():
            collect(nested)
        return tuple(ordered)

    def _acknowledge_resolved_descendants(
        self,
        transaction_ids: Iterable[str],
    ) -> None:
        resolved = {str(transaction_id) for transaction_id in transaction_ids}
        if not resolved:
            return
        with self._manifest_lock:
            changed = False
            for key in (
                "registry_transaction_family",
                "failed_family_members",
            ):
                previous = [
                    str(transaction_id)
                    for transaction_id in self._manifest.get(key, ())
                ]
                current = [
                    transaction_id
                    for transaction_id in previous
                    if transaction_id not in resolved
                ]
                if current != previous:
                    self._manifest[key] = current
                    changed = True
            parents = dict(self._manifest.get("registry_family_parents", {}))
            retained_parents = {
                transaction_id: parent
                for transaction_id, parent in parents.items()
                if transaction_id not in resolved
            }
            if retained_parents != parents:
                self._manifest["registry_family_parents"] = retained_parents
                changed = True
            if changed:
                self._write()

    def assert_head_unchanged(self) -> None:
        """Reject model-authored commits/ref movement before settling writes."""

        self._require_writer_epoch_quiescence(frontier="HEAD proof")
        self._assert_git_entry_unchanged()
        cwd = self._bound_workspace_cwd()
        current = _head(cwd)
        current_ref = _symbolic_head(cwd)
        ref_changed = (
            "head_symbolic_ref" in self._manifest
            and current_ref != self._manifest["head_symbolic_ref"]
        )
        if (
            current != self._manifest["head"]
            or ref_changed
        ):
            raise MutationJournalError(
                f"slice {self.slice_id} changed Git HEAD from "
                f"{self._manifest['head']} "
                f"({self._manifest.get('head_symbolic_ref')}) to {current} "
                f"({current_ref}); model-authored "
                "commits are forbidden and the transaction will roll back"
            )

    def _nested_index_mode_repair_is_privately_confined(
        self,
        metadata: os.stat_result,
    ) -> bool:
        """Return whether a widened gitlink index remains owner-confined."""

        if not self._manifest.get("nested_gitlink_guard"):
            return False
        index = _lexical_workspace_path(Path(str(self._manifest["index_path"])))
        candidate = self
        while True:
            root = _lexical_workspace_path(Path(str(candidate._manifest["cwd"])))
            authority = _active_workspace_mutation_authority(root)
            try:
                relative = index.relative_to(root)
                if authority is None:
                    raise MutationJournalError(
                        "private index repair lacks held root authority"
                    )
                authority = _assert_workspace_mutation_authority(root)
                root_metadata = os.fstat(authority.root_descriptor)
                root_xattrs = _bound_descriptor_xattr_inventory(
                    authority.root_descriptor,
                    label=f"private index repair root {root}",
                )
            except (MutationJournalError, OSError, ValueError):
                relative = Path(".")
                root_metadata = None
                root_xattrs = None
            expected_identity = (
                candidate._manifest.get("directory_identities", {}).get(".")
                or {}
            )
            expected_mode = candidate._manifest.get(
                "directory_modes", {}
            ).get(".")
            expected_xattrs = candidate._manifest.get(
                "directory_xattrs", {}
            ).get(".")
            if (
                relative.parts
                and root_metadata is not None
                and stat.S_ISDIR(root_metadata.st_mode)
                and not stat.S_ISLNK(root_metadata.st_mode)
                and root_metadata.st_uid == os.geteuid()
                and root_metadata.st_uid == metadata.st_uid
                and root_metadata.st_dev == expected_identity.get("device")
                and root_metadata.st_ino == expected_identity.get("inode")
                and stat.S_IMODE(root_metadata.st_mode) == expected_mode
                and stat.S_IMODE(root_metadata.st_mode) & 0o077 == 0
                and isinstance(expected_xattrs, dict)
                and root_xattrs == expected_xattrs
            ):
                return True
            parent_id = candidate.parent_transaction_id
            if parent_id is None:
                return False
            try:
                candidate = _require_live_parent_transaction(parent_id)
            except MutationJournalError:
                return False

    def _nested_index_mode_repair_metadata_is_admissible(
        self,
        metadata: os.stat_result,
        *,
        expected_mode: object,
        current_mode: int,
    ) -> bool:
        """Authenticate the narrow metadata shape of nested index widening."""

        expected_identity = tuple(
            self._manifest.get(field)
            for field in ("index_device", "index_uid", "index_gid")
        )
        if any(
            type(component) is not int or component < 0
            for component in expected_identity
        ):
            # Older journals did not bind index ownership/device. They retain
            # their original fail-closed behavior for permission additions.
            return False
        if expected_identity != (
            metadata.st_dev,
            metadata.st_uid,
            metadata.st_gid,
        ):
            return False
        if type(expected_mode) is not int or not 0 <= expected_mode <= 0o7777:
            return False
        added_mode = current_mode & ~expected_mode
        return bool(
            expected_mode & ~0o666 == 0
            and expected_mode & 0o600 == 0o600
            and current_mode & expected_mode == expected_mode
            and added_mode
            and added_mode & ~0o066 == 0
            and self._nested_index_mode_repair_is_privately_confined(metadata)
        )

    def assert_index_unchanged(
        self,
        *,
        allow_nested_cache_mode_repair: bool = False,
    ) -> None:
        """Reject staged/index mutations before accepting workspace edits."""

        self._require_writer_epoch_quiescence(frontier="index proof")
        self._assert_git_entry_unchanged()
        cwd = self._bound_workspace_cwd()
        index = _index_path(cwd)
        expected_exists = bool(self._manifest["index_exists"])
        if index.is_file() != expected_exists:
            raise MutationJournalError(
                f"slice {self.slice_id} changed Git index existence"
            )
        if not expected_exists:
            return
        expected = self._read_snapshot_blob_record(
            self._manifest.get("index_blob"),
            label="Git index assertion baseline",
        )
        try:
            current_index, metadata, current_xattrs = (
                self._read_bound_git_admin_file(
                    str(self._manifest["index_path"]),
                    label="Git index assertion",
                    max_bytes=max(len(expected), 1),
                )
            )
        except MutationJournalError as exc:
            raise MutationJournalError(
                f"slice {self.slice_id} removed or replaced Git index"
            ) from exc
        for field, observed in (
            ("index_device", metadata.st_dev),
            ("index_uid", metadata.st_uid),
            ("index_gid", metadata.st_gid),
        ):
            expected_metadata = self._manifest.get(field)
            if expected_metadata is not None and observed != int(expected_metadata):
                raise MutationJournalError(
                    f"slice {self.slice_id} changed Git index {field[6:]}"
                )
        if self._manifest.get("index_semantic_views"):
            current_views = _index_semantic_views(
                cwd, index
            )
            expected_views = tuple(
                self._read_snapshot_blob_record(
                    (self._manifest.get("index_semantic_blobs") or {}).get(name),
                    label=f"Git index semantic baseline {name}",
                )
                for name in ("index_stage", "index_flags_v", "index_flags_f")
            )
            if current_views != expected_views:
                raise MutationJournalError(
                    f"slice {self.slice_id} changed staged Git index state"
                )
        else:
            # Backward compatibility for journals created before semantic
            # index-view capture was added.
            if current_index != expected:
                raise MutationJournalError(
                    f"slice {self.slice_id} changed Git index bytes"
                )
        verified_index, verified_metadata, verified_xattrs = (
            self._read_bound_git_admin_file(
                str(self._manifest["index_path"]),
                label="Git index post-semantic assertion",
                max_bytes=max(len(expected), 1),
            )
        )
        if (
            verified_index != current_index
            or _git_admin_file_metadata(verified_metadata)
            != _git_admin_file_metadata(metadata)
            or verified_xattrs != current_xattrs
        ):
            raise MutationJournalError(
                f"slice {self.slice_id} changed Git index during semantic proof"
            )
        expected_mode = self._manifest.get("index_mode")
        current_mode = stat.S_IMODE(metadata.st_mode)
        mode_narrowed = False
        nested_mode_repair = False
        if expected_mode is not None and current_mode != int(expected_mode):
            # Git may replace an otherwise equivalent index through an
            # index.lock created beneath a stricter provider umask. Permission
            # removal cannot widen access, but admit it only alongside proven
            # cache-byte churn; a standalone chmod remains a hard failure.
            # Permission additions fail except for the authenticated nested
            # pure-rw widening below; special bits always fail.
            mode_narrowed = (
                current_index != expected
                and current_mode & ~int(expected_mode) == 0
            )
            nested_mode_repair = bool(
                allow_nested_cache_mode_repair
                and self._manifest.get("nested_gitlink_guard")
                and current_index != expected
                and self._nested_index_mode_repair_metadata_is_admissible(
                    metadata,
                    expected_mode=expected_mode,
                    current_mode=current_mode,
                )
            )
            if not mode_narrowed and not nested_mode_repair:
                raise MutationJournalError(
                    f"slice {self.slice_id} changed Git index mode"
                )
        if current_xattrs != self._manifest.get("index_xattrs", {}):
            raise MutationJournalError(
                f"slice {self.slice_id} changed Git index xattrs"
            )
        normalization_needed = bool(
            current_index != expected or mode_narrowed or nested_mode_repair
        )
        visible_before_normalization = set(self.detected_scope_escapes())
        status_before_normalization = (
            _nested_clean_status(cwd) if normalization_needed else None
        )
        # Assay's intent-to-add capture may rewrite cache/stat extensions
        # without changing entries or flags. Restore exact bytes and mode so
        # benign churn does not accumulate across accepted model calls.
        if normalization_needed:
            self._restore_bound_git_admin_file(
                str(self._manifest["index_path"]),
                exists=True,
                record={
                    "mode": expected_mode,
                    "xattrs": self._manifest.get("index_xattrs", {}),
                },
                payload=expected,
                label="Git index normalization",
                expected_current=(
                    verified_index,
                    _git_admin_file_metadata(verified_metadata),
                    verified_xattrs,
                ),
            )
        if (
            status_before_normalization is not None
            and _nested_clean_status(cwd) != status_before_normalization
        ):
            raise MutationJournalError(
                f"slice {self.slice_id} changed Git status after index "
                "normalization"
            )
        if normalization_needed:
            # Re-enter the ordinary non-repairing proof over the captured bytes
            # before any parent may compare its enclosing module administration.
            self.assert_index_unchanged()
        # A forged stat cache can make the first status scan trust poisoned
        # worktree bytes even when staged entries/flags are unchanged. Once
        # the exact baseline index is back, rescan before any journal can be
        # disarmed so the real out-of-scope delta becomes visible.
        hidden_escapes = set(self.detected_scope_escapes()).difference(
            visible_before_normalization
        )
        if hidden_escapes:
            raise MutationJournalError(
                f"slice {self.slice_id} changed paths outside its scope after "
                f"index normalization: {sorted(hidden_escapes)!r}"
            )

    def _verified_timestamp_only_object_changes(
        self,
        cwd: Path,
        expected: dict[str, dict[str, object]],
        current: dict[str, dict[str, object]],
        *,
        allow_additions: bool = False,
    ) -> set[str] | None:
        """Accept canonical object timestamp drift after native integrity proof."""

        changes = _timestamp_only_object_changes(
            expected,
            current,
            allow_additions=allow_additions,
        )
        if not changes:
            return changes
        result = _git_fsck(
            cwd,
            "--full",
            "--no-dangling",
            str(self._manifest["head"]),
            check=False,
        )
        if result.returncode != 0:
            diagnostic = b"\n".join((result.stdout, result.stderr)).decode(
                "utf-8", errors="replace"
            ).strip()
            raise MutationJournalError(
                "timestamp-only Git object drift failed full fsck: "
                f"{diagnostic[-1000:]}"
            )
        return changes

    def assert_repository_metadata_unchanged(self) -> None:
        """Reject non-HEAD refs and Git object-store mutations."""
        self._require_writer_epoch_quiescence(
            frontier="repository metadata proof"
        )
        self._assert_registry_marker_unchanged()
        self._assert_registry_topology_unchanged()
        self._assert_git_entry_unchanged()
        self._normalize_indexes_before_admin_topology_proof()
        self._assert_git_admin_topology_unchanged()
        self._assert_tracked_path_metadata_unchanged()
        self._assert_cached_module_controls_unchanged()
        self._assert_absent_worktree_admin_controls_unchanged()
        cwd = self._bound_workspace_cwd()
        expected_directory_modes = self._manifest.get("directory_modes")
        ignored_roots = self._effective_ignored_directory_roots(
            cwd,
            protected_paths=(
                expected_directory_modes
                if isinstance(expected_directory_modes, dict)
                else ()
            ),
        )
        authorized_directory_topology: set[str] = set()
        if expected_directory_modes is not None:
            current_directory_modes = _directory_mode_inventory(
                cwd,
                excluded_roots=(
                    *self._manifest.get("metadata_relatives", ()),
                    *self._manifest.get("initialized_gitlinks", ()),
                    *ignored_roots,
                ),
            )
            directory_changes = {
                path
                for path in set(expected_directory_modes) | set(current_directory_modes)
                if expected_directory_modes.get(path) != current_directory_modes.get(path)
            }
            recursive_scope = set(self._manifest.get("recursive_scope", ()))
            scope = tuple(self._manifest.get("scope", ()))
            deleted_recursive_roots = self._deleted_recursive_scope_roots()
            status_paths = {
                _normalize_relative(cwd, path)
                for path in _git_status_paths(cwd)
            }
            entries = self._manifest.get("entries", {})
            tracked_metadata = self._manifest.get(
                "tracked_path_metadata", {}
            )

            def _has_authorized_status_descendant(path: str) -> bool:
                prefix = path.rstrip("/") + "/"
                return any(
                    status.startswith(prefix)
                    and any(
                        status == root
                        or (
                            root in recursive_scope
                            and status.startswith(root.rstrip("/") + "/")
                        )
                        for root in scope
                    )
                    for status in status_paths
                )

            def _is_unaliased_topology_change(path: str) -> bool:
                expected_present = path in expected_directory_modes
                current_present = path in current_directory_modes
                if expected_present == current_present:
                    # Mode changes are never justified by Git-visible files.
                    return False
                if expected_present:
                    # A removed directory may be absent, but replacing it
                    # with a file or symlink is not a topology deletion.
                    try:
                        (cwd / path).lstat()
                    except FileNotFoundError:
                        return True
                    return False
                # Conversely, a new directory cannot replace a baseline file
                # or symlink. Every explicit scope root and pre-dirty node has
                # an exact snapshot; tracked nodes also have a metadata guard.
                baseline = entries.get(path) or tracked_metadata.get(path)
                return baseline is None or baseline.get("kind") == "missing"

            authorized_directory_topology = {
                path
                for path in directory_changes
                if _is_unaliased_topology_change(path)
                and (
                    _has_authorized_status_descendant(path)
                    or any(
                        path == root
                        or path.startswith(root.rstrip("/") + "/")
                        for root in deleted_recursive_roots
                    )
                )
            }
            directory_changes.difference_update(
                authorized_directory_topology
            )
            invalid_recursive_roots = {
                path
                for path in recursive_scope
                if (cwd / path).is_symlink()
                or ((cwd / path).exists() and not (cwd / path).is_dir())
            }
            directory_changes.update(invalid_recursive_roots)
            if directory_changes:
                raise MutationJournalError(
                    f"slice {self.slice_id} changed guarded worktree directory "
                    f"topology or modes: {sorted(directory_changes)[:10]!r}"
                )
        expected_directory_xattrs = self._manifest.get("directory_xattrs")
        if expected_directory_xattrs is not None:
            xattr_changes = [
                relative
                for relative, expected in expected_directory_xattrs.items()
                if relative not in authorized_directory_topology
                and _xattr_inventory(
                    cwd if relative == "." else cwd / relative
                ) != expected
            ]
            if xattr_changes:
                raise MutationJournalError(
                    f"slice {self.slice_id} changed guarded directory xattrs: "
                    f"{sorted(xattr_changes)[:10]!r}"
                )
        nested_markers = _relevant_nested_vcs_markers(
            cwd,
            excluded_roots=(
                *self._manifest.get("metadata_relatives", ()),
                *self._manifest.get("initialized_gitlinks", ()),
            ),
            ignored_roots=ignored_roots,
        )
        if nested_markers:
            raise MutationJournalError(
                f"slice {self.slice_id} created nested VCS administration: "
                f"{list(nested_markers)!r}"
            )
        refs_root = _refs_path(cwd)
        if (
            not self._bound_paths_equivalent(
                refs_root,
                str(self._manifest.get("refs_path", refs_root)),
            )
            or not self._bound_paths_same(
                refs_root,
                str(self._manifest.get("refs_resolved_path", refs_root)),
            )
        ):
            raise MutationJournalError(
                f"slice {self.slice_id} moved or aliased Git refs"
            )
        expected_refs_tree = self._manifest.get("refs_tree")
        if expected_refs_tree is not None and not (
            self._bound_git_admin_tree_matches(
                str(self._manifest.get("refs_path", refs_root)),
                record={
                    "mode": self._manifest.get("refs_root_mode"),
                    "device": self._manifest.get("refs_root_device"),
                    "inode": self._manifest.get("refs_root_inode"),
                    "xattrs": self._manifest.get("refs_root_xattrs", {}),
                },
                entries=expected_refs_tree,
                label="Git refs assertion",
            )
        ):
            raise MutationJournalError(
                f"slice {self.slice_id} changed physical Git loose refs"
            )
        log_refs_root = _git_control_path(cwd, "logs/refs")
        if not self._bound_paths_equivalent(
            log_refs_root,
            str(self._manifest.get("log_refs_path", log_refs_root)),
        ):
            raise MutationJournalError(
                f"slice {self.slice_id} moved Git ref logs"
            )
        expected_log_refs_exists = bool(
            self._manifest.get("log_refs_exists", False)
        )
        if not expected_log_refs_exists:
            self._assert_bound_git_admin_entry_absent(
                str(self._manifest.get("log_refs_path", log_refs_root)),
                label="Git ref logs",
            )
        else:
            expected_log_tree = self._manifest.get("log_refs_tree")
            if expected_log_tree is not None and not (
                self._bound_git_admin_tree_matches(
                    str(self._manifest.get("log_refs_path", log_refs_root)),
                    record={
                        "mode": self._manifest.get("log_refs_root_mode"),
                        "device": self._manifest.get("log_refs_root_device"),
                        "inode": self._manifest.get("log_refs_root_inode"),
                        "xattrs": self._manifest.get(
                            "log_refs_root_xattrs", {}
                        ),
                    },
                    entries=expected_log_tree,
                    label="Git ref logs assertion",
                )
            ):
                raise MutationJournalError(
                    f"slice {self.slice_id} changed physical Git ref logs"
                )
        for record in self._manifest.get("control_files", ()):
            path = self._bound_manifest_path(str(record["path"]))
            logical_name = record.get("name")
            if (
                logical_name is not None
                and not self._bound_paths_equivalent(
                    _git_control_path(cwd, str(logical_name)),
                    path,
                )
            ):
                raise MutationJournalError(
                    f"slice {self.slice_id} moved Git control {logical_name}: "
                    f"current={_git_control_path(cwd, str(logical_name))} "
                    f"expected={path}"
                )
            expected_exists = bool(record["exists"])
            if not expected_exists:
                self._assert_bound_git_admin_entry_absent(
                    path,
                    label=f"Git control {path}",
                )
                continue
            expected = self._read_snapshot_blob_record(
                record,
                label=f"Git control {path}",
            )
            payload, metadata, xattrs = self._read_bound_git_admin_file(
                path,
                label=f"Git control {path}",
                max_bytes=max(len(expected), 1),
            )
            if (
                payload != expected
                or stat.S_IMODE(metadata.st_mode) != int(record["mode"])
                or xattrs != record.get("xattrs", {})
            ):
                raise MutationJournalError(
                    f"slice {self.slice_id} changed Git control {path}"
                )
        disabled_git_hooks = self._manifest.get("disabled_git_hooks")
        if isinstance(disabled_git_hooks, dict):
            path = Path(str(disabled_git_hooks["path"]))
            hooks_metadata = _disabled_git_hooks_device(path)
            if (
                _auxiliary_git_tree_path(cwd, "hooks") != path
                or hooks_metadata is None
                or hooks_metadata.st_rdev != int(disabled_git_hooks["rdev"])
            ):
                raise MutationJournalError(
                    f"slice {self.slice_id} changed disabled Git hooks binding"
                )
        for record in self._manifest.get("auxiliary_git_trees", ()):
            name = str(record["name"])
            path = self._bound_manifest_path(str(record["path"]))
            if not self._bound_paths_equivalent(
                _auxiliary_git_tree_path(cwd, name),
                path,
            ):
                raise MutationJournalError(
                    f"slice {self.slice_id} moved Git administrative tree {name}"
                )
            expected_exists = bool(record["exists"])
            if not expected_exists:
                self._assert_bound_git_admin_entry_absent(
                    path,
                    label=f"Git administrative tree {name}",
                )
                continue
            if (
                not self._bound_git_admin_tree_matches(
                    path,
                    record=record,
                    entries=record["entries"],
                    label=f"Git administrative tree {name}",
                )
            ):
                raise MutationJournalError(
                    f"slice {self.slice_id} changed Git administrative tree {name}"
                )
        expected_worktrees = self._manifest.get("registered_worktrees")
        for rendered in self._manifest.get("absent_registered_worktrees", ()):
            try:
                Path(str(rendered)).lstat()
            except FileNotFoundError:
                continue
            raise MutationJournalError(
                f"slice {self.slice_id} populated an absent registered "
                f"worktree path: {rendered}"
            )
        if (
            expected_worktrees is not None
            and tuple(expected_worktrees) != _registered_worktrees(cwd)
        ):
            raise MutationJournalError(
                f"slice {self.slice_id} changed registered Git worktrees"
            )
        expected_worktree_namespace = self._manifest.get(
            "worktree_namespace_topology"
        )
        if (
            expected_worktree_namespace is not None
            and _worktree_namespace_topology(
                cwd,
                guarded_admin_roots=self._manifest.get(
                    "guarded_worktree_admin_roots", ()
                ),
            ) != expected_worktree_namespace
        ):
            raise MutationJournalError(
                f"slice {self.slice_id} changed Git worktree admin topology"
            )
        expected_modules = self._manifest.get("module_admin_roots")
        if (
            expected_modules is not None
            and tuple(expected_modules) != _module_admin_roots(cwd)
        ):
            raise MutationJournalError(
                f"slice {self.slice_id} changed Git module administration"
            )
        expected_module_namespace = self._manifest.get(
            "module_namespace_topology"
        )
        if expected_module_namespace is not None:
            current_module_namespace = _module_namespace_topology(
                cwd,
                guarded_roots=(
                    *self._manifest.get("initialized_module_admin_roots", ()),
                    *self._manifest.get("cached_module_admin_roots", ()),
                ),
            )
            if current_module_namespace != expected_module_namespace:
                raise MutationJournalError(
                    f"slice {self.slice_id} changed Git module namespace topology"
                )
        expected_refs = self._manifest.get("refs")
        if expected_refs is not None and _refs_snapshot(cwd) != expected_refs:
            raise MutationJournalError(
                f"slice {self.slice_id} changed Git refs"
            )
        expected_objects = self._manifest.get("object_inventory")
        if expected_objects is not None:
            objects_root, current_objects = _object_inventory(cwd)
            if (
                not self._bound_paths_equivalent(
                    objects_root,
                    str(self._manifest.get("objects_path", objects_root)),
                )
                or not self._bound_paths_same(
                    objects_root,
                    str(self._manifest.get(
                        "objects_resolved_path",
                        objects_root,
                    )),
                )
            ):
                raise MutationJournalError(
                    f"slice {self.slice_id} moved the Git object directory"
                )
            expected_objects_root_mode = self._manifest.get("objects_root_mode")
            if (
                expected_objects_root_mode is not None
                and stat.S_IMODE(objects_root.lstat().st_mode)
                != int(expected_objects_root_mode)
            ):
                raise MutationJournalError(
                    f"slice {self.slice_id} changed Git object root mode"
                )
            if _xattr_inventory(objects_root) != self._manifest.get(
                "objects_root_xattrs", {}
            ):
                raise MutationJournalError(
                    f"slice {self.slice_id} changed Git object root xattrs"
                )
            object_changes = {
                path
                for path in set(expected_objects) | set(current_objects)
                if current_objects.get(path) != expected_objects.get(path)
            }
            timestamp_only = (
                self._verified_timestamp_only_object_changes(
                    cwd,
                    expected_objects,
                    current_objects,
                )
                if object_changes else set()
            )
            if object_changes and timestamp_only is None:
                result = _git_fsck(
                    cwd,
                    "--no-dangling",
                    "HEAD",
                    check=False,
                )
                diagnostic = b"\n".join(
                    (result.stdout, result.stderr)
                ).decode("utf-8", errors="replace").strip()
                raise MutationJournalError(
                    f"slice {self.slice_id} changed Git objects "
                    f"{sorted(object_changes)[:10]!r}; "
                    f"connectivity={diagnostic[-500:]!r}"
                )
        for nested in self._nested_journals():
            # A children-first rollback can deliberately retain an already
            # terminal child until the parent reaches its own durable commit
            # point.  The child's restore performed its complete final proof;
            # re-entering capture validation on the inactive terminal object
            # would reject solely because it is no longer a writable journal.
            if nested.state == "rolled_back":
                if not nested.cleanup_pending:
                    raise MutationJournalError(
                        "terminal nested mutation journal disappeared before "
                        "family cleanup"
                    )
                continue
            nested.assert_exact_baseline()

    def _normalize_indexes_before_admin_topology_proof(self) -> None:
        """Prove and normalize benign index cache churn deepest-first.

        A superproject owns an exact snapshot of ``.git/modules`` while each
        initialized gitlink also has its own guard journal. Ordinary Git reads
        may rewrite an index's stat/cache extensions without changing staged
        entries or flags. Let each journal perform its existing semantic index
        proof and exact-byte normalization before its parent compares the
        enclosing admin tree. Recurse deepest-first so the same rule covers the
        current checkout and arbitrarily nested gitlinks. Real staged entries,
        assume-unchanged/skip-worktree flags, added permissions, xattr changes,
        and hidden scope escapes still fail closed before any parent snapshot
        can be accepted. Prove every other admin entry first so an unrelated
        control mutation cannot enter Git-capture recovery merely because its
        index also churned.
        """

        for nested in self._nested_journals():
            if nested.state == "rolled_back":
                # Children-first rollback already completed the child's final
                # proof. The ordinary terminal-child check below authenticates
                # its retained cleanup receipt before the parent can settle.
                continue
            nested._normalize_indexes_before_admin_topology_proof()
        self._assert_git_entry_unchanged()
        self._assert_git_admin_topology_unchanged(
            allow_nested_journal_controls=True,
            allow_index_mode_narrowing=True,
            allow_nested_index_mode_repair=True,
        )
        self.assert_index_unchanged(
            allow_nested_cache_mode_repair=True,
        )
        self._assert_git_admin_topology_unchanged(
            allow_nested_journal_controls=True,
        )

    def _nested_journal_admin_additions(
        self,
        root: Path,
        additions: set[str],
    ) -> set[str]:
        """Validate top-level controls owned by this exact journal family.

        A linked-worktree or gitlink guard can capture its Git-admin topology
        before its parent publishes the shared registry and lock controls.
        During children-first rollback those controls are additions relative
        to the child's baseline, but they are not untrusted: the connected
        family projection, exact marker payloads, directory inode, and shared
        lock inode authenticate them.  Do not infer authority from names alone.
        """

        projected_family = {
            str(transaction_id)
            for transaction_id in self._manifest.get(
                "registry_transaction_family",
                (),
            )
        }
        if not projected_family:
            projected_family = {self.transaction_id}
        with _LIVE_TRANSACTIONS_LOCK:
            available = _writer_epoch_available_members_locked(self)
            missing = projected_family.difference(available)
            if missing:
                raise MutationJournalError(
                    "journal family controls lack exact live/recovery owners: "
                    f"{sorted(missing)!r}"
                )
            family_members = [
                available[transaction_id]
                for transaction_id in sorted(projected_family)
            ]

        allowed: set[str] = set()
        lock_records = (
            [
                (member, member._manifest.get("authority_lock"))
                for member in family_members
                if member._manifest.get("authority_lock") is not None
                and Path(
                    str(member._manifest["authority_lock"]["path"])
                ).parent == root
            ]
            if "crucible-workspace.lock" in additions
            else []
        )
        if lock_records:
            lock_path = root / "crucible-workspace.lock"
            metadata, xattrs = self._inspect_bound_git_admin_entry(
                lock_path,
                label="nested journal authority lock",
            )
            for _nested, expected in lock_records:
                assert expected is not None
                if (
                    not stat.S_ISREG(metadata.st_mode)
                    or metadata.st_dev != int(expected["device"])
                    or metadata.st_ino != int(expected["inode"])
                    or metadata.st_nlink != int(expected["nlink"])
                    or stat.S_IMODE(metadata.st_mode) != int(expected["mode"])
                    or xattrs != expected.get("xattrs", {})
                ):
                    raise MutationJournalError(
                        "nested journal authority lock changed or was aliased"
                    )
            allowed.add(lock_path.name)

        markers = (
            {
                Path(str(member._manifest["registry_marker"])): member
                for member in family_members
                if member._manifest.get("registry_marker") is not None
                and Path(
                    str(member._manifest["registry_marker"])
                ).parent.parent == root
            }
            if _REGISTRY_DIRECTORY in additions
            else {}
        )
        if markers:
            registry = root / _REGISTRY_DIRECTORY
            expected_directory_records = [
                admin_record["entries"][_REGISTRY_DIRECTORY]
                for member in family_members
                for admin_record in member._manifest.get(
                    "git_admin_topology", ()
                )
                if Path(str(admin_record["root"])) == root
                and _REGISTRY_DIRECTORY in admin_record["entries"]
            ]
            if not expected_directory_records:
                raise MutationJournalError(
                    "nested journal registry lacks inode authority"
                )
            first_record = expected_directory_records[0]
            if any(
                record.get("kind") != "owned_directory"
                or (
                    record.get("device"),
                    record.get("inode"),
                    record.get("mode"),
                    record.get("xattrs", {}),
                )
                != (
                    first_record.get("device"),
                    first_record.get("inode"),
                    first_record.get("mode"),
                    first_record.get("xattrs", {}),
                )
                for record in expected_directory_records
            ):
                raise MutationJournalError(
                    "nested journal registry authority is inconsistent"
                )
            with self._open_bound_git_admin_directory(
                registry,
                record=first_record,
                label="nested journal registry",
            ) as registry_fd:
                opened = os.fstat(registry_fd)
                if (
                    stat.S_IMODE(opened.st_mode) != int(first_record["mode"])
                    or _bound_descriptor_xattr_inventory(
                        registry_fd,
                        label="nested journal registry",
                    ) != first_record.get("xattrs", {})
                ):
                    raise MutationJournalError(
                        "nested journal registry metadata changed"
                    )
                current_entries = set(_bounded_directory_names(
                    registry_fd,
                    label="nested journal registry",
                    max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
                ))
                expected_entries = {path.name for path in markers}
                if current_entries != expected_entries:
                    raise MutationJournalError(
                        "nested journal registry contains non-journal entries"
                    )
                for marker_path, member in markers.items():
                    expected_payload = member._expected_registry_marker_payload()
                    payload, marker_metadata = _read_bound_regular_entry(
                        registry_fd,
                        marker_path.name,
                        label=f"nested journal registry marker {marker_path.name}",
                        max_bytes=max(len(expected_payload), 1),
                    )
                    if payload != expected_payload or marker_metadata.st_nlink != 1:
                        raise MutationJournalError(
                            "nested journal registry marker changed: "
                            f"{marker_path.name}"
                        )
            allowed.add(registry.name)

        return allowed

    def _assert_git_admin_topology_unchanged(
        self,
        *,
        allow_nested_journal_controls: bool = False,
        allow_index_mode_narrowing: bool = False,
        allow_nested_index_mode_repair: bool = False,
    ) -> None:
        expected_roots = self._manifest.get("git_admin_topology")
        if expected_roots is None:
            return
        cwd = self._bound_workspace_cwd()
        current_roots = tuple(dict.fromkeys((_git_common_dir(cwd), _git_dir(cwd))))
        if len(current_roots) != len(expected_roots) or any(
            not self._bound_paths_same(root, str(record["root"]))
            for record, root in zip(expected_roots, current_roots, strict=True)
        ):
            raise MutationJournalError("Git admin roots moved or aliased")
        for record, root in zip(expected_roots, current_roots, strict=True):
            with self._open_bound_git_admin_directory(
                root,
                record=record,
                label=f"Git admin root {root}",
            ) as root_fd:
                root_metadata = os.fstat(root_fd)
                if (
                    stat.S_IMODE(root_metadata.st_mode) != int(record["mode"])
                    or _bound_descriptor_xattr_inventory(
                        root_fd,
                        label=f"Git admin root {root}",
                    ) != record.get("xattrs", {})
                ):
                    raise MutationJournalError(
                        f"slice {self.slice_id} changed Git admin root {root}"
                    )
                expected_entries = record["entries"]
                current_names = set(_bounded_directory_names(
                    root_fd,
                    label=f"Git admin root {root}",
                    max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
                ))
            additions = current_names.difference(expected_entries)
            allowed_additions = (
                self._nested_journal_admin_additions(root, additions)
                if (
                    allow_nested_journal_controls
                    or len(self._manifest.get(
                        "registry_transaction_family",
                        (),
                    )) > 1
                )
                else set()
            )
            if current_names != set(expected_entries) | allowed_additions:
                raise MutationJournalError(
                    f"slice {self.slice_id} changed Git admin top-level topology"
                )
            for name, expected in expected_entries.items():
                path = root / name
                kind = expected["kind"]
                metadata, xattrs = self._inspect_bound_git_admin_entry(
                    path,
                    label=f"Git admin entry {path}",
                )
                if xattrs != expected.get("xattrs", {}):
                    raise MutationJournalError(
                        f"slice {self.slice_id} changed Git admin xattrs {path}"
                    )
                if kind == "file":
                    expected_payload = self._read_snapshot_blob_record(
                        expected,
                        label=f"Git admin file {path}",
                    )
                    payload, opened, opened_xattrs = (
                        self._read_bound_git_admin_file(
                            path,
                            label=f"Git admin file {path}",
                            max_bytes=max(len(expected_payload), 1),
                        )
                    )
                    if (
                        not stat.S_ISREG(metadata.st_mode)
                        or metadata.st_nlink != 1
                        or stat.S_IMODE(metadata.st_mode) != int(expected["mode"])
                        or payload != expected_payload
                        or (opened.st_dev, opened.st_ino)
                        != (metadata.st_dev, metadata.st_ino)
                        or opened_xattrs != expected.get("xattrs", {})
                    ):
                        raise MutationJournalError(
                            f"slice {self.slice_id} changed Git admin file {path}"
                        )
                elif kind == "owned_file":
                    observed_mode = stat.S_IMODE(metadata.st_mode)
                    expected_mode = int(expected["mode"])
                    mode_matches = observed_mode == expected_mode
                    if (
                        not mode_matches
                        and allow_index_mode_narrowing
                        and name == "index"
                    ):
                        # Defer only permission removal or an authenticated,
                        # pure rw-bit widening of a nested index. The latter
                        # still needs byte churn plus exact stage/flag proof in
                        # ``assert_index_unchanged`` before normalization.
                        mode_matches = bool(
                            observed_mode & ~expected_mode == 0
                            or (
                                allow_nested_index_mode_repair
                                and self._manifest.get("nested_gitlink_guard")
                                and self
                                ._nested_index_mode_repair_metadata_is_admissible(
                                    metadata,
                                    expected_mode=expected_mode,
                                    current_mode=observed_mode,
                                )
                            )
                        )
                    if (
                        not stat.S_ISREG(metadata.st_mode)
                        or metadata.st_nlink != 1
                        or (
                            expected.get("device") is not None
                            and metadata.st_dev != int(expected["device"])
                        )
                        or (
                            expected.get("uid") is not None
                            and metadata.st_uid != int(expected["uid"])
                        )
                        or (
                            expected.get("gid") is not None
                            and metadata.st_gid != int(expected["gid"])
                        )
                        or not mode_matches
                    ):
                        raise MutationJournalError(
                            f"slice {self.slice_id} changed Git admin file {path}"
                        )
                elif kind == "authority_lock":
                    if (
                        not stat.S_ISREG(metadata.st_mode)
                        or metadata.st_dev != int(expected["device"])
                        or metadata.st_ino != int(expected["inode"])
                        or metadata.st_nlink != int(expected["nlink"])
                        or stat.S_IMODE(metadata.st_mode) != int(expected["mode"])
                    ):
                        raise MutationJournalError(
                            "workspace authority lock inode changed; refusing "
                            "unsafe repair while transaction lock is held"
                        )
                elif kind == "owned_directory":
                    if (
                        not stat.S_ISDIR(metadata.st_mode)
                        or stat.S_ISLNK(metadata.st_mode)
                        or (metadata.st_dev, metadata.st_ino)
                        != (int(expected["device"]), int(expected["inode"]))
                        or stat.S_IMODE(metadata.st_mode) != int(expected["mode"])
                    ):
                        raise MutationJournalError(
                            f"slice {self.slice_id} changed Git admin directory {path}"
                        )
                elif kind == "guarded_directory":
                    if not self._bound_git_admin_tree_matches(
                        path,
                        record=expected,
                        entries=expected["entries"],
                        label=f"custom Git admin tree {path}",
                    ):
                        raise MutationJournalError(
                            f"slice {self.slice_id} changed custom Git admin tree {path}"
                        )
                else:
                    raise MutationJournalError(
                        f"unknown Git admin topology kind: {kind!r}"
                    )

    def _initial_fsck_reasons(self, cwd: Path) -> set[str]:
        """Classify pre-rollback drift that requires object verification.

        This check intentionally runs before the access-repair prepass.  A
        model can make an object or administrative directory unreadable, and
        opening it for rollback must not erase the evidence that a terminal
        connectivity check is required.
        """

        reasons: set[str] = set()
        try:
            self._assert_git_entry_unchanged()
            self._assert_git_admin_topology_unchanged(
                allow_nested_journal_controls=True,
            )
        except (MutationJournalError, OSError):
            reasons.add("controls")

        expected_refs = self._manifest.get("refs")
        if expected_refs is not None:
            try:
                if (
                    _head(cwd) != self._manifest["head"]
                    or _symbolic_head(cwd)
                    != self._manifest.get("head_symbolic_ref")
                    or _refs_snapshot(cwd) != expected_refs
                ):
                    reasons.add("refs")
            except (MutationJournalError, OSError):
                reasons.add("refs")

        expected_objects = self._manifest.get("object_inventory")
        if expected_objects is not None:
            try:
                objects_root, current_objects = _object_inventory(cwd)
                root_metadata = objects_root.lstat()
                if (
                    not self._bound_paths_equivalent(
                        objects_root,
                        str(self._manifest.get("objects_path", objects_root)),
                    )
                    or not self._bound_paths_same(
                        objects_root,
                        str(self._manifest.get(
                            "objects_resolved_path",
                            objects_root,
                        )),
                    )
                    or (
                        self._manifest.get("objects_root_mode") is not None
                        and stat.S_IMODE(root_metadata.st_mode)
                        != int(self._manifest["objects_root_mode"])
                    )
                    or _xattr_inventory(objects_root)
                    != self._manifest.get("objects_root_xattrs", {})
                    or (
                        current_objects != expected_objects
                        and _timestamp_only_object_changes(
                            expected_objects,
                            current_objects,
                        ) is None
                    )
                ):
                    reasons.add("objects")
            except (MutationJournalError, OSError):
                reasons.add("objects")

        return reasons

    def _restore_git_admin_topology(self) -> None:
        expected_roots = self._manifest.get("git_admin_topology")
        if expected_roots is None:
            return
        cwd = self._bound_workspace_cwd()
        current_roots = tuple(dict.fromkeys((_git_common_dir(cwd), _git_dir(cwd))))
        bound_expected_roots = tuple(
            self._bound_manifest_path(str(record["root"]))
            for record in expected_roots
        )
        if len(current_roots) != len(bound_expected_roots) or any(
            not self._bound_paths_same(current, expected)
            for current, expected in zip(
                current_roots,
                bound_expected_roots,
                strict=True,
            )
        ):
            raise MutationJournalError("Git admin roots moved during rollback")

        # Authenticate every restorable payload and every irreplaceable
        # directory/lock inode before making the first namespace or metadata
        # change.  This is what prevents a same-mode directory substitution
        # from turning rollback into a recursive edit of an externally parked
        # tree.
        payloads: dict[tuple[int, str], bytes] = {}
        guarded_payloads: dict[tuple[int, str], dict[str, bytes]] = {}
        allowed_family_additions: dict[int, set[str]] = {}
        budget = _MutationJournalArtifactBudget()
        for record, root in zip(
            expected_roots,
            bound_expected_roots,
            strict=True,
        ):
            if not isinstance(record, Mapping):
                raise MutationJournalError(
                    "Git admin topology root record is malformed"
                )
            root_metadata, _root_xattrs = self._inspect_bound_git_admin_entry(
                str(record["root"]),
                label=f"Git admin root {record['root']}",
            )
            if (
                not stat.S_ISDIR(root_metadata.st_mode)
                or stat.S_ISLNK(root_metadata.st_mode)
                or (
                    record.get("device") is not None
                    and root_metadata.st_dev != int(record["device"])
                )
                or (
                    record.get("inode") is not None
                    and root_metadata.st_ino != int(record["inode"])
                )
            ):
                raise MutationJournalError(
                    f"Git admin root moved or aliased during rollback: {root}"
                )
            expected_entries = record.get("entries")
            if not isinstance(expected_entries, Mapping):
                raise MutationJournalError(
                    f"Git admin topology entries are malformed: {root}"
                )
            for name, expected in expected_entries.items():
                if (
                    not isinstance(name, str)
                    or name in {"", ".", ".."}
                    or "/" in name
                    or not isinstance(expected, Mapping)
                ):
                    raise MutationJournalError(
                        f"Git admin topology entry is malformed: {root}"
                    )
                kind = expected.get("kind")
                if kind == "file":
                    payloads[(id(record), name)] = (
                        self._read_snapshot_blob_record(
                            expected,
                            label=f"Git admin topology {root / name}",
                            budget=budget,
                        )
                    )
                elif kind == "owned_file":
                    metadata, _xattrs = self._inspect_bound_git_admin_entry(
                        Path(str(record["root"])) / name,
                        label=f"Git admin owned file {root / name}",
                    )
                    if (
                        not stat.S_ISREG(metadata.st_mode)
                        or metadata.st_nlink != 1
                    ):
                        raise MutationJournalError(
                            f"Git admin file moved or aliased: {root / name}"
                        )
                elif kind == "authority_lock":
                    metadata, observed_xattrs = (
                        self._inspect_bound_git_admin_entry(
                            Path(str(record["root"])) / name,
                            label="workspace authority lock",
                        )
                    )
                    if (
                        not stat.S_ISREG(metadata.st_mode)
                        or metadata.st_dev != int(expected["device"])
                        or metadata.st_ino != int(expected["inode"])
                        or metadata.st_nlink != int(expected["nlink"])
                        or stat.S_IMODE(metadata.st_mode) != int(expected["mode"])
                        or observed_xattrs != expected.get("xattrs", {})
                    ):
                        raise MutationJournalError(
                            "workspace authority lock inode changed; journal retained"
                        )
                elif kind in {"owned_directory", "guarded_directory"}:
                    metadata, _xattrs = self._inspect_bound_git_admin_entry(
                        Path(str(record["root"])) / name,
                        label=f"Git admin directory {root / name}",
                    )
                    if (
                        not stat.S_ISDIR(metadata.st_mode)
                        or stat.S_ISLNK(metadata.st_mode)
                        or metadata.st_dev != int(expected["device"])
                        or metadata.st_ino != int(expected["inode"])
                    ):
                        raise MutationJournalError(
                            f"Git admin directory moved or aliased: {root / name}"
                        )
                    if kind == "guarded_directory":
                        nested_payloads: dict[str, bytes] = {}
                        nested_entries = expected.get("entries", {})
                        if not isinstance(nested_entries, Mapping):
                            raise MutationJournalError(
                                "Git admin guarded tree entries are malformed: "
                                f"{root / name}"
                            )
                        for nested_name, nested_entry in nested_entries.items():
                            if not isinstance(nested_entry, Mapping):
                                raise MutationJournalError(
                                    "Git admin guarded tree entry is malformed: "
                                    f"{root / name}"
                                )
                            if nested_entry.get("kind") == "file":
                                nested_payloads[str(nested_name)] = (
                                    self._read_snapshot_blob_record(
                                        nested_entry,
                                        label=(
                                            "Git admin guarded topology "
                                            f"{root / name / str(nested_name)}"
                                        ),
                                        budget=budget,
                                    )
                                )
                        guarded_payloads[(id(record), name)] = nested_payloads
                else:
                    raise MutationJournalError(
                        f"unsupported Git admin topology kind: {kind!r}"
                    )

            # Scan every top-level addition across every admin root before
            # deleting even a regular-file addition from the first root.
            # Directory additions have no capture-time inode authority and
            # may be externally parked trees, so exact rollback must retain
            # the journal instead of recursively editing them.
            with self._open_bound_git_admin_directory(
                str(record["root"]),
                record=record,
                label=f"Git admin root preflight {root}",
            ) as root_fd:
                current_names = _bounded_directory_names(
                    root_fd,
                    label=f"Git admin root preflight {root}",
                    max_entries=(
                        _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS
                    ),
                )
                additions = set(current_names).difference(expected_entries)
                allowed_additions = self._nested_journal_admin_additions(
                    Path(str(record["root"])),
                    additions,
                )
                allowed_family_additions[id(record)] = allowed_additions
                for addition in additions.difference(allowed_additions):
                    metadata = os.stat(
                        addition,
                        dir_fd=root_fd,
                        follow_symlinks=False,
                    )
                    if stat.S_ISDIR(
                        metadata.st_mode
                    ) and not stat.S_ISLNK(metadata.st_mode):
                        raise MutationJournalError(
                            "refusing to recursively remove an "
                            "unauthenticated Git-admin topology addition: "
                            f"{root / addition}"
                        )

        for record, root in zip(
            expected_roots,
            bound_expected_roots,
            strict=True,
        ):
            expected_entries = cast(
                Mapping[str, Mapping[str, object]],
                record["entries"],
            )
            with self._open_bound_git_admin_directory(
                str(record["root"]),
                record=record,
                label=f"Git admin root {root}",
            ) as root_fd:
                current_names = _bounded_directory_names(
                    root_fd,
                    label=f"Git admin root {root}",
                    max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
                )
                for name in sorted(
                    set(current_names)
                    .difference(expected_entries)
                    .difference(allowed_family_additions[id(record)])
                ):
                    with _open_settlement_parent_if_present(
                        root_fd,
                        name,
                    ) as binding:
                        parent_fd, entry_name, parent_chain, missing_index = binding
                        if missing_index is not None:
                            raise MutationJournalError(
                                f"Git admin addition disappeared: {root / name}"
                            )
                        current = os.stat(
                            entry_name,
                            dir_fd=parent_fd,
                            follow_symlinks=False,
                        )
                        if stat.S_ISDIR(
                            current.st_mode
                        ) and not stat.S_ISLNK(current.st_mode):
                            raise MutationJournalError(
                                "refusing to recursively remove an "
                                "unauthenticated Git-admin topology addition: "
                                f"{root / name}"
                            )
                        _remove_bound_workspace_entry(
                            root_fd,
                            name,
                            parent_fd,
                            entry_name,
                            parent_chain,
                        )

            for name, expected in expected_entries.items():
                logical = Path(str(record["root"])) / name
                kind = expected["kind"]
                if kind == "file":
                    self._restore_bound_git_admin_file(
                        logical,
                        exists=True,
                        record=expected,
                        payload=payloads[(id(record), name)],
                        label=f"Git admin topology {root / name}",
                    )
                elif kind == "owned_file":
                    self._restore_bound_git_admin_entry_metadata(
                        logical,
                        record=expected,
                        label=f"Git admin owned file {root / name}",
                        require_identity=False,
                    )
                elif kind == "authority_lock":
                    continue
                elif kind == "owned_directory":
                    self._restore_bound_git_admin_entry_metadata(
                        logical,
                        record=expected,
                        label=f"Git admin owned directory {root / name}",
                        require_identity=True,
                    )
                elif kind == "guarded_directory":
                    self._restore_bound_git_admin_tree(
                        logical,
                        exists=True,
                        record=expected,
                        entries=cast(
                            Mapping[str, Mapping[str, object]],
                            expected.get("entries", {}),
                        ),
                        label=f"Git admin guarded tree {root / name}",
                        preloaded_payloads=guarded_payloads[
                            (id(record), name)
                        ],
                    )

            self._restore_bound_git_admin_entry_metadata(
                str(record["root"]),
                record=record,
                label=f"Git admin root {root}",
                require_identity=True,
            )

            with self._open_bound_git_admin_directory(
                str(record["root"]),
                record=record,
                label=f"Git admin root final proof {root}",
            ) as root_fd:
                if set(_bounded_directory_names(
                    root_fd,
                    label=f"Git admin root final proof {root}",
                    max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
                )) != (
                    set(expected_entries)
                    | allowed_family_additions[id(record)]
                ):
                    raise MutationJournalError(
                        f"Git admin root differs after restoration: {root}"
                    )

    def _restore_control_files(self) -> None:
        cwd = self._bound_workspace_cwd()
        records = tuple(self._manifest.get("control_files", ()))
        budget = _MutationJournalArtifactBudget()
        payloads: dict[int, bytes] = {}
        for record in records:
            if not isinstance(record, Mapping):
                raise MutationJournalError("Git control manifest is malformed")
            if bool(record.get("exists")):
                payloads[id(record)] = self._read_snapshot_blob_record(
                    record,
                    label=f"Git control {record.get('name', '<unknown>')}",
                    budget=budget,
                )
        for record in records:
            path = self._bound_manifest_path(str(record["path"]))
            logical_name = record.get("name")
            if (
                logical_name is not None
                and not self._bound_paths_equivalent(
                    _git_control_path(cwd, str(logical_name)),
                    path,
                )
            ):
                raise MutationJournalError(
                    f"refusing to restore aliased Git control {logical_name}"
                )
            self._restore_bound_git_admin_file(
                str(record["path"]),
                exists=bool(record["exists"]),
                record=record,
                payload=payloads.get(id(record)),
                label=f"Git control {logical_name or record['path']}",
            )

    def _restore_attribute_admin_control(self, cwd: Path) -> bool:
        """Restore config/info controls before any attribute-aware Git call."""

        changed = False
        current_common_dir = _git_common_dir(cwd)
        captured_common_dir = self._manifest.get("git_common_dir")
        if captured_common_dir is None:
            objects_path = self._manifest.get("objects_path")
            captured_common_dir = (
                str(Path(str(objects_path)).parent)
                if objects_path
                else str(current_common_dir)
            )
        common_dir = self._bound_manifest_path(str(captured_common_dir))
        if not self._bound_paths_same(current_common_dir, common_dir):
            raise MutationJournalError(
                "Git common directory moved during restore preparation: "
                f"current={current_common_dir} expected={common_dir}"
            )
        current_git_dir = _git_dir(cwd)
        git_dir = self._bound_manifest_path(
            str(self._manifest.get("git_admin_dir", current_git_dir))
        )
        if not self._bound_paths_same(current_git_dir, git_dir):
            raise MutationJournalError(
                "Git worktree directory moved during restore preparation: "
                f"current={current_git_dir} expected={git_dir}"
            )
        selected_records = tuple(
            record
            for record in self._manifest.get("control_files", ())
            if record.get("name") in {
                "config",
                "config.worktree",
                "info/attributes",
            }
        )
        payloads: dict[int, bytes] = {}
        budget = _MutationJournalArtifactBudget()
        for record in selected_records:
            if bool(record.get("exists")):
                payloads[id(record)] = self._read_snapshot_blob_record(
                    record,
                    label=f"Git attribute admin {record.get('name')}",
                    budget=budget,
                )
        for record in selected_records:
            path = self._bound_manifest_path(str(record["path"]))
            allowed_roots = (
                (common_dir, git_dir)
                if record.get("name") == "config.worktree"
                else (common_dir,)
            )
            if not any(
                self._bound_paths_same(path.parent, allowed)
                or any(
                    self._bound_paths_same(ancestor, allowed)
                    for ancestor in path.parents
                )
                for allowed in allowed_roots
            ):
                exc = MutationJournalError(
                    "Git attribute admin control escaped the common dir"
                )
                raise MutationJournalError(
                    "Git attribute admin control escaped the common dir"
                ) from exc
            changed = self._restore_bound_git_admin_file(
                str(record["path"]),
                exists=bool(record["exists"]),
                record=record,
                payload=payloads.get(id(record)),
                label=f"Git attribute admin {record.get('name')}",
            ) or changed
        return changed

    def _restore_auxiliary_git_trees(self, cwd: Path) -> None:
        disabled_git_hooks = self._manifest.get("disabled_git_hooks")
        if isinstance(disabled_git_hooks, dict):
            path = Path(str(disabled_git_hooks["path"]))
            metadata = _disabled_git_hooks_device(path)
            if (
                _auxiliary_git_tree_path(cwd, "hooks") != path
                or metadata is None
                or metadata.st_rdev != int(disabled_git_hooks["rdev"])
            ):
                raise MutationJournalError(
                    "refusing to restore changed disabled Git hooks binding"
                )
        for record in self._manifest.get("auxiliary_git_trees", ()):
            name = str(record["name"])
            path = self._bound_manifest_path(str(record["path"]))
            if not self._bound_paths_equivalent(
                _auxiliary_git_tree_path(cwd, name),
                path,
            ):
                raise MutationJournalError(
                    f"refusing to restore aliased Git administrative tree {name}"
                )
            self._restore_bound_git_admin_tree(
                str(record["path"]),
                exists=bool(record["exists"]),
                record=record,
                entries=record.get("entries", {}),
                label=f"Git auxiliary tree {name}",
            )

    def _remove_added_registered_worktrees(self, cwd: Path) -> None:
        expected = self._manifest.get("registered_worktrees")
        if expected is None:
            return
        baseline = tuple(str(path) for path in expected)
        current = list(_registered_worktrees(cwd))
        missing: list[str] = []
        for expected_path in baseline:
            match = next(
                (
                    index
                    for index, current_path in enumerate(current)
                    if self._bound_paths_equivalent(
                        expected_path,
                        current_path,
                    )
                ),
                None,
            )
            if match is None:
                missing.append(expected_path)
                continue
            current.pop(match)
        if missing:
            raise MutationJournalError(
                "registered baseline Git worktrees disappeared; refusing "
                f"lossy rollback: {sorted(missing)!r}"
            )
        if current:
            raise MutationJournalError(
                "new registered Git worktrees target unjournaled external "
                "paths; refusing destructive rollback and retaining evidence: "
                f"{sorted(current)!r}"
            )

    def _remove_bound_git_admin_addition(
        self,
        rendered: str | Path,
        *,
        record: Mapping[str, object],
        label: str,
    ) -> None:
        """Remove one inventoried admin addition through held inode authority."""

        device = record.get("device")
        inode = record.get("inode")
        if (
            isinstance(device, bool)
            or not isinstance(device, int)
            or isinstance(inode, bool)
            or not isinstance(inode, int)
        ):
            raise MutationJournalError(
                f"Git-admin addition lacks inode authority: {label}"
            )
        expected_identity = (device, inode)
        logical = _lexical_workspace_path(Path(rendered))
        with self._bound_git_admin_path(logical) as (
            root_fd,
            relative,
            _logical_root,
        ):
            if relative == ".":
                raise MutationJournalError(
                    f"refusing to remove a Git-admin authority root: {label}"
                )
            with _open_settlement_parent_if_present(
                root_fd,
                relative,
                allow_terminal_vcs_metadata=True,
            ) as binding:
                parent_fd, name, parent_chain, missing_index = binding
                if missing_index is not None:
                    raise MutationJournalError(
                        f"Git-admin addition disappeared before removal: {label}"
                    )
                before = os.stat(
                    name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
                if (before.st_dev, before.st_ino) != expected_identity:
                    raise MutationJournalError(
                        f"Git-admin addition changed before removal: {label}"
                    )
                _assert_settlement_parent_binding(
                    root_fd,
                    relative,
                    parent_fd,
                    parent_chain,
                    allow_terminal_vcs_metadata=True,
                )
                if stat.S_ISDIR(before.st_mode) and not stat.S_ISLNK(
                    before.st_mode
                ):
                    descriptor, opened = _open_authority_directory_at(
                        parent_fd,
                        name,
                        label=label,
                    )
                    try:
                        if (opened.st_dev, opened.st_ino) != expected_identity:
                            raise MutationJournalError(
                                f"Git-admin addition changed while opening: {label}"
                            )
                        _remove_bound_directory_tree(
                            parent_fd,
                            name,
                            descriptor,
                            opened,
                        )
                    finally:
                        os.close(descriptor)
                elif stat.S_ISREG(before.st_mode):
                    _remove_bound_regular_entry(
                        parent_fd,
                        name,
                        label=label,
                        expected_metadata=before,
                    )
                elif stat.S_ISLNK(before.st_mode):
                    _remove_bound_symlink_entry(
                        parent_fd,
                        name,
                        label=label,
                        expected_metadata=before,
                    )
                else:
                    raise MutationJournalError(
                        f"Git-admin addition has unsupported type: {label}"
                    )
                _assert_settlement_parent_binding(
                    root_fd,
                    relative,
                    parent_fd,
                    parent_chain,
                    allow_terminal_vcs_metadata=True,
                )
                try:
                    os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
                except FileNotFoundError:
                    pass
                else:
                    raise MutationJournalError(
                        f"Git-admin addition remained after removal: {label}"
                    )

    def _restore_worktree_namespace(self, cwd: Path) -> None:
        expected = self._manifest.get("worktree_namespace_topology")
        if expected is None:
            return
        guarded = self._manifest.get("guarded_worktree_admin_roots", ())
        current = _worktree_namespace_topology(
            cwd,
            guarded_admin_roots=guarded,
        )
        root = _git_common_dir(cwd) / "worktrees"
        expected_root = expected.get(".", {"kind": "missing"})
        if expected_root.get("kind") == "missing":
            current_root = current.get(".", {"kind": "missing"})
            if current_root.get("kind") != "missing":
                self._remove_bound_git_admin_addition(
                    root,
                    record=current_root,
                    label="added Git worktree administration root",
                )
            return
        if expected_root.get("kind") != "directory":
            raise MutationJournalError("unsupported baseline worktrees root")
        current_root = current.get(".", {"kind": "missing"})
        if (
            current_root.get("kind") != "directory"
            or (
                current_root.get("device"),
                current_root.get("inode"),
            )
            != (expected_root.get("device"), expected_root.get("inode"))
        ):
            raise MutationJournalError(
                "baseline Git worktrees root moved or disappeared"
            )
        for relative in _dedupe_roots(
            set(current).difference(expected).difference({"."})
        ):
            self._remove_bound_git_admin_addition(
                root / relative,
                record=current[relative],
                label=f"added Git worktree administration {relative}",
            )
        for relative, metadata in sorted(
            expected.items(),
            key=lambda item: (item[0].count("/"), item[0]),
        ):
            path = root if relative == "." else root / relative
            if metadata.get("kind") == "directory":
                observed = current.get(relative)
                if (
                    not isinstance(observed, Mapping)
                    or observed.get("kind") != "directory"
                    or (observed.get("device"), observed.get("inode"))
                    != (metadata.get("device"), metadata.get("inode"))
                ):
                    raise MutationJournalError(
                        "baseline Git worktree administration changed: "
                        f"{relative}"
                    )
                self._restore_bound_git_admin_entry_metadata(
                    path,
                    record=metadata,
                    label=f"Git worktree administration {relative}",
                    require_identity=True,
                )
            elif metadata.get("kind") == "file":
                # Baseline residual files are rejected at begin; this branch
                # is retained only for forward-compatible manifests.
                raise MutationJournalError(
                    f"cannot restore opaque worktree admin file: {relative}"
                )

    def _remove_added_module_admin(self, cwd: Path) -> None:
        expected = self._manifest.get("module_admin_roots")
        if expected is None:
            return
        baseline = set(expected)
        current = set(_module_admin_roots(cwd))
        missing = baseline.difference(current)
        if missing:
            raise MutationJournalError(
                "baseline Git module administration disappeared; refusing "
                f"lossy rollback: {sorted(missing)!r}"
            )
        modules_root = _git_common_dir(cwd) / "modules"
        topology = _module_namespace_topology(
            cwd,
            guarded_roots=baseline,
        )
        for relative in sorted(
            current.difference(baseline),
            key=lambda path: (path.count("/"), path),
            reverse=True,
        ):
            record = topology.get(relative)
            if not isinstance(record, Mapping):
                raise MutationJournalError(
                    "added Git module administration lacks inode authority: "
                    f"{relative}"
                )
            self._remove_bound_git_admin_addition(
                modules_root / relative,
                record=record,
                label=f"added Git module administration {relative}",
            )

    def _restore_module_namespace(self, cwd: Path) -> None:
        expected = self._manifest.get("module_namespace_topology")
        if expected is None:
            return
        guarded = (
            *self._manifest.get("initialized_module_admin_roots", ()),
            *self._manifest.get("cached_module_admin_roots", ()),
        )
        current = _module_namespace_topology(cwd, guarded_roots=guarded)
        modules_root = _git_common_dir(cwd) / "modules"
        expected_root = expected.get(".", {"kind": "missing"})
        if expected_root.get("kind") == "missing":
            current_root = current.get(".", {"kind": "missing"})
            if current_root.get("kind") != "missing":
                self._remove_bound_git_admin_addition(
                    modules_root,
                    record=current_root,
                    label="added Git module administration root",
                )
            return
        if expected_root.get("kind") != "directory":
            raise MutationJournalError("unsupported baseline modules root")
        current_root = current.get(".", {"kind": "missing"})
        if (
            current_root.get("kind") != "directory"
            or (
                current_root.get("device"),
                current_root.get("inode"),
            )
            != (expected_root.get("device"), expected_root.get("inode"))
        ):
            raise MutationJournalError("Git modules root moved or disappeared")
        additions = _dedupe_roots(
            set(current).difference(expected).difference({"."})
        )
        for relative in sorted(
            additions,
            key=lambda path: (path.count("/"), path),
            reverse=True,
        ):
            self._remove_bound_git_admin_addition(
                modules_root / relative,
                record=current[relative],
                label=f"added Git module namespace {relative}",
            )
        for relative, metadata in sorted(
            expected.items(),
            key=lambda item: (item[0].count("/"), item[0]),
        ):
            if metadata.get("kind") != "directory":
                raise MutationJournalError(
                    f"unsupported baseline module namespace entry: {relative}"
                )
            observed = current.get(relative)
            if (
                not isinstance(observed, Mapping)
                or observed.get("kind") != "directory"
                or (observed.get("device"), observed.get("inode"))
                != (metadata.get("device"), metadata.get("inode"))
            ):
                raise MutationJournalError(
                    f"baseline Git module namespace changed: {relative}"
                )
            directory = (
                modules_root if relative == "." else modules_root / relative
            )
            self._restore_bound_git_admin_entry_metadata(
                directory,
                record=metadata,
                label=f"Git module namespace {relative}",
                require_identity=True,
            )

    def _restore_directory_modes(
        self,
        cwd: Path,
        *,
        observed_parent_bindings: Mapping[
            str, tuple[int, int] | None
        ] | None = None,
    ) -> dict[str, _BoundWorkspaceDirectoryRecord]:
        """Restore directory topology/metadata through one held workspace fd."""

        expected_raw = self._manifest.get("directory_modes")
        if expected_raw is None:
            return {}
        expected, expected_xattrs = _validated_workspace_directory_baseline(
            expected_raw,
            self._manifest.get("directory_xattrs", {}),
        )
        captured_identities = self._effective_workspace_directory_identities(
            expected,
        )
        excluded_roots = (
            *self._manifest.get("metadata_relatives", ()),
            *self._manifest.get("initialized_gitlinks", ()),
            *self._effective_ignored_directory_roots(
                cwd,
                protected_paths=expected,
            ),
        )
        normalized_excluded_roots = tuple(_dedupe_roots(excluded_roots))
        for relative in expected:
            if relative == ".":
                continue
            if any(
                relative == excluded
                or relative.startswith(excluded.rstrip("/") + "/")
                for excluded in normalized_excluded_roots
            ):
                raise MutationJournalError(
                    "workspace directory baseline crosses an excluded root: "
                    f"{relative!r}"
                )
        with _bound_workspace_restore_root(self) as root_fd:
            authority = _bound_workspace_directory_inventory(
                root_fd,
                excluded_roots=normalized_excluded_roots,
            )
            root_record = authority.get(".")
            if root_record is None:
                raise MutationJournalError(
                    "workspace root directory authority is absent"
                )

            # Bind every prior root observation before the first topology
            # mutation.  A provider-created parent may be absent from the
            # baseline yet remains essential authority against a later swap.
            for relative, expected_identity in (
                observed_parent_bindings or {}
            ).items():
                current = authority.get(relative)
                if expected_identity is None:
                    _assert_bound_workspace_absence_token(
                        root_fd,
                        relative,
                        authority,
                    )
                    continue
                if current is None or (current.device, current.inode) != (
                    expected_identity[0],
                    expected_identity[1],
                ):
                    raise MutationJournalError(
                        "workspace directory changed after root restoration: "
                        f"{relative!r}"
                    )

            for relative in set(authority).intersection(expected):
                current = authority[relative]
                current_identity = (current.device, current.inode)
                if current_identity == captured_identities[relative]:
                    continue
                if (
                    self._restored_workspace_entry_authority.get(relative)
                    == current_identity
                ):
                    # Recursive snapshot restoration replaces its root with a
                    # private descriptor-bound directory.  The installer
                    # records that exact published inode; carry it as the new
                    # authority instead of requiring the removed baseline
                    # inode to reappear.
                    continue
                raise MutationJournalError(
                    "workspace baseline directory differs from its captured "
                    f"identity: {relative!r}"
                )

            additions = sorted(
                set(authority).difference(expected).difference({"."}),
                key=lambda path: (path.count("/"), path),
                reverse=True,
            )
            for relative in additions:
                record = authority[relative]
                _remove_bound_empty_workspace_directory(
                    root_fd,
                    relative,
                    record,
                    authority,
                )
                del authority[relative]

            for relative in sorted(
                set(expected).difference(authority).difference({"."}),
                key=lambda path: (path.count("/"), path),
            ):
                record = _create_bound_workspace_baseline_directory(
                    root_fd,
                    relative,
                    expected[relative],
                    expected_xattrs[relative],
                    authority,
                )
                authority[relative] = record

            if set(authority) != set(expected):
                raise MutationJournalError(
                    "workspace directory topology differs from baseline"
                )

            # Descendants precede restrictive parents, and the held root is
            # restored last, so metadata never strands a later operation.
            for relative in sorted(
                expected,
                key=lambda path: (path.count("/"), path),
                reverse=True,
            ):
                record = authority[relative]
                _restore_bound_workspace_directory_metadata(
                    root_fd,
                    relative,
                    record,
                    expected[relative],
                    expected_xattrs[relative],
                    authority,
                )
            return _reprove_bound_workspace_directory_authority(
                root_fd,
                authority,
                expected,
                expected_xattrs,
                excluded_roots=normalized_excluded_roots,
            )

    def _reprove_restored_workspace_directory_authority(
        self,
        cwd: Path,
        authority: Mapping[str, _BoundWorkspaceDirectoryRecord],
    ) -> dict[str, _BoundWorkspaceDirectoryRecord]:
        """Reprove the carried directory grant at the terminal handoff."""

        expected_raw = self._manifest.get("directory_modes")
        if expected_raw is None:
            if authority:
                raise MutationJournalError(
                    "workspace directory authority lacks a baseline"
                )
            return {}
        expected, expected_xattrs = _validated_workspace_directory_baseline(
            expected_raw,
            self._manifest.get("directory_xattrs", {}),
        )
        excluded_roots = tuple(_dedupe_roots((
            *self._manifest.get("metadata_relatives", ()),
            *self._manifest.get("initialized_gitlinks", ()),
            *self._effective_ignored_directory_roots(
                cwd,
                protected_paths=expected,
            ),
        )))
        with _bound_workspace_restore_root(self) as root_fd:
            return _reprove_bound_workspace_directory_authority(
                root_fd,
                authority,
                expected,
                expected_xattrs,
                excluded_roots=excluded_roots,
            )

    def _prepare_restore_access(self, *, writable: bool) -> None:
        """Reopen known real directories without following hostile aliases."""

        def restore_directory(
            path: Path,
            mode: int,
            *,
            expected_identity: tuple[int, int] | None = None,
        ) -> None:
            try:
                metadata = _descriptor_bound_lstat(path)
            except FileNotFoundError:
                return
            if not stat.S_ISDIR(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
                return
            requested = mode | (0o700 if writable else 0)
            if os.name == "nt":
                path.chmod(requested)
                return
            _make_real_directory_tree_owner_accessible(
                path,
                tree_label=f"restore-access directory {path}",
                recursive=False,
                final_root_mode=requested,
                expected_root_identity=expected_identity,
            )

        def restore_admin_directory(
            path: Path,
            record: Mapping[str, object],
            *,
            recursive: bool = False,
            label: str,
        ) -> None:
            """Prepare only one captured admin inode through held authority."""

            mode = record.get("mode")
            device = record.get("device")
            inode = record.get("inode")
            if any(
                isinstance(value, bool) or not isinstance(value, int)
                for value in (mode, device, inode)
            ):
                raise MutationJournalError(
                    f"Git-admin access record is malformed: {label}"
                )
            with self._open_bound_git_admin_directory(
                path,
                record=record,
                label=label,
            ) as descriptor:
                _make_real_directory_tree_owner_accessible(
                    path,
                    tree_label=label,
                    root_descriptor=descriptor,
                    recursive=recursive,
                    final_root_mode=(
                        int(cast(int, mode)) | (0o700 if writable else 0)
                    ),
                    expected_root_identity=(
                        int(cast(int, device)),
                        int(cast(int, inode)),
                    ),
                )

        cwd = self._bound_workspace_cwd()
        directory_modes = self._manifest.get("directory_modes", {})
        directory_identities = self._effective_workspace_directory_identities(
            directory_modes,
        )
        root_mode = directory_modes.get(".")
        if root_mode is not None:
            restore_directory(
                cwd,
                int(root_mode),
                expected_identity=directory_identities["."],
            )

        authority = self._manifest.get("authority_lock")
        if authority is not None:
            common_dir = self._bound_manifest_path(
                str(authority["common_dir"])
            )
            metadata = self._bound_path_metadata(common_dir)
            if (
                not stat.S_ISDIR(metadata.st_mode)
                or stat.S_ISLNK(metadata.st_mode)
                or metadata.st_dev != int(authority["common_device"])
                or metadata.st_ino != int(authority["common_inode"])
            ):
                raise MutationJournalError(
                    "workspace authority common dir moved or aliased"
                )
            # Keep the authority parent at its exact mode until after the lock
            # inode has been validated. It may also be an admin root below.
            restore_directory(
                common_dir,
                int(authority["common_mode"]),
                expected_identity=(
                    int(authority["common_device"]),
                    int(authority["common_inode"]),
                ),
            )

        for relative, mode in sorted(
            directory_modes.items(),
            key=lambda item: (item[0].count("/"), item[0]),
        ):
            if relative == ".":
                continue
            path = cwd if relative == "." else cwd / relative
            restore_directory(
                path,
                int(mode),
                expected_identity=directory_identities[relative],
            )

        for record in self._manifest.get("git_admin_topology", ()):
            root = _lexical_workspace_path(Path(str(record["root"])))
            restore_admin_directory(
                root,
                record,
                label=f"Git admin root {root}",
            )
            for name, expected in record.get("entries", {}).items():
                if expected.get("kind") not in {
                    "owned_directory", "guarded_directory"
                }:
                    continue
                path = root / name
                restore_admin_directory(
                    path,
                    expected,
                    recursive=(
                        writable
                        and expected.get("kind") == "guarded_directory"
                    ),
                    label=f"Git admin directory {path}",
                )

        objects_root = _lexical_workspace_path(Path(
            str(self._manifest.get("objects_path", ""))
        ))
        if str(objects_root):
            restore_admin_directory(
                objects_root,
                {
                    "mode": self._manifest.get("objects_root_mode"),
                    "device": self._manifest.get("objects_root_device"),
                    "inode": self._manifest.get("objects_root_inode"),
                },
                label="Git object root",
            )
            for relative, expected in sorted(
                self._manifest.get("object_inventory", {}).items(),
                key=lambda item: (item[0].count("/"), item[0]),
            ):
                if expected.get("kind") == "directory":
                    restore_admin_directory(
                        objects_root / relative,
                        expected,
                        label=f"Git object directory {relative}",
                    )
            if writable:
                with self._open_bound_git_admin_directory(
                    objects_root,
                    record={
                        "device": self._manifest.get("objects_root_device"),
                        "inode": self._manifest.get("objects_root_inode"),
                    },
                    label="Git object root",
                ) as objects_fd:
                    _make_real_directory_tree_owner_accessible(
                        objects_root,
                        tree_label="Git object",
                        root_descriptor=objects_fd,
                        expected_root_identity=(
                            int(self._manifest["objects_root_device"]),
                            int(self._manifest["objects_root_inode"]),
                        ),
                    )

        registry_path = self._manifest.get("registry_directory")
        if writable and registry_path is not None:
            with self._bound_registry_directory() as registry_fd:
                _make_real_directory_tree_owner_accessible(
                    self._bound_manifest_path(str(registry_path)),
                    tree_label="mutation registry",
                    root_descriptor=registry_fd,
                )

        current_common_dir = _git_common_dir(cwd)
        captured_common_dir = self._manifest.get("git_common_dir")
        if captured_common_dir is None:
            objects_path = self._manifest.get("objects_path")
            captured_common_dir = (
                str(Path(str(objects_path)).parent)
                if objects_path
                else str(current_common_dir)
            )
        common_dir = _lexical_workspace_path(Path(str(captured_common_dir)))
        if not self._bound_paths_same(current_common_dir, common_dir):
            raise MutationJournalError(
                "Git common directory moved during restore preparation: "
                f"current={current_common_dir} expected={common_dir}"
            )
        module_namespace = self._manifest.get("module_namespace_topology")
        if (
            isinstance(module_namespace, dict)
            and module_namespace.get(".", {}).get("kind") == "directory"
        ):
            modules_root = common_dir / "modules"
            for relative, expected in module_namespace.items():
                if expected.get("kind") == "directory":
                    restore_admin_directory(
                        modules_root if relative == "." else modules_root / relative,
                        expected,
                        label=f"Git module namespace {relative}",
                    )

        worktree_namespace = self._manifest.get("worktree_namespace_topology")
        if (
            isinstance(worktree_namespace, dict)
            and worktree_namespace.get(".", {}).get("kind") == "directory"
        ):
            worktrees_root = common_dir / "worktrees"
            for relative, expected in worktree_namespace.items():
                if expected.get("kind") == "directory":
                    restore_admin_directory(
                        worktrees_root
                        if relative == "."
                        else worktrees_root / relative,
                        expected,
                        label=f"Git worktree namespace {relative}",
                    )

        cached_metadata = self._manifest.get("cached_module_metadata", {})
        for record in self._manifest.get("cached_module_controls", ()):
            root = _lexical_workspace_path(Path(str(record["root"])))
            root_baseline = cached_metadata[str(record["relative_root"])]
            restore_admin_directory(
                root,
                root_baseline,
                label=f"cached Git module root {record['relative_root']}",
            )
            for relative, expected in record["entries"].items():
                if expected.get("kind") == "directory":
                    restore_admin_directory(
                        root / relative,
                        expected,
                        label=(
                            "cached Git module control "
                            f"{record['relative_root']}/{relative}"
                        ),
                    )
            for name, expected in record["payload_roots"].items():
                restore_admin_directory(
                    root / name,
                    expected,
                    label=(
                        "cached Git module payload "
                        f"{record['relative_root']}/{name}"
                    ),
                )

        for record in self._manifest.get(
            "absent_worktree_admin_controls", ()
        ):
            root = _lexical_workspace_path(Path(str(record["root"])))
            restore_admin_directory(
                root,
                record,
                label=f"missing-worktree admin {record.get('name')}",
            )
            for relative, expected in record["entries"].items():
                if expected.get("kind") == "directory":
                    restore_admin_directory(
                        root / relative,
                        expected,
                        label=f"missing-worktree admin {relative}",
                    )

        if not writable:
            return
        excluded = tuple(_dedupe_roots((
            *self._manifest.get("metadata_relatives", ()),
            *self._manifest.get("initialized_gitlinks", ()),
            *self._manifest.get("ignored_nested_vcs_roots", ()),
        )))

        with _bound_workspace_restore_root(self) as root_fd:
            _make_real_directory_tree_owner_accessible(
                cwd,
                tree_label="workspace restore-access tree",
                root_descriptor=root_fd,
                excluded_roots=(".git", *excluded),
            )

    def _restore_refs_tree(self, cwd: Path) -> None:
        expected = self._manifest.get("refs_tree")
        if expected is None:
            return
        current_root = _refs_path(cwd)
        root = self._bound_manifest_path(
            str(self._manifest.get("refs_path", current_root))
        )
        if (
            not self._bound_paths_equivalent(
                current_root,
                str(self._manifest.get("refs_path", root)),
            )
            or not self._bound_paths_same(
                root,
                str(self._manifest.get("refs_resolved_path", root)),
            )
        ):
            raise MutationJournalError("Git refs directory moved or aliased")
        self._restore_bound_git_admin_tree(
            str(self._manifest.get("refs_path", root)),
            exists=True,
            record={
                "mode": self._manifest.get("refs_root_mode"),
                "device": self._manifest.get("refs_root_device"),
                "inode": self._manifest.get("refs_root_inode"),
                "xattrs": self._manifest.get("refs_root_xattrs", {}),
            },
            entries=expected,
            label="Git refs",
        )

    def _restore_log_refs_tree(self, cwd: Path) -> None:
        current_root = _git_control_path(cwd, "logs/refs")
        root = self._bound_manifest_path(
            str(self._manifest.get("log_refs_path", current_root))
        )
        if not self._bound_paths_equivalent(
            current_root,
            str(self._manifest.get("log_refs_path", root)),
        ):
            raise MutationJournalError("Git ref-log directory moved or aliased")
        expected_exists = bool(self._manifest.get("log_refs_exists", False))
        self._restore_bound_git_admin_tree(
            str(self._manifest.get("log_refs_path", root)),
            exists=expected_exists,
            record={
                "mode": self._manifest.get("log_refs_root_mode"),
                "device": self._manifest.get("log_refs_root_device"),
                "inode": self._manifest.get("log_refs_root_inode"),
                "xattrs": self._manifest.get("log_refs_root_xattrs", {}),
            },
            entries=self._manifest.get("log_refs_tree") or {},
            label="Git ref logs",
        )

    def _restore_refs(self, cwd: Path) -> None:
        expected = self._manifest.get("refs")
        if expected is None:
            return
        current = _refs_snapshot(cwd)
        commands = ["start"]
        commands.extend(
            f"update {ref} {oid}"
            for ref, oid in sorted(expected.items())
            if current.get(ref) != oid
        )
        commands.extend(
            f"delete {ref}"
            for ref in sorted(set(current).difference(expected))
        )
        commands.extend(("prepare", "commit"))
        if len(commands) == 3:
            return
        env, authority_fds = _bound_git_subprocess_authority(cwd)
        result = subprocess.run(
            [
                "git", *_GIT_SAFE_OPTIONS,
                "update-ref", "--stdin",
            ],
            cwd=cwd,
            env=env,
            input=("\n".join(commands) + "\n").encode(),
            capture_output=True,
            check=False,
            pass_fds=authority_fds,
        )
        if result.returncode != 0:
            raise MutationJournalError(
                "failed to restore Git refs: "
                + result.stderr.decode("utf-8", errors="replace").strip()
            )

    def _restore_object_inventory(
        self,
        cwd: Path,
        *,
        cleanup_additions: bool = True,
    ) -> None:
        expected = self._manifest.get("object_inventory")
        if expected is None:
            return
        current_root = _objects_path(cwd)
        root = self._bound_manifest_path(
            str(self._manifest.get("objects_path", current_root))
        )
        if (
            not self._bound_paths_equivalent(
                current_root,
                str(self._manifest.get("objects_path", root)),
            )
            or not self._bound_paths_same(
                root,
                str(self._manifest.get("objects_resolved_path", root)),
            )
        ):
            raise MutationJournalError("Git object directory moved or aliased")
        expected_root_mode = self._manifest.get("objects_root_mode")
        if expected_root_mode is not None:
            self._restore_bound_git_admin_entry_metadata(
                str(self._manifest.get("objects_path", root)),
                record={
                    "mode": expected_root_mode,
                    "device": self._manifest.get("objects_root_device"),
                    "inode": self._manifest.get("objects_root_inode"),
                    "xattrs": self._manifest.get("objects_root_xattrs", {}),
                },
                label="Git object root",
                require_identity=True,
            )
        _root, current = _object_inventory(cwd)
        baseline_changes = {
            path
            for path, metadata in expected.items()
            if current.get(path) != metadata
        }
        timestamp_only = self._verified_timestamp_only_object_changes(
            cwd,
            expected,
            current,
            allow_additions=True,
        )
        if timestamp_only is not None:
            baseline_changes.difference_update(timestamp_only)
        restorable_directories = {
            path
            for path in baseline_changes
            if expected[path].get("kind") == "directory"
            and current.get(path, {}).get("kind") == "directory"
            and all(
                current[path].get(key) == expected[path].get(key)
                for key in ("device", "inode")
            )
        }
        restorable_files = {
            path
            for path in baseline_changes
            if expected[path].get("kind") == "file"
            and current.get(path, {}).get("kind") == "file"
            and all(
                current[path].get(key) == expected[path].get(key)
                for key in (
                    "device", "inode", "nlink", "size", "mtime_ns", "ctime_ns"
                )
            )
        }
        irreplaceable_changes = baseline_changes.difference(
            restorable_directories | restorable_files
        )
        if irreplaceable_changes:
            raise MutationJournalError(
                "pre-existing Git objects changed or disappeared: "
                f"{sorted(irreplaceable_changes)[:10]!r}"
            )
        for relative in sorted(
            restorable_directories,
            key=lambda path: (path.count("/"), path),
        ):
            self._restore_bound_git_admin_entry_metadata(
                root / relative,
                record=expected[relative],
                label=f"Git object directory {relative}",
                require_identity=True,
            )
        for relative in sorted(restorable_files):
            object_file = root / relative
            self._restore_bound_git_admin_entry_metadata(
                object_file,
                record=expected[relative],
                label=f"Git object file {relative}",
                require_identity=True,
            )
            restored, _xattrs = self._inspect_bound_git_admin_entry(
                object_file,
                label=f"Git object file {relative}",
            )
            expected[relative]["ctime_ns"] = restored.st_ctime_ns
        if not cleanup_additions:
            return
        for relative in sorted(
            set(current).difference(expected),
            key=lambda path: (path.count("/"), path),
            reverse=True,
        ):
            self._remove_bound_git_admin_addition(
                root / relative,
                record=current[relative],
                label=f"added Git object {relative}",
            )

    def _registry_marker(self) -> Path | None:
        rendered = self._manifest.get("registry_marker")
        if rendered is None:
            return None
        marker = Path(str(rendered))
        authority = self._manifest.get("registry_directory")
        if authority is None:
            raise MutationJournalError(
                "mutation registry directory authority is absent"
            )
        authority_path = self._bound_manifest_path(str(authority))
        marker = self._bound_manifest_path(marker)
        expected = authority_path / f"{self.transaction_id}.json"
        if marker != expected or marker.parent != authority_path:
            raise MutationJournalError(
                f"mutation registry marker moved or aliased: {marker}"
            )
        return marker

    def _assert_registry_marker_unchanged(self) -> None:
        marker = self._registry_marker()
        if marker is None:
            return
        expected = self._expected_registry_marker_payload()
        with self._bound_registry_directory() as registry_fd:
            try:
                observed, _metadata = _read_bound_regular_entry(
                    registry_fd,
                    f"{self.transaction_id}.json",
                    label=f"mutation registry marker {self.transaction_id}",
                    max_bytes=max(len(expected), 1),
                )
            except MutationJournalError as exc:
                raise MutationJournalError(
                    f"mutation registry marker is absent or unsafe: {marker}"
                ) from exc
        if observed != expected:
            raise MutationJournalError(
                f"mutation registry marker changed: {marker}"
            )

    def _restore_registry_marker(self) -> None:
        marker = self._registry_marker()
        if marker is None:
            return
        expected = self._expected_registry_marker_payload()
        marker_name = f"{self.transaction_id}.json"
        with self._bound_registry_directory() as registry_fd:
            try:
                os.stat(
                    marker_name,
                    dir_fd=registry_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                _publish_bound_regular_noreplace(
                    registry_fd,
                    marker_name,
                    expected,
                    label=(
                        "restored mutation registry marker "
                        f"{self.transaction_id}"
                    ),
                )
            observed, _metadata = _read_bound_regular_entry(
                registry_fd,
                marker_name,
                label=f"mutation registry marker {self.transaction_id}",
                max_bytes=max(len(expected), 1),
            )
            if observed != expected:
                raise MutationJournalError(
                    "restored mutation registry marker payload changed"
                )

    @contextmanager
    def _bound_registry_directory(self) -> Iterator[int]:
        """Bind the exact registry inode beneath the held common directory."""

        logical_cwd = Path(self._manifest["cwd"])
        if _active_workspace_mutation_authority(logical_cwd) is None:
            with workspace_mutation_lock(logical_cwd):
                with self._bound_registry_directory() as descriptor:
                    yield descriptor
            return
        authority = _assert_workspace_mutation_authority(logical_cwd)
        recorded = self._manifest.get("registry_directory")
        captured_common = (self._manifest.get("authority_lock") or {}).get(
            "common_dir"
        )
        if (
            recorded is None
            or captured_common is None
            or Path(str(captured_common)) != authority.common_dir
            or Path(str(recorded))
            != authority.common_dir / _REGISTRY_DIRECTORY
        ):
            raise MutationJournalError(
                "mutation registry directory conflicts with held authority"
            )
        expected_device = self._manifest.get("registry_directory_device")
        expected_inode = self._manifest.get("registry_directory_inode")
        expected_mode = self._manifest.get("registry_directory_mode")
        if (
            type(expected_device) is not int
            or type(expected_inode) is not int
            or type(expected_mode) is not int
            or expected_device < 0
            or expected_inode <= 0
            or expected_mode < 0
            or expected_mode > 0o7777
        ):
            raise MutationJournalError(
                "mutation registry directory identity is absent or malformed"
            )
        descriptor, opened = _open_authority_directory_at(
            authority.common_descriptor,
            _REGISTRY_DIRECTORY,
            label="mutation registry directory",
        )
        if (
            (opened.st_dev, opened.st_ino)
            != (expected_device, expected_inode)
            or stat.S_IMODE(opened.st_mode) != expected_mode
        ):
            os.close(descriptor)
            raise MutationJournalError(
                "mutation registry directory changed from its manifest identity"
            )
        try:
            yield descriptor
            held = os.fstat(descriptor)
            current = os.stat(
                _REGISTRY_DIRECTORY,
                dir_fd=authority.common_descriptor,
                follow_symlinks=False,
            )
            if (
                not stat.S_ISDIR(held.st_mode)
                or (held.st_dev, held.st_ino)
                != (expected_device, expected_inode)
                or stat.S_IMODE(held.st_mode) != expected_mode
                or (current.st_dev, current.st_ino)
                != (expected_device, expected_inode)
                or stat.S_IMODE(current.st_mode) != expected_mode
            ):
                raise MutationJournalError(
                    "mutation registry directory changed during cleanup"
                )
        except MutationJournalError:
            raise
        except (OSError, TypeError, ValueError) as exc:
            raise MutationJournalError(
                f"cannot revalidate mutation registry directory: {exc}"
            ) from exc
        finally:
            os.close(descriptor)

    def _expected_registry_marker_payload(
        self,
        *,
        journal_fd: int | None = None,
    ) -> bytes:
        marker = self._registry_marker()
        if marker is None:
            raise MutationJournalError(
                "mutation registry marker authority is absent"
            )
        expected_marker = marker.parent / f"{self.transaction_id}.json"
        if marker != expected_marker:
            raise MutationJournalError(
                "mutation registry marker transaction binding changed"
            )
        owned_descriptor = journal_fd is None
        if journal_fd is None:
            journal_fd, opened = _open_authority_directory(
                self._logical_journal_dir,
                label="mutation journal registry authority",
            )
        else:
            opened = os.fstat(journal_fd)
        try:
            if (
                self._logical_journal_identity is None
                or (opened.st_dev, opened.st_ino)
                != self._logical_journal_identity
            ):
                raise MutationJournalError(
                    "mutation journal changed before registry cleanup"
                )
            payload, _metadata = _read_bound_regular_entry(
                journal_fd,
                "registry_marker",
                label="mutation journal registry-marker authority",
                max_bytes=_CONTROL_FILE_MAX_BYTES,
            )
            if owned_descriptor:
                _assert_authority_directory_binding(
                    self._logical_journal_dir,
                    journal_fd,
                    opened,
                    label="mutation journal registry authority",
                )
        finally:
            if owned_descriptor:
                os.close(journal_fd)
        try:
            record = json.loads(payload)
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            raise MutationJournalError(
                "mutation journal registry-marker authority is malformed"
            ) from exc
        if (
            not isinstance(record, dict)
            or set(record)
            != {"schema", "transaction_id", "cwd", "spec_dir", "journal_dir"}
            or record.get("schema") != _SCHEMA
            or record.get("transaction_id") != self.transaction_id
            or record.get("cwd") != str(Path(self._manifest["cwd"]))
            or record.get("spec_dir")
            != str(_originating_spec_dir(
                self._registry_authority_journal_dir.parent,
            ))
            or record.get("journal_dir")
            != str(self._registry_authority_journal_dir.resolve())
        ):
            raise MutationJournalError(
                "mutation journal registry-marker authority changed"
            )
        return payload

    def _matching_registry_cleanup_quarantines(
        self,
        registry_fd: int,
        expected_payload: bytes,
    ) -> tuple[tuple[str, os.stat_result, bytes], ...]:
        """Bind stale private marker reservations/quarantines exactly."""

        prefix = f".crucible-cleanup-{self.transaction_id}-"
        matches: list[tuple[str, os.stat_result, bytes]] = []
        for name in _bounded_directory_names(
            registry_fd,
            label="mutation registry directory",
            max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
        ):
            suffix = name.removeprefix(prefix)
            owned_name = (
                name.startswith(prefix)
                and len(suffix) == 64
                and all(
                    character in "0123456789abcdef"
                    for character in suffix
                )
            )
            if name == f"{self.transaction_id}.json":
                continue
            try:
                payload, metadata = _read_bound_regular_entry(
                    registry_fd,
                    name,
                    label="mutation registry cleanup quarantine",
                    max_bytes=max(len(expected_payload), 1),
                )
            except MutationJournalError as exc:
                if not owned_name:
                    continue
                raise MutationJournalError(
                    "mutation registry cleanup quarantine is unsafe"
                ) from exc
            if not owned_name:
                if payload == expected_payload:
                    raise MutationJournalError(
                        "mutation registry marker moved outside its cleanup "
                        "namespace"
                    )
                continue
            if payload not in {b"", expected_payload}:
                raise MutationJournalError(
                    "mutation registry cleanup quarantine has foreign payload"
                )
            matches.append((name, metadata, payload))
        if sum(payload == expected_payload for _name, _metadata, payload in matches) > 1:
            raise MutationJournalError(
                "mutation registry contains duplicate cleanup quarantines"
            )
        return tuple(matches)

    def _remove_registry_marker(
        self,
        *,
        allow_missing: bool = False,
        journal_fd: int | None = None,
        expected_payload: bytes | None = None,
    ) -> None:
        marker = self._registry_marker()
        if marker is None:
            return
        marker_name = f"{self.transaction_id}.json"
        quarantine_prefix = (
            f".crucible-cleanup-{self.transaction_id}-"
        )
        if expected_payload is None:
            expected_payload = self._expected_registry_marker_payload(
                journal_fd=journal_fd,
            )
        with self._bound_registry_directory() as registry_fd:
            quarantines = self._matching_registry_cleanup_quarantines(
                registry_fd,
                expected_payload,
            )
            reservations = [
                (name, metadata)
                for name, metadata, payload in quarantines
                if payload == b""
            ]
            marker_quarantines = [
                (name, metadata)
                for name, metadata, payload in quarantines
                if payload == expected_payload
            ]
            for reservation_name, reservation_metadata in reservations:
                _remove_bound_regular_entry(
                    registry_fd,
                    reservation_name,
                    expected_metadata=reservation_metadata,
                    expected_payload=b"",
                    label="mutation registry cleanup reservation",
                    quarantine_prefix=quarantine_prefix,
                )
            try:
                metadata = os.stat(
                    marker_name,
                    dir_fd=registry_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                if allow_missing:
                    if not marker_quarantines:
                        return
                    quarantine_name, quarantine_metadata = marker_quarantines[0]
                    _remove_bound_regular_entry(
                        registry_fd,
                        quarantine_name,
                        expected_metadata=quarantine_metadata,
                        expected_payload=expected_payload,
                        label=(
                            "mutation registry marker cleanup quarantine "
                            f"{self.transaction_id}"
                        ),
                        quarantine_prefix=quarantine_prefix,
                    )
                    return
                raise MutationJournalError(
                    f"mutation registry marker was removed: {marker}"
                ) from None
            if marker_quarantines:
                raise MutationJournalError(
                    "mutation registry marker has a duplicate cleanup quarantine"
                )
            _remove_bound_regular_entry(
                registry_fd,
                marker_name,
                expected_metadata=metadata,
                expected_payload=expected_payload,
                label=f"mutation registry marker {self.transaction_id}",
                quarantine_prefix=quarantine_prefix,
            )
            try:
                os.stat(
                    marker_name,
                    dir_fd=registry_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                pass
            else:
                raise MutationJournalError(
                    "mutation registry marker remained after exact cleanup"
                )

    def _assert_no_filtered_scope_paths(self, cwd: Path) -> None:
        """Reject newly materialized filtered outputs before Git capture."""

        scope = tuple(self._manifest["scope"])
        if not scope:
            return
        recursive_scope = set(self._manifest.get("recursive_scope", ()))

        def _in_scope(relative: str) -> bool:
            return any(
                relative == root
                or (
                    root in recursive_scope
                    and relative.startswith(root.rstrip("/") + "/")
                )
                for root in scope
            )

        names = _run_bound_git_process(
            cwd,
            _git_argv(
                "ls-files",
                "--cached",
                "--others",
                "-z",
                "--",
                *scope,
            ),
            GIT_OPTIONAL_LOCKS="0",
            GIT_LITERAL_PATHSPECS="1",
        )
        if names.returncode != 0:
            raise MutationJournalError(
                "cannot enumerate mutation scope for Git filter safety: "
                + names.stderr.decode("utf-8", errors="replace").strip()
            )
        relevant = tuple(dict.fromkeys(
            record
            for encoded in names.stdout.split(b"\0")
            if encoded
            for record in (_normalize_relative(cwd, os.fsdecode(encoded)),)
            if _in_scope(record)
        ))
        if not relevant:
            return
        attributes = _run_bound_git_process(
            cwd,
            _git_argv("check-attr", "-z", "filter", "--stdin"),
            input_bytes=(
                b"\0".join(os.fsencode(path) for path in relevant) + b"\0"
            ),
            GIT_OPTIONAL_LOCKS="0",
            GIT_LITERAL_PATHSPECS="1",
        )
        if attributes.returncode != 0:
            raise MutationJournalError(
                "cannot inspect mutation-scope Git filter attributes: "
                + attributes.stderr.decode("utf-8", errors="replace").strip()
            )
        fields = attributes.stdout.split(b"\0")
        if fields and fields[-1] == b"":
            fields.pop()
        if len(fields) % 3:
            raise MutationJournalError(
                "malformed mutation-scope git check-attr output"
            )
        filtered = tuple(
            os.fsdecode(path)
            for path, attribute, value in zip(
                fields[0::3], fields[1::3], fields[2::3], strict=True
            )
            if attribute.lower() == b"filter"
            and value.lower() not in {b"unset", b"unspecified"}
        )
        if filtered:
            raise MutationJournalError(
                "mutation scope contains externally filtered paths; exact "
                "capture cannot author their canonical stored image without "
                f"executing a driver: {list(filtered)!r}"
            )

    def prepare_git_capture(self) -> None:
        """Restore attribute/config policy before post-invocation Git reads.

        Assay calls this immediately after the backend returns and before it
        runs diff/status. Persist the observed policy mutation so subsequent
        validation still classifies the write even though the dangerous rule
        has already been removed from the worktree.
        """

        family_rollback_terminal = (
            self.state == "rolled_back"
            and isinstance(
                self._manifest.get("lifecycle_family_rollback"),
                dict,
            )
        )
        if (
            not self.active
            and self.state != "committed"
            and not family_rollback_terminal
        ):
            raise MutationJournalError(
                f"cannot prepare Git capture for inactive slice {self.slice_id}"
            )
        self._require_writer_epoch_quiescence(frontier="Git capture")
        cwd = self._bound_workspace_cwd()
        # Validate durable policy authority before any repair mutates the
        # checkout.  A corrupt proof must fail closed with the original bytes
        # still available for recovery inspection.
        retained_deferred = (
            self._validated_deferred_recursive_attribute_policy_roots()
        )
        changed_admin = self._restore_attribute_admin_control(cwd)
        changed_policy = set(self._restore_attribute_policy(
            cwd,
            defer_deleted_recursive_roots=True,
        ))
        deferred_roots = self._deferred_recursive_attribute_policy_roots(
            cwd,
            changed_policy,
        )
        updated_deferred = dict(retained_deferred)
        for path in changed_policy:
            recursive_root = deferred_roots.get(path)
            if recursive_root is None:
                # A later direct policy mutation must revoke an earlier
                # whole-root tombstone proof instead of laundering it.
                updated_deferred.pop(path, None)
            else:
                updated_deferred[path] = recursive_root
        if self._restore_validation_in_progress:
            self._restore_new_attribute_changes.update(changed_policy)
            self._restore_new_attribute_admin_changed = (
                self._restore_new_attribute_admin_changed or changed_admin
            )
        if (
            changed_policy
            or changed_admin
            or updated_deferred != retained_deferred
        ):
            retained = set(
                self._manifest.get("pre_capture_attribute_changes", ())
            )
            self._manifest["pre_capture_attribute_changes"] = sorted(
                retained | changed_policy
            )
            if changed_admin:
                self._manifest["pre_capture_attribute_admin_changed"] = True
            self._manifest[
                _DEFERRED_RECURSIVE_ATTRIBUTE_POLICY_KEY
            ] = updated_deferred
            self._write()
        self._assert_no_filtered_scope_paths(cwd)

    def detected_scope_escapes(self) -> tuple[str, ...]:
        """Detect Git-visible writes relative to the exact journal baseline.

        Unlike assay's pre/post dirty-*set* subtraction, this compares bytes,
        modes, symlink targets, and existence for paths that were already dirty
        before invocation.  A model therefore cannot silently modify a user's
        pre-existing dirty file and have it mistaken for ambient state.
        """

        self._require_writer_epoch_quiescence(
            frontier="scope-escape detection"
        )
        cwd = self._bound_workspace_cwd()
        scope = tuple(self._manifest["scope"])
        recursive_scope = set(self._manifest.get("recursive_scope", ()))

        def _in_scope(relative: str) -> bool:
            return any(
                relative == root
                or (
                    root in recursive_scope
                    and relative.startswith(root.rstrip("/") + "/")
                )
                for root in scope
            )

        self.prepare_git_capture()
        changed_policy = (
            set(self._restore_new_attribute_changes)
            if self._restore_validation_in_progress
            else set(self._manifest.get("pre_capture_attribute_changes", ()))
        )
        attribute_admin_changed = (
            self._restore_new_attribute_admin_changed
            if self._restore_validation_in_progress
            else bool(self._manifest.get("pre_capture_attribute_admin_changed"))
        )
        if attribute_admin_changed:
            raise MutationJournalError(
                "slice changed Git config/info attributes; restored before status"
            )
        live_deferred_roots = (
            self._deferred_recursive_attribute_policy_roots(
                cwd,
                changed_policy,
            )
        )
        durable_deferred_roots = (
            self._validated_deferred_recursive_attribute_policy_roots()
        )
        deferred_policy = frozenset(
            path
            for path, recursive_root in live_deferred_roots.items()
            if durable_deferred_roots.get(path) == recursive_root
        )
        if self._selectively_restored_attribute_policy:
            deferred_policy = frozenset({
                *deferred_policy,
                *self._restored_attribute_policy_paths(
                    cwd,
                    changed_policy,
                    self._selectively_restored_attribute_policy,
                ),
            })
        in_scope_policy = sorted(
            path for path in changed_policy
            if _in_scope(path) and path not in deferred_policy
        )
        if in_scope_policy:
            raise MutationJournalError(
                "mutation of Git attribute policy is unsupported while exact "
                f"rollback is active: {in_scope_policy!r}"
            )
        candidates = set(self._manifest["baseline_dirty"])
        candidates.update(changed_policy)
        candidates.update(self._tracked_metadata_drift_paths(cwd))
        candidates.update(_git_status_paths(cwd))
        entries: dict[str, dict] = self._manifest["entries"]
        metadata_relatives = self._metadata_relative_roots(cwd)

        escapes: list[str] = []
        for rendered in sorted(candidates):
            relative = _normalize_relative(cwd, rendered)
            if any(
                relative == metadata or relative.startswith(metadata + "/")
                for metadata in metadata_relatives
            ):
                continue
            if _in_scope(relative):
                continue
            if relative in changed_policy:
                escapes.append(relative)
                continue
            expected = entries.get(relative)
            if expected is None or not _matches_snapshot(
                self, relative, expected,
            ):
                escapes.append(relative)
        return tuple(escapes)

    def record_implementation(self, impl: "Implementation") -> None:
        self._require_writer_epoch_quiescence(
            frontier="Implementation recording"
        )
        cwd = self._bound_workspace_cwd()
        metadata_relatives = self._metadata_relative_roots(cwd)
        escapes = {
            _normalize_relative(cwd, path)
            for path in getattr(impl, "scope_escapes", ()) or ()
        }
        escapes = {
            path for path in escapes
            if not any(
                path == metadata or path.startswith(metadata + "/")
                for metadata in metadata_relatives
            )
        }
        current = set(self._manifest.get("scope_escapes", ()))
        self._manifest["scope_escapes"] = sorted(current | escapes)
        self._manifest["state"] = "scoped"
        self._write()

    def record_scope_escapes(self, paths: Iterable[str]) -> None:
        """Durably include late runner/gate escapes in rollback authority."""

        self._require_writer_epoch_quiescence(
            frontier="scope-escape recording"
        )
        cwd = self._bound_workspace_cwd()
        normalized = {
            _normalize_relative(cwd, path)
            for path in paths
        }
        current = set(self._manifest.get("scope_escapes", ()))
        self._manifest["scope_escapes"] = sorted(current | normalized)
        self._manifest["state"] = "scoped"
        self._write()

    def _authorized_scope_changed(self) -> bool:
        """Whether the live authorized scope differs from this baseline.

        ``Implementation.files_modified`` is a cumulative HEAD-to-workspace
        view, so it can include an earlier slice's already-dirty in-scope
        files.  The journal's exact pre-invocation snapshots are the authority
        for deciding whether this invocation changed those bytes.  A current
        status path absent from ``entries`` covers files newly created below
        an existing directory scope.
        """

        self._require_writer_epoch_quiescence(
            frontier="authorized-scope inspection"
        )
        cwd = self._bound_workspace_cwd()
        scope = tuple(self._manifest["scope"])
        recursive_scope = set(self._manifest.get("recursive_scope", ()))

        def _in_scope(relative: str) -> bool:
            return any(
                relative == root
                or (
                    root in recursive_scope
                    and relative.startswith(root.rstrip("/") + "/")
                )
                for root in scope
            )

        entries: dict[str, dict] = self._manifest["entries"]
        if any(
            _in_scope(relative)
            and not _matches_snapshot(
                self, relative, expected,
            )
            for relative, expected in entries.items()
        ):
            return True
        for rendered in _git_status_paths(cwd):
            relative = _normalize_relative(cwd, rendered)
            if _in_scope(relative) and relative not in entries:
                return True
        return False

    def locally_changed_paths(
        self,
        paths: Iterable[str],
    ) -> tuple[str, ...]:
        """Return requested scope paths changed since this journal began.

        ``Implementation.files_modified`` is cumulative against ``HEAD`` and
        can therefore include dirt inherited from an earlier slice.  Gates
        that need proof of a mutation by *this* invocation must compare the
        live nodes with this transaction's exact pre-invocation snapshots
        instead.  Directory scopes include changed, created, or deleted
        descendants; ordinary file scopes compare the exact node.

        The method accepts only paths already authorized by this journal.  A
        caller cannot use it as an oracle over unrelated workspace content.
        """

        self._require_writer_epoch_quiescence(
            frontier="local-change inspection"
        )
        cwd = self._bound_workspace_cwd()
        scope = tuple(self._manifest["scope"])
        recursive_scope = set(self._manifest.get("recursive_scope", ()))
        entries: dict[str, dict] = self._manifest["entries"]

        def _authorized(relative: str) -> bool:
            return any(
                relative == root
                or (
                    root in recursive_scope
                    and relative.startswith(root.rstrip("/") + "/")
                )
                for root in scope
            )

        normalized = tuple(dict.fromkeys(
            _normalize_relative(cwd, rendered)
            for rendered in paths
        ))
        unauthorized = tuple(
            relative for relative in normalized if not _authorized(relative)
        )
        if unauthorized:
            raise MutationJournalError(
                "local-mutation query escapes journal scope: "
                f"{list(unauthorized)!r}"
            )

        status_paths = {
            _normalize_relative(cwd, rendered)
            for rendered in _git_status_paths(cwd)
        }
        changed: list[str] = []
        for relative in normalized:
            prefix = relative.rstrip("/") + "/"
            expected_nodes = {
                path: expected
                for path, expected in entries.items()
                if path == relative or path.startswith(prefix)
            }
            if any(
                not _matches_snapshot(
                    self,
                    path,
                    expected,
                )
                for path, expected in expected_nodes.items()
            ):
                changed.append(relative)
                continue
            if any(
                (path == relative or path.startswith(prefix))
                and path not in expected_nodes
                for path in status_paths
            ):
                changed.append(relative)
        return tuple(changed)

    def locally_changed_scope_paths(self) -> tuple[str, ...]:
        """Return authorized scope roots changed since this journal began.

        This is the whole-scope counterpart to ``locally_changed_paths`` for
        failure recovery. It uses the journal's already-normalized authority,
        which is important when a caller supplied a workspace-prefixed path
        that was resolved relative to the checkout during journal creation.
        """

        self._require_writer_epoch_quiescence(
            frontier="scope-change inspection"
        )
        return self.locally_changed_paths(tuple(self._manifest["scope"]))

    def validate_implementation(self, impl: "Implementation") -> "Implementation":
        """Fail closed on ref movement and merge byte-level scope escapes."""

        self._require_writer_epoch_quiescence(
            frontier="Implementation validation"
        )
        self.assert_head_unchanged()
        cwd = self._bound_workspace_cwd()
        metadata_relatives = self._metadata_relative_roots(cwd)
        reported = tuple(
            path for path in impl.scope_escapes
            if not any(
                path == metadata or path.startswith(metadata + "/")
                for metadata in metadata_relatives
            )
        )
        if reported != impl.scope_escapes:
            classification = impl.classification
            if classification == "hard_fail_scope_escape" and not reported:
                classification = (
                    "success"
                    if self._authorized_scope_changed()
                    else (
                        "hard_fail_empty_diff"
                        if impl.files_modified
                        else "soft_fail_no_changes"
                    )
                )
            impl = replace(
                impl,
                scope_escapes=reported,
                classification=classification,
            )
        detected = self.detected_scope_escapes()
        if detected:
            merged = tuple(dict.fromkeys((*impl.scope_escapes, *detected)))
            classification = impl.classification
            if classification in {
                "success",
                "soft_fail_no_changes",
                "hard_fail_empty_diff",
            }:
                classification = "hard_fail_scope_escape"
            impl = replace(
                impl,
                scope_escapes=merged,
                classification=classification,
            )
        # Keep integrity checks last: ``git status`` inside scope detection can
        # rewrite only index stat-cache bytes. Semantic comparison followed by
        # exact snapshot restoration removes that benign churn before attach.
        self.assert_head_unchanged()
        self.assert_repository_metadata_unchanged()
        self.assert_index_unchanged()
        self.record_implementation(impl)
        return impl

    def _lifecycle_settlement_operation(
        self,
        *,
        implementation_refs: Iterable[str] = (),
        allow_committed: bool = False,
    ) -> dict[str, object]:
        """Capture this transaction's exact current scoped postimage."""

        self._require_writer_epoch_quiescence(
            frontier="lifecycle settlement capture"
        )
        if not self.active and not (
            allow_committed and self.state == "committed"
        ):
            raise MutationJournalError(
                f"cannot settle inactive transaction {self.transaction_id}"
            )
        self.assert_head_unchanged()
        self.assert_repository_metadata_unchanged()
        self.assert_index_unchanged()
        escapes = self.detected_scope_escapes()
        if escapes:
            raise MutationJournalError(
                "lifecycle settlement mutation escaped its declared scope: "
                f"{list(escapes)!r}"
            )
        recorded_cwd = Path(self._manifest["cwd"])
        authority = _assert_workspace_mutation_authority(recorded_cwd)
        root_metadata = os.fstat(authority.root_descriptor)
        expected_root = self._manifest.get("authority_lock") or {}
        if (
            expected_root.get("root_device") is not None
            and root_metadata.st_dev != int(expected_root["root_device"])
        ) or (
            expected_root.get("root_inode") is not None
            and root_metadata.st_ino != int(expected_root["root_inode"])
        ):
            raise MutationJournalError(
                "lifecycle settlement root conflicts with journal authority"
            )
        scope = tuple(
            _settlement_relative_path(str(path))
            for path in self._manifest.get("scope", ())
        )
        recursive_scope = set(
            _settlement_relative_path(str(path))
            for path in self._manifest.get("recursive_scope", ())
        )

        def in_scope(relative: str) -> bool:
            return any(
                relative == root
                or (
                    root in recursive_scope
                    and relative.startswith(root.rstrip("/") + "/")
                )
                for root in scope
            )

        budget = _SettlementCaptureBudget()
        candidates: set[str] = set()

        def add_candidate(rendered: str) -> None:
            relative = _settlement_relative_path(rendered)
            if relative in candidates:
                return
            if not in_scope(relative):
                raise MutationJournalError(
                    "lifecycle settlement postimage escaped transaction scope"
                )
            budget.add_path(relative)
            candidates.add(relative)

        for path in scope:
            add_candidate(path)
        for path in self._manifest.get("entries", {}):
            relative = _settlement_relative_path(str(path))
            if in_scope(relative):
                add_candidate(relative)
        for path in _git_status_paths(recorded_cwd):
            relative = _settlement_relative_path(path)
            if in_scope(relative):
                add_candidate(relative)
        for root in sorted(recursive_scope):
            for path in _descriptor_recursive_postimage_paths(
                authority.root_descriptor,
                root,
            ):
                add_candidate(path)
        normalized = tuple(sorted(candidates))
        postimages = [
            {
                "path": path,
                "state": _current_postimage_state(
                    authority.root_descriptor,
                    path,
                    budget,
                ),
            }
            for path in normalized
        ]
        refs = tuple(dict.fromkeys(str(ref) for ref in implementation_refs))
        if any(not ref for ref in refs):
            raise MutationJournalError(
                "lifecycle settlement has an empty Implementation ref"
            )
        operation: dict[str, object] = {
            "role": "mutation",
            "transaction_id": self.transaction_id,
            "slice_id": self.slice_id,
            "scope": list(scope),
            "recursive_scope": sorted(recursive_scope),
            "postimages": postimages,
            "implementation_refs": list(refs),
            "root_identity": {
                "device": root_metadata.st_dev,
                "inode": root_metadata.st_ino,
            },
            "capture_totals": budget.as_record(),
        }
        self.assert_head_unchanged()
        self.assert_repository_metadata_unchanged()
        self.assert_index_unchanged()
        return operation

    def _lifecycle_guard_operation(self) -> dict[str, object]:
        """Bind a family guard whose workspace must remain at its baseline."""

        self._require_writer_epoch_quiescence(
            frontier="lifecycle guard capture"
        )
        if not self.active:
            raise MutationJournalError(
                f"cannot settle inactive guard transaction {self.transaction_id}"
            )
        self.assert_head_unchanged()
        self.assert_repository_metadata_unchanged()
        self.assert_index_unchanged()
        self.assert_exact_baseline()
        authority = _assert_workspace_mutation_authority(
            Path(self._manifest["cwd"])
        )
        root_metadata = os.fstat(authority.root_descriptor)
        operation: dict[str, object] = {
            "role": "guard",
            "transaction_id": self.transaction_id,
            "slice_id": self.slice_id,
            "scope": [
                _settlement_relative_path(str(path))
                for path in self._manifest.get("scope", ())
            ],
            "recursive_scope": sorted(
                _settlement_relative_path(str(path))
                for path in self._manifest.get("recursive_scope", ())
            ),
            "postimages": [],
            "implementation_refs": [],
            "root_identity": {
                "device": root_metadata.st_dev,
                "inode": root_metadata.st_ino,
            },
            "capture_totals": {
                "paths": 0,
                "path_bytes": 0,
                "hashed_bytes": 0,
                "xattr_bytes": 0,
            },
        }
        self.assert_head_unchanged()
        self.assert_repository_metadata_unchanged()
        self.assert_index_unchanged()
        return operation

    def prepare(self, impl: "Implementation", *, keep: bool) -> None:
        from assay.canonical import hash_record  # noqa: PLC0415

        self._require_writer_epoch_quiescence(
            frontier="Implementation preparation"
        )
        if keep and self._manifest.get("lineage") is None:
            raise MutationJournalError(
                "accepted mutation transaction has no Spec lineage"
            )
        self._assert_nested_journals_exact()
        self.record_implementation(impl)
        record_ref = str(hash_record(impl))
        expected_postimage: dict[str, object] | None = None
        if keep:
            with workspace_mutation_lock(Path(self._manifest["cwd"])):
                expected_postimage = self._lifecycle_settlement_operation(
                    implementation_refs=(record_ref,),
                )
            encoded_postimage = json.dumps(
                expected_postimage,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
            if len(encoded_postimage) > (
                _LIFECYCLE_SETTLEMENT_MAX_ARTIFACT_BYTES
            ):
                raise MutationJournalError(
                    "Implementation postimage exceeds its size ceiling"
                )
        self._manifest["expected_lifecycle"] = None
        self._manifest["expected_postimage"] = expected_postimage
        self._manifest["expected_implementation"] = {
            "record_ref": record_ref,
            "slice_id": impl.slice_id,
            "base_commit": impl.base_commit,
            "diff_ref": str(impl.diff_ref),
            "transcript_ref": str(impl.transcript_ref),
            "classification": impl.classification,
        }
        self._manifest["state"] = (
            "prepared_keep" if keep else "prepared_rollback"
        )
        self._write()

    def prepare_lifecycle_acceptance(
        self,
        *,
        kind: str,
        reason: str,
        run_id: str | None = None,
        settlement_ref: str | None = None,
        settlement_family: Iterable[str] = (),
        settlement_family_parents: Mapping[str, str | None] | None = None,
    ) -> None:
        """Durably declare the lifecycle record that will settle this edit."""

        self._require_writer_epoch_quiescence(
            frontier="lifecycle acceptance preparation"
        )
        self.prepare_lifecycle_acceptances(
            kind=kind,
            reasons=(reason,),
            run_id=run_id,
            settlement_ref=settlement_ref,
            settlement_family=settlement_family,
            settlement_family_parents=settlement_family_parents,
        )

    def prepare_lifecycle_acceptances(
        self,
        *,
        kind: str,
        reasons: Iterable[str],
        run_id: str | None = None,
        settlement_ref: str | None = None,
        settlement_family: Iterable[str] = (),
        settlement_family_parents: Mapping[str, str | None] | None = None,
    ) -> None:
        """Declare the finite accepted child outcomes that settle this edit."""

        self._require_writer_epoch_quiescence(
            frontier="lifecycle family preparation"
        )
        if self._manifest.get("lineage") is None:
            raise MutationJournalError(
                "accepted mutation transaction has no Spec lineage"
            )
        self._assert_nested_journals_exact()
        accepted_reasons = tuple(dict.fromkeys(reasons))
        accepted_family = tuple(sorted({
            str(transaction_id) for transaction_id in settlement_family
        }))
        accepted_parents = (
            {
                str(transaction_id): (
                    str(parent) if parent is not None else None
                )
                for transaction_id, parent in (
                    settlement_family_parents or {}
                ).items()
            }
            if settlement_ref is not None
            else {}
        )
        if settlement_ref is not None and (
            self.transaction_id not in accepted_family
            or set(accepted_parents) != set(accepted_family)
        ):
            raise MutationJournalError(
                "prepared lifecycle settlement family is incomplete"
            )
        if settlement_ref is None and (
            accepted_family or accepted_parents
        ):
            raise MutationJournalError(
                "generic lifecycle acceptance cannot carry settlement family"
            )
        if not accepted_reasons:
            raise MutationJournalError(
                "accepted mutation transaction requires lifecycle reasons"
            )
        # This transaction may previously have been prepared_rollback around a
        # failed seed Implementation. Once a child lifecycle becomes the only
        # acceptance proof, that attached failure must not satisfy recovery.
        self._manifest["expected_implementation"] = None
        self._manifest["expected_postimage"] = None
        self._manifest["expected_lifecycle"] = {
            "kind": kind,
            "reasons": list(accepted_reasons),
            "run_id": run_id,
            "settlement_ref": settlement_ref,
            "settlement_family": list(accepted_family),
            "settlement_family_parents": accepted_parents,
        }
        self._manifest["state"] = "prepared_keep"
        self._write()

    def commit(
        self,
        *,
        attached: bool = False,
        corpus: "Corpus | None" = None,
        _settlement_family_prevalidated: bool = False,
        _authority_held: bool = False,
        _settlement_family_locks_held: bool = False,
        _journal_binding_held: bool = False,
    ) -> None:
        """Disarm the journal after the mutation is accepted.

        ``attached=True`` is used only after the exact expected Implementation
        or lifecycle settlement is atomically visible from the Spec. Marker or
        owner cleanup failure raises with the durable journal retained; the
        caller must reconcile that attached authority before reporting
        success. Ephemeral/nested checkpoints have no attachment proof and
        still raise so their parent unwind restores the mutation.
        """

        self._require_writer_epoch_quiescence(frontier="journal commit")
        if self._discovery_binding is not None and not _journal_binding_held:
            original_dir = self.journal_dir
            with _bound_mutation_journal_directory(self) as (
                artifact_dir,
                journal_fd,
                parent_fd,
                entry_name,
            ):
                self.journal_dir = artifact_dir
                try:
                    self.commit(
                        attached=attached,
                        corpus=corpus,
                        _settlement_family_prevalidated=(
                            _settlement_family_prevalidated
                        ),
                        _authority_held=_authority_held,
                        _settlement_family_locks_held=(
                            _settlement_family_locks_held
                        ),
                        _journal_binding_held=True,
                    )
                finally:
                    self.journal_dir = original_dir
                if self.state == "committed":
                    try:
                        current_entry = os.stat(
                            entry_name,
                            dir_fd=parent_fd,
                            follow_symlinks=False,
                        )
                    except FileNotFoundError:
                        return
                    if (current_entry.st_dev, current_entry.st_ino) != (
                        os.fstat(journal_fd).st_dev,
                        os.fstat(journal_fd).st_ino,
                    ):
                        raise MutationJournalError(
                            "bound mutation journal changed before commit "
                            "cleanup"
                        )
                    _revalidate_discovery_directory_entry(
                        parent_fd,
                        entry_name,
                        journal_fd,
                        os.fstat(journal_fd),
                        label=(
                            "bound mutation journal before commit cleanup"
                        ),
                    )
                    _remove_bound_directory_tree(
                        parent_fd,
                        entry_name,
                        journal_fd,
                        os.fstat(journal_fd),
                    )
            return

        if attached and corpus is None:
            from assay.corpus.store import Corpus  # noqa: PLC0415

            corpus = Corpus(_originating_spec_dir(self.journal_dir))
        if attached and not _authority_held:
            initial_expected = self._manifest.get("expected_lifecycle") or {}
            initial_settlement_ref = initial_expected.get("settlement_ref")
            if initial_settlement_ref is not None:
                expected_family = set(
                    initial_expected.get("settlement_family", ())
                )
                with _LIVE_TRANSACTIONS_LOCK:
                    initial_family = {
                        transaction_id: _LIVE_JOURNAL_OBJECTS[transaction_id]
                        for transaction_id in expected_family
                        if transaction_id in _LIVE_JOURNAL_OBJECTS
                    }
                if set(initial_family) != expected_family:
                    raise MutationJournalError(
                        "attached lifecycle settlement family is not fully live"
                    )
                with _lifecycle_family_workspace_locks(
                    initial_family.values()
                ):
                    return self.commit(
                        attached=True,
                        corpus=corpus,
                        _settlement_family_prevalidated=(
                            _settlement_family_prevalidated
                        ),
                        _authority_held=True,
                        _settlement_family_locks_held=True,
                        _journal_binding_held=_journal_binding_held,
                    )
            with workspace_mutation_lock(Path(self._manifest["cwd"])):
                return self.commit(
                    attached=True,
                    corpus=corpus,
                    _settlement_family_prevalidated=(
                        _settlement_family_prevalidated
                    ),
                    _authority_held=True,
                    _settlement_family_locks_held=(
                        _settlement_family_locks_held
                    ),
                    _journal_binding_held=_journal_binding_held,
                )

        self._assert_no_failed_descendant()
        expected_lifecycle = self._manifest.get("expected_lifecycle") or {}
        expected_implementation = self._manifest.get(
            "expected_implementation"
        )
        settlement_ref = expected_lifecycle.get("settlement_ref")
        lifecycle_family_to_finalize: tuple[
            WorkspaceMutationJournal,
            ...,
        ] = ()
        if (
            attached
            and settlement_ref is not None
            and not _settlement_family_prevalidated
            and not _settlement_family_locks_held
        ):
            expected_family = set(
                expected_lifecycle.get("settlement_family", ())
            )
            with _LIVE_TRANSACTIONS_LOCK:
                lock_family = {
                    transaction_id: _LIVE_JOURNAL_OBJECTS[transaction_id]
                    for transaction_id in expected_family
                    if transaction_id in _LIVE_JOURNAL_OBJECTS
                }
            if set(lock_family) != expected_family:
                raise MutationJournalError(
                    "attached lifecycle settlement family is not fully live"
                )
            with _lifecycle_family_workspace_locks(lock_family.values()):
                return self.commit(
                    attached=True,
                    corpus=corpus,
                    _settlement_family_prevalidated=False,
                    _authority_held=True,
                    _settlement_family_locks_held=True,
                    _journal_binding_held=_journal_binding_held,
                )
        if attached and expected_lifecycle and settlement_ref is None:
            raise MutationJournalError(
                "attached lifecycle commit lacks an exact mutation postimage "
                "settlement"
            )
        if attached and settlement_ref is not None:
            if corpus is None:
                raise MutationJournalError(
                    "attached lifecycle settlement requires Corpus authority"
                )
            lifecycle_ref = _expected_lifecycle_ref(
                corpus,
                expected_lifecycle,
                self._manifest.get("lineage"),
                strict_ambiguity=True,
            )
            if lifecycle_ref is None:
                raise MutationJournalError(
                    "attached lifecycle settlement event is absent"
                )
            if not _settlement_family_prevalidated:
                expected_family = set(
                    expected_lifecycle.get("settlement_family", ())
                )
                with _LIVE_TRANSACTIONS_LOCK:
                    family_journals = {
                        transaction_id: _LIVE_JOURNAL_OBJECTS[transaction_id]
                        for transaction_id in expected_family
                        if transaction_id in _LIVE_JOURNAL_OBJECTS
                    }
                if set(family_journals) != expected_family:
                    raise MutationJournalError(
                        "attached lifecycle settlement family is not fully live"
                    )
                for family_journal in family_journals.values():
                    family_expected = (
                        family_journal._manifest.get("expected_lifecycle") or {}
                    )
                    if family_expected.get("settlement_ref") != settlement_ref:
                        raise MutationJournalError(
                            "attached lifecycle settlement family disagrees"
                        )
                    _assert_journal_lifecycle_settlement(
                        corpus,
                        family_journal,
                        lifecycle_ref,
                    )
                lifecycle_family_to_finalize = tuple(
                    family_journals[transaction_id]
                    for transaction_id in sorted(family_journals)
                )
            _assert_journal_lifecycle_settlement(
                corpus,
                self,
                lifecycle_ref,
            )
            if lifecycle_family_to_finalize:
                _commit_prevalidated_lifecycle_family(
                    lifecycle_family_to_finalize
                )
                return
        if attached and expected_implementation is not None:
            assert corpus is not None
            implementation_ref = _expected_implementation_ref(
                corpus,
                expected_implementation,
                self._manifest.get("lineage"),
                strict_ambiguity=True,
            )
            if implementation_ref is None:
                raise MutationJournalError(
                    "attached Implementation settlement is absent"
                )
            expected_postimage = self._manifest.get("expected_postimage")
            if not isinstance(expected_postimage, dict):
                raise MutationJournalError(
                    "attached Implementation lacks an exact postimage"
                )
            self.assert_head_unchanged()
            self.assert_repository_metadata_unchanged()
            self.assert_index_unchanged()
            observed_postimage = self._lifecycle_settlement_operation(
                implementation_refs=(implementation_ref,),
            )
            if observed_postimage != expected_postimage:
                raise MutationJournalError(
                    "attached Implementation postimage no longer matches"
                )
            self.assert_head_unchanged()
            self.assert_repository_metadata_unchanged()
            self.assert_index_unchanged()
        nested_journals = self._nested_journals_for_restore()
        for nested in nested_journals:
            nested.assert_exact_baseline()
        for nested in reversed(nested_journals):
            nested.commit(
                attached=attached,
                corpus=corpus,
                _settlement_family_prevalidated=(
                    _settlement_family_prevalidated
                    or settlement_ref is not None
                ),
                _authority_held=True,
                _settlement_family_locks_held=True,
            )

        previous = self._manifest["state"]
        self._manifest["state"] = "committed"
        try:
            self._write()
        except BaseException as exc:
            self._manifest["state"] = previous
            if attached:
                raise MutationJournalError(
                    "attached mutation journal commit marker remains "
                    "incomplete; durable journal retained for reconciliation"
                ) from exc
            raise
        _cleanup_terminal_mutation_journal(
            self,
            allow_missing_registry=False,
        )

    def settle_or_restore(
        self,
        corpus: "Corpus",
        *,
        full: bool | None = None,
    ) -> bool:
        """Preserve an attached prepared keep; otherwise restore exactly.

        This is the graceful-exception counterpart to startup recovery. A
        BaseException can land after the atomic Corpus commit but before the
        caller writes the journal's committed marker; blindly restoring then
        would leave a landed Spec pointing at workspace bytes that no longer
        exist.
        """
        return self.settle_or_restore_outcome(
            corpus,
            full=full,
        ).completed

    def settle_or_restore_outcome(
        self,
        corpus: "Corpus",
        *,
        full: bool | None = None,
    ) -> JournalSettlementOutcome:
        """Reconcile under one serialized workspace/Spec snapshot.

        Prepared keep's absent-versus-attached decision authorizes either
        destructive restoration or preservation. Own the canonical
        workspace-then-Spec lock order here so ordinary graceful-unwind callers
        cannot race a concurrent acceptance. Prepared rollback does not use
        Spec state as mutation authority, but still shares the workspace lock.
        """

        try:
            self._require_writer_epoch_quiescence(
                frontier="journal settlement"
            )
        except MutationJournalError:
            return JournalSettlementOutcome(False, "writer_epoch_blocked")
        if not self.active and not self.cleanup_pending:
            return JournalSettlementOutcome(True, "inactive")
        workspace = _lexical_workspace_path(self._manifest["cwd"])
        authority_context = (
            self._pre_root_restore_authority()
            if (
                self.active
                and _active_external_workspace_coordination(workspace) is None
            )
            else workspace_mutation_lock(workspace)
        )
        with authority_context:
            if self.state == "prepared_keep":
                with _readable_spec_authority(corpus):
                    return self._settle_or_restore_outcome_locked(
                        corpus,
                        full=full,
                    )
            return self._settle_or_restore_outcome_locked(
                corpus,
                full=full,
            )

    def _settle_or_restore_outcome_locked(
        self,
        corpus: "Corpus",
        *,
        full: bool | None = None,
    ) -> JournalSettlementOutcome:
        """Reconcile while the required workspace/Spec locks are held."""

        if not self.active:
            if not self.cleanup_pending:
                return JournalSettlementOutcome(True, "inactive")
            completed = self.retry_cleanup()
            return JournalSettlementOutcome(
                completed,
                "inactive" if completed else "cleanup_pending",
            )
        strict_ambiguity = self.state == "prepared_keep"
        if strict_ambiguity:
            from . import _build_verify  # noqa: PLC0415

            latest = corpus.latest_spec()
            if latest is None:
                raise MutationJournalError(
                    "prepared mutation settlement has no latest Spec authority"
                )
            valid_lineage, lineage_reason = (
                _build_verify._validate_spec_lineage(corpus, latest)
            )
            if not valid_lineage:
                raise MutationJournalError(
                    "latest Spec lineage is invalid before prepared mutation "
                    f"settlement: {lineage_reason}"
                )
        implementation_ref = _expected_implementation_ref(
            corpus,
            self._manifest.get("expected_implementation"),
            self._manifest.get("lineage"),
            strict_ambiguity=strict_ambiguity,
        )
        lifecycle_ref = _expected_lifecycle_ref(
            corpus,
            self._manifest.get("expected_lifecycle"),
            self._manifest.get("lineage"),
            strict_ambiguity=strict_ambiguity,
        )
        if self.state == "prepared_keep" and (
            implementation_ref is not None or lifecycle_ref is not None
        ):
            self.commit(attached=True, corpus=corpus)
            return JournalSettlementOutcome(
                True,
                "preserved",
                implementation_ref=implementation_ref,
                lifecycle_ref=lifecycle_ref,
            )
        restored = self.restore(full=full)
        return JournalSettlementOutcome(
            restored,
            "restored" if restored else "restore_failed",
        )

    def _restore_index(self, cwd: Path) -> None:
        index = self._bound_manifest_path(self._manifest["index_path"])
        # Refuse to write an index outside this checkout's current Git dir.
        current_index = _index_path(cwd)
        if (
            index.name != current_index.name
            or not self._bound_paths_same(index.parent, current_index.parent)
        ):
            raise MutationJournalError(
                f"Git index moved since snapshot: {index}"
            )
        exists = bool(self._manifest["index_exists"])
        payload = (
            self._read_snapshot_blob_record(
                self._manifest.get("index_blob"),
                label="Git index",
            )
            if exists
            else None
        )
        self._restore_bound_git_admin_file(
            str(self._manifest["index_path"]),
            exists=exists,
            record={
                "mode": self._manifest.get("index_mode", 0o644),
                "xattrs": self._manifest.get("index_xattrs", {}),
            },
            payload=payload,
            label="Git index",
        )

    def _restore_snapshot_root(
        self,
        cwd: Path,
        relative: str,
        *,
        expected_parent_bindings: Mapping[str, tuple[int, int] | None] | None = None,
    ) -> tuple[tuple[str, int | None, int | None], ...]:
        del cwd  # All source reads below use the held checkout descriptor.
        with _bound_workspace_restore_root(self) as root_fd:
            return self._restore_snapshot_root_bound(
                Path(_authority_descriptor_cwd(root_fd)),
                relative,
                expected_parent_bindings=expected_parent_bindings,
            )

    def _restore_snapshot_root_bound(
        self,
        cwd: Path,
        relative: str,
        *,
        expected_parent_bindings: Mapping[str, tuple[int, int] | None] | None = None,
    ) -> tuple[tuple[str, int | None, int | None], ...]:
        relative = _settlement_relative_path(relative)
        entries: dict[str, dict] = self._manifest["entries"]
        state = entries.get(relative)
        materialized: list[tuple[str, dict[str, object]]] = []
        restore_budget = _MutationJournalArtifactBudget()
        if state is None:
            raw_binding = self._manifest.get("raw_object_restore", {}).get(
                relative
            )
            if raw_binding is not None:
                if not isinstance(raw_binding, dict):
                    raise MutationJournalError(
                        f"raw workspace restore authority is malformed: {relative!r}"
                    )
                materialized.append((
                    relative,
                    _materialize_raw_object_restore_entry(
                        cwd,
                        relative,
                        raw_binding,
                        restore_budget,
                    ),
                ))
            else:
                # A clean tracked path has no physical snapshot. Authenticate
                # its exact blob before deleting the live entry, then install
                # that payload descriptor-relatively instead of asking Git to
                # traverse a replaceable parent pathname.
                tree_state = _materialize_git_tree_restore_entry(
                    cwd,
                    str(self._manifest["head"]),
                    relative,
                    restore_budget,
                )
                if tree_state is not None:
                    tracked_metadata = self._manifest.get(
                        "tracked_path_metadata", {}
                    ).get(relative, {})
                    if (
                        isinstance(tracked_metadata, dict)
                        and tracked_metadata.get("kind") == tree_state["kind"]
                    ):
                        tree_state["mode"] = tracked_metadata.get(
                            "mode", tree_state["mode"]
                        )
                        tree_state["xattrs"] = tracked_metadata.get("xattrs", {})
                    materialized.append((relative, tree_state))
        else:
            if not isinstance(state, dict):
                raise MutationJournalError(
                    f"workspace snapshot state is malformed: {relative!r}"
                )
            if state.get("kind") == "opaque_directory":
                raise MutationJournalError(
                    "cannot prove or restore opaque nested-repository state for "
                    f"{relative}; journal retained"
                )
            subtree = {
                path: item
                for path, item in entries.items()
                if isinstance(path, str)
                and (path == relative or path.startswith(relative + "/"))
            }
            if subtree.get(relative) is not state:
                raise MutationJournalError(
                    f"workspace snapshot root is inconsistent: {relative!r}"
                )
            for path, item in sorted(
                subtree.items(),
                key=lambda pair: (pair[0].count("/"), pair[0]),
            ):
                if _settlement_relative_path(path) != path or not isinstance(item, dict):
                    raise MutationJournalError(
                        f"workspace snapshot entry is malformed: {path!r}"
                    )
                kind = item.get("kind")
                if kind == "opaque_directory":
                    raise MutationJournalError(
                        "cannot prove or restore opaque nested-repository state "
                        f"for {path}; journal retained"
                    )
                if path != relative:
                    parent = PurePosixPath(path).parent.as_posix()
                    parent_state = subtree.get(parent)
                    if not isinstance(parent_state, dict) or parent_state.get(
                        "kind"
                    ) != "directory":
                        raise MutationJournalError(
                            f"workspace snapshot parent is not a directory: {path!r}"
                        )
                if kind == "missing":
                    if path != relative or len(subtree) != 1:
                        raise MutationJournalError(
                            f"workspace snapshot absence is inconsistent: {path!r}"
                        )
                    continue
                if kind not in {"file", "directory", "symlink"}:
                    raise MutationJournalError(
                        f"unknown snapshot entry kind {kind!r}"
                    )
                record: dict[str, object] = {
                    "kind": kind,
                    "mode": item.get("mode"),
                    "xattrs": item.get("xattrs", {}),
                }
                if kind == "file":
                    digest = item.get("sha256")
                    data = _read_bound_snapshot_blob(
                        self,
                        digest,
                        item.get("size"),
                        restore_budget,
                        label=path,
                    )
                    record["payload"] = data
                elif kind == "symlink":
                    target = item.get("target")
                    if not isinstance(target, str) or "\0" in target:
                        raise MutationJournalError(
                            f"workspace snapshot symlink is malformed: {path!r}"
                        )
                    record["target"] = target
                materialized.append((path, record))

        # Validate every mode/xattr before the first destructive operation so a
        # corrupt journal cannot turn a complete baseline into a partial one.
        for path, item in materialized:
            mode = item.get("mode")
            if (
                not isinstance(mode, int)
                or isinstance(mode, bool)
                or not 0 <= mode <= 0o7777
            ):
                raise MutationJournalError(
                    f"workspace snapshot metadata is malformed: {path!r}"
                )
            validated_xattrs = _validated_restore_xattrs(
                item.get("xattrs", {}),
                label=path,
            )
            if item.get("kind") == "symlink" and validated_xattrs:
                raise MutationJournalError(
                    "descriptor-bound symlink xattr restoration is unsupported; "
                    f"journal retained for {path!r}"
                )
            item["xattrs"] = validated_xattrs

        # Parent observations from baseline-absent roots are stability tokens,
        # not authority to replace a directory that existed at capture.  Parse
        # the complete capture-time directory identity map before the first
        # target removal so an arbitrary same-mode parent cannot be laundered
        # into the later directory-restoration phase.
        captured_directory_modes, _captured_directory_xattrs = (
            _validated_workspace_directory_baseline(
                self._manifest.get("directory_modes"),
                self._manifest.get("directory_xattrs", {}),
            )
        )
        captured_directory_identities = (
            self._effective_workspace_directory_identities(
                captured_directory_modes,
            )
        )

        with _bound_workspace_restore_root(self) as root_fd:
            parent_bindings: tuple[
                tuple[str, int | None, int | None], ...
            ] = ()
            effective_expected_parent_bindings = dict(
                expected_parent_bindings or {}
            )
            if materialized:
                ensured_parent_bindings = _ensure_bound_workspace_restore_parents(
                    self,
                    root_fd,
                    relative,
                    expected_parent_bindings=expected_parent_bindings,
                )
                parent_bindings = ensured_parent_bindings
                for parent_path, device, inode in ensured_parent_bindings:
                    previously_bound = (expected_parent_bindings or {}).get(
                        parent_path
                    )
                    if previously_bound is not None and previously_bound != (
                        device,
                        inode,
                    ):
                        raise MutationJournalError(
                            "workspace restore parent changed between roots: "
                            f"{parent_path!r}"
                        )
                    effective_expected_parent_bindings[parent_path] = (
                        device,
                        inode,
                    )
                    # ``_ensure_bound_workspace_restore_parents`` admits only
                    # the captured inode, a previously authenticated inode, or
                    # a directory it privately created after proving absence.
                    # Preserve that provenance separately from passive parent
                    # observations used only for cross-root stability.
                    self._restored_workspace_entry_authority[parent_path] = (
                        device,
                        inode,
                    )
            root_metadata = os.fstat(root_fd)
            expected_root_parent_chain = (
                (root_metadata.st_dev, root_metadata.st_ino),
                *(
                    (device, inode)
                    for _path, device, inode in parent_bindings
                    if device is not None and inode is not None
                ),
            )
            with _open_settlement_parent_if_present(root_fd, relative) as binding:
                parent_fd, name, parent_chain, missing_index = binding
                _assert_expected_workspace_restore_parent_bindings(
                    relative,
                    parent_chain,
                    missing_index,
                    effective_expected_parent_bindings,
                )
                if not materialized:
                    parent_bindings = (
                        _observed_workspace_restore_parent_bindings(
                            relative,
                            parent_chain,
                        )
                    )
                    for (
                        observed_parent_path,
                        observed_device,
                        observed_inode,
                    ) in parent_bindings:
                        if observed_device is None or observed_parent_path in (
                            expected_parent_bindings or {}
                        ):
                            continue
                        captured_identity = captured_directory_identities.get(
                            observed_parent_path
                        )
                        if captured_identity is not None and captured_identity != (
                            observed_device,
                            observed_inode,
                        ):
                            raise MutationJournalError(
                                "workspace restore parent differs from its "
                                f"captured identity: {observed_parent_path!r}"
                            )
                if missing_index is not None:
                    if materialized:
                        raise MutationJournalError(
                            f"workspace restore parent is absent: {relative!r}"
                        )
                    # Absence behind a missing parent is accepted only after the
                    # identical held-root walk remains absent a second time.
                    with _open_settlement_parent_if_present(
                        root_fd,
                        relative,
                    ) as retry:
                        (
                            _retry_fd,
                            _retry_name,
                            retry_chain,
                            retry_missing_index,
                        ) = retry
                        if (
                            retry_chain != parent_chain
                            or retry_missing_index != missing_index
                        ):
                            raise MutationJournalError(
                                "workspace restore parent changed during "
                                f"absence proof: {relative!r}"
                            )
                    self._restored_workspace_entry_authority[relative] = None
                    return parent_bindings
                if materialized and parent_chain != expected_root_parent_chain:
                    raise MutationJournalError(
                        "workspace restore parent conflicts with captured "
                        f"authority before removal: {relative!r}"
                    )
                _remove_bound_workspace_entry(
                    root_fd,
                    relative,
                    parent_fd,
                    name,
                    parent_chain,
                )
                if not materialized:
                    self._restored_workspace_entry_authority[relative] = None

            installed_directories: dict[str, tuple[int, int]] = {}
            for path, item in materialized:
                expected_parent_chain = list(expected_root_parent_chain)
                for directory_path, identity in sorted(
                    installed_directories.items(),
                    key=lambda pair: (pair[0].count("/"), pair[0]),
                ):
                    if path.startswith(directory_path.rstrip("/") + "/"):
                        expected_parent_chain.append(identity)
                installed_identity = _install_bound_workspace_entry(
                    root_fd,
                    path,
                    expected_parent_chain=tuple(expected_parent_chain),
                    kind=str(item["kind"]),
                    mode=cast(int, item["mode"]),
                    xattrs=cast(Mapping[str, str], item.get("xattrs", {})),
                    payload=cast(bytes | None, item.get("payload")),
                    target=cast(str | None, item.get("target")),
                )
                self._restored_workspace_entry_authority[path] = (
                    installed_identity
                )
                if item["kind"] == "directory":
                    installed_directories[path] = installed_identity
            return parent_bindings

    def _restore_captured_parent_metadata(
        self,
        bindings: Mapping[str, tuple[int, int] | None],
    ) -> None:
        """Restore shared parent metadata once all dependent roots are done."""

        if not bindings:
            return
        expected_modes = self._manifest.get("directory_modes")
        if not isinstance(expected_modes, dict):
            raise MutationJournalError(
                "workspace directory baseline is malformed"
            )
        ordered = tuple(
            (path, *identity)
            for path, identity in sorted(
                bindings.items(),
                key=lambda pair: (pair[0].count("/"), pair[0]),
            )
            if identity is not None and path in expected_modes
        )
        if not ordered:
            return
        with _bound_workspace_restore_root(self) as root_fd:
            _restore_bound_workspace_parent_metadata(
                self,
                root_fd,
                ordered,
            )

    def _remove_workspace_relative_bound(self, relative: str) -> None:
        """Remove one workspace marker without following intermediate aliases."""

        relative = _settlement_relative_path(
            relative,
            allow_terminal_vcs_metadata=True,
        )
        with _bound_workspace_restore_root(self) as root_fd:
            with _open_settlement_parent_if_present(
                root_fd,
                relative,
                allow_terminal_vcs_metadata=True,
            ) as binding:
                parent_fd, name, parent_chain, missing_index = binding
                if missing_index is not None:
                    with _open_settlement_parent_if_present(
                        root_fd,
                        relative,
                        allow_terminal_vcs_metadata=True,
                    ) as retry:
                        (
                            _retry_fd,
                            _retry_name,
                            retry_chain,
                            retry_missing_index,
                        ) = retry
                        if (
                            retry_chain != parent_chain
                            or retry_missing_index != missing_index
                        ):
                            raise MutationJournalError(
                                "workspace removal parent changed during "
                                f"absence proof: {relative!r}"
                            )
                    with _open_settlement_parent_if_present(
                        root_fd,
                        relative,
                        allow_terminal_vcs_metadata=True,
                    ) as final_probe:
                        (
                            _final_fd,
                            _final_name,
                            final_chain,
                            final_missing_index,
                        ) = final_probe
                        if (
                            final_chain != parent_chain
                            or final_missing_index != missing_index
                        ):
                            raise MutationJournalError(
                                "workspace removal parent changed after "
                                f"absence proof: {relative!r}"
                            )
                    return
                _remove_bound_workspace_entry(
                    root_fd,
                    relative,
                    parent_fd,
                    name,
                    parent_chain,
                    allow_terminal_vcs_metadata=True,
                )

    def admit_restored_path_child(
        self, child: "WorkspaceMutationJournal",
    ) -> None:
        """Transfer restored-path observations into one fresh child baseline.

        Selective restore proves exact post-restore metadata until a subsequent
        authorized invocation begins. Its observations are not a permanent ban
        on the child editing those same paths. Reprove them before retiring
        only the intersection of child and ancestor write scopes; all durable
        preimages, replacement-inode authority, and ordinary metadata checks
        remain in force. This does not arm or authorize a provider generation.
        """

        logical_cwd = Path(self._manifest["cwd"])
        if not self._has_held_git_admin_authority():
            with workspace_mutation_lock(logical_cwd):
                return self.admit_restored_path_child(child)
        family = validated_live_parent_writer_epoch_family(
            self.transaction_id, cwd=logical_cwd,
        )
        by_id = {member.transaction_id: member for member in family}
        if (
            by_id.get(child.transaction_id) is not child
            or child.parent_transaction_id != self.transaction_id
        ):
            raise MutationJournalError(
                "restored-path continuation requires an exact live child"
            )
        ancestors: list[WorkspaceMutationJournal] = []
        ancestor: WorkspaceMutationJournal | None = self
        while ancestor is not None:
            validate_live_parent_transaction(
                ancestor.transaction_id, cwd=Path(child._manifest["cwd"]),
            )
            ancestors.append(ancestor)
            parent_id = ancestor.parent_transaction_id
            ancestor = by_id.get(parent_id) if parent_id is not None else None
        if not any(
            ancestor._restored_tracked_metadata_observations
            for ancestor in ancestors
        ):
            return

        # Adding a pristine child produces a mixed old-quiesced/new-never-armed
        # family until the ordinary root-first writer arm. Authenticate the
        # old generation through its root certificate and require every added
        # member to be pristine, rather than treating "partial" as quiescence.
        root = ancestors[-1]
        root._require_writer_epoch_quiescence(
            frontier="restored-path child admission"
        )
        root_epoch = root.read_writer_epoch_record()
        prior_members = dict(root._writer_epoch_family_pairs(
            _writer_epoch_module._parse_epoch_record(root_epoch)
        ))
        for member in family:
            raw = member.read_writer_epoch_record()
            expected = (
                root_epoch if member.transaction_id in prior_members
                else initial_writer_epoch_record()
            )
            if raw != expected:
                raise MutationJournalError(
                    "restored-path child admission has unsettled writer authority"
                )
            failed = member._manifest.get("failed_family_members")
            if not isinstance(failed, list) or failed:
                raise MutationJournalError(
                    "restored-path child admission has unresolved failed authority"
                )
        if (
            child.read_writer_epoch_record() != initial_writer_epoch_record()
            or child.state != "invoking"
            or child._manifest.get("expected_implementation") is not None
            or child._manifest.get("expected_lifecycle") is not None
        ):
            raise MutationJournalError(
                "restored-path continuation requires a pristine child checkpoint"
            )

        projections: dict[str, tuple[tuple[str, ...], frozenset[str]]] = {}
        for member in (child, *ancestors):
            raw_scope = member._manifest.get("scope")
            raw_recursive = member._manifest.get("recursive_scope")
            if (
                not isinstance(raw_scope, list)
                or not isinstance(raw_recursive, list)
                or any(
                    not isinstance(path, str)
                    for path in (*raw_scope, *raw_recursive)
                )
            ):
                raise MutationJournalError(
                    "restored-path scope authority is malformed"
                )
            scope = tuple(_settlement_relative_path(path) for path in raw_scope)
            recursive = frozenset(
                _settlement_relative_path(path) for path in raw_recursive
            )
            if len(set(scope)) != len(scope) or not recursive.issubset(scope):
                raise MutationJournalError(
                    "restored-path scope authority is ambiguous"
                )
            projections[member.transaction_id] = scope, recursive

        def authorized(journal: WorkspaceMutationJournal, relative: str) -> bool:
            scope, recursive = projections[journal.transaction_id]
            return any(
                relative == path
                or (path in recursive and relative.startswith(path + "/"))
                for path in scope
            )

        admitted: list[tuple[WorkspaceMutationJournal, str]] = []
        child_baseline = child._manifest.get("tracked_path_metadata", {})
        if not isinstance(child_baseline, Mapping):
            raise MutationJournalError("restored-path child baseline is malformed")
        for ancestor in ancestors:
            ancestor._assert_no_failed_descendant()
            ancestor.assert_head_unchanged()
            ancestor.assert_repository_metadata_unchanged()
            ancestor.assert_index_unchanged()
            for relative, observation in (
                ancestor._restored_tracked_metadata_observations.items()
            ):
                if not (
                    authorized(child, relative)
                    and authorized(ancestor, relative)
                ):
                    continue
                if (
                    child_baseline.get(relative) != observation
                    or _tracked_path_metadata_for_path(
                        child._bound_workspace_cwd(), relative,
                    ) != observation
                ):
                    raise MutationJournalError(
                        "restored-path child baseline differs from its "
                        f"authenticated parent observation: {relative!r}"
                    )
                admitted.append((ancestor, relative))
        # Publish no partial handoff if any ancestor, unrelated restored path,
        # or fresh child baseline failed its proof above.
        for ancestor, relative in admitted:
            del ancestor._restored_tracked_metadata_observations[relative]

    def restore_paths_from_snapshot(self, paths: Iterable[str]) -> None:
        """Restore selected role escapes to this journal's exact baseline.

        This keeps authorized in-scope edits live while recovering an
        out-of-scope write. Unlike a checkout-from-HEAD cleanup, it preserves
        bytes, modes, symlink targets, and existence for paths that were dirty
        before the role began (including a seeded production diff).
        """

        if not self.active:
            raise MutationJournalError(
                f"cannot restore paths from inactive slice {self.slice_id}"
            )
        self._require_writer_epoch_quiescence(
            frontier="selective snapshot restore"
        )
        cwd = self._bound_workspace_cwd()
        normalized = {
            _normalize_relative(cwd, path)
            for path in paths
        }
        metadata_relatives = self._metadata_relative_roots(cwd)
        normalized = {
            path for path in normalized
            if not any(
                path == metadata or path.startswith(metadata + "/")
                for metadata in metadata_relatives
            )
        }
        parent_bindings: dict[str, tuple[int, int] | None] = {}
        for relative in _dedupe_roots(normalized):
            _merge_workspace_restore_parent_bindings(
                parent_bindings,
                self._restore_snapshot_root(
                    cwd,
                    relative,
                    expected_parent_bindings=parent_bindings,
                ),
            )
        directory_authority = self._restore_directory_modes(
            cwd,
            observed_parent_bindings=parent_bindings,
        )
        directory_authority = (
            self._reprove_restored_workspace_directory_authority(
                cwd,
                directory_authority,
            )
        )
        if self._record_restored_workspace_directory_authority(
            directory_authority,
        ):
            # A recursive snapshot restore publishes private replacement
            # inodes.  Persist their exact authority before any later step can
            # fail or the process can die, so retry never has to trust a
            # path-only recreation.
            self._write()
        entry_authority, verified_postimages = self._restore_tracked_path_metadata(
            cwd,
            directory_authority,
        )
        if verified_postimages:
            raise MutationJournalError(
                "unexpected active parent proof during root restoration"
            )
        self._reprove_restored_workspace_entry_authority(
            directory_authority,
        )
        self._reprove_restored_tracked_path_authority(
            cwd,
            directory_authority,
            entry_authority,
        )
        if self._record_restored_tracked_entry_authority(entry_authority):
            # Publish exact replacement tracked-entry authority before index
            # or repository repair can fail, so a new process can safely
            # resume without admitting a path-only rebind.
            self._write()
        restored_attribute_policy = (
            self._restored_attribute_policy_paths(
                cwd,
                self._manifest.get("pre_capture_attribute_changes", ()),
                normalized,
            )
        )
        if restored_attribute_policy:
            # Keep the durable historical latch until every repository/index
            # proof below succeeds.  The process-local grant is bound to the
            # exact restored bytes and is rechecked by scope detection.
            self._selectively_restored_attribute_policy.update(
                restored_attribute_policy
            )
        try:
            self._restore_index(cwd)
            self.assert_head_unchanged()
            self.assert_repository_metadata_unchanged()
            self.assert_index_unchanged()
            directory_authority = (
                self._reprove_restored_workspace_directory_authority(
                    cwd,
                    directory_authority,
                )
            )
            self._reprove_restored_workspace_entry_authority(
                directory_authority,
            )
            self._reprove_restored_tracked_path_authority(
                cwd,
                directory_authority,
                entry_authority,
            )
        finally:
            self._selectively_restored_attribute_policy.difference_update(
                restored_attribute_policy
            )
        if restored_attribute_policy:
            pending_policy = set(
                self._manifest.get("pre_capture_attribute_changes", ())
            )
            proofs = (
                self._validated_deferred_recursive_attribute_policy_roots()
            )
            pending_policy.difference_update(restored_attribute_policy)
            for path in restored_attribute_policy:
                proofs.pop(path, None)
            previous_pending = self._manifest.get(
                "pre_capture_attribute_changes",
                [],
            )
            previous_proofs = self._manifest.get(
                _DEFERRED_RECURSIVE_ATTRIBUTE_POLICY_KEY,
                {},
            )
            self._manifest["pre_capture_attribute_changes"] = sorted(
                pending_policy
            )
            self._manifest[
                _DEFERRED_RECURSIVE_ATTRIBUTE_POLICY_KEY
            ] = proofs
            try:
                self._write()
            except BaseException:
                self._manifest["pre_capture_attribute_changes"] = (
                    previous_pending
                )
                self._manifest[
                    _DEFERRED_RECURSIVE_ATTRIBUTE_POLICY_KEY
                ] = previous_proofs
                raise
            # Recheck after the durable proof is consumed and without the
            # temporary grant.  A late policy write is therefore relatched as
            # a direct mutation and cannot be hidden by the stale snapshot.
            self.assert_repository_metadata_unchanged()
            self.assert_index_unchanged()
            directory_authority = (
                self._reprove_restored_workspace_directory_authority(
                    cwd,
                    directory_authority,
                )
            )
            self._reprove_restored_workspace_entry_authority(
                directory_authority,
            )
            self._reprove_restored_tracked_path_authority(
                cwd,
                directory_authority,
                entry_authority,
            )

    def _assert_workspace_baseline(
        self,
        cwd: Path,
        *,
        roots: set[str],
        full: bool,
    ) -> None:
        metadata_relatives = self._metadata_relative_roots(cwd)
        if full:
            external_filter_paths = set(
                self._manifest.get("external_filter_paths", ())
            )
            unbound_external_filter_paths = (
                external_filter_paths
                - set(self._manifest.get("entries", {}))
            )
            if unbound_external_filter_paths:
                raise MutationJournalError(
                    "external filter paths lack physical snapshot entries: "
                    f"{sorted(unbound_external_filter_paths)!r}"
                )
            current_status = {
                path
                for path in _git_status_paths(cwd)
                if not any(
                    path == metadata or path.startswith(metadata + "/")
                    for metadata in metadata_relatives
                )
                and path not in external_filter_paths
            }
            expected_status = (
                set(self._manifest["baseline_dirty"])
                - external_filter_paths
            )
            if current_status != expected_status:
                raise MutationJournalError(
                    "workspace status differs from transaction baseline after "
                    f"restore: expected={sorted(expected_status)!r}, "
                    f"actual={sorted(current_status)!r}"
                )
        entries = {
            relative: expected
            for relative, expected in self._manifest["entries"].items()
            if full or any(
                relative == root or relative.startswith(root + "/")
                for root in roots
            )
        }
        for relative, expected in entries.items():
            if expected["kind"] == "opaque_directory" or not _matches_snapshot(
                self,
                relative,
                expected,
            ):
                raise MutationJournalError(
                    f"workspace path differs from snapshot after restore: {relative}"
                )
        raw_bindings = {
            relative: binding
            for relative, binding in self._manifest.get(
                "raw_object_restore", {}
            ).items()
            if full or any(
                relative == root or relative.startswith(root + "/")
                for root in roots
            )
        }
        for relative, binding in raw_bindings.items():
            if not _matches_raw_object_binding(self, relative, binding):
                raise MutationJournalError(
                    "workspace path differs from raw Git-object baseline "
                    f"after restore: {relative}"
                )

    def _restore_nested_gitlink_guard(
        self,
        *,
        _defer_terminal_cleanup: bool = False,
    ) -> bool:
        """Restore nested Git authority without checking out tracked bytes."""

        self._restored_workspace_entry_authority = {}
        self._restored_tracked_metadata_observations = {}
        cwd = self._bound_workspace_cwd()
        try:
            self._prepare_workspace_root_access()
            self._assert_authority_lock_unchanged()
            self._assert_bound_git_authority()
            fsck_reasons = self._initial_fsck_reasons(cwd)
            self._prepare_restore_access(writable=False)
            self._assert_authority_lock_unchanged()
            self._assert_bound_git_authority()
            nested_ids = self._nested_transaction_ids()
            self._assert_no_failed_descendant(allow=nested_ids)
            # A tracked-file metadata change may have crossed a transforming
            # checkout boundary. Preserve it and the journal for inspection;
            # only baseline-absent nonignored paths are safe to remove.
            self._preflight_nested_restore()
            self._prepare_restore_access(writable=True)
            nested_journals = self._nested_journals_for_restore()
            with ExitStack() as nested_authorities:
                for nested in nested_journals:
                    nested_authorities.enter_context(
                        nested._nested_restore_authority()
                    )
                for nested in reversed(nested_journals):
                    restored = nested.restore(_defer_terminal_cleanup=True)
                    if not restored:
                        raise MutationJournalError(
                            "nested child rollback failed: "
                            f"{nested.slice_id}"
                        )
            self._assert_no_failed_descendant()

            self._restore_registry_marker()
            self._restore_registry_topology()
            self._restore_git_entry(cwd)
            self._restore_object_inventory(cwd, cleanup_additions=False)
            self._restore_refs_tree(cwd)
            self._restore_log_refs_tree(cwd)
            self._restore_control_files()
            self._remove_added_registered_worktrees(cwd)
            self._restore_absent_worktree_admin_controls()
            self._restore_worktree_namespace(cwd)
            self._restore_auxiliary_git_trees(cwd)
            self._restore_refs(cwd)
            self._restore_index(cwd)

            if not self._manifest.get("external_worktree_guard"):
                for encoded in _git(
                    cwd,
                    "ls-files",
                    "-z",
                    "--others",
                    "--exclude-standard",
                ).split(b"\0"):
                    if encoded:
                        self._remove_workspace_relative_bound(
                            _normalize_relative(cwd, os.fsdecode(encoded))
                        )

            # Re-resolve ignore state only after baseline config/index/admin
            # controls are back. Newly-created ignored build products remain
            # outside authority; relevant nested VCS markers are removed.
            ignored_roots = self._effective_ignored_directory_roots(
                cwd,
                protected_paths=self._manifest.get("directory_modes", {}),
            )
            nested_markers = _relevant_nested_vcs_markers(
                cwd,
                excluded_roots=(
                    *self._manifest.get("metadata_relatives", ()),
                    *self._manifest.get("initialized_gitlinks", ()),
                ),
                ignored_roots=ignored_roots,
            )
            for relative in nested_markers:
                self._remove_workspace_relative_bound(relative)
            self._restore_cached_module_controls()
            self._restore_module_namespace(cwd)
            self._remove_added_module_admin(cwd)
            workspace_directory_authority = self._restore_directory_modes(cwd)
            (
                workspace_entry_authority,
                verified_postimages,
            ) = self._restore_tracked_path_metadata(
                cwd,
                workspace_directory_authority,
                allow_exact_baseline_rebind=True,
            )
            if verified_postimages:
                raise MutationJournalError(
                    "unexpected active parent proof during gitlink restoration"
                )

            # update-ref may append logs; restore the exact physical control
            # image once more before dropping transaction-created objects.
            self._restore_refs_tree(cwd)
            self._restore_log_refs_tree(cwd)
            self._restore_control_files()
            self._remove_added_registered_worktrees(cwd)
            self._restore_absent_worktree_admin_controls()
            self._restore_worktree_namespace(cwd)
            self._restore_auxiliary_git_trees(cwd)
            self._restore_object_inventory(cwd)
            self._restore_git_admin_topology()
            self.assert_head_unchanged()
            self.assert_repository_metadata_unchanged()
            self.assert_index_unchanged()
            self._assert_nested_worktree_unchanged()
            if _requires_full_fsck(fsck_reasons):
                logger.info(
                    "mutation journal: full fsck slice=%s cwd=%s reasons=%s",
                    self.slice_id,
                    cwd,
                    sorted(fsck_reasons),
                )
                _git_fsck(cwd, "--full", "--no-dangling", "HEAD")

            if _active_workspace_mutation_authority(
                Path(self._manifest["cwd"])
            ) is not None:
                _assert_workspace_mutation_authority(
                    Path(self._manifest["cwd"])
                )
            workspace_directory_authority = (
                self._reprove_restored_workspace_directory_authority(
                    cwd,
                    workspace_directory_authority,
                )
            )
            self._reprove_restored_workspace_entry_authority(
                workspace_directory_authority,
            )
            self._reprove_restored_tracked_path_authority(
                cwd,
                workspace_directory_authority,
                workspace_entry_authority,
            )
            previous = self._manifest["state"]
            self._manifest["state"] = "rolled_back"
            try:
                self._write()
            except BaseException:
                self._manifest["state"] = previous
                raise
            if not _defer_terminal_cleanup:
                terminal_descendants = self._nested_journals_children_first()
                for nested in terminal_descendants:
                    _cleanup_terminal_mutation_journal(
                        nested,
                        allow_missing_registry=False,
                    )
                self._acknowledge_resolved_descendants(
                    nested.transaction_id
                    for nested in terminal_descendants
                )
                _cleanup_terminal_mutation_journal(
                    self,
                    allow_missing_registry=False,
                )
            return True
        except BaseException:
            if self.active:
                self._record_restore_failure()
            logger.exception(
                "nested mutation journal %s: rollback failed; journal retained",
                self.journal_dir,
            )
            return False

    def restore(
        self,
        *,
        full: bool | None = None,
        active_parent_postimage_handoff: (_ActiveParentPostimageHandoff | None) = None,
        _defer_terminal_cleanup: bool = False,
    ) -> bool:
        """Restore through the descriptor-bound journal discovered at startup.

        ``active_parent_postimage_handoff`` is a one-shot in-process proof
        issued after a higher-level gate accepts production bytes that
        replaced their inode while this narrower child journal was active.
        It never relaxes the default restore.
        """

        if not self.active and active_parent_postimage_handoff is not None:
            logger.error(
                "mutation journal %s: inactive journal cannot consume a "
                "parent postimage handoff",
                self.journal_dir,
            )
            return False
        logical_cwd = Path(self._manifest["cwd"])
        if (
            self.active
            and _active_external_workspace_coordination(logical_cwd) is None
        ):
            try:
                with self._pre_root_restore_authority():
                    if active_parent_postimage_handoff is None:
                        return self.restore(
                            full=full,
                            _defer_terminal_cleanup=_defer_terminal_cleanup,
                        )
                    return self.restore(
                        full=full,
                        active_parent_postimage_handoff=(
                            active_parent_postimage_handoff
                        ),
                        _defer_terminal_cleanup=_defer_terminal_cleanup,
                    )
            except MutationJournalError:
                logger.exception(
                    "mutation journal %s: pre-root recovery admission failed",
                    self.journal_dir,
                )
                return False
        if not self._has_held_git_admin_authority():
            with workspace_mutation_lock(Path(self._manifest["cwd"])):
                if active_parent_postimage_handoff is None:
                    return self.restore(
                        full=full,
                        _defer_terminal_cleanup=_defer_terminal_cleanup,
                    )
                return self.restore(
                    full=full,
                    active_parent_postimage_handoff=(active_parent_postimage_handoff),
                    _defer_terminal_cleanup=_defer_terminal_cleanup,
                )

        if self._discovery_binding is None:
            return self._restore_bound(
                full=full,
                active_parent_postimage_handoff=(active_parent_postimage_handoff),
                _defer_terminal_cleanup=_defer_terminal_cleanup,
            )
        original_dir = self.journal_dir
        with _bound_mutation_journal_directory(self) as (
            artifact_dir,
            journal_fd,
            parent_fd,
            entry_name,
        ):
            self.journal_dir = artifact_dir
            try:
                restored = self._restore_bound(
                    full=full,
                    active_parent_postimage_handoff=(active_parent_postimage_handoff),
                    _defer_terminal_cleanup=True,
                )
                if not restored:
                    return False
                if _defer_terminal_cleanup:
                    return True
                # Keep the startup-discovered parent descriptor bound while
                # enumerating and deleting descendants.  Resetting to the
                # lexical Corpus path here would allow a path replacement to
                # substitute fresh, unbound child objects between restore and
                # terminal cleanup.
                terminal_descendants = self._nested_journals_children_first()
                for nested in terminal_descendants:
                    _cleanup_terminal_mutation_journal(
                        nested,
                        allow_missing_registry=False,
                    )
                self._acknowledge_resolved_descendants(
                    nested.transaction_id
                    for nested in terminal_descendants
                )
                self._require_writer_epoch_quiescence(
                    frontier="bound terminal rollback cleanup"
                )
                self._persist_writer_epoch_terminal_proof()
                component = self._discovery_binding.components[-1]
                _revalidate_discovery_directory_entry(
                    parent_fd,
                    entry_name,
                    journal_fd,
                    os.fstat(journal_fd),
                    label="bound mutation journal before terminal cleanup",
                )
                if (component.device, component.inode) != (
                    os.fstat(journal_fd).st_dev,
                    os.fstat(journal_fd).st_ino,
                ):
                    raise MutationJournalError(
                        "bound mutation journal changed before terminal cleanup"
                    )
                completed_receipt = _remove_terminal_journal_with_receipt(
                    self,
                    parent_fd=parent_fd,
                    parent_path=original_dir.parent,
                    entry_name=entry_name,
                    journal_fd=journal_fd,
                    journal_metadata=os.fstat(journal_fd),
                    allow_missing_registry=False,
                )
                _remove_completed_terminal_cleanup_receipt(
                    parent_fd,
                    completed_receipt,
                )
                _unregister_terminal_live(self.transaction_id)
                return not self.cleanup_pending
            finally:
                self.journal_dir = original_dir

    def _restore_bound(
        self,
        *,
        full: bool | None = None,
        active_parent_postimage_handoff: (_ActiveParentPostimageHandoff | None) = None,
        _defer_terminal_cleanup: bool = False,
    ) -> bool:
        """Restore this transaction and retain the journal on any failure."""

        if not self.active:
            return active_parent_postimage_handoff is None
        if active_parent_postimage_handoff is not None and full is not False:
            self._record_restore_failure()
            logger.error(
                "mutation journal %s: parent postimage handoff requires an "
                "explicit scoped restore",
                self.journal_dir,
            )
            return False
        try:
            self._require_writer_epoch_quiescence(frontier="journal restore")
        except MutationJournalError:
            self._record_restore_failure()
            logger.exception(
                "mutation journal %s: writer epoch blocked rollback",
                self.journal_dir,
            )
            return False
        if self._manifest.get("nested_gitlink_guard"):
            return self._restore_nested_gitlink_guard(
                _defer_terminal_cleanup=_defer_terminal_cleanup
            )
        self._restored_workspace_entry_authority = {}
        self._restored_tracked_metadata_observations = {}
        cwd = self._bound_workspace_cwd()
        retained_parent_postimages: dict[str, _ActiveParentPostimageRecord] = {}
        pending_attribute_changes = tuple(
            self._manifest.get("pre_capture_attribute_changes", ())
        )
        pending_attribute_admin = bool(
            self._manifest.get("pre_capture_attribute_admin_changed")
        )
        pending_deferred_attribute_policy = (
            self._validated_deferred_recursive_attribute_policy_roots()
        )
        self._restore_validation_in_progress = True
        self._restore_new_attribute_changes.clear()
        self._restore_new_attribute_admin_changed = False
        try:
            if active_parent_postimage_handoff is not None:
                retained_parent_postimages = (
                    self._consume_active_parent_postimage_handoff(
                        active_parent_postimage_handoff
                    )
                )
            self._prepare_workspace_root_access()
            self._assert_authority_lock_unchanged()
            self._assert_bound_git_authority()
            fsck_reasons = self._initial_fsck_reasons(cwd)
            self._prepare_restore_access(writable=False)
            self._assert_authority_lock_unchanged()
            self._assert_bound_git_authority()
            active_authority = _active_workspace_mutation_authority(
                Path(self._manifest["cwd"])
            )
            if not cwd.is_dir() or (
                active_authority is None and cwd.is_symlink()
            ):
                raise MutationJournalError(
                    f"checkout no longer exists or is aliased: {cwd}"
                )
            nested_ids = self._nested_transaction_ids()
            self._assert_no_failed_descendant(allow=nested_ids)
            self._prepare_restore_access(writable=True)
            nested_journals = self._nested_journals_for_restore()
            with ExitStack() as nested_authorities:
                for nested in nested_journals:
                    nested_authorities.enter_context(
                        nested._nested_restore_authority()
                    )
                for nested in nested_journals:
                    nested._preflight_nested_restore()
                for nested in reversed(nested_journals):
                    restored = nested.restore(_defer_terminal_cleanup=True)
                    if not restored:
                        raise MutationJournalError(
                            "nested child rollback failed: "
                            f"{nested.slice_id}"
                        )
            self._assert_no_failed_descendant()
            if retained_parent_postimages:
                # A linked-worktree or gitlink guard restored with deferred
                # cleanup is terminal but remains in the process-owned writer
                # family.  The active-parent handoff reproof below deliberately
                # accepts only active family members, so first retire these
                # successfully restored descendants through the ordinary
                # proof-bearing cleanup path.  The still-active family root
                # retains each exact terminal proof before any guard journal or
                # registry marker is removed.
                terminal_descendants = self._nested_journals_children_first()
                for nested in terminal_descendants:
                    _cleanup_terminal_mutation_journal(
                        nested,
                        allow_missing_registry=False,
                    )
                self._acknowledge_resolved_descendants(
                    nested.transaction_id
                    for nested in terminal_descendants
                )
            # Re-establish the common-dir orphan marker first. If untrusted
            # code removed/replaced it and this process dies during rollback,
            # another corpus must still be prevented from baselining the
            # partially-restored checkout.
            self._restore_registry_marker()
            self._restore_registry_topology()
            self._restore_git_entry(cwd)
            try:
                current_head: str | None = _head(cwd)
            except MutationJournalError:
                current_head = None
            current_ref = _symbolic_head(cwd)
            changed_attribute_admin = (
                self._restore_attribute_admin_control(cwd)
                or pending_attribute_admin
            )
            (
                early_attribute_policy_changes,
                restored_parent_bindings,
            ) = self._restore_recursive_roots_for_attribute_policy(cwd)
            changed_attribute_policy = tuple(sorted(set(
                (
                    *early_attribute_policy_changes,
                    *self._restore_attribute_policy(cwd),
                    *pending_attribute_changes,
                )
            )))
            # The violation remains represented by the forced full rollback;
            # clear its validation latch so final baseline assertions can run.
            self._manifest["pre_capture_attribute_changes"] = []
            self._manifest["pre_capture_attribute_admin_changed"] = False
            self._manifest[
                _DEFERRED_RECURSIVE_ATTRIBUTE_POLICY_KEY
            ] = {}
            try:
                self.assert_repository_metadata_unchanged()
                repository_metadata_changed = bool(
                    changed_attribute_policy or changed_attribute_admin
                )
            except MutationJournalError:
                repository_metadata_changed = True
            current_head_changed = (
                current_head != self._manifest["head"]
                or (
                    "head_symbolic_ref" in self._manifest
                    and current_ref != self._manifest["head_symbolic_ref"]
                )
                or repository_metadata_changed
            )
            if full is None:
                full = self.state == "invoking" or current_head_changed
            # Validate irreplaceable baseline objects before touching the
            # checkout, but retain newly-created commit/tree/blob objects until
            # all inter-HEAD paths have been enumerated and the worktree has
            # been reset. Removing a model-authored commit object first makes
            # the later diff unreadable and strands the rollback.
            self._restore_object_inventory(cwd, cleanup_additions=False)
            ignored_roots = self._effective_ignored_directory_roots(
                cwd,
                protected_paths=self._manifest.get("directory_modes", {}),
            )
            nested_markers_to_remove = _relevant_nested_vcs_markers(
                cwd,
                excluded_roots=(
                    *self._manifest.get("metadata_relatives", ()),
                    *self._manifest.get("initialized_gitlinks", ()),
                ),
                ignored_roots=ignored_roots,
            )
            roots = set(self._manifest["scope"])
            roots.update(self._manifest.get("scope_escapes", ()))
            # Git's index stat cache stores coarse timestamps on common
            # formats. Nanosecond worktree metadata independently exposes a
            # same-size/same-mtime overwrite, and the drifted path is restored
            # from its immutable HEAD/snapshot baseline below.
            metadata_drift = self._tracked_metadata_drift_paths(cwd)
            if full:
                roots.update(metadata_drift)
            else:
                roots.update(
                    path for path in metadata_drift
                    if any(
                        path == authorized
                        or path.startswith(authorized.rstrip("/") + "/")
                        for authorized in roots
                    )
                )
            if full:
                roots.update(self._manifest["baseline_dirty"])
                if current_head_changed:
                    # A hard reset can rewrite every path governed by a
                    # built-in checkout transform even when its blob OID did
                    # not change between commits. Reapply each path's exact
                    # physical baseline after the reset.
                    roots.update(self._manifest.get("transforming_paths", ()))
                    if current_head is not None:
                        changed = _git(
                            cwd,
                            "diff",
                            "--no-ext-diff",
                            "--no-textconv",
                            "--name-only",
                            "-z",
                            self._manifest["head"],
                            current_head,
                        )
                        roots.update(
                            _normalize_relative(cwd, os.fsdecode(path))
                            for path in changed.split(b"\0")
                            if path
                        )
            # Restore the physical namespace before resolving individual
            # controls: a nested loose-ref directory may itself have been
            # replaced by a symlink. Absent lock controls (including
            # index.lock) are removed here before reset/checkout writes.
            self._restore_refs_tree(cwd)
            self._restore_log_refs_tree(cwd)
            self._restore_control_files()
            self._remove_added_registered_worktrees(cwd)
            self._restore_absent_worktree_admin_controls()
            self._restore_worktree_namespace(cwd)
            self._restore_auxiliary_git_trees(cwd)
            self._restore_refs(cwd)
            if full:
                # Recompute status only after restoring config/attributes and
                # sparse controls; a model may have changed core.filemode or
                # ignore semantics specifically to hide an out-of-scope edit.
                roots.update(_git_status_paths(cwd))
            if full and current_head_changed:
                fsck_reasons.add("reset")
                baseline_ref_known = "head_symbolic_ref" in self._manifest
                baseline_ref = self._manifest.get("head_symbolic_ref")
                if baseline_ref_known and baseline_ref is not None:
                    _git(cwd, "symbolic-ref", "HEAD", baseline_ref)
                elif baseline_ref_known:
                    _git(
                        cwd,
                        "checkout",
                        "--detach",
                        "-q",
                        self._manifest["head"],
                    )
                _git(cwd, "reset", "--hard", self._manifest["head"])
            normalized = {
                _normalize_relative(cwd, path)
                for path in roots
            }
            metadata_relatives = self._metadata_relative_roots(cwd)
            normalized = {
                path for path in normalized
                if not any(
                    path == metadata or path.startswith(metadata + "/")
                    for metadata in metadata_relatives
                )
            }
            for relative in _dedupe_roots(normalized):
                _merge_workspace_restore_parent_bindings(
                    restored_parent_bindings,
                    self._restore_snapshot_root(
                        cwd,
                        relative,
                        expected_parent_bindings=restored_parent_bindings,
                    ),
                )
            for relative in nested_markers_to_remove:
                self._remove_workspace_relative_bound(relative)
            self._restore_index(cwd)
            # Reset/checkout can append reflogs and materialize ORIG_HEAD even
            # when moving to the same OID. Reapply the exact physical controls
            # after all Git worktree operations and before deleting the added
            # commit objects they may still mention.
            self._restore_refs_tree(cwd)
            self._restore_log_refs_tree(cwd)
            self._restore_control_files()
            self._restore_auxiliary_git_trees(cwd)
            # Ignore policy is now at the restored workspace/admin image.
            # Rescan globally so a temporary ignore rule cannot strand nested
            # administration that the pre-restore scan intentionally skipped.
            for relative in _relevant_nested_vcs_markers(
                cwd,
                excluded_roots=(
                    *self._manifest.get("metadata_relatives", ()),
                    *self._manifest.get("initialized_gitlinks", ()),
                ),
                ignored_roots=self._effective_ignored_directory_roots(
                    cwd,
                    protected_paths=self._manifest.get(
                        "directory_modes",
                        {},
                    ),
                ),
            ):
                self._remove_workspace_relative_bound(relative)
            self._restore_cached_module_controls()
            self._restore_module_namespace(cwd)
            self._remove_added_module_admin(cwd)
            workspace_directory_authority = self._restore_directory_modes(
                cwd,
                observed_parent_bindings=restored_parent_bindings,
            )
            if retained_parent_postimages:
                # Reauthenticate immediately before carrying any live inode
                # across the child's terminal boundary.  Restoration above
                # may not silently outlive or reparent the asserted family.
                if self._validated_active_parent_handoff_paths(
                    tuple(retained_parent_postimages)
                ) != frozenset(retained_parent_postimages):
                    raise MutationJournalError(
                        "retained parent path authority changed during restore"
                    )
            (
                workspace_entry_authority,
                verified_postimages,
            ) = self._restore_tracked_path_metadata(
                cwd,
                workspace_directory_authority,
                active_parent_postimages=retained_parent_postimages,
                restored_roots=frozenset(normalized),
            )
            missing_handoffs = {
                path
                for path, record in retained_parent_postimages.items()
                if path not in self._restored_workspace_entry_authority
                or self._restored_workspace_entry_authority[path]
                != _active_parent_postimage_identity(record)
            }
            if (
                verified_postimages != frozenset(retained_parent_postimages)
                or missing_handoffs
            ):
                raise MutationJournalError(
                    "active parent postimage handoff was not consumed for "
                    "every path: "
                    f"verified={sorted(verified_postimages)!r}; "
                    f"missing={sorted(missing_handoffs)!r}"
                )
            self._restore_object_inventory(cwd)
            self._restore_git_admin_topology()
            self.assert_head_unchanged()
            self.assert_repository_metadata_unchanged()
            self.assert_index_unchanged()
            self._assert_workspace_baseline(
                cwd,
                roots=normalized,
                full=bool(full),
            )
            if _requires_full_fsck(fsck_reasons):
                logger.info(
                    "mutation journal: full fsck slice=%s cwd=%s reasons=%s",
                    self.slice_id,
                    cwd,
                    sorted(fsck_reasons),
                )
                _git_fsck(cwd, "--full", "--no-dangling", "HEAD")
            if _active_workspace_mutation_authority(
                Path(self._manifest["cwd"])
            ) is not None:
                _assert_workspace_mutation_authority(
                    Path(self._manifest["cwd"])
                )
            workspace_directory_authority = (
                self._reprove_restored_workspace_directory_authority(
                    cwd,
                    workspace_directory_authority,
                )
            )
            self._reprove_restored_workspace_entry_authority(
                workspace_directory_authority,
            )
            terminal_verified_postimages = (
                self._reprove_restored_tracked_path_authority(
                    cwd,
                    workspace_directory_authority,
                    workspace_entry_authority,
                    active_parent_postimages=retained_parent_postimages,
                )
            )
            if terminal_verified_postimages != frozenset(
                retained_parent_postimages
            ):
                raise MutationJournalError(
                    "active parent postimage handoff was not terminally "
                    "reproved for every path"
                )
            self._manifest["pre_capture_attribute_changes"] = []
            self._manifest["pre_capture_attribute_admin_changed"] = False
            self._manifest[
                _DEFERRED_RECURSIVE_ATTRIBUTE_POLICY_KEY
            ] = {}
            previous = self._manifest["state"]
            self._manifest["state"] = "rolled_back"
            try:
                self._write()
            except BaseException:
                self._manifest["state"] = previous
                raise
            if not _defer_terminal_cleanup:
                terminal_descendants = self._nested_journals_children_first()
                for nested in terminal_descendants:
                    _cleanup_terminal_mutation_journal(
                        nested,
                        allow_missing_registry=False,
                    )
                self._acknowledge_resolved_descendants(
                    nested.transaction_id
                    for nested in terminal_descendants
                )
                _cleanup_terminal_mutation_journal(
                    self,
                    allow_missing_registry=False,
                )
            logger.info(
                "mutation journal: restored slice %s (%s rollback)",
                self.slice_id,
                "full" if full else "scoped",
            )
            return True
        except BaseException:  # keep durable journal for startup retry
            if self.active:
                self._manifest["pre_capture_attribute_changes"] = sorted({
                    *pending_attribute_changes,
                    *self._restore_new_attribute_changes,
                })
                self._manifest["pre_capture_attribute_admin_changed"] = (
                    pending_attribute_admin
                    or self._restore_new_attribute_admin_changed
                )
                # A policy change observed during rollback revokes any older
                # whole-root tombstone proof for that path.  Restoring the
                # original map wholesale would let a fresh direct mutation be
                # laundered as the earlier recursive deletion on retry.
                self._manifest[
                    _DEFERRED_RECURSIVE_ATTRIBUTE_POLICY_KEY
                ] = {
                    path: recursive_root
                    for path, recursive_root in (
                        pending_deferred_attribute_policy.items()
                    )
                    if path not in self._restore_new_attribute_changes
                }
                self._record_restore_failure()
            logger.exception(
                "mutation journal %s: rollback failed; journal retained",
                self.journal_dir,
            )
            return False
        finally:
            self._restore_validation_in_progress = False
            self._restore_new_attribute_changes.clear()
            self._restore_new_attribute_admin_changed = False


@dataclass(frozen=True)
class _MutationJournalPathComponent:
    name: str
    device: int
    inode: int


@dataclass(frozen=True)
class _TerminalCleanupReceipt:
    parent_path: Path
    parent_device: int
    parent_inode: int
    receipt_name: str
    receipt_payload: bytes
    transaction_id: str
    original_name: str
    tombstone_name: str
    journal_device: int
    journal_inode: int
    manifest: dict[str, object]
    writer_epoch_terminal_proof: (
        _writer_epoch_module.WriterEpochTerminalProof
    )
    registry_payload: bytes
    proof_digests: dict[str, str | None]
    journal_inventory: tuple[tuple[object, ...], ...]
    target_name: str | None


@dataclass(frozen=True)
class _MutationJournalPathBinding:
    spec_dir: Path
    spec_device: int
    spec_inode: int
    components: tuple[_MutationJournalPathComponent, ...]
    manifest_metadata: tuple[int, int, int, int, int, int, int]
    artifact_inventory: tuple[tuple[object, ...], ...]


@dataclass
class _MutationJournalArtifactBudget:
    paths: int = 0
    bytes: int = 0

    def charge_path(self) -> None:
        self.paths += 1
        if self.paths > _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS:
            raise MutationJournalError(
                "mutation journal artifact inventory exceeds its path ceiling"
            )

    def charge_bytes(self, size: int) -> None:
        self.bytes += size
        if self.bytes > _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_BYTES:
            raise MutationJournalError(
                "mutation journal artifact inventory exceeds its byte ceiling"
            )


def _mutation_journal_artifact_inventory(
    journal_fd: int,
    *,
    budget: _MutationJournalArtifactBudget | None = None,
) -> tuple[tuple[object, ...], ...]:
    """Hash every restore-authority artifact below one held journal fd."""

    capture_budget = budget or _MutationJournalArtifactBudget()
    records: list[tuple[object, ...]] = []

    def walk(directory_fd: int, prefix: str, depth: int) -> None:
        if depth > _MUTATION_JOURNAL_MAX_DISCOVERY_DEPTH:
            raise MutationJournalError(
                "mutation journal artifact tree exceeds its depth ceiling"
            )
        remaining = (
            _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS
            - capture_budget.paths
        )
        entry_ceiling = remaining + (2 if not prefix else 0)
        initial_names = _bounded_directory_names(
            directory_fd,
            label="mutation journal artifact tree",
            max_entries=entry_ceiling,
        )
        for name in initial_names:
            if not prefix and name in {_MANIFEST, "nested_mutations"}:
                continue
            capture_budget.charge_path()
            relative = f"{prefix}/{name}" if prefix else name
            before = os.stat(
                name,
                dir_fd=directory_fd,
                follow_symlinks=False,
            )
            descriptor: int | None = None
            try:
                if stat.S_ISDIR(before.st_mode) and not stat.S_ISLNK(
                    before.st_mode
                ):
                    descriptor = os.open(
                        name,
                        os.O_RDONLY
                        | getattr(os, "O_CLOEXEC", 0)
                        | getattr(os, "O_DIRECTORY", 0)
                        | getattr(os, "O_NOFOLLOW", 0),
                        dir_fd=directory_fd,
                    )
                    opened = os.fstat(descriptor)
                    if (opened.st_dev, opened.st_ino) != (
                        before.st_dev,
                        before.st_ino,
                    ):
                        raise MutationJournalError(
                            "mutation journal artifact directory changed "
                            f"while opening: {relative!r}"
                        )
                    records.append((
                        relative,
                        "directory",
                        opened.st_dev,
                        opened.st_ino,
                        opened.st_mode,
                        opened.st_nlink,
                        opened.st_mtime_ns,
                        opened.st_ctime_ns,
                        None,
                    ))
                    walk(descriptor, relative, depth + 1)
                elif stat.S_ISREG(before.st_mode) and not stat.S_ISLNK(
                    before.st_mode
                ):
                    if before.st_nlink != 1:
                        raise MutationJournalError(
                            "mutation journal artifact is hard-linked: "
                            f"{relative!r}"
                        )
                    capture_budget.charge_bytes(before.st_size)
                    descriptor = os.open(
                        name,
                        os.O_RDONLY
                        | getattr(os, "O_CLOEXEC", 0)
                        | getattr(os, "O_NOFOLLOW", 0)
                        | getattr(os, "O_NONBLOCK", 0),
                        dir_fd=directory_fd,
                    )
                    opened = os.fstat(descriptor)
                    if (
                        not stat.S_ISREG(opened.st_mode)
                        or opened.st_nlink != 1
                        or (opened.st_dev, opened.st_ino)
                        != (before.st_dev, before.st_ino)
                    ):
                        raise MutationJournalError(
                            "mutation journal artifact changed while opening: "
                            f"{relative!r}"
                        )
                    digest = hashlib.sha256()
                    observed = 0
                    while True:
                        chunk = os.read(descriptor, 1024 * 1024)
                        if not chunk:
                            break
                        observed += len(chunk)
                        if observed > before.st_size:
                            raise MutationJournalError(
                                "mutation journal artifact grew during read: "
                                f"{relative!r}"
                            )
                        digest.update(chunk)
                    finished = os.fstat(descriptor)
                    if observed != before.st_size or any(
                        getattr(opened, field) != getattr(finished, field)
                        for field in _SETTLEMENT_STABLE_STAT_FIELDS
                    ):
                        raise MutationJournalError(
                            "mutation journal artifact changed during read: "
                            f"{relative!r}"
                        )
                    records.append((
                        relative,
                        "file",
                        opened.st_dev,
                        opened.st_ino,
                        opened.st_mode,
                        opened.st_nlink,
                        opened.st_mtime_ns,
                        opened.st_ctime_ns,
                        digest.hexdigest(),
                    ))
                else:
                    raise MutationJournalError(
                        "mutation journal artifact is a special or aliased "
                        f"file: {relative!r}"
                    )
                after = os.stat(
                    name,
                    dir_fd=directory_fd,
                    follow_symlinks=False,
                )
                if any(
                    getattr(before, field) != getattr(after, field)
                    for field in _SETTLEMENT_STABLE_STAT_FIELDS
                ):
                    raise MutationJournalError(
                        "mutation journal artifact changed during inventory: "
                        f"{relative!r}"
                    )
            finally:
                if descriptor is not None:
                    os.close(descriptor)
        final_names = _bounded_directory_names(
            directory_fd,
            label="mutation journal artifact tree",
            max_entries=entry_ceiling,
        )
        if initial_names != final_names:
            raise MutationJournalError(
                "mutation journal artifact tree changed during inventory"
            )

    walk(journal_fd, "", 0)
    return tuple(sorted(records, key=lambda item: str(item[0])))


def _terminal_cleanup_journal_inventory(
    journal_fd: int,
) -> tuple[tuple[object, ...], ...]:
    """Bind every remaining journal node independent of cleanup renames."""

    budget = _MutationJournalArtifactBudget()
    records: list[tuple[object, ...]] = []

    def cleanup_reservation(name: str) -> bool:
        suffix = name.removeprefix(".crucible-cleanup-")
        return (
            name.startswith(".crucible-cleanup-")
            and len(suffix) >= 64
            and re.fullmatch(r"[0-9a-f]{64}", suffix[-64:]) is not None
        )

    def walk(directory_fd: int, depth: int) -> None:
        if depth > _MUTATION_JOURNAL_MAX_DISCOVERY_DEPTH:
            raise MutationJournalError(
                "terminal cleanup inventory exceeds its depth ceiling"
            )
        names = _bounded_directory_names(
            directory_fd,
            label="terminal cleanup journal inventory",
            max_entries=(
                _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS - budget.paths
            ),
        )
        for name in names:
            budget.charge_path()
            before = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
            descriptor: int | None = None
            try:
                if stat.S_ISDIR(before.st_mode) and not stat.S_ISLNK(
                    before.st_mode
                ):
                    descriptor = os.open(
                        name,
                        os.O_RDONLY
                        | getattr(os, "O_CLOEXEC", 0)
                        | getattr(os, "O_DIRECTORY", 0)
                        | getattr(os, "O_NOFOLLOW", 0),
                        dir_fd=directory_fd,
                    )
                    opened = os.fstat(descriptor)
                    if (opened.st_dev, opened.st_ino) != (
                        before.st_dev,
                        before.st_ino,
                    ):
                        raise MutationJournalError(
                            "terminal cleanup directory changed while opening"
                        )
                    child_names = _bounded_directory_names(
                        descriptor,
                        label="terminal cleanup journal inventory directory",
                        max_entries=(
                            _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS
                            - budget.paths
                        ),
                    )
                    if cleanup_reservation(name) and not child_names:
                        continue
                    records.append((
                        "directory",
                        opened.st_dev,
                        opened.st_ino,
                        opened.st_mode,
                    ))
                    walk(descriptor, depth + 1)
                elif stat.S_ISREG(before.st_mode) and not stat.S_ISLNK(
                    before.st_mode
                ):
                    if before.st_nlink != 1:
                        raise MutationJournalError(
                            "terminal cleanup inventory file is hard-linked"
                        )
                    if cleanup_reservation(name) and before.st_size == 0:
                        continue
                    budget.charge_bytes(before.st_size)
                    digest = _digest_bound_regular_entry(
                        directory_fd,
                        name,
                        label="terminal cleanup journal inventory file",
                        max_bytes=(
                            _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_BYTES
                            - budget.bytes
                            + before.st_size
                        ),
                    )
                    records.append((
                        "file",
                        before.st_dev,
                        before.st_ino,
                        before.st_mode,
                        before.st_nlink,
                        before.st_size,
                        digest,
                    ))
                else:
                    raise MutationJournalError(
                        "terminal cleanup inventory contains a special entry"
                    )
                after = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
                if (after.st_dev, after.st_ino) != (
                    before.st_dev,
                    before.st_ino,
                ):
                    raise MutationJournalError(
                        "terminal cleanup inventory entry changed identity"
                    )
            finally:
                if descriptor is not None:
                    os.close(descriptor)
        if names != _bounded_directory_names(
            directory_fd,
            label="terminal cleanup journal inventory",
            max_entries=(
                _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS - budget.paths
                + len(names)
            ),
        ):
            raise MutationJournalError(
                "terminal cleanup journal inventory changed during capture"
            )

    walk(journal_fd, 0)
    return tuple(sorted(records, key=repr))


def _journal_manifest_metadata(
    journal_fd: int,
) -> tuple[int, int, int, int, int, int, int]:
    try:
        metadata = os.stat(
            _MANIFEST,
            dir_fd=journal_fd,
            follow_symlinks=False,
        )
    except OSError as exc:
        raise MutationJournalError(
            f"cannot inspect bound mutation journal manifest: {exc}"
        ) from exc
    if (
        not stat.S_ISREG(metadata.st_mode)
        or stat.S_ISLNK(metadata.st_mode)
        or metadata.st_nlink != 1
        or metadata.st_size > _MUTATION_JOURNAL_MAX_MANIFEST_BYTES
    ):
        raise MutationJournalError(
            "bound mutation journal manifest is unsafe"
        )
    return cast(tuple[int, int, int, int, int, int, int], tuple(
        int(getattr(metadata, field))
        for field in _SETTLEMENT_STABLE_STAT_FIELDS
    ))


def _compare_replace_bound_manifest_at(
    journal_fd: int,
    journal_dir: Path,
    *,
    expected_payload: bytes,
    expected_metadata: os.stat_result,
    replacement: Mapping[str, object],
) -> dict[str, object]:
    """CAS one held journal manifest, fsync it, and return the durable reread."""

    payload = json.dumps(
        replacement,
        indent=2,
        default=str,
    ).encode("utf-8")
    if len(payload) > _MUTATION_JOURNAL_MAX_MANIFEST_BYTES:
        raise MutationJournalError(
            "writer epoch replacement manifest exceeds its byte ceiling"
        )
    temporary = f".tmp_{_MANIFEST}_{os.getpid()}_{secrets.token_hex(16)}"
    descriptor: int | None = None
    published = False
    try:
        descriptor = os.open(
            temporary,
            os.O_WRONLY
            | os.O_CREAT
            | os.O_EXCL
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0),
            0o600,
            dir_fd=journal_fd,
        )
        _write_all_bound(descriptor, payload)
        os.fsync(descriptor)
        os.close(descriptor)
        descriptor = None

        current_payload, current_metadata = _read_bound_regular_entry(
            journal_fd,
            _MANIFEST,
            label="writer epoch compare manifest",
            max_bytes=_MUTATION_JOURNAL_MAX_MANIFEST_BYTES,
        )
        if (
            current_payload != expected_payload
            or (current_metadata.st_dev, current_metadata.st_ino)
            != (expected_metadata.st_dev, expected_metadata.st_ino)
        ):
            raise MutationJournalError(
                "writer epoch manifest changed before compare-and-write"
            )
        os.replace(
            temporary,
            _MANIFEST,
            src_dir_fd=journal_fd,
            dst_dir_fd=journal_fd,
        )
        published = True
        _fsync_terminal_parent_directory(
            journal_fd,
            label="writer epoch journal directory",
        )
        observed = _load_mutation_journal_manifest_at(
            journal_fd,
            journal_dir,
        )
        if observed != replacement:
            raise MutationJournalError(
                "writer epoch replacement changed after durable publication"
            )
        return cast(dict[str, object], observed)
    finally:
        if descriptor is not None:
            os.close(descriptor)
        if not published:
            try:
                os.unlink(temporary, dir_fd=journal_fd)
            except FileNotFoundError:
                pass


@contextmanager
def _bound_mutation_journal_directory(
    journal: WorkspaceMutationJournal,
    *,
    verify_manifest_payload: bool = True,
    verify_artifacts: bool = True,
) -> Iterator[tuple[Path, int, int, str]]:
    """Reopen a discovered journal's full no-follow chain and hold its fds."""

    binding = journal._discovery_binding
    if binding is None:
        raise MutationJournalError(
            "mutation journal has no descriptor discovery binding"
        )
    descriptors: list[int] = []
    try:
        spec_fd, spec_opened = _open_authority_directory(
            binding.spec_dir,
            label="bound Corpus Spec directory",
        )
        descriptors.append(spec_fd)
        if (
            spec_opened.st_dev,
            spec_opened.st_ino,
        ) != (binding.spec_device, binding.spec_inode):
            raise MutationJournalError(
                "Corpus Spec directory changed after journal discovery"
            )
        parent_fd = spec_fd
        for component in binding.components:
            descriptor, opened = _discovery_directory_entry(
                parent_fd,
                component.name,
                label=f"bound mutation journal component {component.name!r}",
            )
            descriptors.append(descriptor)
            if (opened.st_dev, opened.st_ino) != (
                component.device,
                component.inode,
            ):
                raise MutationJournalError(
                    "mutation journal path changed after discovery at "
                    f"{component.name!r}"
                )
            parent_fd = descriptor
        if len(descriptors) < 2:
            raise MutationJournalError(
                "mutation journal discovery binding is incomplete"
            )
        journal_fd = descriptors[-1]
        if _journal_manifest_metadata(journal_fd) != binding.manifest_metadata:
            raise MutationJournalError(
                "mutation journal manifest changed after discovery"
            )
        if verify_artifacts and (
            _mutation_journal_artifact_inventory(journal_fd)
            != binding.artifact_inventory
        ):
            raise MutationJournalError(
                "mutation journal restore artifacts changed after discovery"
            )
        if verify_manifest_payload:
            observed = _load_mutation_journal_manifest_at(
                journal_fd,
                journal.journal_dir,
            )
            if observed != journal._manifest:
                raise MutationJournalError(
                    "mutation journal manifest payload changed after discovery"
                )
        yield (
            Path(_authority_descriptor_cwd(journal_fd)),
            journal_fd,
            descriptors[-2],
            binding.components[-1].name,
        )
    finally:
        for descriptor in reversed(descriptors):
            os.close(descriptor)


@contextmanager
def refresh_mutation_journal_artifact_binding(
    journal: WorkspaceMutationJournal,
    *,
    allowed_paths: Iterable[str] = (),
    allowed_prefixes: Iterable[str] = (),
    expected_artifacts: Mapping[str, tuple[str, str | None]] | None = None,
    exclusive_prefixes: Iterable[str] = (),
) -> Iterator[tuple[Path, int | None]]:
    """Perform and bind one exact, authorized journal-artifact transition."""

    if journal._discovery_binding is None:
        yield journal.journal_dir, None
        return
    exact = frozenset(
        _settlement_relative_path(path) for path in allowed_paths
    )
    prefixes = frozenset(
        _settlement_relative_path(path) for path in allowed_prefixes
    )
    exclusive = frozenset(
        _settlement_relative_path(path) for path in exclusive_prefixes
    )
    if not exact and not prefixes and expected_artifacts is None:
        raise MutationJournalError(
            "journal artifact update has no authorized path"
        )

    binding = journal._discovery_binding
    with _bound_mutation_journal_directory(journal) as (
        artifact_dir,
        journal_fd,
        _parent_fd,
        _entry_name,
    ):
        yield artifact_dir, journal_fd
        if journal._discovery_binding is not binding:
            raise MutationJournalError(
                "mutation journal artifact authority changed during update"
            )
        observed = _mutation_journal_artifact_inventory(journal_fd)
        previous_by_path = {
            str(record[0]): record for record in binding.artifact_inventory
        }
        observed_by_path = {
            str(record[0]): record for record in observed
        }
        expected = {
            _settlement_relative_path(path): value
            for path, value in (expected_artifacts or {}).items()
        }

        def authorized(path: str) -> bool:
            return path in exact or path in expected or any(
                path == prefix or path.startswith(prefix.rstrip("/") + "/")
                for prefix in prefixes
            )

        changed = {
            path
            for path in set(previous_by_path) | set(observed_by_path)
            if previous_by_path.get(path) != observed_by_path.get(path)
        }
        unauthorized = sorted(path for path in changed if not authorized(path))
        if unauthorized:
            raise MutationJournalError(
                "journal artifact update changed unauthorized paths: "
                f"{unauthorized!r}"
            )
        for path, (kind, digest) in expected.items():
            record = observed_by_path.get(path)
            if (
                record is None
                or record[1] != kind
                or record[8] != digest
            ):
                raise MutationJournalError(
                    "journal artifact update differs from its authored "
                    f"payload: {path!r}"
                )
        for prefix in exclusive:
            observed_under_prefix = {
                path
                for path in observed_by_path
                if path == prefix
                or path.startswith(prefix.rstrip("/") + "/")
            }
            expected_under_prefix = {
                path
                for path in expected
                if path == prefix
                or path.startswith(prefix.rstrip("/") + "/")
            }
            if observed_under_prefix != expected_under_prefix:
                raise MutationJournalError(
                    "journal artifact update introduced unreferenced paths "
                    f"under {prefix!r}"
                )
        journal._discovery_binding = replace(
            binding,
            artifact_inventory=observed,
        )


@contextmanager
def _bound_mutation_journal_run_directory(
    journal: WorkspaceMutationJournal,
) -> Iterator[tuple[Path, int]]:
    """Hold the exact run directory captured by journal discovery."""

    binding = journal._discovery_binding
    if binding is None or len(binding.components) < 2:
        raise MutationJournalError(
            "mutation journal has no bound Corpus run authority"
        )
    descriptors: list[int] = []
    try:
        spec_fd, spec_opened = _open_authority_directory(
            binding.spec_dir,
            label="bound Corpus Spec directory",
        )
        descriptors.append(spec_fd)
        if (spec_opened.st_dev, spec_opened.st_ino) != (
            binding.spec_device,
            binding.spec_inode,
        ):
            raise MutationJournalError(
                "Corpus Spec directory changed after journal discovery"
            )
        parent_fd = spec_fd
        for component in binding.components[:2]:
            descriptor, opened = _discovery_directory_entry(
                parent_fd,
                component.name,
                label=f"bound Corpus run component {component.name!r}",
            )
            descriptors.append(descriptor)
            if (opened.st_dev, opened.st_ino) != (
                component.device,
                component.inode,
            ):
                raise MutationJournalError(
                    "Corpus run path changed after journal discovery"
                )
            parent_fd = descriptor
        yield Path(_authority_descriptor_cwd(descriptors[-1])), descriptors[-1]
    finally:
        for descriptor in reversed(descriptors):
            os.close(descriptor)


def _bind_discovered_mutation_journal(
    journal: WorkspaceMutationJournal,
    spec_dir: Path,
    *,
    artifact_budget: _MutationJournalArtifactBudget | None = None,
) -> None:
    try:
        relative = journal.journal_dir.relative_to(spec_dir)
    except ValueError as exc:
        raise MutationJournalError(
            "mutation journal path escapes its Corpus Spec directory"
        ) from exc
    if not relative.parts:
        raise MutationJournalError("mutation journal path binding is empty")
    spec_fd, spec_opened = _open_authority_directory(
        spec_dir,
        label="Corpus Spec directory",
    )
    descriptors = [spec_fd]
    components: list[_MutationJournalPathComponent] = []
    try:
        parent_fd = spec_fd
        for name in relative.parts:
            descriptor, opened = _discovery_directory_entry(
                parent_fd,
                name,
                label=f"mutation journal path component {name!r}",
            )
            descriptors.append(descriptor)
            components.append(_MutationJournalPathComponent(
                name=name,
                device=opened.st_dev,
                inode=opened.st_ino,
            ))
            parent_fd = descriptor
        observed = _load_mutation_journal_manifest_at(
            descriptors[-1],
            journal.journal_dir,
        )
        if observed != journal._manifest:
            raise MutationJournalError(
                "mutation journal changed between inventory and path binding"
            )
        journal._discovery_binding = _MutationJournalPathBinding(
            spec_dir=spec_dir,
            spec_device=spec_opened.st_dev,
            spec_inode=spec_opened.st_ino,
            components=tuple(components),
            manifest_metadata=_journal_manifest_metadata(descriptors[-1]),
            artifact_inventory=_mutation_journal_artifact_inventory(
                descriptors[-1],
                budget=artifact_budget,
            ),
        )
    finally:
        for descriptor in reversed(descriptors):
            os.close(descriptor)


def _terminal_receipt_name(transaction_id: str) -> str:
    if re.fullmatch(r"[0-9a-f]{32}", transaction_id) is None:
        raise MutationJournalError(
            "terminal cleanup transaction id is malformed"
        )
    return f"{_TERMINAL_RECEIPT_PREFIX}{transaction_id}.json"


def _terminal_tombstone_name(transaction_id: str, nonce: str) -> str:
    if re.fullmatch(r"[0-9a-f]{64}", nonce) is None:
        raise MutationJournalError("terminal cleanup nonce is malformed")
    return f"{_TERMINAL_TOMBSTONE_PREFIX}{transaction_id}-{nonce}"


def _writer_epoch_manifest_proof(
    manifest: Mapping[str, object],
    *,
    terminal_state: "_writer_epoch_module.WriterTerminalState",
) -> "_writer_epoch_module.WriterEpochTerminalProof":
    """Build an exact typed epoch certificate for a recovery manifest."""

    transaction_id = manifest.get("transaction_id")
    parent = manifest.get("parent_transaction_id")
    if (
        not isinstance(transaction_id, str)
        or (parent is not None and not isinstance(parent, str))
        or terminal_state not in {"committed", "rolled_back"}
    ):
        raise MutationJournalError(
            "terminal cleanup writer epoch identity is malformed"
        )
    epoch_record = manifest.get(WRITER_EPOCH_MANIFEST_KEY)
    try:
        parsed_epoch = _writer_epoch_module._parse_epoch_record(epoch_record)
    except (TypeError, ValueError) as exc:
        raise MutationJournalError(
            f"terminal cleanup writer epoch is UNKNOWN: {exc}"
        ) from exc
    if parsed_epoch.state == "quiesced":
        family = tuple(
            (member.transaction_id, member.parent_transaction_id)
            for member in parsed_epoch.family
        )
    elif parsed_epoch.state == "never_armed":
        family = _generation_zero_writer_epoch_family(manifest)
    else:
        raise MutationJournalError(
            "terminal cleanup writer epoch remains armed"
        )
    try:
        return _writer_epoch_module.build_writer_epoch_terminal_proof(
            transaction_id=transaction_id,
            parent_transaction_id=cast(str | None, parent),
            terminal_state=terminal_state,
            epoch_record=epoch_record,
            family=family,
            terminal_manifest=manifest,
        )
    except (
        TypeError,
        ValueError,
        _writer_epoch_module.WriterEpochBlockedError,
    ) as exc:
        raise MutationJournalError(
            f"terminal cleanup writer epoch proof is invalid: {exc}"
        ) from exc


def _terminal_cleanup_writer_epoch_proof(
    manifest: Mapping[str, object],
) -> "_writer_epoch_module.WriterEpochTerminalProof":
    """Build the exact typed epoch certificate for a terminal receipt."""

    state = manifest.get("state")
    if state not in {"committed", "rolled_back"}:
        raise MutationJournalError(
            "terminal cleanup writer epoch state is malformed"
        )
    return _writer_epoch_manifest_proof(
        manifest,
        terminal_state=cast(
            "_writer_epoch_module.WriterTerminalState",
            state,
        ),
    )


def _parse_terminal_cleanup_receipt(
    parent_fd: int,
    parent_path: Path,
    receipt_name: str,
    payload: bytes,
    *,
    canonical_receipt_name: str | None = None,
) -> _TerminalCleanupReceipt:
    """Validate one durable out-of-journal terminal cleanup authority."""

    try:
        record = json.loads(payload)
    except (TypeError, ValueError, json.JSONDecodeError) as exc:
        raise MutationJournalError(
            "terminal cleanup receipt is malformed"
        ) from exc
    required = {
        "schema",
        "transaction_id",
        "original_name",
        "tombstone_name",
        "parent_device",
        "parent_inode",
        "journal_device",
        "journal_inode",
        "manifest_b64",
        "manifest_sha256",
        "registry_marker_b64",
        "registry_marker_sha256",
        "writer_epoch_terminal_proof",
        "proof_digests",
        "journal_inventory",
    }
    if not isinstance(record, dict) or set(record) != required:
        raise MutationJournalError("terminal cleanup receipt fields changed")
    transaction_id = str(record.get("transaction_id", ""))
    if (
        record.get("schema") != _TERMINAL_CLEANUP_SCHEMA
        or (canonical_receipt_name or receipt_name)
        != _terminal_receipt_name(transaction_id)
        or not isinstance(record.get("original_name"), str)
        or not isinstance(record.get("tombstone_name"), str)
        or not isinstance(record.get("parent_device"), int)
        or isinstance(record.get("parent_device"), bool)
        or not isinstance(record.get("parent_inode"), int)
        or isinstance(record.get("parent_inode"), bool)
        or not isinstance(record.get("journal_device"), int)
        or isinstance(record.get("journal_device"), bool)
        or not isinstance(record.get("journal_inode"), int)
        or isinstance(record.get("journal_inode"), bool)
        or not isinstance(record.get("writer_epoch_terminal_proof"), dict)
        or not isinstance(record.get("proof_digests"), dict)
        or not isinstance(record.get("journal_inventory"), list)
    ):
        raise MutationJournalError("terminal cleanup receipt authority changed")
    parent_metadata = os.fstat(parent_fd)
    if (parent_metadata.st_dev, parent_metadata.st_ino) != (
        int(record["parent_device"]),
        int(record["parent_inode"]),
    ):
        raise MutationJournalError(
            "terminal cleanup receipt parent authority changed"
        )
    original_name = str(record["original_name"])
    tombstone_name = str(record["tombstone_name"])
    tombstone_prefix = f"{_TERMINAL_TOMBSTONE_PREFIX}{transaction_id}-"
    nonce = tombstone_name.removeprefix(tombstone_prefix)
    if (
        original_name in {"", ".", ".."}
        or "/" in original_name
        or not tombstone_name.startswith(tombstone_prefix)
        or _terminal_tombstone_name(transaction_id, nonce) != tombstone_name
    ):
        raise MutationJournalError("terminal cleanup receipt paths changed")
    try:
        manifest_payload = base64.b64decode(
            str(record["manifest_b64"]),
            validate=True,
        )
        registry_payload = base64.b64decode(
            str(record["registry_marker_b64"]),
            validate=True,
        )
    except (TypeError, ValueError) as exc:
        raise MutationJournalError(
            "terminal cleanup receipt payload is malformed"
        ) from exc
    raw_proof_digests = cast(dict[object, object], record["proof_digests"])
    if set(raw_proof_digests) != {
        "git_entry",
        "index_stage",
        "index_flags_v",
        "index_flags_f",
    } or any(
        not isinstance(key, str)
        or (
            value is not None
            and (
                not isinstance(value, str)
                or re.fullmatch(r"[0-9a-f]{64}", value) is None
            )
        )
        for key, value in raw_proof_digests.items()
    ):
        raise MutationJournalError(
            "terminal cleanup proof digests are malformed"
        )
    proof_digests = {
        str(key): (str(value) if value is not None else None)
        for key, value in raw_proof_digests.items()
    }
    raw_inventory = cast(list[object], record["journal_inventory"])
    if len(raw_inventory) > _MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS:
        raise MutationJournalError(
            "terminal cleanup journal inventory exceeds its path ceiling"
        )
    journal_inventory: list[tuple[object, ...]] = []
    for raw_item in raw_inventory:
        if not isinstance(raw_item, list):
            raise MutationJournalError(
                "terminal cleanup journal inventory is malformed"
            )
        item = tuple(raw_item)
        valid_directory = (
            len(item) == 4
            and item[0] == "directory"
            and all(
                isinstance(value, int) and not isinstance(value, bool)
                for value in item[1:]
            )
        )
        valid_file = (
            len(item) == 7
            and item[0] == "file"
            and all(
                isinstance(value, int) and not isinstance(value, bool)
                for value in item[1:6]
            )
            and isinstance(item[6], str)
            and re.fullmatch(r"[0-9a-f]{64}", item[6]) is not None
        )
        if not valid_directory and not valid_file:
            raise MutationJournalError(
                "terminal cleanup journal inventory is malformed"
            )
        journal_inventory.append(item)
    if len(journal_inventory) != len(set(journal_inventory)):
        raise MutationJournalError(
            "terminal cleanup journal inventory contains duplicate nodes"
        )
    if (
        len(payload) > _TERMINAL_RECEIPT_MAX_BYTES
        or hashlib.sha256(manifest_payload).hexdigest()
        != record.get("manifest_sha256")
        or hashlib.sha256(registry_payload).hexdigest()
        != record.get("registry_marker_sha256")
    ):
        raise MutationJournalError("terminal cleanup receipt digest changed")
    try:
        manifest = json.loads(manifest_payload)
        registry_record = json.loads(registry_payload)
    except (TypeError, ValueError, json.JSONDecodeError) as exc:
        raise MutationJournalError(
            "terminal cleanup embedded authority is malformed"
        ) from exc
    if (
        not isinstance(manifest, dict)
        or manifest.get("transaction_id") != transaction_id
        or manifest.get("state") not in {"committed", "rolled_back"}
        or not isinstance(registry_record, dict)
        or registry_record.get("schema") != _SCHEMA
        or registry_record.get("transaction_id") != transaction_id
        or registry_record.get("cwd") != manifest.get("cwd")
        or registry_record.get("journal_dir")
        != str(_lexical_workspace_path(parent_path / original_name))
        or registry_record.get("spec_dir")
        != str(_originating_spec_dir_lexical(parent_path))
    ):
        raise MutationJournalError(
            "terminal cleanup embedded authority changed"
        )
    try:
        writer_epoch_terminal_proof = (
            _writer_epoch_module.parse_writer_epoch_terminal_proof(
                record["writer_epoch_terminal_proof"]
            )
        )
        expected_writer_epoch_proof = _terminal_cleanup_writer_epoch_proof(
            cast(dict[str, object], manifest)
        )
    except (TypeError, ValueError, MutationJournalError) as exc:
        raise MutationJournalError(
            f"terminal cleanup writer epoch proof is malformed: {exc}"
        ) from exc
    if writer_epoch_terminal_proof.to_record() != (
        expected_writer_epoch_proof.to_record()
    ):
        raise MutationJournalError(
            "terminal cleanup writer epoch proof changed"
        )
    journal_identity = (
        int(record["journal_device"]),
        int(record["journal_inode"]),
    )
    targets: list[str] = []
    for name in (original_name, tombstone_name):
        try:
            metadata = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            continue
        if (
            not stat.S_ISDIR(metadata.st_mode)
            or stat.S_ISLNK(metadata.st_mode)
            or (metadata.st_dev, metadata.st_ino) != journal_identity
        ):
            raise MutationJournalError(
                "terminal cleanup target identity changed"
            )
        targets.append(name)
    if len(targets) > 1:
        raise MutationJournalError("terminal cleanup target is duplicated")
    target_name = targets[0] if targets else None
    if target_name == original_name:
        target_fd, _target_opened = _open_authority_directory_at(
            parent_fd,
            original_name,
            label="terminal cleanup original journal",
        )
        try:
            observed_manifest, _metadata = _read_bound_regular_entry(
                target_fd,
                _MANIFEST,
                label="terminal cleanup original manifest",
                max_bytes=_MUTATION_JOURNAL_MAX_MANIFEST_BYTES,
            )
            if observed_manifest != manifest_payload:
                raise MutationJournalError(
                    "terminal cleanup receipt targets a non-terminal journal"
                )
        finally:
            os.close(target_fd)
    if target_name is not None:
        target_fd, _target_opened = _open_authority_directory_at(
            parent_fd,
            target_name,
            label="terminal cleanup inventory target",
        )
        try:
            current_inventory = _terminal_cleanup_journal_inventory(target_fd)
        finally:
            os.close(target_fd)
        expected_inventory = set(journal_inventory)
        if (
            target_name == original_name
            and set(current_inventory) != expected_inventory
        ) or (
            target_name == tombstone_name
            and not set(current_inventory).issubset(expected_inventory)
        ):
            raise MutationJournalError(
                "terminal cleanup target contents do not match its receipt"
            )
    return _TerminalCleanupReceipt(
        parent_path=parent_path,
        parent_device=int(record["parent_device"]),
        parent_inode=int(record["parent_inode"]),
        receipt_name=receipt_name,
        receipt_payload=payload,
        transaction_id=transaction_id,
        original_name=original_name,
        tombstone_name=tombstone_name,
        journal_device=journal_identity[0],
        journal_inode=journal_identity[1],
        manifest={str(key): value for key, value in manifest.items()},
        writer_epoch_terminal_proof=writer_epoch_terminal_proof,
        registry_payload=registry_payload,
        proof_digests=proof_digests,
        journal_inventory=tuple(journal_inventory),
        target_name=target_name,
    )


def _terminal_cleanup_proof_digests(
    journal_fd: int,
    manifest: Mapping[str, object],
) -> dict[str, str | None]:
    """Bind the baseline Git views needed after journal content is removed."""

    required = {
        "git_entry": isinstance(manifest.get("git_entry"), dict)
        and cast(dict[object, object], manifest["git_entry"]).get("kind")
        == "file",
        "index_stage": bool(manifest.get("index_exists")),
        "index_flags_v": bool(manifest.get("index_exists")),
        "index_flags_f": bool(manifest.get("index_exists")),
    }
    digests: dict[str, str | None] = {}
    for name, present in required.items():
        if not present:
            try:
                os.stat(name, dir_fd=journal_fd, follow_symlinks=False)
            except FileNotFoundError:
                digests[name] = None
                continue
            raise MutationJournalError(
                f"terminal cleanup proof artifact is unexpectedly present: {name}"
            )
        digests[name] = _digest_bound_regular_entry(
            journal_fd,
            name,
            label=f"terminal cleanup proof artifact {name}",
            max_bytes=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_BYTES,
        )
    return digests


def _ensure_terminal_cleanup_receipt(
    journal: WorkspaceMutationJournal,
    parent_fd: int,
    parent_path: Path,
    entry_name: str,
    journal_fd: int,
    journal_metadata: os.stat_result,
) -> tuple[_TerminalCleanupReceipt, bool]:
    """Publish or re-open the durable authority preceding journal deletion."""

    receipt_name = _terminal_receipt_name(journal.transaction_id)
    try:
        existing, _metadata = _read_bound_regular_entry(
            parent_fd,
            receipt_name,
            label="terminal cleanup receipt",
            max_bytes=_TERMINAL_RECEIPT_MAX_BYTES,
        )
    except MutationJournalError:
        try:
            os.stat(receipt_name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            existing = None
        else:
            raise
    if existing is not None:
        receipt = _parse_terminal_cleanup_receipt(
            parent_fd,
            parent_path,
            receipt_name,
            existing,
        )
        if (
            receipt.transaction_id != journal.transaction_id
            or (receipt.journal_device, receipt.journal_inode)
            != (journal_metadata.st_dev, journal_metadata.st_ino)
            or entry_name
            not in {receipt.original_name, receipt.tombstone_name}
        ):
            raise MutationJournalError(
                "terminal cleanup receipt conflicts with journal authority"
            )
        return receipt, True
    manifest_payload, _manifest_metadata = _read_bound_regular_entry(
        journal_fd,
        _MANIFEST,
        label="terminal cleanup manifest",
        max_bytes=_MUTATION_JOURNAL_MAX_MANIFEST_BYTES,
    )
    registry_payload, _registry_metadata = _read_bound_regular_entry(
        journal_fd,
        "registry_marker",
        label="terminal cleanup registry-marker authority",
        max_bytes=_CONTROL_FILE_MAX_BYTES,
    )
    try:
        terminal_manifest = json.loads(manifest_payload)
    except (TypeError, ValueError, json.JSONDecodeError) as exc:
        raise MutationJournalError(
            "terminal cleanup manifest is malformed"
        ) from exc
    if not isinstance(terminal_manifest, dict):
        raise MutationJournalError("terminal cleanup manifest is malformed")
    if journal.state not in {"committed", "rolled_back"}:
        raise MutationJournalError(
            "terminal cleanup receipt requires a terminal journal"
        )
    tombstone_name = _terminal_tombstone_name(
        journal.transaction_id,
        secrets.token_hex(32),
    )
    record = {
        "schema": _TERMINAL_CLEANUP_SCHEMA,
        "transaction_id": journal.transaction_id,
        "original_name": entry_name,
        "tombstone_name": tombstone_name,
        "parent_device": os.fstat(parent_fd).st_dev,
        "parent_inode": os.fstat(parent_fd).st_ino,
        "journal_device": journal_metadata.st_dev,
        "journal_inode": journal_metadata.st_ino,
        "manifest_b64": base64.b64encode(manifest_payload).decode("ascii"),
        "manifest_sha256": hashlib.sha256(manifest_payload).hexdigest(),
        "registry_marker_b64": base64.b64encode(registry_payload).decode("ascii"),
        "registry_marker_sha256": hashlib.sha256(registry_payload).hexdigest(),
        "writer_epoch_terminal_proof": (
            _terminal_cleanup_writer_epoch_proof(
                cast(dict[str, object], terminal_manifest)
            ).to_record()
        ),
        "proof_digests": _terminal_cleanup_proof_digests(
            journal_fd,
            terminal_manifest,
        ),
        "journal_inventory": [
            list(item)
            for item in _terminal_cleanup_journal_inventory(journal_fd)
        ],
    }
    payload = json.dumps(
        record,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    if len(payload) > _TERMINAL_RECEIPT_MAX_BYTES:
        raise MutationJournalError("terminal cleanup receipt exceeds its ceiling")
    _publish_bound_regular_noreplace(
        parent_fd,
        receipt_name,
        payload,
        label="terminal cleanup receipt",
    )
    observed, _metadata = _read_bound_regular_entry(
        parent_fd,
        receipt_name,
        label="terminal cleanup receipt",
        max_bytes=_TERMINAL_RECEIPT_MAX_BYTES,
    )
    if observed != payload:
        raise MutationJournalError("terminal cleanup receipt changed after write")
    return (
        _parse_terminal_cleanup_receipt(
            parent_fd,
            parent_path,
            receipt_name,
            payload,
        ),
        False,
    )


def _fsync_terminal_parent_directory(
    directory_fd: int,
    *,
    label: str,
) -> None:
    """Durably order a directory transition where the platform supports it."""

    try:
        os.fsync(directory_fd)
    except OSError as exc:
        if exc.errno not in {errno.EINVAL, errno.ENOTSUP, errno.EROFS}:
            raise MutationJournalError(f"cannot fsync {label}: {exc}") from exc


def _remove_terminal_journal_with_receipt(
    journal: WorkspaceMutationJournal,
    *,
    parent_fd: int,
    parent_path: Path,
    entry_name: str,
    journal_fd: int,
    journal_metadata: os.stat_result,
    allow_missing_registry: bool,
) -> _TerminalCleanupReceipt:
    """Rename then clear one terminal journal under durable restart authority."""

    receipt, preexisting_receipt = _ensure_terminal_cleanup_receipt(
        journal,
        parent_fd,
        parent_path,
        entry_name,
        journal_fd,
        journal_metadata,
    )
    if receipt.target_name != entry_name:
        raise MutationJournalError(
            "terminal cleanup receipt does not bind the opened journal target"
        )
    journal._registry_authority_journal_dir = (
        parent_path / receipt.original_name
    )
    journal._logical_journal_identity = (
        receipt.journal_device,
        receipt.journal_inode,
    )
    journal._remove_registry_marker(
        allow_missing=allow_missing_registry or preexisting_receipt,
        expected_payload=receipt.registry_payload,
    )

    current = os.stat(entry_name, dir_fd=parent_fd, follow_symlinks=False)
    if (current.st_dev, current.st_ino) != (
        receipt.journal_device,
        receipt.journal_inode,
    ):
        raise MutationJournalError(
            "terminal cleanup journal changed before tombstone transition"
        )
    if entry_name == receipt.original_name:
        try:
            os.stat(
                receipt.tombstone_name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            pass
        else:
            raise MutationJournalError(
                "terminal cleanup tombstone destination already exists"
            )
        os.rename(
            receipt.original_name,
            receipt.tombstone_name,
            src_dir_fd=parent_fd,
            dst_dir_fd=parent_fd,
        )
        _fsync_terminal_parent_directory(
            parent_fd,
            label="terminal mutation journal parent after tombstone rename",
        )
        entry_name = receipt.tombstone_name
    elif entry_name != receipt.tombstone_name:
        raise MutationJournalError(
            "terminal cleanup target escaped its receipt namespace"
        )
    current = os.stat(entry_name, dir_fd=parent_fd, follow_symlinks=False)
    if (current.st_dev, current.st_ino) != (
        receipt.journal_device,
        receipt.journal_inode,
    ):
        raise MutationJournalError(
            "terminal cleanup tombstone changed before content removal"
        )
    _remove_bound_directory_tree(
        parent_fd,
        entry_name,
        journal_fd,
        current,
    )
    _fsync_terminal_parent_directory(
        parent_fd,
        label="terminal mutation journal parent after tombstone removal",
    )
    for controlled_name in (receipt.original_name, receipt.tombstone_name):
        try:
            os.stat(
                controlled_name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            continue
        raise MutationJournalError(
            "terminal cleanup controlled target remained after removal"
        )
    observed_receipt, _metadata = _read_bound_regular_entry(
        parent_fd,
        receipt.receipt_name,
        label="terminal cleanup receipt after journal removal",
        max_bytes=_TERMINAL_RECEIPT_MAX_BYTES,
    )
    if observed_receipt != receipt.receipt_payload:
        raise MutationJournalError(
            "terminal cleanup receipt changed during journal removal"
        )
    completed = _parse_terminal_cleanup_receipt(
        parent_fd,
        parent_path,
        receipt.receipt_name,
        observed_receipt,
    )
    if completed.target_name is not None:
        raise MutationJournalError(
            "terminal cleanup receipt retained a mutation target"
        )
    journal._discovery_binding = None
    return completed


def _terminal_cleanup_receipt_at(
    parent_fd: int,
    parent_path: Path,
    transaction_id: str,
) -> _TerminalCleanupReceipt | None:
    """Read one transaction receipt exactly, returning ``None`` if absent."""

    receipt_name = _terminal_receipt_name(transaction_id)
    try:
        payload, _metadata = _read_bound_regular_entry(
            parent_fd,
            receipt_name,
            label="terminal cleanup receipt",
            max_bytes=_TERMINAL_RECEIPT_MAX_BYTES,
        )
    except MutationJournalError:
        try:
            os.stat(receipt_name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            return None
        raise
    return _parse_terminal_cleanup_receipt(
        parent_fd,
        parent_path,
        receipt_name,
        payload,
    )


def _read_discovered_terminal_cleanup_receipt(
    parent_fd: int,
    receipt: _TerminalCleanupReceipt,
) -> _TerminalCleanupReceipt:
    payload, _metadata = _read_bound_regular_entry(
        parent_fd,
        receipt.receipt_name,
        label="discovered terminal cleanup receipt",
        max_bytes=_TERMINAL_RECEIPT_MAX_BYTES,
    )
    observed = _parse_terminal_cleanup_receipt(
        parent_fd,
        receipt.parent_path,
        receipt.receipt_name,
        payload,
        canonical_receipt_name=_terminal_receipt_name(receipt.transaction_id),
    )
    if payload != receipt.receipt_payload:
        raise MutationJournalError(
            "terminal cleanup receipt changed after discovery"
        )
    return observed


def _remove_completed_terminal_cleanup_receipt(
    parent_fd: int,
    receipt: _TerminalCleanupReceipt,
) -> None:
    """Remove the exact targetless receipt as the final durable frontier."""

    observed = _read_discovered_terminal_cleanup_receipt(parent_fd, receipt)
    if observed.target_name is not None:
        raise MutationJournalError(
            "cannot remove terminal cleanup receipt while its target remains"
        )
    payload, metadata = _read_bound_regular_entry(
        parent_fd,
        observed.receipt_name,
        label="completed terminal cleanup receipt",
        max_bytes=_TERMINAL_RECEIPT_MAX_BYTES,
    )
    prefix = (
        f"{_TERMINAL_RECEIPT_CLEANUP_PREFIX}{receipt.transaction_id}-"
    )
    _remove_bound_regular_entry(
        parent_fd,
        observed.receipt_name,
        label="completed terminal cleanup receipt",
        expected_metadata=metadata,
        expected_payload=payload,
        quarantine_prefix=prefix,
    )
    for name in _bounded_directory_names(
        parent_fd,
        label="terminal cleanup receipt parent",
        max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
    ):
        if not name.startswith(prefix):
            continue
        reservation_payload, reservation_metadata = _read_bound_regular_entry(
            parent_fd,
            name,
            label="terminal receipt cleanup reservation",
            max_bytes=_TERMINAL_RECEIPT_MAX_BYTES,
        )
        if reservation_payload:
            raise MutationJournalError(
                "terminal receipt cleanup retained duplicate authority"
            )
        _remove_bound_regular_entry(
            parent_fd,
            name,
            label="terminal receipt cleanup reservation",
            expected_metadata=reservation_metadata,
            expected_payload=b"",
            quarantine_prefix=prefix,
        )
    _fsync_terminal_parent_directory(
        parent_fd,
        label="terminal cleanup receipt parent after receipt removal",
    )
    for name in _bounded_directory_names(
        parent_fd,
        label="terminal cleanup receipt parent",
        max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
    ):
        if name == _terminal_receipt_name(receipt.transaction_id) or (
            name.startswith(prefix)
        ):
            raise MutationJournalError(
                "terminal cleanup receipt authority remained after removal"
            )


def _cleanup_terminal_mutation_journal(
    journal: WorkspaceMutationJournal,
    *,
    allow_missing_registry: bool = True,
) -> None:
    """Remove a terminal journal through its retained parent authority."""

    if journal.active:
        raise MutationJournalError(
            "cannot clean a non-terminal mutation journal"
        )
    journal._require_writer_epoch_quiescence(
        frontier="terminal journal cleanup"
    )
    journal._persist_writer_epoch_terminal_proof()
    logical_dir = journal._logical_journal_dir
    if _active_workspace_mutation_authority(
        Path(journal._manifest["cwd"])
    ) is None:
        with workspace_mutation_lock(Path(journal._manifest["cwd"])):
            return _cleanup_terminal_mutation_journal(
                journal,
                allow_missing_registry=allow_missing_registry,
            )
    if journal._discovery_binding is None:
        parent_fd, parent_opened = _open_authority_directory(
            logical_dir.parent,
            label="terminal mutation journal parent",
        )
        journal_fd: int | None = None
        try:
            if (
                journal._logical_journal_parent_identity is None
                or (parent_opened.st_dev, parent_opened.st_ino)
                != journal._logical_journal_parent_identity
            ):
                raise MutationJournalError(
                    "terminal mutation journal parent changed since creation"
                )
            receipt = _terminal_cleanup_receipt_at(
                parent_fd,
                logical_dir.parent,
                journal.transaction_id,
            )
            identity_matches: list[tuple[str, os.stat_result]] = []
            for candidate in _bounded_directory_names(
                parent_fd,
                label="terminal mutation journal parent",
                max_entries=_MUTATION_JOURNAL_MAX_DISCOVERY_ARTIFACT_PATHS,
            ):
                metadata = os.stat(
                    candidate,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
                if (
                    journal._logical_journal_identity is not None
                    and (metadata.st_dev, metadata.st_ino)
                    == journal._logical_journal_identity
                ):
                    authorized_names = (
                        {logical_dir.name}
                        if receipt is None
                        else {
                            receipt.original_name,
                            receipt.tombstone_name,
                        }
                    )
                    if candidate not in authorized_names:
                        raise MutationJournalError(
                            "terminal mutation journal moved outside its "
                            "receipt namespace"
                        )
                    identity_matches.append((candidate, metadata))
            if len(identity_matches) > 1:
                raise MutationJournalError(
                    "terminal mutation journal identity is duplicated"
                )
            if receipt is not None:
                if (
                    journal._logical_journal_identity is None
                    or (
                        receipt.journal_device,
                        receipt.journal_inode,
                    ) != journal._logical_journal_identity
                ):
                    raise MutationJournalError(
                        "terminal cleanup receipt conflicts with retained "
                        "journal identity"
                    )
                expected_targets = (
                    []
                    if receipt.target_name is None
                    else [receipt.target_name]
                )
                if [name for name, _metadata in identity_matches] != expected_targets:
                    raise MutationJournalError(
                        "terminal cleanup receipt target inventory changed"
                    )
            if identity_matches:
                entry_name, expected_entry = identity_matches[0]
                journal_fd, journal_opened = _open_authority_directory_at(
                    parent_fd,
                    entry_name,
                    label="terminal mutation journal",
                )
                if (
                    journal._logical_journal_identity is None
                    or (journal_opened.st_dev, journal_opened.st_ino)
                    != journal._logical_journal_identity
                ):
                    raise MutationJournalError(
                        "terminal mutation journal changed since creation"
                    )
                completed_receipt = _remove_terminal_journal_with_receipt(
                    journal,
                    parent_fd=parent_fd,
                    parent_path=logical_dir.parent,
                    entry_name=entry_name,
                    journal_fd=journal_fd,
                    journal_metadata=expected_entry,
                    allow_missing_registry=allow_missing_registry,
                )
                _remove_completed_terminal_cleanup_receipt(
                    parent_fd,
                    completed_receipt,
                )
            elif receipt is not None and receipt.target_name is None:
                journal._registry_authority_journal_dir = (
                    logical_dir.parent / receipt.original_name
                )
                journal._remove_registry_marker(
                    allow_missing=True,
                    expected_payload=receipt.registry_payload,
                )
                _remove_completed_terminal_cleanup_receipt(
                    parent_fd,
                    receipt,
                )
            elif journal.cleanup_pending:
                raise MutationJournalError(
                    "terminal mutation journal identity disappeared while "
                    "cleanup authority remains"
                )
            _assert_authority_directory_binding(
                logical_dir.parent,
                parent_fd,
                parent_opened,
                label="terminal mutation journal parent",
            )
        finally:
            if journal_fd is not None:
                os.close(journal_fd)
            os.close(parent_fd)
        if journal.cleanup_pending:
            raise MutationJournalError(
                "terminal mutation journal cleanup remains pending"
            )
        _unregister_terminal_live(journal.transaction_id)
        return
    with _bound_mutation_journal_directory(journal) as (
        _artifact_dir,
        journal_fd,
        parent_fd,
        entry_name,
    ):
        _revalidate_discovery_directory_entry(
            parent_fd,
            entry_name,
            journal_fd,
            os.fstat(journal_fd),
            label="bound terminal mutation journal",
        )
        completed_receipt = _remove_terminal_journal_with_receipt(
            journal,
            parent_fd=parent_fd,
            # ``journal.journal_dir`` is temporarily the descriptor alias
            # yielded by ``_bound_mutation_journal_directory`` while a
            # discovered journal is being recovered.  Durable registry and
            # receipt authority is bound to the retained logical Corpus path,
            # never to process-local ``/proc/self/fd`` spelling.
            parent_path=logical_dir.parent,
            entry_name=entry_name,
            journal_fd=journal_fd,
            journal_metadata=os.fstat(journal_fd),
            allow_missing_registry=allow_missing_registry,
        )
        _remove_completed_terminal_cleanup_receipt(
            parent_fd,
            completed_receipt,
        )
    if journal.cleanup_pending:
        raise MutationJournalError(
            "bound terminal mutation journal cleanup remains pending"
        )
    _unregister_terminal_live(journal.transaction_id)


def _discovery_directory_entry(
    parent_fd: int,
    name: str,
    *,
    label: str,
) -> tuple[int, os.stat_result]:
    """Open one inventory directory without following a replaceable alias."""

    return _open_authority_directory_at(parent_fd, name, label=label)


def _revalidate_discovery_directory_entry(
    parent_fd: int,
    name: str,
    descriptor: int,
    expected: os.stat_result,
    *,
    label: str,
) -> None:
    try:
        held = os.fstat(descriptor)
        current = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except OSError as exc:
        raise MutationJournalError(
            f"cannot revalidate {label}: {exc}"
        ) from exc
    if (
        not stat.S_ISDIR(held.st_mode)
        or not stat.S_ISDIR(current.st_mode)
        or stat.S_ISLNK(current.st_mode)
        or (held.st_dev, held.st_ino) != (expected.st_dev, expected.st_ino)
        or (current.st_dev, current.st_ino)
        != (expected.st_dev, expected.st_ino)
    ):
        raise MutationJournalError(f"{label} changed identity")


def _load_mutation_journal_manifest_at(
    directory_fd: int,
    journal_dir: Path,
    *,
    budget: "_MutationJournalDiscoveryBudget | None" = None,
) -> dict:
    """Read one stable, regular, bounded manifest through its directory fd."""

    descriptor: int | None = None
    try:
        before = os.stat(
            _MANIFEST,
            dir_fd=directory_fd,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISREG(before.st_mode)
            or stat.S_ISLNK(before.st_mode)
            or before.st_nlink != 1
            or before.st_size > _MUTATION_JOURNAL_MAX_MANIFEST_BYTES
        ):
            raise MutationJournalError(
                f"mutation journal manifest is unsafe: {journal_dir / _MANIFEST}"
            )
        if budget is not None:
            budget.charge_manifest(before.st_size)
        descriptor = os.open(
            _MANIFEST,
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_NONBLOCK", 0),
            dir_fd=directory_fd,
        )
        opened = os.fstat(descriptor)
        if (
            not stat.S_ISREG(opened.st_mode)
            or opened.st_nlink != 1
            or (opened.st_dev, opened.st_ino) != (before.st_dev, before.st_ino)
        ):
            raise MutationJournalError(
                f"mutation journal manifest changed while opening: "
                f"{journal_dir / _MANIFEST}"
            )
        payload = bytearray()
        while True:
            chunk = os.read(descriptor, 1024 * 1024)
            if not chunk:
                break
            if len(payload) + len(chunk) > _MUTATION_JOURNAL_MAX_MANIFEST_BYTES:
                raise MutationJournalError(
                    "mutation journal manifest exceeds its byte ceiling: "
                    f"{journal_dir / _MANIFEST}"
                )
            payload.extend(chunk)
        finished = os.fstat(descriptor)
        after = os.stat(
            _MANIFEST,
            dir_fd=directory_fd,
            follow_symlinks=False,
        )
        if any(
            getattr(opened, field) != getattr(finished, field)
            or getattr(opened, field) != getattr(after, field)
            for field in _SETTLEMENT_STABLE_STAT_FIELDS
        ):
            raise MutationJournalError(
                f"mutation journal manifest changed during read: "
                f"{journal_dir / _MANIFEST}"
            )
        manifest = json.loads(bytes(payload))
    except MutationJournalError:
        raise
    except (OSError, UnicodeError, ValueError, TypeError) as exc:
        raise MutationJournalError(
            f"mutation journal manifest is unreadable: "
            f"{journal_dir / _MANIFEST}: {exc}"
        ) from exc
    finally:
        if descriptor is not None:
            os.close(descriptor)
    if not isinstance(manifest, dict) or manifest.get("schema") != _SCHEMA:
        raise MutationJournalError(
            f"unsupported mutation journal schema at {journal_dir}"
        )
    return manifest


@dataclass
class _MutationJournalDiscoveryBudget:
    manifest_bytes: int = 0
    path_bytes: int = 0

    def charge_manifest(self, size: int) -> None:
        self.manifest_bytes += size
        if (
            self.manifest_bytes
            > _MUTATION_JOURNAL_MAX_DISCOVERY_MANIFEST_BYTES
        ):
            raise MutationJournalError(
                "mutation journal inventory exceeds its aggregate manifest "
                "byte ceiling"
            )

    def charge_path(self, value: str | Path) -> None:
        self.path_bytes += len(os.fsencode(os.fspath(value)))
        if self.path_bytes > _MUTATION_JOURNAL_MAX_DISCOVERY_PATH_BYTES:
            raise MutationJournalError(
                "mutation journal inventory exceeds its aggregate path byte "
                "ceiling"
            )


def discover_mutation_journals(
    corpus: "Corpus",
    *,
    run_id: str | None = None,
    workspace: str | Path | None = None,
    _terminal_receipts: list[_TerminalCleanupReceipt] | None = None,
) -> tuple[WorkspaceMutationJournal, ...]:
    """Return one bounded, no-follow snapshot of every durable journal.

    This is the sole inventory authority for recovery, settlement attestation,
    Architect retained-prefix decisions, and operator recovery. Any alias,
    special file, duplicate transaction, or concurrent topology change aborts
    the whole snapshot before a caller may mutate source or journal state.
    """

    spec_dir = _lexical_workspace_path(corpus.spec_dir)
    spec_fd, spec_metadata = _open_authority_directory(
        spec_dir,
        label="Corpus Spec directory",
    )
    runs_fd: int | None = None
    journals: list[WorkspaceMutationJournal] = []
    transaction_ids: dict[str, Path] = {}
    journal_inodes: dict[tuple[int, int], Path] = {}
    terminal_receipts: list[_TerminalCleanupReceipt] = []
    terminal_receipt_paths: dict[str, Path] = {}
    selected_run_ids: dict[Path, str] = {}
    budget = _MutationJournalDiscoveryBudget()
    artifact_budget = _MutationJournalArtifactBudget()

    def add_journal(
        *,
        journal_fd: int,
        journal_path: Path,
        opened: os.stat_result,
        physical_parent_id: str | None,
        depth: int,
    ) -> WorkspaceMutationJournal:
        if depth > _MUTATION_JOURNAL_MAX_DISCOVERY_DEPTH:
            raise MutationJournalError(
                "mutation journal family exceeds its discovery depth ceiling"
            )
        if len(journals) >= _MUTATION_JOURNAL_MAX_DISCOVERED_MEMBERS:
            raise MutationJournalError(
                "mutation journal inventory exceeds its aggregate member ceiling"
            )
        inode = (opened.st_dev, opened.st_ino)
        previous_path = journal_inodes.get(inode)
        if previous_path is not None:
            raise MutationJournalError(
                "mutation journal directory has multiple inventory paths: "
                f"{previous_path}, {journal_path}"
            )
        budget.charge_path(journal_path)
        manifest = _load_mutation_journal_manifest_at(
            journal_fd,
            journal_path,
            budget=budget,
        )
        required_shape = {
            "transaction_id": str,
            "created_ns": int,
            "slice_id": str,
            "state": str,
            "cwd": str,
            "registry_directory": str,
            "registry_directory_mode": int,
            "registry_directory_device": int,
            "registry_directory_inode": int,
            "registry_marker": str,
        }
        malformed_fields = [
            field
            for field, expected_type in required_shape.items()
            if not isinstance(manifest.get(field), expected_type)
            or (
                expected_type is int
                and isinstance(manifest.get(field), bool)
            )
        ]
        parent_id = manifest.get("parent_transaction_id")
        if parent_id is not None and not isinstance(parent_id, str):
            malformed_fields.append("parent_transaction_id")
        family = manifest.get("registry_transaction_family", ())
        family_parents = manifest.get("registry_family_parents", {})
        if (
            not isinstance(family, (list, tuple))
            or not all(isinstance(item, str) for item in family)
        ):
            malformed_fields.append("registry_transaction_family")
        if not isinstance(family_parents, dict) or not all(
            isinstance(key, str)
            and (value is None or isinstance(value, str))
            for key, value in family_parents.items()
        ):
            malformed_fields.append("registry_family_parents")
        if malformed_fields:
            raise MutationJournalError(
                "mutation journal manifest has malformed authority fields at "
                f"{journal_path}: {sorted(set(malformed_fields))!r}"
            )
        journal = WorkspaceMutationJournal(journal_path, manifest)
        transaction_id = journal.transaction_id
        if not re.fullmatch(r"[0-9a-f]{32}", transaction_id):
            raise MutationJournalError(
                f"mutation journal has malformed transaction id at {journal_path}"
            )
        previous_transaction = transaction_ids.get(transaction_id)
        if previous_transaction is not None:
            raise MutationJournalError(
                "duplicate mutation transaction id in durable inventory: "
                f"{transaction_id} at {previous_transaction} and {journal_path}"
            )
        receipt_path = terminal_receipt_paths.get(transaction_id)
        if receipt_path is not None:
            raise MutationJournalError(
                "mutation transaction has both live journal and terminal "
                f"cleanup receipt: {transaction_id} at {journal_path} and "
                f"{receipt_path}"
            )
        if (
            physical_parent_id is not None
            and journal.parent_transaction_id != physical_parent_id
        ):
            raise MutationJournalError(
                "nested mutation journal parent edge changed: "
                f"{transaction_id}"
            )
        journal_inodes[inode] = journal_path
        transaction_ids[transaction_id] = journal_path
        journals.append(journal)
        scan_nested(journal_fd, journal, depth=depth)
        return journal

    def scan_journal_container(
        *,
        container_fd: int,
        container_path: Path,
        physical_parent_id: str | None,
        depth: int,
        member_ceiling: int,
    ) -> None:
        opened_container = os.fstat(container_fd)
        initial_names = _bounded_directory_names(
            container_fd,
            label=f"mutation journal container {container_path}",
            max_entries=member_ceiling,
        )
        for name in initial_names:
            budget.charge_path(name)
        receipts_by_name: dict[str, _TerminalCleanupReceipt] = {}
        controlled_names: dict[str, _TerminalCleanupReceipt] = {}
        receipt_reservations: dict[str, str] = {}
        for name in initial_names:
            receipt_match = re.fullmatch(
                re.escape(_TERMINAL_RECEIPT_PREFIX)
                + r"([0-9a-f]{32})\.json",
                name,
            )
            cleanup_match = re.fullmatch(
                re.escape(_TERMINAL_RECEIPT_CLEANUP_PREFIX)
                + r"([0-9a-f]{32})-([0-9a-f]{64})",
                name,
            )
            if receipt_match is None and cleanup_match is None:
                if name.startswith(_TERMINAL_RECEIPT_PREFIX):
                    raise MutationJournalError(
                        "malformed terminal cleanup receipt name in "
                        f"{container_path}: {name!r}"
                    )
                if name.startswith(_TERMINAL_RECEIPT_CLEANUP_PREFIX):
                    raise MutationJournalError(
                        "malformed terminal receipt cleanup name in "
                        f"{container_path}: {name!r}"
                    )
                continue
            payload, _metadata = _read_bound_regular_entry(
                container_fd,
                name,
                label=f"terminal cleanup receipt {container_path / name}",
                max_bytes=_TERMINAL_RECEIPT_MAX_BYTES,
            )
            if cleanup_match is not None and not payload:
                receipt_reservations[name] = cleanup_match.group(1)
                continue
            if receipt_match is not None:
                transaction_id = receipt_match.group(1)
            else:
                assert cleanup_match is not None
                transaction_id = cleanup_match.group(1)
            receipt = _parse_terminal_cleanup_receipt(
                container_fd,
                container_path,
                name,
                payload,
                canonical_receipt_name=(
                    None
                    if receipt_match is not None
                    else _terminal_receipt_name(transaction_id)
                ),
            )
            if (
                physical_parent_id is not None
                and receipt.manifest.get("parent_transaction_id")
                != physical_parent_id
            ):
                raise MutationJournalError(
                    "nested terminal cleanup receipt parent edge changed: "
                    f"{receipt.transaction_id}"
                )
            previous_receipt = terminal_receipt_paths.get(
                receipt.transaction_id
            )
            if previous_receipt is not None:
                raise MutationJournalError(
                    "duplicate terminal cleanup transaction receipt: "
                    f"{receipt.transaction_id} at {previous_receipt} and "
                    f"{container_path / name}"
                )
            live_path = transaction_ids.get(receipt.transaction_id)
            if live_path is not None:
                raise MutationJournalError(
                    "mutation transaction has both live journal and terminal "
                    f"cleanup receipt: {receipt.transaction_id} at "
                    f"{live_path} and {container_path / name}"
                )
            terminal_receipt_paths[receipt.transaction_id] = (
                container_path / name
            )
            terminal_receipts.append(receipt)
            receipts_by_name[name] = receipt
            for controlled_name in (
                receipt.original_name,
                receipt.tombstone_name,
            ):
                if controlled_name in controlled_names:
                    raise MutationJournalError(
                        "terminal cleanup receipts claim the same journal "
                        f"name: {controlled_name!r}"
                    )
                controlled_names[controlled_name] = receipt
        for reservation_name, transaction_id in receipt_reservations.items():
            if transaction_id not in {
                receipt.transaction_id
                for receipt in receipts_by_name.values()
            }:
                raise MutationJournalError(
                    "terminal receipt cleanup reservation lacks its receipt: "
                    f"{container_path / reservation_name}"
                )
        for name in initial_names:
            if name in receipts_by_name or name in receipt_reservations:
                continue
            controlling_receipt = controlled_names.get(name)
            if controlling_receipt is not None:
                if controlling_receipt.target_name != name:
                    raise MutationJournalError(
                        "terminal cleanup controlled name appeared outside "
                        "its receipt target"
                    )
                continue
            if name.startswith(_TERMINAL_TOMBSTONE_PREFIX):
                raise MutationJournalError(
                    "terminal cleanup tombstone lacks a valid receipt: "
                    f"{container_path / name}"
                )
            child_fd: int | None = None
            try:
                child_fd, child_opened = _discovery_directory_entry(
                    container_fd,
                    name,
                    label=f"mutation journal directory {container_path / name}",
                )
                add_journal(
                    journal_fd=child_fd,
                    journal_path=container_path / name,
                    opened=child_opened,
                    physical_parent_id=physical_parent_id,
                    depth=depth,
                )
                _revalidate_discovery_directory_entry(
                    container_fd,
                    name,
                    child_fd,
                    child_opened,
                    label=f"mutation journal directory {container_path / name}",
                )
            finally:
                if child_fd is not None:
                    os.close(child_fd)
        final_names = _bounded_directory_names(
            container_fd,
            label=f"mutation journal container {container_path}",
            max_entries=member_ceiling,
        )
        finished_container = os.fstat(container_fd)
        if initial_names != final_names or (
            opened_container.st_dev,
            opened_container.st_ino,
        ) != (
            finished_container.st_dev,
            finished_container.st_ino,
        ):
            raise MutationJournalError(
                f"mutation journal container changed during discovery: "
                f"{container_path}"
            )

    def scan_nested(
        journal_fd: int,
        journal: WorkspaceMutationJournal,
        *,
        depth: int,
    ) -> None:
        nested_fd: int | None = None
        try:
            try:
                os.stat(
                    "nested_mutations",
                    dir_fd=journal_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                return
            nested_fd, nested_opened = _discovery_directory_entry(
                journal_fd,
                "nested_mutations",
                label=(
                    "nested mutation journal root "
                    f"{journal.journal_dir / 'nested_mutations'}"
                ),
            )
            scan_journal_container(
                container_fd=nested_fd,
                container_path=journal.journal_dir / "nested_mutations",
                physical_parent_id=journal.transaction_id,
                depth=depth + 1,
                member_ceiling=_MUTATION_JOURNAL_MAX_NESTED_MEMBERS,
            )
            _revalidate_discovery_directory_entry(
                journal_fd,
                "nested_mutations",
                nested_fd,
                nested_opened,
                label=(
                    "nested mutation journal root "
                    f"{journal.journal_dir / 'nested_mutations'}"
                ),
            )
        finally:
            if nested_fd is not None:
                os.close(nested_fd)

    try:
        try:
            os.stat("runs", dir_fd=spec_fd, follow_symlinks=False)
        except FileNotFoundError:
            return ()
        runs_fd, runs_opened = _discovery_directory_entry(
            spec_fd,
            "runs",
            label=f"Corpus runs directory {spec_dir / 'runs'}",
        )
        initial_run_names = _bounded_directory_names(
            runs_fd,
            label="Corpus runs directory",
            max_entries=_MUTATION_JOURNAL_MAX_RUNS,
        )
        for name in initial_run_names:
            budget.charge_path(name)
        for name in initial_run_names:
            current_run_fd: int | None = None
            try:
                current_run_fd, current_run_opened = (
                    _discovery_directory_entry(
                        runs_fd,
                        name,
                        label=f"Corpus run directory {name!r}",
                    )
                )
                current_run_path = spec_dir / "runs" / name
                selected_run_ids[current_run_path] = name
                for journal_root in _DURABLE_JOURNAL_ROOTS:
                    journal_root_fd: int | None = None
                    try:
                        try:
                            os.stat(
                                journal_root,
                                dir_fd=current_run_fd,
                                follow_symlinks=False,
                            )
                        except FileNotFoundError:
                            continue
                        journal_root_fd, journal_root_opened = (
                            _discovery_directory_entry(
                                current_run_fd,
                                journal_root,
                                label=(
                                    "durable mutation journal root "
                                    f"{current_run_path / journal_root}"
                                ),
                            )
                        )
                        scan_journal_container(
                            container_fd=journal_root_fd,
                            container_path=current_run_path / journal_root,
                            physical_parent_id=None,
                            depth=0,
                            member_ceiling=(
                                _MUTATION_JOURNAL_MAX_NESTED_MEMBERS
                            ),
                        )
                        _revalidate_discovery_directory_entry(
                            current_run_fd,
                            journal_root,
                            journal_root_fd,
                            journal_root_opened,
                            label=(
                                "durable mutation journal root "
                                f"{current_run_path / journal_root}"
                            ),
                        )
                    finally:
                        if journal_root_fd is not None:
                            os.close(journal_root_fd)
                _revalidate_discovery_directory_entry(
                    runs_fd,
                    name,
                    current_run_fd,
                    current_run_opened,
                    label=f"Corpus run directory {name!r}",
                )
            finally:
                if current_run_fd is not None:
                    os.close(current_run_fd)
        final_run_names = _bounded_directory_names(
            runs_fd,
            label="Corpus runs directory",
            max_entries=_MUTATION_JOURNAL_MAX_RUNS,
        )
        if initial_run_names != final_run_names:
            raise MutationJournalError(
                "Corpus runs directory changed during journal discovery"
            )
        _revalidate_discovery_directory_entry(
            spec_fd,
            "runs",
            runs_fd,
            runs_opened,
            label=f"Corpus runs directory {spec_dir / 'runs'}",
        )
        _assert_authority_directory_binding(
            spec_dir,
            spec_fd,
            spec_metadata,
            label="Corpus Spec directory",
        )
    finally:
        if runs_fd is not None:
            os.close(runs_fd)
        os.close(spec_fd)

    def journal_run_id(journal: WorkspaceMutationJournal) -> str:
        try:
            return journal.journal_dir.relative_to(
                spec_dir / "runs"
            ).parts[0]
        except (IndexError, ValueError) as exc:
            raise MutationJournalError(
                "discovered mutation journal lost its run binding"
            ) from exc

    if run_id is not None:
        if run_id not in selected_run_ids.values():
            raise MutationJournalError(f"unknown mutation run {run_id!r}")
        journals = [
            journal
            for journal in journals
            if journal_run_id(journal) == run_id
        ]
    if workspace is not None:
        requested_workspace = _lexical_workspace_path(workspace)
        related_ids = {
            journal.transaction_id
            for journal in journals
            if _lexical_workspace_path(journal._manifest["cwd"])
            == requested_workspace
        }
        changed = True
        while changed:
            changed = False
            for journal in journals:
                family = {
                    str(transaction_id)
                    for transaction_id in journal._manifest.get(
                        "registry_transaction_family",
                        (),
                    )
                }
                if related_ids.intersection(family) and not family.issubset(
                    related_ids
                ):
                    related_ids.update(family)
                    changed = True
        journals = [
            journal
            for journal in journals
            if journal.transaction_id in related_ids
            or bool(related_ids.intersection(
                str(transaction_id)
                for transaction_id in journal._manifest.get(
                    "registry_transaction_family",
                    (),
                )
            ))
        ]
    selected_terminal_receipts = terminal_receipts
    if run_id is not None:
        selected_terminal_receipts = [
            receipt
            for receipt in selected_terminal_receipts
            if receipt.parent_path.relative_to(spec_dir / "runs").parts[0]
            == run_id
        ]
    if workspace is not None:
        requested_workspace = _lexical_workspace_path(workspace)
        selected_terminal_receipts = [
            receipt
            for receipt in selected_terminal_receipts
            if _lexical_workspace_path(str(receipt.manifest.get("cwd", "")))
            == requested_workspace
        ]
    if _terminal_receipts is not None:
        _terminal_receipts.extend(sorted(
            selected_terminal_receipts,
            key=lambda item: (
                str(item.parent_path),
                item.transaction_id,
            ),
        ))
    for journal in journals:
        _bind_discovered_mutation_journal(
            journal,
            spec_dir,
            artifact_budget=artifact_budget,
        )
    return tuple(sorted(
        journals,
        key=lambda item: (
            str(item.journal_dir),
            item.created_ns,
            item.transaction_id,
        ),
    ))


def read_corpus_run_control_bounded(
    corpus: "Corpus",
    *,
    run_id: str,
    name: str,
    max_bytes: int = _MUTATION_JOURNAL_MAX_RUN_CONTROL_BYTES,
) -> bytes:
    """Read one stable regular run control through a no-follow run binding."""

    if (
        run_id in {"", ".", ".."}
        or "/" in run_id
        or name in {"", ".", ".."}
        or "/" in name
        or max_bytes < 0
        or max_bytes > _MUTATION_JOURNAL_MAX_RUN_CONTROL_BYTES
    ):
        raise MutationJournalError("invalid bounded run-control request")
    spec_dir = _lexical_workspace_path(corpus.spec_dir)
    descriptors: list[int] = []
    control_fd: int | None = None
    try:
        spec_fd, _spec_opened = _open_authority_directory(
            spec_dir,
            label="Corpus Spec directory",
        )
        descriptors.append(spec_fd)
        runs_fd, _runs_opened = _discovery_directory_entry(
            spec_fd,
            "runs",
            label="Corpus runs directory",
        )
        descriptors.append(runs_fd)
        run_fd, _run_opened = _discovery_directory_entry(
            runs_fd,
            run_id,
            label=f"Corpus run directory {run_id!r}",
        )
        descriptors.append(run_fd)
        before = os.stat(name, dir_fd=run_fd, follow_symlinks=False)
        if (
            not stat.S_ISREG(before.st_mode)
            or stat.S_ISLNK(before.st_mode)
            or before.st_nlink != 1
            or before.st_size > max_bytes
        ):
            raise MutationJournalError(
                f"run control {name!r} is unsafe or exceeds its byte ceiling"
            )
        control_fd = os.open(
            name,
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_NONBLOCK", 0),
            dir_fd=run_fd,
        )
        opened = os.fstat(control_fd)
        if (
            not stat.S_ISREG(opened.st_mode)
            or opened.st_nlink != 1
            or (opened.st_dev, opened.st_ino) != (before.st_dev, before.st_ino)
        ):
            raise MutationJournalError(
                f"run control {name!r} changed while opening"
            )
        payload = bytearray()
        while True:
            chunk = os.read(control_fd, min(1024 * 1024, max_bytes + 1))
            if not chunk:
                break
            if len(payload) + len(chunk) > max_bytes:
                raise MutationJournalError(
                    f"run control {name!r} exceeds its byte ceiling"
                )
            payload.extend(chunk)
        finished = os.fstat(control_fd)
        after = os.stat(name, dir_fd=run_fd, follow_symlinks=False)
        if any(
            getattr(opened, field) != getattr(finished, field)
            or getattr(opened, field) != getattr(after, field)
            for field in _SETTLEMENT_STABLE_STAT_FIELDS
        ):
            raise MutationJournalError(
                f"run control {name!r} changed during read"
            )
        return bytes(payload)
    except MutationJournalError:
        raise
    except OSError as exc:
        raise MutationJournalError(
            f"cannot read bounded run control {name!r}: {exc}"
        ) from exc
    finally:
        if control_fd is not None:
            os.close(control_fd)
        for descriptor in reversed(descriptors):
            os.close(descriptor)


@contextmanager
def _lifecycle_family_workspace_locks(
    journals: Iterable[WorkspaceMutationJournal],
) -> Iterator[None]:
    """Hold every distinct family root authority through proof and commit."""

    selected = tuple(journals)
    by_root: dict[Path, list[WorkspaceMutationJournal]] = {}
    keyed_roots: list[
        tuple[tuple[int, int, int, int], Path, Mapping[str, object]]
    ] = []
    signatures: dict[Path, tuple[object, ...]] = {}
    for journal in selected:
        root = _lexical_workspace_path(journal._manifest["cwd"])
        expected = journal._manifest.get("authority_lock")
        if not isinstance(expected, Mapping):
            raise MutationJournalError(
                "lifecycle family member lacks captured lock authority"
            )
        common_key = _validated_external_identity(
            expected.get("common_device"),
            expected.get("common_inode"),
            label="lifecycle family common",
        )
        root_key = _validated_external_identity(
            expected.get("root_device"),
            expected.get("root_inode"),
            label="lifecycle family root",
        )
        signature = (
            expected.get("common_dir"),
            *common_key,
            *root_key,
            expected.get("root_mode"),
        )
        previous = signatures.setdefault(root, signature)
        if previous != signature:
            raise MutationJournalError(
                "lifecycle family members disagree on root authority"
            )
        if root not in by_root:
            keyed_roots.append(((*common_key, *root_key), root, expected))
        by_root.setdefault(root, []).append(journal)

    lock_components = {order[:2] for order, _root, _expected in keyed_roots}
    if len(lock_components) != 1:
        raise MutationJournalError(
            "lifecycle settlement family spans independent mutation-lock "
            "components"
        )
    ordered_roots = sorted(keyed_roots, key=lambda item: item[0])
    with ExitStack() as stack:
        prepared_roots: list[
            tuple[WorkspaceMutationJournal, _PreparedWorkspaceRootAccess | None]
        ] = []
        try:
            for _order, root, expected in ordered_roots:
                representative = by_root[root][0]
                if _active_external_workspace_coordination(root) is None:
                    stack.enter_context(_external_workspace_coordination(
                        root,
                        captured_authority=expected,
                    ))
                for journal in by_root[root]:
                    journal._require_writer_epoch_quiescence(
                        frontier="lifecycle family workspace admission"
                    )
                prepared = representative._prepare_workspace_root_access()
                prepared_roots.append((representative, prepared))
                representative._assert_external_common_authority()
                stack.enter_context(workspace_mutation_lock(root))
            yield
        finally:
            for journal, prepared in reversed(prepared_roots):
                journal._settle_prepared_workspace_root_access(prepared)


def _commit_prevalidated_lifecycle_family(
    journals: Iterable[WorkspaceMutationJournal],
) -> None:
    """Durably mark a whole exact family before removing any member journal."""

    selected = tuple(journals)
    if not selected:
        raise MutationJournalError(
            "cannot finalize an empty lifecycle settlement family"
        )
    selected_ids = {journal.transaction_id for journal in selected}
    settlement_refs = {
        (journal._manifest.get("expected_lifecycle") or {}).get(
            "settlement_ref"
        )
        for journal in selected
    }
    if len(selected_ids) != len(selected) or len(settlement_refs) != 1 or (
        None in settlement_refs
    ):
        raise MutationJournalError(
            "lifecycle settlement family finalization is inconsistent"
        )

    def depth(journal: WorkspaceMutationJournal) -> int:
        observed = 0
        parent = journal.parent_transaction_id
        while parent in selected_ids:
            observed += 1
            parent_journal = next(
                item for item in selected
                if item.transaction_id == parent
            )
            parent = parent_journal.parent_transaction_id
        return observed

    children_first = tuple(sorted(
        selected,
        key=lambda item: (depth(item), item.transaction_id),
        reverse=True,
    ))
    for journal in selected:
        expected = journal._manifest.get("expected_lifecycle") or {}
        if set(expected.get("settlement_family", ())) != selected_ids:
            raise MutationJournalError(
                "lifecycle settlement family finalization is incomplete"
            )
        journal._assert_no_failed_descendant(allow=selected_ids)
        escapes = journal.detected_scope_escapes()
        if escapes:
            raise MutationJournalError(
                "lifecycle settlement family escaped its declared mutation "
                f"scope immediately before commit: {list(escapes)!r}"
            )
        journal.assert_head_unchanged()
        journal.assert_repository_metadata_unchanged()
        journal.assert_index_unchanged()

    previous_states = {
        journal.transaction_id: journal._manifest["state"]
        for journal in selected
    }
    try:
        # This is the family commit point. No journal/registry owner is removed
        # until every member has a durable terminal marker.
        for journal in children_first:
            journal._manifest["state"] = "committed"
            journal._write()
    except BaseException as exc:
        for journal in selected:
            journal._manifest["state"] = previous_states[
                journal.transaction_id
            ]
        raise MutationJournalError(
            "attached lifecycle settlement family markers remain incomplete; "
            "journal owners retained for reconciliation"
        ) from exc

    # Clean children before parents only after the family commit point. A
    # cleanup interruption leaves terminal manifests that startup can remove
    # without ever restoring accepted source.
    for journal in children_first:
        try:
            _cleanup_terminal_mutation_journal(journal)
        except BaseException as exc:
            raise MutationJournalError(
                "attached lifecycle settlement family cleanup remains "
                f"incomplete at {journal.transaction_id}"
            ) from exc
    # Each cleanup proves its journal and registry marker absent before it
    # unregisters the process-local owner.  Do not re-open a cleaned child's
    # journal parent after cleaning its ancestor: nested guard journals live
    # below that ancestor, so its successful removal intentionally removes the
    # retained path authority that ``cleanup_pending`` needs for a fail-closed
    # probe.  The remaining valid family-level invariant is that no selected
    # transaction remains in process-local ownership or failure state.
    with _LIVE_TRANSACTIONS_LOCK:
        retained = sorted(selected_ids.intersection(
            _LIVE_TRANSACTIONS.union(
                _LIVE_JOURNAL_OBJECTS,
                _FAILED_LIVE_TRANSACTIONS,
            )
        ))
    if retained:
        raise MutationJournalError(
            "attached lifecycle settlement family retained terminal owners: "
            f"{retained!r}"
        )


def prepare_mutation_lifecycle_settlement(
    corpus: "Corpus",
    journals: Iterable[WorkspaceMutationJournal],
    *,
    kind: str,
    reason: str,
    run_id: str | None = None,
    implementation_refs: Iterable[str] = (),
    implementation_refs_by_transaction: (
        Mapping[str, Iterable[str]] | None
    ) = None,
    _authority_held: bool = False,
    _mutation_transaction_ids: frozenset[str] | None = None,
) -> tuple[str, str]:
    """Seal exact multi-journal postimages for one lifecycle publication."""

    selected = tuple(journals)
    if not selected:
        raise MutationJournalError(
            "lifecycle settlement requires at least one transaction"
        )
    if not _authority_held:
        requested_ids = {journal.transaction_id for journal in selected}
        declared_families = {
            tuple(sorted(
                str(transaction_id)
                for transaction_id in journal._manifest.get(
                    "registry_transaction_family",
                    (),
                )
            ))
            for journal in selected
        }
        if (
            len(declared_families) != 1
            or not requested_ids.issubset(set(next(iter(declared_families))))
        ):
            raise MutationJournalError(
                "lifecycle settlement requests unrelated journal family "
                "components"
            )
        declared_family = set(next(iter(declared_families)))
        with _LIVE_TRANSACTIONS_LOCK:
            family_journals = {
                transaction_id: _LIVE_JOURNAL_OBJECTS[transaction_id]
                for transaction_id in declared_family
                if transaction_id in _LIVE_JOURNAL_OBJECTS
            }
        if set(family_journals) != declared_family:
            raise MutationJournalError(
                "lifecycle settlement declared journal family is not fully live"
            )
        all_journals = tuple(
            family_journals[transaction_id]
            for transaction_id in sorted(family_journals)
        )
        with _lifecycle_family_workspace_locks(all_journals):
            return prepare_mutation_lifecycle_settlement(
                corpus,
                all_journals,
                kind=kind,
                reason=reason,
                run_id=run_id,
                implementation_refs=implementation_refs,
                implementation_refs_by_transaction=(
                    implementation_refs_by_transaction
                ),
                _authority_held=True,
                _mutation_transaction_ids=frozenset(requested_ids),
            )
    if _mutation_transaction_ids is None:
        raise MutationJournalError(
            "lifecycle settlement lost its mutation-member authority"
        )
    transaction_ids = tuple(journal.transaction_id for journal in selected)
    if len(set(transaction_ids)) != len(transaction_ids):
        raise MutationJournalError(
            "lifecycle settlement contains duplicate transaction claims"
        )
    if _LIFECYCLE_SETTLEMENT_MARKER in reason:
        raise MutationJournalError(
            "lifecycle settlement reason already contains an authority marker"
        )
    selected_ids = set(transaction_ids)
    mutation_ids = set(_mutation_transaction_ids)
    if not mutation_ids or not mutation_ids.issubset(selected_ids):
        raise MutationJournalError(
            "lifecycle settlement mutation members conflict with its family"
        )
    family_parents: dict[str, str | None] | None = None
    for journal in selected:
        declared_family_tuple = tuple(
            str(value)
            for value in journal._manifest.get(
                "registry_transaction_family",
                (),
            )
        )
        declared_parents = {
            str(transaction_id): (
                str(parent) if parent is not None else None
            )
            for transaction_id, parent in journal._manifest.get(
                "registry_family_parents",
                {},
            ).items()
        }
        if (
            len(set(declared_family_tuple)) != len(declared_family_tuple)
            or set(declared_family_tuple) != selected_ids
            or set(declared_parents) != selected_ids
            or declared_parents.get(journal.transaction_id)
            != journal.parent_transaction_id
        ):
            raise MutationJournalError(
                "lifecycle settlement transactions are not one exact "
                "declared journal family"
            )
        if family_parents is None:
            family_parents = declared_parents
        elif family_parents != declared_parents:
            raise MutationJournalError(
                "lifecycle settlement journal family authority is inconsistent"
            )
    assert family_parents is not None
    roots_in_family = [
        transaction_id
        for transaction_id, parent in family_parents.items()
        if parent is None
    ]
    if (
        len(roots_in_family) != 1
        or any(
            parent is not None and parent not in selected_ids
            for parent in family_parents.values()
        )
    ):
        raise MutationJournalError(
            "lifecycle settlement journal family is disconnected"
        )
    visited: set[str] = set()
    pending = [roots_in_family[0]]
    while pending:
        current = pending.pop()
        if current in visited:
            raise MutationJournalError(
                "lifecycle settlement journal family contains a cycle"
            )
        visited.add(current)
        pending.extend(
            transaction_id
            for transaction_id, parent in family_parents.items()
            if parent == current
        )
    if visited != selected_ids:
        raise MutationJournalError(
            "lifecycle settlement journal family is disconnected"
        )

    base_commits = {
        journal.transaction_id: str(journal._manifest.get("head"))
        for journal in selected
    }
    refs = tuple(str(ref) for ref in implementation_refs)
    if (
        any(not ref for ref in refs)
        or len(set(refs)) != len(refs)
    ):
        raise MutationJournalError(
            "lifecycle settlement has duplicate or empty Implementation refs"
        )
    if implementation_refs_by_transaction is None:
        if len(mutation_ids) != 1 and refs:
            raise MutationJournalError(
                "multi-journal lifecycle settlement requires an exact "
                "Implementation-ref allocation"
            )
        allocated_refs = {
            transaction_id: (
                refs if transaction_id in mutation_ids and len(mutation_ids) == 1
                else ()
            )
            for transaction_id in selected_ids
        }
    else:
        if set(implementation_refs_by_transaction) != mutation_ids:
            raise MutationJournalError(
                "lifecycle settlement Implementation allocation conflicts "
                "with its journal family"
            )
        allocated_refs = {
            transaction_id: tuple(str(ref) for ref in assigned)
            for transaction_id, assigned in (
                implementation_refs_by_transaction.items()
            )
        }
        allocated_refs.update({
            transaction_id: ()
            for transaction_id in selected_ids.difference(mutation_ids)
        })
        flattened = tuple(
            ref
            for transaction_id in transaction_ids
            for ref in allocated_refs[transaction_id]
        )
        if (
            any(not ref for ref in flattened)
            or len(set(flattened)) != len(flattened)
            or set(flattened) != set(refs)
        ):
            raise MutationJournalError(
                "lifecycle settlement Implementation allocation is not exact"
            )
    operations = [
        (
            journal._lifecycle_settlement_operation(
                implementation_refs=allocated_refs[journal.transaction_id],
            )
            if journal.transaction_id in mutation_ids
            else journal._lifecycle_guard_operation()
        )
        for journal in selected
    ]
    for operation, journal in zip(operations, selected, strict=True):
        operation["parent_transaction_id"] = family_parents[
            journal.transaction_id
        ]
        operation["transaction_family"] = sorted(selected_ids)
    aggregate_totals = {
        key: sum(
            int(cast(dict[str, int], operation["capture_totals"])[key])
            for operation in operations
        )
        for key in ("paths", "path_bytes", "hashed_bytes", "xattr_bytes")
    }
    if (
        aggregate_totals["paths"] > _LIFECYCLE_SETTLEMENT_MAX_PATHS
        or aggregate_totals["path_bytes"]
        > _LIFECYCLE_SETTLEMENT_MAX_PATH_BYTES
        or aggregate_totals["hashed_bytes"]
        > _LIFECYCLE_SETTLEMENT_MAX_HASHED_BYTES
        or aggregate_totals["xattr_bytes"]
        > _LIFECYCLE_SETTLEMENT_MAX_XATTR_BYTES
    ):
        raise MutationJournalError(
            "aggregate lifecycle settlement exceeds its capture ceiling"
        )
    with _readable_spec_authority(corpus) as latest:
        if latest is None:
            raise MutationJournalError(
                "lifecycle settlement has no latest Spec authority"
            )
        persisted, persisted_digest = corpus.get_spec_with_digest(
            latest.version
        )
        if persisted != latest:
            raise MutationJournalError(
                "lifecycle settlement Spec differs from persisted authority"
            )
        body = {
            "schema": _LIFECYCLE_SETTLEMENT_SCHEMA,
            "kind": kind,
            "reason": reason,
            "run_id": run_id,
            "baseline_spec_version": latest.version,
            "baseline_spec_hash": str(persisted_digest),
            "affected_version": latest.version + 1,
            "base_commits": base_commits,
            "implementation_refs": list(refs),
            "transaction_family": sorted(selected_ids),
            "family_parents": family_parents,
            "capture_totals": aggregate_totals,
            "operations": operations,
        }
        settlement_lineage = {
            "spec_version": int(latest.version),
            "spec_hash": str(persisted_digest),
            "root": str(latest.root) if latest.root is not None else None,
            "implementation_refs": [
                str(ref) for ref in latest.implementation_refs
            ],
            "lifecycle_event_refs": [
                str(ref) for ref in latest.lifecycle_event_refs
            ],
        }
    payload = json.dumps(
        body,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    if len(payload) > _LIFECYCLE_SETTLEMENT_MAX_ARTIFACT_BYTES:
        raise MutationJournalError(
            "lifecycle settlement artifact exceeds its size ceiling"
        )
    settlement_ref = str(corpus.put_artifact(
        payload,
        kind="mutation_settlements",
        name_hint="lifecycle_mutation_settlement.json",
    ))
    settled_reason = reason + _LIFECYCLE_SETTLEMENT_MARKER + settlement_ref
    operations_by_transaction = {
        str(operation["transaction_id"]): operation
        for operation in operations
    }
    promoted_guards: list[WorkspaceMutationJournal] = []
    for journal in selected:
        if journal._manifest.get("lineage") is None:
            if operations_by_transaction[journal.transaction_id].get(
                "role"
            ) != "guard":
                raise MutationJournalError(
                    "mutation settlement member has no baseline Spec lineage"
                )
            # Auto-created outer/submodule/linked-worktree guards intentionally
            # begin before a child workflow supplies Spec authority. Bind them
            # now to the same raw baseline sealed by the aggregate artifact.
            journal._manifest["lineage"] = settlement_lineage
            promoted_guards.append(journal)
    # Writer-epoch quiescence re-reads each durable manifest. Persist every
    # validated guard promotion first so that reload cannot discard its newly
    # bound lineage between aggregate sealing and lifecycle preparation.
    for journal in promoted_guards:
        journal._write()
    for journal in selected:
        journal.prepare_lifecycle_acceptance(
            kind=kind,
            reason=settled_reason,
            run_id=run_id,
            settlement_ref=settlement_ref,
            settlement_family=selected_ids,
            settlement_family_parents=family_parents,
        )
    return settled_reason, settlement_ref


def _load_mutation_lifecycle_settlement(
    corpus: "Corpus",
    settlement_ref: str,
) -> tuple[dict[str, object], dict[str, dict[str, object]]]:
    """Load and shape-check one content-addressed lifecycle settlement."""

    from assay import ContentHash  # noqa: PLC0415

    try:
        raw_payload = corpus.get_artifact_bounded(
            ContentHash(settlement_ref),
            max_bytes=_LIFECYCLE_SETTLEMENT_MAX_ARTIFACT_BYTES,
        )
        payload = json.loads(raw_payload.decode("utf-8"))
    except ValueError as exc:
        if "exceeds" in str(exc):
            raise MutationJournalError(
                "lifecycle settlement artifact exceeds its size ceiling"
            ) from exc
        raise MutationJournalError(
            "lifecycle settlement artifact is unreadable: "
            f"{type(exc).__name__}: {exc}"
        ) from exc
    except Exception as exc:  # noqa: BLE001 - ambiguity retains journals
        raise MutationJournalError(
            "lifecycle settlement artifact is unreadable: "
            f"{type(exc).__name__}: {exc}"
        ) from exc
    if not isinstance(payload, dict) or payload.get("schema") != (
        _LIFECYCLE_SETTLEMENT_SCHEMA
    ):
        raise MutationJournalError("lifecycle settlement artifact is malformed")
    operations = payload.get("operations")
    implementation_refs = payload.get("implementation_refs")
    transaction_family = payload.get("transaction_family")
    family_parents = payload.get("family_parents")
    base_commits = payload.get("base_commits")
    aggregate_totals = payload.get("capture_totals")
    total_keys = ("paths", "path_bytes", "hashed_bytes", "xattr_bytes")
    if (
        not isinstance(payload.get("kind"), str)
        or not isinstance(payload.get("reason"), str)
        or payload.get("run_id") is not None
        and not isinstance(payload.get("run_id"), str)
        or isinstance(payload.get("baseline_spec_version"), bool)
        or not isinstance(payload.get("baseline_spec_version"), int)
        or not isinstance(payload.get("baseline_spec_hash"), str)
        or isinstance(payload.get("affected_version"), bool)
        or not isinstance(payload.get("affected_version"), int)
        or not isinstance(base_commits, dict)
        or not isinstance(implementation_refs, list)
        or any(not isinstance(ref, str) or not ref for ref in implementation_refs)
        or len(set(implementation_refs)) != len(implementation_refs)
        or not isinstance(transaction_family, list)
        or not transaction_family
        or any(
            not isinstance(transaction_id, str)
            or re.fullmatch(r"[0-9a-f]{32}", transaction_id) is None
            for transaction_id in transaction_family
        )
        or len(set(transaction_family)) != len(transaction_family)
        or transaction_family != sorted(transaction_family)
        or not isinstance(family_parents, dict)
        or set(family_parents) != set(transaction_family)
        or set(base_commits) != set(transaction_family)
        or any(
            not isinstance(commit, str) or not commit
            for commit in base_commits.values()
        )
        or any(
            parent is not None and parent not in transaction_family
            for parent in family_parents.values()
        )
        or not isinstance(aggregate_totals, dict)
        or set(aggregate_totals) != set(total_keys)
        or any(
            isinstance(aggregate_totals.get(key), bool)
            or not isinstance(aggregate_totals.get(key), int)
            or int(aggregate_totals[key]) < 0
            for key in total_keys
        )
        or not isinstance(operations, list)
        or not operations
    ):
        raise MutationJournalError("lifecycle settlement artifact is malformed")
    if len(operations) > _LIFECYCLE_SETTLEMENT_MAX_PATHS:
        raise MutationJournalError(
            "lifecycle settlement exceeds its path-count ceiling"
        )
    roots = [
        transaction_id
        for transaction_id, parent in family_parents.items()
        if parent is None
    ]
    if len(roots) != 1:
        raise MutationJournalError(
            "lifecycle settlement transaction family is malformed"
        )
    visited: set[str] = set()
    pending = [roots[0]]
    while pending:
        current = pending.pop()
        if current in visited:
            raise MutationJournalError(
                "lifecycle settlement transaction family contains a cycle"
            )
        visited.add(current)
        pending.extend(
            transaction_id
            for transaction_id, parent in family_parents.items()
            if parent == current
        )
    if visited != set(transaction_family):
        raise MutationJournalError(
            "lifecycle settlement transaction family is disconnected"
        )

    def checked_int(record: Mapping[str, object], key: str) -> int:
        value = record.get(key)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise MutationJournalError(
                "lifecycle settlement postimage state is malformed"
            )
        return value

    def checked_parent_chain(value: object) -> None:
        if (
            not isinstance(value, list)
            or not value
            or len(value) > _LIFECYCLE_SETTLEMENT_MAX_DEPTH
        ):
            raise MutationJournalError(
                "lifecycle settlement parent chain is malformed"
            )
        for identity in value:
            if (
                not isinstance(identity, list)
                or len(identity) != 2
                or any(
                    isinstance(component, bool)
                    or not isinstance(component, int)
                    or component < 0
                    for component in identity
                )
            ):
                raise MutationJournalError(
                    "lifecycle settlement parent chain is malformed"
                )

    def checked_xattrs(value: object) -> int:
        if (
            not isinstance(value, dict)
            or len(value) > 256
            or any(
                not isinstance(name, str) or not isinstance(encoded, str)
                for name, encoded in value.items()
            )
        ):
            raise MutationJournalError(
                "lifecycle settlement xattr state is malformed"
            )
        observed = 0
        for name, encoded in value.items():
            try:
                decoded = bytes.fromhex(cast(str, encoded))
            except ValueError as exc:
                raise MutationJournalError(
                    "lifecycle settlement xattr state is malformed"
                ) from exc
            observed += len(os.fsencode(name)) + len(decoded)
            if observed > 4 * 1024 * 1024:
                raise MutationJournalError(
                    "lifecycle settlement node xattrs exceed their ceiling"
                )
        return observed

    by_transaction: dict[str, dict[str, object]] = {}
    observed_aggregate = {key: 0 for key in total_keys}
    allocated_refs: list[str] = []
    for operation in operations:
        if not isinstance(operation, dict):
            raise MutationJournalError(
                "lifecycle settlement operation is malformed"
            )
        transaction_id = operation.get("transaction_id")
        scope = operation.get("scope")
        recursive_scope = operation.get("recursive_scope")
        postimages = operation.get("postimages")
        operation_refs = operation.get("implementation_refs")
        operation_role = operation.get("role")
        root_identity = operation.get("root_identity")
        operation_totals = operation.get("capture_totals")
        if (
            not isinstance(transaction_id, str)
            or re.fullmatch(r"[0-9a-f]{32}", transaction_id) is None
            or transaction_id in by_transaction
            or operation_role not in {"mutation", "guard"}
            or not isinstance(operation.get("slice_id"), str)
            or not operation.get("slice_id")
            or operation.get("parent_transaction_id")
            != family_parents.get(transaction_id)
            or operation.get("transaction_family") != transaction_family
            or not isinstance(scope, list)
            or any(not isinstance(path, str) or not path for path in scope)
            or len(set(scope)) != len(scope)
            or not isinstance(recursive_scope, list)
            or any(
                not isinstance(path, str) or path not in scope
                for path in recursive_scope
            )
            or len(set(recursive_scope)) != len(recursive_scope)
            or not isinstance(postimages, list)
            or not isinstance(operation_refs, list)
            or any(
                not isinstance(ref, str) or ref not in implementation_refs
                for ref in operation_refs
            )
            or len(set(operation_refs)) != len(operation_refs)
            or (
                operation_role == "mutation"
                and (not scope or not postimages)
            )
            or (
                operation_role == "guard"
                and (postimages or operation_refs)
            )
            or not isinstance(root_identity, dict)
            or set(root_identity) != {"device", "inode"}
            or any(
                isinstance(root_identity.get(key), bool)
                or not isinstance(root_identity.get(key), int)
                or int(root_identity[key]) < 0
                for key in ("device", "inode")
            )
            or not isinstance(operation_totals, dict)
            or set(operation_totals) != set(total_keys)
            or any(
                isinstance(operation_totals.get(key), bool)
                or not isinstance(operation_totals.get(key), int)
                or int(operation_totals[key]) < 0
                for key in total_keys
            )
        ):
            raise MutationJournalError(
                "lifecycle settlement operation is malformed"
            )
        try:
            normalized_scope = tuple(
                _settlement_relative_path(path) for path in scope
            )
            normalized_recursive = frozenset({
                _settlement_relative_path(path) for path in recursive_scope
            })
        except MutationJournalError:
            raise
        if list(normalized_scope) != scope:
            raise MutationJournalError(
                "lifecycle settlement scope is not canonical"
            )

        def in_scope(
            path: str,
            scope_roots: tuple[str, ...] = normalized_scope,
            recursive_roots: frozenset[str] = normalized_recursive,
        ) -> bool:
            return any(
                path == root
                or (
                    root in recursive_roots
                    and path.startswith(root.rstrip("/") + "/")
                )
                for root in scope_roots
            )

        postimage_paths: list[str] = []
        observed_operation = {key: 0 for key in total_keys}
        for postimage in postimages:
            if (
                not isinstance(postimage, dict)
                or not isinstance(postimage.get("path"), str)
                or not isinstance(postimage.get("state"), dict)
            ):
                raise MutationJournalError(
                    "lifecycle settlement postimage is malformed"
                )
            path = _settlement_relative_path(str(postimage["path"]))
            if path != postimage["path"] or not in_scope(path):
                raise MutationJournalError(
                    "lifecycle settlement postimage escaped its scope"
                )
            state = cast(dict[str, object], postimage["state"])
            kind = state.get("kind")
            checked_parent_chain(state.get("parent_chain"))
            if kind == "missing":
                if set(state) != {
                    "kind",
                    "parent_chain",
                    "missing_parent_index",
                }:
                    raise MutationJournalError(
                        "lifecycle settlement missing state is malformed"
                    )
                missing_index = state.get("missing_parent_index")
                if (
                    missing_index is not None
                    and (
                        isinstance(missing_index, bool)
                        or not isinstance(missing_index, int)
                        or missing_index < 0
                        or missing_index >= len(PurePosixPath(path).parts) - 1
                    )
                ):
                    raise MutationJournalError(
                        "lifecycle settlement missing state is malformed"
                    )
            else:
                common_keys = {
                    "kind",
                    "mode",
                    "nlink",
                    "device",
                    "inode",
                    "uid",
                    "gid",
                    "mtime_ns",
                    "ctime_ns",
                    "parent_chain",
                    "xattrs",
                }
                expected_keys = common_keys | (
                    {"sha256", "size"}
                    if kind == "file"
                    else {"target"}
                    if kind == "symlink"
                    else set()
                )
                if kind not in {"file", "symlink", "directory"} or (
                    set(state) != expected_keys
                ):
                    raise MutationJournalError(
                        "lifecycle settlement postimage state is malformed"
                    )
                for key in (
                    "mode",
                    "nlink",
                    "device",
                    "inode",
                    "uid",
                    "gid",
                    "mtime_ns",
                    "ctime_ns",
                ):
                    checked_int(state, key)
                if kind in {"file", "symlink"} and state["nlink"] != 1:
                    raise MutationJournalError(
                        "lifecycle settlement postimage has unsafe links"
                    )
                if kind == "file":
                    size = checked_int(state, "size")
                    digest = state.get("sha256")
                    if (
                        not isinstance(digest, str)
                        or re.fullmatch(r"[0-9a-f]{64}", digest) is None
                    ):
                        raise MutationJournalError(
                            "lifecycle settlement file state is malformed"
                        )
                    observed_operation["hashed_bytes"] += size
                elif kind == "symlink" and not isinstance(
                    state.get("target"),
                    str,
                ):
                    raise MutationJournalError(
                        "lifecycle settlement symlink state is malformed"
                    )
                observed_operation["xattr_bytes"] += checked_xattrs(
                    state.get("xattrs")
                )
            postimage_paths.append(path)
            observed_operation["paths"] += 1
            observed_operation["path_bytes"] += len(os.fsencode(path))
        if (
            postimage_paths != sorted(postimage_paths)
            or len(set(postimage_paths)) != len(postimage_paths)
        ):
            raise MutationJournalError(
                "lifecycle settlement postimage paths are ambiguous"
            )
        if not set(scope).issubset(postimage_paths):
            raise MutationJournalError(
                "lifecycle settlement omitted a scope root"
            )
        if observed_operation != operation_totals:
            raise MutationJournalError(
                "lifecycle settlement capture totals are inconsistent"
            )
        if operation_role == "guard" and any(
            observed_operation[key] != 0 for key in total_keys
        ):
            raise MutationJournalError(
                "lifecycle settlement guard has nonempty capture authority"
            )
        if (
            observed_operation["paths"] > _LIFECYCLE_SETTLEMENT_MAX_PATHS
            or observed_operation["path_bytes"]
            > _LIFECYCLE_SETTLEMENT_MAX_PATH_BYTES
            or observed_operation["hashed_bytes"]
            > _LIFECYCLE_SETTLEMENT_MAX_HASHED_BYTES
            or observed_operation["xattr_bytes"]
            > _LIFECYCLE_SETTLEMENT_MAX_XATTR_BYTES
        ):
            raise MutationJournalError(
                "lifecycle settlement operation exceeds its capture ceiling"
            )
        for key in total_keys:
            observed_aggregate[key] += observed_operation[key]
        allocated_refs.extend(operation_refs)
        by_transaction[transaction_id] = operation
    if set(by_transaction) != set(transaction_family):
        raise MutationJournalError(
            "lifecycle settlement operations do not match their family"
        )
    if (
        len(set(allocated_refs)) != len(allocated_refs)
        or set(allocated_refs) != set(implementation_refs)
        or observed_aggregate != aggregate_totals
        or observed_aggregate["paths"] > _LIFECYCLE_SETTLEMENT_MAX_PATHS
        or observed_aggregate["path_bytes"]
        > _LIFECYCLE_SETTLEMENT_MAX_PATH_BYTES
        or observed_aggregate["hashed_bytes"]
        > _LIFECYCLE_SETTLEMENT_MAX_HASHED_BYTES
        or observed_aggregate["xattr_bytes"]
        > _LIFECYCLE_SETTLEMENT_MAX_XATTR_BYTES
    ):
        raise MutationJournalError(
            "aggregate lifecycle settlement authority is inconsistent"
        )
    return payload, by_transaction


def _mutation_settlement_ref_from_reason(reason: str) -> str | None:
    if _LIFECYCLE_SETTLEMENT_MARKER not in reason:
        return None
    if reason.count(_LIFECYCLE_SETTLEMENT_MARKER) != 1:
        raise MutationJournalError(
            "lifecycle reason contains ambiguous settlement references"
        )
    _prefix, settlement_ref = reason.rsplit(
        _LIFECYCLE_SETTLEMENT_MARKER,
        1,
    )
    if not settlement_ref or any(character.isspace() for character in settlement_ref):
        raise MutationJournalError("lifecycle reason has malformed settlement ref")
    return settlement_ref


def mutation_lifecycle_reason_base(reason: str) -> str:
    """Return the semantic lifecycle reason without its exact-authority suffix."""

    settlement_ref = _mutation_settlement_ref_from_reason(reason)
    if settlement_ref is None:
        return reason
    return reason[: -len(_LIFECYCLE_SETTLEMENT_MARKER + settlement_ref)]


def _validate_mutation_lifecycle_event(
    corpus: "Corpus",
    current_spec: "Spec",
    event_ref: str,
    event,
) -> tuple[
    str,
    dict[str, object],
    dict[str, dict[str, object]],
]:
    """Validate one event's unique attachment and exact settlement claims."""

    from assay.canonical import hash_record  # noqa: PLC0415
    from assay.types.artifacts import LifecycleEvent  # noqa: PLC0415

    from . import _build_verify  # noqa: PLC0415

    settlement_ref = _mutation_settlement_ref_from_reason(event.reason)
    if settlement_ref is None:
        raise MutationJournalError(
            "lifecycle event has no exact mutation settlement"
        )
    payload, operations = _load_mutation_lifecycle_settlement(
        corpus,
        settlement_ref,
    )
    expected_version = int(cast(int, payload["affected_version"]))
    baseline_version = int(cast(int, payload["baseline_spec_version"]))
    if (
        str(hash_record(event)) != event_ref
        or event.kind != payload["kind"]
        or event.reason != (
            str(payload["reason"])
            + _LIFECYCLE_SETTLEMENT_MARKER
            + settlement_ref
        )
        or tuple(event.affected_versions) != (expected_version,)
        or expected_version != baseline_version + 1
        or expected_version > current_spec.version
        or (
            payload.get("run_id") is not None
            and (
                event.execution is None
                or event.execution.run_id != payload["run_id"]
            )
        )
    ):
        raise MutationJournalError(
            "lifecycle event conflicts with its mutation settlement"
        )
    try:
        baseline_spec, baseline_digest = corpus.get_spec_with_digest(
            baseline_version
        )
        accepted_spec, _accepted_digest = corpus.get_spec_with_digest(
            expected_version
        )
        persisted_current, _current_digest = corpus.get_spec_with_digest(
            current_spec.version
        )
    except Exception as exc:  # noqa: BLE001 - authority ambiguity fails closed
        raise MutationJournalError(
            "lifecycle settlement Spec authority is unreadable: "
            f"{type(exc).__name__}: {exc}"
        ) from exc
    if str(baseline_digest) != payload["baseline_spec_hash"]:
        raise MutationJournalError(
            "lifecycle settlement baseline raw Spec hash changed"
        )
    if persisted_current != current_spec:
        raise MutationJournalError(
            "lifecycle settlement current Spec differs from raw authority"
        )
    valid_lineage, lineage_reason = _build_verify._validate_spec_lineage(
        corpus,
        current_spec,
    )
    if not valid_lineage:
        raise MutationJournalError(
            "lifecycle settlement Spec lineage is invalid: "
            f"{lineage_reason}"
        )
    if (
        not _build_verify._spec_refs_are_prefix(baseline_spec, accepted_spec)
        or not _build_verify._spec_refs_are_prefix(accepted_spec, current_spec)
    ):
        raise MutationJournalError(
            "lifecycle settlement Spec refs are not append-only"
        )
    baseline_refs = tuple(
        str(ref) for ref in baseline_spec.lifecycle_event_refs
    )
    accepted_refs = tuple(
        str(ref) for ref in accepted_spec.lifecycle_event_refs
    )
    current_refs = tuple(
        str(ref) for ref in current_spec.lifecycle_event_refs
    )
    if (
        accepted_refs[: len(baseline_refs)] != baseline_refs
        or current_refs[: len(accepted_refs)] != accepted_refs
        or event_ref in baseline_refs
        or accepted_refs[len(baseline_refs):].count(event_ref) != 1
        or current_refs.count(event_ref) != 1
    ):
        raise MutationJournalError(
            "lifecycle settlement event lacks one unique first attachment"
        )
    attached_implementations = {
        str(ref) for ref in accepted_spec.implementation_refs
    }
    required_implementations = set(cast(list[str], payload["implementation_refs"]))
    if not required_implementations.issubset(attached_implementations):
        raise MutationJournalError(
            "lifecycle settlement names unattached Implementations"
        )
    claimed_transactions = set(operations)
    seen_settlement_events: set[str] = set()
    for candidate_ref in current_refs:
        if candidate_ref == event_ref:
            continue
        try:
            candidate = corpus.get_record(
                candidate_ref,
                as_type=LifecycleEvent,
            )
        except Exception as exc:  # noqa: BLE001 - ambiguity retains journals
            raise MutationJournalError(
                "attached lifecycle history is unreadable during settlement "
                f"claim validation: {type(exc).__name__}: {exc}"
            ) from exc
        candidate_settlement_ref = _mutation_settlement_ref_from_reason(
            candidate.reason
        )
        if candidate_settlement_ref is None:
            continue
        if candidate_ref in seen_settlement_events:
            raise MutationJournalError(
                "attached mutation settlement event occurs more than once"
            )
        seen_settlement_events.add(candidate_ref)
        if str(hash_record(candidate)) != candidate_ref:
            raise MutationJournalError(
                "attached mutation settlement event hash is inconsistent"
            )
        candidate_payload, candidate_operations = (
            _load_mutation_lifecycle_settlement(
                corpus,
                candidate_settlement_ref,
            )
        )
        if candidate.reason != (
            str(candidate_payload["reason"])
            + _LIFECYCLE_SETTLEMENT_MARKER
            + candidate_settlement_ref
        ):
            raise MutationJournalError(
                "attached mutation settlement event conflicts with its artifact"
            )
        overlap = claimed_transactions.intersection(candidate_operations)
        if overlap:
            raise MutationJournalError(
                "mutation transaction is claimed by multiple lifecycle "
                f"settlements: {sorted(overlap)!r}"
            )
    return settlement_ref, payload, operations


def _assert_journal_lifecycle_settlement(
    corpus: "Corpus",
    journal: WorkspaceMutationJournal,
    lifecycle_ref: str,
) -> None:
    """Prove one prepared journal is the exact claimed live postimage."""

    journal_cwd = Path(journal._manifest["cwd"])
    if _active_workspace_mutation_authority(journal_cwd) is None:
        # Multi-root guard families share the same canonical mutation-lock
        # component. Re-enter that component for this exact held root so every
        # descriptor-relative proof has its own root authority.
        with workspace_mutation_lock(journal_cwd):
            return _assert_journal_lifecycle_settlement(
                corpus,
                journal,
                lifecycle_ref,
            )

    from assay.types.artifacts import LifecycleEvent  # noqa: PLC0415

    spec = corpus.latest_spec()
    if spec is None:
        raise MutationJournalError(
            "lifecycle settlement has no latest Spec authority"
        )
    try:
        event = corpus.get_record(lifecycle_ref, as_type=LifecycleEvent)
    except Exception as exc:  # noqa: BLE001 - journal remains armed
        raise MutationJournalError(
            "lifecycle settlement event is unreadable: "
            f"{type(exc).__name__}: {exc}"
        ) from exc
    settlement_ref, payload, operations = _validate_mutation_lifecycle_event(
        corpus,
        spec,
        lifecycle_ref,
        event,
    )
    expected = journal._manifest.get("expected_lifecycle") or {}
    if expected.get("settlement_ref") != settlement_ref:
        raise MutationJournalError(
            "prepared journal does not bind the attached settlement artifact"
        )
    operation = operations.get(journal.transaction_id)
    if operation is None:
        raise MutationJournalError(
            "lifecycle settlement does not claim this transaction"
        )
    expected_family = tuple(expected.get("settlement_family", ()))
    expected_parents = expected.get("settlement_family_parents", {})
    authority = _assert_workspace_mutation_authority(
        journal_cwd
    )
    root_metadata = os.fstat(authority.root_descriptor)
    if (
        operation.get("slice_id") != journal.slice_id
        or tuple(cast(list[str], operation.get("scope")))
        != tuple(journal._manifest.get("scope", ()))
        or tuple(cast(list[str], operation.get("recursive_scope")))
        != tuple(sorted(journal._manifest.get("recursive_scope", ())))
        or cast(dict[str, str], payload.get("base_commits", {})).get(
            journal.transaction_id
        ) != journal._manifest.get("head")
        or operation.get("parent_transaction_id")
        != journal.parent_transaction_id
        or tuple(cast(list[str], operation.get("transaction_family", [])))
        != expected_family
        or operation.get("transaction_family")
        != payload.get("transaction_family")
        or expected_parents != payload.get("family_parents")
        or cast(dict[str, object], operation.get("root_identity")) != {
            "device": root_metadata.st_dev,
            "inode": root_metadata.st_ino,
        }
    ):
        raise MutationJournalError(
            "lifecycle settlement operation conflicts with its journal"
        )
    if operation.get("role") == "guard":
        if (
            operation.get("postimages")
            or operation.get("implementation_refs")
            or operation.get("capture_totals") != {
                "paths": 0,
                "path_bytes": 0,
                "hashed_bytes": 0,
                "xattr_bytes": 0,
            }
        ):
            raise MutationJournalError(
                "lifecycle settlement guard operation is not baseline-only"
            )
        journal.assert_exact_baseline()
        journal.assert_head_unchanged()
        journal.assert_repository_metadata_unchanged()
        journal.assert_index_unchanged()
        return
    if operation.get("role") != "mutation":
        raise MutationJournalError(
            "lifecycle settlement operation has an unknown role"
        )
    journal.assert_head_unchanged()
    journal.assert_repository_metadata_unchanged()
    journal.assert_index_unchanged()
    observed = journal._lifecycle_settlement_operation(
        implementation_refs=cast(list[str], operation["implementation_refs"]),
        allow_committed=True,
    )
    observed["parent_transaction_id"] = journal.parent_transaction_id
    observed["transaction_family"] = list(expected_family)
    if observed != operation:
        raise MutationJournalError(
            "lifecycle settlement live postimage no longer matches"
        )
    journal.assert_head_unchanged()
    journal.assert_repository_metadata_unchanged()
    journal.assert_index_unchanged()


def _expected_implementation_ref(
    corpus: "Corpus",
    expected: dict | None,
    lineage: dict | None,
    *,
    strict_ambiguity: bool = True,
) -> str | None:
    """Return the one exact post-baseline Implementation ref, if any.

    Current manifests bind the canonical record hash directly. Older journals
    used a five-field projection; retain compatibility only when that legacy
    projection resolves to exactly one newly attached record. A collision is
    ambiguous: strict prepared-keep recovery retains the armed journal and
    source instead of choosing either preservation or rollback.
    """

    if not expected:
        return None
    from assay.canonical import hash_record  # noqa: PLC0415
    from assay.types.artifacts import Implementation

    spec = corpus.latest_spec()
    if spec is None:
        if not strict_ambiguity:
            return None
        raise MutationJournalError(
            "prepared keep has no readable latest Spec authority"
        )
    if lineage is None:
        if not strict_ambiguity:
            return None
        raise MutationJournalError(
            "prepared keep has no baseline Spec lineage"
        )
    baseline_version = int(lineage.get("spec_version", -1))
    try:
        baseline_spec, baseline_digest = corpus.get_spec_with_digest(
            baseline_version
        )
    except Exception as exc:  # noqa: BLE001 - ambiguity must not erase bytes
        if not strict_ambiguity:
            return None
        raise MutationJournalError(
            "prepared keep baseline Spec is unreadable: "
            f"{type(exc).__name__}: {exc}"
        ) from exc
    if str(baseline_digest) != lineage.get("spec_hash"):
        if not strict_ambiguity:
            return None
        raise MutationJournalError(
            "prepared keep baseline Spec hash does not match its journal"
        )
    if spec.version < baseline_version:
        if strict_ambiguity:
            raise MutationJournalError(
                "prepared keep latest Spec predates its baseline lineage"
            )
        return None
    if spec.version == baseline_version:
        return None
    baseline_root = lineage.get("root")
    if baseline_root is not None and str(spec.root) != baseline_root:
        if strict_ambiguity:
            raise MutationJournalError(
                "prepared keep latest Spec conflicts with its baseline lineage"
            )
        return None
    baseline_refs = tuple(lineage.get("implementation_refs", ()))
    latest_refs = tuple(str(ref) for ref in spec.implementation_refs)
    exact_ref = expected.get("record_ref")
    if isinstance(exact_ref, str):
        if latest_refs.count(exact_ref) <= baseline_refs.count(exact_ref):
            return None
        try:
            record = corpus.get_record(exact_ref, as_type=Implementation)
        except Exception as exc:  # noqa: BLE001 - ambiguity retains journal
            if not strict_ambiguity:
                return None
            raise MutationJournalError(
                "attached expected Implementation is unreadable: "
                f"{exact_ref} ({type(exc).__name__}: {exc})"
            ) from exc
        if str(hash_record(record)) != exact_ref:
            if not strict_ambiguity:
                return None
            raise MutationJournalError(
                "attached expected Implementation hash is inconsistent: "
                f"{exact_ref}"
            )
        # The direct hash closes collisions, while the redundant projection
        # detects a corrupted journal that was retargeted to an unrelated
        # attached record after capture.
        if (
            record.slice_id != expected.get("slice_id")
            or record.base_commit != expected.get("base_commit")
            or str(record.diff_ref) != expected.get("diff_ref")
            or str(record.transcript_ref) != expected.get("transcript_ref")
            or record.classification != expected.get("classification")
        ):
            if not strict_ambiguity:
                return None
            raise MutationJournalError(
                "attached expected Implementation conflicts with its journal: "
                f"{exact_ref}"
            )
        return exact_ref

    matches: list[str] = []
    for ref in spec.implementation_refs:
        rendered = str(ref)
        if latest_refs.count(rendered) <= baseline_refs.count(rendered):
            continue
        try:
            impl = corpus.get_record(ref, as_type=Implementation)
        except Exception as exc:  # noqa: BLE001 - ambiguity retains journal
            if not strict_ambiguity:
                return None
            raise MutationJournalError(
                "post-baseline Implementation evidence is unreadable: "
                f"{rendered} ({type(exc).__name__}: {exc})"
            ) from exc
        if (
            impl.slice_id == expected.get("slice_id")
            and impl.base_commit == expected.get("base_commit")
            and str(impl.diff_ref) == expected.get("diff_ref")
            and str(impl.transcript_ref) == expected.get("transcript_ref")
            and impl.classification == expected.get("classification")
        ):
            matches.append(rendered)
    unique = tuple(dict.fromkeys(matches))
    if len(unique) > 1 and strict_ambiguity:
        raise MutationJournalError(
            "legacy prepared keep matches multiple attached Implementations: "
            f"{list(unique)!r}"
        )
    return unique[0] if len(unique) == 1 else None


def _expected_is_attached(
    corpus: "Corpus",
    expected: dict | None,
    lineage: dict | None,
) -> bool:
    return _expected_implementation_ref(corpus, expected, lineage) is not None


def _expected_lifecycle_ref(
    corpus: "Corpus",
    expected: dict | None,
    lineage: dict | None,
    *,
    strict_ambiguity: bool = True,
) -> str | None:
    if not expected:
        return None
    if lineage is None:
        if not strict_ambiguity:
            return None
        raise MutationJournalError(
            "prepared lifecycle keep has no baseline Spec lineage"
        )
    from assay.canonical import hash_record
    from assay.types.artifacts import LifecycleEvent

    spec = corpus.latest_spec()
    if spec is None:
        if not strict_ambiguity:
            return None
        raise MutationJournalError(
            "prepared lifecycle keep has no readable latest Spec authority"
        )
    baseline_version = int(lineage.get("spec_version", -1))
    try:
        baseline_spec, baseline_digest = corpus.get_spec_with_digest(
            baseline_version
        )
    except Exception as exc:  # noqa: BLE001 - ambiguity must not erase bytes
        if not strict_ambiguity:
            return None
        raise MutationJournalError(
            "prepared lifecycle baseline Spec is unreadable: "
            f"{type(exc).__name__}: {exc}"
        ) from exc
    if str(baseline_digest) != lineage.get("spec_hash"):
        if not strict_ambiguity:
            return None
        raise MutationJournalError(
            "prepared lifecycle baseline Spec hash does not match its journal"
        )
    if spec.version < baseline_version:
        if strict_ambiguity:
            raise MutationJournalError(
                "prepared lifecycle latest Spec predates its baseline lineage"
            )
        return None
    if spec.version == baseline_version:
        return None
    baseline_root = lineage.get("root")
    if baseline_root is not None and str(spec.root) != baseline_root:
        if strict_ambiguity:
            raise MutationJournalError(
                "prepared lifecycle latest Spec conflicts with its baseline "
                "lineage"
            )
        return None
    baseline_refs = tuple(lineage.get("lifecycle_event_refs", ()))
    latest_refs = tuple(str(ref) for ref in spec.lifecycle_event_refs)
    if latest_refs[: len(baseline_refs)] != baseline_refs:
        if not strict_ambiguity:
            return None
        raise MutationJournalError(
            "prepared lifecycle latest refs do not extend the baseline prefix"
        )
    matches: list[str] = []
    for ref in spec.lifecycle_event_refs[len(baseline_refs):]:
        rendered = str(ref)
        try:
            event = corpus.get_record(ref, as_type=LifecycleEvent)
        except Exception as exc:  # noqa: BLE001 - ambiguity retains journal
            if not strict_ambiguity:
                return None
            raise MutationJournalError(
                "post-baseline lifecycle evidence is unreadable: "
                f"{rendered} ({type(exc).__name__}: {exc})"
            ) from exc
        if str(hash_record(event)) != rendered:
            if not strict_ambiguity:
                return None
            raise MutationJournalError(
                "post-baseline lifecycle hash is inconsistent: "
                f"{rendered}"
            )
        if (
            event.kind == expected.get("kind")
            and event.reason in expected.get("reasons", ())
            and (
                expected.get("run_id") is None
                or (
                    event.execution is not None
                    and event.execution.run_id == expected.get("run_id")
                )
            )
        ):
            matches.append(rendered)
    if len(matches) > 1 and strict_ambiguity:
        raise MutationJournalError(
            "prepared lifecycle matches multiple attached events/occurrences: "
            f"{matches!r}"
        )
    if len(matches) != 1:
        return None

    selected = matches[0]
    first_attach_versions: list[int] = []
    previous_refs = tuple(str(ref) for ref in baseline_spec.lifecycle_event_refs)
    for version in range(baseline_version + 1, spec.version + 1):
        try:
            version_spec = corpus.get_spec(version)
        except Exception as exc:  # noqa: BLE001 - ambiguity retains journal
            if not strict_ambiguity:
                return None
            raise MutationJournalError(
                f"prepared lifecycle Spec v{version} is unreadable: "
                f"{type(exc).__name__}: {exc}"
            ) from exc
        current_refs = tuple(
            str(ref) for ref in version_spec.lifecycle_event_refs
        )
        if current_refs[: len(previous_refs)] != previous_refs:
            if not strict_ambiguity:
                return None
            raise MutationJournalError(
                "prepared lifecycle Spec history is not append-only at "
                f"v{version}"
            )
        appended = current_refs[len(previous_refs):]
        first_attach_versions.extend(
            version for ref in appended if ref == selected
        )
        previous_refs = current_refs
    if len(first_attach_versions) != 1:
        if strict_ambiguity:
            raise MutationJournalError(
                "prepared lifecycle ref has ambiguous attachment chronology: "
                f"{selected}"
            )
        return None
    event = corpus.get_record(selected, as_type=LifecycleEvent)
    if tuple(event.affected_versions) != (first_attach_versions[0],):
        if strict_ambiguity:
            raise MutationJournalError(
                "prepared lifecycle affected_versions does not equal its "
                "first attachment version"
            )
        return None
    return selected


def _expected_lifecycle_is_attached(
    corpus: "Corpus",
    expected: dict | None,
    lineage: dict | None,
) -> bool:
    return _expected_lifecycle_ref(corpus, expected, lineage) is not None


def _terminal_entry_projection(
    state: Mapping[str, object],
) -> dict[str, object]:
    """Project a live postimage onto durable baseline-comparison fields."""

    kind = str(state.get("kind", ""))
    if kind == "missing":
        return {"kind": "missing"}
    keys = {"kind", "mode", "xattrs"}
    if kind == "file":
        keys.update({"nlink", "size", "sha256"})
    elif kind == "symlink":
        keys.update({"nlink", "target"})
    elif kind != "directory":
        raise MutationJournalError(
            f"terminal disposition has unsupported entry kind {kind!r}"
        )
    return {key: state.get(key) for key in sorted(keys)}


def _terminal_assert_git_authority(
    journal: WorkspaceMutationJournal,
    receipt: _TerminalCleanupReceipt,
) -> None:
    """Re-prove stable Git identity without depending on deleted snapshots."""

    journal._assert_authority_lock_unchanged()
    cwd = journal._bound_workspace_cwd()
    expected_worktree = journal._bound_manifest_path(
        str(journal._manifest.get("worktree_root", journal._manifest["cwd"]))
    )
    if (
        not journal._bound_paths_same(_git_worktree_root(cwd), expected_worktree)
        or _git_config(cwd, "core.worktree")
        != journal._manifest.get("core_worktree_config")
        or _head(cwd) != journal._manifest.get("head")
        or (
            "head_symbolic_ref" in journal._manifest
            and _symbolic_head(cwd)
            != journal._manifest.get("head_symbolic_ref")
        )
        or (
            journal._manifest.get("refs") is not None
            and _refs_snapshot(cwd) != journal._manifest.get("refs")
        )
    ):
        raise MutationJournalError(
            "terminal cleanup Git authority differs from its durable baseline"
        )
    git_entry = journal._manifest.get("git_entry")
    if isinstance(git_entry, dict):
        path = Path(journal._manifest["cwd"]) / ".git"
        metadata, xattrs = journal._inspect_bound_git_admin_entry(
            path,
            label="terminal cleanup Git administration entry",
        )
        kind = git_entry.get("kind")
        if kind == "directory":
            if (
                not stat.S_ISDIR(metadata.st_mode)
                or stat.S_ISLNK(metadata.st_mode)
                or (metadata.st_dev, metadata.st_ino)
                != (int(git_entry["device"]), int(git_entry["inode"]))
                or stat.S_IMODE(metadata.st_mode) != int(git_entry["mode"])
                or xattrs != git_entry.get("xattrs", {})
            ):
                raise MutationJournalError(
                    "terminal cleanup Git administration entry changed"
                )
        elif kind == "file":
            expected_digest = receipt.proof_digests.get("git_entry")
            size = git_entry.get("size")
            if (
                isinstance(size, bool)
                or not isinstance(size, int)
                or size < 0
            ):
                raise MutationJournalError(
                    "terminal cleanup Git indirection size is malformed"
                )
            payload, opened, opened_xattrs = (
                journal._read_bound_git_admin_file(
                    path,
                    label="terminal cleanup Git indirection entry",
                    max_bytes=max(size, 1),
                )
            )
            if (
                expected_digest is None
                or not stat.S_ISREG(metadata.st_mode)
                or metadata.st_nlink != 1
                or stat.S_IMODE(metadata.st_mode) != int(git_entry["mode"])
                or (opened.st_dev, opened.st_ino)
                != (metadata.st_dev, metadata.st_ino)
                or opened_xattrs != git_entry.get("xattrs", {})
                or hashlib.sha256(payload).hexdigest() != expected_digest
            ):
                raise MutationJournalError(
                    "terminal cleanup Git indirection entry changed"
                )
        else:
            raise MutationJournalError(
                "terminal cleanup Git administration kind is malformed"
            )
    index = _index_path(cwd)
    expected_index = bool(journal._manifest.get("index_exists"))
    try:
        index_metadata = index.lstat()
    except FileNotFoundError:
        index_metadata = None
    if (index_metadata is not None) != expected_index:
        raise MutationJournalError(
            "terminal cleanup Git index existence changed"
        )
    if index_metadata is not None:
        opened_index, index_xattrs = journal._inspect_bound_git_admin_entry(
            index,
            label="terminal cleanup Git index",
        )
        if (
            not stat.S_ISREG(opened_index.st_mode)
            or opened_index.st_nlink != 1
            or (opened_index.st_dev, opened_index.st_ino)
            != (index_metadata.st_dev, index_metadata.st_ino)
            or (
                journal._manifest.get("index_mode") is not None
                and stat.S_IMODE(opened_index.st_mode)
                != int(cast(int | str, journal._manifest["index_mode"]))
            )
            or index_xattrs != journal._manifest.get("index_xattrs", {})
        ):
            raise MutationJournalError("terminal cleanup Git index changed")
        for field, observed in (
            ("index_device", opened_index.st_dev),
            ("index_uid", opened_index.st_uid),
            ("index_gid", opened_index.st_gid),
        ):
            expected = journal._manifest.get(field)
            if expected is not None and (
                type(expected) is not int or observed != expected
            ):
                raise MutationJournalError(
                    "terminal cleanup Git index changed"
                )
        views = _index_semantic_views(cwd, index)
        for name, payload in zip(
            ("index_stage", "index_flags_v", "index_flags_f"),
            views,
            strict=True,
        ):
            if hashlib.sha256(payload).hexdigest() != receipt.proof_digests.get(
                name
            ):
                raise MutationJournalError(
                    "terminal cleanup Git index semantics changed"
                )
        verified_index, verified_xattrs = (
            journal._inspect_bound_git_admin_entry(
                index,
                label="terminal cleanup Git index post-semantic proof",
            )
        )
        if (
            _git_admin_file_metadata(verified_index)
            != _git_admin_file_metadata(opened_index)
            or verified_xattrs != index_xattrs
        ):
            raise MutationJournalError(
                "terminal cleanup Git index changed during semantic proof"
            )


def _terminal_current_settlement_operation(
    journal: WorkspaceMutationJournal,
    *,
    implementation_refs: Iterable[str],
) -> dict[str, object]:
    """Recapture an accepted source postimage without journal-local blobs."""

    recorded_cwd = Path(journal._manifest["cwd"])
    authority = _assert_workspace_mutation_authority(recorded_cwd)
    root_metadata = os.fstat(authority.root_descriptor)
    scope = tuple(
        _settlement_relative_path(str(path))
        for path in journal._manifest.get("scope", ())
    )
    recursive_scope = {
        _settlement_relative_path(str(path))
        for path in journal._manifest.get("recursive_scope", ())
    }

    def in_scope(relative: str) -> bool:
        return any(
            relative == root
            or (
                root in recursive_scope
                and relative.startswith(root.rstrip("/") + "/")
            )
            for root in scope
        )

    budget = _SettlementCaptureBudget()
    candidates: set[str] = set()

    def add_candidate(rendered: str) -> None:
        relative = _settlement_relative_path(rendered)
        if relative in candidates:
            return
        if not in_scope(relative):
            raise MutationJournalError(
                "terminal cleanup postimage escaped transaction scope"
            )
        budget.add_path(relative)
        candidates.add(relative)

    for path in scope:
        add_candidate(path)
    for path in journal._manifest.get("entries", {}):
        relative = _settlement_relative_path(str(path))
        if in_scope(relative):
            add_candidate(relative)
    for path in _git_status_paths(recorded_cwd):
        relative = _settlement_relative_path(path)
        if in_scope(relative):
            add_candidate(relative)
    for root in sorted(recursive_scope):
        for path in _descriptor_recursive_postimage_paths(
            authority.root_descriptor,
            root,
        ):
            add_candidate(path)
    refs = tuple(dict.fromkeys(str(ref) for ref in implementation_refs))
    return {
        "role": "mutation",
        "transaction_id": journal.transaction_id,
        "slice_id": journal.slice_id,
        "scope": list(scope),
        "recursive_scope": sorted(recursive_scope),
        "postimages": [
            {
                "path": path,
                "state": _current_postimage_state(
                    authority.root_descriptor,
                    path,
                    budget,
                ),
            }
            for path in sorted(candidates)
        ],
        "implementation_refs": list(refs),
        "root_identity": {
            "device": root_metadata.st_dev,
            "inode": root_metadata.st_ino,
        },
        "capture_totals": budget.as_record(),
    }


def _terminal_assert_rolled_back_baseline(
    journal: WorkspaceMutationJournal,
) -> None:
    """Prove rolled-back source bytes against the original durable baseline."""

    authority = _assert_workspace_mutation_authority(
        Path(journal._manifest["cwd"])
    )
    budget = _SettlementCaptureBudget()
    for rendered, expected_value in cast(
        dict[str, object],
        journal._manifest.get("entries", {}),
    ).items():
        expected = cast(dict[str, object], expected_value)
        if expected.get("kind") == "opaque_directory":
            continue
        budget.add_path(rendered)
        observed = _current_postimage_state(
            authority.root_descriptor,
            rendered,
            budget,
        )
        if _terminal_entry_projection(observed) != _terminal_entry_projection(
            expected
        ):
            raise MutationJournalError(
                "terminal rollback source differs from its baseline: "
                f"{rendered!r}"
            )
    cwd = journal._bound_workspace_cwd()
    if set(_git_status_paths(cwd)) != set(
        str(path) for path in journal._manifest.get("baseline_dirty", ())
    ):
        raise MutationJournalError(
            "terminal rollback Git status differs from its baseline"
        )
    for rendered, binding_value in cast(
        dict[str, object],
        journal._manifest.get("raw_object_restore", {}),
    ).items():
        if not _matches_raw_object_binding(
            journal,
            rendered,
            cast(dict[str, object], binding_value),
        ):
            raise MutationJournalError(
                "terminal rollback raw Git object binding changed: "
                f"{rendered!r}"
            )


def _prove_terminal_cleanup_disposition(
    corpus: "Corpus",
    receipt: _TerminalCleanupReceipt,
    journal: WorkspaceMutationJournal,
) -> None:
    """Independently prove a receipt's source/Git terminal disposition."""

    journal._require_writer_epoch_quiescence(
        frontier="terminal cleanup disposition proof"
    )
    _terminal_assert_git_authority(journal, receipt)
    if journal.state == "rolled_back":
        _terminal_assert_rolled_back_baseline(journal)
        return
    expected_implementation = journal._manifest.get("expected_implementation")
    expected_lifecycle = journal._manifest.get("expected_lifecycle")
    if isinstance(expected_implementation, dict):
        implementation_ref = _expected_implementation_ref(
            corpus,
            expected_implementation,
            cast(dict | None, journal._manifest.get("lineage")),
            strict_ambiguity=True,
        )
        if implementation_ref is None:
            raise MutationJournalError(
                "terminal committed Implementation is not exactly attached"
            )
        expected_postimage = journal._manifest.get("expected_postimage")
        if not isinstance(expected_postimage, dict) or (
            _terminal_current_settlement_operation(
                journal,
                implementation_refs=(implementation_ref,),
            ) != expected_postimage
        ):
            raise MutationJournalError(
                "terminal committed Implementation postimage changed"
            )
        return
    if isinstance(expected_lifecycle, dict) and expected_lifecycle:
        lifecycle_ref = _expected_lifecycle_ref(
            corpus,
            expected_lifecycle,
            cast(dict | None, journal._manifest.get("lineage")),
            strict_ambiguity=True,
        )
        if lifecycle_ref is None:
            raise MutationJournalError(
                "terminal committed lifecycle event is not exactly attached"
            )
        from assay.types.artifacts import LifecycleEvent  # noqa: PLC0415

        spec = corpus.latest_spec()
        if spec is None:
            raise MutationJournalError(
                "terminal committed lifecycle has no latest Spec"
            )
        event = corpus.get_record(lifecycle_ref, as_type=LifecycleEvent)
        settlement_ref, _payload, operations = (
            _validate_mutation_lifecycle_event(
                corpus,
                spec,
                lifecycle_ref,
                event,
            )
        )
        if expected_lifecycle.get("settlement_ref") != settlement_ref:
            raise MutationJournalError(
                "terminal committed lifecycle settlement changed"
            )
        operation = operations.get(journal.transaction_id)
        if operation is None:
            raise MutationJournalError(
                "terminal committed lifecycle omits transaction"
            )
        current = _terminal_current_settlement_operation(
            journal,
            implementation_refs=cast(
                list[str],
                operation.get("implementation_refs", []),
            ),
        )
        current["parent_transaction_id"] = journal.parent_transaction_id
        current["transaction_family"] = list(
            expected_lifecycle.get("settlement_family", ())
        )
        if current != operation:
            raise MutationJournalError(
                "terminal committed lifecycle postimage changed"
            )
        return
    # Unattached commits are only restart-deletable when they are provably
    # guard-like: source is still the exact baseline. This preserves generic
    # callers without trusting a forged terminal state over live mutations.
    _terminal_assert_rolled_back_baseline(journal)


def _journal_from_terminal_cleanup_receipt(
    receipt: _TerminalCleanupReceipt,
) -> WorkspaceMutationJournal:
    """Construct immutable epoch storage from one parsed cleanup receipt."""

    journal = WorkspaceMutationJournal(
        receipt.parent_path / receipt.original_name,
        dict(receipt.manifest),
    )
    journal._logical_journal_identity = (
        receipt.journal_device,
        receipt.journal_inode,
    )
    journal._logical_journal_parent_identity = (
        receipt.parent_device,
        receipt.parent_inode,
    )
    journal._registry_authority_journal_dir = (
        receipt.parent_path / receipt.original_name
    )
    journal._bind_terminal_cleanup_epoch_proof(
        receipt.writer_epoch_terminal_proof
    )
    return journal


def _resume_terminal_cleanup_receipt(
    corpus: "Corpus",
    receipt: _TerminalCleanupReceipt,
    *,
    cleanup: bool = True,
) -> str | None:
    """Resume one receipt-controlled terminal deletion after global discovery."""

    parent_fd, parent_opened = _open_authority_directory(
        receipt.parent_path,
        label="terminal cleanup receipt parent",
    )
    journal_fd: int | None = None
    try:
        if (parent_opened.st_dev, parent_opened.st_ino) != (
            receipt.parent_device,
            receipt.parent_inode,
        ):
            raise MutationJournalError(
                "terminal cleanup receipt parent changed after discovery"
            )
        observed = _read_discovered_terminal_cleanup_receipt(
            parent_fd,
            receipt,
        )
        journal_opened: os.stat_result | None = None
        if observed.target_name is not None:
            journal_fd, journal_opened = _open_authority_directory_at(
                parent_fd,
                observed.target_name,
                label="terminal cleanup receipt journal target",
            )
            if (journal_opened.st_dev, journal_opened.st_ino) != (
                observed.journal_device,
                observed.journal_inode,
            ):
                raise MutationJournalError(
                    "terminal cleanup receipt journal target changed"
                )
        journal = _journal_from_terminal_cleanup_receipt(observed)
        _prove_terminal_cleanup_disposition(corpus, observed, journal)
        if not cleanup:
            return journal.slice_id
        if observed.target_name is not None:
            assert journal_fd is not None and journal_opened is not None
            _remove_terminal_journal_with_receipt(
                journal,
                parent_fd=parent_fd,
                parent_path=observed.parent_path,
                entry_name=observed.target_name,
                journal_fd=journal_fd,
                journal_metadata=journal_opened,
                allow_missing_registry=True,
            )
        completed = _read_discovered_terminal_cleanup_receipt(
            parent_fd,
            observed,
        )
        if completed.target_name is not None:
            raise MutationJournalError(
                "terminal cleanup receipt target remained after cleanup"
            )
        journal._remove_registry_marker(
            allow_missing=True,
            expected_payload=completed.registry_payload,
        )
        _remove_completed_terminal_cleanup_receipt(parent_fd, completed)
        _assert_authority_directory_binding(
            receipt.parent_path,
            parent_fd,
            parent_opened,
            label="terminal cleanup receipt parent",
        )
        return journal.slice_id
    finally:
        if journal_fd is not None:
            os.close(journal_fd)
        os.close(parent_fd)


@dataclass(frozen=True)
class _PendingDeleteRecoveryPlan:
    """A fully preflighted, replayable pending-delete namespace state."""

    journal: WorkspaceMutationJournal
    receipt: _PendingDeleteQuarantine
    quarantine_state: Literal["missing", "empty", "payload"]
    quarantine_identity: tuple[int, ...] | None
    payload_identity: tuple[int, ...] | None
    target_identity: tuple[int, ...] | None


def _pending_delete_stat_identity(metadata: os.stat_result) -> tuple[int, ...]:
    return tuple(
        int(getattr(metadata, field))
        for field in _SETTLEMENT_STABLE_STAT_FIELDS
    )


def _require_pending_delete_child_settled(
    receipt: _PendingDeleteQuarantine,
) -> None:
    """Reject recovery while the exact hosted child can still mutate."""

    if receipt.state != "bound":
        return
    assert receipt.boot_id is not None
    assert receipt.child_pid is not None
    assert receipt.child_start_ticks is not None
    if receipt.boot_id != _pending_delete_boot_id():
        return
    child = _pending_delete_process_identity(receipt.child_pid)
    if child is None or child[0] in {"X", "Z"}:
        return
    if child[1] == receipt.child_start_ticks:
        raise MutationJournalError(
            "pending delete child is still live; quarantine retained"
        )


def _pending_delete_recovery_plan(
    journal: WorkspaceMutationJournal,
    receipt: _PendingDeleteQuarantine,
    cwd: Path,
) -> _PendingDeleteRecoveryPlan:
    """Inventory one receipt without changing either namespace."""

    _require_pending_delete_child_settled(receipt)
    with _open_pending_delete_parent(cwd, receipt) as (
        parent_fd,
        root_mount_id,
        target_name,
        quarantine_name,
        _parent_chain,
    ):
        try:
            target = os.stat(
                target_name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            target_identity = None
        else:
            target_identity = _pending_delete_stat_identity(target)

        with _open_pending_delete_quarantine(
            parent_fd,
            quarantine_name,
            expected_mount_id=root_mount_id,
        ) as bound:
            if bound is None:
                return _PendingDeleteRecoveryPlan(
                    journal=journal,
                    receipt=receipt,
                    quarantine_state="missing",
                    quarantine_identity=None,
                    payload_identity=None,
                    target_identity=target_identity,
                )
            quarantine_fd, quarantine = bound
            if receipt.state == "bound":
                same_boot = receipt.boot_id == _pending_delete_boot_id()
                if (
                    quarantine.st_dev != receipt.quarantine_device
                    or quarantine.st_ino != receipt.quarantine_inode
                    or quarantine.st_mode != receipt.quarantine_mode
                    # Linux mount IDs are capabilities for one boot, not
                    # persistent filesystem identifiers.  Across reboot the
                    # current descriptor walk still proves qdir/root share
                    # one mount; compare the captured numeric ID only within
                    # its originating boot.
                    or (
                        same_boot
                        and root_mount_id != receipt.quarantine_mount_id
                    )
                ):
                    raise MutationJournalError(
                        "pending delete recovery qdir differs from its receipt"
                    )
            entries = _bounded_directory_names(
                quarantine_fd,
                label="pending delete recovery quarantine",
                max_entries=2,
            )
            quarantine_identity = _pending_delete_stat_identity(quarantine)
            if not entries:
                return _PendingDeleteRecoveryPlan(
                    journal=journal,
                    receipt=receipt,
                    quarantine_state="empty",
                    quarantine_identity=quarantine_identity,
                    payload_identity=None,
                    target_identity=target_identity,
                )
            if entries != (_PENDING_DELETE_PAYLOAD,):
                raise MutationJournalError(
                    "pending delete recovery qdir contains foreign entries"
                )
            if receipt.state != "bound":
                raise MutationJournalError(
                    "reserved pending delete qdir unexpectedly has a payload"
                )
            if target_identity is not None:
                raise MutationJournalError(
                    "pending delete restore target is occupied; both entries "
                    "were preserved"
                )
            before = os.stat(
                _PENDING_DELETE_PAYLOAD,
                dir_fd=quarantine_fd,
                follow_symlinks=False,
            )
            if stat.S_ISLNK(before.st_mode) or not (
                stat.S_ISREG(before.st_mode) or stat.S_ISDIR(before.st_mode)
            ):
                raise MutationJournalError(
                    "pending delete recovery payload has an unsafe type"
                )
            after = os.stat(
                _PENDING_DELETE_PAYLOAD,
                dir_fd=quarantine_fd,
                follow_symlinks=False,
            )
            if _pending_delete_stat_identity(before) != (
                _pending_delete_stat_identity(after)
            ):
                raise MutationJournalError(
                    "pending delete recovery payload changed during preflight"
                )
            return _PendingDeleteRecoveryPlan(
                journal=journal,
                receipt=receipt,
                quarantine_state="payload",
                quarantine_identity=quarantine_identity,
                payload_identity=_pending_delete_stat_identity(before),
                target_identity=None,
            )


def _pending_delete_plans(
    candidates: Iterable[WorkspaceMutationJournal],
    cwd: Path,
) -> tuple[_PendingDeleteRecoveryPlan, ...]:
    """Globally authenticate every receipt before the first source change."""

    owned: list[
        tuple[WorkspaceMutationJournal, _PendingDeleteQuarantine]
    ] = []
    for journal in sorted(candidates, key=lambda item: item.transaction_id):
        with _bound_mutation_journal_directory(journal):
            receipts = _pending_delete_quarantines(journal._manifest)
        owned.extend((journal, receipt) for receipt in receipts)

    tokens: set[str] = set()
    namespaces: list[tuple[str, str]] = []
    for journal, receipt in owned:
        if receipt.token in tokens:
            raise MutationJournalError(
                "pending delete token is duplicated across journals"
            )
        tokens.add(receipt.token)
        for path in (
            receipt.target_relative,
            receipt.quarantine_relative,
        ):
            for previous_transaction, previous in namespaces:
                if (
                    path == previous
                    or path.startswith(previous.rstrip("/") + "/")
                    or previous.startswith(path.rstrip("/") + "/")
                ):
                    raise MutationJournalError(
                        "pending delete namespaces overlap across journals: "
                        f"{previous_transaction} and {journal.transaction_id}"
                    )
            namespaces.append((journal.transaction_id, path))

    return tuple(
        _pending_delete_recovery_plan(journal, receipt, cwd)
        for journal, receipt in owned
    )


def _rename_pending_delete_noreplace(
    source_fd: int,
    source_name: str,
    destination_fd: int,
    destination_name: str,
) -> None:
    """Restore a qdir payload atomically without replacing the public name."""

    if any(
        name in {"", ".", ".."} or "/" in name or "\0" in name
        for name in (source_name, destination_name)
    ):
        raise MutationJournalError(
            "pending delete recovery rename has an unsafe name"
        )
    try:
        renameat2 = ctypes.CDLL(None, use_errno=True).renameat2
    except (AttributeError, OSError) as exc:
        raise MutationJournalError(
            "pending delete recovery requires atomic no-replace rename"
        ) from exc
    renameat2.argtypes = (
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_uint,
    )
    renameat2.restype = ctypes.c_int
    result = renameat2(
        source_fd,
        os.fsencode(source_name),
        destination_fd,
        os.fsencode(destination_name),
        1,  # RENAME_NOREPLACE
    )
    if result == 0:
        return
    error = ctypes.get_errno()
    if error in {errno.EEXIST, errno.ENOTEMPTY}:
        raise MutationJournalError(
            "pending delete restore target appeared; both entries preserved"
        )
    if error in {errno.ENOSYS, errno.EINVAL, errno.EOPNOTSUPP}:
        raise MutationJournalError(
            "pending delete recovery lacks atomic no-replace rename"
        )
    raise MutationJournalError(
        "pending delete restore rename failed: " + os.strerror(error)
    )


def _recover_one_pending_delete_quarantine(
    plan: _PendingDeleteRecoveryPlan,
    cwd: Path,
) -> None:
    """Normalize one preflighted qdir, then durably clear its receipt."""

    receipt_record = plan.receipt.to_record()
    if plan.quarantine_state == "missing":
        plan.journal.clear_pending_delete_quarantine(receipt_record)
        return

    with _open_pending_delete_parent(cwd, plan.receipt) as (
        parent_fd,
        root_mount_id,
        target_name,
        quarantine_name,
        _parent_chain,
    ):
        with _open_pending_delete_quarantine(
            parent_fd,
            quarantine_name,
            expected_mount_id=root_mount_id,
            allow_removed=True,
        ) as bound:
            if bound is None:
                raise MutationJournalError(
                    "pending delete qdir disappeared after preflight"
                )
            quarantine_fd, quarantine = bound
            if _pending_delete_stat_identity(quarantine) != (
                plan.quarantine_identity
            ):
                raise MutationJournalError(
                    "pending delete qdir changed after preflight"
                )
            entries = _bounded_directory_names(
                quarantine_fd,
                label="pending delete recovery quarantine",
                max_entries=2,
            )
            expected_entries = (
                ()
                if plan.quarantine_state == "empty"
                else (_PENDING_DELETE_PAYLOAD,)
            )
            if entries != expected_entries:
                raise MutationJournalError(
                    "pending delete qdir contents changed after preflight"
                )
            try:
                target = os.stat(
                    target_name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                target_identity = None
            else:
                target_identity = _pending_delete_stat_identity(target)
            if target_identity != plan.target_identity:
                raise MutationJournalError(
                    "pending delete public target changed after preflight"
                )

            if plan.quarantine_state == "payload":
                payload = os.stat(
                    _PENDING_DELETE_PAYLOAD,
                    dir_fd=quarantine_fd,
                    follow_symlinks=False,
                )
                if _pending_delete_stat_identity(payload) != (
                    plan.payload_identity
                ):
                    raise MutationJournalError(
                        "pending delete payload changed after preflight"
                    )
                _rename_pending_delete_noreplace(
                    quarantine_fd,
                    _PENDING_DELETE_PAYLOAD,
                    parent_fd,
                    target_name,
                )
                _fsync_terminal_parent_directory(
                    quarantine_fd,
                    label="pending delete quarantine after restore",
                )
                _fsync_terminal_parent_directory(
                    parent_fd,
                    label="pending delete parent after restore",
                )
                restored = os.stat(
                    target_name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
                # A rename updates ctime even though it preserves the exact
                # inode, type, link count, size, and content mtime.
                restored_identity = _pending_delete_stat_identity(restored)
                if (
                    plan.payload_identity is None
                    or restored_identity[:-1]
                    != plan.payload_identity[:-1]
                ):
                    raise MutationJournalError(
                        "pending delete restored target changed identity"
                    )
            if _bounded_directory_names(
                quarantine_fd,
                label="settled pending delete quarantine",
                max_entries=1,
            ):
                raise MutationJournalError(
                    "pending delete quarantine did not become empty"
                )
            os.rmdir(quarantine_name, dir_fd=parent_fd)
            _fsync_terminal_parent_directory(
                parent_fd,
                label="pending delete parent after qdir removal",
            )
    plan.journal.clear_pending_delete_quarantine(receipt_record)


def _recover_pending_delete_quarantines(
    candidates: Iterable[WorkspaceMutationJournal],
    cwd: Path,
) -> None:
    """Preflight all receipts twice, then reprove and recover each one."""

    candidate_tuple = tuple(candidates)
    first = _pending_delete_plans(candidate_tuple, cwd)
    second = _pending_delete_plans(candidate_tuple, cwd)
    if first != second:
        raise MutationJournalError(
            "pending delete recovery inventory changed during global preflight"
        )
    for expected in first:
        current = _pending_delete_recovery_plan(
            expected.journal,
            expected.receipt,
            cwd,
        )
        if current != expected:
            raise MutationJournalError(
                "pending delete recovery state changed before mutation"
            )
        _recover_one_pending_delete_quarantine(expected, cwd)


def _recover_mutation_journals_locked(
    corpus: "Corpus",
    cwd: str | Path,
    *,
    accepted_lifecycle_transactions: (
        Mapping[str, frozenset[str]] | None
    ) = None,
) -> RecoveryReport:
    """Recover journals while workspace and latest-Spec authority are held.

    Newest-first order mirrors context-manager unwinding.  This matters for
    serial invocations: a later checkpoint's baseline may include an earlier
    pending slice, so it must restore before the earlier journal does.
    """

    _assert_workspace_mutation_authority(cwd)
    root = Path(cwd).resolve()
    candidates: list[WorkspaceMutationJournal] = []
    terminal_receipts: list[_TerminalCleanupReceipt] = []
    failures: list[str] = []
    tombstone_recovered: tuple[str, ...] = ()
    try:
        candidates = list(discover_mutation_journals(
            corpus,
            workspace=root,
            _terminal_receipts=terminal_receipts,
        ))
    except Exception as exc:  # noqa: BLE001 - inventory globally gates writes
        return RecoveryReport(
            (),
            (),
            (
                "mutation journal discovery failed; all journals retained: "
                f"{type(exc).__name__}: {exc}",
            ),
        )
    try:
        for candidate in candidates:
            with _bound_mutation_journal_directory(candidate):
                pass
    except Exception as exc:  # noqa: BLE001 - pre-write global reproof
        return RecoveryReport(
            (),
            (),
            (
                "mutation journal binding changed after discovery; all "
                f"journals retained: {type(exc).__name__}: {exc}",
            ),
        )
    try:
        _assert_registry_clear(
            root,
            allowed_transaction_ids={
                *(candidate.transaction_id for candidate in candidates),
                *(receipt.transaction_id for receipt in terminal_receipts),
            },
        )
    except MutationJournalError as exc:
        return RecoveryReport(
            (),
            (),
            (
                "workspace registry has foreign mutation authority before "
                f"recovery; all journals retained: {exc}",
            ),
        )

    def recover_terminal_authority() -> (
        RecoveryReport | tuple[tuple[str, ...], tuple[str, ...]]
    ):
        """Audit one complete family map through receipt/tombstone cleanup."""

        epoch_members: dict[str, WorkspaceMutationJournal] = {}
        try:
            for candidate in candidates:
                if candidate.transaction_id in epoch_members:
                    raise MutationJournalError(
                        "writer epoch audit found duplicate mutation "
                        f"transaction {candidate.transaction_id}"
                    )
                epoch_members[candidate.transaction_id] = candidate
            for receipt in terminal_receipts:
                receipt_journal = _journal_from_terminal_cleanup_receipt(
                    receipt
                )
                if receipt_journal.transaction_id in epoch_members:
                    raise MutationJournalError(
                        "writer epoch audit found duplicate receipt/candidate "
                        f"transaction {receipt_journal.transaction_id}"
                    )
                epoch_members[receipt_journal.transaction_id] = receipt_journal
        except Exception as exc:  # noqa: BLE001 - inventory is global
            return RecoveryReport(
                (),
                (),
                (
                    "writer epoch recovery inventory failed; all journals "
                    f"and receipts retained: {type(exc).__name__}: {exc}",
                ),
            )

        previous_epoch_members = getattr(
            _LOCK_STATE,
            "writer_epoch_recovery_members",
            None,
        )
        _LOCK_STATE.writer_epoch_recovery_members = epoch_members
        try:
            # Epoch authority is the first global recovery gate.  The same
            # exact map remains installed through both receipt passes and the
            # external tombstone reaper; exceptions cannot leak TLS authority.
            try:
                for member in epoch_members.values():
                    member._require_writer_epoch_quiescence(
                        frontier="startup recovery inventory"
                    )
            except Exception as exc:  # noqa: BLE001 - UNKNOWN blocks all
                return RecoveryReport(
                    (),
                    (),
                    (
                        "writer epoch recovery audit failed; all journals and "
                        f"receipts retained: {type(exc).__name__}: {exc}",
                    ),
                )

            # A hosted delete can leave its exact scope root parked inside a
            # durable private sibling.  Normalize those mappings only after
            # every family member proves writer-epoch quiescence, and while
            # that complete audited family map remains installed in TLS.
            try:
                _recover_pending_delete_quarantines(candidates, root)
            except Exception as exc:  # noqa: BLE001 - global write gate
                return RecoveryReport(
                    (),
                    (),
                    (
                        "pending delete quarantine recovery failed; all "
                        "remaining journals and quarantines retained: "
                        f"{type(exc).__name__}: {exc}",
                    ),
                )

            # Re-prove every receipt before deleting any one, then re-prove
            # immediately before its own cleanup to close validation-to-use.
            try:
                for receipt in terminal_receipts:
                    _resume_terminal_cleanup_receipt(
                        corpus,
                        receipt,
                        cleanup=False,
                    )
            except Exception as exc:  # noqa: BLE001 - global receipt gate
                return RecoveryReport(
                    (),
                    (),
                    (
                        "terminal cleanup receipt disposition failed; all "
                        "receipt targets retained: "
                        f"{type(exc).__name__}: {exc}",
                    ),
                )

            receipt_recovered: list[str] = []
            try:
                for receipt in terminal_receipts:
                    slice_id = _resume_terminal_cleanup_receipt(corpus, receipt)
                    if slice_id is not None:
                        receipt_recovered.append(slice_id)
            except Exception as exc:  # noqa: BLE001 - exact retry remains
                return RecoveryReport(
                    tuple(receipt_recovered),
                    (),
                    (f"terminal cleanup receipt recovery failed ({exc})",),
                )

            # Discovery is the global no-write gate.  Tombstones are reaped
            # only while the audited receipt/candidate family map is retained.
            try:
                from ._journal_recovery import (  # noqa: PLC0415
                    reap_external_recovery_tombstones,
                )

                recovered_tombstones = reap_external_recovery_tombstones(
                    corpus,
                    root,
                )
            except Exception as exc:  # noqa: BLE001
                return RecoveryReport(
                    (),
                    (),
                    (f"external recovery tombstone cleanup failed ({exc})",),
                )
            return tuple(receipt_recovered), recovered_tombstones
        finally:
            if previous_epoch_members is None:
                try:
                    del _LOCK_STATE.writer_epoch_recovery_members
                except AttributeError:
                    pass
            else:
                _LOCK_STATE.writer_epoch_recovery_members = (
                    previous_epoch_members
                )

    terminal_authority = recover_terminal_authority()
    if isinstance(terminal_authority, RecoveryReport):
        return terminal_authority
    receipt_recovered, tombstone_recovered = terminal_authority

    recovered: list[str] = [*receipt_recovered, *tombstone_recovered]
    preserved: list[str] = []
    settlements: list[RecoverySettlement] = []
    by_id: dict[str, WorkspaceMutationJournal] = {}
    blocked: set[str] = set()
    for journal in candidates:
        if journal.transaction_id in by_id:
            failures.append(
                f"duplicate mutation transaction id {journal.transaction_id}"
            )
            blocked.add(journal.transaction_id)
        by_id[journal.transaction_id] = journal

    depths: dict[str, int] = {}
    for starting_id in tuple(by_id):
        if starting_id in depths or starting_id in blocked:
            continue
        trail: list[str] = []
        positions: dict[str, int] = {}
        transaction_id = starting_id
        base_depth = -1
        try:
            while transaction_id not in depths:
                if transaction_id in positions:
                    cycle = trail[positions[transaction_id]:] + [transaction_id]
                    blocked.update(cycle)
                    raise MutationJournalError(
                        "mutation journal parent cycle: " + " -> ".join(cycle)
                    )
                if len(trail) >= _MUTATION_JOURNAL_MAX_DISCOVERY_DEPTH:
                    blocked.update(trail)
                    raise MutationJournalError(
                        "mutation journal lineage exceeds its depth ceiling"
                    )
                positions[transaction_id] = len(trail)
                trail.append(transaction_id)
                parent = by_id[transaction_id]._manifest.get(
                    "parent_transaction_id"
                )
                if parent is None or _is_live(str(parent)):
                    base_depth = -1
                    break
                parent_id = str(parent)
                if parent_id not in by_id:
                    blocked.update(trail)
                    raise MutationJournalError(
                        f"mutation journal {transaction_id} has missing parent "
                        f"{parent_id}"
                    )
                transaction_id = parent_id
            else:
                base_depth = depths[transaction_id]
            for offset, current_id in enumerate(reversed(trail), start=1):
                depths[current_id] = base_depth + offset
        except MutationJournalError as exc:
            blocked.update(trail)
            failures.append(str(exc))

    ordered = sorted(
        candidates,
        key=lambda item: (
            depths.get(item.transaction_id, -1),
            item.created_ns,
            int(item._manifest.get("sequence", 0)),
            item.transaction_id,
        ),
        reverse=True,
    )
    exact_family_by_id: dict[str, tuple[str, ...]] = {}
    for candidate in candidates:
        expected = candidate._manifest.get("expected_lifecycle") or {}
        settlement_ref = expected.get("settlement_ref")
        family = tuple(
            str(transaction_id)
            for transaction_id in expected.get("settlement_family", ())
        )
        if settlement_ref is None or len(family) <= 1:
            continue
        if len(family) != len(set(family)) or candidate.transaction_id not in family:
            blocked.update(family)
            blocked.add(candidate.transaction_id)
            failures.append(
                f"{candidate.slice_id}: malformed exact lifecycle settlement "
                "family; journals retained"
            )
            continue
        canonical_family = tuple(sorted(family))
        for transaction_id in family:
            previous_family = exact_family_by_id.get(transaction_id)
            if previous_family is not None and previous_family != canonical_family:
                blocked.update(previous_family)
                blocked.update(canonical_family)
                failures.append(
                    "mutation transaction is claimed by conflicting prepared "
                    f"settlement families: {transaction_id}"
                )
                continue
            exact_family_by_id[transaction_id] = canonical_family
    external_recovery_owner_by_id: dict[str, str] = {}
    for candidate in candidates:
        binding = candidate._discovery_binding
        has_external_recovery = (
            binding is not None
            and any(
                record[0] == "external_recovery.json"
                for record in binding.artifact_inventory
            )
        )
        if not has_external_recovery:
            continue
        external_family = {
            str(transaction_id)
            for transaction_id in candidate._manifest.get(
                "registry_transaction_family",
                (),
            )
        }
        external_family.add(candidate.transaction_id)
        for transaction_id in external_family:
            previous_owner = external_recovery_owner_by_id.get(transaction_id)
            if (
                previous_owner is not None
                and previous_owner != candidate.transaction_id
            ):
                blocked.update(external_family)
                failures.append(
                    "mutation family has conflicting external recovery owners"
                )
                continue
            external_recovery_owner_by_id[transaction_id] = (
                candidate.transaction_id
            )
    failed_recovery: set[str] = set()
    processed_family: set[str] = set()
    previous_writer_epoch_recovery_members = getattr(
        _LOCK_STATE,
        "writer_epoch_recovery_members",
        None,
    )
    _LOCK_STATE.writer_epoch_recovery_members = by_id

    def acknowledge_terminal(transaction_id: str) -> None:
        for candidate in candidates:
            if (
                candidate.transaction_id == transaction_id
                or not candidate.journal_dir.is_dir()
            ):
                continue
            candidate._acknowledge_resolved_descendants((transaction_id,))

    for journal in ordered:
        try:
            _assert_workspace_mutation_authority(root)
            if journal.transaction_id in processed_family:
                continue
            if journal.transaction_id in blocked:
                continue
            unresolved_family = failed_recovery.intersection(
                str(transaction_id)
                for transaction_id in journal._manifest.get(
                    "registry_transaction_family", ()
                )
            )
            if unresolved_family:
                failures.append(
                    f"{journal.slice_id}: unresolved failed descendant "
                    f"{sorted(unresolved_family)!r}; journal retained"
                )
                failed_recovery.add(journal.transaction_id)
                continue
            if _is_live(journal.transaction_id):
                # A composed child workflow may re-enter recovery while its
                # parent transaction intentionally remains open around the
                # child. Only process-local objects registered by begin() are
                # skipped; crash-left manifests are never registered after
                # process restart and remain recoverable.
                continue
            external_owner = external_recovery_owner_by_id.get(
                journal.transaction_id
            )
            if (
                external_owner is not None
                and external_owner != journal.transaction_id
            ):
                # The parent event owns source restoration and every retained
                # guard. Processing a child first would strand removed linked
                # worktree guards before the parent can resume its protocol.
                continue
            # An operator-authorized external Git cleanup uses a separate,
            # write-ahead recovery protocol.  It is intentionally invisible
            # to ordinary recovery until the exact durable acceptance exists;
            # once prepared, startup may safely resume its idempotent
            # source-only rollback and marker cleanup after process death.
            if (journal.journal_dir / "external_recovery.json").is_file():
                from ._journal_recovery import (  # noqa: PLC0415
                    resume_prepared_external_recovery,
                )

                _assert_workspace_mutation_authority(root)
                report = resume_prepared_external_recovery(
                    corpus,
                    journal,
                    _startup_inventory=tuple(candidates),
                )
                if report is None:
                    raise MutationJournalError(
                        "external recovery marker disappeared during resume"
                    )
                recovered.append(journal.slice_id)
                external_family = {
                    transaction_id
                    for transaction_id, owner in (
                        external_recovery_owner_by_id.items()
                    )
                    if owner == journal.transaction_id
                }
                processed_family.update(external_family)
                acknowledge_terminal(journal.transaction_id)
                continue
            settlement_family = exact_family_by_id.get(journal.transaction_id)
            if settlement_family is not None:
                family_set = set(settlement_family)
                family_journals = {
                    transaction_id: by_id[transaction_id]
                    for transaction_id in family_set
                    if transaction_id in by_id
                }
                if set(family_journals) != family_set:
                    terminal_states = {
                        family_journal.state
                        for family_journal in family_journals.values()
                    }
                    if family_journals and (
                        terminal_states == {"committed"}
                        or terminal_states == {"rolled_back"}
                    ):
                        # Family cleanup can be interrupted only after every
                        # member has a durable committed marker. Missing owners
                        # are therefore already terminal, never rollback gaps.
                        for family_journal in family_journals.values():
                            _cleanup_terminal_mutation_journal(
                                family_journal
                            )
                            processed_family.add(
                                family_journal.transaction_id
                            )
                            acknowledge_terminal(
                                family_journal.transaction_id
                            )
                        continue
                    failed_recovery.update(family_set)
                    failures.append(
                        f"{journal.slice_id}: exact lifecycle settlement family "
                        "is incomplete; journals retained"
                    )
                    continue
                try:
                    with _lifecycle_family_workspace_locks(
                        family_journals.values()
                    ):
                        prepared = [
                            family_journal
                            for family_journal in family_journals.values()
                            if (
                                family_journal._manifest.get(
                                    "expected_lifecycle"
                                ) or {}
                            ).get("settlement_ref") is not None
                        ]
                        if not prepared:
                            raise MutationJournalError(
                                "exact lifecycle family lost its prepared "
                                "settlement authority"
                            )
                        representative = prepared[0]
                        representative_expected = (
                            representative._manifest.get(
                                "expected_lifecycle"
                            ) or {}
                        )
                        settlement_ref = representative_expected.get(
                            "settlement_ref"
                        )
                        for prepared_journal in prepared:
                            prepared_expected = (
                                prepared_journal._manifest.get(
                                    "expected_lifecycle"
                                ) or {}
                            )
                            if (
                                prepared_expected.get("settlement_ref")
                                != settlement_ref
                                or set(prepared_expected.get(
                                    "settlement_family",
                                    (),
                                )) != family_set
                            ):
                                raise MutationJournalError(
                                    "exact lifecycle settlement family "
                                    "authority is inconsistent"
                                )
                        lifecycle_ref = _expected_lifecycle_ref(
                            corpus,
                            representative_expected,
                            representative._manifest.get("lineage"),
                            strict_ambiguity=True,
                        )
                        if lifecycle_ref is None:
                            if any(
                                family_journal.state == "committed"
                                for family_journal in family_journals.values()
                            ):
                                raise MutationJournalError(
                                    "committed exact lifecycle family event is "
                                    "absent"
                                )
                            rollback_intent = {
                                "settlement_ref": settlement_ref,
                                "settlement_family": sorted(family_set),
                            }
                            for family_journal in family_journals.values():
                                existing_intent = family_journal._manifest.get(
                                    "lifecycle_family_rollback"
                                )
                                if existing_intent is None:
                                    family_journal._manifest[
                                        "lifecycle_family_rollback"
                                    ] = rollback_intent
                                    family_journal._write()
                                elif existing_intent != rollback_intent:
                                    raise MutationJournalError(
                                        "exact lifecycle family rollback intent "
                                        "is inconsistent"
                                    )
                            family_failed = False
                            for family_journal in sorted(
                                family_journals.values(),
                                key=lambda item: (
                                    depths.get(item.transaction_id, -1),
                                    item.created_ns,
                                    item.transaction_id,
                                ),
                                reverse=True,
                            ):
                                settlement = _recovery_settlement(
                                    corpus,
                                    family_journal,
                                    disposition="recovered",
                                )
                                if family_journal.state == "rolled_back":
                                    continue
                                if family_journal.restore(
                                    _defer_terminal_cleanup=True
                                ):
                                    recovered.append(family_journal.slice_id)
                                    settlements.append(settlement)
                                else:
                                    family_failed = True
                            if family_failed:
                                raise MutationJournalError(
                                    "exact lifecycle settlement family rollback "
                                    "remains pending"
                                )
                            if any(
                                family_journal.state != "rolled_back"
                                for family_journal in family_journals.values()
                            ):
                                raise MutationJournalError(
                                    "exact lifecycle settlement family rollback "
                                    "did not reach terminal markers"
                                )
                            for family_journal in sorted(
                                family_journals.values(),
                                key=lambda item: (
                                    depths.get(item.transaction_id, -1),
                                    item.created_ns,
                                    item.transaction_id,
                                ),
                                reverse=True,
                            ):
                                _cleanup_terminal_mutation_journal(
                                    family_journal
                                )
                            family_pending = False
                        else:
                            for family_journal in family_journals.values():
                                family_expected = (
                                    family_journal._manifest.get(
                                        "expected_lifecycle"
                                    ) or {}
                                )
                                if (
                                    family_journal.state
                                    not in {"prepared_keep", "committed"}
                                    or family_expected.get("settlement_ref")
                                    != settlement_ref
                                    or set(family_expected.get(
                                        "settlement_family",
                                        (),
                                    )) != family_set
                                ):
                                    raise MutationJournalError(
                                        "attached exact lifecycle settlement "
                                        "family is only partially prepared"
                                    )
                                _assert_journal_lifecycle_settlement(
                                    corpus,
                                    family_journal,
                                    lifecycle_ref,
                                )
                            for family_journal in family_journals.values():
                                if family_journal.state == "prepared_keep":
                                    preserved.append(family_journal.slice_id)
                                    settlements.append(_recovery_settlement(
                                        corpus,
                                        family_journal,
                                        disposition="preserved",
                                    ))
                            _commit_prevalidated_lifecycle_family(
                                family_journals.values()
                            )
                            family_pending = any(
                                family_journal.journal_dir.is_dir()
                                for family_journal in family_journals.values()
                            )
                except Exception:
                    failed_recovery.update(family_set)
                    raise
                if family_pending:
                    failed_recovery.update(family_set)
                    failures.append(
                        f"{journal.slice_id}: exact lifecycle settlement family "
                        "finalization remains pending"
                    )
                    continue
                processed_family.update(family_set)
                for transaction_id in family_set:
                    acknowledge_terminal(transaction_id)
                continue
            if journal.state in {"committed", "rolled_back"}:
                _cleanup_terminal_mutation_journal(journal)
                acknowledge_terminal(journal.transaction_id)
                continue
            if (
                journal.state == "prepared_keep"
                and (
                    _expected_is_attached(
                        corpus,
                        journal._manifest.get("expected_implementation"),
                        journal._manifest.get("lineage"),
                    )
                    or _expected_lifecycle_is_attached(
                        corpus,
                        journal._manifest.get("expected_lifecycle"),
                        journal._manifest.get("lineage"),
                    )
                )
            ):
                preserved.append(journal.slice_id)
                settlement = _recovery_settlement(
                    corpus,
                    journal,
                    disposition="preserved",
                )
                settlements.append(settlement)
                if (
                    settlement.implementation_ref is None
                    and settlement.lifecycle_ref is not None
                ):
                    expected_lifecycle = (
                        journal._manifest.get("expected_lifecycle") or {}
                    )
                    expected_settlement_ref = expected_lifecycle.get(
                        "settlement_ref"
                    )
                    if expected_settlement_ref is None:
                        # A generic LifecycleEvent does not bind the exact
                        # transaction scope and postimage. Never disarm it by
                        # matching only kind/reason/run identity.
                        failed_recovery.add(journal.transaction_id)
                        failures.append(
                            f"{journal.slice_id}: lifecycle-only prepared_keep "
                            "lacks durable exact mutation postimage authority; "
                            "journal retained"
                        )
                        continue
                    with _lifecycle_family_workspace_locks((journal,)):
                        _assert_journal_lifecycle_settlement(
                            corpus,
                            journal,
                            settlement.lifecycle_ref,
                        )
                        _assert_workspace_mutation_authority(root)
                        journal.commit(
                            attached=True,
                            corpus=corpus,
                            _settlement_family_prevalidated=True,
                            _authority_held=True,
                            _settlement_family_locks_held=True,
                        )
                else:
                    _assert_workspace_mutation_authority(root)
                    journal.commit(
                        attached=True,
                        corpus=corpus,
                        _settlement_family_prevalidated=True,
                        _authority_held=True,
                    )
                if not journal.journal_dir.exists():
                    acknowledge_terminal(journal.transaction_id)
                continue
            _assert_workspace_mutation_authority(root)
            if journal.restore():
                recovered.append(journal.slice_id)
                settlements.append(
                    _recovery_settlement(
                        corpus,
                        journal,
                        disposition="recovered",
                    )
                )
                acknowledge_terminal(journal.transaction_id)
            else:
                failed_recovery.add(journal.transaction_id)
                failures.append(
                    f"{journal.slice_id}: rollback failed; journal retained"
                )
        except Exception as exc:  # noqa: BLE001
            failed_recovery.add(journal.transaction_id)
            failures.append(f"{journal.slice_id}: recovery raised {exc}")

    try:
        _assert_registry_clear(
            root,
            allowed_transaction_ids=failed_recovery,
        )
    except MutationJournalError as exc:
        failures.append(str(exc))

    if previous_writer_epoch_recovery_members is None:
        try:
            del _LOCK_STATE.writer_epoch_recovery_members
        except AttributeError:
            pass
    else:
        _LOCK_STATE.writer_epoch_recovery_members = (
            previous_writer_epoch_recovery_members
        )

    return RecoveryReport(
        recovered=tuple(recovered),
        preserved=tuple(preserved),
        failures=tuple(failures),
        settlements=tuple(settlements),
    )


def recover_mutation_journals(
    corpus: "Corpus",
    cwd: str | Path,
) -> RecoveryReport:
    """Recover dead journals under one serialized source/Spec snapshot.

    The absent-versus-attached settlement decision authorizes destructive
    source restoration.  Own both locks here so direct callers and every
    composed workflow use the canonical workspace-then-Spec ordering.  Code
    that already holds both locks, such as the lifecycle-aware reaper, calls
    the private locked implementation instead of re-entering Assay's
    deliberately non-reentrant authority guard.
    """

    workspace = _lexical_workspace_path(cwd)
    try:
        with ExitStack() as workspace_release:
            workspace_context = recovery_workspace_mutation_lock(
                corpus,
                workspace,
            )
            workspace_release.callback(workspace_context.retry_cleanup)
            authority = workspace_context.__enter__()
            with _readable_spec_authority(corpus) as spec:
                if spec is not None:
                    # Import lazily: _build_verify depends on journal utilities.
                    from . import _build_verify  # noqa: PLC0415

                    valid_lineage, lineage_reason = (
                        _build_verify._validate_spec_lineage(corpus, spec)
                    )
                    if not valid_lineage:
                        return RecoveryReport(
                            (),
                            (),
                            (
                                "latest Spec lineage is invalid before recovery: "
                                f"{lineage_reason}",
                            ),
                        )
                return _recover_mutation_journals_locked(
                    corpus,
                    authority.root,
                )
    except _SpecAuthorityEntryError as exc:
        return RecoveryReport(
            (),
            (),
            (
                "latest Spec authority is unreadable before recovery; "
                f"journals retained: {type(exc).__name__}: {exc}",
            ),
        )
    except MutationJournalError as exc:
        return RecoveryReport(
            (),
            (),
            (
                "workspace recovery admission failed; journals retained: "
                f"{type(exc).__name__}: {exc}",
            ),
        )


__all__ = [
    "MutationTransaction",
    "MutationJournalCleanupError",
    "MutationJournalError",
    "JournalSettlementOutcome",
    "RecoverySettlement",
    "RecoveryReport",
    "WorkspaceMutationJournal",
    "normalize_scope_path",
    "normalize_workspace_path",
    "recover_mutation_journals",
    "recovery_workspace_mutation_lock",
    "retained_nested_workspace_mutation_lock",
    "resolve_live_mutation_journal",
    "validated_live_parent_writer_epoch_family",
    "workspace_mutation_lock",
]

# Greenfield public name: all model-backed workspace mutation paths use the
# same durable transaction implementation.  The descriptive historical class
# name remains an internal spelling until callers migrate mechanically.
MutationTransaction = WorkspaceMutationJournal
